-- Other executors often lack cloneref/clonefunction/getgc. Kryptic captures those
-- names as locals at chunk start, so rebind them before any later call.
do
    local function _akira_fn(value, fallback)
        if type(value) == 'function' then
            return value
        end
        return fallback
    end
    local function _akira_ident(value)
        return value
    end
    local function _akira_clonefn(fn)
        return fn
    end
    local function _akira_empty()
        return {}
    end
    local function _akira_noop()
    end
    local function _akira_coregui()
        local ok, gui = pcall(function()
            return game:GetService('CoreGui')
        end)
        return ok and gui or nil
    end

    cloneref = _akira_fn(cloneref, _akira_ident)
    clonefunction = _akira_fn(clonefunction, _akira_clonefn)
    getgc = _akira_fn(getgc, _akira_empty)
    filtergc = _akira_fn(filtergc, _akira_empty)
    firesignal = _akira_fn(firesignal, _akira_noop)
    firetouchinterest = _akira_fn(firetouchinterest, _akira_noop)
    fireclickdetector = _akira_fn(fireclickdetector, _akira_noop)
    fireproximityprompt = _akira_fn(fireproximityprompt, _akira_noop)
    replicatesignal = _akira_fn(replicatesignal, _akira_noop)
    setclipboard = _akira_fn(setclipboard, _akira_noop)
    checkcaller = _akira_fn(checkcaller, function()
        return false
    end)
    newcclosure = _akira_fn(newcclosure, _akira_clonefn)
    hookfunction = _akira_fn(hookfunction, function(orig)
        return orig
    end)
    hookmetamethod = _akira_fn(hookmetamethod, function()
        return nil
    end)
    getnamecallmethod = _akira_fn(getnamecallmethod, function()
        return ''
    end)
    getrawmetatable = _akira_fn(getrawmetatable, function(object)
        return getmetatable(object)
    end)
    setrawmetatable = _akira_fn(setrawmetatable, function(object, meta)
        return setmetatable(object, meta)
    end)
    setreadonly = _akira_fn(setreadonly, _akira_noop)
    isreadonly = _akira_fn(isreadonly, function()
        return false
    end)
    getthreadidentity = _akira_fn(getthreadidentity, function()
        return 0
    end)
    setthreadidentity = _akira_fn(setthreadidentity, _akira_noop)
    getsenv = _akira_fn(getsenv, _akira_empty)
    getnilinstances = _akira_fn(getnilinstances, _akira_empty)
    getinstances = _akira_fn(getinstances, _akira_empty)
    isfunctionhooked = _akira_fn(isfunctionhooked, function()
        return false
    end)
    restorefunction = _akira_fn(restorefunction, _akira_noop)
    sethiddenproperty = _akira_fn(sethiddenproperty, function()
        return false
    end)
    gethiddenproperty = _akira_fn(gethiddenproperty, function()
        return nil
    end)
    getrenv = _akira_fn(getrenv, function()
        return _G
    end)
    getcallingscript = _akira_fn(getcallingscript, function()
        return nil
    end)
    getscriptfromthread = _akira_fn(getscriptfromthread, _akira_noop)
    getcallbackvalue = _akira_fn(getcallbackvalue, _akira_noop)
    setfflag = _akira_fn(setfflag, function()
        return false
    end)
    sfflag = _akira_fn(sfflag, function()
        return false
    end)
    gethui = _akira_fn(gethui, _akira_coregui)
    identifyexecutor = _akira_fn(identifyexecutor, function()
        return 'Unknown'
    end)

    local function _akira_fill_env(env)
        if type(env) ~= 'table' then
            return
        end
        local names = {
            cloneref = cloneref,
            clonefunction = clonefunction,
            getgc = getgc,
            filtergc = filtergc,
            firesignal = firesignal,
            gethui = gethui,
            sethiddenproperty = sethiddenproperty,
            hookfunction = hookfunction,
            newcclosure = newcclosure,
        }
        for name, fn in pairs(names) do
            local ok, current = pcall(function()
                return env[name]
            end)
            if (not ok or type(current) ~= 'function') and type(fn) == 'function' then
                pcall(function()
                    env[name] = fn
                end)
            end
        end
    end
    _akira_fill_env(_G)
    pcall(function()
        if type(getgenv) == 'function' then
            _akira_fill_env(getgenv())
        end
    end)
    pcall(function()
        if type(getfenv) == 'function' then
            _akira_fill_env(getfenv(0))
            _akira_fill_env(getfenv(1))
            _akira_fill_env(getfenv())
        end
    end)
end

local function ResolveGlobalEnv()
    local candidates = {}
    if type(getgenv) == 'function' then
        local ok, env = pcall(getgenv)
        if ok and type(env) == 'table' then
            table.insert(candidates, env)
        end
    end
    if type(getfenv) == 'function' then
        local ok, env = pcall(getfenv, 0)
        if ok and type(env) == 'table' then
            table.insert(candidates, env)
        end
    end
    for _, env in ipairs(candidates) do
        local wrote = pcall(function() env.__AkiraEnvProbe = true end)
        local seen = __AkiraEnvProbe == true
        pcall(function() env.__AkiraEnvProbe = nil end)
        if wrote and seen then
            return env
        end
    end
    return _G
end

local __akira_genv = ResolveGlobalEnv()
local shutting_down = false
local __akira_boot_gen = 0
pcall(function()
    local KEY_FILES = {
        'key',
        'key.txt',
        'akira_key.txt',
        'akira/key.txt',
        'akira/key',
        'akira/script_key.txt',
        'script_key.txt',
    }

    local function normalizeKey(val)
        if type(val) ~= 'string' then return nil end
        local trimmed = (string.match(val, '^%s*(.-)%s*$') or val)
        if trimmed == '' or trimmed == 'script_key' or trimmed == 'key' then return nil end
        return trimmed
    end

    local foundKey = nil
    if type(getgenv) == 'function' then
        local okEnv, env = pcall(getgenv)
        if okEnv and type(env) == 'table' then
            foundKey = normalizeKey(env.script_key)
                or normalizeKey(env.key)
                or normalizeKey(env.Key)
                or normalizeKey(env.LRM_LinkedKey)
                or normalizeKey(env.LRM_UserKey)
                or normalizeKey(env.LRM_ScriptKey)
        end
    end
    if not foundKey and type(_G) == 'table' then
        foundKey = normalizeKey(rawget(_G, 'script_key'))
            or normalizeKey(rawget(_G, 'key'))
            or normalizeKey(rawget(_G, 'Key'))
            or normalizeKey(rawget(_G, 'LRM_LinkedKey'))
            or normalizeKey(rawget(_G, 'LRM_UserKey'))
    end
    if not foundKey and type(__akira_genv) == 'table' then
        foundKey = normalizeKey(__akira_genv.script_key)
            or normalizeKey(__akira_genv.key)
            or normalizeKey(__akira_genv.Key)
    end
    if not foundKey and type(getfenv) == 'function' then
        local okFenv, fe = pcall(getfenv, 0)
        if okFenv and type(fe) == 'table' then
            foundKey = normalizeKey(fe.script_key) or normalizeKey(fe.key) or normalizeKey(fe.Key)
        end
    end
    if not foundKey and type(isfile) == 'function' and type(readfile) == 'function' then
        for _, path in ipairs(KEY_FILES) do
            local okExists, exists = pcall(isfile, path)
            if okExists and exists == true then
                local okRead, content = pcall(readfile, path)
                if okRead and type(content) == 'string' then
                    local cand = normalizeKey(content)
                    if cand then
                        foundKey = cand
                        break
                    end
                end
            end
        end
    end

    if foundKey then
        if type(getgenv) == 'function' then
            local okEnv, env = pcall(getgenv)
            if okEnv and type(env) == 'table' then
                env.script_key = foundKey
                env.key = foundKey
            end
        end
        if type(_G) == 'table' then
            pcall(rawset, _G, 'script_key', foundKey)
            pcall(rawset, _G, 'key', foundKey)
        end
        if type(__akira_genv) == 'table' then
            __akira_genv.script_key = foundKey
            __akira_genv.key = foundKey
        end
        if type(makefolder) == 'function' then
            pcall(makefolder, 'akira')
        end
        if type(writefile) == 'function' then
            for _, path in ipairs({ 'akira/script_key.txt', 'akira/key.txt' }) do
                pcall(writefile, path, foundKey)
            end
        end
    end
end)

local nativeTableClone = nil
pcall(function()
    nativeTableClone = table.clone
end)
if type(nativeTableClone) ~= 'function' then
    nativeTableClone = nil
end
local function AkiraClone(object)
    if type(object) ~= 'table' then
        return object
    end
    if nativeTableClone then
        local ok, cloned = pcall(nativeTableClone, object)
        if ok then
            return cloned
        end
    end
    local copy = {}
    for key, value in pairs(object) do
        copy[key] = value
    end
    return copy
end
pcall(function()
    if not nativeTableClone then
        rawset(table, 'clone', AkiraClone)
    end
end)

local function AkiraLibFn(lib, partA, partB)
    if type(lib) ~= 'table' then
        return nil
    end
    local name = tostring(partA or '')
    if type(partB) == 'string' then
        name = name .. partB
    end
    local value = nil
    pcall(function()
        value = rawget(lib, name)
    end)
    if type(value) ~= 'function' then
        local ok, indexed = pcall(function()
            return lib[name]
        end)
        if ok then
            value = indexed
        end
    end
    if type(value) == 'function' then
        return value
    end
    return nil
end

local function AkiraLibSet(lib, partA, partB, value)
    if type(lib) ~= 'table' then
        return false
    end
    local name = tostring(partA or '')
    if type(partB) == 'string' then
        name = name .. partB
    end
    local ok = pcall(function()
        lib[name] = value
    end)
    if ok then
        return true
    end
    return pcall(rawset, lib, name, value)
end

local function __akira_boot_alive()
    return shutting_down ~= true
        and __akira_genv.__AkiraShuttingDown ~= true
        and __akira_genv.__AkiraBootGen == __akira_boot_gen
end

local function __akira_unbind_akira_render_steps()
    local rs = game:GetService('RunService')
    local names = {
        'AkiraViewmodelVisuals',
        'AkiraCameraModifiers',
        'AkiraStretchedResolution',
    }
    local extra = __akira_genv.__AkiraRenderBinds
    if type(extra) == 'table' then
        for index = 1, #extra do
            names[#names + 1] = extra[index]
            extra[index] = nil
        end
    end
    for index = 1, #names do
        pcall(function()
            rs:UnbindFromRenderStep(names[index])
        end)
    end
end

local function __akira_disconnect_rivals_registry()
    local reg = __akira_genv.__AkiraRivalsConnections
    __akira_genv.__AkiraRivalsConnections = nil
    if type(reg) == 'table' and type(reg.disconnect_all) == 'function' then
        pcall(function()
            reg:disconnect_all()
        end)
    end
end

local function __akira_wipe_akira_guis()
    local names = { Akira = true, AkiraOther = true, AkiraMobileToggle = true, AkiraBoot = true, UELib = true, UE = true, Linoria = true, Miku = true, AkiraTargetHud = true }
    local function wipe(parent)
        if not parent then
            return
        end
        for _, child in ipairs(parent:GetChildren()) do
            if child:IsA('ScreenGui') and names[child.Name] then
                pcall(function()
                    child:Destroy()
                end)
            end
        end
    end
    wipe(game:GetService('CoreGui'))
    if gethui then
        wipe(gethui())
    end
    local lp = game:GetService('Players').LocalPlayer
    wipe(lp and lp:FindFirstChildOfClass('PlayerGui'))
    local function wipeHighlights(parent)
        if not parent then
            return
        end
        for _, child in ipairs(parent:GetChildren()) do
            if child.Name == 'AkiraEspHighlights' or child.Name == 'AkiraEspHighlightsLive' then
                pcall(function()
                    child:Destroy()
                end)
            end
        end
    end
    wipeHighlights(game:GetService('CoreGui'))
    wipeHighlights(workspace)
    if gethui then
        wipeHighlights(gethui())
    end
end

local function __akira_prepare_for_teleport()
    if shutting_down and __akira_genv.__AkiraShuttingDown == true then
        return
    end
    shutting_down = true
    __akira_genv.__AkiraShuttingDown = true
    __akira_genv.__AkiraBootGen = (tonumber(__akira_genv.__AkiraBootGen) or 0) + 1
    pcall(function()
        local overlay = __akira_genv.__AkiraBootOverlay
        __akira_genv.__AkiraBootOverlay = nil
        if typeof(overlay) == 'Instance' then
            overlay:Destroy()
        end
    end)
    pcall(__akira_unbind_akira_render_steps)
    pcall(__akira_disconnect_rivals_registry)
    pcall(function()
        local slot = __akira_genv.__AkiraAntiAfk
        __akira_genv.__AkiraAntiAfk = nil
        if type(slot) == 'table' and slot.Connection then
            slot.Connection:Disconnect()
        end
    end)
    pcall(function()
        local lib = __akira_genv.Library
        if type(lib) ~= 'table' then
            return
        end
        lib.Unloaded = true
        local signals = lib.Signals
        if type(signals) == 'table' then
            for index = #signals, 1, -1 do
                local connection = table.remove(signals, index)
                pcall(function()
                    if connection and connection.Disconnect then
                        connection:Disconnect()
                    end
                end)
            end
        end
    end)
    -- Never Library:Unload / ResetState here. getgenv survives teleports and those
    -- closures still point at the DataModel being destroyed, which crashes the client.
    __akira_genv.Library = nil
    if _G then
        _G.Library = nil
    end
end

__akira_genv.__AkiraPrepareTeleport = __akira_prepare_for_teleport

local function __akira_cleanup_previous_instance()
    __akira_genv.__AkiraBootGen = (tonumber(__akira_genv.__AkiraBootGen) or 0) + 1
    shutting_down = true
    __akira_genv.__AkiraShuttingDown = true

    pcall(function()
        local overlay = __akira_genv.__AkiraBootOverlay
        __akira_genv.__AkiraBootOverlay = nil
        if typeof(overlay) == 'Instance' then
            overlay:Destroy()
        end
    end)

    pcall(__akira_unbind_akira_render_steps)
    pcall(__akira_disconnect_rivals_registry)

    local previousGame = __akira_genv.__akira_executed_datamodel
    local sameGame = previousGame == game
    pcall(function()
        if not sameGame then
            __akira_genv.Library = nil
            if _G then
                _G.Library = nil
            end
            return
        end
        local lib = __akira_genv.Library
        if type(lib) == 'table' and type(lib.Unload) == 'function' then
            pcall(lib.Unload, lib)
        end
        if _G and _G.Library and type(_G.Library.Unload) == 'function' and _G.Library ~= lib then
            pcall(_G.Library.Unload, _G.Library)
        end
        __akira_genv.Library = nil
    end)

    pcall(function()
        if type(getconnections) ~= 'function' then
            return
        end
        if __akira_genv.Library == nil and __akira_genv.__akira_executed_datamodel == nil then
            return
        end
        local rs = game:GetService('RunService')
        local signals = { rs.Heartbeat, rs.RenderStepped, rs.Stepped }
        if rs.PreSimulation then
            signals[#signals + 1] = rs.PreSimulation
        end
        if rs.PreRender then
            signals[#signals + 1] = rs.PreRender
        end
        local deadline = os.clock() + 0.02
        for _, signal in ipairs(signals) do
            if os.clock() > deadline then
                break
            end
            local ok, conns = pcall(getconnections, signal)
            if ok and type(conns) == 'table' then
                for index = 1, #conns do
                    if os.clock() > deadline then
                        break
                    end
                    pcall(function()
                        local conn = conns[index]
                        if conn.LuaConnection ~= true then
                            return
                        end
                        local fn = conn.Function
                        if type(fn) ~= 'function' then
                            return
                        end
                        local src = string.lower(tostring(debug.info(fn, 's') or ''))
                        local name = string.lower(tostring(debug.info(fn, 'n') or ''))
                        if src:find('thirdperson', 1, true) or name:find('thirdperson', 1, true)
                            or src:find('akira', 1, true) or src:find('rivals script', 1, true) then
                            conn:Disconnect()
                        end
                    end)
                end
            end
        end
    end)

    pcall(__akira_wipe_akira_guis)

    shutting_down = false
    __akira_genv.__AkiraShuttingDown = false
    __akira_boot_gen = __akira_genv.__AkiraBootGen
end

__akira_cleanup_previous_instance()

-- =========================================================================
-- DEV BUILD (NO KEY SYSTEM / DIRECT EXECUTION)
-- =========================================================================
local __akira_authenticated = true


-- The executor environment (getgenv) survives teleports, so a queued re-run on a
-- new server would see Executed == true from the previous server and bail. Gate
-- re-entry on the server job id instead: same job = already running, new job = allow.
if __akira_genv.Executed == true and __akira_genv.__akira_executed_job == game.JobId then
    pcall(__akira_cleanup_previous_instance)
end
__akira_genv.Executed = true
__akira_genv.__akira_executed_job = game.JobId
__akira_genv.__akira_executed_datamodel = game
pcall(function()
    if type(_G.__AkiraExecuted) ~= 'table' then
        _G.__AkiraExecuted = {}
    end
    if type(game.JobId) == 'string' and game.JobId ~= '' then
        _G.__AkiraExecuted[game.JobId] = true
    end
end)

do
    local _noop = function() end
    local _genv = __akira_genv
    local _stubs = {
        getconnections    = function() return {} end,
        hookmetamethod    = function(obj, method, hook) return nil end,
        hookfunction      = function(orig, hook) return orig end,
        newcclosure       = function(f) return f end,
        getnamecallmethod = function() return '' end,
        firetouchinterest = _noop,
        firesignal        = _noop,
        setclipboard      = _noop,
        cloneref          = function(o) return o end,
        gethui            = function()
            local ok, gui = pcall(function()
                return game:GetService('CoreGui')
            end)
            return ok and gui or nil
        end,
        checkcaller       = function() return false end,
        clonefunction     = function(f) return f end,
        getrawmetatable   = function(o) return getmetatable(o) end,
        setrawmetatable   = function(o, mt) return setmetatable(o, mt) end,
        setreadonly       = _noop,
        isreadonly        = function() return false end,
        getgc             = function() return {} end,
        filtergc          = function() return {} end,
        replicatesignal   = _noop,
        fireclickdetector = _noop,
        fireproximityprompt = _noop,
        getthreadidentity = function() return 0 end,
        setthreadidentity = _noop,
        getsenv           = function() return {} end,
        getscriptfromthread = _noop,
        getcallbackvalue  = _noop,
        getnilinstances   = function() return {} end,
        getinstances      = function() return {} end,
        isfunctionhooked  = function() return false end,
        restorefunction   = _noop,
    }
    local _stubbed = {}
    for name, stub in pairs(_stubs) do
        if rawget(_genv, name) == nil then
            _genv[name] = stub
            _stubbed[name] = true
        end
    end

    if game.GameId ~= 6035872082 and _genv.hookfunction ~= _stubs.hookfunction then
        local ok = pcall(_genv.hookfunction, function() end, function() end)
        if not ok then
            _genv.hookfunction = _stubs.hookfunction
            _stubbed.hookfunction = true
        end
    end

    local _exName = type(identifyexecutor) == 'function' and identifyexecutor() or ''
    local _exNameLower = string.lower(_exName)
    if _exNameLower:find('solara') or _exNameLower:find('xeno') then
        _genv.firetouchinterest = _noop
        _stubbed.firetouchinterest = true
    end

    local _resolvedQueue = (type(queue_on_teleport) == 'function' and queue_on_teleport)
        or (type(queueonteleport) == 'function' and queueonteleport)
        or (syn and type(syn.queue_on_teleport) == 'function' and syn.queue_on_teleport)
        or (fluxus and type(fluxus.queue_on_teleport) == 'function' and fluxus.queue_on_teleport)
        or (type(getgenv) == 'function' and (
            (type(getgenv().queue_on_teleport) == 'function' and getgenv().queue_on_teleport)
            or (type(getgenv().queueonteleport) == 'function' and getgenv().queueonteleport)
            or (getgenv().syn and type(getgenv().syn.queue_on_teleport) == 'function' and getgenv().syn.queue_on_teleport)
            or (getgenv().fluxus and type(getgenv().fluxus.queue_on_teleport) == 'function' and getgenv().fluxus.queue_on_teleport)
        ))
    if _resolvedQueue then
        _genv.queue_on_teleport = _resolvedQueue
    end

    for _, name in ipairs({ 'queue_on_teleport', 'sethiddenproperty', 'gethiddenproperty', 'getrenv', 'getcallingscript' }) do
        if type(_genv[name]) ~= 'function' then
            _stubbed[name] = true
        end
    end

    if type(getgenv) ~= 'function' then
        _stubbed.getgenv = true
    else
        local ok, env = pcall(getgenv)
        if not (ok and env == _genv) then
            _stubbed.getgenv = true
        end
    end

    local _debugExt = {}
    for _, name in ipairs({ 'getupvalue', 'getupvalues', 'setupvalue', 'getconstant', 'getconstants', 'setconstant', 'getprotos', 'getproto', 'getstack', 'info' }) do
        local ok, value = pcall(function() return debug[name] end)
        _debugExt['debug.' .. name] = (ok and type(value) == 'function') or false
    end

    local _NotifiedCapsFeatures = {}
    local function _capsGate(feature, ...)
        local missing = nil
        for _, name in ipairs({ ... }) do
            if not _genv.AkiraCaps.has(name) then
                missing = missing and (missing .. ', ' .. name) or name
            end
        end
        if not missing then
            return true
        end
        if not _NotifiedCapsFeatures[feature] then
            _NotifiedCapsFeatures[feature] = true
            pcall(function()
                local lib = _genv.Library or (_G and _G.Library)
                if lib and type(lib.Notify) == 'function' then
                    lib:Notify({ Title = 'Executor Support', Description = feature .. " won't work on this executor -- it doesn't have " .. missing .. '.', Time = 8 })
                end
            end)
        end
        return false
    end

    _genv.AkiraCaps = {
        stubbed = _stubbed,
        has = function(name)
            if _stubbed[name] then
                return false
            end
            local probed = _debugExt[name]
            if probed ~= nil then
                return probed
            end
            local target = _genv
            for part in string.gmatch(name, '[^%.]+') do
                if type(target) ~= 'table' then
                    return false
                end
                local ok, value = pcall(function() return target[part] end)
                if not ok then
                    return false
                end
                target = value
            end
            return type(target) == 'function'
        end,
        gate = _capsGate,
    }
end

