        end
        local prev = __akira_genv.__AkiraTeleportConn
        if prev then
            pcall(function()
                prev:Disconnect()
            end)
        end
        __akira_genv.__AkiraTeleportConn = lp.OnTeleport:Connect(function(state)
            if state == Enum.TeleportState.Failed then
                return
            end
            pcall(__akira_prepare_for_teleport)
        end)
        local prevRem = __akira_genv.__AkiraPlayerRemovingConn
        if prevRem then
            pcall(function()
                prevRem:Disconnect()
            end)
        end
        __akira_genv.__AkiraPlayerRemovingConn = players.PlayerRemoving:Connect(function(player)
            if player == lp then
                pcall(__akira_prepare_for_teleport)
            end
        end)
    end
    if players.LocalPlayer then
        bindTeleportWatch(players.LocalPlayer)
    else
        local conn
        conn = players:GetPropertyChangedSignal('LocalPlayer'):Connect(function()
            if players.LocalPlayer then
                if conn then
                    conn:Disconnect()
                end
                bindTeleportWatch(players.LocalPlayer)
            end
        end)
    end
end)

local __akira_boot_last_yield = os.clock()
local function __akira_boot_yield(force)
    local now = os.clock()
    local elapsed = now - __akira_boot_last_yield
    if force == true then
        if elapsed < 0.016 then
            return
        end
        __akira_boot_last_yield = now
        task.wait()
        return
    end
    if elapsed >= 0.033 then
        __akira_boot_last_yield = now
        task.wait()
    end
end

