local function __akira_boot_log(text)
    local s = tostring(text)
    local now = os.clock()
    __akira_boot_log_lines[#__akira_boot_log_lines + 1] = string.format('[+%.2fs] %s', now - __akira_boot_clock_start, s)
    if #__akira_boot_log_lines > 400 then
        table.remove(__akira_boot_log_lines, 1)
    end
    local isUrgent = s:find('FATAL') or s:find('error') or s:find('CRASH') or s:find('REENTRY')
    __akira_boot_log_last_flush = now
    __akira_boot_flush_log()
    __akira_boot_live_flush(string.format('[+%.2fs] %s', now - __akira_boot_clock_start, s))
end

