-- Hook watchdog: game-called hooks log their entry (rate-limited, boot window
-- only) and track reentry depth. If the game hard-freezes inside one of our
-- hooks, the last 'HOOK ENTER' line names the culprit, and 'HOOK REENTRY'
-- lines expose infinite recursion cycles (tail-call loops collapse tracebacks).
local __akira_hook_depth = {}
local __akira_hook_log_at = {}
local function __akira_hook_enter(name)
    LPH_ATTRIBUTES(VM(NONE))
    -- Boot-only watchdog. Stripped entirely from Luraph production builds so
    -- game-called hooks (raycast/input) do not pay extra VM/debug cost.
    if LPH_OBFUSCATED then
        return
    end
    local depth = (__akira_hook_depth[name] or 0) + 1
    __akira_hook_depth[name] = depth
    if depth == 3 or depth == 6 or depth == 12 or depth == 24 then
        __akira_boot_log('HOOK REENTRY: ' .. tostring(name) .. ' depth=' .. tostring(depth))
    end
    if os.clock() - __akira_boot_clock_start < 60 then
        local now = os.clock()
        if now - (__akira_hook_log_at[name] or 0) > 2 then
            __akira_hook_log_at[name] = now
            __akira_boot_log('HOOK ENTER: ' .. tostring(name))
        end
    end
end
local function __akira_hook_exit(name)
    LPH_ATTRIBUTES(VM(NONE))
    if LPH_OBFUSCATED then
        return
    end
    __akira_hook_depth[name] = math.max((__akira_hook_depth[name] or 1) - 1, 0)
end

