local function __AkiraElevateIdentity()
    if type(setthreadidentity) == 'function' then
        pcall(setthreadidentity, 8)
    end
end
__AkiraElevateIdentity()

local function RunWithGameIdentity(fn, ...)
    local prevIdentity = nil
    if type(getthreadidentity) == 'function' then
        pcall(function() prevIdentity = getthreadidentity() end)
    elseif type(getidentity) == 'function' then
        pcall(function() prevIdentity = getidentity() end)
    end

    if type(setthreadidentity) == 'function' then
        pcall(setthreadidentity, 0)
    elseif type(setidentity) == 'function' then
        pcall(setidentity, 0)
    end

    local results = table.pack(pcall(fn, ...))

    if prevIdentity ~= nil then
        if type(setthreadidentity) == 'function' then
            pcall(setthreadidentity, prevIdentity)
        elseif type(setidentity) == 'function' then
            pcall(setidentity, prevIdentity)
        end
    end

    return results
end

local _akira_native_require = require
local function SafeRequireGameModule(moduleScript, ...)
    if not moduleScript then return nil end
    local results = RunWithGameIdentity(_akira_native_require, moduleScript, ...)
    if results[1] then
        return results[2]
    end
    local okN, valN = pcall(_akira_native_require, moduleScript, ...)
    if okN then
        return valN
    end
    if type(getrenv) == 'function' then
        local renv = getrenv()
        if renv and type(renv.require) == 'function' and renv.require ~= _akira_native_require then
            local resultsR = RunWithGameIdentity(renv.require, moduleScript, ...)
            if resultsR[1] then
                return resultsR[2]
            end
            local okR, valR = pcall(renv.require, moduleScript, ...)
            if okR then
                return valR
            end
        end
    end
    return nil, results[2]
end

local function require(mod, ...)
    local res, err = SafeRequireGameModule(mod, ...)
    if res ~= nil then
        return res
    end
    error(err or ('Failed to require module: ' .. tostring(mod)), 2)
end

local __akira_shared = {}

local __shared_module_cache = {}

local function RequireSharedModule(name)
    if type(__akira_shared) ~= 'table' then
        error('Missing shared module table')
    end

    local cached = __shared_module_cache[name]
    if cached ~= nil then
        return cached
    end

    local loader = __akira_shared[name]
    if type(loader) ~= 'function' then
        error('Missing shared module: ' .. tostring(name))
    end

    local result = loader()
    __shared_module_cache[name] = result
    return result
end

local Library = nil
local ErrorReporter = nil
local DrawingLib = nil

local function parseColorAndAlpha(data, fallbackAlpha)
    local color, alpha = nil, tonumber(fallbackAlpha)
    if typeof(data) == 'Color3' then
        color = data
    elseif type(data) == 'string' then
        local hex = data:gsub('^#', '')
        local ok, c = pcall(Color3.fromHex, hex)
        if ok and typeof(c) == 'Color3' then
            color = c
        end
    elseif type(data) == 'table' then
        if data._t == 'Color' or data._t == 'Color3' or data.v ~= nil then
            if typeof(data.v) == 'Color3' then
                color = data.v
            elseif type(data.v) == 'string' then
                local hex = data.v:gsub('^#', '')
                local ok, c = pcall(Color3.fromHex, hex)
                if ok and typeof(c) == 'Color3' then color = c end
            end
            if data.a ~= nil then alpha = tonumber(data.a) end
        elseif data.r and data.g and data.b then
            local r, g, b = tonumber(data.r) or 1, tonumber(data.g) or 1, tonumber(data.b) or 1
            if r > 1 or g > 1 or b > 1 then
                color = Color3.fromRGB(r, g, b)
            else
                color = Color3.new(r, g, b)
            end
            if data.a ~= nil then alpha = tonumber(data.a) end
        elseif data.R and data.G and data.B then
            local r, g, b = tonumber(data.R) or 1, tonumber(data.G) or 1, tonumber(data.B) or 1
            if r > 1 or g > 1 or b > 1 then
                color = Color3.fromRGB(r, g, b)
            else
                color = Color3.new(r, g, b)
            end
            alpha = tonumber(data.A or data.Transparency or alpha)
        elseif data.value ~= nil then
            return parseColorAndAlpha(data.value, data.transparency or data.a or alpha)
        elseif data.Hex or data.hex then
            local hex = tostring(data.Hex or data.hex):gsub('^#', '')
            local ok, c = pcall(Color3.fromHex, hex)
            if ok and typeof(c) == 'Color3' then color = c end
            if data.Alpha or data.alpha or data.a then alpha = tonumber(data.Alpha or data.alpha or data.a) end
        elseif data[1] ~= nil and data[2] ~= nil and data[3] ~= nil then
            local r, g, b = tonumber(data[1]) or 1, tonumber(data[2]) or 1, tonumber(data[3]) or 1
            if r > 1 or g > 1 or b > 1 then
                color = Color3.fromRGB(r, g, b)
            else
                color = Color3.new(r, g, b)
            end
            alpha = tonumber(data[4] or data.a or data.A or alpha)
        elseif typeof(data.Color) == 'Color3' then
            color = data.Color
            alpha = tonumber(data.Transparency or data.Alpha or data.alpha or data.a or alpha)
        end
    end
    return color, alpha
end

__akira_shared.script_paths = function()

local DisplayName = 'Akira'
local StorageRoot = 'akira'

local AutoShowPath = StorageRoot .. '/AutoShow.txt'
local UiSettingsPath = StorageRoot .. '/UISettings.json'
local HttpService = game:GetService('HttpService')

local DefaultUiSettings = {
    auto_show = false,
    show_notification = true,
    show_keybind_states = false,
    show_mobile_button = true,
    auto_execute_on_teleport = false,
    auto_save_config = false,
    load_config_name = '',
    menu_keybind = 'RightShift',
    ui_scale = 100,
}

local module = {}

pcall(function()
    if not isfolder(StorageRoot) then
        makefolder(StorageRoot)
    end
end)

local function clone_table(source)
    local copy = {}
    for key, value in pairs(source) do
        copy[key] = value
    end
    return copy
end

local function apply_ui_setting_overrides(defaults, overrides)
    if type(overrides) ~= 'table' then
        return defaults
    end

    for key, value in pairs(overrides) do
        if DefaultUiSettings[key] ~= nil and value ~= nil then
            defaults[key] = value
        end
    end

    return defaults
end

local function sanitize_ui_settings(settings, defaults)
    local data = clone_table(defaults)
    if type(settings) ~= 'table' then
        return data
    end

    for key, fallback in pairs(defaults) do
        local value = settings[key]
        if type(fallback) == 'boolean' then
            if type(value) == 'boolean' then
                data[key] = value
            end
        elseif type(fallback) == 'string' then
            if type(value) == 'string' and value ~= '' then
                data[key] = value
            end
        elseif type(fallback) == 'number' then
            if type(value) == 'number' then
                data[key] = math.clamp(math.round(value), 50, 150)
            end
        end
    end

    return data
end

local function read_legacy_auto_show(default_value)
    local path = module.auto_show_path()
    if not isfile(path) then
        return default_value
    end

    local success, value = pcall(readfile, path)
    if not success then
        return default_value
    end

    value = string.lower(tostring(value))
    if value == 'true' then
        return true
    end
    if value == 'false' then
        return false
    end

    return default_value
end

function module.storage_root()
    return StorageRoot
end

function module.auto_show_path()
    return AutoShowPath
end

function module.ui_settings_path()
    return UiSettingsPath
end

function module.default_ui_settings(overrides)
    return apply_ui_setting_overrides(clone_table(DefaultUiSettings), overrides)
end

function module.sanitize_config_name(config_name)
    local clean = tostring(config_name or ''):gsub('^%s+', ''):gsub('%s+$', ''):gsub('^["\']', ''):gsub('["\']$', ''):gsub('%.[jJ][sS][oO][nN]$', '')
    clean = clean:gsub('[\\/:*?"<>|]', '')
    return clean
end

function module.config_path(config_name)
    return StorageRoot .. '/settings/' .. module.sanitize_config_name(config_name) .. '.json'
end

function module.list_config_names(extra)
    local list = {}
    local seen = {}
    local function add(name)
        name = module.sanitize_config_name(name)
        if name == '' or string.lower(name) == 'none' or seen[name] then
            return
        end
        seen[name] = true
        list[#list + 1] = name
    end
    if type(extra) == 'table' then
        for _, name in ipairs(extra) do
            add(name)
        end
    end
    local folders = {
        StorageRoot .. '/settings',
        StorageRoot .. '/Configs',
        'akira/settings',
        'akira/Configs',
    }
    for _, folder in ipairs(folders) do
        pcall(function()
            if type(makefolder) == 'function' and type(isfolder) == 'function' and not isfolder(folder) then
                makefolder(folder)
            end
            if type(listfiles) ~= 'function' or (type(isfolder) == 'function' and not isfolder(folder)) then
                return
            end
            for _, file in ipairs(listfiles(folder) or {}) do
                local normalized = tostring(file):gsub('\\', '/')
                local name = normalized:match('([^/]+)%.[jJ][sS][oO][nN]$') or normalized:match('([^/]+)%.[cC][fF][gG]$')
                add(name)
            end
        end)
    end
    table.sort(list, function(a, b)
        return string.lower(a) < string.lower(b)
    end)
    return list
end

function module.remove_premade_configs()
    local names = { 'Legit', 'Rage', 'RIVALS Default', 'RIVALS', 'RIVALS Default.json' }
    local removed = 0
    for _, name in ipairs(names) do
        local clean = module.sanitize_config_name(name)
        local paths = {
            module.config_path(clean),
            StorageRoot .. '/Configs/' .. clean .. '.json',
            StorageRoot .. '/' .. clean .. '.json',
        }
        for _, path in ipairs(paths) do
            pcall(function()
                if type(isfile) == 'function' and isfile(path) and type(delfile) == 'function' then
                    delfile(path)
                    removed = removed + 1
                end
            end)
        end
    end
    return removed
end

function module.delete_config(config_name)
    local clean = module.sanitize_config_name(config_name)
    if clean == '' then
        return false
    end
    local deleted = false
    local paths = {
        module.config_path(clean),
        StorageRoot .. '/Configs/' .. clean .. '.json',
        StorageRoot .. '/' .. clean .. '.json',
    }
    for _, path in ipairs(paths) do
        local okExists, exists = pcall(function()
            return type(isfile) == 'function' and isfile(path)
        end)
        if okExists and exists and type(delfile) == 'function' then
            local ok = pcall(delfile, path)
            deleted = deleted or ok
        end
    end
    return deleted
end

function module.load_ui_settings(overrides)
    local defaults = module.default_ui_settings(overrides)

    if isfile(UiSettingsPath) then
        local read_ok, raw = pcall(readfile, UiSettingsPath)
        if read_ok then
            local decode_ok, decoded = pcall(function()
                return HttpService:JSONDecode(raw)
            end)
            if decode_ok then
                return sanitize_ui_settings(decoded, defaults)
            end
        end
    end

    defaults.auto_show = read_legacy_auto_show(defaults.auto_show)
    return defaults
end

function module.save_ui_settings(settings, overrides)
    local data = sanitize_ui_settings(settings, module.default_ui_settings(overrides))
    writefile(UiSettingsPath, HttpService:JSONEncode(data))
    writefile(module.auto_show_path(), data.auto_show and 'true' or 'false')
    return data
end

function module.ensure_auto_show_file()
    local path = module.auto_show_path()
    local ui_settings = module.load_ui_settings()
    writefile(path, ui_settings.auto_show and 'true' or 'false')
    return path
end

function module.capture_script_key()
    local seen = {}
    local function consider(value)
        if type(value) ~= 'string' then
            return nil
        end
        local key = (string.match(value, '^%s*(.-)%s*$') or value)
        if key == '' or key == 'script_key' or key == 'key' or seen[key] then
            return nil
        end
        seen[key] = true
        return key
    end

    local candidates = {}
    local function push(value)
        local key = consider(value)
        if key then
            candidates[#candidates + 1] = key
        end
    end

    if type(getgenv) == 'function' then
        local ok, env = pcall(getgenv)
        if ok and type(env) == 'table' then
            push(env.script_key)
            push(env.key)
            push(env.Key)
            push(env.LRM_LinkedKey)
            push(env.LRM_UserKey)
            push(env.LRM_ScriptKey)
        end
    end
    push(rawget(_G, 'script_key'))
    push(rawget(_G, 'key'))
    push(rawget(_G, 'Key'))
    push(rawget(_G, 'LRM_LinkedKey'))
    push(rawget(_G, 'LRM_UserKey'))
    if type(__akira_genv) == 'table' then
        push(__akira_genv.script_key)
        push(__akira_genv.key)
        push(__akira_genv.Key)
    end
    if type(script_key) == 'string' then
        push(script_key)
    end
    if type(key) == 'string' then
        push(key)
    end

    if type(isfile) == 'function' and type(readfile) == 'function' then
        for _, path in ipairs({ 'akira/script_key.txt', 'akira/key.txt', 'key.txt', 'key', 'script_key.txt', 'akira_key.txt', 'akira/script_key.txt', 'akira/key.txt', 'akira_key.txt' }) do
            local exists = false
            local okExists, isThere = pcall(isfile, path)
            exists = okExists and isThere == true
            if exists then
                local okRead, raw = pcall(readfile, path)
                if okRead then
                    push(raw)
                end
            end
        end
    end

    return candidates[1]
end

function module.persist_script_key(key)
    if type(key) ~= 'string' or key == '' then
        return
    end
    pcall(function()
        if type(getgenv) == 'function' then
            local env = getgenv()
            if type(env) == 'table' then
                env.script_key = key
                env.key = key
            end
        end
        if type(_G) == 'table' then
            rawset(_G, 'script_key', key)
            rawset(_G, 'key', key)
        end
        if type(__akira_genv) == 'table' then
            __akira_genv.script_key = key
            __akira_genv.key = key
        end
    end)
    pcall(function()
        if type(makefolder) == 'function' then
            pcall(makefolder, 'akira')
        end
        if type(writefile) == 'function' then
            for _, path in ipairs({ 'akira/script_key.txt', 'akira/key.txt' }) do
                pcall(writefile, path, key)
            end
        end
    end)
end

function module.queue_on_teleport_script()
    local key = module.capture_script_key()
    local waitBlock = [[task.spawn(function()
    pcall(function()
        if not game:IsLoaded() then
