		end)

		SaveManager:SetIgnoreIndexes({ 'SaveManager_ConfigList', 'SaveManager_ConfigName', 'SaveManager_ClipboardInput' })

	end

	SaveManager:BuildFolderTree()

end



getgenv().SaveManager = SaveManager;

return SaveManager

