local function runSource(source, chunkName)
    if type(source) ~= 'string' or source == '' then
        return nil, 'empty source'
    end
    local loader = loadstring or load
    if type(loader) ~= 'function' then
        return nil, 'loadstring unavailable'
    end
    local chunk, compileErr = loader(source, chunkName)
    if type(chunk) ~= 'function' then
        chunk, compileErr = loader(source)
    end
    if type(chunk) ~= 'function' then
        return nil, 'compile failed: ' .. tostring(compileErr)
    end
    local okRun, result = pcall(chunk)
    if okRun and type(result) == 'table' then
        return result
    end
    return nil, 'execution failed: ' .. tostring(result)
end

local function fetchRemoteSource(url)
    if type(url) ~= 'string' or url == '' then
        return nil
    end
    local result = nil
    local done = false
    task.spawn(function()
        local function take(body)
            return type(body) == 'string' and #body > 100
        end
        if type(game.HttpGet) == 'function' then
            local okGet, src = pcall(game.HttpGet, game, url)
            if okGet and take(src) then
                result = src
                done = true
                return
            end
        end
        local req = (syn and syn.request) or (http and http.request) or http_request or request
        if type(req) == 'function' then
            local okReq, resp = pcall(req, {
                Url = url,
                Method = 'GET',
            })
            if okReq and type(resp) == 'table' then
                local body = resp.Body or resp.body
                local status = tonumber(resp.StatusCode or resp.status_code) or 200
                if (status == 200 or status == 0) and take(body) then
                    result = body
                    done = true
                    return
                end
            end
        end
        done = true
    end)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 12 do
        task.wait(0.05)
    end
    return result
end

local AKIRA_UI_REMOTE = {
