local function fetchFirstRemote(urls)
    if type(urls) == 'string' then
        urls = { urls }
    end
    if type(urls) ~= 'table' then
        return nil
    end
    for i = 1, #urls do
        local source = fetchRemoteSource(urls[i])
        if type(source) == 'string' and #source > 100 then
            return source
        end
    end
    return nil
end

local function bindAkiraIntoBridge(bridgeSource, akiraSource)
    if type(bridgeSource) ~= 'string' then
        return bridgeSource
    end
    bridgeSource = bridgeSource:gsub('\r\n', '\n'):gsub('\r', '\n')
    if type(akiraSource) == 'string' and #akiraSource > 100 then
        akiraSource = akiraSource:gsub('\r\n', '\n'):gsub('\r', '\n')
        akiraSource = akiraSource:gsub(
            'state = state or not Toggle%.State',
            'if state == nil then state = not Toggle.State end\n\t\tstate = state == true'
        )
        akiraSource = akiraSource:gsub('Library%.MenuKey = EKC%.LeftAlt', 'Library.MenuKey = EKC.RightShift')
        local env = (type(getgenv) == 'function' and getgenv()) or _G
        if type(env) == 'table' then
            env.__AkiraAkiraSource = akiraSource
        end
        pcall(function()
            _G.__AkiraAkiraSource = akiraSource
        end)
    end
    if not bridgeSource:find('HSRC_CANDIDATES', 1, true) then
        return bridgeSource
    end
    local startPos = bridgeSource:find('local HSRC_CANDIDATES', 1, true)
    local errPos = bridgeSource:find("error('[Akira Bridge] '", 1, true)
        or bridgeSource:find('error("[Akira Bridge] "', 1, true)
    if not startPos or not errPos then
        return bridgeSource
    end
    local endPos = bridgeSource:find('\nend', errPos, true)
    if not endPos then
        return bridgeSource
    end
    endPos = endPos + 4
    local replacement = [[
local AkiraSource = (type(getgenv) == 'function' and getgenv().__AkiraAkiraSource) or rawget(_G, '__AkiraAkiraSource')
if type(AkiraSource) ~= 'string' or #AkiraSource < 100 then
	error('[Akira Bridge] AkiraUI.lua was not fetched from GitHub')
end
]]
    bridgeSource = bridgeSource:sub(1, startPos - 1) .. replacement .. bridgeSource:sub(endPos + 1)
    bridgeSource = bridgeSource:gsub(
        "local function MakeSectionFrom%(entry, sectionArgs%)\n\tlocal Sec = entry%.Section%(sectionArgs%)\n\treturn Sec\nend",
        [[local function MakeSectionFrom(entry, sectionArgs)
	if type(entry) ~= 'table' then
		return nil
	end
	local fn = entry.Section
	if type(fn) ~= 'function' then
		return nil
	end
	local ok, sec = pcall(fn, entry, sectionArgs or {})
	if ok then
		return sec
	end
	ok, sec = pcall(fn, sectionArgs or {})
	if ok then
		return sec
	end
	return nil
end]]
    )
    bridgeSource = bridgeSource:gsub(
        "Library%.ToggleKeybind = %{\n\tValue = H%.MenuKey,",
        "pcall(function() H.MenuKey = Enum.KeyCode.RightShift end)\nLibrary.ToggleKeybind = {\n\tValue = 'RightShift',\n\tType = 'KeyPicker',"
    )
    bridgeSource = bridgeSource:gsub(
        "local L = section:Label%({ Text = opts%.Text or opts%.Name or tostring%(id%) }%)\n\t\tlocal el = L:Toggle",
        "if type(section) ~= 'table' or type(section.Label) ~= 'function' then error('[Akira Bridge] section has no Label') end\n\t\tlocal L = section:Label({ Text = opts.Text or opts.Name or tostring(id) })\n\t\tsection.LastLabel = L\n\t\tlocal el = L:Toggle"
    )
    bridgeSource = bridgeSource:gsub(
        "function page%.Select%(self%)\n\t\tpcall%(hp%.Open, hp%)\n\t\tpage%.IsOpen = true\n\tend",
        "function page.Select(self)\n\t\tpcall(hp.Open, hp)\n\t\tpage.IsOpen = true\n\tend\n\tfunction page.ShowTab(self)\n\t\tpcall(hp.Open, hp)\n\t\tpage.IsOpen = true\n\tend\n\tfunction page.HideTab(self)\n\t\tpcall(hp.Close, hp)\n\t\tpage.IsOpen = false\n\tend"
    )
    bridgeSource = bridgeSource:gsub(
        "ControlBuilders%.AddToggle = function%(self, id, opts%) return BuildControl%(self%.Section, 'Toggle', id, opts%) end",
        [[ControlBuilders.AddToggle = function(self, id, opts)
	local ok, res = pcall(BuildControl, self.Section, 'Toggle', id, opts)
	if ok then return res end
	warn('[Akira Bridge] AddToggle', id, res)
	return { Type = 'Toggle', Value = false, OnChanged = function() end, SetValue = function() end, AddKeyPicker = function() return {} end, AddColorPicker = function() return {} end, AddColorpicker = function() return {} end }
end]]
    )
    return bridgeSource
end

local function loadWorkspaceModule(fileName)
    local lastErr = 'module not found'
    local env = (type(getgenv) == 'function' and getgenv()) or _G
    local cacheKeys = {
        ['Library.lua'] = 'Library',
        ['ThemeManager.lua'] = 'ThemeManager',
        ['SaveManager.lua'] = 'SaveManager',
        ['DrawingLib.lua'] = 'DrawingLib',
        ['AkiraUI.lua'] = 'AkiraUI',
    }
    local function acceptModule(module, err)
        if type(module) ~= 'table' then
            lastErr = err or lastErr
            return nil
        end
        if fileName == 'Library.lua' and type(AkiraLibFn(module, 'Create', 'Window')) ~= 'function' then
            lastErr = 'loaded UI library has no CreateWindow'
            return nil
        end
        local cacheKey = cacheKeys[fileName]
        if cacheKey and type(env) == 'table' then
            env[cacheKey] = module
        end
        return module
    end

    -- GitHub raw only (never written to workspace, never the old Linoria embed).
    local remoteSource = fetchFirstRemote(AKIRA_UI_REMOTE[fileName])
    if fileName == 'Library.lua' then
        local akiraSource = fetchFirstRemote(AKIRA_UI_REMOTE['AkiraUI.lua'])
        if type(akiraSource) ~= 'string' then
            error('Failed to load AkiraUI.lua from GitHub')
        end
        remoteSource = bindAkiraIntoBridge(remoteSource, akiraSource)
    end
    if type(remoteSource) == 'string' then
        local module, err = runSource(remoteSource, '@github/' .. fileName)
        local accepted = acceptModule(module, err)
        if accepted then
            return accepted
        end
        lastErr = err or lastErr
        warn('[Akira] GitHub UI file "' .. fileName .. '" failed to load: ' .. tostring(lastErr))
    else
        lastErr = 'remote fetch failed'
        warn('[Akira] GitHub fetch failed for ' .. fileName)
    end

    local cacheKey = cacheKeys[fileName]
    if cacheKey and type(env) == 'table' and type(env[cacheKey]) == 'table' then
        local cached = env[cacheKey]
        if fileName ~= 'Library.lua' or type(AkiraLibFn(cached, 'Create', 'Window')) == 'function' then
            return cached
        end
    end

    if fileName ~= 'Library.lua' then
        local embeddedSource = __akira_embedded_ui[fileName]
        if type(embeddedSource) == 'string' and #embeddedSource > 100 then
            local module, err = runSource(embeddedSource, '@embedded/' .. fileName)
            local accepted = acceptModule(module, err)
            if accepted then
                warn('[Akira] Using embedded ' .. fileName .. ' (GitHub unavailable)')
                return accepted
            end
            lastErr = err or lastErr
        end
    end

    error('Failed to load ' .. fileName .. ': ' .. tostring(lastErr))
end

local function AdaptLinoriaForAkira(library, saveManager, themeManager)
    if type(library) ~= 'table' then
        error('GitHub UI library did not return a table')
    end
    pcall(function()
        library.MenuKey = Enum.KeyCode.RightShift
        library.ToggleKeybind = library.ToggleKeybind or {}
        library.ToggleKeybind.Type = 'KeyPicker'
        library.ToggleKeybind.Value = 'RightShift'
        if type(library.ToggleKeybind.SetValue) == 'function' then
            library.ToggleKeybind:SetValue('RightShift')
        elseif type(library.ToggleKeybind.SetKeybind) == 'function' then
            library.ToggleKeybind.SetKeybind(Enum.KeyCode.RightShift)
        end
    end)
    if type(saveManager) ~= 'table' then
        error('SaveManager.lua did not return a table')
    end
    if type(themeManager) ~= 'table' then
        error('ThemeManager.lua did not return a table')
    end

    local TweenService = game:GetService('TweenService')
    local UserInputService = game:GetService('UserInputService')

    if type(getgenv) == 'function' then
        local okEnv, env = pcall(getgenv)
        if okEnv and type(env) == 'table' then
            library.Toggles = library.Toggles or env.Toggles or {}
            library.Options = library.Options or env.Options or {}
            env.Library = library
            env.Toggles = library.Toggles
            env.Options = library.Options
        end
    end

    library.Toggles = library.Toggles or {}
    library.Options = library.Options or {}
    library.Flags = library.Options
    library.Unloaded = false
    library.NotifyOnError = false
    library.ShowCustomCursor = false
    library.ToggleKeybind = library.ToggleKeybind
    library.UnloadSignals = library.UnloadSignals or {}
    library.DependencyBoxes = library.DependencyBoxes or {}
    library.Directory = library.Directory or 'akira'
    library.CurrentUIScale = library.CurrentUIScale or 1
    library._AccentCallbacks = library._AccentCallbacks or {}
    library._ScaleFrames = library._ScaleFrames or {}

    local function patchAkiraScreenGui(sg)
        if typeof(sg) ~= 'Instance' or not sg:IsA('LayerCollector') then
            return
        end
        pcall(function()
            sg.Name = 'Akira'
            sg.ResetOnSpawn = false
            sg.IgnoreGuiInset = true
            sg.DisplayOrder = math.max(tonumber(sg.DisplayOrder) or 0, 100000)
            sg.Enabled = true
            local parent = game:GetService('CoreGui')
            if type(gethui) == 'function' then
                local okHui, hui = pcall(gethui)
                if okHui and typeof(hui) == 'Instance' then
                    parent = hui
                end
            end
            if sg.Parent ~= parent then
                sg.Parent = parent
            end
        end)
    end
    patchAkiraScreenGui(library.ScreenGui)

    local function resolveAkiraFont()
        local getAsset = (type(getcustomasset) == 'function' and getcustomasset) or (type(getsynasset) == 'function' and getsynasset)
        local candidates = {
            'UE-LIB/PixeloidSansBold-1jpBg.ttf',
            'miku ui/PixeloidSansBold-1jpBg.ttf',
            'akira/fonts/PixeloidSansBold-1jpBg.ttf',
            'PixeloidSansBold-1jpBg.ttf',
            'UE-LIB/Pixeboy-z8XGD.ttf',
            'miku ui/Pixeboy-z8XGD.ttf',
            'akira/fonts/Pixeboy-z8XGD.ttf',
            'Pixeboy-z8XGD.ttf',
        }
        if type(getAsset) == 'function' then
            for _, path in ipairs(candidates) do
                local exists = true
                if type(isfile) == 'function' then
                    local okFile, isThere = pcall(isfile, path)
                    exists = okFile and isThere == true
                end
                if exists then
                    local okAsset, asset = pcall(getAsset, path)
                    if okAsset and type(asset) == 'string' and asset ~= '' then
                        local okFont, fontObj = pcall(Font.new, asset)
                        if okFont and typeof(fontObj) == 'Font' then
                            return fontObj
                        end
                    end
                end
            end
        end
        return Enum.Font.Arcade
    end

    local nativeNotify = library.Notify
    if type(nativeNotify) == 'function' then
        function library:Notify(textOrInfo, time, extra)
            local text = textOrInfo
            local duration = time
            if type(textOrInfo) == 'table' then
                local title = textOrInfo.Title or textOrInfo.title
                local desc = textOrInfo.Description or textOrInfo.Text or textOrInfo.text
                if title and desc then
                    text = tostring(title) .. '  ·  ' .. tostring(desc)
                else
                    text = tostring(desc or title or 'Notification')
                end
                duration = textOrInfo.Time or textOrInfo.Duration or time
            elseif textOrInfo ~= nil and type(textOrInfo) ~= 'string' then
                text = tostring(textOrInfo)
            end
            return nativeNotify(self, text, duration, extra)
        end
    end

    local origCreate = library.Create
    if type(origCreate) == 'function' then
        function library:Create(Class, Properties)
            local inst = Class
            if type(Class) == 'string' then
                inst = Instance.new(Class)
            end
            local parent = Properties and Properties.Parent
            for prop, val in pairs(Properties or {}) do
                if prop ~= 'Parent' then
                    if prop == 'Font' and typeof(val) == 'Font' then
                        inst.FontFace = val
                    else
                        pcall(function()
                            inst[prop] = val
                        end)
                    end
                end
            end
            if parent ~= nil then
                inst.Parent = parent
            end
            if inst:IsA("TextLabel") or inst:IsA("TextBox") or inst:IsA("TextButton") then
                local fontSize = tonumber(library.FontSize) or 14
                if Properties and Properties.TextSize then
                    inst:SetAttribute("FontSizeOffset", Properties.TextSize - fontSize)
                else
                    inst:SetAttribute("FontSizeOffset", 0)
                end
            end
            return inst
        end
    end

    local origGetTextBounds = library.GetTextBounds
    function library:GetTextBounds(Text, Font, Size, Resolution)
        local useFont = Font
        if typeof(useFont) == 'Font' then
            useFont = Enum.Font.Code
        end
        if type(origGetTextBounds) == 'function' then
            local ok, bx, by = pcall(origGetTextBounds, self, Text, useFont, Size, Resolution)
            if ok and tonumber(bx) and bx > 0 then
                return bx, by
            end
        end
        local text = tostring(Text or '')
        local size = Size or 14
        local ok, bounds = pcall(function()
            return game:GetService('TextService'):GetTextSize(text, size, useFont or Enum.Font.Code, Resolution or Vector2.new(1920, 1080))
        end)
        if ok and bounds and bounds.X and bounds.X > 0 then
            return bounds.X, bounds.Y
        end
        return math.max(#text * size * 0.62, 8), size + 2
    end

    library.Font = resolveAkiraFont()
    library.AccentColor = library.AccentColor or Color3.fromRGB(56, 130, 255)
    library.BackgroundColor = library.BackgroundColor or Color3.fromRGB(10, 11, 14)
    library.MainColor = library.MainColor or Color3.fromRGB(15, 17, 22)
    library.OutlineColor = library.OutlineColor or Color3.fromRGB(26, 28, 36)
    library.FontColor = library.FontColor or Color3.fromRGB(255, 255, 255)
    library.Accent = library.AccentColor
    library.SaveManager = saveManager
    library.ThemeManager = themeManager

    if library.Scheme == nil then
        library.Scheme = setmetatable({}, {
            __index = function(_, key)
                return library[key]
            end,
            __newindex = function(_, key, value)
                library[key] = value
            end,
        })
    end

    function library:GetViewportSize()
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize
        if viewport and viewport.X > 0 and viewport.Y > 0 then
            return viewport
        end
        local screenResolutionOk, res = pcall(function()
            return game:GetService('GuiService'):GetScreenResolution()
        end)
        if screenResolutionOk and typeof(res) == 'Vector2' and res.X > 0 and res.Y > 0 then
            return res
        end
        return Vector2.new(1280, 720)
    end

    function library:IsMobile()
        if self._IsMobileCached ~= nil then
            return self._IsMobileCached
        end
        local UserInputService = game:GetService('UserInputService')
        local GuiService = game:GetService('GuiService')

        local preferredOk, preferred = pcall(function()
            return UserInputService.PreferredInput
        end)
        if preferredOk and preferred == Enum.PreferredInput.Touch then
            self._IsMobileCached = true
            return true
        end

        local smallScreenOk, isSmall = pcall(function()
            return GuiService:IsSmallScreen()
        end)
        if smallScreenOk and isSmall == true then
            self._IsMobileCached = true
            return true
        end

        if UserInputService.TouchEnabled == true then
            if UserInputService.KeyboardEnabled == false or UserInputService.MouseEnabled == false then
                self._IsMobileCached = true
                return true
            end
            if UserInputService.AccelerometerEnabled == true or UserInputService.GyroscopeEnabled == true then
                self._IsMobileCached = true
                return true
            end
            local vp = self:GetViewportSize()
            if vp.Y < 560 or vp.X < 860 then
                self._IsMobileCached = true
                return true
            end
        end

        self._IsMobileCached = false
        return false
    end

    function library:GetResponsiveWindowSize()
        local viewport = self:GetViewportSize()
        local vx = viewport.X
        local vy = viewport.Y

        if not self:IsMobile() then
            local w = math.clamp(math.floor(vx * 0.36), 530, 560)
            local h = math.clamp(math.floor(vy * 0.62), 480, 520)
            return UDim2.fromOffset(w, h)
        end

        local isTablet = (math.min(vx, vy) >= 600) or (vx >= 1000 and vy >= 650)
        if isTablet then
            local w = math.clamp(math.floor(vx * 0.74), 680, 820)
            local h = math.clamp(math.floor(vy * 0.72), 480, 580)
            return UDim2.fromOffset(w, h)
        end

        -- Mobile phone (landscape orientation):
        -- Height: fills ~88% of vertical space, leaving safe margins top and bottom
        local targetHeight = math.floor(vy * 0.88)
        local h = math.clamp(targetHeight, 280, math.max(vy - 28, 280))

        -- Width: proportional card layout (~80% screen width, capped by 2.1x aspect ratio and screen width)
        local targetWidth = math.floor(vx * 0.80)
        local maxWidth = math.min(math.floor(h * 2.1), vx - 32)
        local minWidth = math.min(500, math.max(vx - 24, 300))
        local w = math.clamp(targetWidth, minWidth, maxWidth)

        return UDim2.fromOffset(w, h)
    end

    function library:GetMobileWindowSize()
        return self:GetResponsiveWindowSize()
    end

    function library:SetMobileButtonEnabled(enabled)
        if enabled == true and type(self.EnsureMobileToggleButton) == 'function' then
            pcall(self.EnsureMobileToggleButton, self)
        end
        local gui = self.MobileGui
        if typeof(gui) == 'Instance' then
            gui.Enabled = enabled == true
        end
    end

    function library:EnsureMobileToggleButton()
        if typeof(self.MobileGui) == 'Instance' and self.MobileGui.Parent then
            self.MobileGui.Enabled = true
            if type(self._UpdateMobileToggleVisual) == 'function' then
                pcall(self._UpdateMobileToggleVisual, self)
            end
            return self.MobileGui
        end

        local CoreGui = game:GetService('CoreGui')
        local UserInputService = game:GetService('UserInputService')
        local TweenService = game:GetService('TweenService')
        local parent = CoreGui
        pcall(function()
            if type(gethui) == 'function' then
                parent = gethui()
            end
        end)

        local SIZE = 52
        local accent = self.AccentColor or Color3.fromRGB(56, 130, 255)
        local fillClosedTop = Color3.fromRGB(16, 18, 24)
        local fillClosedBottom = Color3.fromRGB(10, 11, 14)
        local fillOpenTop = accent:Lerp(Color3.fromRGB(25, 45, 75), 0.35)
        local fillOpenBottom = Color3.fromRGB(12, 18, 28)
        local outlineClosed = Color3.fromRGB(45, 60, 85)
        local statusActiveColor = Color3.fromRGB(52, 211, 153)
        local statusInactiveColor = accent

        local gui = Instance.new('ScreenGui')
        gui.Name = 'AkiraMobileToggle'
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.DisplayOrder = 100000
        gui.Parent = parent

        -- Pinned on upper-mid left edge, clear of thumbstick and topbar
        local root = Instance.new('Frame')
        root.Name = 'Root'
        root.AnchorPoint = Vector2.new(0, 0.5)
        root.BackgroundTransparency = 1
        root.BorderSizePixel = 0
        root.Size = UDim2.fromOffset(SIZE, SIZE)
        root.Position = UDim2.new(0, 16, 0.32, 0)
        root.ZIndex = 10
        root.Parent = gui

        -- Ambient neon backlight glow
        local aura = Instance.new('Frame')
        aura.Name = 'Aura'
        aura.AnchorPoint = Vector2.new(0.5, 0.5)
        aura.Position = UDim2.fromScale(0.5, 0.5)
        aura.Size = UDim2.fromOffset(SIZE + 10, SIZE + 10)
        aura.BackgroundColor3 = accent
        aura.BackgroundTransparency = 0.82
        aura.BorderSizePixel = 0
        aura.ZIndex = 9
        aura.Parent = root
        local auraCorner = Instance.new('UICorner')
        auraCorner.CornerRadius = UDim.new(0, 20)
        auraCorner.Parent = aura

        -- Multi-layer drop shadow
        local shadow = Instance.new('Frame')
        shadow.Name = 'Shadow'
        shadow.BackgroundColor3 = Color3.fromRGB(4, 2, 8)
        shadow.BackgroundTransparency = 0.45
        shadow.BorderSizePixel = 0
        shadow.Size = UDim2.fromOffset(SIZE, SIZE)
        shadow.Position = UDim2.fromOffset(0, 3)
        shadow.ZIndex = 10
        shadow.Parent = root
        local shadowCorner = Instance.new('UICorner')
        shadowCorner.CornerRadius = UDim.new(0, 15)
        shadowCorner.Parent = shadow

        -- Main Action Button
        local button = Instance.new('TextButton')
        button.Name = 'Toggle'
        button.BackgroundColor3 = fillClosedTop
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Size = UDim2.fromOffset(SIZE, SIZE)
        button.Position = UDim2.fromOffset(0, 0)
        button.Text = ''
        button.ZIndex = 12
        button.Active = true
        button.Selectable = false
        button.Parent = root
        local buttonCorner = Instance.new('UICorner')
        buttonCorner.CornerRadius = UDim.new(0, 15)
        buttonCorner.Parent = button

        -- Metallic / Glass Face Gradient
        local gradient = Instance.new('UIGradient')
        gradient.Name = 'FaceGradient'
        gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(140, 135, 155)),
        })
        gradient.Rotation = 90
        gradient.Parent = button

        -- Holographic / Neon Outer Ring
        local stroke = Instance.new('UIStroke')
        stroke.Name = 'Ring'
        stroke.Color = accent
        stroke.Thickness = 1.8
        stroke.Transparency = 0.1
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = button

        local strokeGrad = Instance.new('UIGradient')
        strokeGrad.Name = 'StrokeGrad'
        strokeGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
