        inner.ZIndex = 13
        inner.Parent = button
        local innerCorner = Instance.new('UICorner')
        innerCorner.CornerRadius = UDim.new(0, 12)
        innerCorner.Parent = inner
        local innerStroke = Instance.new('UIStroke')
        innerStroke.Name = 'BevelStroke'
        innerStroke.Color = Color3.fromRGB(255, 255, 255)
        innerStroke.Thickness = 1
        innerStroke.Transparency = 0.86
        innerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        innerStroke.Parent = inner

        -- Stylized Logo Shadow Glow
        local logoGlow = Instance.new('TextLabel')
        logoGlow.Name = 'LogoGlow'
        logoGlow.BackgroundTransparency = 1
        logoGlow.Size = UDim2.fromScale(1, 1)
        logoGlow.Position = UDim2.fromOffset(0, 1)
        logoGlow.Text = 'H'
        logoGlow.TextColor3 = accent
        logoGlow.TextTransparency = 0.45
        logoGlow.TextSize = 24
        logoGlow.ZIndex = 14
        logoGlow.Parent = button
        if typeof(self.Font) == 'Font' then
            logoGlow.FontFace = self.Font
        else
            logoGlow.Font = Enum.Font.GothamBlack
        end

        -- Center Emblem 'H'
        local letter = Instance.new('TextLabel')
        letter.Name = 'Letter'
        letter.BackgroundTransparency = 1
        letter.Size = UDim2.fromScale(1, 1)
        letter.Position = UDim2.fromOffset(0, 0)
        letter.Text = 'H'
        letter.TextColor3 = Color3.fromRGB(255, 255, 255)
        letter.TextSize = 23
        letter.ZIndex = 15
        letter.Parent = button
        if typeof(self.Font) == 'Font' then
            letter.FontFace = self.Font
        else
            letter.Font = Enum.Font.GothamBlack
        end

        -- Top-Right Illuminated Status LED Pip
        local statusGem = Instance.new('Frame')
        statusGem.Name = 'StatusGem'
        statusGem.AnchorPoint = Vector2.new(1, 0)
        statusGem.Position = UDim2.new(1, -7, 0, 7)
        statusGem.Size = UDim2.fromOffset(9, 9)
        statusGem.BackgroundColor3 = statusInactiveColor
        statusGem.BorderSizePixel = 0
        statusGem.ZIndex = 16
        statusGem.Parent = button
        local gemCorner = Instance.new('UICorner')
        gemCorner.CornerRadius = UDim.new(1, 0)
        gemCorner.Parent = statusGem

        local gemStroke = Instance.new('UIStroke')
        gemStroke.Name = 'GemStroke'
        gemStroke.Color = Color3.fromRGB(255, 255, 255)
        gemStroke.Thickness = 1
        gemStroke.Transparency = 0.4
        gemStroke.Parent = statusGem

        local gemCore = Instance.new('Frame')
        gemCore.Name = 'GemCore'
        gemCore.AnchorPoint = Vector2.new(0.5, 0.5)
        gemCore.Position = UDim2.fromScale(0.5, 0.5)
        gemCore.Size = UDim2.fromOffset(4, 4)
        gemCore.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        gemCore.BackgroundTransparency = 0.1
        gemCore.BorderSizePixel = 0
        gemCore.ZIndex = 17
        gemCore.Parent = statusGem
        local coreCorner = Instance.new('UICorner')
        coreCorner.CornerRadius = UDim.new(1, 0)
        coreCorner.Parent = gemCore

        -- Bottom Cyber Accent Bar
        local accentBar = Instance.new('Frame')
        accentBar.Name = 'AccentBar'
        accentBar.AnchorPoint = Vector2.new(0.5, 1)
        accentBar.Position = UDim2.new(0.5, 0, 1, -5)
        accentBar.Size = UDim2.fromOffset(18, 3)
        accentBar.BackgroundColor3 = accent
        accentBar.BorderSizePixel = 0
        accentBar.ZIndex = 15
        accentBar.Parent = button
        local barCorner = Instance.new('UICorner')
        barCorner.CornerRadius = UDim.new(1, 0)
        barCorner.Parent = accentBar

        -- Press scale for smooth micro-animations
        local pressScale = Instance.new('UIScale')
        pressScale.Name = 'PressScale'
        pressScale.Scale = 1
        pressScale.Parent = root

        local function applyAccent(color)
            if typeof(color) ~= 'Color3' then
                return
            end
            accent = color
            fillOpenTop = accent:Lerp(Color3.fromRGB(25, 45, 75), 0.35)
            statusInactiveColor = accent
            aura.BackgroundColor3 = accent
            accentBar.BackgroundColor3 = accent
            logoGlow.TextColor3 = accent
            if type(self._UpdateMobileToggleVisual) == 'function' then
                self:_UpdateMobileToggleVisual()
            end
        end

        function self:_UpdateMobileToggleVisual()
            if not button or not button.Parent then
                return
            end
            local open = false
            if type(self.IsMenuVisible) == 'function' then
                open = self:IsMenuVisible() == true
            elseif self.Toggled == true then
                open = true
            end

            local targetBg = open and fillOpenTop or fillClosedTop
            local targetStroke = open and accent or outlineClosed:Lerp(accent, 0.5)
            local targetStatus = open and statusActiveColor or statusInactiveColor
            local targetAura = open and 0.65 or 0.85

            pcall(function()
                TweenService:Create(button, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    BackgroundColor3 = targetBg,
                }):Play()
                TweenService:Create(stroke, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    Color = targetStroke,
                    Thickness = open and 2.2 or 1.8,
                }):Play()
                TweenService:Create(statusGem, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    BackgroundColor3 = targetStatus,
                }):Play()
                TweenService:Create(aura, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                    BackgroundTransparency = targetAura,
                }):Play()
            end)
        end

        local connections = {}
        local lastPressTime = 0

        local function animatePress(pressed)
            pcall(function()
                if pressed then
                    TweenService:Create(pressScale, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        Scale = 0.88,
                    }):Play()
                else
                    TweenService:Create(pressScale, TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                        Scale = 1.0,
                    }):Play()
                end
            end)
        end

        local function onToggleActivated()
            local now = os.clock()
            if now - lastPressTime < 0.28 then
                return
            end
            lastPressTime = now

            animatePress(true)
            task.delay(0.09, function()
                animatePress(false)
            end)

            if type(self.Toggle) == 'function' then
                task.spawn(function()
                    pcall(self.Toggle, self)
                    if type(self._UpdateMobileToggleVisual) == 'function' then
                        self:_UpdateMobileToggleVisual()
                    end
                end)
            end
        end

        -- Multi-event touch & click listeners guarantee 100% responsiveness on all devices
        table.insert(connections, button.Activated:Connect(onToggleActivated))
        table.insert(connections, button.MouseButton1Click:Connect(onToggleActivated))
        if typeof(button.TouchTap) == 'RBXScriptSignal' then
            table.insert(connections, button.TouchTap:Connect(onToggleActivated))
        end

        -- Touch down visual feedback
        table.insert(connections, button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                animatePress(true)
            end
        end))

        -- Fallback toggle on InputEnded if Activated is suppressed by mobile executor
        table.insert(connections, button.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                animatePress(false)
                onToggleActivated()
            end
        end))

        if type(self.OnAccent) == 'function' then
            self:OnAccent(function()
                applyAccent(self.AccentColor or self.Accent)
            end)
        end

        if not self._MobileToggleWrapped and type(self.Toggle) == 'function' then
            self._MobileToggleWrapped = true
            local nativeToggle = self.Toggle
            self.Toggle = function(lib, ...)
                local result = nativeToggle(lib, ...)
                local owner = (type(lib) == 'table' and lib) or self
                if type(owner._UpdateMobileToggleVisual) == 'function' then
                    owner:_UpdateMobileToggleVisual()
                end
                return result
            end
        end

        self:_UpdateMobileToggleVisual()
        self.MobileGui = gui
        table.insert(self.UnloadSignals, function()
            for _, conn in ipairs(connections) do
                pcall(function()
                    conn:Disconnect()
                end)
            end
            pcall(function()
                gui:Destroy()
            end)
            self.MobileGui = nil
            self._UpdateMobileToggleVisual = nil
        end)
        return gui
    end

    local nativeOnUnload = library.OnUnload
    function library:OnUnload(callback)
        if type(callback) == 'function' then
            table.insert(self.UnloadSignals, callback)
        elseif type(nativeOnUnload) == 'function' then
            return nativeOnUnload(self, callback)
        end
    end

    local originalNotify = library.Notify
    library.Notify = function(self, first, second, ...)
        if type(first) == 'table' then
            local title = first.Title or first.title
            local description = first.Description or first.description or first.Text or first.text
            local time = first.Time or first.time or first.LifeTime or second
            local text = description or title or ''
            if title and description then
                text = tostring(title) .. ' — ' .. tostring(description)
            end
            if type(originalNotify) == 'function' then
                return originalNotify(self, tostring(text), time)
            end
            return
        end
        if type(originalNotify) == 'function' then
            return originalNotify(self, first, second, ...)
        end
    end

    function library:CreateInstance(className, properties)
        local inst = Instance.new(className)
        for key, value in pairs(properties or {}) do
            pcall(function()
                inst[key] = value
            end)
        end
        return inst
    end

    function library:RegisterUIScale(frame)
        if typeof(frame) ~= 'Instance' then
            return
        end
        self._ScaleFrames = self._ScaleFrames or {}
        for _, existing in ipairs(self._ScaleFrames) do
            if existing == frame then
                local scale = frame:FindFirstChildOfClass('UIScale')
                if scale then
                    scale.Scale = self.CurrentUIScale or 1
                end
                return scale
            end
        end
        local scale = frame:FindFirstChildOfClass('UIScale')
        if not scale then
            scale = Instance.new('UIScale')
            scale.Name = 'AkiraUIScale'
            scale.Parent = frame
        end
        scale.Scale = self.CurrentUIScale or 1
        table.insert(self._ScaleFrames, frame)
        return scale
    end

    function library:SetUIScale(scale)
        scale = math.clamp(tonumber(scale) or 1, 0.5, 2)
        if self._LastAppliedUIScale and math.abs(self._LastAppliedUIScale - scale) < 0.001 then
            return
        end
        self._LastAppliedUIScale = scale
        self.CurrentUIScale = scale
        local function apply(container)
            if typeof(container) ~= 'Instance' then
                return
            end
            local uiScale = container:FindFirstChild('AkiraUIScale')
            if not uiScale or not uiScale:IsA('UIScale') then
                uiScale = container:FindFirstChildOfClass('UIScale')
            end
            if not uiScale then
                uiScale = Instance.new('UIScale')
                uiScale.Name = 'AkiraUIScale'
                uiScale.Parent = container
            end
            if math.abs(uiScale.Scale - scale) >= 0.001 then
                uiScale.Scale = scale
            end
        end
        local windowFrame = self.Window and self.Window.Holder
        apply(windowFrame)
        for index = #self._ScaleFrames, 1, -1 do
            local frame = self._ScaleFrames[index]
            if not frame or not frame.Parent then
                table.remove(self._ScaleFrames, index)
            elseif frame ~= windowFrame and not (windowFrame and frame:IsDescendantOf(windowFrame)) then
                apply(frame)
            end
        end
        task.defer(function()
            if type(self.ClampGuiToViewport) ~= 'function' then
                return
            end
            if windowFrame then
                pcall(self.ClampGuiToViewport, self, windowFrame)
            end
            local frames = self._ScaleFrames
            if type(frames) ~= 'table' then
                return
            end
            for _, frame in ipairs(frames) do
                if frame and frame ~= windowFrame then
                    pcall(self.ClampGuiToViewport, self, frame)
                end
            end
        end)
    end

    function library:AddGlowingV2(frame, color, transparency)
        if typeof(frame) ~= 'Instance' then
            return
        end
        local stroke = Instance.new('UIStroke')
        stroke.Color = color or self.Accent
        stroke.Transparency = transparency or 0.45
        stroke.Thickness = 1.5
        stroke.LineJoinMode = Enum.LineJoinMode.Miter
        stroke.Parent = frame
        return stroke
    end
    library.AddGlowing = library.AddGlowingV2

    function library:RegisterAccentGradient(gradient)
        if typeof(gradient) ~= 'Instance' then
            return
        end
        local accent = self.Accent or Color3.fromRGB(56, 140, 255)
        gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, accent),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(245, 247, 250)),
            ColorSequenceKeypoint.new(1, accent),
        })
    end

    function library:RegisterAccent(instance, property)
        if typeof(instance) ~= 'Instance' or type(property) ~= 'string' then
            return
        end
        local accent = self.Accent or Color3.fromRGB(56, 140, 255)
        pcall(function()
            instance[property] = accent
        end)
    end

    function library:OnAccent(fn)
        if type(fn) == 'function' then
            table.insert(self._AccentCallbacks, fn)
        end
    end

    local originalTween = library.Tween
    function library:Tween(a, b, c)
        if typeof(a) == 'Instance' and typeof(b) == 'TweenInfo' and type(c) == 'table' then
            local tw = TweenService:Create(a, b, c)
            tw:Play()
            return tw
        end
        if type(originalTween) == 'function' then
            return originalTween(self, a, b, c)
        end
    end

    function library:Draggable(targetFrame, dragHandle)
        dragHandle = dragHandle or targetFrame
        if typeof(targetFrame) ~= 'Instance' or typeof(dragHandle) ~= 'Instance' then
            return
        end
        local dragging = false
        local grabOffset
        local moveConn
        local endConn
        local function stopDrag()
            dragging = false
            grabOffset = nil
            if moveConn then
                moveConn:Disconnect()
                moveConn = nil
            end
            if endConn then
                endConn:Disconnect()
                endConn = nil
            end
            if type(self.ClampGuiToViewport) == 'function' then
                self:ClampGuiToViewport(targetFrame)
            end
        end
        local function applyDrag()
            if not dragging or not grabOffset then
                return
            end
            local mouse = UserInputService:GetMouseLocation()
            local scale = 1
            if type(self.GetGuiScale) == 'function' then
                scale = self:GetGuiScale(targetFrame)
            else
                local uiScale = targetFrame:FindFirstChildOfClass('UIScale')
                if uiScale and type(uiScale.Scale) == 'number' and uiScale.Scale > 0 then
                    scale = uiScale.Scale
                end
            end
            local absSize = targetFrame.AbsoluteSize
            local absX = mouse.X - grabOffset.X
            local absY = mouse.Y - grabOffset.Y
            local camera = workspace.CurrentCamera
            local vp = camera and camera.ViewportSize
            if vp then
                local pad = 4
                local minX = pad
                local minY = pad
                local maxX = vp.X - absSize.X - pad
                local maxY = vp.Y - absSize.Y - pad
                if maxX < minX then
                    minX = pad
                    maxX = pad
                end
                if maxY < minY then
                    minY = pad
                    maxY = pad
                end
                absX = math.clamp(absX, minX, maxX)
                absY = math.clamp(absY, minY, maxY)
            end
            local ap = targetFrame.AnchorPoint
            local nextPos = UDim2.fromOffset(
                math.floor((absX + absSize.X * ap.X) / scale + 0.5),
                math.floor((absY + absSize.Y * ap.Y) / scale + 0.5)
            )
            if targetFrame.Position ~= nextPos then
                targetFrame.Position = nextPos
            end
        end
        dragHandle.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            local mouse = UserInputService:GetMouseLocation()
            local absPos = targetFrame.AbsolutePosition
            dragging = true
            grabOffset = Vector2.new(mouse.X - absPos.X, mouse.Y - absPos.Y)
            if moveConn then
                moveConn:Disconnect()
            end
            if endConn then
                endConn:Disconnect()
            end
            moveConn = UserInputService.InputChanged:Connect(function(move)
                if not dragging then
                    return
                end
                if move.UserInputType == Enum.UserInputType.MouseMovement or move.UserInputType == Enum.UserInputType.Touch then
                    applyDrag()
                end
            end)
            endConn = UserInputService.InputEnded:Connect(function(ended)
                if ended.UserInputType == Enum.UserInputType.MouseButton1 or ended.UserInputType == Enum.UserInputType.Touch then
                    stopDrag()
                end
            end)
        end)
    end

    function library:CenterWindow()
        local holder = self.Window and self.Window.Holder
        if typeof(holder) ~= 'Instance' then
            return
        end
        local vp = self:GetViewportSize()
        local scale = tonumber(self.CurrentUIScale) or 1
        if scale <= 0 then
            scale = 1
        end
        local w = holder.Size.X.Offset
        local h = holder.Size.Y.Offset
        if w < 8 then
            w = 550
        end
        if h < 8 then
            h = 500
        end
        holder.AnchorPoint = Vector2.new(0, 0)
        holder.Position = UDim2.fromOffset(
            math.max(8, math.floor((vp.X - w * scale) * 0.5)),
            math.max(8, math.floor((vp.Y - h * scale) * 0.5))
        )
    end

    function library:ClampGuiToViewport(frame)
        if typeof(frame) ~= 'Instance' or not frame:IsA('GuiObject') then
            return
        end
        if frame.Visible ~= true then
            return
        end
        local vp = self:GetViewportSize()
        local scale = 1
        if type(self.GetGuiScale) == 'function' then
            local okScale, got = pcall(self.GetGuiScale, self, frame)
            if okScale and type(got) == 'number' and got > 0 then
                scale = got
            end
        else
            local uiScale = frame:FindFirstChildOfClass('UIScale')
            if uiScale and type(uiScale.Scale) == 'number' and uiScale.Scale > 0 then
                scale = uiScale.Scale
            end
        end
        local absSize = frame.AbsoluteSize
        if absSize.X < 8 or absSize.Y < 8 then
            absSize = Vector2.new(math.max(frame.Size.X.Offset * scale, 8), math.max(frame.Size.Y.Offset * scale, 8))
        end
        local absPos = frame.AbsolutePosition
        local pad = 8
        local x, y = absPos.X, absPos.Y
        local offScreen = (x + absSize.X < pad) or (y + absSize.Y < pad) or (x > vp.X - pad) or (y > vp.Y - pad)
        if offScreen or (x <= 2 and y <= 2 and frame.AnchorPoint.X > 0) then
            x = (vp.X - absSize.X) * 0.5
            y = (vp.Y - absSize.Y) * 0.5
        else
            local maxX = math.max(pad, vp.X - absSize.X - pad)
            local maxY = math.max(pad, vp.Y - absSize.Y - pad)
            x = math.clamp(x, pad, maxX)
            y = math.clamp(y, pad, maxY)
        end
        local ap = frame.AnchorPoint
        frame.Position = UDim2.fromOffset(
            math.floor((x + absSize.X * ap.X) / scale + 0.5),
            math.floor((y + absSize.Y * ap.Y) / scale + 0.5)
        )
    end

    function library:IsMenuVisible()
        local holder = self.Window and self.Window.Holder
        return holder ~= nil and holder.Visible == true
    end

    function library:SetVisible(state)
        state = state == true
        if self:IsMenuVisible() ~= state then
            self:Toggle()
        end
    end

    library.ToggleMenu = function(self, state)
        if state == nil then
            return library:Toggle()
        end
        return library:SetVisible(state == true)
    end

    local nativeCreateWindow = AkiraLibFn(library, 'Create', 'Window')
    if type(nativeCreateWindow) ~= 'function' then
        error('UI library is missing CreateWindow')
    end
    local lastMenuToggleAt = 0
    local function wrapLibraryToggle()
        if library._AkiraToggleWrapped then
            return
        end
        local nativeToggle = library.Toggle
        if type(nativeToggle) ~= 'function' then
            return
        end
        library._AkiraToggleWrapped = true
        library.Toggle = function(self, ...)
            local now = os.clock()
            if now - lastMenuToggleAt < 0.16 then
                return
            end
            lastMenuToggleAt = now
            local lib = (type(self) == 'table' and self.ScreenGui) and self or library
            patchAkiraScreenGui(lib.ScreenGui)
            local result = nativeToggle(lib, ...)
            patchAkiraScreenGui(lib.ScreenGui)
            local holder = lib.Window and lib.Window.Holder
            if typeof(holder) == 'Instance' then
                holder.Visible = lib.Toggled == true
                if lib.Toggled == true and lib.OpenedFrames ~= nil then
                    local abs = holder.AbsolutePosition
                    local size = holder.AbsoluteSize
                    if size.X < 8 or size.Y < 8 or abs.X + size.X < 24 or abs.Y + size.Y < 24 or (abs.X <= 2 and abs.Y <= 2 and holder.AnchorPoint.X > 0) then
                        if type(lib.CenterWindow) == 'function' then
                            lib:CenterWindow()
                        end
                    elseif type(lib.ClampGuiToViewport) == 'function' then
                        pcall(lib.ClampGuiToViewport, lib, holder)
                    end
                    if type(lib.ResumeLayout) == 'function' then
                        pcall(lib.ResumeLayout, lib)
                    end
                    local win = lib.Window
                    local shown = false
                    if win and win.ActiveTab and type(win.ActiveTab.ShowTab) == 'function' then
                        shown = pcall(win.ActiveTab.ShowTab, win.ActiveTab)
                    end
                    if not shown and win and type(win.Tabs) == 'table' then
                        for _, tab in pairs(win.Tabs) do
                            if type(tab) == 'table' and type(tab.ShowTab) == 'function' then
                                pcall(tab.ShowTab, tab)
                                break
                            end
                        end
                    end
                end
            end
            return result
        end
    end

    local function bindMenuKeyHandler()
        if library._AkiraMenuKeyBound then
            return
        end
        library._AkiraMenuKeyBound = true
        local UserInputService = game:GetService('UserInputService')
        local function normalizeKeyName(name)
            if typeof(name) == 'EnumItem' then
                name = name.Name
            end
            name = tostring(name or ''):gsub('%s+', '')
            local aliases = {
                RShift = 'RightShift',
                LShift = 'LeftShift',
                RCtrl = 'RightControl',
                RightCtrl = 'RightControl',
                LCtrl = 'LeftControl',
                LeftCtrl = 'LeftControl',
                LAlt = 'LeftAlt',
                RAlt = 'RightAlt',
            }
            return aliases[name] or name
        end
        local conn = UserInputService.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.Keyboard then
                return
            end
            if UserInputService:GetFocusedTextBox() then
                return
            end
            local pressed = normalizeKeyName(input.KeyCode.Name)
            local bind = library.ToggleKeybind
            local bindName = nil
            if type(bind) == 'table' then
                bindName = bind.Value or bind.Name
            elseif type(bind) == 'string' then
                bindName = bind
            elseif typeof(bind) == 'EnumItem' then
                bindName = bind.Name
            end
            bindName = normalizeKeyName(bindName)
            if bindName == '' or bindName == 'None' or bindName == 'nil' then
                bindName = 'RightShift'
            end
            if pressed == bindName then
                task.spawn(function()
                    library:Toggle()
                end)
            end
        end)
        library.UnloadSignals = library.UnloadSignals or {}
        table.insert(library.UnloadSignals, function()
            pcall(function()
                conn:Disconnect()
            end)
        end)
    end

    AkiraLibSet(library, 'Create', 'Window', function(self, config)
        if type(config) == 'table' then
            if config.TabPadding == nil then
                config.TabPadding = 5
            end
            if self:IsMobile() then
                config.Size = self:GetResponsiveWindowSize()
                config.Center = true
            elseif typeof(config.Size) ~= 'UDim2' then
                config.Size = self:GetResponsiveWindowSize()
            else
                local vp = self:GetViewportSize()
                if config.Size.X.Offset > (vp.X - 30) or config.Size.Y.Offset > (vp.Y - 30) then
                    config.Size = self:GetResponsiveWindowSize()
                    config.Center = true
                end
            end
        end
        if type(config) == 'table' and library.OpenedFrames == nil then
            config.Size = nil
            config.Center = false
        end
        local window = nativeCreateWindow(self, config)
        library.Window = window
        patchAkiraScreenGui(library.ScreenGui)
        wrapLibraryToggle()
        bindMenuKeyHandler()
        local isAkira = library.OpenedFrames == nil
        if window and typeof(window.Holder) == 'Instance' and not isAkira then
            local holder = window.Holder
            if type(library.CenterWindow) == 'function' then
                library:CenterWindow()
            end
            local camera = workspace.CurrentCamera
            if camera then
                local lastVp = nil
                camera:GetPropertyChangedSignal('ViewportSize'):Connect(function()
                    local vp = library:GetViewportSize()
                    if lastVp and lastVp.X == vp.X and lastVp.Y == vp.Y then
                        return
                    end
                    lastVp = vp

                    if library.Toggled ~= true and (not holder or not holder.Visible) then
                        return
                    end

                    if library:IsMobile() then
                        holder.Size = library:GetResponsiveWindowSize()
                    elseif holder.AbsoluteSize.X > (vp.X - 20) or holder.AbsoluteSize.Y > (vp.Y - 20) then
                        holder.Size = library:GetResponsiveWindowSize()
                    end
                    if type(library.CenterWindow) == 'function' then
                        library:CenterWindow()
                    elseif type(library.ClampGuiToViewport) == 'function' then
                        pcall(library.ClampGuiToViewport, library, holder)
                    end
                end)
            end
        end
        if type(library.EnsureMobileToggleButton) == 'function' then
            pcall(library.EnsureMobileToggleButton, library)
        end
        if not isAkira then
        pcall(function()
            local holder = window and window.Holder
            if typeof(holder) ~= 'Instance' then
                return
            end
            for _, desc in ipairs(holder:GetDescendants()) do
                if desc:IsA('UIListLayout') and desc.FillDirection == Enum.FillDirection.Horizontal then
                    local parent = desc.Parent
                    if parent and (parent.Name == 'TabArea' or (parent:IsA('GuiObject') and parent.Size.Y.Offset == 0 and parent.Size.Y.Scale == 1)) then
                        desc.HorizontalAlignment = Enum.HorizontalAlignment.Left
                    end
                end
            end
        end)
        end
        if window and type(window.AddTab) == 'function' then
            local nativeAddTab = window.AddTab
            function window:AddTab(title, ...)
                local existing = self.Tabs and self.Tabs[title]
                if type(existing) == 'table' and existing.Name == title and type(existing.AddLeftGroupbox) == 'function' then
                    return existing
                end
                local tab = nativeAddTab(self, title, ...)
                if tab then
                    local function dummyToggle()
                        return {
                            Type = 'Toggle',
                            Value = false,
                            OnChanged = function() end,
                            SetValue = function(self, v) self.Value = v == true end,
                            AddKeyPicker = function()
                                return { Type = 'KeyPicker', Value = 'None', Mode = 'Toggle', OnClick = function() end, SetValue = function() end, GetState = function() return false end }
                            end,
                            AddColorPicker = function()
                                return { Type = 'ColorPicker', Value = Color3.new(1, 1, 1), SetValue = function() end, SetValueRGB = function() end, OnChanged = function() end }
                            end,
                            AddColorpicker = function(self, ...)
                                return self:AddColorPicker(...)
                            end,
                        }
                    end
                    local function wrapBox(box)
                        if not box or box.__DropdownWrapped then
                            return box
                        end
                        box.__DropdownWrapped = true
                        local function wrapMethod(methodName, fallback)
                            local native = box[methodName]
                            if type(native) ~= 'function' then
                                if fallback then
                                    box[methodName] = fallback
                                end
                                return
                            end
                            box[methodName] = function(self, ...)
                                local ok, res = pcall(native, self, ...)
                                if not ok then
                                    warn('[Akira] ' .. methodName .. ' failed: ' .. tostring(res))
                                    if fallback then
                                        return fallback(self, ...)
                                    end
                                    return nil
                                end
                                if methodName == 'AddToggle' and type(res) == 'table' and type(res.AddKeyPicker) == 'function' then
                                    local nativeKP = res.AddKeyPicker
                                    res.AddKeyPicker = function(...)
                                        local okKP, kp = pcall(nativeKP, ...)
                                        if okKP then
                                            return kp
                                        end
                                        warn('[Akira] AddKeyPicker failed: ' .. tostring(kp))
                                        return dummyToggle():AddKeyPicker()
                                    end
                                end
                                if methodName == 'AddLabel' and type(res) == 'table' then
                                    if type(res.AddKeyPicker) == 'function' then
                                        local nativeKP = res.AddKeyPicker
                                        res.AddKeyPicker = function(...)
                                            local okKP, kp = pcall(nativeKP, ...)
                                            if okKP then
                                                return kp
                                            end
                                            warn('[Akira] Label:AddKeyPicker failed: ' .. tostring(kp))
                                            return dummyToggle():AddKeyPicker()
                                        end
                                    end
                                    if type(res.AddColorPicker) ~= 'function' then
                                        res.AddColorPicker = dummyToggle().AddColorPicker
                                        res.AddColorpicker = res.AddColorPicker
                                    end
                                end
                                return res
                            end
                        end
                        if type(box.AddDropdown) == 'function' then
                            local nativeAddDropdown = box.AddDropdown
                            function box:AddDropdown(idx, info)
                                if type(info) == 'table' then
                                    if type(info.Values) ~= 'table' then
                                        info.Values = {}
                                    end
                                    if info.Default == nil and info.AllowNull ~= true then
                                        if info.Values[1] ~= nil and not info.Multi then
                                            info.Default = info.Values[1]
                                        else
                                            info.AllowNull = true
                                        end
                                    end
                                end
                                local ok, res = pcall(nativeAddDropdown, self, idx, info)
                                if ok then
                                    return res
                                end
                                warn('[Akira] AddDropdown failed: ' .. tostring(res))
                                return { Type = 'Dropdown', Value = info and info.Default, Values = info and info.Values or {}, SetValue = function() end, SetValues = function() end, OnChanged = function() end }
                            end
                        end
                        wrapMethod('AddToggle', function()
                            return dummyToggle()
                        end)
                        wrapMethod('AddSlider')
                        wrapMethod('AddInput')
                        wrapMethod('AddButton')
                        wrapMethod('AddLabel')
                        wrapMethod('AddDivider')
                        wrapMethod('AddParagraph')
                        wrapMethod('AddColorPicker')
                        wrapMethod('AddKeyPicker', function()
                            return dummyToggle():AddKeyPicker()
                        end)
                        wrapMethod('AddDependencyBox', function()
                            local dummy = { Type = 'DependencyBox', SetupDependencies = function() end }
                            setmetatable(dummy, { __index = box })
                            return dummy
                        end)
                        return box
                    end

                    for _, method in ipairs({ 'AddLeftGroupbox', 'AddRightGroupbox', 'AddGroupbox', 'AddLeftTabbox', 'AddRightTabbox' }) do
                        if type(tab[method]) == 'function' then
                            local nativeMethod = tab[method]
                            tab[method] = function(t, ...)
                                local okBox, box = pcall(nativeMethod, t, ...)
                                if not okBox then
                                    warn('[Akira] ' .. method .. ' failed: ' .. tostring(box))
                                    box = {}
                                end
                                if method:find('Tabbox', 1, true) and box and type(box.AddTab) == 'function' then
                                    local nativeBoxAddTab = box.AddTab
                                    box.AddTab = function(b, ...)
                                        local subTab = nativeBoxAddTab(b, ...)
                                        return wrapBox(subTab)
                                    end
                                end
                                return wrapBox(box)
                            end
                        end
                    end
                end
                return tab
            end
        end
        if window and type(window.SelectTab) ~= 'function' then
            function window:SelectTab(name)
                local tab = self.Tabs and self.Tabs[name]
                if tab and type(tab.ShowTab) == 'function' then
                    tab:ShowTab()
                end
            end
        end
        if window and type(window.AddDialog) ~= 'function' then
            function window:AddDialog(index, dialogInfo)
                dialogInfo = dialogInfo or {}
                self.__Dialogs = self.__Dialogs or {}
                if self.__Dialogs[index] then
                    return self.__Dialogs[index]
                end
                local tab = (self.Tabs and (self.Tabs['misc'] or self.Tabs['Misc'])) or (type(self.AddTab) == 'function' and self:AddTab('misc'))
                local box = tab and type(tab.AddLeftGroupbox) == 'function' and tab:AddLeftGroupbox(dialogInfo.Title or tostring(index))
                if not box and tab and type(tab.AddRightGroupbox) == 'function' then
                    box = tab:AddRightGroupbox(dialogInfo.Title or tostring(index))
                end
                box = box or {}
                if type(dialogInfo.Description) == 'string' and type(box.AddLabel) == 'function' then
                    box:AddLabel(dialogInfo.Description, true)
                end
                if type(box.Dismiss) ~= 'function' then
                    function box:Dismiss() end
                end
                if type(dialogInfo.FooterButtons) == 'table' and type(box.AddButton) == 'function' then
                    task.defer(function()
                        for name, buttonInfo in pairs(dialogInfo.FooterButtons) do
                            box:AddButton(buttonInfo.Title or name, function()
                                if type(buttonInfo.Callback) == 'function' then
                                    buttonInfo.Callback(box)
                                end
                            end)
                        end
                    end)
                end
                self.__Dialogs[index] = box
                return box
            end
        end
        return window
    end)
    function library:LoadConfig(name)
        if saveManager and type(saveManager.Load) == 'function' then
            return saveManager:Load(name)
        end
        return false, 'save manager load missing'
    end

    function library:ApplyConfig(data)
        if saveManager and type(saveManager.LoadFromString) == 'function' and type(data) == 'string' then
            return saveManager:LoadFromString(data)
        end
        if type(data) ~= 'table' then
            return false
        end
        local env = (type(getgenv) == 'function' and getgenv()) or _G
        local bridge = (type(env) == 'table' and env.RivalsRuntimeBridge) or (type(RivalsRuntimeBridge) == 'table' and RivalsRuntimeBridge)
        if library.BeginSilentApply then
            pcall(library.BeginSilentApply, library)
        else
            library.ConfigLoading = true
            if type(library.SuspendLayout) == 'function' then
                pcall(library.SuspendLayout, library)
            end
        end
        if bridge then
            bridge.RuntimeRefreshSuspended = true
        end
        local ok = pcall(function()
            local objects = data.objects or data
            if type(objects) == 'table' then
                local parser = saveManager and saveManager.Parser
                local opCount = 0
                for _, option in ipairs(objects) do
                    if type(option) == 'table' and option.type and parser and parser[option.type] and type(parser[option.type].Load) == 'function' then
                        pcall(parser[option.type].Load, option.idx, option)
                    end
                    opCount = opCount + 1
                    if opCount % 15 == 0 then
                        task.wait()
                    end
                end
            end
        end)
        if type(library.UpdateDependencyBoxes) == 'function' then
            pcall(library.UpdateDependencyBoxes, library)
        end
        if bridge then
            bridge.RuntimeRefreshSuspended = false
        end
        if library.EndSilentApply then
            pcall(library.EndSilentApply, library)
        else
            library.ConfigLoading = false
            if type(library.ResumeLayout) == 'function' then
                pcall(library.ResumeLayout, library)
            end
        end
        return ok == true
    end

    local nativeSetFolder = saveManager.SetFolder
    function saveManager:SetFolder(folder)
        if type(folder) == 'string' and folder ~= '' then
            library.Directory = folder
        end
        if type(nativeSetFolder) == 'function' then
            return nativeSetFolder(self, folder)
        end
    end

    if type(themeManager.SetLibrary) == 'function' then
        themeManager:SetLibrary(library)
    end
    if type(saveManager.SetLibrary) == 'function' then
        saveManager:SetLibrary(library)
    end

    return library, saveManager, themeManager
end

__akira_boot_status('Loading UI library...')
Library = loadWorkspaceModule('Library.lua')
__akira_boot_status('Library.lua done: ' .. tostring(type(Library)))
ThemeManager = loadWorkspaceModule('ThemeManager.lua')
__akira_boot_status('ThemeManager.lua done: ' .. tostring(type(ThemeManager)))
SaveManager = loadWorkspaceModule('SaveManager.lua')
__akira_boot_status('SaveManager.lua done: ' .. tostring(type(SaveManager)))
pcall(function()
    DrawingLib = loadWorkspaceModule('DrawingLib.lua')
    if DrawingLib and Library then
        Library.DrawingLib = DrawingLib
    end
end)
__akira_boot_status('Preparing menu...')
Library, SaveManager, ThemeManager = AdaptLinoriaForAkira(Library, SaveManager, ThemeManager)
__akira_boot_yield(true)


do
    local CoreGui = game:GetService("CoreGui")
    local UserInputService = game:GetService("UserInputService")
    local NewColorSequence = ColorSequence.new
    local NewColorSequenceKeypoint = ColorSequenceKeypoint.new
    local ProggyCleanFont = typeof(Library.Font) == 'Font' and Library.Font or nil

function Library:CosmeticsWindow(Opts)
	Opts = typeof(Opts) == "table" and Opts or {}
	if type(self.CreateInstance) ~= 'function' then
		function self:CreateInstance(className, properties)
			if type(self.Create) == 'function' then
				local ok, inst = pcall(self.Create, self, className, properties)
				if ok and inst then
					return inst
				end
			end
			local inst = Instance.new(className)
			for key, value in pairs(properties or {}) do
				pcall(function()
					inst[key] = value
				end)
			end
			return inst
		end
	end
	local Width = tonumber(Opts.Width) or 580
	local Height = tonumber(Opts.Height) or 530
	local AccentColor = Library.Accent
	if typeof(AccentColor) ~= 'Color3' then
		AccentColor = Color3.fromRGB(56, 130, 255)
	end
	local ColMain = (typeof(Library.MainColor) == 'Color3' and Library.MainColor) or Color3.fromRGB(15, 17, 22)
	local ColBack = (typeof(Library.BackgroundColor) == 'Color3' and Library.BackgroundColor) or Color3.fromRGB(10, 11, 14)
	local ColAccent = (typeof(Library.AccentColor) == 'Color3' and Library.AccentColor) or AccentColor
	local ColOutline = (typeof(Library.OutlineColor) == 'Color3' and Library.OutlineColor) or Color3.fromRGB(26, 28, 36)
	local ColFont = (typeof(Library.FontColor) == 'Color3' and Library.FontColor) or Color3.fromRGB(255, 255, 255)
	local ColMuted = ColFont:Lerp(ColMain, 0.52)
	local ColRisk = (typeof(Library.RiskColor) == 'Color3' and Library.RiskColor) or Color3.fromRGB(255, 50, 50)
	local function LerpAccent(amount)
		return ColAccent:Lerp(ColMain, amount)
	end
	local CosmeticsFont = (Library and Library.Font) or Enum.Font.Arcade
	local function _BuildCosmeticTile(host, parent, name, icon, isSelected, onClick, onRightClick)
		local selectedBg = ColAccent:Lerp(ColMain, 0.75)
		local btn = host:CreateInstance("TextButton", {
			Name = tostring(name),
			Parent = parent,
			BackgroundColor3 = isSelected and selectedBg or ColMain,
			BorderSizePixel = 0,
			AutoButtonColor = false,
			Text = "",
			Size = UDim2.new(0, 87, 0, 62),
		})
		host:CreateInstance("UIStroke", {
			Parent = btn,
			Color = isSelected and ColAccent or ColOutline,
			Thickness = 1,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		})
		if type(icon) == "string" and icon ~= "" then
			host:CreateInstance("ImageLabel", {
				Parent = btn,
				BackgroundTransparency = 1,
				Image = icon,
				Size = UDim2.new(1, -8, 1, -18),
				Position = UDim2.new(0, 4, 0, 2),
				ScaleType = Enum.ScaleType.Fit,
			})
		end
		host:CreateInstance("TextLabel", {
			Parent = btn,
			BackgroundTransparency = 1,
			Text = tostring(name),
			TextColor3 = isSelected and ColAccent or ColFont,
			TextSize = 10,
			Font = CosmeticsFont,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Size = UDim2.new(1, -4, 0, 14),
			Position = UDim2.new(0, 2, 1, -16),
		})
		btn.MouseButton1Click:Connect(function()
			if type(onClick) == "function" then
				onClick()
			end
		end)
		if type(onRightClick) == "function" then
			btn.MouseButton2Click:Connect(function()
				onRightClick()
			end)
		end
		return btn
	end

	local Gui = self:CreateInstance("ScreenGui", {
		Name = "CosmeticsGui",
		IgnoreGuiInset = true,
		ResetOnSpawn = false,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 2000,
		Enabled = false,
	})
	pcall(function()
		local protect = protectgui or (syn and syn.protect_gui)
		if type(protect) == 'function' then
			protect(Gui)
		end
	end)
	do
		local parented = false
		local candidates = {}
		pcall(function()
			if type(gethui) == 'function' then
				candidates[#candidates + 1] = gethui()
			end
		end)
		candidates[#candidates + 1] = CoreGui
		for _, parent in ipairs(candidates) do
			if parent and not parented then
				parented = pcall(function()
					Gui.Parent = parent
				end) and Gui.Parent ~= nil
			end
		end
		if not parented then
			pcall(function()
				local lp = game:GetService('Players').LocalPlayer
				if lp then
					Gui.Parent = lp:FindFirstChildOfClass('PlayerGui')
				end
			end)
		end
	end

	local Outer = self:CreateInstance("Frame", {
		Name = "Outer",
		Parent = Gui,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.fromOffset(Width, Height),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BorderSizePixel = 0,
		Visible = false,
	})
	local curScale = self.CurrentUIScale or (Library and Library.CurrentUIScale) or 1.0
	local winScale = self:RegisterUIScale(Outer)
	if winScale then winScale.Scale = curScale end

	pcall(function()
		if type(self.AddCorner) == 'function' then
			self:AddCorner(Outer, 10)
		elseif type(Library.AddCorner) == 'function' then
			Library:AddCorner(Outer, 10)
		end
		if type(self.AddStroke) == 'function' then
			self:AddStroke(Outer, 'OutlineColor', 1)
		elseif type(Library.AddStroke) == 'function' then
			Library:AddStroke(Outer, 'OutlineColor', 1)
		end
		-- Soft glow behind the cosmetics window to match the main menu.
		local Glow = self:CreateInstance("Frame", {
			Name = "AkiraGlow",
			Parent = Outer,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, 0),
			Size = UDim2.new(1, 16, 1, 16),
			BackgroundColor3 = ColAccent,
			BackgroundTransparency = 0.9,
			BorderSizePixel = 0,
			ZIndex = 0,
		})
		if Glow then
			if type(self.AddCorner) == 'function' then
				self:AddCorner(Glow, 14)
			elseif type(Library.AddCorner) == 'function' then
				Library:AddCorner(Glow, 14)
			end
			if type(Library.AddToRegistry) == 'function' then
				pcall(Library.AddToRegistry, Library, Glow, { BackgroundColor3 = 'AccentColor' })
			end
		end
	end)
	local Inner = self:CreateInstance("Frame", {
		Name = "Inner",
		Parent = Outer,
		BackgroundColor3 = ColMain,
		BorderColor3 = ColAccent,
		BorderMode = Enum.BorderMode.Inset,
		Position = UDim2.new(0, 1, 0, 1),
		Size = UDim2.new(1, -2, 1, -2),
	})

	local TitleBar = self:CreateInstance("Frame", {
		Name = "TitleBar",
		Parent = Inner,
		Position = UDim2.new(0, 0, 0, 0),
		Size = UDim2.new(1, 0, 0, 28),
		BackgroundTransparency = 1,
		ZIndex = 5,
	})
	local TitleLbl = self:CreateInstance("TextLabel", {
		Parent = TitleBar,
		Position = UDim2.new(0, 12, 0, 0),
		Size = UDim2.new(1, -36, 1, 0),
		BackgroundTransparency = 1,
		Text = "Cosmetic Changer",
		TextColor3 = ColFont,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		Font = CosmeticsFont,
	})
	if ProggyCleanFont then TitleLbl.FontFace = ProggyCleanFont end

	local CloseBtn = self:CreateInstance("TextButton", {
		Parent = TitleBar,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -6, 0.5, 0),
		Size = UDim2.fromOffset(18, 18),
		BackgroundColor3 = ColMain,
		BorderSizePixel = 0,
		AutoButtonColor = false,
		Text = "X",
		TextColor3 = ColMuted,
		TextSize = 10,
		Font = CosmeticsFont,
		ZIndex = 6,
	})
	if ProggyCleanFont then CloseBtn.FontFace = ProggyCleanFont end
	self:CreateInstance("UIStroke", {
		Parent = CloseBtn,
		Color = ColOutline,
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
	})
	CloseBtn.MouseEnter:Connect(function()
		CloseBtn.TextColor3 = ColAccent
	end)
	CloseBtn.MouseLeave:Connect(function()
		CloseBtn.TextColor3 = ColMuted
	end)

	self:Draggable(Outer, TitleBar)

	local Content = self:CreateInstance("Frame", {
		Name = "Content",
		Parent = Inner,
		Position = UDim2.new(0, 8, 0, 28),
		Size = UDim2.new(1, -16, 1, -36),
		BackgroundTransparency = 1,
	})
	self:CreateInstance("UIListLayout", {
		Parent = Content,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 4),
	})

	-- 1. Weapon Filter Label
	local WeaponFilterLbl = self:CreateInstance("TextLabel", {
		Parent = Content,
		Size = UDim2.new(1, 0, 0, 14),
		BackgroundTransparency = 1,
		Text = "WEAPON FILTER",
		TextColor3 = ColMuted,
		TextSize = 11,
		Font = CosmeticsFont,
		TextXAlignment = Enum.TextXAlignment.Left,
		LayoutOrder = 1,
	})
	if ProggyCleanFont then WeaponFilterLbl.FontFace = ProggyCleanFont end

	-- 2. Weapon Search Box
	local WeaponSearchFrame = self:CreateInstance("Frame", {
		Parent = Content,
		Size = UDim2.new(1, 0, 0, 20),
		BackgroundColor3 = ColBack,
		BorderSizePixel = 0,
		LayoutOrder = 2,
	})
	local WeaponSearchStroke = self:CreateInstance("UIStroke", {
		Parent = WeaponSearchFrame,
		Color = ColOutline,
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
	})
	local WeaponSearchBox = self:CreateInstance("TextBox", {
		Parent = WeaponSearchFrame,
		Position = UDim2.new(0, 6, 0, 0),
		Size = UDim2.new(1, -12, 1, 0),
		BackgroundTransparency = 1,
		ClearTextOnFocus = false,
		PlaceholderText = "Search weapon...",
		PlaceholderColor3 = ColMuted,
		Text = "",
		TextColor3 = ColFont,
		TextSize = 11,
		Font = CosmeticsFont,
		TextXAlignment = Enum.TextXAlignment.Left,
	})
	if ProggyCleanFont then WeaponSearchBox.FontFace = ProggyCleanFont end
	WeaponSearchBox.Focused:Connect(function()
		WeaponSearchStroke.Color = Library.Accent
	end)
	WeaponSearchBox.FocusLost:Connect(function()
		WeaponSearchStroke.Color = ColOutline
	end)

	-- 3. Weapon Grid Frame
	local WeaponGridScroll = self:CreateInstance("ScrollingFrame", {
		Parent = Content,
		Size = UDim2.new(1, 0, 0, 136),
		BackgroundColor3 = ColBack,
		BorderSizePixel = 0,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = Library.Accent,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		CanvasSize = UDim2.new(0, 0, 0, 0),
		LayoutOrder = 3,
	})
	Library:RegisterAccent(WeaponGridScroll, "ScrollBarImageColor3")
	self:CreateInstance("UIStroke", {
		Parent = WeaponGridScroll,
		Color = ColOutline,
		Thickness = 1,
