	local function UpdateCategoryButtons()
		for i, cat in ipairs(Categories) do
			local btn = CategoryButtons[cat]
			if btn then
				local isCurrent = (i == CurrentCategoryIdx)
				btn.BackgroundColor3 = isCurrent and LerpAccent(0.8) or ColMain
				btn.TextColor3 = isCurrent and Library.Accent or ColMuted
				local bottomBar = btn:FindFirstChild("ActiveIndicator")
				if bottomBar then
					bottomBar.Visible = isCurrent
					bottomBar.BackgroundColor3 = Library.Accent
				end
			end
		end
	end

	for i, cat in ipairs(Categories) do
		local btn = self:CreateInstance("TextButton", {
			Name = "CatBtn_" .. cat,
			Parent = CategoryBar,
			Size = UDim2.new(0.245, 0, 1, 0),
			BackgroundColor3 = (i == 1) and LerpAccent(0.8) or ColMain,
			BorderSizePixel = 0,
			AutoButtonColor = false,
			Text = CategoryDisplayNames[cat] or cat,
			TextColor3 = (i == 1) and Library.Accent or ColMuted,
			TextSize = 11,
			Font = CosmeticsFont,
			LayoutOrder = i,
		})
		if ProggyCleanFont then btn.FontFace = ProggyCleanFont end

		local ind = self:CreateInstance("Frame", {
			Name = "ActiveIndicator",
			Parent = btn,
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, 0, 1, 0),
			Size = UDim2.new(1, 0, 0, 2),
			BackgroundColor3 = Library.Accent,
			BorderSizePixel = 0,
			Visible = (i == 1),
		})

		btn.MouseEnter:Connect(function()
			if i ~= CurrentCategoryIdx then
				btn.TextColor3 = ColFont
			end
		end)
		btn.MouseLeave:Connect(function()
			if i ~= CurrentCategoryIdx then
				btn.TextColor3 = ColMuted
			end
		end)

		btn.MouseButton1Click:Connect(function()
			if CurrentCategoryIdx ~= i then
				CurrentCategoryIdx = i
				UpdateCategoryButtons()
				if RefreshCosmeticsGrid then RefreshCosmeticsGrid() end
			end
		end)

		CategoryButtons[cat] = btn
	end

