	-- 10. Footer Label
	local FooterLbl = self:CreateInstance("TextLabel", {
		Parent = Content,
		Size = UDim2.new(1, 0, 0, 14),
		BackgroundTransparency = 1,
		Text = "Right click a weapon to toggle the skin changer for it.",
		TextColor3 = ColMuted,
		TextSize = 10,
		Font = CosmeticsFont,
		LayoutOrder = 12,
	})

	local SelectedWeapon = nil
	local SelectedCosmetic = nil
	local Obj = {
		_Visible = false,
		Gui = Gui,
		Outer = Outer,
	}

	RefreshCosmeticsGrid = function()
		for _, child in ipairs(CosmeticGridScroll:GetChildren()) do
			if child:IsA("GuiObject") and not child:IsA("UILayout") and not child:IsA("UIPadding") and not child:IsA("UIStroke") then
				child:Destroy()
			end
		end
		if not SelectedWeapon then return end

		local category = GetCategoryName()
		local filterText = CosmeticSearchBox.Text:lower()
		local list = type(Opts.GetCosmetics) == "function" and Opts.GetCosmetics(SelectedWeapon, category) or {}
		local activeVal = type(Opts.GetSelectedCosmetic) == "function" and Opts.GetSelectedCosmetic(SelectedWeapon, category) or nil

		for _, cosName in ipairs(list) do
			if filterText == "" or tostring(cosName):lower():find(filterText, 1, true) then
				local isSel = (activeVal ~= nil and activeVal == cosName)
				local icon = type(Opts.GetCosmeticIcon) == "function" and Opts.GetCosmeticIcon(SelectedWeapon, category, cosName) or ""
				_BuildCosmeticTile(self, CosmeticGridScroll, tostring(cosName), icon, isSel, function()
					SelectedCosmetic = cosName
					if type(Opts.OnSelectCosmetic) == "function" then
						Opts.OnSelectCosmetic(SelectedWeapon, category, cosName)
					end
					RefreshCosmeticsGrid()
				end, nil)
			end
		end
	end

	RefreshWeaponsGrid = function()
		for _, child in ipairs(WeaponGridScroll:GetChildren()) do
			if child:IsA("GuiObject") and not child:IsA("UILayout") and not child:IsA("UIPadding") and not child:IsA("UIStroke") then
				child:Destroy()
			end
		end

		local filterText = WeaponSearchBox.Text:lower()
		local weapons = type(Opts.GetWeapons) == "function" and Opts.GetWeapons() or {}
		if not SelectedWeapon and #weapons > 0 then
			SelectedWeapon = weapons[1]
		end

		for _, wName in ipairs(weapons) do
			if filterText == "" or tostring(wName):lower():find(filterText, 1, true) then
				local isSel = (SelectedWeapon == wName)
				local icon = type(Opts.GetWeaponIcon) == "function" and Opts.GetWeaponIcon(wName) or ""
				_BuildCosmeticTile(self, WeaponGridScroll, tostring(wName), icon, isSel, function()
					SelectedWeapon = wName
					RefreshWeaponsGrid()
					RefreshCosmeticsGrid()
					if type(Opts.OnSelectWeapon) == "function" then
						Opts.OnSelectWeapon(wName)
					end
				end, function()
					if type(Opts.OnToggleWeaponOverride) == "function" then
						Opts.OnToggleWeaponOverride(wName)
					end
				end)
			end
		end
	end

	WeaponSearchBox:GetPropertyChangedSignal("Text"):Connect(RefreshWeaponsGrid)
	CosmeticSearchBox:GetPropertyChangedSignal("Text"):Connect(RefreshCosmeticsGrid)

	ApplyAllBtn.MouseButton1Click:Connect(function()
		if SelectedWeapon and type(Opts.OnApplyAll) == "function" then
			local category = GetCategoryName()
			local activeVal = type(Opts.GetSelectedCosmetic) == "function" and Opts.GetSelectedCosmetic(SelectedWeapon, category) or SelectedCosmetic
			Opts.OnApplyAll(SelectedWeapon, category, activeVal)
			RefreshCosmeticsGrid()
		end
	end)

	RandomizeRandomBtn.MouseButton1Click:Connect(function()
		if type(Opts.OnRandomizeRandom) == "function" then
			Opts.OnRandomizeRandom()
			RefreshCosmeticsGrid()
		end
	end)

	RandomizeEverythingBtn.MouseButton1Click:Connect(function()
		if type(Opts.OnRandomizeEverything) == "function" then
			Opts.OnRandomizeEverything()
		elseif type(Opts.OnRandomizeRandom) == "function" then
			Opts.OnRandomizeRandom()
		end
		RefreshWeaponsGrid()
		RefreshCosmeticsGrid()
	end)

	ResetBtn.MouseButton1Click:Connect(function()
		if type(Opts.OnResetDefaults) == "function" then
			Opts.OnResetDefaults()
			RefreshWeaponsGrid()
			RefreshCosmeticsGrid()
		end
	end)

	local function CloseWindow()
		Obj:SetVisible(false)
	end
	CloseBtn.MouseButton1Click:Connect(CloseWindow)
	CloseBottomBtn.MouseButton1Click:Connect(CloseWindow)

	-- Sync with Main Window & Menu Keybind (RightShift)
	local function ResolveMenuKey()
		local menuKey = Enum.KeyCode.RightShift
		if Library.ToggleKeybind and Library.ToggleKeybind.Value then
			local raw = Library.ToggleKeybind.Value
			if typeof(raw) == "EnumItem" then
				menuKey = raw
			elseif typeof(raw) == "string" and Enum.KeyCode[raw] then
				menuKey = Enum.KeyCode[raw]
			end
		elseif Library.Flags and Library.Flags.MenuKeybind then
			local raw = Library.Flags.MenuKeybind
			if typeof(raw) == "EnumItem" then
				menuKey = raw
			elseif typeof(raw) == "string" and Enum.KeyCode[raw] then
				menuKey = Enum.KeyCode[raw]
			end
		end
		return menuKey
	end

	local keyConn = UserInputService.InputBegan:Connect(function(input, gameProc)
		if gameProc then return end
		if UserInputService:GetFocusedTextBox() then return end
		if input.KeyCode == Enum.KeyCode.Escape and Obj and Obj._Visible then
			Obj:SetVisible(false)
		end
	end)

	Library:OnAccent(function()
		UpdateCategoryButtons()
		if Obj and Obj._Visible then
			RefreshWeaponsGrid()
			RefreshCosmeticsGrid()
		end
	end)

	function Obj:SetVisible(state)
		self._Visible = state
		Outer.Visible = state
		Gui.Enabled = state
		if state then
			local curScale = (Library and Library.CurrentUIScale) or (self._Library and self._Library.CurrentUIScale) or 1.0
			local uiScale = Outer:FindFirstChildOfClass("UIScale")
			if uiScale then
				uiScale.Scale = curScale
			end
			UpdateCategoryButtons()
			RefreshWeaponsGrid()
			RefreshCosmeticsGrid()
			if type(Library.ClampGuiToViewport) == 'function' then
				task.defer(function()
					Library:ClampGuiToViewport(Outer)
				end)
			end
		end
	end

	function Obj:Toggle()
		self:SetVisible(not self._Visible)
	end

	function Obj:Refresh()
		UpdateCategoryButtons()
		RefreshWeaponsGrid()
		RefreshCosmeticsGrid()
	end

	function Obj:Destroy()
		if keyConn then keyConn:Disconnect() end
		Gui:Destroy()
	end

	Obj.Outer = Outer
	Obj.Gui = Gui
	Library._CosmeticsWindow = Obj
	return Obj
end
end

pcall(function()
    if type(getgenv) ~= 'function' then
        return
    end
    local okEnv, env = pcall(getgenv)
    if okEnv and type(env) == 'table' then
        env.Library = Library
        if type(Library.Toggles) == 'table' then
            env.Toggles = Library.Toggles
        end
        if type(Library.Options) == 'table' then
            env.Options = Library.Options
        end
    end
end)

Library.NotifyOnError = false
Library.ShowCustomCursor = false

do
    local OriginalNotify = rawget(Library, 'Notify')
    if type(OriginalNotify) == 'function' then
        Library.Notify = function(self, ...)
            __AkiraElevateIdentity()
            local args = table.pack(...)
            local text = args[1]
            local duration = args[2]
            if type(text) == 'table' then
                local info = text
                local title = info.Title or info.title
                local desc = info.Description or info.Text or info.text
                if title and desc then
                    text = tostring(title) .. '  ·  ' .. tostring(desc)
                else
                    text = tostring(desc or title or 'Notification')
                end
                duration = info.Time or info.Duration or duration
            elseif text ~= nil and type(text) ~= 'string' then
                text = tostring(text)
            end
            local ok, result = pcall(function()
                return OriginalNotify(self, text, duration)
            end)
            if ok then
                return result
            end
            return nil
        end
    end
end

do
    local Caps = __akira_genv.AkiraCaps
    if type(Caps) == 'table' then
        local NotifiedFeatures = {}
        Caps.gate = function(feature, ...)
            local missing = nil
            for _, name in ipairs({ ... }) do
                if not Caps.has(name) then
                    missing = missing and (missing .. ', ' .. name) or name
                end
            end
            if not missing then
                return true
            end
            if not NotifiedFeatures[feature] then
                NotifiedFeatures[feature] = true
                pcall(function()
                    Library:Notify({ Title = 'Executor Support', Description = feature .. ' won\'t work on this executor -- it doesn\'t have ' .. missing .. '.', Time = 8 })
                end)
            end
            return false
        end
    end
end

