            local function CreateFovDrawingGroup()
                local function SafeNew(kind)
                    local ok, obj = pcall(Drawing.new, kind)
                    if ok and obj then
                        return obj
                    end
                    return {
                        Visible = false,
                        Color = Color3.new(1, 1, 1),
                        Transparency = 1,
                        Thickness = 1,
                        Radius = 0,
                        Position = Vector2.zero,
                        Filled = false,
                        NumSides = 0,
                        Remove = function() end,
                        Destroy = function() end,
                    }
                end

                local group = {
                    Fill = SafeNew('Circle'),
                    Glow2 = SafeNew('Circle'),
                    Glow1 = SafeNew('Circle'),
                    Outline = SafeNew('Circle'),
                }
                group.Fill.Filled = true
                group.Fill.NumSides = 64
                group.Fill.Visible = false

                group.Glow2.Filled = false
                group.Glow2.NumSides = 64
                group.Glow2.Visible = false

                group.Glow1.Filled = false
                group.Glow1.NumSides = 64
                group.Glow1.Visible = false

                group.Outline.Filled = false
                group.Outline.NumSides = 64
                group.Outline.Thickness = 1.5
                group.Outline.Visible = false

                function group:EnsureGradientOverlay()
                    if self.GradientFill and self.Gradient and self.GradientFill.Parent then
                        return true
                    end

                    local parent = nil
                    if type(GetFovOverlayGui) == 'function' then
                        parent = GetFovOverlayGui()
                    end
                    if not (parent and parent.Parent) then
                        parent = Library and Library.ScreenGui
                    end
                    if not (parent and parent.Parent) then
                        return false
                    end

                    local fillFrame = Instance.new('Frame')
                    fillFrame.Name = 'AkiraFovGradientFill'
                    fillFrame.AnchorPoint = Vector2.new(0.5, 0.5)
                    fillFrame.BackgroundColor3 = Color3.new(1, 1, 1)
                    fillFrame.BackgroundTransparency = 0.75
                    fillFrame.BorderSizePixel = 0
                    fillFrame.Active = false
                    fillFrame.Selectable = false
                    fillFrame.ClipsDescendants = false
                    fillFrame.Position = UDim2.fromScale(0.5, 0.5)
                    fillFrame.Size = UDim2.fromOffset(0, 0)
                    fillFrame.Visible = false
                    fillFrame.ZIndex = 2
                    fillFrame.Parent = parent
                    local fillCorner = Instance.new('UICorner')
                    fillCorner.CornerRadius = UDim.new(1, 0)
                    fillCorner.Parent = fillFrame
                    local fillGradient = Instance.new('UIGradient')
                    fillGradient.Rotation = 45
                    fillGradient.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 80, 160)),
                        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 210, 70)),
                        ColorSequenceKeypoint.new(1, Color3.fromRGB(70, 170, 255)),
                    })
                    fillGradient.Parent = fillFrame

                    self.GradientFill = fillFrame
                    self.Gradient = fillGradient
                    self.CachedGradKey = nil
                    return true
                end

                function group:Hide()
                    self.Outline.Visible = false
                    self.Fill.Visible = false
                    self.Glow1.Visible = false
                    self.Glow2.Visible = false
                    if self.Outline then self.Outline._akiraLast = nil end
                    if self.Fill then self.Fill._akiraLast = nil end
                    if self.Glow1 then self.Glow1._akiraLast = nil end
                    if self.Glow2 then self.Glow2._akiraLast = nil end
                    if self.GradientFill then
                        self.GradientFill.Visible = false
                    end
                end

                function group:Destroy()
                    self:Hide()
                    pcall(function() self.Outline:Remove() end)
                    pcall(function() self.Fill:Remove() end)
                    pcall(function() self.Glow1:Remove() end)
                    pcall(function() self.Glow2:Remove() end)
                    pcall(function()
                        if self.GradientFill then
                            self.GradientFill:Destroy()
                        end
                    end)
                    self.GradientFill = nil
                    self.Gradient = nil
                end

                return group
            end

