                { 'HitboxHead', 'HitboxBody' },
            }

            local DrawingPool = {
                Line = {},
                Square = {},
                Circle = {},
                Text = {},
                Triangle = {},
            }

            local function SafeDrawing(kind)
                if DrawingLib and type(DrawingLib.New) == 'function' then
                    return DrawingLib.New(kind)
                end
                if not DrawingSupported then return nil end
                local pool = DrawingPool[kind]
                if pool and #pool > 0 then
                    local obj = table.remove(pool)
                    if obj then
                        pcall(function() obj.Visible = false end)
                        return obj
                    end
                end
                local ok, obj = pcall(Drawing.new, kind)
                if ok and obj then
                    pcall(function() obj.Visible = false end)
                    return obj
                end
                return nil
            end

            local function SafeDrawingRelease(obj, kind)
                if not obj or typeof(obj) == 'Instance' then return end
                pcall(function() obj.Visible = false end)
                if kind and DrawingPool[kind] then
                    table.insert(DrawingPool[kind], obj)
                else
                    if DrawingLib and type(DrawingLib.Release) == 'function' then
                        DrawingLib.Release(obj)
                    elseif type(obj.Remove) == 'function' then
                        pcall(function() obj:Remove() end)
                    end
                end
            end

            local function SafeDrawingDestroy(obj)
                if obj and typeof(obj) ~= 'Instance' and type(obj.Remove) == 'function' then
                    pcall(function() obj:Remove() end)
                end
            end

            local function CreatePlayerEspEntry(targetPlayer)
                if ESPObjects[targetPlayer] then return end

                local highlight = Instance.new('Highlight')
                highlight.Name = 'AkiraEspHighlight'
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.FillTransparency = 0.5
                highlight.OutlineTransparency = 0
                highlight.Enabled = false
                pcall(function()
                    highlight.Parent = HighlightContainer
                end)

                local boxOutline = SafeDrawing('Square')
                if boxOutline then
                    boxOutline.Thickness = 2
                    boxOutline.Filled = false
                    boxOutline.Color = Color3.new(0, 0, 0)
                    boxOutline.Visible = false
                end

                local boxMain = SafeDrawing('Square')
                if boxMain then
                    boxMain.Thickness = 1
                    boxMain.Filled = false
                    boxMain.Color = Color3.fromRGB(0, 255, 100)
                    boxMain.Visible = false
                end

                local cornerLines = {}
                for i = 1, 8 do
                    local l = SafeDrawing('Line')
                    if l then
                        l.Thickness = 1
                        l.Color = Color3.fromRGB(0, 255, 100)
                        l.Visible = false
                        table.insert(cornerLines, l)
                    end
                end

                local skeletonLines = {}

                local nameText = SafeDrawing('Text')
                if nameText then
                    nameText.Center = true
                    nameText.Outline = true
                    nameText.Size = 14
                    nameText.Color = Color3.fromRGB(255, 255, 255)
                    nameText.Visible = false
                end

                local healthBarBg = SafeDrawing('Square')
                if healthBarBg then
                    healthBarBg.Thickness = 1
                    healthBarBg.Filled = true
                    healthBarBg.Color = Color3.fromRGB(20, 20, 20)
                    healthBarBg.Visible = false
                end

                local healthBarFill = SafeDrawing('Square')
                if healthBarFill then
                    healthBarFill.Thickness = 1
                    healthBarFill.Filled = true
                    healthBarFill.Color = Color3.fromRGB(0, 255, 0)
                    healthBarFill.Visible = false
                end

                local healthText = SafeDrawing('Text')
                if healthText then
                    healthText.Center = false
                    healthText.Outline = true
                    healthText.Size = 12
                    healthText.Color = Color3.fromRGB(255, 255, 255)
                    healthText.Visible = false
                end

                local weaponText = SafeDrawing('Text')
                if weaponText then
                    weaponText.Center = true
                    weaponText.Outline = true
                    weaponText.Size = 13
                    weaponText.Color = Color3.fromRGB(220, 220, 220)
                    weaponText.Visible = false
                end

                local ammoText = SafeDrawing('Text')
                if ammoText then
                    ammoText.Center = true
                    ammoText.Outline = true
                    ammoText.Size = 12
                    ammoText.Color = Color3.fromRGB(200, 200, 200)
                    ammoText.Visible = false
                end

                local distanceText = SafeDrawing('Text')
                if distanceText then
                    distanceText.Center = true
                    distanceText.Outline = true
                    distanceText.Size = 12
                    distanceText.Color = Color3.fromRGB(200, 200, 200)
                    distanceText.Visible = false
                end

                local lookLine = SafeDrawing('Line')
                if lookLine then
                    lookLine.Thickness = 1.5
                    lookLine.Color = Color3.fromRGB(255, 255, 0)
                    lookLine.Visible = false
                end

                local snapline = SafeDrawing('Line')
                if snapline then
                    snapline.Thickness = 1
                    snapline.Color = Color3.fromRGB(255, 255, 255)
                    snapline.Visible = false
                end

                local headDot = SafeDrawing('Circle')
                if headDot then
                    headDot.Radius = 3
                    headDot.Filled = true
                    headDot.Color = Color3.fromRGB(255, 255, 255)
                    headDot.Visible = false
                end

                local arrow1 = SafeDrawing('Line')
                local arrow2 = SafeDrawing('Line')
                local arrow3 = SafeDrawing('Line')
                for _, a in ipairs({arrow1, arrow2, arrow3}) do
                    if a then
                        a.Thickness = 2
                        a.Color = Color3.fromRGB(0, 255, 100)
                        a.Visible = false
                    end
                end

                ESPObjects[targetPlayer] = {
                    Highlight = highlight,
                    BoxOutline = boxOutline,
                    BoxMain = boxMain,
                    CornerLines = cornerLines,
                    SkeletonLines = skeletonLines,
                    NameText = nameText,
                    HealthBarBg = healthBarBg,
                    HealthBarFill = healthBarFill,
                    HealthText = healthText,
                    WeaponText = weaponText,
                    AmmoText = ammoText,
                    DistanceText = distanceText,
                    LookLine = lookLine,
                    Snapline = snapline,
                    HeadDot = headDot,
                    Arrow1 = arrow1,
                    Arrow2 = arrow2,
                    Arrow3 = arrow3,
                    SmoothHp = 1,
                }
            end

            local function HidePlayerEsp(entry)
                if not entry or entry._allHidden then return end
                entry._allHidden = true
                entry._bodyHidden = true
                if entry.Highlight and entry.Highlight.Enabled then entry.Highlight.Enabled = false end
                if entry.BoxOutline and entry.BoxOutline.Visible then entry.BoxOutline.Visible = false end
                if entry.BoxMain and entry.BoxMain.Visible then entry.BoxMain.Visible = false end
                if entry.CornerLines then
                    for _, l in ipairs(entry.CornerLines) do if l.Visible then l.Visible = false end end
                end
                if entry.SkeletonLines then
                    for _, l in ipairs(entry.SkeletonLines) do if l.Visible then l.Visible = false end end
                end
                if entry.NameText and entry.NameText.Visible then entry.NameText.Visible = false end
                if entry.HealthBarBg and entry.HealthBarBg.Visible then entry.HealthBarBg.Visible = false end
                if entry.HealthBarFill and entry.HealthBarFill.Visible then entry.HealthBarFill.Visible = false end
                if entry.HealthText and entry.HealthText.Visible then entry.HealthText.Visible = false end
                if entry.WeaponText and entry.WeaponText.Visible then entry.WeaponText.Visible = false end
                if entry.AmmoText and entry.AmmoText.Visible then entry.AmmoText.Visible = false end
                if entry.DistanceText and entry.DistanceText.Visible then entry.DistanceText.Visible = false end
                if entry.LookLine and entry.LookLine.Visible then entry.LookLine.Visible = false end
                if entry.Snapline and entry.Snapline.Visible then entry.Snapline.Visible = false end
                if entry.HeadDot and entry.HeadDot.Visible then entry.HeadDot.Visible = false end
                if entry.Arrow1 and entry.Arrow1.Visible then entry.Arrow1.Visible = false end
                if entry.Arrow2 and entry.Arrow2.Visible then entry.Arrow2.Visible = false end
                if entry.Arrow3 and entry.Arrow3.Visible then entry.Arrow3.Visible = false end
            end

            local function DestroyPlayerEsp(targetPlayer)
                local entry = ESPObjects[targetPlayer]
                if not entry then return end
                HidePlayerEsp(entry)
                if entry.Highlight then pcall(function() entry.Highlight:Destroy() end) end
                SafeDrawingRelease(entry.BoxOutline, 'Square')
                SafeDrawingRelease(entry.BoxMain, 'Square')
                if entry.CornerLines then
                    for _, l in ipairs(entry.CornerLines) do SafeDrawingRelease(l, 'Line') end
                end
                if entry.SkeletonLines then
                    for _, l in ipairs(entry.SkeletonLines) do SafeDrawingRelease(l, 'Line') end
                end
                SafeDrawingRelease(entry.NameText, 'Text')
                SafeDrawingRelease(entry.HealthBarBg, 'Square')
                SafeDrawingRelease(entry.HealthBarFill, 'Square')
                SafeDrawingRelease(entry.HealthText, 'Text')
                SafeDrawingRelease(entry.WeaponText, 'Text')
                SafeDrawingRelease(entry.AmmoText, 'Text')
                SafeDrawingRelease(entry.DistanceText, 'Text')
                SafeDrawingRelease(entry.LookLine, 'Line')
                SafeDrawingRelease(entry.Snapline, 'Line')
                SafeDrawingRelease(entry.HeadDot, 'Circle')
                SafeDrawingRelease(entry.Arrow1, 'Line')
                SafeDrawingRelease(entry.Arrow2, 'Line')
                SafeDrawingRelease(entry.Arrow3, 'Line')
                entry.BBox = nil
                entry.BBoxFrame = nil
                ESPObjects[targetPlayer] = nil
            end

            local function CreateESP(player)
                return CreatePlayerEspEntry(player)
            end

            local function DestroyESP(player)
                return DestroyPlayerEsp(player)
            end

            local function DestroyAllESP()
                for p in pairs(ESPObjects) do
                    DestroyPlayerEsp(p)
                end
            end

            local function HideESP(entry)
                return HidePlayerEsp(entry)
            end

            Players.PlayerRemoving:Connect(DestroyPlayerEsp)

            local function GetPlayerEquippedWeapon(character)
                if not character then return "" end
                local tool = character:FindFirstChildOfClass("Tool")
                if tool then return tool.Name end
                local eq = character:FindFirstChild("EquippedItem")
                if eq and eq.Value then return tostring(eq.Value) end
                local attr = character:GetAttribute("EquippedWeapon")
                if attr then return tostring(attr) end
                return ""
            end

            local function IsTeammate(player)
                if not player or player == LP then return true end
                local myTeamId = LP:GetAttribute('TeamID') or LP:GetAttribute('Team')
                local theirTeamId = player:GetAttribute('TeamID') or player:GetAttribute('Team')
                if myTeamId and theirTeamId and myTeamId ~= '' and theirTeamId ~= '' then
                    return myTeamId == theirTeamId
                end
                if LP.Team and player.Team and LP.Team == player.Team then
                    return true
                end
                return false
            end

            local function ShouldShow(player, showTeammates)
                if not player or player == LP then return false end
                if showTeammates then return true end
                return not IsTeammate(player)
            end

            local function IsPlayerInLocalEnvironment(player)
                if not player or player == LP or not IsUnder(player, Players) then
                    return false
                end
                local character = player.Character
                if not character or not character.Parent then
                    return false
                end
                return true
            end

            local function ReconcileESPPlayers()
                for p in pairs(ESPObjects) do
                    if not p or not IsUnder(p, Players) then
                        DestroyPlayerEsp(p)
                    end
                end
                local created = 0
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP and IsUnder(p, Players) and not ESPObjects[p] then
                        CreatePlayerEspEntry(p)
                        created = created + 1
                        if created >= 6 then
                            break
                        end
                    end
                end
            end

            local function IsRivalsPickupPlace()
                return type(CurrentRivalsPlace) == 'number' and (
                    CurrentRivalsPlace == RIVALS_SHARED_MATCH_PLACE
                    or CurrentRivalsPlace == 71874690745115
                    or CurrentRivalsPlace == 133215910299950
                )
            end

            local function ResolveRivalsDataRemote(remoteName, expectedClass)
                expectedClass = expectedClass or 'RemoteEvent'
                local remotesFolder = ReplicatedStorage:FindFirstChild('Remotes')
                local dataFolder = remotesFolder and remotesFolder:FindFirstChild('Data')
                local remote = dataFolder and dataFolder:FindFirstChild(remoteName)
                if remote and remote:IsA(expectedClass) then
                    return remote
                end

                return nil
            end

            local function GetRivalsPickupTouchPart()
                if not InitCharacter() or not Char or not HumanoidRootPart then
                    return nil
                end

                return Char:FindFirstChild('HitboxBody')
                    or HumanoidRootPart
                    or Char:FindFirstChildWhichIsA('BasePart')
            end

            local function GetRivalsPickupKind(drop)
                if not drop or not drop:IsA('BasePart') or drop.Name ~= '_drop' then
                    return nil
                end

                if drop:FindFirstChild('Health') then
                    return 'Health'
                end

                if drop:FindFirstChild('AmmoBalanced') or drop:FindFirstChild('Ammo') then
                    return 'Ammo'
                end

                return nil
            end

            local function IsRivalsSpawnShieldActive(character)
                if not character or not character.Parent then
                    return false
                end

                local player = Players:GetPlayerFromCharacter(character)
                local fighter = player and TrackedFightersByPlayer[player]

                if not fighter then
                    local fighterController = ResolveFighterController()
                    if fighterController and type(fighterController.GetFighter) == 'function' then
                        fighter = player and fighterController:GetFighter(player) or nil
                        if not fighter then
                            fighter = fighterController:GetFighter(character)
                        end
                    end
                end

                if not fighter then
                    return false
                end

                return FighterDataCache.ReadEntity(fighter.Entity)
            end

            local function TouchRivalsPickupDrop(drop, touchPart)
                if not drop or not drop.Parent or not touchPart or not touchPart.Parent then
                    return false
                end

                firetouchinterest(touchPart, drop, 0)
                task.defer(function()
                    if drop.Parent and touchPart.Parent then
                        firetouchinterest(touchPart, drop, 1)
                    end
                end)
                return true
            end

            local LocalPickupObserver = {
                RetryActive = false,
                RetryDelay = 0.05,
                RetryNonce = 0,
            }

            ;(function() LPH_ATTRIBUTES(VM(NONE))
                local pickupDropsByKind = {
                    Health = {},
                    Ammo = {},
                }
                local pickupDropObservers = {}

                local function ClearPickupDropKinds(drop)
                    if not drop then
                        return
                    end

                    pickupDropsByKind.Health[drop] = nil
                    pickupDropsByKind.Ammo[drop] = nil
                end

                local function DisconnectPickupDropObserver(drop)
                    local observer = pickupDropObservers[drop]
                    if not observer then
                        return
                    end

                    local childAddedConnection = observer.ChildAddedConnection
                    if childAddedConnection then
                        pcall(function()
                            childAddedConnection:Disconnect()
                        end)
                    end

                    local childRemovedConnection = observer.ChildRemovedConnection
                    if childRemovedConnection then
                        pcall(function()
                            childRemovedConnection:Disconnect()
                        end)
                    end

                    pickupDropObservers[drop] = nil
                end

                local function RefreshPickupDrop(drop)
                    ClearPickupDropKinds(drop)

                    if not drop or not IsUnder(drop, Workspace) or not drop:IsA('BasePart') or drop.Name ~= '_drop' then
                        return
                    end

                    local dropKind = GetRivalsPickupKind(drop)
                    local hasTouchInterest = drop:FindFirstChildOfClass('TouchTransmitter') ~= nil
                    if dropKind and hasTouchInterest then
                        pickupDropsByKind[dropKind][drop] = true
                        if UpdateRivalsPickupFeatures then
                            UpdateRivalsPickupFeatures()
                        end
                    end
                end

                function LocalPickupObserver.ObserveDrop(drop)
                    if not drop or not drop:IsA('BasePart') or drop.Name ~= '_drop' then
                        return
                    end

                    if pickupDropObservers[drop] then
                        RefreshPickupDrop(drop)
                        return
                    end

                    local observer = {}
                    pickupDropObservers[drop] = observer

                    observer.ChildAddedConnection = drop.ChildAdded:Connect(GuardRivalsCallback('PickupDrop_ChildAdded', function()
                        RefreshPickupDrop(drop)
                    end))
                    observer.ChildRemovedConnection = drop.ChildRemoved:Connect(GuardRivalsCallback('PickupDrop_ChildRemoved', function()
                        RefreshPickupDrop(drop)
                    end))

                    RefreshPickupDrop(drop)
                end

                function LocalPickupObserver.UnobserveDrop(drop)
                    ClearPickupDropKinds(drop)
                    DisconnectPickupDropObserver(drop)
                end

                function LocalPickupObserver.ResetDropTracking()
                    for drop in pairs(pickupDropObservers) do
                        DisconnectPickupDropObserver(drop)
                    end

                    for drop in pairs(pickupDropsByKind.Health) do
                        pickupDropsByKind.Health[drop] = nil
                    end

                    for drop in pairs(pickupDropsByKind.Ammo) do
                        pickupDropsByKind.Ammo[drop] = nil
                    end
                end

                function LocalPickupObserver.FindNearestDrop(pickupKind, touchPart)
                    if not IsRivalsPickupPlace() or not touchPart or not touchPart.Parent then
                        return nil
                    end

                    if pickupKind == 'Health' and (not Humanoid or Humanoid.Health >= Humanoid.MaxHealth) then
                        return nil
                    end

                    local nearestDrop = nil
                    local nearestDistance = nil
                    local candidateDrops = pickupDropsByKind[pickupKind]

                    if not candidateDrops then
                        return nil
                    end

                    for drop in pairs(candidateDrops) do
                        if not IsUnder(drop, Workspace) then
                            ClearPickupDropKinds(drop)
                            DisconnectPickupDropObserver(drop)
                        else
                            local dropKind = GetRivalsPickupKind(drop)
                            local hasTouchInterest = drop:FindFirstChildOfClass('TouchTransmitter') ~= nil
                            if dropKind == pickupKind and drop.CanTouch == true and hasTouchInterest then
                                local distance = (drop.Position - touchPart.Position).Magnitude
                                if not nearestDistance or distance < nearestDistance then
                                    nearestDrop = drop
                                    nearestDistance = distance
                                end
                            end
                        end
                    end

                    return nearestDrop
                end
            end)()

            function LocalPickupObserver.CancelRetry()
                LocalPickupObserver.RetryActive = false
                LocalPickupObserver.RetryNonce = LocalPickupObserver.RetryNonce + 1
            end

            function LocalPickupObserver.SyncRetry(shouldRetry)
                if not shouldRetry then
                    LocalPickupObserver.CancelRetry()
                    return
                end

                if LocalPickupObserver.RetryActive then
                    return
                end

                LocalPickupObserver.RetryActive = true
                LocalPickupObserver.RetryNonce = LocalPickupObserver.RetryNonce + 1
                local retryNonce = LocalPickupObserver.RetryNonce

                task.spawn(GuardRivalsCallback('Pickup_Retry', function()
                    while LocalPickupObserver.RetryActive and LocalPickupObserver.RetryNonce == retryNonce do
                        task.wait(LocalPickupObserver.RetryDelay)
                        if LocalPickupObserver.RetryNonce ~= retryNonce or not LocalPickupObserver.RetryActive then
                            return
                        end

                        if not UpdateRivalsPickupFeatures or not UpdateRivalsPickupFeatures() then
                            LocalPickupObserver.RetryActive = false
                            return
                        end
                    end
                end))
            end

            UpdateRivalsPickupFeatures = function()
                if not __akira_genv.AkiraCaps.gate('Auto Pickup', 'firetouchinterest') then
                    LocalPickupObserver.CancelRetry()
                    return false
                end
                if not IsRivalsPickupPlace() or not InitCharacter() or not Humanoid or Humanoid.Health <= 0 then
                    LocalPickupObserver.CancelRetry()
                    return false
                end

                local touchPart = GetRivalsPickupTouchPart()
                if not touchPart then
                    LocalPickupObserver.CancelRetry()
                    return false
                end

                local touchedDrop = false
                local shouldRetry = false
                local missingHealth = math.max(Humanoid.MaxHealth - Humanoid.Health, 0)

                if Toggles.P8S1T1 and Toggles.P8S1T1.Value and missingHealth >= 25 then
                    shouldRetry = true
                    local healthDrop = LocalPickupObserver.FindNearestDrop('Health', touchPart)
                    if healthDrop then
                        touchedDrop = TouchRivalsPickupDrop(healthDrop, touchPart)
                    end
                end

                local fighter = ResolveLocalFighter()
                local item = fighter and fighter.EquippedItem or nil
                local ammo = ReadItemValue(item, 'Ammo')
                if not touchedDrop and Toggles.P8S1T2 and Toggles.P8S1T2.Value and type(ammo) == 'number' and ammo <= 0 then
                    shouldRetry = true
                    local ammoDrop = LocalPickupObserver.FindNearestDrop('Ammo', touchPart)
                    if ammoDrop then
                        TouchRivalsPickupDrop(ammoDrop, touchPart)
                    end
                end

                LocalPickupObserver.SyncRetry(shouldRetry)
                return shouldRetry
            end

            local function RefreshLocalPickupHealthObserver()
                if not IsRivalsPickupPlace() or not InitCharacter() or not Humanoid then
                    DisconnectWeaponInfoConnection(LocalPickupObserver, 'HealthChanged')
                    return
                end

                ConnectWeaponInfoSignal(Humanoid.HealthChanged, LocalPickupObserver, 'HealthChanged', function()
                    local missingHealth = math.max(Humanoid.MaxHealth - Humanoid.Health, 0)
                    if missingHealth >= 25 then
                        UpdateRivalsPickupFeatures()
                    end
                end)
            end

            local function IsRivalsModToggleEnabled(toggleId)
                LPH_ATTRIBUTES(VM(NONE))
                local toggle = Toggles[toggleId]
                if toggle ~= nil then
                    if toggle.Value == true then
                        return true
                    end
                    if type(toggle.Get) == 'function' then
                        local ok, value = pcall(toggle.Get, toggle)
                        if ok and value == true then
                            return true
                        end
                    end
                end
                local flags = Library and rawget(Library, 'Flags')
                return type(flags) == 'table' and flags[toggleId] == true
            end

            local ResolveRivalsWeaponSpeedScale
            ;(function() LPH_ATTRIBUTES(VM(NONE))

            local function ReadRivalsModNumber(optionId, fallback)
                LPH_ATTRIBUTES(VM(NONE))
                local option = Options[optionId]
                if option ~= nil then
                    if type(option.Value) == 'number' then
                        return option.Value
                    end
                    if type(option.Get) == 'function' then
                        local ok, value = pcall(option.Get, option)
                        if ok and type(value) == 'number' then
                            return value
                        end
                    end
                end
                local flags = Library and rawget(Library, 'Flags')
                if type(flags) == 'table' and type(flags[optionId]) == 'number' then
                    return flags[optionId]
                end
                return fallback
            end

