            function RivalsModsState.AkiraLocalFighterState:GetItems()
                local fighter = ResolveLocalFighter()
                local items = type(fighter) == 'table' and rawget(fighter, 'Items') or nil
                if type(items) == 'table' then
                    return items
                end
                return {}
            end

            function RivalsModsState.AkiraLocalFighterState:GetItemById(objectId)
                for _, item in next, self:GetItems() do
                    if objectId == rawget(rawget(item, 'Data'), 'ObjectID') then
                        return item
                    end
                end
                return nil
            end

            function RivalsModsState.ResolveNoSpreadClientItem()
                local state = RivalsModsState
                if state.NoSpreadClientItem then
                    return state.NoSpreadClientItem
                end

                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local replicated = modules and modules:FindFirstChild('ClientReplicatedClasses')
                local fighter = replicated and replicated:FindFirstChild('ClientFighter')
                local clientItemModule = fighter and fighter:FindFirstChild('ClientItem')
                if not clientItemModule then
                    return nil
                end

                local ok, clientItem = pcall(require, clientItemModule)
                if not ok or type(clientItem) ~= 'table' then
                    return nil
                end

                state.NoSpreadClientItem = clientItem
                return clientItem
            end

            function RivalsModsState.ResolveNoSpreadRemote()
                local state = RivalsModsState
                if state.NoSpreadRemote then
                    return state.NoSpreadRemote
                end

                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                local replication = remotes and remotes:FindFirstChild('Replication')
                local fighter = replication and replication:FindFirstChild('Fighter')
                local remote = fighter and fighter:FindFirstChild('UseItem')
                if not remote or not remote:IsA('RemoteEvent') then
                    return nil
                end

                state.NoSpreadRemote = cloneref(remote)
                return state.NoSpreadRemote
            end

            function RivalsModsState.EnsureAkiraInputHook()
                local state = RivalsModsState
                __akira_boot_log('RuntimeA: IH clientItem resolve...')
                if state.AkiraInputHook and state.NoSpreadController and state.GrenadeFuseController then
                    return true
                end
                if type(setrawmetatable) ~= 'function'
                    or type(clonefunction) ~= 'function'
                    or type(debug.getupvalues) ~= 'function'
                    or type(debug.setupvalue) ~= 'function' then
                    return false
                end

                local clientItem = RivalsModsState.ResolveNoSpreadClientItem()
                __akira_boot_log('RuntimeA: IH remote resolve...')
                local remote = RivalsModsState.ResolveNoSpreadRemote()
                __akira_boot_log('RuntimeA: IH enum resolve...')
                local enumLibrary = ResolveEnumLibrary()
                local fromEnum = type(enumLibrary) == 'table' and rawget(enumLibrary, '_from_enum') or nil
                if type(clientItem) ~= 'table' or not remote or type(fromEnum) ~= 'table' then
                    return false
                end

                local playerContext = {
                    inner = {
                        fighterState = RivalsModsState.AkiraLocalFighterState.new(),
                    },
                }

                __akira_boot_log('RuntimeA: IH prototype create...')
                local ok, inputHookOrError = pcall(function()
                    local inputHookPrototype = state.AkiraInputHookPrototype
                    if inputHookPrototype == nil then
                        inputHookPrototype = RivalsModsState.CreateAkiraInputHookPrototype(
                            clientItem,
                            remote,
                            function(encodedType)
                                return rawget(fromEnum, encodedType)
                            end
                        )
                        state.AkiraInputHookPrototype = inputHookPrototype
                    end
                    local inputHook = inputHookPrototype.new()
                    state.AkiraInputHook = inputHook
                    state.NoSpreadPlayerContext = playerContext
                    __akira_boot_log('RuntimeA: IH controllers...')
                    local noSpread = RivalsModsState.AkiraNoSpreadPrototype.new(
                        inputHook:Reserve(),
                        playerContext
                    )
                    state.NoSpreadController = noSpread
                    local grenade = RivalsModsState.AkiraGrenadeFusePrototype.new(
                        inputHook:Reserve(),
                        playerContext
                    )
                    state.GrenadeFuseController = grenade
                    __akira_boot_log('RuntimeA: IH controllers done')
                    return inputHook
                end)
                __akira_boot_log('RuntimeA: IH done (' .. tostring(ok) .. ')')
                if not ok then
                    ReportRivalsRuntimeIssue('mods_no_spread_input_hook_initialize', inputHookOrError)
                    return false
                end
                return inputHookOrError ~= nil
            end

            function RivalsModsState.SyncNoSpreadEnabled()
                local state = RivalsModsState
                local controller = state.NoSpreadController
                if not controller then
                    return false
                end
                local enabled = IsRivalsModToggleEnabled('P4S1T3')
                if controller._inputBinding.enabled ~= enabled then
                    controller:SetEnabled(enabled)
                end
                return true
            end

            function RivalsModsState.SyncGrenadeFuse()
                local state = RivalsModsState
                local controller = state.GrenadeFuseController
                if not controller then
                    return false
                end
                local enabled = IsRivalsModToggleEnabled('P4S1T6')
                local explodeOn = Options and Options.P4S1D1 and Options.P4S1D1.Value
                controller:SetExplodeOn(type(explodeOn) == 'string' and explodeOn or 'Impact')
                controller:SetRemoveFuse(IsRivalsModToggleEnabled('P4S1T7'))
                if controller._inputBinding.enabled ~= enabled then
                    controller:SetEnabled(enabled)
                end
                return true
            end

            function RivalsModsState.RestoreAkiraInputHook()
                local state = RivalsModsState
                if state.NoSpreadController then
                    state.NoSpreadController:Destroy()
                end
                if state.GrenadeFuseController then
                    state.GrenadeFuseController:Destroy()
                end
                if state.AkiraInputHook then
                    state.AkiraInputHook:Destroy()
                end
                state.NoSpreadController = nil
                state.GrenadeFuseController = nil
                state.NoSpreadPlayerContext = nil
                state.AkiraInputHook = nil
                state.NoSpreadClientItem = nil
                state.NoSpreadRemote = nil
            end

            function RivalsModsState.StoreOriginalItemInfo(item)
                local state = RivalsModsState
                if type(item) ~= 'table' or state.OriginalItemInfo[item] ~= nil then
                    return
                end

                local info = item.Info
                if type(info) ~= 'table' then
                    return
                end

                local inputSpammingEnabled = rawget(info, 'InputSpammingEnabled')
                state.OriginalItemInfo[item] = {
                    Info = info,
                    HasDashCooldown = rawget(info, 'DashCooldown') ~= nil,
                    DashCooldown = rawget(info, 'DashCooldown'),
                    HasMaxDoubleJumps = rawget(info, 'MaxDoubleJumps') ~= nil,
                    MaxDoubleJumps = rawget(info, 'MaxDoubleJumps'),
                    HasReloadLength = rawget(info, 'ReloadLength') ~= nil,
                    ReloadLength = rawget(info, 'ReloadLength'),
                    HasChargeTime = rawget(info, 'ChargeTime') ~= nil,
                    ChargeTime = rawget(info, 'ChargeTime'),
                    HasInputSpammingEnabled = inputSpammingEnabled ~= nil,
                    InputSpammingEnabled = type(inputSpammingEnabled) == 'table'
                        and AkiraClone(inputSpammingEnabled)
                        or inputSpammingEnabled,
                }
            end

            function RivalsModsState.ApplyPersistentItemModifiers(item)
                RivalsModsState.StoreOriginalItemInfo(item)

                local original = RivalsModsState.OriginalItemInfo[item]
                local info = original and original.Info or nil
                if type(info) ~= 'table' then
                    return
                end

                if IsRivalsModToggleEnabled('P4S2T4') then
                    local inputSpammingEnabled = original.InputSpammingEnabled
                    if type(inputSpammingEnabled) == 'table' then
                        local automaticInputSpamming = AkiraClone(inputSpammingEnabled)
                        automaticInputSpamming.StartShooting = 0
                        automaticInputSpamming.StartReloading = 0
                        rawset(info, 'InputSpammingEnabled', automaticInputSpamming)
                    end
                elseif original.HasInputSpammingEnabled then
                    rawset(info, 'InputSpammingEnabled', type(original.InputSpammingEnabled) == 'table'
                        and AkiraClone(original.InputSpammingEnabled)
                        or original.InputSpammingEnabled)
                else
                    rawset(info, 'InputSpammingEnabled', nil)
                end

                if IsRivalsModToggleEnabled('P4S2T5') then
                    rawset(info, 'MaxDoubleJumps', 676767)
                elseif original.HasMaxDoubleJumps then
                    rawset(info, 'MaxDoubleJumps', original.MaxDoubleJumps)
                else
                    rawset(info, 'MaxDoubleJumps', nil)
                end

                if IsRivalsModToggleEnabled('P4S1T5') and type(original.DashCooldown) == 'number' then
                    local reduction = math.clamp(ReadRivalsModNumber('P4S1S5', 75), 0, 100) / 100
                    rawset(info, 'DashCooldown', original.DashCooldown * (1 - reduction))
                elseif original.HasDashCooldown then
                    rawset(info, 'DashCooldown', original.DashCooldown)
                else
                    rawset(info, 'DashCooldown', nil)
                end

                if IsRivalsModToggleEnabled('P4S1_ProjRapidFire') then
                    local name = tostring(item and (item.Name or (rawget(item, 'ItemData') and item.ItemData.Name)) or '')
                    if name == 'Bow' or name == 'Slingshot' or name == 'Daggers' then
                        rawset(info, 'ReloadLength', name == 'Daggers' and 0.08 or 0)
                    end
                elseif original.HasReloadLength then
                    rawset(info, 'ReloadLength', original.ReloadLength)
                else
                    rawset(info, 'ReloadLength', nil)
                end

                if IsRivalsModToggleEnabled('P4S1_BowInstantDraw') then
                    local name = tostring(item and (item.Name or (rawget(item, 'ItemData') and item.ItemData.Name)) or '')
                    if name == 'Bow' then
                        rawset(info, 'ChargeTime', 0)
                    end
                elseif original.HasChargeTime then
                    rawset(info, 'ChargeTime', original.ChargeTime)
                else
                    rawset(info, 'ChargeTime', nil)
                end
            end

            function RivalsModsState.RestorePersistentItem(item)
                local state = RivalsModsState
                local original = state.OriginalItemInfo[item]
                local info = original and original.Info or nil
                if type(info) == 'table' then
                    if original.HasInputSpammingEnabled then
                        rawset(info, 'InputSpammingEnabled', type(original.InputSpammingEnabled) == 'table'
                            and AkiraClone(original.InputSpammingEnabled)
                            or original.InputSpammingEnabled)
                    else
                        rawset(info, 'InputSpammingEnabled', nil)
                    end

                    if original.HasMaxDoubleJumps then
                        rawset(info, 'MaxDoubleJumps', original.MaxDoubleJumps)
                    else
                        rawset(info, 'MaxDoubleJumps', nil)
                    end

                    if original.HasDashCooldown then
                        rawset(info, 'DashCooldown', original.DashCooldown)
                    else
                        rawset(info, 'DashCooldown', nil)
                    end

                    if original.HasReloadLength then
                        rawset(info, 'ReloadLength', original.ReloadLength)
                    else
                        rawset(info, 'ReloadLength', nil)
                    end

                    if original.HasChargeTime then
                        rawset(info, 'ChargeTime', original.ChargeTime)
                    else
                        rawset(info, 'ChargeTime', nil)
                    end
                end

                state.OriginalItemInfo[item] = nil
            end

            function RivalsModsState.DisconnectPersistentItemSignals()
                local state = RivalsModsState
                for _, connectionName in ipairs({ 'InfoModifierItemAdded', 'InfoModifierItemRemoved' }) do
                    local connection = state[connectionName]
                    if connection then
                        pcall(function()
                            connection:Disconnect()
                        end)
                    end
                    state[connectionName] = nil
                end
                state.InfoModifierFighter = nil
            end

            function RivalsModsState.RestorePersistentItemModifiers(disconnectSignals)
                local state = RivalsModsState
                local trackedItems = {}
                for item in pairs(state.OriginalItemInfo) do
                    trackedItems[#trackedItems + 1] = item
                end
                for _, item in ipairs(trackedItems) do
                    RivalsModsState.RestorePersistentItem(item)
                end

                if disconnectSignals then
                    RivalsModsState.DisconnectPersistentItemSignals()
                end
            end

            function RivalsModsState.RefreshPersistentItemModifiers()
                local state = RivalsModsState
                local fighter = ResolveLocalFighter()
                if fighter ~= state.InfoModifierFighter then
                    RivalsModsState.RestorePersistentItemModifiers(true)
                    state.InfoModifierFighter = fighter
                    if fighter then
                        if fighter.ItemAdded and type(fighter.ItemAdded.Connect) == 'function' then
                            state.InfoModifierItemAdded = fighter.ItemAdded:Connect(GuardRivalsCallback('Mods_ItemAdded', function(item)
                                RivalsModsState.ApplyPersistentItemModifiers(item)
                            end))
                        end
                        if fighter.ItemRemoved and type(fighter.ItemRemoved.Connect) == 'function' then
                            state.InfoModifierItemRemoved = fighter.ItemRemoved:Connect(GuardRivalsCallback('Mods_ItemRemoved', function(item)
                                RivalsModsState.RestorePersistentItem(item)
                            end))
                        end
                    end
                end

                if not fighter or type(fighter.Items) ~= 'table' then
                    return false
                end

                for _, item in pairs(fighter.Items) do
                    RivalsModsState.ApplyPersistentItemModifiers(item)
                end
                return true
            end

            function RivalsModsState.ResolveCameraController()
                local state = RivalsModsState
                if state.CameraController then
                    return state.CameraController
                end

                if type(__AkiraElevateIdentity) == 'function' then
                    pcall(__AkiraElevateIdentity)
                end

                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local cameraControllerModule = controllers and controllers:FindFirstChild('CameraController')
                if not cameraControllerModule then
                    return nil
                end

                local ok, cameraController = pcall(require, cameraControllerModule)
                if not ok or type(cameraController) ~= 'table' then
                    return nil
                end

                state.CameraController = cameraController
                return cameraController
            end

            function RivalsModsState.FreezeSpring(spring, fallback)
                if spring == nil then
                    return
                end

                local function get(key)
                    local ok, value = pcall(function()
                        return spring[key]
                    end)
                    if ok then
                        return value
                    end
                    return nil
                end

                local function set(key, value)
                    if value == nil then
                        return false
                    end
                    return pcall(function()
                        spring[key] = value
                    end)
                end

                local current = get('Value')
                if current == nil then
                    current = get('Position')
                end
                local valueType = typeof(current)
                if valueType ~= 'number' and valueType ~= 'Vector2' and valueType ~= 'Vector3' then
                    return
                end
                local value = fallback
                if valueType == 'Vector2' then
                    value = Vector2.zero
                elseif valueType == 'Vector3' then
                    value = Vector3.zero
                else
                    value = 0
                end

                if not set('Value', value) then
                    set('Position', value)
                end
                if get('Target') ~= nil then
                    set('Target', value)
                elseif get('Goal') ~= nil then
                    set('Goal', value)
                end
                pcall(function()
                    if type(spring.SetGoal) == 'function' then
                        spring:SetGoal(value)
                    elseif type(spring.setGoal) == 'function' then
                        spring:setGoal(value)
                    end
                end)

                local velocity = get('Velocity')
                local velocityType = typeof(velocity)
                if velocityType == 'number' then
                    set('Velocity', 0)
                elseif velocityType == 'Vector2' then
                    set('Velocity', Vector2.zero)
                elseif velocityType == 'Vector3' then
                    set('Velocity', Vector3.zero)
                elseif velocityType == 'CFrame' then
                    set('Velocity', CFrame.identity)
                else
                    pcall(function()
                        spring.Velocity = 0
                    end)
                end
            end

            function RivalsModsState.ApplyCameraMotionSuppression(cameraController)
                if not cameraController or not IsRivalsModToggleEnabled('P1S31T1') then
                    return
                end
                if IsRivalsModToggleEnabled('P4S2T8') then
                    return
                end
                pcall(function()
                    cameraController._bobbing_tick = 0
                end)
                pcall(RivalsModsState.FreezeSpring, cameraController._sway_spring, Vector2.zero)
                pcall(RivalsModsState.FreezeSpring, cameraController._bobbing_speed_spring, 0)
                pcall(RivalsModsState.FreezeSpring, cameraController._bobbing_value_spring, 0)
                pcall(RivalsModsState.FreezeSpring, cameraController._leaning_spring, 0)
                pcall(RivalsModsState.FreezeSpring, cameraController._jump_spring, 0)
                pcall(RivalsModsState.FreezeSpring, cameraController._sliding_spring, 0)
            end

            local function IsThirdPersonPov(cameraState)
                if type(cameraState) ~= 'table' then
                    return false
                end
                local states = cameraState.States
                local pov = cameraState._pov_state
                if type(states) ~= 'table' then
                    return false
                end
                return pov == states.ThirdPerson
                    or pov == states.ThirdPersonMirrored
                    or pov == states.ThirdPersonUnlockedMouse
            end

            function RivalsModsState.RevertThirdPersonOverrideHook()
                local restore = RivalsModsState.ThirdPersonOverrideRestore
                RivalsModsState.ThirdPersonOverrideRestore = nil
                if type(restore) ~= 'table' or not restore.controller then
                    return
                end
                if type(restore.original) == 'function' then
                    restore.controller.SetThirdPersonOverride = restore.original
                end
            end

            function RivalsModsState.EnsureThirdPersonOverrideHook(cameraController)
                cameraController = cameraController or RivalsModsState.ResolveCameraController()
                if not cameraController or type(cameraController.SetThirdPersonOverride) ~= 'function' then
                    return cameraController
                end
                local restore = RivalsModsState.ThirdPersonOverrideRestore
                if type(restore) == 'table' and restore.controller == cameraController then
                    return cameraController
                end
                if type(restore) == 'table' then
                    RivalsModsState.RevertThirdPersonOverrideHook()
                end
                local original = cameraController.SetThirdPersonOverride
                RivalsModsState.ThirdPersonOverrideRestore = {
                    controller = cameraController,
                    original = original,
                }
                cameraController.SetThirdPersonOverride = function(self, enabled)
                    if IsRivalsModToggleEnabled('P4S2T8') then
                        enabled = true
                    end
                    return original(self, enabled)
                end
                return cameraController
            end

            function RivalsModsState.EnsureThirdPersonActiveListener(cameraController)
                cameraController = cameraController or RivalsModsState.ResolveCameraController()
                if not cameraController then
                    return
                end
                local restore = RivalsModsState.ThirdPersonActiveRestore
                if type(restore) == 'table' and restore.controller == cameraController then
                    return
                end
                if type(restore) == 'table' and restore.connection then
                    pcall(function()
                        restore.connection:Disconnect()
                    end)
                end
                RivalsModsState.ThirdPersonActiveRestore = nil
                if typeof(cameraController.ActiveStateChanged) ~= 'RBXScriptSignal'
                    and type(cameraController.ActiveStateChanged) ~= 'table' then
                    return
                end
                local ok, connection = pcall(function()
                    return cameraController.ActiveStateChanged:Connect(function(newState)
                        if newState and IsRivalsModToggleEnabled('P4S2T8') then
                            pcall(RivalsModsState.SetThirdPersonEnabled, nil, true)
                        end
                    end)
                end)
                if ok and connection then
                    RivalsModsState.ThirdPersonActiveRestore = {
                        controller = cameraController,
                        connection = connection,
                    }
                end
            end

            function RivalsModsState.SetThirdPersonEnabled(_, enabled)
                enabled = enabled == true
                local cameraController
                if enabled then
                    cameraController = RivalsModsState.EnsureThirdPersonOverrideHook()
                    RivalsModsState.EnsureThirdPersonActiveListener(cameraController)
                else
                    cameraController = RivalsModsState.ResolveCameraController()
                end
                if not cameraController or type(cameraController.SetThirdPersonOverride) ~= 'function' then
                    return
                end
                pcall(function()
                    cameraController:SetThirdPersonOverride(enabled)
                end)
                local cameraState = cameraController.CameraState
                local states = type(cameraState) == 'table' and cameraState.States or nil
                if not enabled then
                    if type(states) == 'table' and type(cameraState._SetPOVState) == 'function' then
                        pcall(function()
                            cameraState:_SetPOVState(states.FirstPerson)
                        end)
                    end
                    return
                end
                if type(states) ~= 'table' or IsThirdPersonPov(cameraState) then
                    return
                end
                if type(cameraState.TogglePOV) == 'function' then
                    pcall(function()
                        if cameraState.GetPublicState and cameraState:GetPublicState() ~= states.ThirdPerson then
                            cameraState:TogglePOV()
                        end
                    end)
                elseif type(cameraState._SetPOVState) == 'function' then
                    pcall(function()
                        cameraState:_SetPOVState(states.ThirdPerson)
                    end)
                end
            end

            function RivalsModsState.ResolveUtilityModule()
                local state = RivalsModsState
                if state.UtilityModule then
                    return state.UtilityModule
                end

                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local utilityScript = modules and modules:FindFirstChild('Utility')
                if not utilityScript then
                    return nil
                end

                local ok, utility = pcall(require, utilityScript)
                if not ok or type(utility) ~= 'table' then
                    return nil
                end

                state.UtilityModule = utility
                return utility
            end

            function RivalsModsState.IsSilentV2Mode()
                return Options.P2S1_SilentMode and Options.P2S1_SilentMode.Value == 'Silent V2'
            end

            function RivalsModsState.ResolveSilentV2Destination()
                if not RivalsModsState.IsSilentV2Active() then
                    AimbotSilentState.RaycastDestination = nil
                    return nil
                end
                local dest = AimbotSilentState.RaycastDestination
                if typeof(dest) == 'Vector3' then
                    return dest
                end
                if type(RivalsRuntimeBridge.GetBestAimbotTarget) ~= 'function' then
                    return nil
                end
                local targetInfo = RivalsRuntimeBridge.GetBestAimbotTarget()
                if type(targetInfo) == 'table' and typeof(targetInfo.worldPosition) == 'Vector3' then
                    AimbotSilentState.RaycastDestination = targetInfo.worldPosition
                    AimbotSilentState.HookTarget = targetInfo
                    return targetInfo.worldPosition
                end
                return nil
            end

            function RivalsModsState.SilentV2HitchanceAllows(item)
                local hitchance = 100
                if Options.P2S1_HitChance and type(Options.P2S1_HitChance.Value) == 'number' then
                    hitchance = math.clamp(Options.P2S1_HitChance.Value, 0, 100)
                end
                if hitchance >= 99.5 then
                    return true
                end
                if hitchance <= 0 then
                    return false
                end
                local now = tick()
                local lastShot = item and rawget(item, '_last_shot')
                local windowKey = type(lastShot) == 'number' and lastShot or nil
                if type(windowKey) ~= 'number' then
                    local prevAt = AimbotSilentState.HitChanceAt
                    if type(prevAt) == 'number' and (now - prevAt) < 0.08 then
                        windowKey = AimbotSilentState.HitChanceKey
                    else
                        windowKey = now
                    end
                end
                if AimbotSilentState.HitChanceKey ~= windowKey then
                    AimbotSilentState.HitChanceKey = windowKey
                    AimbotSilentState.HitChanceAt = now
                    AimbotSilentState.HitChancePass = (math.random() * 100) <= hitchance
                end
                return AimbotSilentState.HitChancePass == true
            end

            function RivalsModsState.IsSilentV2Active()
                if not (Toggles.P2S1T1 and Toggles.P2S1T1.Value == true) then
                    return false
                end
                if Options.P2S1T1K and type(Options.P2S1T1K.GetState) == 'function' and not Options.P2S1T1K:GetState() then
                    return false
                end
                return true
            end

            function RivalsModsState.EnsureSilentV2RaycastHook()
                LPH_ATTRIBUTES(VM(NONE))
                local state = RivalsModsState
                if state.SilentV2RaycastHooked then
                    return true
                end
                if not (Toggles.P2S1T1 and Toggles.P2S1T1.Value == true) and not RivalsModsState.IsSilentV2Mode() then
                    return false
                end
                local now = os.clock()
                if type(state.SilentV2HookNextTry) == 'number' and now < state.SilentV2HookNextTry then
                    return false
                end

                local utility = RivalsModsState.ResolveUtilityModule()
                if type(utility) ~= 'table' then
                    state.SilentV2HookNextTry = now + 0.75
                    return false
                end

                local mt = getmetatable(utility)
                local index = type(mt) == 'table' and mt.__index or nil
                local original = nil
                if type(index) == 'table' and type(index.Raycast) == 'function' then
                    original = index.Raycast
                elseif type(utility.Raycast) == 'function' then
                    original = utility.Raycast
                end
                if type(original) ~= 'function' then
                    state.SilentV2HookNextTry = now + 0.75
                    return false
                end

                local invokeOriginal = original
                local hooked = function(...)
                    LPH_ATTRIBUTES(VM(NONE))
                    __akira_hook_enter('Utility.Raycast')
                    local a1, a2, a3, a4 = ...
                    local destIndex = nil
                    if (type(a1) == 'table' or typeof(a1) == 'userdata') and typeof(a2) == 'Vector3' and typeof(a3) == 'Vector3' then
                        destIndex = 3
                    elseif typeof(a1) == 'Vector3' and typeof(a2) == 'Vector3' then
                        destIndex = 2
                    end
                    if destIndex and RivalsModsState.IsSilentV2Active() then
                        local dest = RivalsModsState.ResolveSilentV2Destination()
                        if typeof(dest) == 'Vector3' then
                            local fighter = ResolveLocalFighter()
                            local item = fighter and fighter.EquippedItem or nil
                            if RivalsModsState.SilentV2HitchanceAllows(item) then
                                __akira_hook_exit('Utility.Raycast')
                                if destIndex == 3 then
                                    return invokeOriginal(a1, a2, dest, a4, select(5, ...))
                                end
                                return invokeOriginal(a1, dest, a3, select(4, ...))
                            end
                        end
                    end
                    __akira_hook_exit('Utility.Raycast')
                    return invokeOriginal(...)
                end

                local assigned = false
                if type(hookfunction) == 'function' then
                    local okHook, restored = pcall(hookfunction, original, hooked)
                    if okHook and type(restored) == 'function' and restored ~= hooked then
                        invokeOriginal = restored
                        assigned = true
                    end
                end

                local function unlock(target)
                    if type(target) ~= 'table' or type(setreadonly) ~= 'function' then
                        return
                    end
                    pcall(function()
                        if type(isreadonly) ~= 'function' or isreadonly(target) then
                            setreadonly(target, false)
                        end
                    end)
                end
                unlock(index)
                unlock(utility)
                if type(index) == 'table' then
                    if pcall(function()
                        index.Raycast = hooked
                    end) and index.Raycast == hooked then
                        assigned = true
                    end
                end
                if pcall(function()
                    utility.Raycast = hooked
                end) and utility.Raycast == hooked then
                    assigned = true
                end
                if not assigned and type(isfunctionhooked) == 'function' then
                    local okHooked, isHooked = pcall(isfunctionhooked, original)
                    if okHooked and isHooked == true then
                        assigned = true
                    end
                end
                if not assigned then
                    state.SilentV2HookNextTry = now + 1.25
                    return false
                end

                state.OriginalUtilityRaycast = original
                state.UtilityRaycastIndex = index
                state.SilentV2RaycastHooked = true
                state.SilentV2HookNextTry = nil
                return true
            end

            function RivalsModsState.GetViewmodelOffsetCFrame()
                if not IsRivalsModToggleEnabled('P4S2T10') then
                    return nil
                end
                local offset = CFrame.new(
                    ReadRivalsModNumber('P4S2S5', 0),
                    ReadRivalsModNumber('P4S2S6', 0),
                    ReadRivalsModNumber('P4S2S7', 0)
                )
                if offset == CFrame.new() then
                    return nil
                end
                return offset
            end

            function RivalsModsState.ShouldHookViewModelUpdate()
                return IsRivalsModToggleEnabled('P1S31T1')
                    or IsRivalsModToggleEnabled('P1S31T2')
                    or IsRivalsModToggleEnabled('P1S31T3')
                    or IsRivalsModToggleEnabled('P1S31T4')
                    or IsRivalsModToggleEnabled('P1S31T5')
                    or IsRivalsModToggleEnabled('P4S2T10')
            end

            function RivalsModsState.UpdateCameraModifiers()
                LPH_ATTRIBUTES(VM(NONE))
                local state = RivalsModsState
                if not (
                    IsRivalsModToggleEnabled('P4S2T9')
                    or IsRivalsModToggleEnabled('P4S2T6')
                    or IsRivalsModToggleEnabled('P4S2T8')
                    or IsRivalsModToggleEnabled('P1S31T1')
                    or IsRivalsModToggleEnabled('P1S31T2')
                    or IsRivalsModToggleEnabled('P1S31T3')
                    or IsRivalsModToggleEnabled('P1S31T4')
                    or IsRivalsModToggleEnabled('P1S31T5')
                    or IsRivalsModToggleEnabled('P4S2T10')
                ) then
                    return
                end
                local cameraController = RivalsModsState.ResolveCameraController()
                local customFov = IsRivalsModToggleEnabled('P4S2T9')
                local targetFov = ReadRivalsModNumber('P4S2S4', 80)

                if cameraController then
                    if IsRivalsModToggleEnabled('P4S2T6') then
                        if state.CameraShakeOriginalEnabled == nil then
                            state.CameraShakeOriginalEnabled = cameraController._shake_enabled
                        end
                        cameraController._shake_enabled = false
                    elseif state.CameraShakeOriginalEnabled ~= nil then
                        cameraController._shake_enabled = state.CameraShakeOriginalEnabled
                        state.CameraShakeOriginalEnabled = nil
                    end

                    pcall(RivalsModsState.ApplyCameraMotionSuppression, cameraController)

                    if type(cameraController.SetExternalFOVOffset) == 'function' then
                        local baseFov = type(cameraController._base_fov) == 'number' and cameraController._base_fov or 80
                        local offset = customFov and (targetFov - baseFov) or 0
                        if state._LastFovOffset ~= offset then
                            state._LastFovOffset = offset
                            pcall(cameraController.SetExternalFOVOffset, cameraController, 'Akira', offset)
                        end
                    end
                end

                local cam = Workspace.CurrentCamera
                if cam and type(cameraController and cameraController.SetExternalFOVOffset) ~= 'function' then
                    if customFov then
                        if state.CameraFovOriginal == nil then
                            state.CameraFovOriginal = cam.FieldOfView
                        end
                        if cam.FieldOfView ~= targetFov then
                            cam.FieldOfView = targetFov
                        end
                    elseif state.CameraFovOriginal ~= nil then
                        cam.FieldOfView = state.CameraFovOriginal
                        state.CameraFovOriginal = nil
                        state._LastFovOffset = nil
                    end
                end
            end

            function RivalsModsState.IsSprintAnimationKey(animator, animationKey)
                if type(animationKey) ~= 'string' then
                    return false
                end
                if animator and animationKey == rawget(animator, '_sprint_animation') then
                    return true
                end
                local lower = string.lower(animationKey)
                return string.find(lower, 'sprint', 1, true) ~= nil
            end

            function RivalsModsState.ShouldSuppressViewmodelAnimation(animator, animationKey)
                if type(animationKey) ~= 'string' then
                    return false
                end
                local thirdPerson = IsRivalsModToggleEnabled('P4S2T8')
                local noMotion = IsRivalsModToggleEnabled('P1S31T1') and not thirdPerson
                if IsRivalsModToggleEnabled('P1S31T2')
                    and (string.find(animationKey, 'Shoot', 1, true) ~= nil or animationKey == 'QuickShot') then
                    return true
                end
                if not thirdPerson
                    and (IsRivalsModToggleEnabled('P1S31T3') or noMotion)
                    and RivalsModsState.IsSprintAnimationKey(animator, animationKey) then
                    return true
                end
                if IsRivalsModToggleEnabled('P1S31T4')
                    and animationKey == rawget(animator, '_equip_animation') then
                    return true
                end
                if IsRivalsModToggleEnabled('P1S31T5')
                    and string.find(animationKey, 'Reload', 1, true) ~= nil then
                    return true
                end
                return false
            end

            function RivalsModsState.ResolveViewModelAnimator(viewModel)
                if type(viewModel) ~= 'table' then
                    return nil
                end
                if rawget(viewModel, '_sprint_animation') ~= nil or type(rawget(viewModel, 'PlaySprintAnimation')) == 'function' then
                    return viewModel
                end
                for _, key in ipairs({ 'ViewModelAnimator', 'Animator', '_animator', 'AnimatorObject' }) do
                    local nested = rawget(viewModel, key)
                    if type(nested) == 'table' and (
                        rawget(nested, '_sprint_animation') ~= nil
                        or type(rawget(nested, 'PlaySprintAnimation')) == 'function'
                    ) then
                        return nested
                    end
                end
                for _, nested in pairs(viewModel) do
                    if type(nested) == 'table' and rawget(nested, 'ClientViewModel') == viewModel then
                        return nested
                    end
                end
                return nil
            end

            function RivalsModsState.ForEachLocalAnimator(callback)
                if type(callback) ~= 'function' then
                    return
                end
                local fighter = ResolveLocalFighter()
                local items = fighter and type(fighter.Items) == 'table' and fighter.Items or {}
                for _, item in pairs(items) do
                    local viewModel = type(item) == 'table' and (rawget(item, 'ViewModel') or rawget(item, '_ViewModel')) or nil
                    local animator = RivalsModsState.ResolveViewModelAnimator(viewModel)
                    if animator then
                        callback(animator, viewModel, item)
                    end
                end
            end

            function RivalsModsState.StopSprintOnAnimator(animator)
                if type(animator) ~= 'table' then
                    return
                end
                pcall(function()
                    if type(animator.StopSprintAnimation) == 'function' then
                        animator:StopSprintAnimation()
                    end
                end)
                pcall(function()
                    local key = rawget(animator, '_sprint_animation')
                    if type(key) == 'string' and type(animator.StopAnimation) == 'function' then
                        animator:StopAnimation(key, 0)
                    end
                end)
                pcall(function()
                    local track = type(animator.GetSprintTrack) == 'function' and animator:GetSprintTrack()
                    if track and track.IsPlaying then
                        track:Stop(0)
                    end
                end)
            end

            function RivalsModsState.FreezeViewModelMotion(viewModel)
                if type(viewModel) ~= 'table' then
                    return
                end
                pcall(function()
                    viewModel._bobbing_tick = 0
                end)
                for springName, value in pairs(RivalsModsState.MotionSpringValues) do
                    pcall(RivalsModsState.FreezeSpring, rawget(viewModel, springName), value)
                end
                pcall(RivalsModsState.FreezeSpring, rawget(viewModel, '_sway_spring'), Vector2.zero)
                pcall(RivalsModsState.FreezeSpring, rawget(viewModel, '_leaning_spring'), 0)
                pcall(function()
                    if type(viewModel.SetCustomSprintingEnabled) == 'function' then
                        viewModel:SetCustomSprintingEnabled(false)
                    end
                end)
            end

            function RivalsModsState.ApplyViewmodelMotionSuppression(items)
                if IsRivalsModToggleEnabled('P4S2T8') then
                    return
                end
                local noMotion = IsRivalsModToggleEnabled('P1S31T1')
                local noSprint = IsRivalsModToggleEnabled('P1S31T3')
                if noMotion then
                    for _, item in pairs(items or {}) do
                        local viewModel = type(item) == 'table' and (rawget(item, 'ViewModel') or rawget(item, '_ViewModel')) or nil
                        RivalsModsState.FreezeViewModelMotion(viewModel)
                    end
                end
                if noMotion or noSprint then
                    RivalsModsState.ForEachLocalAnimator(function(animator, viewModel)
                        RivalsModsState.StopSprintOnAnimator(animator)
                        if type(viewModel) == 'table' and type(viewModel.SetCustomSprintingEnabled) == 'function' then
                            pcall(viewModel.SetCustomSprintingEnabled, viewModel, false)
                        end
                    end)
                end
            end

            function RivalsModsState.EnsureViewModelUpdateHook()
                local state = RivalsModsState
                if state.ViewModelUpdateRestore then
                    return
                end
                local class = RivalsRuntimeBridge.NativeRemovals.RequireModule('ClientViewModel')
                if type(class) ~= 'table' then
                    return
                end
                local originalUpdate = rawget(class, 'Update')
                if type(originalUpdate) ~= 'function' then
                    return
                end
                rawset(class, 'Update', function(viewModel, deltaTime, cameraData, offsets, ...)
                    if IsRivalsModToggleEnabled('P4S2T8') then
                        local packed = table.pack(pcall(originalUpdate, viewModel, deltaTime, cameraData, offsets, ...))
                        if not packed[1] then
                            return nil
                        end
                        return table.unpack(packed, 2, packed.n)
                    end
                    local noMotion = IsRivalsModToggleEnabled('P1S31T1')
                    local noSprint = noMotion or IsRivalsModToggleEnabled('P1S31T3')
                    local restoreCamera = nil
                    if type(cameraData) == 'table' and noSprint then
                        restoreCamera = {
                            IsActuallySprinting = cameraData.IsActuallySprinting,
                        }
                        cameraData.IsActuallySprinting = false
                        if noMotion then
                            restoreCamera.MoveSpeed = cameraData.MoveSpeed
                            restoreCamera.JustLanded = cameraData.JustLanded
                            restoreCamera.PlayerVelocity = cameraData.PlayerVelocity
                            restoreCamera.MoveVelocity = cameraData.MoveVelocity
                            restoreCamera.IsSliding = cameraData.IsSliding
                            cameraData.MoveSpeed = 0
                            cameraData.JustLanded = false
                            cameraData.PlayerVelocity = Vector3.zero
                            cameraData.MoveVelocity = Vector3.zero
                            cameraData.IsSliding = false
                        end
                    end
                    if noMotion then
                        RivalsModsState.FreezeViewModelMotion(viewModel)
                    end
                    local restoreOffset = nil
                    local hadOffsetField = false
                    local extraOffset = RivalsModsState.GetViewmodelOffsetCFrame()
                    if extraOffset and type(offsets) == 'table' then
                        hadOffsetField = true
                        restoreOffset = offsets.ViewModelOffset
                        offsets.ViewModelOffset = (restoreOffset or CFrame.identity) * extraOffset
                    end
                    local fighter = type(viewModel) == 'table' and viewModel.ClientItem and viewModel.ClientItem.ClientFighter or nil
                    local swayHooked = false
                    if noMotion and type(fighter) == 'table' then
                        rawset(fighter, 'GetCameraSway', function()
                            return Vector2.zero
                        end)
                        swayHooked = true
                    end
                    local packed = table.pack(pcall(originalUpdate, viewModel, deltaTime, cameraData, offsets, ...))
                    if swayHooked then
                        rawset(fighter, 'GetCameraSway', nil)
                    end
                    if hadOffsetField then
                        offsets.ViewModelOffset = restoreOffset
                    end
                    if restoreCamera and type(cameraData) == 'table' then
                        for key, value in pairs(restoreCamera) do
                            cameraData[key] = value
                        end
                    end
                    if noSprint then
                        RivalsModsState.StopSprintOnAnimator(RivalsModsState.ResolveViewModelAnimator(viewModel))
                    end
                    if noMotion then
                        RivalsModsState.FreezeViewModelMotion(viewModel)
                    end
                    if not packed[1] then
                        return nil
                    end
                    return table.unpack(packed, 2, packed.n)
                end)
                state.ViewModelUpdateRestore = {
                    class = class,
                    original = originalUpdate,
                }
            end

            function RivalsModsState.RevertViewModelUpdateHook()
                local restore = RivalsModsState.ViewModelUpdateRestore
                RivalsModsState.ViewModelUpdateRestore = nil
                if type(restore) == 'table' and restore.class and type(restore.original) == 'function' then
                    rawset(restore.class, 'Update', restore.original)
                end
            end

            function RivalsModsState.RefreshViewmodelEffects()
                if shutting_down or (Library and (Library.ConfigLoading or Library.LayoutSuspended)) or (RivalsRuntimeBridge and RivalsRuntimeBridge.RuntimeRefreshSuspended) then
                    return
                end
                local state = RivalsModsState
                local fighter = ResolveLocalFighter()
                local items = fighter and type(fighter.Items) == 'table' and fighter.Items or {}
                if RivalsModsState.ShouldHookViewModelUpdate() then
                    state.EnsureViewModelUpdateHook()
                else
                    state.RevertViewModelUpdateHook()
                end
                state.ApplyViewmodelMotionSuppression(items)
                RivalsRuntimeBridge.NativeRemovals.SyncAnimationHook()
            end

            function RivalsModsState.RestoreClientModifiers()
                local state = RivalsModsState
                if state.CameraController and state.CameraShakeOriginalEnabled ~= nil then
                    state.CameraController._shake_enabled = state.CameraShakeOriginalEnabled
                end
                local activeRestore = RivalsModsState.ThirdPersonActiveRestore
                RivalsModsState.ThirdPersonActiveRestore = nil
                if type(activeRestore) == 'table' and activeRestore.connection then
                    pcall(function()
                        activeRestore.connection:Disconnect()
                    end)
                end
                pcall(RivalsModsState.RevertThirdPersonOverrideHook)
                if state.CameraController and type(state.CameraController.SetThirdPersonOverride) == 'function' then
                    pcall(function()
                        state.CameraController:SetThirdPersonOverride(false)
                    end)
                end
                pcall(RivalsModsState.RevertViewModelUpdateHook)
                if state.CameraController and type(state.CameraController.SetExternalFOVOffset) == 'function' then
                    pcall(function()
                        state.CameraController:SetExternalFOVOffset('Akira', 0)
                    end)
                end
                if state.CameraController and state.CameraViewModelOriginal ~= nil then
                    state.CameraController.ViewModelOffsetCFrame = state.CameraViewModelOriginal
                end
                if state.CameraFovOriginal ~= nil and Workspace.CurrentCamera then
                    Workspace.CurrentCamera.FieldOfView = state.CameraFovOriginal
                end
                state.CameraShakeOriginalEnabled = nil
                state.CameraViewModelOriginal = nil
                state.CameraFovOriginal = nil
                state.CameraController = nil
                RivalsRuntimeBridge.NativeRemovals.RevertAnimationHook()
                RivalsModsState.RestorePersistentItemModifiers(true)
            end

            function RivalsModsState.ResolveGunModule()
                local state = RivalsModsState
                if state.GunModule then
                    return state.GunModule
                end

                if not IsReplicatedStateReady() then
                    return nil
                end

                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local itemTypes = modules and modules:FindFirstChild('ItemTypes')
                local gunModuleScript = itemTypes and itemTypes:FindFirstChild('Gun')
                if not gunModuleScript then
                    return nil
                end

                local ok, gunModule = pcall(require, gunModuleScript)
                if not ok then
                    return nil
                end

                state.GunModule = gunModule
                return gunModule
            end

            function RivalsModsState.ResolveMeleeModule()
                local state = RivalsModsState
                if state.MeleeModule then
                    return state.MeleeModule
                end

                if not IsReplicatedStateReady() then
                    return nil
                end

                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local itemTypes = modules and modules:FindFirstChild('ItemTypes')
                local meleeModuleScript = itemTypes and itemTypes:FindFirstChild('Melee')
                if not meleeModuleScript then
                    return nil
                end

                local ok, meleeModule = pcall(require, meleeModuleScript)
                if not ok then
                    return nil
                end

                state.MeleeModule = meleeModule
                return meleeModule
            end

            function RivalsModsState.ResolveGunbladeModule()
                local state = RivalsModsState
                if state.GunbladeModule then
                    return state.GunbladeModule
                end

                if not IsReplicatedStateReady() then
                    return nil
                end

                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local items = modules and modules:FindFirstChild('Items')
                local gunbladeModuleScript = items and items:FindFirstChild('Gunblade')
                if not gunbladeModuleScript then
                    return nil
                end

                local ok, gunbladeModule = pcall(require, gunbladeModuleScript)
                if not ok then
                    return nil
                end

                state.GunbladeModule = gunbladeModule
                return gunbladeModule
            end

            function RivalsModsState.ResolveGunStartShootingBase(fallback)
                local gunModule = RivalsModsState.ResolveGunModule()
                if gunModule and type(gunModule.StartShooting) == 'function' then
                    local originalGunStartShooting = RivalsModsState.OriginalGunStartShooting
                    if fallback == originalGunStartShooting or fallback == gunModule.StartShooting then
                        return gunModule.StartShooting
                    end
                end

                local meleeModule = RivalsModsState.ResolveMeleeModule()
                if meleeModule and type(meleeModule.StartShooting) == 'function' then
                    local originalMeleeStartShooting = RivalsModsState.OriginalMeleeStartShooting
                    if fallback == originalMeleeStartShooting or fallback == meleeModule.StartShooting then
                        return meleeModule.StartShooting
                    end
                end

                local gunbladeModule = RivalsModsState.ResolveGunbladeModule()
                if gunbladeModule and type(gunbladeModule.StartShooting) == 'function' then
                    local originalGunbladeStartShooting = RivalsModsState.OriginalGunbladeStartShooting
                    if fallback == originalGunbladeStartShooting or fallback == gunbladeModule.StartShooting then
                        return gunbladeModule.StartShooting
                    end
                end

                return fallback
            end

            local function ResolveRivalsModsStartShootingItem(item)
                if type(item) == 'table' and type(item.Name) == 'string' and item.Name ~= '' then
                    return item
                end

                local fighter = ResolveLocalFighter()
                local equippedItem = fighter and fighter.EquippedItem or nil
                if type(equippedItem) == 'table' and type(equippedItem.Name) == 'string' and equippedItem.Name ~= '' then
                    return equippedItem
                end

                return nil
            end

            function ResolveRivalsWeaponSpeedScale()
                if not IsRivalsModToggleEnabled('P4S1T1') then
                    return 1
                end

                local weaponSpeedBoost = math.clamp(ReadRivalsModNumber('P4S1S4', 85), 0, 85)
                return 1 / (1 + (weaponSpeedBoost / 100))
            end

            local function ResolveRivalsReloadKey(item, reloadEnum)
                local info = item and item.Info or nil
                if not info then
                    return nil
                end

                if reloadEnum ~= nil and type(item.FromEnum) == 'function' then
                    local ok, resolvedReloadKey = pcall(function()
                        return item:FromEnum(reloadEnum)
                    end)
                    if ok and type(resolvedReloadKey) == 'string' then
                        return resolvedReloadKey
                    end
                end

                local currentAmmo = ReadItemValue(item, 'Ammo')
                if type(currentAmmo) == 'number' and currentAmmo <= 0 and info.HasEmptyReload then
                    return 'EmptyReload'
                end

                return 'Reload'
            end

            local function WithScaledRivalsReloadTimings(info, reloadKey, reloadDurationScale, callback)
                if type(callback) ~= 'function' then
                    return nil
                end

                if not info or type(reloadKey) ~= 'string' or type(reloadDurationScale) ~= 'number' or reloadDurationScale >= 0.999 then
                    return callback()
                end

                local timingFields = nil
                if info.ReloadType == 'Regular' then
                    timingFields = {
                        reloadKey .. 'Length',
                        reloadKey .. 'ActionTimestamp',
                    }
                elseif info.ReloadType == 'Segmented' then
                    timingFields = {
                        reloadKey .. 'StartLength',
                        reloadKey .. 'StartActionTimestamp',
                        reloadKey .. 'SegmentLength',
                        reloadKey .. 'SegmentActionTimestamp',
                        reloadKey .. 'FinishLength',
                        reloadKey .. 'FinishActionTimestamp',
                    }
                else
                    return callback()
                end

                local originalTimings = {}
                for _, fieldName in ipairs(timingFields) do
                    local fieldValue = info[fieldName]
                    if type(fieldValue) == 'number' then
                        originalTimings[fieldName] = fieldValue
                        info[fieldName] = math.max(0.05, fieldValue * reloadDurationScale)
                    end
                end

                local results = table.pack(pcall(callback))
                for fieldName, fieldValue in pairs(originalTimings) do
                    info[fieldName] = fieldValue
                end

                if not results[1] then
                    ReportRivalsRuntimeIssue('mods_reload_timings', results[2])
                    return nil
                end

                return table.unpack(results, 2, results.n)
            end

            local function StopRivalsEquipAnimations(item)
                local viewModel = item and item.ViewModel
                if not viewModel then
                    return
                end

                if type(viewModel.StopAnimation) == 'function' then
                    pcall(function()
                        viewModel:StopAnimation('Equip')
                    end)
                    pcall(function()
                        viewModel:StopAnimation('EquipEmpty')
                    end)
                    return
                end

                local animator = viewModel.Animator
                if animator and type(animator.StopAnimation) == 'function' then
                    pcall(function()
                        animator:StopAnimation('Equip')
                    end)
                    pcall(function()
                        animator:StopAnimation('EquipEmpty')
                    end)
                end
            end

            function RivalsModsState.EnsureGunHooks()
                LPH_ATTRIBUTES(VM(NONE))
                local gunModule = RivalsModsState.ResolveGunModule()
                if not gunModule then
                    return false
                end

                local state = RivalsModsState

                if type(gunModule.StartShooting) == 'function' and not state.OriginalGunStartShooting then
                    local originalStartShooting = gunModule.StartShooting
                    state.OriginalGunStartShooting = originalStartShooting
                    gunModule.StartShooting = function(self, ...)
                        LPH_ATTRIBUTES(VM(NONE))
                        __akira_hook_enter('Gun.StartShooting')
                        local item = ResolveRivalsModsStartShootingItem(self)
                        if not item then
                            __akira_hook_exit('Gun.StartShooting')
                            return nil
                        end
                        local info = item.Info
                        local originalShootCooldown = nil
                        local originalBurstCooldown = nil
                        local originalQuickShotCooldown = nil
                        if IsRivalsModToggleEnabled('P4S1T1') and info then
                            local weaponSpeedScale = ResolveRivalsWeaponSpeedScale()
                            if type(info.ShootCooldown) == 'number' then
                                originalShootCooldown = info.ShootCooldown
                                info.ShootCooldown = math.max(0.001, originalShootCooldown * weaponSpeedScale)
                            end
                            if type(info.ShootBurstCooldown) == 'number' then
                                originalBurstCooldown = info.ShootBurstCooldown
                                info.ShootBurstCooldown = math.max(0.001, originalBurstCooldown * weaponSpeedScale)
                            end
                            if type(info.QuickShotCooldown) == 'number' then
                                originalQuickShotCooldown = info.QuickShotCooldown
                                info.QuickShotCooldown = math.max(0.001, originalQuickShotCooldown * weaponSpeedScale)
                            end
                        end

                        local didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot = false, nil, nil, nil, nil
                        if type(state.BeginAimbotSilentShot) == 'function' then
                            didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot = state.BeginAimbotSilentShot(item)
                        end

                        local results = RunWithGameIdentity(originalStartShooting, item, ...)

                        if type(state.FinishAimbotSilentShot) == 'function' then
                            state.FinishAimbotSilentShot(didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot)
                        end

                        if originalShootCooldown ~= nil then
                            info.ShootCooldown = originalShootCooldown
                        end
                        if originalBurstCooldown ~= nil then
                            info.ShootBurstCooldown = originalBurstCooldown
                        end
                        if originalQuickShotCooldown ~= nil then
                            info.QuickShotCooldown = originalQuickShotCooldown
                        end

                        if not results[1] then
                            ReportRivalsRuntimeIssue('mods_start_shooting', results[2])
                            __akira_hook_exit('Gun.StartShooting')
                            return nil
                        end

                        __akira_hook_exit('Gun.StartShooting')
                        return table.unpack(results, 2, results.n)
                    end
                end

                if type(gunModule.StartReloading) == 'function' and not state.OriginalGunStartReloading then
                    local originalStartReloading = gunModule.StartReloading
                    state.OriginalGunStartReloading = originalStartReloading
                    gunModule.StartReloading = function(self, forceReload, reloadEnum, animationEnum, segmentedCount)
                        LPH_ATTRIBUTES(VM(NONE))
                        __akira_hook_enter('Gun.StartReloading')
                        if not IsRivalsModToggleEnabled('P4S1T2') then
                            __akira_hook_exit('Gun.StartReloading')
                            return originalStartReloading(self, forceReload, reloadEnum, animationEnum, segmentedCount)
                        end

                        local reloadSpeedBoost = math.clamp(ReadRivalsModNumber('P4S1S3', 10), 0, 20)
                        if reloadSpeedBoost <= 0 then
                            __akira_hook_exit('Gun.StartReloading')
                            return originalStartReloading(self, forceReload, reloadEnum, animationEnum, segmentedCount)
                        end

                        local reloadDurationScale = 1 - (reloadSpeedBoost / 100)
                        local resolvedReloadKey = ResolveRivalsReloadKey(self, reloadEnum)
                        __akira_hook_exit('Gun.StartReloading')
                        return WithScaledRivalsReloadTimings(self and self.Info or nil, resolvedReloadKey, reloadDurationScale, function()
                            return originalStartReloading(self, forceReload, reloadEnum, animationEnum, segmentedCount)
                        end)
                    end
                end

                if type(gunModule._Recoil) == 'function' and not state.OriginalGunRecoil then
                    local originalRecoil = gunModule._Recoil
                    state.OriginalGunRecoil = originalRecoil
                    gunModule._Recoil = function(self, multiplier)
                        if IsRivalsModToggleEnabled('P4S1T4') and type(multiplier) == 'number' then
                            local reduction = math.clamp(ReadRivalsModNumber('P4S1S2', 100), 0, 100)
                            local reducedMultiplier = multiplier * (1 - (reduction / 100))
                            if reducedMultiplier <= 0.001 then
                                return
                            end
                            return originalRecoil(self, reducedMultiplier)
                        end

                        return originalRecoil(self, multiplier)
                    end
                end

                if type(gunModule.GetAimSpeed) == 'function' and not state.OriginalGunGetAimSpeed then
                    local originalGetAimSpeed = gunModule.GetAimSpeed
                    state.OriginalGunGetAimSpeed = originalGetAimSpeed
                    gunModule.GetAimSpeed = function(self)
                        local originalAimSpeed = originalGetAimSpeed(self)
                        if IsRivalsModToggleEnabled('P4S2T2') and type(originalAimSpeed) == 'number' then
                            local adsSpeedBoost = math.clamp(ReadRivalsModNumber('P4S2S2', 85), 0, 85)
                            return math.max(1, originalAimSpeed * (1 + (adsSpeedBoost / 100)))
                        end

                        return originalAimSpeed
                    end
                end

                if type(gunModule.Equip) == 'function' and not state.OriginalGunEquip then
                    local originalEquip = gunModule.Equip
                    state.OriginalGunEquip = originalEquip
                    gunModule.Equip = function(self, ...)
                        local results = table.pack(originalEquip(self, ...))
                        if IsRivalsModToggleEnabled('P4S2T3') then
                            local equipSpeedBoost = math.clamp(ReadRivalsModNumber('P4S2S3', 100), 0, 80)
                            local equipSpeedScale = 1 / (1 + (equipSpeedBoost / 100))
                            local now = tick()
                            local remainingEquipCooldown = type(self._equip_cooldown) == 'number' and math.max(self._equip_cooldown - now, 0) or 0
                            self._equip_cooldown = now + (remainingEquipCooldown * equipSpeedScale)

                            local equipHash = self._equip_hash
                            local scaledEquipDuration = remainingEquipCooldown * equipSpeedScale
                            task.delay(scaledEquipDuration, function()
                                if self and self._equip_hash == equipHash then
                                    StopRivalsEquipAnimations(self)
                                end
                            end)
                        end

                        return table.unpack(results, 1, results.n)
                    end
                end

                return true
            end

            function RivalsModsState.EnsureMeleeHooks()
                local meleeModule = RivalsModsState.ResolveMeleeModule()
                if not meleeModule then
                    return false
                end

                local state = RivalsModsState

                if type(meleeModule.StartShooting) == 'function' and not state.OriginalMeleeStartShooting then
                    local originalStartShooting = meleeModule.StartShooting
                    state.OriginalMeleeStartShooting = originalStartShooting
                    meleeModule.StartShooting = function(self, ...)
                        local item = ResolveRivalsModsStartShootingItem(self)
                        if not item then
                            return nil
                        end
                        local info = item.Info
                        local originalAttackCooldown = nil
                        if IsRivalsModToggleEnabled('P4S1T1') and info then
                            local weaponSpeedScale = ResolveRivalsWeaponSpeedScale()
                            if type(info.AttackCooldown) == 'number' then
                                originalAttackCooldown = info.AttackCooldown
                                info.AttackCooldown = math.max(0.001, originalAttackCooldown * weaponSpeedScale)
                            end
                        end

                        local didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot = false, nil, nil, nil, nil
                        if type(state.BeginAimbotSilentShot) == 'function' then
                            didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot = state.BeginAimbotSilentShot(item)
                        end

                        local results = RunWithGameIdentity(originalStartShooting, item, ...)

                        if type(state.FinishAimbotSilentShot) == 'function' then
                            state.FinishAimbotSilentShot(didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot)
                        end

                        if originalAttackCooldown ~= nil then
                            info.AttackCooldown = originalAttackCooldown
                        end

                        if not results[1] then
                            ReportRivalsRuntimeIssue('mods_melee_start_shooting', results[2])
                            return nil
                        end

                        return table.unpack(results, 2, results.n)
                    end
                end

                return true
            end

            function RivalsModsState.EnsureGunbladeHooks()
                local gunbladeModule = RivalsModsState.ResolveGunbladeModule()
                if not gunbladeModule then
                    return false
                end

                local state = RivalsModsState

                if type(gunbladeModule.StartShooting) == 'function' and not state.OriginalGunbladeStartShooting then
                    local originalStartShooting = gunbladeModule.StartShooting
                    state.OriginalGunbladeStartShooting = originalStartShooting
                    gunbladeModule.StartShooting = function(self, ...)
                        local item = ResolveRivalsModsStartShootingItem(self)
                        if not item then
                            return nil
                        end
                        local info = item.Info
                        local originalBladeCooldown = nil
                        if IsRivalsModToggleEnabled('P4S1T1') and info and type(item and item.Get) == 'function' and item:Get('Mode') == 'Blade' then
                            local weaponSpeedScale = ResolveRivalsWeaponSpeedScale()
                            if type(info.BladeCooldown) == 'number' then
                                originalBladeCooldown = info.BladeCooldown
                                info.BladeCooldown = math.max(0.001, originalBladeCooldown * weaponSpeedScale)
                            end
                        end

                        local didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot = false, nil, nil, nil, nil
                        if type(state.BeginAimbotSilentShot) == 'function' then
                            didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot = state.BeginAimbotSilentShot(item)
                        end

                        local results = RunWithGameIdentity(originalStartShooting, item, ...)

                        if type(state.FinishAimbotSilentShot) == 'function' then
                            state.FinishAimbotSilentShot(didPrimeSilent, silentCamera, silentOriginalCFrame, silentCamController, silentOriginalCamRot)
                        end

                        if originalBladeCooldown ~= nil then
                            info.BladeCooldown = originalBladeCooldown
                        end

                        if not results[1] then
                            ReportRivalsRuntimeIssue('mods_gunblade_start_shooting', results[2])
                            return nil
                        end

                        return table.unpack(results, 2, results.n)
                    end
                end

                return true
            end

            local function AkiraHookSnapshotKey()
                return '__AkiraModHookSnap'
            end

            function RivalsModsState.RestoreHooksFromSnapshot()
                local env = __akira_genv
                local snap = env and env[AkiraHookSnapshotKey()]
                if type(snap) ~= 'table' then
                    return false
                end
                env[AkiraHookSnapshotKey()] = nil
                local restored = 0
                local function restoreModuleField(entry)
                    if type(entry) ~= 'table' or type(entry.module) ~= 'table' or type(entry.value) ~= 'function' then
                        return
                    end
                    pcall(function()
                        if typeof(setreadonly) == 'function' and type(isreadonly) == 'function' and isreadonly(entry.module) then
                            setreadonly(entry.module, false)
                        end
                        entry.module[entry.field] = entry.value
                    end)
                    restored = restored + 1
                end
                restoreModuleField(snap.GunStartShooting)
                restoreModuleField(snap.GunStartReloading)
                restoreModuleField(snap.GunRecoil)
                restoreModuleField(snap.GunGetAimSpeed)
                restoreModuleField(snap.GunEquip)
                restoreModuleField(snap.MeleeStartShooting)
                restoreModuleField(snap.GunbladeStartShooting)
                if type(snap.Raycast) == 'table' and type(snap.Raycast.value) == 'function' then
                    local rayVal = snap.Raycast.value
                    pcall(function()
                        if type(restorefunction) == 'function' then
                            restorefunction(rayVal)
                        end
                    end)
                    local function restoreField(target)
                        pcall(function()
                            if typeof(target) ~= 'table' or type(setreadonly) ~= 'function' or type(isreadonly) ~= 'function' then
                                return
                            end
                            if isreadonly(target) then
                                setreadonly(target, false)
                            end
                            target.Raycast = rayVal
                        end)
                    end
                    restoreField(snap.Raycast.index)
                    restoreField(snap.Raycast.utility)
                    restored = restored + 1
                end
                if type(snap.Input) == 'table' and type(snap.Input.method) == 'function' and type(snap.Input.index) == 'number' then
                    pcall(function()
                        debug.setupvalue(snap.Input.method, snap.Input.index, snap.Input.value)
                    end)
                    restored = restored + 1
                end
                if restored > 0 then
                    __akira_boot_log('REHOOK: restored ' .. tostring(restored) .. ' stale hooks from a previous run')
                end
                return restored > 0
            end

            function RivalsModsState.SaveHooksSnapshot()
                local state = RivalsModsState
                local snap = {}
                local function capture(field, module, prop, value)
                    if type(value) ~= 'function' or type(module) ~= 'table' then
                        return
                    end
                    snap[field] = {
                        module = module,
                        field = prop,
                        value = value,
                    }
                end
                capture('GunStartShooting', state.GunModule, 'StartShooting', state.OriginalGunStartShooting)
                capture('GunStartReloading', state.GunModule, 'StartReloading', state.OriginalGunStartReloading)
                capture('GunRecoil', state.GunModule, '_Recoil', state.OriginalGunRecoil)
                capture('GunGetAimSpeed', state.GunModule, 'GetAimSpeed', state.OriginalGunGetAimSpeed)
                capture('GunEquip', state.GunModule, 'Equip', state.OriginalGunEquip)
                capture('MeleeStartShooting', state.MeleeModule, 'StartShooting', state.OriginalMeleeStartShooting)
                capture('GunbladeStartShooting', state.GunbladeModule, 'StartShooting', state.OriginalGunbladeStartShooting)
                if type(state.OriginalUtilityRaycast) == 'function' then
                    snap.Raycast = {
                        value = state.OriginalUtilityRaycast,
                        index = state.UtilityRaycastIndex,
                        utility = state.UtilityModule,
                    }
                end
                local inputHook = state.AkiraInputHook
                if type(inputHook) == 'table' and type(inputHook._restore) == 'table' then
                    snap.Input = {
                        method = inputHook._restore.method,
                        index = inputHook._restore.index,
                        value = inputHook._restore.original,
                    }
                end
                if next(snap) then
                    __akira_genv[AkiraHookSnapshotKey()] = snap
                end
            end

            function RivalsModsState.EnsureHooks()
                if shutting_down or (Library and (Library.ConfigLoading or Library.LayoutSuspended)) or (RivalsRuntimeBridge and RivalsRuntimeBridge.RuntimeRefreshSuspended) then
                    return false
                end
                local state = RivalsModsState
                pcall(RivalsModsState.RestoreHooksFromSnapshot)
                __akira_boot_log('RuntimeA: refresh persistent mods...')
                pcall(RivalsModsState.RefreshPersistentItemModifiers)
                pcall(RivalsModsState.UpdateCameraModifiers)
                pcall(RivalsModsState.RefreshViewmodelEffects)
                __akira_boot_log('RuntimeA: silent raycast hook...')
                pcall(RivalsModsState.EnsureSilentV2RaycastHook)
                __akira_boot_log('RuntimeA: raycast hook done')
                if state.NoSpreadController then
                    __akira_boot_log('RuntimeA: sync nospread...')
                    RivalsModsState.SyncNoSpreadEnabled()
                    __akira_boot_log('RuntimeA: sync nospread done')
                end
                if state.GrenadeFuseController then
                    __akira_boot_log('RuntimeA: sync grenade fuse...')
                    RivalsModsState.SyncGrenadeFuse()
                    __akira_boot_log('RuntimeA: sync grenade fuse done')
                end

                __akira_boot_log('RuntimeA: P4S gate check...')
                if not (
                    IsRivalsModToggleEnabled('P4S1T1')
                    or IsRivalsModToggleEnabled('P4S1T2')
                    or IsRivalsModToggleEnabled('P4S1T3')
                    or IsRivalsModToggleEnabled('P4S1T4')
                    or IsRivalsModToggleEnabled('P4S1T5')
                    or IsRivalsModToggleEnabled('P4S1T6')
                    or IsRivalsModToggleEnabled('P4S1T7')
                    or IsRivalsModToggleEnabled('P4S2T2')
                    or IsRivalsModToggleEnabled('P4S2T3')
                    or IsRivalsModToggleEnabled('P4S2T4')
                    or IsRivalsModToggleEnabled('P4S2T5')
                    or IsRivalsModToggleEnabled('P4S2T6')
                    or IsRivalsModToggleEnabled('P4S2T8')
                    or IsRivalsModToggleEnabled('P4S2T9')
                    or IsRivalsModToggleEnabled('P4S2T10')
                    or IsRivalsModToggleEnabled('P4S1_ProjRapidFire')
                    or IsRivalsModToggleEnabled('P4S1_BowInstantDraw')
                ) then
                    state.PendingEnsureHooks = false
                    return false
                end

                if not IsReplicatedStateReady() then
                    state.PendingEnsureHooks = true
                    return false
                end
                __akira_boot_log('RuntimeA: replicated state ok')

                state.PendingEnsureHooks = false
                if IsRivalsModToggleEnabled('P4S1T3')
                    or IsRivalsModToggleEnabled('P4S1T6')
                    or IsRivalsModToggleEnabled('P4S1T7') then
                    __akira_genv.AkiraCaps.gate('No Spread / Grenade Fuse', 'debug.getupvalues', 'debug.setupvalue')
                end
                __akira_boot_log('RuntimeA: input hook...')
                if RivalsModsState.EnsureAkiraInputHook() then
                    RivalsModsState.SyncNoSpreadEnabled()
                    RivalsModsState.SyncGrenadeFuse()
                end
                __akira_boot_log('RuntimeA: input hook done')
                __akira_boot_log('RuntimeA: input hook done')
                __akira_boot_log('RuntimeA: gun hooks...')
                RivalsModsState.EnsureGunHooks()
                __akira_boot_log('RuntimeA: melee hooks...')
                RivalsModsState.EnsureMeleeHooks()
                __akira_boot_log('RuntimeA: gunblade hooks...')
                RivalsModsState.EnsureGunbladeHooks()
                if IsRivalsModToggleEnabled('P4S2T8') then
                    pcall(RivalsModsState.SetThirdPersonEnabled, nil, true)
                end
                RivalsModsState.SaveHooksSnapshot()
                return true
            end

            __akira_boot_yield()

            function RivalsModsState.RestoreHooks()
                local state = RivalsModsState
                RivalsModsState.RestoreClientModifiers()
                RivalsModsState.RestoreAkiraInputHook()
                local gunModule = state.GunModule
                if gunModule then
                    if state.OriginalGunStartShooting then
                        gunModule.StartShooting = state.OriginalGunStartShooting
                    end
                    if state.OriginalGunStartReloading then
                        gunModule.StartReloading = state.OriginalGunStartReloading
                    end
                    if state.OriginalGunRecoil then
                        gunModule._Recoil = state.OriginalGunRecoil
                    end
                    if state.OriginalGunGetAimSpeed then
                        gunModule.GetAimSpeed = state.OriginalGunGetAimSpeed
                    end
                    if state.OriginalGunEquip then
                        gunModule.Equip = state.OriginalGunEquip
                    end
                end

                local meleeModule = state.MeleeModule
                if meleeModule then
                    if state.OriginalMeleeStartShooting then
                        meleeModule.StartShooting = state.OriginalMeleeStartShooting
                    end
                end

                local gunbladeModule = state.GunbladeModule
                if gunbladeModule then
                    if state.OriginalGunbladeStartShooting then
                        gunbladeModule.StartShooting = state.OriginalGunbladeStartShooting
                    end
                end

                state.GunModule = nil
                state.MeleeModule = nil
                state.GunbladeModule = nil
                state.OriginalGunStartShooting = nil
                state.OriginalMeleeStartShooting = nil
                state.OriginalGunbladeStartShooting = nil
                state.OriginalGunStartReloading = nil
                state.OriginalGunRecoil = nil
                state.OriginalGunGetAimSpeed = nil
                state.OriginalGunEquip = nil

                if state.OriginalUtilityRaycast then
                    local utility = state.UtilityModule
                    local index = state.UtilityRaycastIndex
                    if type(restorefunction) == 'function' then
                        pcall(restorefunction, state.OriginalUtilityRaycast)
                    end
                    if type(index) == 'table' then
                        pcall(function()
                            index.Raycast = state.OriginalUtilityRaycast
                        end)
                    end
                    if type(utility) == 'table' then
                        pcall(function()
                            utility.Raycast = state.OriginalUtilityRaycast
                        end)
                    end
                end
                state.OriginalUtilityRaycast = nil
                state.UtilityRaycastIndex = nil
                state.SilentV2RaycastHooked = nil
                state.SilentV2HookNextTry = nil
                state.UtilityModule = nil

                if __akira_genv then
                    __akira_genv[AkiraHookSnapshotKey()] = nil
                end
            end
            end)()

            local RefreshAimbotEnabledToggleKeypickerState = nil
            local AimbotBridge = {}
            ;(function() LPH_ATTRIBUTES(VM(NONE))
            do
                local function IsTouchAimbotDevice()
                    return UserInputService.TouchEnabled and not UserInputService.MouseEnabled
                end

                local function GetAimbotViewportCenter()
                    local camera = Workspace.CurrentCamera
                    if camera then
                        return Vector2.new(camera.ViewportSize.X * 0.5, camera.ViewportSize.Y * 0.5)
                    end

                    return Vector2.zero
                end

                AimbotBridge.GetAimbotPointerPosition = function()
                    if IsTouchAimbotDevice() then
                        return GetAimbotViewportCenter()
                    end

                    local okBehavior, mouseBehavior = pcall(function()
                        return UserInputService.MouseBehavior
                    end)
                    if okBehavior and mouseBehavior == Enum.MouseBehavior.LockCenter then
                        return GetAimbotViewportCenter()
                    end

                    return UserInputService:GetMouseLocation()
                end

                AimbotBridge.WorldToAimbotScreen = function(worldPosition, camera)
                    camera = camera or Workspace.CurrentCamera
                    if not camera or typeof(worldPosition) ~= 'Vector3' then
                        return nil, false
                    end
                    local screenPoint, onScreen = camera:WorldToViewportPoint(worldPosition)
                    return Vector2.new(screenPoint.X, screenPoint.Y), onScreen == true and screenPoint.Z > 0
                end

                AimbotBridge.ResolveAimbotEquippedItem = function()
                    local fighter = ResolveLocalFighter()
                    return fighter and fighter.EquippedItem or nil
                end

                local AIMBOT_HARD_BLOCK_ITEMS = {
                    ['Warper'] = true,
                    ['Medkit'] = true,
                    ['Subspace Tripmine'] = true,
                    ['Warpstone'] = true,
                    ['Flashbang'] = true,
                    ['Grenade'] = true,
                    ['Jump Pad'] = true,
                    ['Molotov'] = true,
                    ['Satchel'] = true,
                    ['Smoke Grenade'] = true,
                    ['War Horn'] = true,
                    ['Grappler'] = true,
                    ['Flamethrower'] = true,
                }

                local AIMBOT_HOLD_FIRE_ITEMS = {
                    ['Flamethrower'] = true,
                }

                AimbotBridge.CanUseAimbotWithItem = function(item, isDirectAimbot)
                    if not item then
                        return true
                    end

                    local name = item.Name
                    if AIMBOT_HARD_BLOCK_ITEMS[name] == true then
                        return false
                    end

                    local selection = (isDirectAimbot and Options.P2S2_IgnoreWeapons and Options.P2S2_IgnoreWeapons.Value)
                        or (Options.P2S1D4 and Options.P2S1D4.Value)
                    if type(selection) == 'table' then
                        if selection[name] == true then
                            return false
                        end
                        for _, selectedName in ipairs(selection) do
                            if selectedName == name then
                                return false
                            end
                        end
                    end

                    if type(item.StartShooting) == 'function' then
                        return true
                    end
                    if name == 'Daggers' or name == 'Bow' or name == 'Slingshot' then
                        return true
                    end
                    if AIMBOT_HOLD_FIRE_ITEMS[name] == true then
                        return true
                    end
                    local info = item.Info
                    if type(info) == 'table' then
                        local className = info.Class or info.Type
                        if className == 'Gun' or className == 'Melee' or className == 'Gunblade' then
                            return true
                        end
                    end

                    return false
                end

                AimbotBridge.CanUseTriggerbotWithItem = function(item)
                    return AimbotBridge.CanUseAimbotWithItem(item)
                end

                AimbotBridge.SyncAimbotToggleKeypickerToUi = function(toggle, keypicker)
                    if not toggle or not keypicker then
                        return function() end
                    end

                    local applyingToggleState = false
                    local applyingKeypickerState = false
                    local lastMode = keypicker.Mode

                    local function syncKeypickerFromToggle(value)
                        if keypicker.Mode ~= 'Toggle' then
                            lastMode = keypicker.Mode
                            return
                        end

                        local nextState = value == true
                        if keypicker.Toggled == nextState then
                            lastMode = keypicker.Mode
                            return
                        end

                        applyingToggleState = true
                        keypicker.Toggled = nextState
                        if type(keypicker.Update) == 'function' then
                            keypicker:Update()
                        end
                        applyingToggleState = false
                        lastMode = keypicker.Mode
                    end

                    if type(toggle.OnChanged) == 'function' then
                        toggle:OnChanged(function(value)
                            if applyingKeypickerState then
                                return
                            end

                            syncKeypickerFromToggle(value)
                        end)
                    end

                    if type(keypicker.OnClick) == 'function' then
                        keypicker:OnClick(function(state)
                            if applyingToggleState or keypicker.Mode ~= 'Toggle' then
                                lastMode = keypicker.Mode
                                return
                            end

                            local nextValue = state == true
                            if toggle.Value == nextValue then
                                lastMode = keypicker.Mode
                                return
                            end

                            applyingKeypickerState = true
                            toggle:SetValue(nextValue)
                            applyingKeypickerState = false
                            lastMode = keypicker.Mode
                        end)
                    end

                    syncKeypickerFromToggle(toggle.Value)

                    return function()
                        if keypicker.Mode == 'Toggle' and lastMode ~= 'Toggle' then
                            syncKeypickerFromToggle(toggle.Value)
                        else
                            lastMode = keypicker.Mode
                        end
                    end
                end

                AimbotBridge.IsRagebotForcingCombat = function()
                    return false
                end

                AimbotBridge.ResolveAimbotMode = function()
                    local mode = Options.P2S1D1 and Options.P2S1D1.Value or 'Silent'
                    if mode ~= 'Camera' then
                        return 'Silent'
                    end
                    return mode
                end

                AimbotBridge.IsSilentAimToggleOn = function()
                    return Toggles.P2S1T1 and Toggles.P2S1T1.Value == true
                end

                AimbotBridge.IsDirectAimbotToggleOn = function()
                    return Toggles.P2S2_AimEnabled and Toggles.P2S2_AimEnabled.Value == true
                end

                AimbotBridge.IsAimbotSelected = function()
                    return AimbotBridge.IsRagebotForcingCombat()
                        or AimbotBridge.IsSilentAimToggleOn()
                        or AimbotBridge.IsDirectAimbotToggleOn()
                end

                AimbotBridge.IsSilentAimFullyActive = function()
                    if RefreshAimbotEnabledToggleKeypickerState then
                        RefreshAimbotEnabledToggleKeypickerState()
                    end
                    if not AimbotBridge.IsSilentAimToggleOn() then
                        return false
                    end
                    if not AimbotBridge.CanUseAimbotWithItem(AimbotBridge.ResolveAimbotEquippedItem()) then
                        return false
                    end
                    if Options.P2S1T1K and type(Options.P2S1T1K.GetState) == 'function' then
                        return Options.P2S1T1K:GetState() == true
                    end
                    return true
                end

                AimbotBridge.IsExplicitAimbotEnabled = function()
                    return AimbotBridge.IsSilentAimFullyActive()
                end

                -- Silent Aim check
                AimbotBridge.IsAimbotEnabled = function()
                    if AimbotBridge.IsRagebotForcingCombat() then
                        return AimbotBridge.CanUseAimbotWithItem(AimbotBridge.ResolveAimbotEquippedItem())
                    end
                    return AimbotBridge.IsSilentAimFullyActive()
                end

                local function IsMouseInputHeld(userInputType, trackedHeld)
                    if trackedHeld then
                        return true
                    end
                    local ok, pressed = pcall(function()
                        return UserInputService:IsMouseButtonPressed(userInputType)
                    end)
                    return ok == true and pressed == true
                end

                AimbotBridge.IsDirectAimKeyActive = function()
                    local aimKey = Options.P2S2_AimKey
                    local leftHeld = IsMouseInputHeld(Enum.UserInputType.MouseButton1, AimbotInputState.LeftMouse)
                    local rightHeld = IsMouseInputHeld(Enum.UserInputType.MouseButton2, AimbotInputState.RightMouse)
                    if not aimKey then
                        return leftHeld or rightHeld
                    end

                    local keyValue = aimKey.Value
                    local unbound = keyValue == nil or keyValue == '' or keyValue == 'Unknown' or keyValue == 'None' or keyValue == 'NONE'
                    local hasCustomKey = (type(aimKey.GetKey) == 'function' and aimKey:GetKey() ~= nil)
                        or (keyValue ~= nil and not unbound)
                    if not hasCustomKey or unbound then
                        if IsTouchAimbotDevice() then
                            return ((AimbotInputState.TouchCount and AimbotInputState.TouchCount > 0) or leftHeld or rightHeld) == true
                        end
                        return leftHeld or rightHeld
                    end

                    if keyValue == 'MB1' or keyValue == 'MouseButton1' or keyValue == 'Button1' then
                        return leftHeld or (type(aimKey.GetState) == 'function' and aimKey:GetState() == true)
                    end
                    if keyValue == 'MB2' or keyValue == 'MouseButton2' or keyValue == 'Button2' then
                        return rightHeld or (type(aimKey.GetState) == 'function' and aimKey:GetState() == true)
                    end
                    if type(aimKey.GetState) == 'function' then
                        return aimKey:GetState() == true
                    end
                    return false
                end

                -- Direct Aimbot (Cam Aim / Mouse Aim) check
                AimbotBridge.IsDirectAimbotEnabled = function()
                    if not (Toggles.P2S2_AimEnabled and Toggles.P2S2_AimEnabled.Value) then
                        return false
                    end
                    if AimbotInputState.SyntheticInputBlocked() then
                        return false
                    end
                    local equippedItem = AimbotBridge.ResolveAimbotEquippedItem()
                    if not AimbotBridge.CanUseAimbotWithItem(equippedItem, true) then
                        return false
                    end
                    if not AimbotBridge.IsDirectAimKeyActive() then
                        return false
                    end

                    return true
                end

                AimbotBridge.IsCameraAimEnabled = function()
                    return AimbotBridge.IsDirectAimbotEnabled()
                end

                AimbotBridge.IsTriggerbotEnabled = function()
                    if not AimbotBridge.CanUseTriggerbotWithItem(AimbotBridge.ResolveAimbotEquippedItem()) then
                        return false
                    end

                    if AimbotBridge.IsRagebotForcingCombat() then
                        return true
                    end

                    if not (Toggles.P2S1T7 and Toggles.P2S1T7.Value) then
                        return false
                    end

                    if Options.P2S1T7K and type(Options.P2S1T7K.GetState) == 'function' then
                        return Options.P2S1T7K:GetState()
                    end

                    return true
                end

                AimbotBridge.ParseMultiOption = function(optionId)
                    local option = Options and Options[optionId]
                    local value = option and option.Value
                    local selected = {}
                    if type(value) == 'table' then
                        for key, entry in pairs(value) do
                            if type(key) == 'string' and entry == true then
                                selected[key] = true
                            elseif type(entry) == 'string' then
                                selected[entry] = true
                            end
                        end
                    elseif type(value) == 'string' and value ~= '' then
                        selected[value] = true
                    end
                    return selected
                end

                AimbotBridge.ResolveTargeting = function(optionId)
                    local selected = AimbotBridge.ParseMultiOption(optionId)
                    local hasSelection = false
                    for _ in pairs(selected) do
                        hasSelection = true
                        break
                    end
                    if not hasSelection then
                        -- Empty selection means "no filters" — do not force them back on.
                        return {
                            requireVisible = false,
                            ignoreFov = true,
                            teamCheck = false,
                        }
                    end
                    return {
                        requireVisible = selected['Visible Only'] == true,
                        ignoreFov = selected['FOV Check'] ~= true,
                        teamCheck = selected['Team Check'] == true,
                    }
                end

                AimbotBridge.IsAimbotIgnoreFovEnabled = function()
                    return AimbotBridge.ResolveTargeting('P2S1_Targeting').ignoreFov
                end

                local function LerpFovGradientColor(a, b, alpha)
                    alpha = math.clamp(alpha, 0, 1)
                    a = a or Color3.new(1, 1, 1)
                    b = b or a
                    return Color3.new(
                        a.R + ((b.R - a.R) * alpha),
                        a.G + ((b.G - a.G) * alpha),
                        a.B + ((b.B - a.B) * alpha)
                    )
                end

                local function SampleFovGradientColor(c1, c2, c3, t)
                    local palette = { c1 or Color3.fromRGB(70, 160, 255), c2 or Color3.fromRGB(56, 130, 255), c3 or c1, c1 }
                    local wrapped = t % 1
                    if wrapped < 0 then
                        wrapped = wrapped + 1
                    end
                    local scaled = wrapped * 3
                    local index = math.floor(scaled)
                    local frac = scaled - index
                    local mixed = LerpFovGradientColor(palette[index + 1], palette[index + 2], frac)
                    local neighbor = palette[((index + 1) % 3) + 1]
                    return LerpFovGradientColor(mixed, neighbor, 0.18)
                end

                local CachedRainbowFovSequence = nil
                local function BuildRainbowFovSequence()
                    if CachedRainbowFovSequence then
                        return CachedRainbowFovSequence
                    end
                    CachedRainbowFovSequence = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 0.9, 1)),
                        ColorSequenceKeypoint.new(0.2, Color3.fromHSV(0.2, 0.9, 1)),
                        ColorSequenceKeypoint.new(0.4, Color3.fromHSV(0.4, 0.9, 1)),
                        ColorSequenceKeypoint.new(0.6, Color3.fromHSV(0.6, 0.9, 1)),
                        ColorSequenceKeypoint.new(0.8, Color3.fromHSV(0.8, 0.9, 1)),
                        ColorSequenceKeypoint.new(1, Color3.fromHSV(0.99, 0.9, 1)),
                    })
                    return CachedRainbowFovSequence
                end

                local function BuildFovGradientSequence(c1, c2, c3)
                    c1 = c1 or Color3.fromRGB(70, 160, 255)
                    c2 = c2 or Color3.fromRGB(56, 130, 255)
                    c3 = c3 or c1
                    return ColorSequence.new({
                        ColorSequenceKeypoint.new(0, c1),
                        ColorSequenceKeypoint.new(0.5, c2),
                        ColorSequenceKeypoint.new(1, c3),
                    })
                end

                local function ApplyCachedFovGradient(group, rainbow, c1, c2, c3)
                    local key
                    if rainbow then
                        key = 'rainbow'
                    else
                        local ok1, h1 = pcall(function() return c1:ToHex() end)
                        local ok2, h2 = pcall(function() return c2:ToHex() end)
                        local ok3, h3 = pcall(function() return c3:ToHex() end)
                        key = table.concat({ ok1 and h1 or 'a', ok2 and h2 or 'b', ok3 and h3 or 'c' }, '|')
                    end
                    if group.CachedGradKey == key then
                        return
                    end
                    group.CachedGradKey = key
                    if rainbow then
                        group.Gradient.Color = BuildRainbowFovSequence()
                    else
                        group.Gradient.Color = BuildFovGradientSequence(c1, c2, c3)
                    end
                end

                local function ResolveFovFillTransparency(opacity)
                    local visible = math.clamp(tonumber(opacity) or 0.35, 0, 1)
                    return 1 - visible
                end

                local function CircleNeedsWrite(circle, vis, x, y, radius, color, trans, thickness)
                    local last = circle._akiraLast
                    if type(last) ~= 'table' then
                        return true
                    end
                    if last.vis ~= vis then
                        return true
                    end
                    if vis ~= true then
                        return false
                    end
                    if math.abs((last.x or 0) - x) > 0.6 or math.abs((last.y or 0) - y) > 0.6 then
                        return true
                    end
                    if math.abs((last.r or 0) - radius) > 0.4 then
                        return true
                    end
                    if math.abs((last.t or 0) - trans) > 0.01 then
                        return true
                    end
                    if thickness and math.abs((last.th or 0) - thickness) > 0.05 then
                        return true
                    end
                    local lc = last.c
                    if color and (not lc or math.abs(lc.R - color.R) > 0.004 or math.abs(lc.G - color.G) > 0.004 or math.abs(lc.B - color.B) > 0.004) then
                        return true
                    end
                    return false
                end

                local function ApplyFovCircle(circle, vis, pos, radius, color, trans, thickness)
                    if not circle then
                        return
                    end
                    local x = pos and pos.X or 0
                    local y = pos and pos.Y or 0
                    if not CircleNeedsWrite(circle, vis, x, y, radius or 0, color, trans or 0, thickness) then
                        return
                    end
                    circle.Visible = vis
                    if vis then
                        circle.Position = pos
                        circle.Radius = radius
                        if color then
                            circle.Color = color
                        end
                        circle.Transparency = trans
                        if thickness then
                            circle.Thickness = thickness
                        end
                        if circle.NumSides ~= 64 then
                            pcall(function() circle.NumSides = 64 end)
                        end
                    end
                    circle._akiraLast = {
                        vis = vis,
                        x = x,
                        y = y,
                        r = radius or 0,
                        c = color,
                        t = trans or 0,
                        th = thickness or 0,
                    }
                end

                local function RenderCustomFovCircle(group, show, radius, baseColor, rainbow, rainbowSpeed, glow, glowColorOverride, fill, fillColor, fillOpacity, thickness, opacity, pointerPos, gradientStyle)
                    if not show or type(radius) ~= 'number' or radius <= 0 then
                        group:Hide()
                        return
                    end

                    pointerPos = pointerPos or AimbotBridge.GetAimbotPointerPosition()

                    local mainColor
                    if rainbow then
                        local speed = tonumber(rainbowSpeed) or 1
                        local hue = (tick() * (speed * 0.25)) % 1
                        mainColor = Color3.fromHSV(hue, 0.85, 1)
                    else
                        mainColor = baseColor or Color3.fromRGB(255, 70, 70)
                    end

                    local th = math.max(tonumber(thickness) or 1.5, 1)
                    local trans = math.clamp(tonumber(opacity) or 0.72, 0.05, 1)
                    local useGradient = gradientStyle and gradientStyle.enabled == true
                    if useGradient then
                        useGradient = group:EnsureGradientOverlay() == true
                    end
                    local showFill = fill == true or useGradient == true
                    local dFillTrans = ResolveFovFillTransparency(fillOpacity)

                    if useGradient and showFill then
                        ApplyFovCircle(group.Fill, false)
                        local now = tick()
                        local speed = tonumber(gradientStyle.speed) or 1
                        local animate = gradientStyle.animate == true
                        local cycle = animate and ((now * speed * 0.18) % 1) or 0
                        local c1 = gradientStyle.color1 or mainColor
                        local c2 = gradientStyle.color2 or mainColor:Lerp(Color3.new(1, 1, 1), 0.35)
                        local c3 = gradientStyle.color3 or c1
                        if rainbow then
                            local hue = (now * ((tonumber(rainbowSpeed) or 1) * 0.25)) % 1
                            c1 = Color3.fromHSV(hue, 0.9, 1)
                            c2 = Color3.fromHSV((hue + 0.33) % 1, 0.85, 1)
                            c3 = Color3.fromHSV((hue + 0.66) % 1, 0.9, 1)
                        end
                        local diameter = math.max(radius * 2, 2)
                        group.GradientFill.Visible = true
                        group.GradientFill.Position = UDim2.fromOffset(pointerPos.X, pointerPos.Y)
                        if group._lastDiam ~= diameter then
                            group.GradientFill.Size = UDim2.fromOffset(diameter, diameter)
                            group._lastDiam = diameter
                        end
                        if group._lastFillTrans ~= dFillTrans then
                            group.GradientFill.BackgroundTransparency = dFillTrans
                            group._lastFillTrans = dFillTrans
                        end
                        ApplyCachedFovGradient(group, rainbow, c1, c2, c3)
                        if animate then
                            group.Gradient.Rotation = (now * speed * 48) % 360
                        elseif group.Gradient.Rotation ~= 45 then
                            group.Gradient.Rotation = 45
                        end
                        mainColor = SampleFovGradientColor(c1, c2, c3, cycle)
                    else
                        if group.GradientFill and group.GradientFill.Visible then
                            group.GradientFill.Visible = false
                        end
                        if fill then
                            local effectiveFillColor = rainbow and mainColor or (fillColor or mainColor)
                            ApplyFovCircle(group.Fill, dFillTrans < 0.995, pointerPos, math.max(radius - (th * 0.5), 0), effectiveFillColor, dFillTrans)
                        else
                            ApplyFovCircle(group.Fill, false)
                        end
                    end

                    if glow then
                        local effectiveGlowColor = rainbow and mainColor or (glowColorOverride or mainColor)
                        ApplyFovCircle(group.Glow1, true, pointerPos, radius, effectiveGlowColor, math.clamp(trans * 0.35, 0, 1), th + 2)
                        ApplyFovCircle(group.Glow2, true, pointerPos, radius, effectiveGlowColor, math.clamp(trans * 0.16, 0, 1), th + 4.5)
                    else
                        ApplyFovCircle(group.Glow1, false)
                        ApplyFovCircle(group.Glow2, false)
                    end

                    ApplyFovCircle(group.Outline, true, pointerPos, radius, mainColor, trans, th)
                end

                local function ResolveTargetScreenPosition(targetInfo, allowOffscreen)
                    if not targetInfo then
                        return nil
                    end
                    local targetPart = targetInfo.part
                    if not targetPart or not targetPart.Parent then
                        return nil
                    end
                    local subject = targetInfo.instance or (targetInfo.player and targetInfo.player.Character)
                    if subject then
                        local humanoid = subject:FindFirstChildOfClass('Humanoid')
                        if humanoid and humanoid.Health <= 0 then
                            return nil
                        end
                    end
                    local worldPos = targetPart.Position or targetInfo.worldPosition
                    if not worldPos then
                        return nil
                    end
                    local camera = Workspace.CurrentCamera
                    if not camera then
                        return nil
                    end
                    local screenPos, onScreen = AimbotBridge.WorldToAimbotScreen(worldPos, camera)
                    if onScreen and screenPos then
                        return screenPos
                    end
                    if not allowOffscreen then
                        return nil
                    end

                    -- Off-screen / behind camera projection onto viewport border
                    local viewport = camera.ViewportSize or Vector2.new(1920, 1080)
                    local center = Vector2.new(viewport.X * 0.5, viewport.Y * 0.5)
                    local camCFrame = camera.CFrame
                    local localVec = camCFrame:PointToObjectSpace(worldPos)
                    local dir
                    if localVec.Z >= 0 then
                        dir = Vector2.new(localVec.X, -localVec.Y)
                    else
                        local projected = camera:WorldToViewportPoint(worldPos)
                        dir = Vector2.new(projected.X - center.X, projected.Y - center.Y)
                    end
                    if dir.Magnitude < 0.001 then
                        dir = Vector2.new(0, 1)
                    end
                    local unitDir = dir.Unit
                    local margin = 60
                    local distX = (math.abs(unitDir.X) > 1e-5) and (((unitDir.X > 0 and (viewport.X - margin - center.X) or (margin - center.X)) / unitDir.X)) or math.huge
                    local distY = (math.abs(unitDir.Y) > 1e-5) and (((unitDir.Y > 0 and (viewport.Y - margin - center.Y) or (margin - center.Y)) / unitDir.Y)) or math.huge
                    local maxDist = math.min(math.abs(distX), math.abs(distY))
                    return center + unitDir * maxDist
                end

                local function ReadFovGradientStyle(prefix)
                    local mix = Options[prefix .. '_FOVGradMix']
                    local mixValue = mix and mix.Value
                    local color1 = parseColorAndAlpha(Options[prefix .. '_FOVGrad1'] and Options[prefix .. '_FOVGrad1'].Value)
                    local color2 = parseColorAndAlpha(Options[prefix .. '_FOVGrad2'] and Options[prefix .. '_FOVGrad2'].Value)
                    local color3 = parseColorAndAlpha(Options[prefix .. '_FOVGrad3'] and Options[prefix .. '_FOVGrad3'].Value)
                    if (not color1 or not color2 or not color3) and type(mixValue) == 'table' then
                        color1 = color1 or parseColorAndAlpha(mixValue[1] or mixValue.Color1)
                        color2 = color2 or parseColorAndAlpha(mixValue[2] or mixValue.Color2)
                        color3 = color3 or parseColorAndAlpha(mixValue[3] or mixValue.Color3)
                    end
                    return {
                        enabled = Toggles[prefix .. '_FOVGradient'] and Toggles[prefix .. '_FOVGradient'].Value == true,
                        animate = Toggles[prefix .. '_FOVGradientAnimate'] and Toggles[prefix .. '_FOVGradientAnimate'].Value == true,
                        speed = Options[prefix .. '_FOVGradientSpeed'] and Options[prefix .. '_FOVGradientSpeed'].Value or 1,
                        color1 = color1,
                        color2 = color2,
                        color3 = color3,
                    }
                end

                local lastFovCircleAt = 0
                AimbotBridge.UpdateAimbotFovCircle = function(aimAssistActive, cameraAimActive)
                    local nowClock = os.clock()
                    if nowClock - lastFovCircleAt < 0.02 then
                        return
                    end
                    lastFovCircleAt = nowClock

                    local pointerPos = AimbotBridge.GetAimbotPointerPosition()

                    -- 1. Aimbot (Direct Aim) FOV Circle: always shown if showAimFov is enabled
                    local showAimFov = Toggles.P2S2_ShowFOV and Toggles.P2S2_ShowFOV.Value == true
                    if showAimFov then
                        local radius = Options.P2S2_FOVRadius and Options.P2S2_FOVRadius.Value or 250
                        local baseColor = parseColorAndAlpha(Options.P2S2_FOVColor and Options.P2S2_FOVColor.Value) or Color3.fromRGB(255, 70, 70)
                        local rainbow = Toggles.P2S2_FOVRainbow and Toggles.P2S2_FOVRainbow.Value == true
                        local rainbowSpeed = Options.P2S2_FOVRainbowSpeed and Options.P2S2_FOVRainbowSpeed.Value or 1
                        local glow = Toggles.P2S2_FOVGlow and Toggles.P2S2_FOVGlow.Value == true
                        local glowColor = parseColorAndAlpha(Options.P2S2_FOVGlowColor and Options.P2S2_FOVGlowColor.Value) or baseColor
                        local fill = Toggles.P2S2_FOVFill and Toggles.P2S2_FOVFill.Value == true
                        local fillColor = parseColorAndAlpha(Options.P2S2_FOVFillColor and Options.P2S2_FOVFillColor.Value) or baseColor
                        local fillOpacity = Options.P2S2_FOVFillTransparency and Options.P2S2_FOVFillTransparency.Value or 0.35
                        local thickness = Options.P2S2_FOVThickness and Options.P2S2_FOVThickness.Value or 1.5
                        local opacity = Options.P2S2_FOVTransparency and Options.P2S2_FOVTransparency.Value or 0.72

                        local aimbotPos = pointerPos
                        local followAimFov = Toggles.P2S2_FollowFOV and Toggles.P2S2_FollowFOV.Value == true
                        local alwaysFollowAim = Toggles.P2S2_AlwaysFollowFOV and Toggles.P2S2_AlwaysFollowFOV.Value == true
                        if followAimFov or alwaysFollowAim then
                            local aimbotTarget = RivalsRuntimeBridge.CurrentCameraAimTarget or AimbotSilentState.HookTarget
                            if not aimbotTarget then
                                local cache = RivalsRuntimeBridge._AimbotSweepCache
                                if cache and (nowClock - (cache.at or 0)) < 0.2 then
                                    aimbotTarget = cache.result
                                end
                            end
                            if not aimbotTarget and alwaysFollowAim and type(RivalsRuntimeBridge.GetBestAimbotTarget) == 'function' then
                                local cache = RivalsRuntimeBridge._AimbotFovCircleTargetCache
                                if not cache or (nowClock - cache.at) > 0.15 then
                                    aimbotTarget = RivalsRuntimeBridge.GetBestAimbotTarget(false, true, 'Auto', 9999)
                                    RivalsRuntimeBridge._AimbotFovCircleTargetCache = { at = nowClock, target = aimbotTarget }
                                else
                                    aimbotTarget = cache.target
                                end
                            end
                            local targetPos = ResolveTargetScreenPosition(aimbotTarget, alwaysFollowAim)
                            if targetPos then
                                aimbotPos = targetPos
                            end
                        end
                        if not AimbotFovDrawings._smoothedPos then
                            AimbotFovDrawings._smoothedPos = aimbotPos
                        end
                        local dt = math.clamp(nowClock - (AimbotFovDrawings._lastAt or nowClock), 0.001, 0.1)
                        AimbotFovDrawings._lastAt = nowClock
                        local lerpSpeed = (followAimFov or alwaysFollowAim) and 35 or 20
                        local lerpAlpha = math.clamp(1 - math.exp(-dt * lerpSpeed), 0, 1)
                        AimbotFovDrawings._smoothedPos = AimbotFovDrawings._smoothedPos:Lerp(aimbotPos, lerpAlpha)
                        aimbotPos = AimbotFovDrawings._smoothedPos

                        RenderCustomFovCircle(AimbotFovDrawings, true, radius, baseColor, rainbow, rainbowSpeed, glow, glowColor, fill, fillColor, fillOpacity, thickness, opacity, aimbotPos, ReadFovGradientStyle('P2S2'))
                    else
                        AimbotFovDrawings:Hide()
                        AimbotFovDrawings._smoothedPos = nil
                    end

                    -- 2. Silent Aim FOV Circle: always shown if showSilentFov is enabled
                    local showSilentFov = Toggles.P2S1T5 and Toggles.P2S1T5.Value == true
                    if showSilentFov then
                        local radius = Options.P2S1S2 and Options.P2S1S2.Value or 282
                        local baseColor = parseColorAndAlpha(Options.P2S1_FOVColor and Options.P2S1_FOVColor.Value) or Color3.fromRGB(70, 130, 255)
                        local rainbow = Toggles.P2S1_FOVRainbow and Toggles.P2S1_FOVRainbow.Value == true
                        local rainbowSpeed = Options.P2S1_FOVRainbowSpeed and Options.P2S1_FOVRainbowSpeed.Value or 1
                        local glow = Toggles.P2S1_FOVGlow and Toggles.P2S1_FOVGlow.Value == true
                        local glowColor = parseColorAndAlpha(Options.P2S1_FOVGlowColor and Options.P2S1_FOVGlowColor.Value) or baseColor
                        local fill = Toggles.P2S1_FOVFill and Toggles.P2S1_FOVFill.Value == true
                        local fillColor = parseColorAndAlpha(Options.P2S1_FOVFillColor and Options.P2S1_FOVFillColor.Value) or baseColor
                        local fillOpacity = Options.P2S1_FOVFillTransparency and Options.P2S1_FOVFillTransparency.Value or 0.35
                        local thickness = Options.P2S1_FOVThickness and Options.P2S1_FOVThickness.Value or 1.5
                        local opacity = Options.P2S1_FOVTransparency and Options.P2S1_FOVTransparency.Value or 0.72

                        local silentPos = pointerPos
                        local followSilentFov = Toggles.P2S1_FollowFOV and Toggles.P2S1_FollowFOV.Value == true
                        local alwaysFollowSilent = Toggles.P2S1_AlwaysFollowFOV and Toggles.P2S1_AlwaysFollowFOV.Value == true
                        if followSilentFov or alwaysFollowSilent then
                            local silentTarget = AimbotSilentState.HookTarget or RivalsRuntimeBridge.CurrentCameraAimTarget
                            if not silentTarget then
                                local cache = RivalsRuntimeBridge._AimbotSweepCache
                                if cache and (nowClock - (cache.at or 0)) < 0.2 then
                                    silentTarget = cache.result
                                end
                            end
                            if not silentTarget and alwaysFollowSilent and type(RivalsRuntimeBridge.GetBestAimbotTarget) == 'function' then
                                silentTarget = RivalsRuntimeBridge.GetBestAimbotTarget(false, true, 'Auto', 9999)
                            end
                            local targetPos = ResolveTargetScreenPosition(silentTarget, alwaysFollowSilent)
                            if targetPos then
                                silentPos = targetPos
                            end
                        end
                        if not SilentFovDrawings._smoothedPos then
                            SilentFovDrawings._smoothedPos = silentPos
                        end
                        local sdt = math.clamp(nowClock - (SilentFovDrawings._lastAt or nowClock), 0.001, 0.1)
                        SilentFovDrawings._lastAt = nowClock
                        local sLerpSpeed = (followSilentFov or alwaysFollowSilent) and 35 or 20
                        local sLerpAlpha = math.clamp(1 - math.exp(-sdt * sLerpSpeed), 0, 1)
                        SilentFovDrawings._smoothedPos = SilentFovDrawings._smoothedPos:Lerp(silentPos, sLerpAlpha)
                        silentPos = SilentFovDrawings._smoothedPos

                        RenderCustomFovCircle(SilentFovDrawings, true, radius, baseColor, rainbow, rainbowSpeed, glow, glowColor, fill, fillColor, fillOpacity, thickness, opacity, silentPos, ReadFovGradientStyle('P2S1'))
                    else
                        SilentFovDrawings:Hide()
                        SilentFovDrawings._smoothedPos = nil
                    end
                end

                AimbotBridge.IsAimbotShootInputHeld = function()
                    if not AimbotBridge.CanUseAimbotWithItem(AimbotBridge.ResolveAimbotEquippedItem()) then
                        return false
                    end

                    local touchActive = AimbotInputState.TouchCount > 0
                    return AimbotInputState.LeftMouse or AimbotInputState.RightMouse or touchActive
                end
            end

            do
                AimbotBridge.ReadAimbotShootRemaining = function(item)
                    local shootCooldown = item and rawget(item, '_shoot_cooldown')
                    if type(shootCooldown) == 'number' then
                        return math.max(shootCooldown - tick(), 0)
                    end
                    return 0
                end

                AimbotBridge.ReadAimbotReloadRemaining = function(item)
                    local reloadCooldown = item and rawget(item, '_reload_cooldown')
                    if type(reloadCooldown) == 'number' then
                        return math.max(reloadCooldown - tick(), 0)
                    end
                    return 0
                end

                AimbotBridge.ReadAimbotLastShot = function(item)
                    local lastShot = item and rawget(item, '_last_shot')
                    if type(lastShot) == 'number' then
                        return lastShot
                    end
                    return nil
                end

                AimbotBridge.ReadAimbotIsCharging = function(item)
                    return item and rawget(item, '_is_charging') == true
                end

                local function IsAimbotKatanaDeflectCheckEnabled()
                    return Toggles.P2S1T8 and Toggles.P2S1T8.Value == true
                end

                local AIMBOT_KATANA_DEFLECT_BYPASS_ITEMS = {
                    ['Slingshot'] = true,
                    ['Bow'] = true,
                    ['Exogun'] = true,
                    ['Spray'] = true,
                    ['Flamethrower'] = true,
                    ['Grenade Launcher'] = true,
                    ['RPG'] = true,
                    ['Crossbow'] = true,
                    ['Daggers'] = true,
                }

                local function IsAimbotKatanaDeflectBypassItem(item)
                    if not item then
                        return false
                    end

                    return AIMBOT_KATANA_DEFLECT_BYPASS_ITEMS[item.Name] == true
                end

                RivalsRuntimeBridge.IsRivalsKatanaDeflectActiveItem = function(item)
                    if not item or item.Name ~= 'Katana' then
                        return false
                    end

                    local now = tick()
                    local attackCooldown = rawget(item, '_attack_cooldown')
                    local deflectCooldown = rawget(item, '_deflect_cooldown')
                    local deflectHash = rawget(item, '_deflect_hash')
                    return type(attackCooldown) == 'number' and attackCooldown > now
                        and type(deflectCooldown) == 'number' and deflectCooldown > now
                        and type(deflectHash) == 'number' and deflectHash % 2 == 1
                end

                AimbotBridge.ShouldIgnoreAimbotKatanaDeflectTarget = function(player, localItem)
                    if not player or not IsAimbotKatanaDeflectCheckEnabled() or IsAimbotKatanaDeflectBypassItem(localItem) then
                        return false
                    end

                    local fighter = TrackedFightersByPlayer[player]
                    return RivalsRuntimeBridge.IsRivalsKatanaDeflectActiveItem(fighter and fighter.EquippedItem or nil)
                end

                AimbotBridge.IsAimbotSilentShotHookItem = function(item)
                    if not AimbotBridge.CanUseTriggerbotWithItem(item) then
                        return false
                    end

                    local info = item and item.Info or nil
                    local hasTimedShotCooldown = type(info and info.ShootCooldown) == 'number'
                        or type(info and info.ShootBurstCooldown) == 'number'
                        or type(info and info.ShootBurst) == 'number'
                        or type(info and info.QuickShotCooldown) == 'number'
                        or type(info and info.ChargeReleaseCooldown) == 'number'
                        or type(info and info.BladeCooldown) == 'number'
                    local hasMeleeAttackCooldown = type(info and info.AttackCooldown) == 'number' and ((info.Class == 'Melee') or (info.Type == 'Melee'))
                    return item ~= nil
                        and type(item.StartShooting) == 'function'
                        and (hasTimedShotCooldown or hasMeleeAttackCooldown)
                end

                AimbotBridge.ShouldUseAimbotSilentContinuousAim = function(item)
                    if item and item.Name == 'Flamethrower' then
                        return rawget(item, '_is_using') == true
                    end

                    if not AimbotBridge.IsAimbotSilentShotHookItem(item) then
                        return true
                    end

                    return AimbotBridge.ReadAimbotIsCharging(item)
                end

            end
            end)()

            ;(function() LPH_ATTRIBUTES(VM(NONE))
            local function ResolveAimbotSilentDebugEnabled()
                return Toggles.P9S2T1 and Toggles.P9S2T1.Value == true
            end

            local function ReadAimbotSilentToggle(toggleId, fallback)
                local toggle = Toggles[toggleId]
                if toggle ~= nil then
                    return toggle.Value == true
                end
                return fallback == true
            end

            local function ReleaseTriggerbotMouseHold()
                if not AimbotSilentConnections.TriggerbotHoldingMouse then
                    return
                end

                local holdX = AimbotSilentConnections.TriggerbotHoldX or 0
                local holdY = AimbotSilentConnections.TriggerbotHoldY or 0
                local virtualInputManager = Instance.new('VirtualInputManager')
                virtualInputManager:SendMouseButtonEvent(holdX, holdY, 0, false, game, 1)
                AimbotSilentConnections.TriggerbotHoldingMouse = false
                AimbotSilentConnections.TriggerbotHoldX = nil
                AimbotSilentConnections.TriggerbotHoldY = nil
            end

            AimbotBridge.ResetTriggerbotReactionState = function()
                AimbotSilentConnections.TriggerbotTarget = nil
                AimbotSilentConnections.TriggerbotTargetAcquiredAt = 0
            end

            AimbotBridge.ResetCameraAimRandomState = function()
                AimbotSilentConnections.CameraAimRandomTarget = nil
                AimbotSilentConnections.CameraAimRandomPart = nil
                RivalsRuntimeBridge.CurrentCameraAimTarget = nil
            end

            local function DisconnectAimbotSilentConnections()
                ReleaseTriggerbotMouseHold()

                for _, connectionName in ipairs({ 'Shot', 'ProjectileShot' }) do
                    local connection = AimbotSilentConnections[connectionName]
                    if connection then
                        pcall(function()
                            connection:Disconnect()
                        end)
                    end
                end

                AimbotSilentConnections.Shot = nil
                AimbotSilentConnections.ProjectileShot = nil

                local hookedItem = AimbotSilentConnections.HookedItem
                local originalStartShooting = AimbotSilentConnections.OriginalStartShooting
                if hookedItem and originalStartShooting and hookedItem.StartShooting == AimbotSilentConnections.WrappedStartShooting then
                    hookedItem.StartShooting = RivalsModsState.ResolveGunStartShootingBase(originalStartShooting)
                end

                AimbotSilentConnections.HookedItem = nil
                AimbotSilentConnections.OriginalStartShooting = nil
                AimbotSilentConnections.WrappedStartShooting = nil
            end

            local function ResetAimbotRuntimeState()
                DisconnectAimbotSilentConnections()
                AimbotSilentState.Item = nil
                AimbotSilentState.HookTarget = nil
                AimbotSilentState.HookTargetCapturedAt = 0
                AimbotSilentState.ShotPrimeDepth = 0
                AimbotSilentState.HitChanceKey = nil
                AimbotSilentState.HitChancePass = true
                AimbotSilentState.HitChanceAt = nil
                AimbotSilentState.RaycastDestination = nil
            end

            local function EnsureAimbotSilentConnections(item)
                local state = AimbotSilentState
                if state.Item ~= item then
                    DisconnectAimbotSilentConnections()
                    state.Item = item
                    state.LastShot = AimbotBridge.ReadAimbotLastShot(item)
                    state.LastShotChangedAt = 0
                    state.ShotSignalAt = 0
                    state.ProjectileShotAt = 0
                    state.HookTarget = nil
                    state.HookTargetCapturedAt = 0
                end

                if not item then
                    return
                end

                if not AimbotSilentConnections.Shot and type(item.Shot) == 'table' and type(item.Shot.Connect) == 'function' then
                    AimbotSilentConnections.Shot = item.Shot:Connect(GuardRivalsCallback('Aimbot_Shot', function()
                        AimbotSilentState.ShotSignalAt = tick()
                    end))
                end

                if not AimbotSilentConnections.ProjectileShot and type(item.ProjectileShot) == 'table' and type(item.ProjectileShot.Connect) == 'function' then
                    AimbotSilentConnections.ProjectileShot = item.ProjectileShot:Connect(GuardRivalsCallback('Aimbot_ProjectileShot', function()
                        AimbotSilentState.ProjectileShotAt = tick()
                    end))
                end
            end

            local function ResolveAimbotSilentHoldWindow(item)
                local holdWindow = 0
                local info = item and item.Info or nil

                if ReadAimbotSilentToggle('P9S2T8', true) and type(info and info.ShootCooldown) == 'number' then
                    holdWindow = math.max(holdWindow, info.ShootCooldown)
                end

                if ReadAimbotSilentToggle('P9S2T10', true) and type(info and info.ShootBurstCooldown) == 'number' then
                    holdWindow = math.max(holdWindow, info.ShootBurstCooldown)
                end

                if ReadAimbotSilentToggle('P9S2T11', true) and type(info and info.QuickShotCooldown) == 'number' then
                    holdWindow = math.max(holdWindow, info.QuickShotCooldown)
                end

                if ReadAimbotSilentToggle('P9S2T18', true) and type(info and info.ChargeReleaseCooldown) == 'number' then
                    holdWindow = math.max(holdWindow, info.ChargeReleaseCooldown)
                end

                return holdWindow
            end

            local function ResolveAimbotSilentHookTargetCacheWindow(item)
                local info = item and item.Info or nil
                local cacheWindow = math.huge

                local function consider(window)
                    if type(window) == 'number' and window > 0 then
                        cacheWindow = math.min(cacheWindow, window)
                    end
                end

                consider(info and info.ShootBurstCooldown)
                consider(info and info.QuickShotCooldown)
                consider(info and info.ShootCooldown)
                consider(info and info.ChargeReleaseCooldown)

                if cacheWindow == math.huge then
                    return 1 / 30
                end

                return math.clamp(cacheWindow, 1 / 60, 0.08)
            end

            AimbotBridge.ResolveAimbotSilentDebugEnabled = ResolveAimbotSilentDebugEnabled
            AimbotBridge.ReadAimbotSilentToggle = ReadAimbotSilentToggle
            AimbotBridge.DisconnectAimbotSilentConnections = DisconnectAimbotSilentConnections
            AimbotBridge.ResetAimbotRuntimeState = ResetAimbotRuntimeState
            AimbotBridge.EnsureAimbotSilentConnections = EnsureAimbotSilentConnections
            AimbotBridge.ResolveAimbotSilentHoldWindow = ResolveAimbotSilentHoldWindow
            AimbotBridge.ResolveAimbotSilentHookTargetCacheWindow = ResolveAimbotSilentHookTargetCacheWindow
            AimbotBridge.ReleaseTriggerbotMouseHold = ReleaseTriggerbotMouseHold
            end)()

