            ;(function() LPH_ATTRIBUTES(VM(NONE))
            local function MapValuesClose(a, b)
                if a == b then return true end
                local ta = typeof(a)
                if ta ~= typeof(b) then return false end
                if ta == 'number' then
                    return math.abs(a - b) < 1e-3
                end
                if ta == 'Color3' then
                    local ar, ag, ab = tonumber(a.R), tonumber(a.G), tonumber(a.B)
                    local br, bg, bb = tonumber(b.R), tonumber(b.G), tonumber(b.B)
                    if not ar or not ag or not ab or not br or not bg or not bb then return false end
                    return math.abs(ar - br) < 1e-3 and math.abs(ag - bg) < 1e-3 and math.abs(ab - bb) < 1e-3
                end
                return false
            end

            local RivalsMapParser = {
                IsMapStreaming = false,
                CurrentMapName = nil,
                MapNameExpiresAt = 0,
                ActiveEnvironmentId = nil,
                CachedMapContext = nil,
                CachedMapModel = nil,
                CachedMapAnchor = nil,
                LastContextCheckAt = 0,
                KnownMaps = {
                    'Arena', 'Crossroads', 'Dust', 'Depot', 'Facility',
                    'Rooftop', 'Cargo', 'Subzero', 'Colosseum', 'Underground',
                    'Backrooms', 'Shooting Range', 'Trainyard', 'Cyberpunk', 'Construction',
                },
                ResolvedMapsCache = nil,
                StabilityCallbacks = {},
                StabilityActive = false,
                LastBrightness = nil,
                StableSince = 0,
                StabilityStartedAt = 0,
                HardCapSeconds = 6,
                RequiredStableSeconds = 1.0,
                LifecycleBound = false,
                DuelControllerCache = nil,
            }
            RivalsRuntimeBridge.MapParser = RivalsMapParser

            function RivalsMapParser.InvalidateCaches()
                RivalsMapParser.CurrentMapName = nil
                RivalsMapParser.MapNameExpiresAt = 0
                RivalsMapParser.ActiveEnvironmentId = nil
                RivalsMapParser.CachedMapContext = nil
                RivalsMapParser.CachedMapModel = nil
                RivalsMapParser.CachedMapAnchor = nil
                RivalsMapParser.LastContextCheckAt = 0
            end

            function RivalsMapParser.StartMapStreamWatch(reason)
                RivalsMapParser.IsMapStreaming = true
                RivalsMapParser.InvalidateCaches()
                local world = RivalsRuntimeBridge.WorldVisuals
                if world then
                    world.LightingReady = false
                    world.GuardSettleUntil = os.clock() + 8.0
                    if world.LightingGuard then
                        world.LightingGuard.Writing = true
                    end
                end
                RivalsMapParser.BeginStabilityWatcher()
            end

            function RivalsMapParser.WaitForMapStability(onStable)
                local world = RivalsRuntimeBridge.WorldVisuals
                if not RivalsMapParser.IsMapStreaming and world and world.LightingReady then
                    if onStable then
                        task.defer(onStable)
                    end
                    return
                end
                if onStable then
                    table.insert(RivalsMapParser.StabilityCallbacks, onStable)
                end
                RivalsMapParser.BeginStabilityWatcher()
            end

            function RivalsMapParser.BeginStabilityWatcher()
                if RivalsMapParser.StabilityActive then
                    return
                end
                RivalsMapParser.StabilityActive = true
                RivalsMapParser.StabilityStartedAt = os.clock()
                RivalsMapParser.StableSince = os.clock()
                RivalsMapParser.LastBrightness = nil

                task.spawn(function()
                    local lighting = game:GetService('Lighting')
                    pcall(function()
                        RivalsMapParser.LastBrightness = lighting.Brightness
                    end)

                    while not shutting_down and (os.clock() - RivalsMapParser.StabilityStartedAt < RivalsMapParser.HardCapSeconds) do
                        task.wait(0.25)
                        local ok, current = pcall(function()
                            return lighting.Brightness
                        end)
                        if ok then
                            if RivalsMapParser.LastBrightness == nil or not MapValuesClose(current, RivalsMapParser.LastBrightness) then
                                RivalsMapParser.LastBrightness = current
                                RivalsMapParser.StableSince = os.clock()
                            elseif (os.clock() - RivalsMapParser.StableSince) >= RivalsMapParser.RequiredStableSeconds then
                                break
                            end
                        end
                    end

                    RivalsMapParser.StabilityActive = false
                    RivalsMapParser.IsMapStreaming = false

                    local world = RivalsRuntimeBridge.WorldVisuals
                    if world then
                        if world.LightingGuard then
                            world.LightingGuard.Writing = false
                        end
                        world.GuardSettleUntil = os.clock() + 1.5
                        world.LightingReady = true
                    end

                    local cbs = RivalsMapParser.StabilityCallbacks
                    RivalsMapParser.StabilityCallbacks = {}
                    for _, cb in ipairs(cbs) do
                        task.spawn(pcall, cb)
                    end

                    if world and world.Initialized and not shutting_down then
                        task.defer(function()
                            pcall(world.RefreshAll)
                        end)
                    end
                end)
            end

            function RivalsMapParser.AttachLifecycleListeners()
                if RivalsMapParser.LifecycleBound then
                    return
                end
                RivalsMapParser.LifecycleBound = true
                pcall(function()
                    Workspace:GetAttributeChangedSignal('MatchMap'):Connect(function()
                        RivalsMapParser.StartMapStreamWatch('MatchMap changed')
                    end)
                end)
                pcall(function()
                    Workspace:GetAttributeChangedSignal('MapName'):Connect(function()
                        RivalsMapParser.StartMapStreamWatch('MapName changed')
                    end)
                end)
            end

            function RivalsMapParser.ResolveCurrentMapName()
                local now = os.clock()
                if RivalsMapParser.CurrentMapName and now < RivalsMapParser.MapNameExpiresAt then
                    return RivalsMapParser.CurrentMapName
                end

                for _, attributeName in ipairs({'MapName', 'MatchMap'}) do
                    local name = Workspace:GetAttribute(attributeName)
                    if type(name) == 'string' and name ~= '' then
                        RivalsMapParser.CurrentMapName = name
                        RivalsMapParser.MapNameExpiresAt = now + 1.0
                        return name
                    end
                end

                local duelController = RivalsMapParser.DuelControllerCache
                if not duelController and IsReplicatedStateReady() then
                    local playerScripts = LP:FindFirstChild('PlayerScripts')
                    local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                    local duelControllerModule = controllers and controllers:FindFirstChild('DuelController')
                    if duelControllerModule then
                        local ok, dc = pcall(require, duelControllerModule)
                        if ok and type(dc) == 'table' then
                            RivalsMapParser.DuelControllerCache = dc
                            duelController = dc
                        end
                    end
                end

                if duelController then
                    local duel = duelController.CurrentObject
                    if duel then
                        if type(duel.GetMapName) == 'function' then
                            local mapOk, name = pcall(duel.GetMapName, duel)
                            if mapOk and type(name) == 'string' and name ~= '' then
                                RivalsMapParser.CurrentMapName = name
                                RivalsMapParser.MapNameExpiresAt = now + 1.0
                                return name
                            end
                        end
                        if type(duel.Get) == 'function' then
                            for _, key in ipairs({'MapName', 'Map'}) do
                                local mapOk, name = pcall(duel.Get, duel, key)
                                if mapOk and type(name) == 'string' and name ~= '' then
                                    RivalsMapParser.CurrentMapName = name
                                    RivalsMapParser.MapNameExpiresAt = now + 1.0
                                    return name
                                end
                            end
                        end
                        local name = duel.MapName or duel.Map
                        if type(name) == 'string' and name ~= '' then
                            RivalsMapParser.CurrentMapName = name
                            RivalsMapParser.MapNameExpiresAt = now + 1.0
                            return name
                        end
                    end
                end

                if RivalsMapParser.CachedMapModel and RivalsMapParser.CachedMapModel.Name and RivalsMapParser.CachedMapModel.Name ~= '' and RivalsMapParser.CachedMapModel.Name ~= 'Workspace' then
                    RivalsMapParser.CurrentMapName = RivalsMapParser.CachedMapModel.Name
                    RivalsMapParser.MapNameExpiresAt = now + 1.0
                    return RivalsMapParser.CachedMapModel.Name
                end

                return 'Default'
            end

            function RivalsMapParser.ResolveMapContext()
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                local rootPart = character and character:FindFirstChild('HumanoidRootPart') or nil
                if not character or not humanoid or humanoid.Health <= 0 or not rootPart then
                    return nil
                end

                local environmentId = character:GetAttribute('EnvironmentID')
                if environmentId == nil then
                    local fighter = ResolveLocalFighter()
                    local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                    environmentId = type(data) == 'table' and rawget(data, 'EnvironmentID') or nil
                end
                if environmentId == nil then
                    return nil
                end

                if RivalsMapParser.CachedMapContext and RivalsMapParser.ActiveEnvironmentId == environmentId
                    and RivalsMapParser.CachedMapModel and RivalsMapParser.CachedMapModel.Parent
                    and RivalsMapParser.CachedMapModel:IsDescendantOf(Workspace) then
                    local ctx = RivalsMapParser.CachedMapContext
                    ctx.Character = character
                    ctx.Humanoid = humanoid
                    ctx.RootPart = rootPart
                    return ctx
                end

                local now = os.clock()
                if now - RivalsMapParser.LastContextCheckAt < 0.25 and RivalsMapParser.CachedMapContext then
                    return RivalsMapParser.CachedMapContext
                end
                RivalsMapParser.LastContextCheckAt = now

                local tagged = game:GetService('CollectionService'):GetTagged('RaycastWhitelist' .. tostring(environmentId))
                local mapModel = tagged and tagged[1]
                local depth = 0
                while mapModel and mapModel ~= Workspace and depth < 15
                    and not (mapModel:IsA('Model') or mapModel:GetAttribute('EnvironmentID') == environmentId) do
                    mapModel = mapModel.Parent
                    depth = depth + 1
                end

                if not mapModel or mapModel == Workspace or not mapModel:IsA('PVInstance') then
                    return nil
                end

                local mapName = RivalsMapParser.ResolveCurrentMapName()
                if not mapName or mapName == 'Default' then
                    mapName = mapModel.Name
                end

                local pivot = nil
                pcall(function()
                    pivot = mapModel:GetPivot()
                end)
                pivot = pivot or CFrame.identity

                local ctx = {
                    Character = character,
                    Humanoid = humanoid,
                    RootPart = rootPart,
                    MapModel = mapModel,
                    MapAnchor = pivot,
                    MapName = mapName,
                    EnvironmentId = environmentId,
                }

                RivalsMapParser.ActiveEnvironmentId = environmentId
                RivalsMapParser.CachedMapModel = mapModel
                RivalsMapParser.CachedMapAnchor = ctx.MapAnchor
                RivalsMapParser.CachedMapContext = ctx
                return ctx
            end

            function RivalsMapParser.ResolveMapValues()
                if RivalsMapParser.ResolvedMapsCache and #RivalsMapParser.ResolvedMapsCache > 0 then
                    return RivalsMapParser.ResolvedMapsCache
                end

                local values = {}
                local seen = {}
                for _, mapName in ipairs(RivalsMapParser.KnownMaps) do
                    if not seen[mapName] then
                        seen[mapName] = true
                        values[#values + 1] = mapName
                    end
                end

                task.spawn(function()
                    local modules = ReplicatedStorage:FindFirstChild('Modules')
                    local duelLibraryModule = modules and modules:FindFirstChild('DuelLibrary')
                    if duelLibraryModule then
                        local ok, duelLibrary = pcall(require, duelLibraryModule)
                        if ok and type(duelLibrary) == 'table' then
                            local order = type(duelLibrary.MapOrder) == 'table' and duelLibrary.MapOrder or duelLibrary.Maps
                            if type(order) == 'table' then
                                for _, mapName in ipairs(order) do
                                    if type(mapName) == 'string' and mapName ~= '' and not seen[mapName] then
                                        seen[mapName] = true
                                        values[#values + 1] = mapName
                                    end
                                end
                            end
                        end
                    end
                end)

                RivalsMapParser.ResolvedMapsCache = values
                return values
            end

