            function RivalsRuntimeBridge.WorldVisuals.ReadToggle(optionId, fallback)
                local toggle = Toggles[optionId]
                if toggle and toggle.Value ~= nil then
                    return toggle.Value == true
                end
                return fallback == true
            end

            function RivalsRuntimeBridge.WorldVisuals.ReadOption(optionId, fallback)
                local option = Options[optionId]
                if option and option.Value ~= nil then
                    return option.Value
                end
                return fallback
            end

            function RivalsRuntimeBridge.WorldVisuals.ReadColor3(optionId, fallback)
                local value = RivalsRuntimeBridge.WorldVisuals.ReadOption(optionId, fallback)
                if typeof(value) == 'Color3' then
                    return value
                end
                if type(value) == 'table' then
                    local r = tonumber(value[1] or value.R or value.r)
                    local g = tonumber(value[2] or value.G or value.g)
                    local b = tonumber(value[3] or value.B or value.b)
                    if r and g and b then
                        if r > 1 or g > 1 or b > 1 then
                            return Color3.fromRGB(r, g, b)
                        end
                        return Color3.new(r, g, b)
                    end
                end
                if type(value) == 'string' then
                    local hex = value:gsub('^#', '')
                    local ok, color = pcall(Color3.fromHex, hex)
                    if ok and typeof(color) == 'Color3' then
                        return color
                    end
                end
                if typeof(fallback) == 'Color3' then
                    return fallback
                end
                return Color3.new(1, 1, 1)
            end

            function RivalsRuntimeBridge.WorldVisuals.ValuesClose(a, b)
                if a == b then
                    return true
                end
                local ta = typeof(a)
                if ta ~= typeof(b) then
                    return false
                end
                if ta == 'number' then
                    return math.abs(a - b) < 1e-3
                end
                if ta == 'Color3' then
                    local ar, ag, ab = tonumber(a.R), tonumber(a.G), tonumber(a.B)
                    local br, bg, bb = tonumber(b.R), tonumber(b.G), tonumber(b.B)
                    if not ar or not ag or not ab or not br or not bg or not bb then
                        return false
                    end
                    local dr, dg, db = ar - br, ag - bg, ab - bb
                    return (dr * dr + dg * dg + db * db) < 1e-6
                end
                return false
            end

            function RivalsRuntimeBridge.WorldVisuals.NewGuard(target)
                return {
                    Target = target,
                    Originals = {},
                    HasOriginal = {},
                    Overrides = {},
                    Writing = false,
                    Connection = nil,
                }
            end

            function RivalsRuntimeBridge.WorldVisuals.EnsureGuardWatch(guard)
                if not guard or not guard.Target or guard.Connection then
                    return
                end
                local world = RivalsRuntimeBridge.WorldVisuals
                local lastWatchRun = 0
                local ok, conn = pcall(function()
                    return guard.Target.Changed:Connect(function(property)
                        if property == 'ClockTime' or property == 'GeographicLatitude' or property == 'TimeOfDay' then
                            return
                        end
                        local mapParser = RivalsRuntimeBridge.MapParser
                        if guard.Writing or shutting_down or not world.LightingReady or (mapParser and mapParser.IsMapStreaming) then
                            return
                        end
                        local now = os.clock()
                        if (world.GuardSettleUntil and now < world.GuardSettleUntil) or (now - lastWatchRun < 0.1) then
                            return
                        end
                        local desired = guard.Overrides[property]
                        if desired == nil then
                            return
                        end
                        local currentOk, current = pcall(function()
                            return guard.Target[property]
                        end)
                        if not currentOk or world.ValuesClose(current, desired) then
                            return
                        end
                        guard.Pending = guard.Pending or {}
                        if guard.Pending[property] then
                            return
                        end
                        guard.Pending[property] = true
                        lastWatchRun = now
                        task.defer(function()
                            guard.Pending[property] = nil
                            if shutting_down or not world.LightingReady or (mapParser and mapParser.IsMapStreaming) then
                                return
                            end
                            if world.GuardSettleUntil and os.clock() < world.GuardSettleUntil then
                                return
                            end
                            local override = guard.Overrides[property]
                            if override == nil then
                                return
                            end
                            local ok2, cur = pcall(function()
                                return guard.Target[property]
                            end)
                            if not ok2 or world.ValuesClose(cur, override) then
                                return
                            end
                            guard.Writing = true
                            pcall(function()
                                guard.Target[property] = override
                            end)
                            guard.Writing = false
                        end)
                    end)
                end)
                if ok then
                    guard.Connection = conn
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.FlushGuard(guard)
                local world = RivalsRuntimeBridge.WorldVisuals
                if not guard or not guard.Target or guard.Writing then
                    return
                end
                guard.Writing = true
                for property, value in pairs(guard.Overrides) do
                    local ok, current = pcall(function()
                        return guard.Target[property]
                    end)
                    if ok and not world.ValuesClose(current, value) then
                        pcall(function()
                            guard.Target[property] = value
                        end)
                    end
                end
                guard.Writing = false
            end

            function RivalsRuntimeBridge.WorldVisuals.FlushAllGuards()
                local world = RivalsRuntimeBridge.WorldVisuals
                world.FlushGuard(world.LightingGuard)
                for _, guards in pairs(world.NativeEffectGuards) do
                    for _, guard in pairs(guards) do
                        world.FlushGuard(guard)
                    end
                end
                for _, guard in pairs(world.NativeSkyGuards) do
                    world.FlushGuard(guard)
                end
                for _, guard in pairs(world.NativeAtmosphereGuards) do
                    world.FlushGuard(guard)
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.SetGuardOverride(guard, property, value)
                if not guard or not guard.Target then
                    return false
                end
                local world = RivalsRuntimeBridge.WorldVisuals
                if world.UnsupportedLightingProperties and world.UnsupportedLightingProperties[property] then
                    return false
                end
                local capturedNow = false
                if guard.HasOriginal[property] ~= true then
                    local ok, nativeValue = pcall(function()
                        return guard.Target[property]
                    end)
                    if not ok then
                        world.UnsupportedLightingProperties = world.UnsupportedLightingProperties or {}
                        world.UnsupportedLightingProperties[property] = true
                        return false
                    end
                    guard.Originals[property] = nativeValue
                    guard.HasOriginal[property] = true
                    capturedNow = true
                end
                guard.Overrides[property] = value
                local already = false
                pcall(function()
                    already = world.ValuesClose(guard.Target[property], value)
                end)
                if already then
                    world.EnsureGuardWatch(guard)
                    return true
                end
                guard.Writing = true
                local ok = pcall(function()
                    guard.Target[property] = value
                end)
                guard.Writing = false
                if not ok then
                    guard.Overrides[property] = nil
                    if capturedNow then
                        guard.Originals[property] = nil
                        guard.HasOriginal[property] = nil
                    end
                    world.UnsupportedLightingProperties = world.UnsupportedLightingProperties or {}
                    world.UnsupportedLightingProperties[property] = true
                    return false
                end
                world.EnsureGuardWatch(guard)
                return true
            end

            function RivalsRuntimeBridge.WorldVisuals.ClearGuardOverride(guard, property)
                if not guard or guard.HasOriginal[property] ~= true then
                    return false
                end
                local nativeValue = guard.Originals[property]
                guard.Overrides[property] = nil
                guard.Writing = true
                local ok = pcall(function()
                    guard.Target[property] = nativeValue
                end)
                guard.Writing = false
                guard.Originals[property] = nil
                guard.HasOriginal[property] = nil
                return ok
            end

            function RivalsRuntimeBridge.WorldVisuals.ReconcileGuard(guard, properties, desired)
                for _, property in ipairs(properties) do
                    if desired[property] ~= nil then
                        RivalsRuntimeBridge.WorldVisuals.SetGuardOverride(guard, property, desired[property])
                    else
                        RivalsRuntimeBridge.WorldVisuals.ClearGuardOverride(guard, property)
                    end
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.DestroyGuard(guard)
                if not guard then
                    return
                end
                local properties = {}
                for property in pairs(guard.HasOriginal) do
                    properties[#properties + 1] = property
                end
                for _, property in ipairs(properties) do
                    RivalsRuntimeBridge.WorldVisuals.ClearGuardOverride(guard, property)
                end
                if guard.Connection then
                    guard.Connection:Disconnect()
                    guard.Connection = nil
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshLighting()
                local world = RivalsRuntimeBridge.WorldVisuals
                local desired = {}
                if world.ReadToggle('P1S4T2', false) then
                    desired.Ambient = world.ReadColor3('P1S4C1', Color3.new(0.231373, 0.796078, 1))
                    desired.OutdoorAmbient = world.ReadColor3('P1S4C2', Color3.new(0.003922, 0.4, 0.545098))
                end
                if world.ReadToggle('P1S4T3', false) then
                    desired.ClockTime = tonumber(world.ReadOption('P1S4S1', 12)) or 12
                end
                if world.ReadToggle('P1S4T4', false) then
                    desired.Brightness = tonumber(world.ReadOption('P1S4S2', 2)) or 2
                end
                if world.ReadToggle('P1S4T5', false) then
                    desired.ColorShift_Top = world.ReadColor3('P1S4C3', Color3.fromRGB(100, 160, 255))
                    desired.ColorShift_Bottom = world.ReadColor3('P1S4C4', Color3.fromRGB(20, 40, 90))
                end
                if world.ReadToggle('P1S4T6', false) then
                    desired.EnvironmentDiffuseScale = tonumber(world.ReadOption('P1S4S3', 0)) or 0
                end
                if world.ReadToggle('P1S4T7', false) then
                    desired.ExposureCompensation = tonumber(world.ReadOption('P1S4S4', 0)) or 0
                end
                if world.ReadToggle('P1S4T8', false) then
                    desired.EnvironmentSpecularScale = tonumber(world.ReadOption('P1S4S5', 0)) or 0
                end
                if world.ReadToggle('P1S5T1', false) then
                    desired.FogColor = world.ReadColor3('P1S5C1', Color3.fromRGB(192, 192, 192))
                    desired.FogStart = tonumber(world.ReadOption('P1S5S1', 0)) or 0
                    desired.FogEnd = tonumber(world.ReadOption('P1S5S2', 100000)) or 100000
                end
                if world.ReadToggle('P1S5T2', false) then
                    desired.GeographicLatitude = tonumber(world.ReadOption('P1S5S3', 41.733)) or 41.733
                end
                if world.ReadToggle('P1S5T3', false) then
                    desired.GlobalShadows = false
                end
                if world.ReadToggle('P1S5T4', false) then
                    desired.ShadowSoftness = tonumber(world.ReadOption('P1S5S4', 0.5)) or 0.5
                end
                if world.ReadToggle('P1S5T5', false) and world.LightingReady then
                    local styleName = world.ReadOption('P1S5D1', 'Realistic')
                    if type(styleName) == 'string' and styleName ~= '' then
                        local enumOk, lightingStyle = pcall(function()
                            return Enum.LightingStyle[styleName]
                        end)
                        if enumOk and lightingStyle then
                            desired.LightingStyle = lightingStyle
                        end
                    end
                end
                if world.ReadToggle('P1S5T6', false) then
                    desired.ShadowColor = world.ReadColor3('P1S5C2', Color3.new(0.7, 0.7, 0.72))
                end
                if world.ReadToggle('P1S5T7', false) and world.LightingReady then
                    desired.PrioritizeLightingQuality = true
                end
                if world.ReadToggle('P1S8T1', false) then
                    local enumOk, tonemapperPreset = pcall(function()
                        return Enum.TonemapperPreset[world.ReadOption('P1S8D1', 'Default')]
                    end)
                    if enumOk and tonemapperPreset then
                        desired.TonemapperPreset = tonemapperPreset
                    end
                end
                world.ReconcileGuard(world.LightingGuard, world.LightingProperties, desired)
            end

            function RivalsRuntimeBridge.WorldVisuals.ApplyOwnedEffectProperties(className, effect)
                local definition = RivalsRuntimeBridge.WorldVisuals.PostEffects[className]
                if not definition or not effect then
                    return
                end
                for property, optionInfo in pairs(definition.Properties) do
                    pcall(function()
                        local value
                        if typeof(optionInfo[2]) == 'Color3' then
                            value = RivalsRuntimeBridge.WorldVisuals.ReadColor3(optionInfo[1], optionInfo[2])
                        else
                            value = RivalsRuntimeBridge.WorldVisuals.ReadOption(optionInfo[1], optionInfo[2])
                        end
                        effect[property] = value
                    end)
                end
                pcall(function()
                    effect.Enabled = true
                end)
            end

            function RivalsRuntimeBridge.WorldVisuals.GuardNativeEffect(className, effect)
                local world = RivalsRuntimeBridge.WorldVisuals
                if not effect or effect == world.OwnedEffects[className] then
                    return
                end
                local guards = world.NativeEffectGuards[className]
                if not guards then
                    guards = setmetatable({}, { __mode = 'k' })
                    world.NativeEffectGuards[className] = guards
                end
                local guard = guards[effect]
                if not guard then
                    guard = world.NewGuard(effect)
                    guards[effect] = guard
                end
                world.SetGuardOverride(guard, 'Enabled', false)
            end

            function RivalsRuntimeBridge.WorldVisuals.RestorePostEffect(className)
                local world = RivalsRuntimeBridge.WorldVisuals
                local owned = world.OwnedEffects[className]
                world.OwnedEffects[className] = nil
                if owned then
                    pcall(function()
                        owned:Destroy()
                    end)
                end
                local guards = world.NativeEffectGuards[className]
                if guards then
                    for effect, guard in pairs(guards) do
                        world.DestroyGuard(guard)
                        guards[effect] = nil
                    end
                end
                world.NativeEffectGuards[className] = nil
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshPostEffect(className)
                local world = RivalsRuntimeBridge.WorldVisuals
                local definition = world.PostEffects[className]
                if not definition or not world.ReadToggle(definition.Toggle, false) then
                    world.RestorePostEffect(className)
                    return
                end
                local owned = world.OwnedEffects[className]
                if not owned or owned.Parent == nil then
                    owned = Instance.new(className)
                    owned.Name = 'AkiraWorldVisuals_' .. className
                    world.OwnedEffects[className] = owned
                    world.ApplyOwnedEffectProperties(className, owned)
                    owned.Parent = world.Lighting
                else
                    world.ApplyOwnedEffectProperties(className, owned)
                end
                for _, child in ipairs(world.Lighting:GetChildren()) do
                    if child.ClassName == className and child ~= owned then
                        world.GuardNativeEffect(className, child)
                    end
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.NormalizeAssetId(value)
                if type(value) == 'number' then
                    return 'rbxassetid://' .. tostring(value)
                end
                if type(value) ~= 'string' then
                    return nil
                end
                value = value:match('^%s*(.-)%s*$') or ''
                if value == '' then
                    return nil
                end
                if value:match('^%d+$') then
                    return 'rbxassetid://' .. value
                end
                return value
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshAmbience()
                local world = RivalsRuntimeBridge.WorldVisuals
                local source = world.ReadToggle('P1S14T1', false)
                    and world.NormalizeAssetId(world.ReadOption('P1S14I1', '')) or nil
                if not source then
                    local owned = world.OwnedAmbience
                    world.OwnedAmbience = nil
                    world.ActiveAmbienceSource = nil
                    if owned then
                        pcall(function()
                            owned:Destroy()
                        end)
                    end
                    return
                end

                local sound = world.OwnedAmbience
                if not sound or sound.Parent == nil then
                    sound = Instance.new('Sound')
                    sound.Name = 'AkiraWorldVisuals_Ambience'
                    sound.Looped = true
                    world.OwnedAmbience = sound
                    sound.Parent = world.SoundService
                end
                sound.Volume = world.ReadOption('P1S14S1', 1)
                if world.ActiveAmbienceSource ~= source or sound.SoundId ~= source then
                    world.ActiveAmbienceSource = source
                    sound.SoundId = source
                    sound:Play()
                elseif not sound.IsPlaying then
                    sound:Play()
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.SafeNumberRange(minVal, maxVal)
                local a = tonumber(minVal) or 0
                local b = tonumber(maxVal) or a
                if a > b then
                    a, b = b, a
                end
                return NumberRange.new(a, b)
            end

            function RivalsRuntimeBridge.WorldVisuals.ScaleNumberSequence(sequence, scale)
                if typeof(sequence) ~= 'NumberSequence' then
                    return NumberSequence.new(0, 0)
                end
                local keypoints = {}
                local ok, source = pcall(function()
                    return sequence.Keypoints
                end)
                if not ok or type(source) ~= 'table' then
                    return NumberSequence.new(0, 0)
                end
                for _, keypoint in ipairs(source) do
                    local time = tonumber(keypoint.Time) or 0
                    local value = tonumber(keypoint.Value) or 0
                    local envelope = tonumber(keypoint.Envelope) or 0
                    table.insert(keypoints, NumberSequenceKeypoint.new(
                        time,
                        value * (tonumber(scale) or 1),
                        envelope * (tonumber(scale) or 1)
                    ))
                end
                if #keypoints == 0 then
                    return NumberSequence.new(0, 0)
                end
                return NumberSequence.new(keypoints)
            end

            function RivalsRuntimeBridge.WorldVisuals.ClearWeatherEmitters()
                local world = RivalsRuntimeBridge.WorldVisuals
                for _, record in ipairs(world.WeatherEmitters) do
                    if record.Emitter then
                        pcall(function()
                            record.Emitter:Destroy()
                        end)
                    end
                end
                world.WeatherEmitters = {}
                world.ActiveWeatherPreset = nil
            end

            function RivalsRuntimeBridge.WorldVisuals.DestroyWeather()
                local world = RivalsRuntimeBridge.WorldVisuals
                world.WeatherGeneration = world.WeatherGeneration + 1
                world.NextLightningAt = 0
                world.ClearWeatherEmitters()
                local part = world.OwnedWeatherPart
                world.OwnedWeatherPart = nil
                if part then
                    pcall(function()
                        part:Destroy()
                    end)
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.ReconcileWeather()
                local world = RivalsRuntimeBridge.WorldVisuals
                local intensity = math.max(0, tonumber(world.ReadOption('P1S28S1', 1)) or 1)
                local rate = math.max(0, tonumber(world.ReadOption('P1S28S2', 1)) or 1)
                local speed = math.max(0, tonumber(world.ReadOption('P1S28S3', 1)) or 1)
                local size = math.max(0, tonumber(world.ReadOption('P1S28S4', 1)) or 1)
                local glow = math.clamp(tonumber(world.ReadOption('P1S28S5', 0.6)) or 0.6, 0, 1)
                local spread = math.max(0, tonumber(world.ReadOption('P1S28S6', 25)) or 25)
                local color = world.ReadColor3('P1S28C1', Color3.new(1, 1, 1))
                if typeof(color) ~= 'Color3' then
                    color = Color3.new(1, 1, 1)
                end
                local angle = math.rad(tonumber(world.ReadOption('P1S28S9', 0)) or 0)
                local strength = tonumber(world.ReadOption('P1S28S8', 0)) or 0
                local windX = math.sin(angle) * strength
                local windZ = math.cos(angle) * strength

                local effHeight = math.clamp(tonumber(world.ReadOption('P1S28S7', 24)) or 24, 8, 80)
                for _, record in ipairs(world.WeatherEmitters) do
                    local emitter = record.Emitter
                    local spec = record.Spec
                    if emitter and emitter.Parent and spec then
                        emitter.Rate = math.clamp(spec.BaseRate * intensity * rate, 0, 1800)
                        local effSpeed = math.max(30, spec.SpeedMin * speed)
                        local targetMaxSpeed = math.max(effSpeed, spec.SpeedMax * speed)
                        emitter.Speed = world.SafeNumberRange(effSpeed, targetMaxSpeed)
                        local fallTime = (effHeight + 25) / math.max(1, effSpeed)
                        local minLife = math.max(0.45, fallTime * 0.8)
                        local maxLife = math.max(minLife, fallTime * 1.25)
                        emitter.Lifetime = world.SafeNumberRange(minLife, maxLife)
                        emitter.Size = world.ScaleNumberSequence(
                            NumberSequence.new(spec.SizeStart, spec.SizeEnd),
                            math.clamp(size, 0.2, 2.5)
                        )
                        emitter.LightEmission = math.clamp((spec.LightEmission or 0.08) * glow, 0, 0.25)
                        local spreadAngle = spec.BaseSpread * spread
                        emitter.SpreadAngle = Vector2.new(spreadAngle, spreadAngle)
                        emitter.Color = ColorSequence.new(color)
                        emitter.Acceleration = Vector3.new(windX, spec.BaseAccelerationY, windZ)
                    end
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.RebuildWeather(preset)
                local world = RivalsRuntimeBridge.WorldVisuals
                local specs = world.WeatherPresets[preset]
                world.ClearWeatherEmitters()
                if not specs or not world.OwnedWeatherPart then
                    return
                end
                world.ActiveWeatherPreset = preset
                for _, spec in ipairs(specs) do
                    local emitter = Instance.new('ParticleEmitter')
                    emitter.Name = 'AkiraWeatherEmitter'
                    emitter.Shape = Enum.ParticleEmitterShape.Box
                    emitter.EmissionDirection = Enum.NormalId.Bottom
                    emitter.Enabled = true
                    emitter.Texture = spec.Texture
                    emitter.Transparency = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, 1),
                        NumberSequenceKeypoint.new(0.15, spec.TransparencyMax),
                        NumberSequenceKeypoint.new(0.85, spec.TransparencyMax),
                        NumberSequenceKeypoint.new(1, 1),
                    })
                    emitter.Lifetime = world.SafeNumberRange(spec.LifetimeMin, spec.LifetimeMax)
                    emitter.Rotation = world.SafeNumberRange(spec.RotationMin, spec.RotationMax)
                    emitter.RotSpeed = world.SafeNumberRange(spec.RotationSpeedMin, spec.RotationSpeedMax)
                    emitter.LightInfluence = 0
                    if spec.Orientation then
                        emitter.Orientation = spec.Orientation
                    end
                    emitter.Parent = world.OwnedWeatherPart
                    table.insert(world.WeatherEmitters, {Emitter = emitter, Spec = spec})
                end
                world.ReconcileWeather()
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshWeather()
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.ReadToggle('P1S28T1', false) then
                    world.DestroyWeather()
                    return
                end

                local preset = world.ReadOption('P1S28D1', 'Heavy Rain')
                if not world.WeatherPresets[preset] then
                    preset = 'Heavy Rain'
                end
                local part = world.OwnedWeatherPart
                if not part or part.Parent == nil then
                    part = Instance.new('Part')
                    part.Name = 'AkiraWeatherEmitter'
                    part.Anchored = true
                    part.CanCollide = false
                    part.CanQuery = false
                    part.CanTouch = false
                    part.CastShadow = false
                    part.Transparency = 1
                    part.Size = Vector3.new(85, 2, 85)
                    part.Parent = Workspace
                    world.OwnedWeatherPart = part
                    world.ActiveWeatherPreset = nil
                    world.NextLightningAt = tick() + math.max(0.2, tonumber(world.ReadOption('P1S29S1', 2)) or 2)
                end
                if world.ActiveWeatherPreset ~= preset then
                    world.WeatherGeneration = world.WeatherGeneration + 1
                    world.NextLightningAt = tick() + math.max(0.2, tonumber(world.ReadOption('P1S29S1', 2)) or 2)
                    world.RebuildWeather(preset)
                else
                    world.ReconcileWeather()
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.AddLightningSegment(instances, startPosition, endPosition, color, thickness, brightness)
                local near = Instance.new('Attachment')
                near.Name = 'AkiraLightningAttachment'
                near.Position = startPosition
                near.Parent = Workspace.Terrain
                local far = Instance.new('Attachment')
                far.Name = 'AkiraLightningAttachment'
                far.Position = endPosition
                far.Parent = Workspace.Terrain
                local beam = Instance.new('Beam')
                beam.Name = 'AkiraLightningBeam'
                beam.Attachment0 = near
                beam.Attachment1 = far
                beam.Color = ColorSequence.new(color)
                beam.Width0 = thickness
                beam.Width1 = math.max(0.05, thickness * 0.72)
                beam.FaceCamera = true
                beam.LightEmission = 1
                beam.LightInfluence = 0
                beam.Brightness = math.max(1, brightness)
                beam.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.02),
                    NumberSequenceKeypoint.new(0.8, 0.12),
                    NumberSequenceKeypoint.new(1, 1),
                })
                beam.Parent = Workspace.Terrain
                table.insert(instances, beam)
                table.insert(instances, near)
                table.insert(instances, far)
            end

            function RivalsRuntimeBridge.WorldVisuals.BuildLightningPoints(startPosition, endPosition, jaggedness)
                local distance = (endPosition - startPosition).Magnitude
                local segments = math.clamp(math.floor(distance / 12), 8, 28)
                local points = table.create(segments + 1)
                for index = 0, segments do
                    local alpha = index / segments
                    local point = startPosition:Lerp(endPosition, alpha)
                    if index > 0 and index < segments then
                        local taper = math.sin(alpha * math.pi)
                        point = point + Vector3.new(
                            (math.random() - 0.5) * jaggedness * 2 * taper,
                            (math.random() - 0.5) * jaggedness * taper,
                            (math.random() - 0.5) * jaggedness * 2 * taper
                        )
                    end
                    points[index + 1] = point
                end
                return points
            end

            function RivalsRuntimeBridge.WorldVisuals.ResolveWeatherSound()
                local world = RivalsRuntimeBridge.WorldVisuals
                local source = world.ReadOption('P1S29I1', '')
                if type(source) ~= 'string' or source:match('^%s*$') then
                    return 'rbxassetid://79197041664081'
                end
                source = world.NormalizeAssetId(source)
                if not source then
                    return nil
                end
                if source:match('^rbxasset') then
                    return source
                end
                local customAsset = type(getcustomasset) == 'function' and getcustomasset
                    or (type(getsynasset) == 'function' and getsynasset or nil)
                if customAsset and type(isfile) == 'function' and isfile(source) then
                    local ok, asset = pcall(customAsset, source)
                    if ok and type(asset) == 'string' then
                        return asset
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.WorldVisuals.PlayWeatherThunder(distance)
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.ReadToggle('P1S29T4', false) then
                    return
                end
                local source = world.ResolveWeatherSound()
                if not source then
                    return
                end
                local generation = world.WeatherGeneration
                local delayTime = world.ReadToggle('P1S29T5', false) and distance / 1225 or 0
                local volume = (tonumber(world.ReadOption('P1S29S15', 1)) or 1)
                    * math.max(0.3, 1 - distance / 320)
                local playbackSpeed = 0.75 + math.random() * 0.25
                task.delay(delayTime, function()
                    if not world.Initialized or generation ~= world.WeatherGeneration
                        or not world.ReadToggle('P1S28T1', false) then
                        return
                    end
                    local sound = Instance.new('Sound')
                    sound.Name = 'AkiraWeatherThunder'
                    sound.SoundId = source
                    sound.Volume = math.max(0, volume)
                    sound.PlaybackSpeed = playbackSpeed
                    sound.PlayOnRemove = true
                    sound.Parent = world.SoundService
                    sound:Destroy()
                end)
            end

            function RivalsRuntimeBridge.WorldVisuals.RenderWeatherLightning(startPosition, endPosition)
                local world = RivalsRuntimeBridge.WorldVisuals
                local color = world.ReadOption('P1S29C1', Color3.fromRGB(214, 230, 255))
                if typeof(color) ~= 'Color3' then color = Color3.fromRGB(214, 230, 255) end
                local thickness = math.max(0.05, tonumber(world.ReadOption('P1S29S4', 4)) or 4)
                local jaggedness = math.max(0, tonumber(world.ReadOption('P1S29S5', 7)) or 7)
                local branchCount = math.clamp(math.floor(tonumber(world.ReadOption('P1S29S6', 12)) or 12), 0, 24)
                local flash = math.max(0, tonumber(world.ReadOption('P1S29S7', 8)) or 8)
                local instances = {}
                local points = world.BuildLightningPoints(startPosition, endPosition, jaggedness)
                for index = 1, #points - 1 do
                    world.AddLightningSegment(instances, points[index], points[index + 1], color, thickness, flash)
                end

                for _ = 1, branchCount do
                    local sourceIndex = math.random(2, math.max(2, #points - 2))
                    local source = points[sourceIndex]
                    local branchLength = math.max(4, jaggedness * (1.5 + math.random()))
                    local branchEnd = source + Vector3.new(
                        (math.random() - 0.5) * branchLength * 2,
                        -math.random() * branchLength,
                        (math.random() - 0.5) * branchLength * 2
                    )
                    world.AddLightningSegment(instances, source, branchEnd, color, thickness * 0.45, flash * 0.7)
                end

                local impact = Instance.new('Attachment')
                impact.Name = 'AkiraLightningImpact'
                impact.Position = endPosition
                impact.Parent = Workspace.Terrain
                table.insert(instances, impact)
                if flash > 0 then
                    local light = Instance.new('PointLight')
                    light.Name = 'AkiraLightningFlash'
                    light.Color = color
                    light.Brightness = flash
                    light.Range = math.max(18, flash * 5)
                    light.Shadows = true
                    light.Parent = impact
                    table.insert(instances, light)
                end

                if world.ReadToggle('P1S29T2', false) then
                    local sparkColor = world.ReadOption('P1S29C2', Color3.fromRGB(238, 246, 255))
                    if typeof(sparkColor) ~= 'Color3' then sparkColor = Color3.fromRGB(238, 246, 255) end
                    local sparkCount = math.clamp(math.floor(tonumber(world.ReadOption('P1S29S8', 18)) or 18), 0, 40)
                    local sparkThickness = math.max(0.2, tonumber(world.ReadOption('P1S29S9', 2.2)) or 2.2)
                    local sparkDistance = math.max(2, tonumber(world.ReadOption('P1S29S10', 22)) or 22)
                    local sparkSpeed = math.max(2, tonumber(world.ReadOption('P1S29S11', 22)) or 22)
                    local sparks = Instance.new('ParticleEmitter')
                    sparks.Name = 'AkiraLightningSparks'
                    sparks.Texture = 'rbxassetid://119455261341623'
                    sparks.Rate = 0
                    sparks.Color = ColorSequence.new(sparkColor)
                    sparks.LightEmission = 1
                    local s1 = sparkSpeed * 0.65
                    local s2 = sparkSpeed
                    sparks.Speed = world.SafeNumberRange(s1, s2)
                    local safeDivSpeed = math.max(0.1, sparkSpeed)
                    local l1 = math.max(0.1, (sparkDistance / safeDivSpeed) * 0.65)
                    local l2 = math.max(l1, (sparkDistance / safeDivSpeed))
                    sparks.Lifetime = world.SafeNumberRange(l1, l2)
                    sparks.Size = NumberSequence.new({
                        NumberSequenceKeypoint.new(0, sparkThickness * 0.035),
                        NumberSequenceKeypoint.new(1, 0),
                    })
                    sparks.SpreadAngle = Vector2.new(180, 180)
                    sparks.Acceleration = Vector3.new(0, -Workspace.Gravity * 0.2, 0)
                    sparks.Parent = impact
                    sparks:Emit(sparkCount)
                    table.insert(instances, sparks)
                end

                if world.ReadToggle('P1S29T3', false) then
                    local explosionColor = world.ReadOption('P1S29C3', Color3.fromRGB(238, 200, 255))
                    if typeof(explosionColor) ~= 'Color3' then explosionColor = Color3.fromRGB(238, 200, 255) end
                    local explosionSize = math.max(0, tonumber(world.ReadOption('P1S29S13', 0.45)) or 0.45)
                    local explosionBolts = math.clamp(math.floor(tonumber(world.ReadOption('P1S29S14', 14)) or 14), 0, 30)
                    for _ = 1, explosionBolts do
                        local angle = math.random() * math.pi * 2
                        local length = (4 + math.random() * 12) * explosionSize
                        local arcEnd = endPosition + Vector3.new(
                            math.cos(angle) * length,
                            math.random() * length * 0.35,
                            math.sin(angle) * length
                        )
                        world.AddLightningSegment(instances, endPosition, arcEnd, explosionColor, thickness * 0.22, flash * 0.5)
                    end
                end

                task.delay(0.24, function()
                    for _, instance in ipairs(instances) do
                        if instance and instance.Parent then
                            pcall(function() instance:Destroy() end)
                        end
                    end
                end)
            end

            function RivalsRuntimeBridge.WorldVisuals.FireWeatherLightning()
                local world = RivalsRuntimeBridge.WorldVisuals
                local camera = Workspace.CurrentCamera
                if not camera or not world.ReadToggle('P1S29T1', false) then
                    return
                end
                local preset = world.ActiveWeatherPreset
                if preset ~= 'Rain' and preset ~= 'Heavy Rain' and preset ~= 'Blizzard' then
                    return
                end
                local distanceLimit = math.max(10, tonumber(world.ReadOption('P1S29S2', 80)) or 80)
                local radius = math.min(18, distanceLimit) + math.random() * math.max(0, distanceLimit - math.min(18, distanceLimit))
                local angle = math.random() * math.pi * 2
                local cameraPosition = camera.CFrame.Position
                local strikeX = cameraPosition.X + math.cos(angle) * radius
                local strikeZ = cameraPosition.Z + math.sin(angle) * radius
                local height = math.max(50, tonumber(world.ReadOption('P1S29S3', 220)) or 220)
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                if LP.Character then
                    params.FilterDescendantsInstances = {LP.Character}
                end
                local groundY = cameraPosition.Y - 40
                local result = Workspace:Raycast(
                    Vector3.new(strikeX, cameraPosition.Y + height, strikeZ),
                    Vector3.new(0, -2000, 0),
                    params
                )
                if result then
                    groundY = result.Position.Y
                end
                local finishPosition = Vector3.new(strikeX, groundY, strikeZ)
                local startPosition = Vector3.new(
                    strikeX + (math.random() - 0.5) * 30,
                    groundY + height,
                    strikeZ + (math.random() - 0.5) * 30
                )
                world.RenderWeatherLightning(startPosition, finishPosition)
                world.PlayWeatherThunder(radius)
            end

            function RivalsRuntimeBridge.WorldVisuals.UpdateWeather()
                LPH_ATTRIBUTES(VM(NONE))
                local world = RivalsRuntimeBridge.WorldVisuals
                local part = world.OwnedWeatherPart
                local camera = Workspace.CurrentCamera
                if part and part.Parent and camera then
                    -- Throttle: repositioning rain/snow to the camera does not need a
                    -- per-frame raycast. 8 Hz is plenty and removes a per-frame
                    -- RaycastParams + table allocation and Workspace:Raycast call.
                    local now = os.clock()
                    local nextAt = world._WeatherRaycastAt or 0
                    if now >= nextAt then
                        world._WeatherRaycastAt = now + 0.125
                        local rayParams = world._WeatherRayParams
                        if not rayParams then
                            rayParams = RaycastParams.new()
                            rayParams.FilterType = Enum.RaycastFilterType.Exclude
                            world._WeatherRayParams = rayParams
                        end
                        local height = math.clamp(tonumber(world.ReadOption('P1S28S7', 24)) or 24, 8, 100)
                        local LP = game:GetService('Players').LocalPlayer
                        local char = LP and LP.Character
                        local ignoreList = world._WeatherIgnoreList
                        if not ignoreList then
                            ignoreList = {}
                            world._WeatherIgnoreList = ignoreList
                        else
                            table.clear(ignoreList)
                        end
                        ignoreList[1] = part
                        ignoreList[2] = camera
                        if char then ignoreList[3] = char end
                        rayParams.FilterDescendantsInstances = ignoreList

                        local hit = Workspace:Raycast(camera.CFrame.Position, Vector3.new(0, height, 0), rayParams)
                        if hit and hit.Position then
                            part.Position = hit.Position - Vector3.new(0, 1.2, 0)
                        else
                            part.Position = camera.CFrame.Position + Vector3.new(0, height, 0)
                        end
                    end
                end
                if not part or not world.ReadToggle('P1S29T1', false)
                    or (world.ActiveWeatherPreset ~= 'Rain' and world.ActiveWeatherPreset ~= 'Heavy Rain' and world.ActiveWeatherPreset ~= 'Blizzard') then
                    return
                end
                local now = tick()
                if now >= world.NextLightningAt then
                    local interval = math.max(0.2, tonumber(world.ReadOption('P1S29S1', 2)) or 2)
                    world.NextLightningAt = now + interval
                    world.FireWeatherLightning()
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.UpdateFrame()
                LPH_ATTRIBUTES(VM(NONE))
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.Initialized or not world.LightingReady or world._Applying then
                    return
                end
                if not world.ReadToggle('P1S28T1', false) and not world.ReadToggle('P1S29T1', false) then
                    return
                end
                pcall(world.UpdateWeather)
            end

            function RivalsRuntimeBridge.WorldVisuals.UpdateStretchedResolution()
                LPH_ATTRIBUTES(VM(NONE))
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.ReadToggle('P1S30T1', false) then
                    world.RestoreStretchedResolution()
                    return
                end
                local camera = Workspace.CurrentCamera
                if not camera then
                    return
                end
                local xRatio = math.clamp(tonumber(world.ReadOption('P1S30S1', 1)) or 1, 0.01, 1)
                local yRatio = math.clamp(tonumber(world.ReadOption('P1S30S2', 1)) or 1, 0.01, 1)
                if xRatio >= 0.999 and yRatio >= 0.999 then
                    world.RestoreStretchedResolution()
                    return
                end
                if IsRivalsModToggleEnabled('P4S2T8') then
                    return
                end

                if not world.StretchedOriginalFov then
                    world.StretchedOriginalFov = camera.FieldOfView
                end
                local stretchScale = math.clamp(xRatio / math.max(yRatio, 0.01), 0.5, 2.0)
                local targetFov = math.clamp((world.StretchedOriginalFov or 80) * stretchScale, 30, 120)
                if math.abs(camera.FieldOfView - targetFov) > 0.1 then
                    camera.FieldOfView = targetFov
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.RestoreStretchedResolution()
                local world = RivalsRuntimeBridge.WorldVisuals
                if world.StretchedResolutionBound then
                    pcall(function()
                        RunService:UnbindFromRenderStep('AkiraStretchedResolution')
                    end)
                    world.StretchedResolutionBound = false
                end
                local camera = Workspace.CurrentCamera or world.StretchedLastCamera
                if camera and camera.Parent and world.StretchedOriginalFov then
                    pcall(function()
                        camera.FieldOfView = world.StretchedOriginalFov
                    end)
                end
                world.StretchedOriginalFov = nil
                world.StretchedLastCamera = nil
                world.StretchedLastBase = nil
                world.StretchedLastResult = nil
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshStretchedResolution()
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.ReadToggle('P1S30T1', false) then
                    world.RestoreStretchedResolution()
                    return
                end
                if not world.StretchedResolutionBound then
                    world.StretchedResolutionBound = true
                    RunService:BindToRenderStep(
                        'AkiraStretchedResolution',
                        Enum.RenderPriority.Camera.Value + 1,
                        GuardRivalsCallback('WorldVisuals_StretchedResolution', world.UpdateStretchedResolution)
                    )
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.LoadCustomSkyboxes()
                local world = RivalsRuntimeBridge.WorldVisuals
                if world.CustomSkyboxesLoaded then
                    return
                end
                world.CustomSkyboxesLoaded = true
                world.CustomSkyboxes = {}
                if not isfile(world.CustomSkyPath) then
                    return
                end
                local readOk, raw = pcall(readfile, world.CustomSkyPath)
                local decodeOk, decoded = pcall(function()
                    return game:GetService('HttpService'):JSONDecode(raw)
                end)
                if not readOk or not decodeOk or type(decoded) ~= 'table' then
                    return
                end
                for name, faces in pairs(decoded) do
                    if type(name) == 'string' and name ~= '' and type(faces) == 'table' and world.SkyPresets[name] == nil then
                        local normalized = {}
                        local valid = true
                        for property in pairs(world.SkyFaceInputs) do
                            normalized[property] = world.NormalizeAssetId(faces[property])
                            if not normalized[property] then
                                valid = false
                                break
                            end
                        end
                        if valid then
                            world.CustomSkyboxes[name] = normalized
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.SaveCustomSkyboxes()
                local world = RivalsRuntimeBridge.WorldVisuals
                return pcall(function()
                    writefile(world.CustomSkyPath, game:GetService('HttpService'):JSONEncode(world.CustomSkyboxes))
                end)
            end

            function RivalsRuntimeBridge.WorldVisuals.ResolveSkyPresetNames()
                local world = RivalsRuntimeBridge.WorldVisuals
                world.LoadCustomSkyboxes()
                local names = AkiraClone(world.SkyPresetNames)
                local customNames = {}
                for name in pairs(world.CustomSkyboxes) do
                    customNames[#customNames + 1] = name
                end
                table.sort(customNames)
                for _, name in ipairs(customNames) do
                    names[#names + 1] = name
                end
                return names
            end

            function RivalsRuntimeBridge.WorldVisuals.ResolveCustomSkyNames()
                RivalsRuntimeBridge.WorldVisuals.LoadCustomSkyboxes()
                local names = {}
                for name in pairs(RivalsRuntimeBridge.WorldVisuals.CustomSkyboxes) do
                    names[#names + 1] = name
                end
                table.sort(names)
                return names
            end

            function RivalsRuntimeBridge.WorldVisuals.ResolveSkyPreset(name)
                local world = RivalsRuntimeBridge.WorldVisuals
                world.LoadCustomSkyboxes()
                return world.SkyPresets[name] or world.CustomSkyboxes[name]
            end

