            function RivalsRuntimeBridge.WorldVisuals.ApplyWorldPreset(name)
                local world = RivalsRuntimeBridge.WorldVisuals
                local preset = world.WorldPresets[name]
                if not preset then
                    return
                end
                world._Applying = true
                local wanted = preset.Toggles or {}
                for _, toggleId in ipairs(world.WorldPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] ~= true and toggle.Value then
                        toggle:SetValue(false)
                    end
                end
                for optionId, value in pairs(preset.Options or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValue) == 'function' then
                        option:SetValue(value)
                    end
                end
                for optionId, rgb in pairs(preset.Colors or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValueRGB) == 'function' then
                        local color
                        if typeof(rgb) == 'Color3' then
                            color = rgb
                        elseif type(rgb) == 'table' then
                            color = Color3.fromRGB(tonumber(rgb[1]) or 255, tonumber(rgb[2]) or 255, tonumber(rgb[3]) or 255)
                        end
                        if color then
                            pcall(option.SetValueRGB, option, color)
                        end
                    end
                end
                for _, toggleId in ipairs(world.WorldPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] == true and not toggle.Value then
                        toggle:SetValue(true)
                    end
                end
                world._Applying = false
                world.RefreshAll()
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshSkyDropdowns()
                local world = RivalsRuntimeBridge.WorldVisuals
                local presetOption = Options.P1S12D1
                local savedOption = Options.P1S12D2
                if presetOption and type(presetOption.SetValues) == 'function' then
                    pcall(function()
                        presetOption:SetValues(world.ResolveSkyPresetNames())
                    end)
                end
                if savedOption and type(savedOption.SetValues) == 'function' then
                    pcall(function()
                        savedOption:SetValues(world.ResolveCustomSkyNames())
                    end)
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.AddCustomSkybox(name, faces)
                local world = RivalsRuntimeBridge.WorldVisuals
                world.LoadCustomSkyboxes()
                name = type(name) == 'string' and (name:match('^%s*(.-)%s*$') or '') or ''
                if name == '' or world.SkyPresets[name] ~= nil or world.CustomSkyboxes[name] ~= nil then
                    return false
                end
                local normalized = {}
                for property in pairs(world.SkyFaceInputs) do
                    normalized[property] = world.NormalizeAssetId(faces[property])
                    if not normalized[property] then
                        return false
                    end
                end
                world.CustomSkyboxes[name] = normalized
                if not world.SaveCustomSkyboxes() then
                    world.CustomSkyboxes[name] = nil
                    return false
                end
                world.RefreshSkyDropdowns()
                return true
            end

            function RivalsRuntimeBridge.WorldVisuals.AddCustomSkyboxFromOptions()
                local world = RivalsRuntimeBridge.WorldVisuals
                local faces = {}
                for property, optionId in pairs(world.SkyFaceInputs) do
                    faces[property] = world.ReadOption(optionId, '')
                end
                local added = world.AddCustomSkybox(world.ReadOption('P1S12I7', ''), faces)
                if added then
                    local nameOption = Options.P1S12I7
                    if nameOption and type(nameOption.SetValue) == 'function' then
                        nameOption:SetValue('')
                    end
                    for _, optionId in pairs(world.SkyFaceInputs) do
                        local option = Options[optionId]
                        if option and type(option.SetValue) == 'function' then
                            option:SetValue('')
                        end
                    end
                end
                return added
            end

            function RivalsRuntimeBridge.WorldVisuals.RemoveSelectedCustomSkybox()
                local world = RivalsRuntimeBridge.WorldVisuals
                local name = world.ReadOption('P1S12D2', nil)
                if type(name) ~= 'string' or world.CustomSkyboxes[name] == nil then
                    return false
                end
                local removed = world.CustomSkyboxes[name]
                world.CustomSkyboxes[name] = nil
                if not world.SaveCustomSkyboxes() then
                    world.CustomSkyboxes[name] = removed
                    return false
                end
                world.RefreshSkyDropdowns()
                local presetOption = Options.P1S12D1
                if presetOption and presetOption.Value == name and type(presetOption.SetValue) == 'function' then
                    presetOption:SetValue(nil)
                end
                local savedOption = Options.P1S12D2
                if savedOption and savedOption.Value == name and type(savedOption.SetValue) == 'function' then
                    savedOption:SetValue(nil)
                end
                world.RefreshSky()
                return true
            end

            function RivalsRuntimeBridge.WorldVisuals.RestoreSky()
                local world = RivalsRuntimeBridge.WorldVisuals
                local owned = world.OwnedSky
                world.OwnedSky = nil
                world.ActiveSkyName = nil
                if owned then
                    pcall(function()
                        owned:Destroy()
                    end)
                end
                for sky, guard in pairs(world.NativeSkyGuards) do
                    world.DestroyGuard(guard)
                    world.NativeSkyGuards[sky] = nil
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.GuardNativeSky(sky, preset)
                local world = RivalsRuntimeBridge.WorldVisuals
                if not sky or sky == world.OwnedSky then
                    return
                end
                local guard = world.NativeSkyGuards[sky]
                if not guard then
                    guard = world.NewGuard(sky)
                    world.NativeSkyGuards[sky] = guard
                end
                world.ReconcileGuard(guard, world.SkyProperties, preset or {})
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshSky()
                local world = RivalsRuntimeBridge.WorldVisuals
                local presetName = world.ReadOption('P1S12D1', '')
                local preset = world.ReadToggle('P1S12T1', false) and world.ResolveSkyPreset(presetName) or nil
                if not preset then
                    world.RestoreSky()
                    return
                end
                local nativeSkies = {}
                for _, child in ipairs(world.Lighting:GetChildren()) do
                    if child:IsA('Sky') and child ~= world.OwnedSky then
                        nativeSkies[#nativeSkies + 1] = child
                    end
                end
                if #nativeSkies > 0 then
                    local owned = world.OwnedSky
                    world.OwnedSky = nil
                    world.ActiveSkyName = nil
                    if owned then
                        pcall(function()
                            owned:Destroy()
                        end)
                    end
                    for _, sky in ipairs(nativeSkies) do
                        world.GuardNativeSky(sky, preset)
                    end
                    return
                end
                if not world.OwnedSky or world.OwnedSky.Parent == nil or world.ActiveSkyName ~= presetName then
                    local previous = world.OwnedSky
                    world.OwnedSky = nil
                    if previous then
                        pcall(function()
                            previous:Destroy()
                        end)
                    end
                    local sky = Instance.new('Sky')
                    sky.Name = 'AkiraWorldVisuals_Sky'
                    for property, value in pairs(preset) do
                        pcall(function()
                            sky[property] = value
                        end)
                    end
                    world.OwnedSky = sky
                    world.ActiveSkyName = presetName
                    sky.Parent = world.Lighting
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.ResolveAtmosphereValues()
                local world = RivalsRuntimeBridge.WorldVisuals
                return {
                    Color = world.ReadColor3('P1S13C1', Color3.new(0.7843, 0.6667, 0.4235)),
                    Decay = world.ReadColor3('P1S13C2', Color3.new(0.3608, 0.2353, 0.0549)),
                    Density = tonumber(world.ReadOption('P1S13S1', 0.395)) or 0.395,
                    Offset = tonumber(world.ReadOption('P1S13S2', 0)) or 0,
                    Glare = tonumber(world.ReadOption('P1S13S3', 0)) or 0,
                    Haze = tonumber(world.ReadOption('P1S13S4', 0)) or 0,
                }
            end

            function RivalsRuntimeBridge.WorldVisuals.RestoreAtmosphere()
                local world = RivalsRuntimeBridge.WorldVisuals
                local owned = world.OwnedAtmosphere
                world.OwnedAtmosphere = nil
                if owned then
                    pcall(function()
                        owned:Destroy()
                    end)
                end
                for atmosphere, guard in pairs(world.NativeAtmosphereGuards) do
                    world.DestroyGuard(guard)
                    world.NativeAtmosphereGuards[atmosphere] = nil
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.GuardNativeAtmosphere(atmosphere, desired)
                local world = RivalsRuntimeBridge.WorldVisuals
                if not atmosphere or atmosphere == world.OwnedAtmosphere then
                    return
                end
                local guard = world.NativeAtmosphereGuards[atmosphere]
                if not guard then
                    guard = world.NewGuard(atmosphere)
                    world.NativeAtmosphereGuards[atmosphere] = guard
                end
                world.ReconcileGuard(guard, world.AtmosphereProperties, desired)
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshAtmosphere()
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.ReadToggle('P1S13T1', false) then
                    world.RestoreAtmosphere()
                    return
                end
                local desired = world.ResolveAtmosphereValues()
                local nativeAtmospheres = {}
                for _, child in ipairs(world.Lighting:GetChildren()) do
                    if child:IsA('Atmosphere') and child ~= world.OwnedAtmosphere then
                        nativeAtmospheres[#nativeAtmospheres + 1] = child
                    end
                end
                if #nativeAtmospheres > 0 then
                    local owned = world.OwnedAtmosphere
                    world.OwnedAtmosphere = nil
                    if owned then
                        pcall(function()
                            owned:Destroy()
                        end)
                    end
                    for _, atmosphere in ipairs(nativeAtmospheres) do
                        world.GuardNativeAtmosphere(atmosphere, desired)
                    end
                    return
                end
                local atmosphere = world.OwnedAtmosphere
                if not atmosphere or atmosphere.Parent == nil then
                    atmosphere = Instance.new('Atmosphere')
                    atmosphere.Name = 'AkiraWorldVisuals_Atmosphere'
                    world.OwnedAtmosphere = atmosphere
                    atmosphere.Parent = world.Lighting
                end
                for property, value in pairs(desired) do
                    atmosphere[property] = value
                end
            end

            local LIGHTING_REFRESH_CLASSES = {
                Atmosphere = true, Sky = true, Clouds = true,
                BloomEffect = true, BlurEffect = true, ColorCorrectionEffect = true,
                DepthOfFieldEffect = true, SunRaysEffect = true,
            }

            function RivalsRuntimeBridge.WorldVisuals.OnLightingDescendantAdded(descendant)
                local world = RivalsRuntimeBridge.WorldVisuals
                if world._Applying or not world.LightingReady then
                    return
                end
                if typeof(descendant) ~= 'Instance' then
                    return
                end
                local descName = descendant.Name
                if descName:sub(1, 17) == 'AkiraWorldVisuals_' or descName == 'AkiraWeatherEmitter' or descName:find('Akira') then
                    return
                end
                if not LIGHTING_REFRESH_CLASSES[descendant.ClassName] then
                    return
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.OnLightingDescendantRemoving(descendant)
                local world = RivalsRuntimeBridge.WorldVisuals
                local mapParser = RivalsRuntimeBridge.MapParser
                local shouldRefresh = false
                local effectGuards = world.NativeEffectGuards[descendant.ClassName]
                local effectGuard = effectGuards and effectGuards[descendant]
                if effectGuard then
                    world.DestroyGuard(effectGuard)
                    effectGuards[descendant] = nil
                end
                local skyGuard = world.NativeSkyGuards[descendant]
                if skyGuard then
                    world.DestroyGuard(skyGuard)
                    world.NativeSkyGuards[descendant] = nil
                    shouldRefresh = true
                end
                local atmosphereGuard = world.NativeAtmosphereGuards[descendant]
                if atmosphereGuard then
                    world.DestroyGuard(atmosphereGuard)
                    world.NativeAtmosphereGuards[descendant] = nil
                    shouldRefresh = true
                end
                local isOwned = descendant.Name:sub(1, 17) == 'AkiraWorldVisuals_' or descendant.Name:find('Akira')
                for className, owned in pairs(world.OwnedEffects) do
                    if descendant == owned then
                        world.OwnedEffects[className] = nil
                        if not isOwned and not world._Applying then shouldRefresh = true end
                    end
                end
                if descendant == world.OwnedSky then
                    world.OwnedSky = nil
                    if not isOwned and not world._Applying then shouldRefresh = true end
                elseif descendant == world.OwnedAtmosphere then
                    world.OwnedAtmosphere = nil
                    if not isOwned and not world._Applying then shouldRefresh = true end
                end
                if shouldRefresh and world.Initialized and world.LightingReady and not world._Applying and not (mapParser and mapParser.IsMapStreaming) then
                    if world._RemovingRefreshScheduled then
                        return
                    end
                    world._RemovingRefreshScheduled = true
                    task.delay(0.5, function()
                        world._RemovingRefreshScheduled = false
                        if world.Initialized and not world._Applying and not (mapParser and mapParser.IsMapStreaming) then
                            world.RefreshAll()
                        end
                    end)
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.WaitForLightingStability(onStable)
                local mapParser = RivalsRuntimeBridge.MapParser
                if mapParser then
                    return mapParser.WaitForMapStability(onStable)
                end
                if onStable then
                    pcall(onStable)
                end
            end

            function RivalsRuntimeBridge.WorldVisuals.EnsureInitialized()
                local world = RivalsRuntimeBridge.WorldVisuals
                if world.Initialized then
                    return
                end
                world.Initialized = true
                world.LightingReady = false
                world.UnsupportedLightingProperties = {}
                pcall(world.LoadCustomSkyboxes)
                local function armLighting()
                    if shutting_down or not world.Initialized then
                        return
                    end
                    if not world.LightingGuard then
                        world.LightingGuard = world.NewGuard(world.Lighting)
                    end
                    if not world.Connections.DescendantAdded then
                        world.Connections.DescendantAdded = world.Lighting.DescendantAdded:Connect(world.OnLightingDescendantAdded)
                    end
                    if not world.Connections.DescendantRemoving then
                        world.Connections.DescendantRemoving = world.Lighting.DescendantRemoving:Connect(world.OnLightingDescendantRemoving)
                    end
                    if not world.Connections.PreRender then
                        local preRenderSignal = RunService.PreRender or RunService.RenderStepped
                        world.Connections.PreRender = preRenderSignal:Connect(function()
                            __akira_genv.__AkiraCurrentLoop = 'WorldFrame'
                            world.UpdateFrame()
                            __akira_genv.__AkiraCurrentLoop = nil
                        end)
                    end
                    world.LightingReady = true
                    world.EnsureGuardWatch(world.LightingGuard)
                end

                local mapParser = RivalsRuntimeBridge.MapParser
                if mapParser then
                    mapParser.WaitForMapStability(function()
                        if shutting_down or not world.Initialized or world.LightingReady then
                            return
                        end
                        pcall(armLighting)
                        world.GuardSettleUntil = os.clock() + 2.0
                        if world.Initialized and not shutting_down then
                            pcall(world.RefreshAll)
                        end
                    end)
                else
                    pcall(armLighting)
                    world.GuardSettleUntil = os.clock() + 2.0
                    pcall(world.RefreshAll)
                end
            end

            __akira_boot_yield()

            -- Partial refresh routing: map a world option id to just the subsystem it
            -- affects so a single slider change does not rebuild the whole world.
            local WORLD_PARTIAL_ROUTES = {
                P1S4 = 'Lighting', P1S5 = 'Lighting', P1S8 = 'Lighting',
                P1S6 = 'BloomEffect', P1S7 = 'ColorCorrectionEffect', P1S10 = 'SunRaysEffect',
                P1S12 = 'Sky', P1S13 = 'Atmosphere', P1S14 = 'Ambience',
                P1S28 = 'Weather', P1S29 = 'Weather', P1S30 = 'StretchedResolution',
            }

            local function ResolveWorldPartialStep(world, route)
                if route == 'Lighting' then
                    return world.RefreshLighting
                elseif route == 'Sky' then
                    return world.RefreshSky
                elseif route == 'Atmosphere' then
                    return world.RefreshAtmosphere
                elseif route == 'Ambience' then
                    return world.RefreshAmbience
                elseif route == 'Weather' then
                    return world.RefreshWeather
                elseif route == 'StretchedResolution' then
                    return world.RefreshStretchedResolution
                elseif route == 'BloomEffect' or route == 'ColorCorrectionEffect' or route == 'SunRaysEffect' then
                    return function()
                        world.RefreshPostEffect(route)
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshForOption(optionId)
                local world = RivalsRuntimeBridge.WorldVisuals
                if shutting_down or (Library and Library.ConfigLoading) or RivalsRuntimeBridge.RuntimeRefreshSuspended or world._Applying then
                    return
                end
                if type(optionId) ~= 'string' then
                    return world.RefreshAll()
                end
                local route = WORLD_PARTIAL_ROUTES[optionId:sub(1, 5)] or WORLD_PARTIAL_ROUTES[optionId:sub(1, 4)]
                if not route then
                    return world.RefreshAll()
                end
                if not world.Initialized then
                    -- RefreshAll runs EnsureInitialized itself.
                    return world.RefreshAll()
                end
                world._PartialSteps = world._PartialSteps or {}
                world._PartialSteps[route] = true
                if world._PartialScheduled then
                    return
                end
                world._PartialScheduled = true
                task.defer(function()
                    world._PartialScheduled = false
                    if shutting_down or (Library and Library.ConfigLoading) or RivalsRuntimeBridge.RuntimeRefreshSuspended then
                        world._PartialSteps = {}
                        return
                    end
                    if not world.LightingReady then
                        -- The armed initialization will run a full refresh shortly.
                        world._PartialSteps = {}
                        return
                    end
                    local steps = world._PartialSteps
                    world._PartialSteps = {}
                    __akira_boot_log('World: partial refresh')
                    for stepRoute in pairs(steps) do
                        local stepFn = ResolveWorldPartialStep(world, stepRoute)
                        if stepFn then
                            local ok, err = pcall(stepFn)
                            if not ok then
                                warn('[Akira] WorldVisuals.Partial.' .. tostring(stepRoute) .. ': ' .. tostring(err))
                            end
                            __akira_boot_yield()
                        end
                    end
                end)
            end

            function RivalsRuntimeBridge.WorldVisuals.RefreshAll()
                if shutting_down or (Library and Library.ConfigLoading) then
                    return
                end
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local world = RivalsRuntimeBridge.WorldVisuals
                if world._Applying or world._RefreshScheduled then
                    world._RefreshDirty = true
                    return
                end
                world._RefreshScheduled = true
                task.defer(function()
                    if shutting_down or (Library and Library.ConfigLoading) or RivalsRuntimeBridge.RuntimeRefreshSuspended then
                        world._RefreshScheduled = false
                        world._RefreshDirty = false
                        return
                    end
                    world._RefreshDirty = false
                    world._Applying = true
                    local function step(name, fn)
                        local ok, err = pcall(fn)
                        if not ok then
                            warn('[Akira] WorldVisuals.' .. tostring(name) .. ': ' .. tostring(err))
                        end
                        __akira_boot_yield()
                    end
                    step('EnsureInitialized', world.EnsureInitialized)
                    if not world.LightingReady then
                        world._Applying = false
                        world._RefreshScheduled = false
                        world._RefreshDirty = true
                        return
                    end
                    __akira_boot_log('World: full refresh')
                    step('RefreshLighting', world.RefreshLighting)
                    for className in pairs(world.PostEffects) do
                        step('RefreshPostEffect_' .. tostring(className), function()
                            world.RefreshPostEffect(className)
                        end)
                    end
                    step('RefreshAmbience', world.RefreshAmbience)
                    step('RefreshWeather', world.RefreshWeather)
                    step('RefreshStretchedResolution', world.RefreshStretchedResolution)
                    step('RefreshSky', world.RefreshSky)
                    step('RefreshAtmosphere', world.RefreshAtmosphere)
                    world._Applying = false
                    world._RefreshScheduled = false
                    world._RefreshDirty = false
                end)
            end

            function RivalsRuntimeBridge.WorldVisuals.Destroy()
                local world = RivalsRuntimeBridge.WorldVisuals
                if not world.Initialized then
                    return
                end
                world.Initialized = false
                world.LightingReady = false
                world._RefreshScheduled = false
                world._RefreshDirty = false
                world._Applying = false
                for _, connection in pairs(world.Connections) do
                    connection:Disconnect()
                end
                world.Connections = {}
                world.DestroyGuard(world.LightingGuard)
                world.LightingGuard = nil
                for className in pairs(world.PostEffects) do
                    world.RestorePostEffect(className)
                end
                local ambience = world.OwnedAmbience
                world.OwnedAmbience = nil
                world.ActiveAmbienceSource = nil
                if ambience then
                    pcall(function()
                        ambience:Destroy()
                    end)
                end
                world.DestroyWeather()
                world.RestoreStretchedResolution()
                world.RestoreSky()
                world.RestoreAtmosphere()
            end
            end)()

            RivalsRuntimeBridge.ViewmodelVisuals = {
                AppearanceSnapshots = setmetatable({}, { __mode = 'k' }),
                TextureSnapshots = {},
                Highlights = {},
                Crosshair = nil,
                CrosshairLayout = nil,
                LastReconcileAt = 0,
                FollowPosition = nil,
                MaterialMap = {
                    Ghost = Enum.Material.ForceField,
                    Hologram = Enum.Material.ForceField,
                    XRay = Enum.Material.ForceField,
                    Neon = Enum.Material.Neon,
                    Energy = Enum.Material.Neon,
                    Glow = Enum.Material.Neon,
                    Plasma = Enum.Material.Neon,
                    Flat = Enum.Material.SmoothPlastic,
                    Matte = Enum.Material.Plastic,
                    Plastic = Enum.Material.Plastic,
                    Chrome = Enum.Material.Metal,
                    Metal = Enum.Material.Metal,
                    Glass = Enum.Material.Glass,
                    Crystal = Enum.Material.Glass,
                    Diamond = Enum.Material.DiamondPlate,
                    Ice = Enum.Material.Ice,
                    Pearl = Enum.Material.Marble,
                    Foil = Enum.Material.Foil,
                    Carbon = Enum.Material.Granite,
                    Obsidian = Enum.Material.Slate,
                    Reflective = Enum.Material.Glass,
                    Custom = Enum.Material.SmoothPlastic,
                    Wood = Enum.Material.Wood,
                    Brick = Enum.Material.Brick,
                    Fabric = Enum.Material.Fabric,
                    Corroded = Enum.Material.CorrodedMetal,
                },
                MaterialNames = {
                    'Ghost', 'Hologram', 'XRay', 'Neon', 'Glow', 'Energy', 'Plasma',
                    'Flat', 'Matte', 'Plastic', 'Chrome', 'Metal', 'Glass', 'Crystal',
                    'Diamond', 'Ice', 'Pearl', 'Foil', 'Carbon', 'Obsidian',
                    'Wood', 'Brick', 'Fabric', 'Corroded', 'Reflective', 'Custom', 'Original',
                },
                MaterialExtras = {
                    Ghost = { Reflectance = 0 },
                    Hologram = { Reflectance = 0.22, Pulse = true, PulseAmplitude = 0.28, PulseSpeed = 3.2 },
                    XRay = { Reflectance = 0.08, Pulse = true, PulseAmplitude = 0.18, PulseSpeed = 2.4, AlwaysOnTop = true },
                    Neon = { Reflectance = 0 },
                    Glow = { Reflectance = 0, GlowHighlight = true },
                    Energy = { Reflectance = 0, Pulse = true, PulseAmplitude = 0.22, PulseSpeed = 4, HueShift = true },
                    Plasma = { Reflectance = 0.35, Pulse = true, PulseAmplitude = 0.3, PulseSpeed = 5, HueShift = true },
                    Flat = { Reflectance = 0 },
                    Matte = { Reflectance = 0 },
                    Plastic = { Reflectance = 0.04 },
                    Chrome = { Reflectance = 1 },
                    Metal = { Reflectance = 0.7 },
                    Glass = { Reflectance = 0.42 },
                    Crystal = { Reflectance = 0.9 },
                    Diamond = { Reflectance = 0.35 },
                    Ice = { Reflectance = 0.5 },
                    Pearl = { Reflectance = 0.55 },
                    Foil = { Reflectance = 0.85 },
                    Carbon = { Reflectance = 0.12 },
                    Obsidian = { Reflectance = 0.4 },
                    Wood = { Reflectance = 0.05 },
                    Brick = { Reflectance = 0 },
                    Fabric = { Reflectance = 0 },
                    Corroded = { Reflectance = 0.15 },
                    Reflective = { Reflectance = 1 },
                    Custom = { Reflectance = 0.25 },
                },
                FontMap = {
                    Inconsolata = Enum.Font.Code,
                    Gotham = Enum.Font.Gotham,
                    ['Source Sans'] = Enum.Font.SourceSans,
                    ['Roboto Mono'] = Enum.Font.RobotoMono,
