            }

            function RivalsRuntimeBridge.ViewmodelVisuals.ReadToggle(optionId)
                LPH_ATTRIBUTES(VM(NONE))
                local toggle = Toggles and Toggles[optionId]
                if toggle ~= nil then
                    if toggle.Value == true then
                        return true
                    end
                    if type(toggle.Get) == 'function' then
                        local ok, value = pcall(toggle.Get, toggle)
                        if ok and value == true then
                            return true
                        end
                    end
                end
                local flags = Library and rawget(Library, 'Flags')
                return type(flags) == 'table' and flags[optionId] == true
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ReadOption(optionId, fallback)
                LPH_ATTRIBUTES(VM(NONE))
                local option = Options and Options[optionId]
                if option ~= nil then
                    if type(option.Get) == 'function' then
                        local ok, value = pcall(option.Get, option)
                        if ok and value ~= nil then
                            return value
                        end
                    end
                    local ok, value = pcall(rawget, option, 'Value')
                    if not ok or value == nil then
                        ok, value = pcall(function()
                            return option.Value
                        end)
                    end
                    if ok and value ~= nil then
                        return value
                    end
                end
                local flags = Library and rawget(Library, 'Flags')
                if type(flags) == 'table' and flags[optionId] ~= nil then
                    return flags[optionId]
                end
                return fallback
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ReadColor(optionId, fallback)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local color = select(1, parseColorAndAlpha(visuals.ReadOption(optionId, fallback)))
                if typeof(color) == 'Color3' then
                    return color
                end
                return fallback
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ReadNumber(optionId, fallback)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local value = visuals.ReadOption(optionId, fallback)
                if type(value) == 'table' then
                    value = value.Value or value.v or value.Number
                end
                value = tonumber(value)
                if value == nil then
                    return fallback
                end
                return value
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.AppendUniqueRoot(roots, seen, root)
                if typeof(root) ~= 'Instance' or root.Parent == nil or seen[root] then
                    return
                end
                seen[root] = true
                roots[#roots + 1] = root
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.IsLocalViewModel(model)
                if typeof(model) ~= 'Instance' then
                    return false
                end
                local prefix = LP.Name .. ' -'
                return model.Name == LP.Name or string.sub(model.Name, 1, #prefix) == prefix
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.IsArmName(name)
                if type(name) ~= 'string' then
                    return false
                end
                name = string.lower(name)
                local keywords = {
                    'arm', 'hand', 'sleeve', 'elbow', 'wrist',
                    'shoulder', 'finger', 'thumb', 'glove',
                }
                for i = 1, #keywords do
                    if string.find(name, keywords[i], 1, true) then
                        return true
                    end
                end
                return false
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.IsArmInstance(instance, stopAt)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local current = instance
                while typeof(current) == 'Instance' and current ~= stopAt do
                    if visuals.IsArmName(current.Name) then
                        return true
                    end
                    current = current.Parent
                end
                return false
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.CollectArmRoots(visuals, scopes, seen, root, stopAt)
                if typeof(root) ~= 'Instance' then
                    return
                end
                visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, root:FindFirstChild('LeftArm'))
                visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, root:FindFirstChild('RightArm'))
                visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, root:FindFirstChild('Left Arm'))
                visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, root:FindFirstChild('Right Arm'))
                visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, root:FindFirstChild('Arms'))
                local nested = root:FindFirstChild('ViewModel')
                if nested and nested ~= root then
                    visuals.CollectArmRoots(visuals, scopes, seen, nested, stopAt or root)
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.CollectFirstPersonScopes(visuals, scopes, seen, folder)
                if typeof(folder) ~= 'Instance' then
                    return
                end
                for _, model in ipairs(folder:GetChildren()) do
                    if model:IsA('Model') and visuals.IsLocalViewModel(model) then
                        visuals.AppendUniqueRoot(scopes.Item, seen.Item, model:FindFirstChild('ItemVisual'))
                        visuals.CollectArmRoots(visuals, scopes, seen, model, folder)
                        for _, descendant in ipairs(model:GetDescendants()) do
                            if descendant:IsA('BasePart') then
                                if visuals.IsArmInstance(descendant, model) then
                                    visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, descendant)
                                elseif not seen.Item[descendant] and descendant.Name ~= 'HumanoidRootPart' then
                                    local itemVisual = model:FindFirstChild('ItemVisual')
                                    if itemVisual and descendant:IsDescendantOf(itemVisual) then
                                        visuals.AppendUniqueRoot(scopes.Item, seen.Item, descendant)
                                    elseif not visuals.IsArmInstance(descendant, model) then
                                        visuals.AppendUniqueRoot(scopes.Item, seen.Item, descendant)
                                    end
                                end
                            elseif descendant:IsA('Model') and visuals.IsArmName(descendant.Name) then
                                visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, descendant)
                            end
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ResolveScopes()
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local scopes = { Character = {}, Arms = {}, Item = {} }
                local seen = { Character = {}, Arms = {}, Item = {} }
                visuals.AppendUniqueRoot(scopes.Character, seen.Character, LP.Character)

                local fighter = ResolveLocalFighter()
                local equippedItem = fighter and fighter.EquippedItem or nil
                local clientViewModel = type(equippedItem) == 'table'
                    and (rawget(equippedItem, '_ViewModel') or rawget(equippedItem, 'ViewModel')) or nil
                if type(clientViewModel) == 'table' then
                    visuals.AppendUniqueRoot(scopes.Item, seen.Item, rawget(clientViewModel, 'ItemModel'))
                    visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, rawget(clientViewModel, '_left_arm'))
                    visuals.AppendUniqueRoot(scopes.Arms, seen.Arms, rawget(clientViewModel, '_right_arm'))
                    visuals.CollectArmRoots(visuals, scopes, seen, rawget(clientViewModel, 'Model'))
                    visuals.CollectArmRoots(visuals, scopes, seen, rawget(clientViewModel, 'Instance'))
                end

                local viewModels = Workspace:FindFirstChild('ViewModels')
                visuals.CollectFirstPersonScopes(visuals, scopes, seen, viewModels and viewModels:FindFirstChild('FirstPerson'))
                visuals.CollectFirstPersonScopes(visuals, scopes, seen, viewModels and viewModels:FindFirstChild('ThirdPerson'))
                local camera = Workspace.CurrentCamera
                if camera then
                    visuals.CollectFirstPersonScopes(visuals, scopes, seen, camera)
                end
                return scopes
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.CaptureAppearance(part)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local snapshot = visuals.AppearanceSnapshots[part]
                if snapshot then
                    return snapshot
                end
                snapshot = {
                    Material = part.Material,
                    Color = part.Color,
                    Transparency = part.Transparency,
                    Reflectance = part.Reflectance,
                    MaterialVariant = part.MaterialVariant,
                }
                visuals.AppearanceSnapshots[part] = snapshot
                return snapshot
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.RestoreAppearance(part, snapshot)
                if not part or part.Parent == nil or type(snapshot) ~= 'table' then
                    return
                end
                pcall(function()
                    part.Material = snapshot.Material
                    part.Color = snapshot.Color
                    part.Transparency = snapshot.Transparency
                    part.Reflectance = snapshot.Reflectance
                    part.MaterialVariant = snapshot.MaterialVariant or ''
                end)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.CaptureTexture(instance, property, root)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local snapshot = visuals.TextureSnapshots[instance]
                if snapshot then
                    return snapshot
                end
                snapshot = { Property = property, Root = root }
                if property == 'Parent' then
                    snapshot.Value = instance.Parent
                else
                    snapshot.Value = instance[property]
                end
                visuals.TextureSnapshots[instance] = snapshot
                return snapshot
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.StripTextures(root, activeTextures)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                for instance, snapshot in pairs(visuals.TextureSnapshots) do
                    if snapshot.Root == root and snapshot.Property == 'Parent' and instance.Parent == nil then
                        activeTextures[instance] = true
                    end
                end
                local descendants = root:GetDescendants()
                if root:IsA('BasePart') then
                    table.insert(descendants, root)
                end
                for _, descendant in ipairs(descendants) do
                    local property = nil
                    local replacement = nil
                    if descendant:IsA('MeshPart') then
                        property = 'TextureID'
                        replacement = ''
                    elseif descendant:IsA('SpecialMesh') then
                        property = 'TextureId'
                        replacement = ''
                    elseif descendant:IsA('Decal') or descendant:IsA('Texture') then
                        property = 'Parent'
                    elseif descendant:IsA('SurfaceAppearance')
                        or descendant:IsA('Clothing') or descendant:IsA('ShirtGraphic') then
                        property = 'Parent'
                    elseif descendant:IsA('Shirt') then
                        property = 'ShirtTemplate'
                        replacement = ''
                    elseif descendant:IsA('Pants') then
                        property = 'PantsTemplate'
                        replacement = ''
                    end
                    if property then
                        visuals.CaptureTexture(descendant, property, root)
                        activeTextures[descendant] = true
                        pcall(function()
                            if property == 'Parent' then
                                descendant.Parent = nil
                            else
                                descendant[property] = replacement
                            end
                        end)
                    end
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.RestoreTexture(instance, snapshot)
                if not instance or type(snapshot) ~= 'table' then
                    return
                end
                pcall(function()
                    instance[snapshot.Property] = snapshot.Value
                end)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.IsSafeChamPart(part, root, bodyOnly)
                if typeof(part) ~= 'Instance' or not part:IsA('BasePart') then
                    return false
                end
                if part.Name == 'HumanoidRootPart' or part:IsA('Terrain') then
                    return false
                end
                if root == Workspace or root:IsA('Camera') or root:IsA('Terrain') then
                    return false
                end
                if not part:IsDescendantOf(root) and part ~= root then
                    return false
                end
                if part.Transparency >= 1 then
                    return false
                end
                local name = part.Name
                if string.find(name, 'Hitbox', 1, true) then
                    return false
                end
                local size = part.Size
                if size.X > 80 or size.Y > 80 or size.Z > 80 then
                    return false
                end
                if bodyOnly == true then
                    if name == 'HitboxHead' or name == 'HitboxBody' then
                        return false
                    end
                end
                return true
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ApplyChamScope(roots, optionPrefix, activeParts, activeTextures)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if not visuals.ReadToggle(optionPrefix .. 'T1') then
                    return
                end
                local bodyOnly = optionPrefix == 'P1S19'
                local materialName = tostring(visuals.ReadOption(optionPrefix .. 'D1', 'Ghost') or 'Ghost')
                local material = visuals.MaterialMap[materialName]
                local extras = visuals.MaterialExtras[materialName] or {}
                local color = visuals.ReadColor(optionPrefix .. 'C1', Color3.new(1, 1, 1))
                local transparency = math.clamp(visuals.ReadNumber(optionPrefix .. 'S1', 0) or 0, 0, 1)
                if extras.HueShift and typeof(color) == 'Color3' then
                    local hue, saturation, value = color:ToHSV()
                    color = Color3.fromHSV((hue + os.clock() * 0.14) % 1, math.clamp(saturation, 0.45, 1), value)
                end
                if extras.Pulse then
                    local wave = (math.sin(os.clock() * (extras.PulseSpeed or 3)) + 1) * 0.5
                    transparency = math.clamp(transparency + (wave - 0.5) * (extras.PulseAmplitude or 0.2), 0, 1)
                end
                local stripTextures = materialName ~= 'Original' or visuals.ReadToggle(optionPrefix .. 'T2')
                if optionPrefix == 'P1S19' then
                    stripTextures = true
                end
                for _, root in ipairs(roots) do
                    if typeof(root) == 'Instance' and root ~= Workspace and not root:IsA('Camera') and not root:IsA('Terrain') then
                    local descendants = root:GetDescendants()
                    if root:IsA('BasePart') then
                        table.insert(descendants, root)
                    end
                    for _, descendant in ipairs(descendants) do
                        if visuals.IsSafeChamPart(descendant, root, bodyOnly) then
                            local snapshot = visuals.CaptureAppearance(descendant)
                            activeParts[descendant] = true
                            pcall(function()
                                descendant.MaterialVariant = ''
                                descendant.Material = material or snapshot.Material
                                descendant.Color = color
                                if snapshot.Transparency < 1 then
                                    descendant.Transparency = transparency
                                end
                                if optionPrefix ~= 'P1S19' then
                                    descendant.LocalTransparencyModifier = 0
                                end
                                if extras.Reflectance ~= nil then
                                    descendant.Reflectance = extras.Reflectance
                                elseif material == Enum.Material.ForceField or material == Enum.Material.Neon then
                                    descendant.Reflectance = 0
                                end
                            end)
                        end
                    end
                    if stripTextures then
                        visuals.StripTextures(root, activeTextures)
                    end
                    end
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ReconcileHighlights(scopeName, roots, optionPrefix)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local entries = visuals.Highlights[scopeName] or {}
                visuals.Highlights[scopeName] = entries
                local active = {}
                if visuals.ReadToggle(optionPrefix .. 'T1') then
                    local fillColor = visuals.ReadColor(optionPrefix .. 'C1', Color3.new(1, 1, 1))
                    local fillTransparency = math.clamp(visuals.ReadNumber(optionPrefix .. 'S1', 0.5) or 0.5, 0, 1)
                    local outlineColor = visuals.ReadColor(optionPrefix .. 'C2', Color3.new(1, 1, 1))
                    local outlineTransparency = math.clamp(visuals.ReadNumber(optionPrefix .. 'S2', 0) or 0, 0, 1)
                    for _, root in ipairs(roots) do
                        active[root] = true
                        local highlight = entries[root]
                        if not highlight or highlight.Parent == nil then
                            highlight = Instance.new('Highlight')
                            highlight.Name = 'AkiraViewmodelHighlight_' .. scopeName
                            highlight.DepthMode = Enum.HighlightDepthMode.Occluded
                            highlight.Adornee = root
                            highlight.Parent = root
                            entries[root] = highlight
                        end
                        highlight.FillColor = fillColor
                        highlight.FillTransparency = fillTransparency
                        highlight.OutlineColor = outlineColor
                        highlight.OutlineTransparency = outlineTransparency
                    end
                end
                for root, highlight in pairs(entries) do
                    if not active[root] then
                        pcall(function() highlight:Destroy() end)
                        entries[root] = nil
                    end
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ReconcileModels()
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local scopes = visuals.ResolveScopes()
                local activeParts = {}
                local activeTextures = {}
                visuals.ApplyChamScope(scopes.Character, 'P1S19', activeParts, activeTextures)
                visuals.ApplyChamScope(scopes.Arms, 'P1S20', activeParts, activeTextures)
                visuals.ApplyChamScope(scopes.Item, 'P1S21', activeParts, activeTextures)
                for part, snapshot in pairs(visuals.AppearanceSnapshots) do
                    if not activeParts[part] then
                        visuals.RestoreAppearance(part, snapshot)
                        visuals.AppearanceSnapshots[part] = nil
                    end
                end
                for instance, snapshot in pairs(visuals.TextureSnapshots) do
                    if not activeTextures[instance] then
                        visuals.RestoreTexture(instance, snapshot)
                        visuals.TextureSnapshots[instance] = nil
                    end
                end
                visuals.ReconcileHighlights('Arms', scopes.Arms, 'P1S22')
                visuals.ReconcileHighlights('Item', scopes.Item, 'P1S23')
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ShimmerColorAt(elapsed, fraction, baseColor, fadeColor)
                local phase = (elapsed * 2.5) - (fraction * math.pi * 2)
                local wave = 0.5 + 0.5 * math.cos(phase)
                local highlight = wave * wave * (3 - 2 * wave)
                return fadeColor:Lerp(baseColor, highlight)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.PerimeterColorAt(elapsed, fraction, firstColor, secondColor)
                local phase = (elapsed * 2.0 + fraction * 2.0) * math.pi
                local wave = 0.5 + 0.5 * math.sin(phase)
                local smoothAlpha = wave * wave * (3 - 2 * wave)
                return firstColor:Lerp(secondColor, smoothAlpha)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.PingPongColorAt(elapsed, fraction, backgroundColor, mainColor, rotation)
                local rotRad = math.rad(rotation or 0)
                local armAngle = (fraction * 4.0) * (math.pi * 0.5) - (math.pi * 0.5)
                local proj = math.cos(armAngle - rotRad)
                local wavePos = math.sin(elapsed * math.pi * 1.5)
                local dist = math.abs(proj - wavePos)
                local t = math.clamp(1 - dist, 0, 1)
                local influence = t * t * (3 - 2 * t)
                return backgroundColor:Lerp(mainColor, influence)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ResolveLineColor(baseColor, fraction, elapsed)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if not visuals.ReadToggle('P1S26T10') then
                    return baseColor
                end
                local speed = visuals.ReadOption('P1S26S12', 1)
                local animationTime = elapsed * speed
                local kind = visuals.ReadOption('P1S26D3', 'Shimmer')
                if kind == 'Perimeter' then
                    return visuals.PerimeterColorAt(
                        animationTime, fraction,
                        visuals.ReadOption('P1S26C7', Color3.fromRGB(255, 0, 0)),
                        visuals.ReadOption('P1S26C8', Color3.fromRGB(0, 0, 255))
                    )
                elseif kind == 'PingPong' then
                    return visuals.PingPongColorAt(
                        animationTime, fraction,
                        visuals.ReadOption('P1S26C9', Color3.new(0, 0, 0)),
                        visuals.ReadOption('P1S26C10', Color3.new(1, 1, 1)),
                        visuals.ReadOption('P1S26S13', 0)
                    )
                end
                return visuals.ShimmerColorAt(
                    animationTime, fraction, baseColor,
                    visuals.ReadOption('P1S26C6', Color3.fromRGB(40, 40, 40))
                )
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ResolveTextGradient(elapsed, baseColor)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if not visuals.ReadToggle('P1S26T13') then
                    return ColorSequence.new(baseColor), Vector2.zero, 0
                end
                local speed = visuals.ReadOption('P1S26S17', 1)
                local animationTime = elapsed * speed
                if visuals.ReadOption('P1S26D5', 'Shimmer') == 'PingPong' then
                    local bg = visuals.ReadOption('P1S26C14', Color3.new(0, 0, 0))
                    local main = visuals.ReadOption('P1S26C15', Color3.new(1, 1, 1))
                    local rot = visuals.ReadOption('P1S26S18', 0)
                    local wavePos = math.sin(animationTime * math.pi * 1.5)
                    local colors = {}
                    for index = 0, 8 do
                        local fraction = index / 8
                        local proj = fraction * 2 - 1
                        local dist = math.abs(proj - wavePos)
                        local t = math.clamp(1 - dist / 0.8, 0, 1)
                        local influence = t * t * (3 - 2 * t)
                        colors[#colors + 1] = ColorSequenceKeypoint.new(fraction, bg:Lerp(main, influence))
                    end
                    return ColorSequence.new(colors), Vector2.zero, rot
                end
                local fadeColor = visuals.ReadOption('P1S26C13', Color3.fromRGB(40, 40, 40))
                local seq = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, fadeColor),
                    ColorSequenceKeypoint.new(0.5, baseColor),
                    ColorSequenceKeypoint.new(1, fadeColor),
                })
                local offsetWave = math.sin(animationTime * 2.2) * 0.65
                return seq, Vector2.new(offsetWave, 0), 45
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.CreateCrosshairArm(parent, name)
                local outline = Instance.new('Frame')
                outline.Name = name .. 'Outline'
                outline.AnchorPoint = Vector2.new(0.5, 0.5)
                outline.BorderSizePixel = 0
                outline.Parent = parent
                local fill = Instance.new('Frame')
                fill.Name = name
                fill.AnchorPoint = Vector2.new(0.5, 0.5)
                fill.BorderSizePixel = 0
                fill.Parent = parent
                return { Outline = outline, Fill = fill }
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.EnsureCrosshair()
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if visuals.Crosshair and visuals.Crosshair.Gui and visuals.Crosshair.Gui.Parent then
                    return visuals.Crosshair
                end
                local gui = Instance.new('ScreenGui')
                gui.Name = 'AkiraCustomCrosshair'
                gui.IgnoreGuiInset = true
                gui.ResetOnSpawn = false
                gui.DisplayOrder = 10000
                gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                gui.Parent = LP:FindFirstChild('PlayerGui') or WaitForChildTimeout(LP, 'PlayerGui', 1)
                local container = Instance.new('Frame')
                container.Name = 'Container'
                container.AnchorPoint = Vector2.new(0.5, 0.5)
                container.Size = UDim2.fromOffset(0, 0)
                container.BackgroundTransparency = 1
                container.Parent = gui
                local image = Instance.new('ImageLabel')
                image.Name = 'Image'
                image.AnchorPoint = Vector2.new(0.5, 0.5)
                image.Position = UDim2.fromOffset(0, 0)
                image.BackgroundTransparency = 1
                image.BorderSizePixel = 0
                image.Visible = false
                image.Parent = container
                local textLabel = Instance.new('TextLabel')
                textLabel.Name = 'Text'
                textLabel.AnchorPoint = Vector2.new(0.5, 0)
                textLabel.AutomaticSize = Enum.AutomaticSize.XY
                textLabel.BackgroundTransparency = 1
                textLabel.BorderSizePixel = 0
                textLabel.Text = ''
                textLabel.TextColor3 = Color3.new(1, 1, 1)
                textLabel.Visible = false
                textLabel.Parent = gui
                local textGradient = Instance.new('UIGradient')
                textGradient.Name = 'ColorGradient'
                textGradient.Parent = textLabel
                local textStroke = Instance.new('UIStroke')
                textStroke.Name = 'Outline'
                textStroke.Enabled = false
                textStroke.Parent = textLabel
                visuals.Crosshair = {
                    Gui = gui,
                    Container = container,
                    Image = image,
                    Text = textLabel,
                    TextGradient = textGradient,
                    TextStroke = textStroke,
                    Top = visuals.CreateCrosshairArm(container, 'Top'),
                    Bottom = visuals.CreateCrosshairArm(container, 'Bottom'),
                    Left = visuals.CreateCrosshairArm(container, 'Left'),
                    Right = visuals.CreateCrosshairArm(container, 'Right'),
                }
                return visuals.Crosshair
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ResolveCrosshairImage(value)
                value = type(value) == 'string' and value:match('^%s*(.-)%s*$') or ''
                if value == '' then
                    return ''
                end
                if value:match('^%d+$') then
                    return 'rbxassetid://' .. value
                end
                if value:match('^rbxasset') or value:match('^https?://') then
                    return value
                end
                if isfile and isfile(value) then
                    local customAsset = getcustomasset or getsynasset
                    if type(customAsset) == 'function' then
                        local ok, asset = pcall(customAsset, value)
                        if ok and type(asset) == 'string' then
                            return asset
                        end
                    end
                end
                return value
            end

