                },
                ['T-Style'] = {
                    Toggles = { P1S26T2 = true, P1S26T4 = true, P1S26T5 = true, P1S26T6 = true },
                    Options = { P1S26D1 = 'Lines', P1S26S1 = 10, P1S26S2 = 2, P1S26S3 = 5, P1S26S11 = 1 },
                    Colors = {
                        P1S26C1 = {0, 0, 0},
                        P1S26C2 = {0, 255, 0}, P1S26C3 = {0, 255, 0},
                        P1S26C4 = {0, 255, 0}, P1S26C5 = {0, 255, 0},
                    },
                },
                ['Krunker Cross'] = {
                    Toggles = { P1S26T2 = true, P1S26T3 = true, P1S26T4 = true, P1S26T5 = true, P1S26T6 = true },
                    Options = { P1S26D1 = 'Lines', P1S26S1 = 16, P1S26S2 = 2, P1S26S3 = 5, P1S26S11 = 1 },
                    Colors = {
                        P1S26C1 = {0, 0, 0},
                        P1S26C2 = {255, 255, 255}, P1S26C3 = {255, 255, 255},
                        P1S26C4 = {255, 255, 255}, P1S26C5 = {255, 255, 255},
                    },
                },
                ['Sniper Thin'] = {
                    Toggles = { P1S26T2 = true, P1S26T3 = true, P1S26T4 = true, P1S26T5 = true, P1S26T6 = true },
                    Options = { P1S26D1 = 'Lines', P1S26S1 = 20, P1S26S2 = 1, P1S26S3 = 2, P1S26S11 = 1 },
                    Colors = {
                        P1S26C1 = {0, 0, 0},
                        P1S26C2 = {255, 255, 255}, P1S26C3 = {255, 255, 255},
                        P1S26C4 = {255, 255, 255}, P1S26C5 = {255, 255, 255},
                    },
                },
                ['Rainbow Spin'] = {
                    Toggles = { P1S26T2 = true, P1S26T3 = true, P1S26T4 = true, P1S26T5 = true, P1S26T6 = true, P1S26T8 = true },
                    Options = { P1S26D1 = 'Lines', P1S26S1 = 10, P1S26S2 = 2, P1S26S3 = 6, P1S26S11 = 1, P1S26S4 = 0, P1S26S5 = 90 },
                    Colors = {
                        P1S26C1 = {0, 0, 0},
                        P1S26C2 = {255, 0, 0}, P1S26C3 = {0, 255, 0},
                        P1S26C4 = {0, 0, 255}, P1S26C5 = {255, 255, 0},
                    },
                },
            }

            function RivalsRuntimeBridge.ViewmodelVisuals.ApplyCrosshairPreset(name)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local preset = visuals.CrosshairPresets[name]
                if not preset then
                    return
                end
                local wanted = preset.Toggles or {}
                for _, toggleId in ipairs(visuals.CrosshairPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] ~= true and toggle.Value then
                        toggle:SetValue(false)
                    end
                end
                for optionId, value in pairs(preset.Options or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValue) == 'function' then
                        option:SetValue(value)
                    end
                end
                for optionId, rgb in pairs(preset.Colors or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValueRGB) == 'function' then
                        local color
                        if typeof(rgb) == 'Color3' then
                            color = rgb
                        elseif type(rgb) == 'table' then
                            color = Color3.fromRGB(tonumber(rgb[1]) or 255, tonumber(rgb[2]) or 255, tonumber(rgb[3]) or 255)
                        end
                        if color then
                            pcall(option.SetValueRGB, option, color)
                        end
                    end
                end
                for _, toggleId in ipairs(visuals.CrosshairPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] == true and not toggle.Value then
                        toggle:SetValue(true)
                    end
                end
                if Toggles and Toggles.P1S26T1 and not Toggles.P1S26T1.Value then
                    Toggles.P1S26T1:SetValue(true)
                end
                visuals.RefreshAll()
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.RestoreNativeCrosshairs()
                RivalsRuntimeBridge.NativeRemovals.SetNativeCrosshairHidden(false)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.HideNativeCrosshairs()
                RivalsRuntimeBridge.NativeRemovals.SetNativeCrosshairHidden(true)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.SetCrosshairArm(arm, position, size, color, outlineColor, outlineThickness, visible)
                arm.Fill.Visible = visible
                arm.Outline.Visible = visible and outlineThickness > 0
                arm.Fill.Position = UDim2.fromOffset(position.X, position.Y)
                arm.Fill.Size = UDim2.fromOffset(size.X, size.Y)
                arm.Fill.BackgroundColor3 = color
                arm.Outline.Position = arm.Fill.Position
                arm.Outline.Size = UDim2.fromOffset(size.X + outlineThickness * 2, size.Y + outlineThickness * 2)
                arm.Outline.BackgroundColor3 = outlineColor
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ResolveCrosshairPosition(deltaTime, center)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local followEnabled = visuals.ReadToggle('P1S26T9')
                local alwaysFollow = visuals.ReadToggle('P1S26_AlwaysFollow')
                if not followEnabled and not alwaysFollow then
                    visuals.FollowPosition = center
                    return center
                end
                local targetPosition = center
                local hasTarget = false
                if type(RivalsRuntimeBridge.GetBestAimbotTarget) == 'function' then
                    local targetInfo
                    local requireVis = not alwaysFollow
                    local silentAimOn = visuals.ReadToggle('P2S1T1') and AimbotBridge.IsSilentAimFullyActive()
                    local cameraAimOn = AimbotBridge.IsDirectAimbotEnabled()

                    if alwaysFollow or silentAimOn or cameraAimOn or followEnabled then
                        if not alwaysFollow and cameraAimOn and RivalsRuntimeBridge.CurrentCameraAimTarget then
                            targetInfo = RivalsRuntimeBridge.CurrentCameraAimTarget
                        elseif not alwaysFollow and silentAimOn and AimbotSilentState.HookTarget then
                            targetInfo = AimbotSilentState.HookTarget
                        elseif not alwaysFollow and (os.clock() - (RivalsRuntimeBridge.LastAimbotSweepAt or 0) <= 0.05) then
                            targetInfo = RivalsRuntimeBridge.LastAimbotSweepTarget
                        end

                        if not targetInfo or (alwaysFollow and not targetInfo.worldPosition and not targetInfo.part) then
                            targetInfo = RivalsRuntimeBridge.GetBestAimbotTarget(requireVis, true, 'Auto', 9999)
                        end

                        local camera = Workspace.CurrentCamera
                        if targetInfo and camera then
                            local worldPos = (targetInfo.part and targetInfo.part.Position) or targetInfo.worldPosition
                            if worldPos then
                                local projected, onScreen = camera:WorldToViewportPoint(worldPos)
                                if onScreen and projected.Z > 0 then
                                    targetPosition = Vector2.new(projected.X, projected.Y)
                                    hasTarget = true
                                elseif alwaysFollow then
                                    local viewport = camera.ViewportSize or Vector2.new(1920, 1080)
                                    local camCFrame = camera.CFrame
                                    local localVec = camCFrame:PointToObjectSpace(worldPos)
                                    local dir
                                    if localVec.Z >= 0 then
                                        dir = Vector2.new(localVec.X, -localVec.Y)
                                    else
                                        dir = Vector2.new(projected.X - center.X, projected.Y - center.Y)
                                    end
                                    if dir.Magnitude < 0.001 then
                                        dir = Vector2.new(0, 1)
                                    end
                                    local unitDir = dir.Unit
                                    local margin = 70
                                    local distX = (math.abs(unitDir.X) > 1e-5) and (((unitDir.X > 0 and (viewport.X - margin - center.X) or (margin - center.X)) / unitDir.X)) or math.huge
                                    local distY = (math.abs(unitDir.Y) > 1e-5) and (((unitDir.Y > 0 and (viewport.Y - margin - center.Y) or (margin - center.Y)) / unitDir.Y)) or math.huge
                                    local maxDist = math.min(math.abs(distX), math.abs(distY))
                                    targetPosition = center + unitDir * maxDist
                                    hasTarget = true
                                end
                            end
                        end
                    end
                end
                if not visuals.FollowPosition then
                    visuals.FollowPosition = targetPosition
                end
                local speed = (alwaysFollow or hasTarget) and 35 or 15
                local alpha = math.clamp(1 - math.exp(-math.max(deltaTime or 0, 0) * speed), 0, 1)
                visuals.FollowPosition = visuals.FollowPosition:Lerp(targetPosition, alpha)
                return visuals.FollowPosition
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.GetUnderCrosshairPosition(fallbackCenter)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local layout = visuals.CrosshairLayout
                if layout and layout.NextStackY then
                    local posX
                    if layout.HasText and layout.TextPosition then
                        posX = layout.TextPosition.X
                    elseif fallbackCenter and typeof(fallbackCenter) == 'Vector2' then
                        posX = fallbackCenter.X
                    elseif layout.Center then
                        posX = layout.Center.X
                    end
                    if not posX then
                        local cam = Workspace.CurrentCamera
                        local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                        posX = vp.X * 0.5
                    end
                    return Vector2.new(posX, layout.NextStackY)
                end
                local cam = Workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                local cx = (fallbackCenter and fallbackCenter.X) or (vp.X * 0.5)
                local cy = (fallbackCenter and fallbackCenter.Y) or (vp.Y * 0.5)
                return Vector2.new(cx, cy + 22)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.UpdateCrosshair(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if not visuals.ReadToggle('P1S26T1') then
                    if visuals.Crosshair and visuals.Crosshair.Gui then
                        visuals.Crosshair.Gui.Enabled = false
                    end
                    visuals.FollowPosition = nil
                    visuals.CrosshairLayout = nil
                    visuals.RestoreNativeCrosshairs()
                    return
                end

                if not RivalsRuntimeBridge.NativeRemovals.IsNativeCrosshairActive() then
                    if visuals.Crosshair and visuals.Crosshair.Gui then
                        visuals.Crosshair.Gui.Enabled = false
                    end
                    visuals.CrosshairLayout = nil
                    visuals.RestoreNativeCrosshairs()
                    return
                end

                visuals.HideNativeCrosshairs()

                local crosshair = visuals.EnsureCrosshair()
                crosshair.Gui.Enabled = true
                local camera = Workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
                local center = Vector2.new(viewport.X * 0.5, viewport.Y * 0.5)
                local position = visuals.ResolveCrosshairPosition(deltaTime, center)
                crosshair.Container.Position = UDim2.fromOffset(math.round(position.X), math.round(position.Y))
                local textPosition = center
                if (visuals.ReadToggle('P1S26T9') or visuals.ReadToggle('P1S26_AlwaysFollow'))
                    and visuals.ReadOption('P1S26D2', 'Crosshair') == 'Crosshair + Text' then
                    textPosition = position
                end
                local elapsed = os.clock()

                local angle = visuals.ReadOption('P1S26S4', 0)
                if visuals.ReadToggle('P1S26T8') then
                    angle = (angle + elapsed * visuals.ReadOption('P1S26S5', 90)) % 360
                end
                crosshair.Container.Rotation = angle
                local style = visuals.ReadOption('P1S26D1', 'Lines')
                local imageMode = style == 'Image'
                crosshair.Image.Visible = imageMode
                if imageMode then
                    local size = visuals.ReadOption('P1S26S6', 32)
                    crosshair.Image.Size = UDim2.fromOffset(size, size)
                    crosshair.Image.Image = visuals.ResolveCrosshairImage(visuals.ReadOption('P1S26I1', ''))
                    crosshair.Image.ImageTransparency = math.clamp(visuals.ReadOption('P1S26S7', 0), 0, 1)
                end

                local length = visuals.ReadOption('P1S26S1', 12)
                local thickness = visuals.ReadOption('P1S26S2', 2)
                local gap = visuals.ReadOption('P1S26S3', 6)
                if visuals.ReadToggle('P1S26T7') then
                    local minimum = visuals.ReadOption('P1S26S8', 4)
                    local maximum = visuals.ReadOption('P1S26S9', 16)
                    local wave = 0.5 - 0.5 * math.cos(elapsed * visuals.ReadOption('P1S26S10', 3))
                    gap = gap + minimum + (maximum - minimum) * wave
                end
                local outlineThickness = visuals.ReadToggle('P1S26T2') and visuals.ReadOption('P1S26S11', 1) or 0
                local outlineColor = visuals.ReadOption('P1S26C1', Color3.new(0, 0, 0))

                local bottomExtent
                if imageMode then
                    bottomExtent = (visuals.ReadOption('P1S26S6', 32) or 32) * 0.5
                else
                    local hasBottomArm = visuals.ReadToggle('P1S26T4')
                    if hasBottomArm then
                        bottomExtent = gap + length + outlineThickness
                    else
                        bottomExtent = math.max(gap, 6)
                    end
                end

                local textEnabled = visuals.ReadToggle('P1S26T11')
                local rawText = tostring(visuals.ReadOption('P1S26I2', ''))
                local hasContent = textEnabled and (rawText:match('%S') ~= nil)
                crosshair.Text.Visible = textEnabled and hasContent
                local textHeight = 0
                local userOffset = visuals.ReadOption('P1S26S15', 24)
                local textYOffset = math.max(userOffset, bottomExtent + 6)
                if textEnabled and hasContent then
                    crosshair.Text.Text = rawText
                    local textSize = visuals.ReadOption('P1S26S14', 14)
                    crosshair.Text.TextSize = textSize
                    crosshair.Text.Font = visuals.FontMap[visuals.ReadOption('P1S26D4', 'Inconsolata')] or Enum.Font.Code
                    crosshair.Text.Position = UDim2.fromOffset(
                        math.round(textPosition.X),
                        math.round(textPosition.Y + textYOffset)
                    )
                    local textColor = visuals.ReadOption('P1S26C11', Color3.new(1, 1, 1))
                    local gradientColor, gradientOffset, gradientRotation = visuals.ResolveTextGradient(elapsed, textColor)
                    crosshair.TextGradient.Color = gradientColor
                    crosshair.TextGradient.Offset = gradientOffset
                    crosshair.TextGradient.Rotation = gradientRotation
                    crosshair.TextStroke.Enabled = visuals.ReadToggle('P1S26T12')
                    crosshair.TextStroke.Color = visuals.ReadOption('P1S26C12', Color3.new(0, 0, 0))
                    crosshair.TextStroke.Thickness = visuals.ReadOption('P1S26S16', 1)

                    local boundsY = crosshair.Text.TextBounds.Y
                    textHeight = (boundsY and boundsY > 0) and boundsY or textSize
                end

                local nextY
                if hasContent then
                    nextY = textPosition.Y + textYOffset + textHeight + 4
                else
                    nextY = position.Y + bottomExtent + 6
                end
                visuals.CrosshairLayout = {
                    Center = position,
                    TextPosition = textPosition,
                    BottomExtent = bottomExtent,
                    HasText = hasContent,
                    TextBottomY = hasContent and (textPosition.Y + textYOffset + textHeight) or nil,
                    NextStackY = nextY,
                }

                local armDefinitions = {
                    {Key = 'Top', Position = Vector2.new(0, -(gap + length * 0.5)), Size = Vector2.new(thickness, length), Toggle = 'P1S26T3', Color = 'P1S26C2', Fraction = 0},
                    {Key = 'Bottom', Position = Vector2.new(0, gap + length * 0.5), Size = Vector2.new(thickness, length), Toggle = 'P1S26T4', Color = 'P1S26C3', Fraction = 0.5},
                    {Key = 'Left', Position = Vector2.new(-(gap + length * 0.5), 0), Size = Vector2.new(length, thickness), Toggle = 'P1S26T5', Color = 'P1S26C4', Fraction = 0.75},
                    {Key = 'Right', Position = Vector2.new(gap + length * 0.5, 0), Size = Vector2.new(length, thickness), Toggle = 'P1S26T6', Color = 'P1S26C5', Fraction = 0.25},
                }
                for _, definition in ipairs(armDefinitions) do
                    local baseColor = visuals.ReadOption(definition.Color, Color3.new(1, 1, 1))
                    visuals.SetCrosshairArm(
                        crosshair[definition.Key], definition.Position, definition.Size,
                        visuals.ResolveLineColor(baseColor, definition.Fraction, elapsed),
                        outlineColor, outlineThickness,
                        not imageMode and visuals.ReadToggle(definition.Toggle)
                    )
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.RefreshAll()
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                RivalsRuntimeBridge.ViewmodelVisuals.LastReconcileAt = tick()
                RivalsRuntimeBridge.ViewmodelVisuals.ReconcileModels()
                RivalsRuntimeBridge.ViewmodelVisuals.UpdateCrosshair(0)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.Update(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local liveChams = visuals.ReadToggle('P1S19T1')
                    or visuals.ReadToggle('P1S20T1')
                    or visuals.ReadToggle('P1S21T1')
                    or visuals.ReadToggle('P1S22T1')
                    or visuals.ReadToggle('P1S23T1')
                if liveChams then
                    local now = tick()
                    if (now - (visuals.LastReconcileAt or 0)) >= 0.25 then
                        visuals.LastReconcileAt = now
                        visuals.ReconcileModels()
                    end
                end
                if visuals.ReadToggle('P1S26T1') then
                    visuals._NativeRestored = false
                    visuals.UpdateCrosshair(deltaTime)
                else
                    if visuals.Crosshair and visuals.Crosshair.Gui then
                        visuals.Crosshair.Gui.Enabled = false
                    end
                    visuals.CrosshairLayout = nil
                    if not visuals._NativeRestored then
                        visuals.RestoreNativeCrosshairs()
                        visuals._NativeRestored = true
                    end
                end
                local hudOn = (Toggles.P1S50T1 and Toggles.P1S50T1.Value == true)
                    or (Toggles.P8S4T20 and Toggles.P8S4T20.Value == true)
                    or (Toggles.P8S4T21 and Toggles.P8S4T21.Value == true)
                if hudOn then
                    local targetHud = RivalsRuntimeBridge.TargetHud
                    if targetHud and type(targetHud.Update) == 'function' then
                        targetHud.Update(deltaTime)
                    end
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.Destroy()
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                visuals.CrosshairLayout = nil
                visuals.RestoreNativeCrosshairs()
                for part, snapshot in pairs(visuals.AppearanceSnapshots) do
                    visuals.RestoreAppearance(part, snapshot)
                end
                visuals.AppearanceSnapshots = setmetatable({}, { __mode = 'k' })
                for instance, snapshot in pairs(visuals.TextureSnapshots) do
                    visuals.RestoreTexture(instance, snapshot)
                end
                visuals.TextureSnapshots = {}
                for _, entries in pairs(visuals.Highlights) do
                    for _, highlight in pairs(entries) do
                        pcall(function() highlight:Destroy() end)
                    end
                end
                visuals.Highlights = {}
                if visuals.Crosshair and visuals.Crosshair.Gui then
                    pcall(function() visuals.Crosshair.Gui:Destroy() end)
                end
                visuals.Crosshair = nil
                visuals.FollowPosition = nil
                visuals.LastReconcileAt = 0
            end

            ;(function()
                local hud = {
                    GhostHp = 1,
                    DisplayHp = 1,
                    GhostDelayUntil = 0,
                    LastPlayer = nil,
                    LastTargetName = nil,
                    SwapUntil = 0,
                    SwapFrom = nil,
                    LostHp = 0,
                    GainedHp = 0,
                    LastHp = nil,
                    IconCache = {},
                    ThumbCache = {},
                    ThumbPending = {},
                    LastUiAt = 0,
                    TypeIndex = 0,
                    TypeUntil = 0,
                }
                RivalsRuntimeBridge.TargetHud = hud

                local function hudParent()
                    local parent = nil
                    pcall(function()
                        if type(gethui) == 'function' then
                            parent = gethui()
                        end
                    end)
                    if typeof(parent) ~= 'Instance' or parent.Name == 'RobloxGui' then
                        parent = CoreGui
                    end
                    return parent
                end

                local function hudToggle(id, fallback)
                    local toggle = Toggles[id]
                    if toggle ~= nil then
                        return toggle.Value == true
                    end
                    return fallback == true
                end

                local function hudOption(id, fallback)
                    local option = Options[id]
                    if option ~= nil and option.Value ~= nil then
                        return option.Value
                    end
                    return fallback
                end

                local function hudColor(id, fallback)
                    local option = Options[id]
                    local value = option and option.Value
                    if typeof(value) == 'Color3' then
                        return value
                    end
                    return fallback
                end

                local function findPlayerByName(name)
                    if type(name) ~= 'string' or name == '' then
                        return nil
                    end
                    local direct = Players:FindFirstChild(name)
                    if direct then
                        return direct
                    end
                    for _, player in ipairs(Players:GetPlayers()) do
                        if player.Name == name or player.DisplayName == name then
                            return player
                        end
                    end
                    return nil
                end

                local function resolveHudTarget()
                    if hudToggle('P8S4T1', false) then
                        local getter = RivalsRuntimeBridge.GetAkiraRagebotTargetName
                        local rageName = type(getter) == 'function' and getter() or nil
                        local ragePlayer = findPlayerByName(rageName)
                        if ragePlayer then
                            return ragePlayer, rageName, 'rage'
                        end
                        if type(rageName) == 'string' and rageName ~= '' then
                            return nil, rageName, 'rage'
                        end
                    end
                    local aim = RivalsRuntimeBridge.CurrentCameraAimTarget
                    local aimPlayer = aim and (aim.player or aim.Player)
                    if typeof(aimPlayer) == 'Instance' then
                        return aimPlayer, aim.displayName or aimPlayer.DisplayName or aimPlayer.Name, 'aim'
                    end
                    local hook = AimbotSilentState and AimbotSilentState.HookTarget
                    local hookPlayer = hook and (hook.player or hook.Player)
                    if typeof(hookPlayer) == 'Instance' then
                        return hookPlayer, hookPlayer.DisplayName or hookPlayer.Name, 'silent'
                    end
                    return nil, nil, nil
                end

                local function healthColor(ratio)
                    if ratio > 0.35 then
                        return Color3.fromRGB(70, 170, 255)
                    end
                    return Color3.fromRGB(70, 170, 255):Lerp(Color3.fromRGB(230, 70, 70), (0.35 - ratio) / 0.35)
                end

                local function deviceLabel(player)
                    if player == LP then
                        if UserInputService.VREnabled then
                            return 'virtualreality'
                        end
                        if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
                            return 'mobile'
                        end
                        if UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
                            return 'console'
                        end
                        return 'pc'
                    end
                    local raw = player:GetAttribute('Device') or player:GetAttribute('InputDevice') or player:GetAttribute('Platform')
                    if type(raw) == 'string' and raw ~= '' then
                        return string.lower(raw)
                    end
                    return 'unknown'
                end

                local function weaponIcon(name)
                    if type(name) ~= 'string' or name == '' then
                        return ''
                    end
                    local cached = hud.IconCache[name]
                    if cached ~= nil then
                        return cached
                    end
                    local lib = hud.ItemLib
                    if type(lib) ~= 'table' then
                        if not hud.ItemLibPending then
                            hud.ItemLibPending = true
                            task.defer(function()
                                pcall(function()
                                    local modules = ReplicatedStorage:FindFirstChild('Modules')
                                    local module = modules and modules:FindFirstChild('ItemLibrary')
                                    if module then
                                        local ok, required = pcall(require, module)
                                        if ok and type(required) == 'table' then
                                            hud.ItemLib = required
                                        end
                                    end
                                end)
                                hud.ItemLibPending = false
                            end)
                        end
                        return ''
                    end
                    local image = ''
                    if type(lib.GetViewModelImage) == 'function' then
                        local ok, got = pcall(lib.GetViewModelImage, lib, name)
                        if ok and type(got) == 'string' then
                            image = got
                        end
                    end
                    if image == '' and type(lib.Items) == 'table' and type(lib.Items[name]) == 'table' then
                        if type(lib.GetViewModelImageFromWeaponData) == 'function' then
                            local ok2, got2 = pcall(lib.GetViewModelImageFromWeaponData, lib, lib.Items[name], true)
                            if ok2 and type(got2) == 'string' then
                                image = got2
                            end
                        end
                    end
                    hud.IconCache[name] = image
                    return image
                end

                local function avatarImage(player)
                    if not player then
                        return ''
                    end
                    local uid = player.UserId
                    if hud.ThumbCache[uid] then
                        return hud.ThumbCache[uid]
                    end
                    if hud.ThumbPending[uid] then
                        return ''
                    end
                    hud.ThumbPending[uid] = true
                    task.spawn(function()
                        local ok, content = pcall(function()
                            return Players:GetUserThumbnailAsync(uid, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
                        end)
                        hud.ThumbCache[uid] = (ok and type(content) == 'string') and content or ''
                        hud.ThumbPending[uid] = nil
                    end)
                    return ''
                end

                local function collectWeapons(player)
                    local names = {}
                    local equipped = nil
                    local seen = {}
                    local function add(name)
                        if type(name) == 'string' and name ~= '' and not seen[name] then
                            seen[name] = true
                            names[#names + 1] = name
                        end
                    end
                    local fighter = TrackedFightersByPlayer[player]
                    if fighter then
                        equipped = ResolveRivalsFighterEquippedItemName(fighter)
                        local inventory = ReadRivalsFighterInventory(fighter)
                        if type(inventory) == 'table' then
                            for _, item in pairs(inventory) do
                                add(ResolveRivalsInventoryItemName(item))
                            end
                        end
                        local lastPicked = fighter.Data and fighter.Data.LastPickedWeapons
                        if type(lastPicked) == 'table' then
                            for _, name in ipairs(lastPicked) do
                                add(name)
                            end
                        end
                    end
                    local info = ReadWeaponInfo(player)
                    if info and info.label and info.label ~= '*Reloading*' then
                        add(info.label)
                        equipped = equipped or info.label
                    end
                    return names, equipped
                end

                local function readLocalAmmo()
                    local info = ReadWeaponInfo(LP)
                    if not info then
                        return nil
                    end
                    local mag = info.ammo
                    local reserveText = nil
                    local observer = WeaponInfoConnections[LP]
                    local reserve = observer and observer.AmmoReserve
                    local maxAmmo = info.maxAmmo
                    local magText = FormatAmmoValue(mag) or '--'
                    local maxText = FormatAmmoValue(maxAmmo)
                    local leftText = FormatAmmoValue(reserve)
                    if maxText then
                        return string.format('%s/%s', magText, maxText), leftText
                    end
                    if leftText then
                        return magText, leftText
                    end
                    return magText, nil
                end

                local function makeLabel(parent, props)
                    local label = Instance.new('TextLabel')
                    label.BackgroundTransparency = 1
                    label.BorderSizePixel = 0
                    label.Font = Enum.Font.Gotham
                    label.TextColor3 = Color3.fromRGB(230, 232, 240)
                    label.TextXAlignment = Enum.TextXAlignment.Left
                    label.TextYAlignment = Enum.TextYAlignment.Center
                    label.TextSize = 14
                    label.ZIndex = 6
                    for key, value in pairs(props) do
                        label[key] = value
                    end
                    label.Parent = parent
                    return label
                end

                function hud.Destroy()
                    if hud.Gui then
                        pcall(function()
                            hud.Gui:Destroy()
                        end)
                    end
                    hud.Gui = nil
                    hud.Card = nil
                    hud.Xh = nil
                    hud.XhText = nil
                    hud.Slots = nil
                    hud.RageBar = nil
                    hud.Avatar = nil
                end

