                local function placeCard(card)
                    local pos = hudOption('P1S50D1', 'Bottom Left')
                    if pos == 'Top Left' then
                        card.AnchorPoint = Vector2.new(0, 0)
                        card.Position = UDim2.new(0, 18, 0, 72)
                    elseif pos == 'Top Right' then
                        card.AnchorPoint = Vector2.new(1, 0)
                        card.Position = UDim2.new(1, -18, 0, 72)
                    elseif pos == 'Bottom Right' then
                        card.AnchorPoint = Vector2.new(1, 1)
                        card.Position = UDim2.new(1, -18, 1, -18)
                    else
                        card.AnchorPoint = Vector2.new(0, 1)
                        card.Position = UDim2.new(0, 18, 1, -18)
                    end
                end

                local _hudSeqOff = ColorSequence.new(Color3.fromRGB(230, 90, 90), Color3.fromRGB(255, 180, 180))
                local _hudSeqSwap = ColorSequence.new(Color3.fromRGB(255, 210, 90), Color3.fromRGB(255, 255, 255))
                local _hudSeqOn = ColorSequence.new(Color3.fromRGB(90, 220, 130), Color3.fromRGB(255, 255, 255))
                local _hudSeqNone = ColorSequence.new(Color3.fromRGB(180, 186, 200), Color3.fromRGB(230, 232, 240))

                function hud.Update(deltaTime)
                    LPH_ATTRIBUTES(VM(NONE))
                    if shutting_down then
                        return
                    end
                    local showHud = hudToggle('P1S50T1', false)
                    local showRage = hudToggle('P8S4T20', false)
                    local showXh = hudToggle('P8S4T21', false)
                    if not showHud and not showRage and not showXh then
                        if hud.Gui then
                            hud.Gui.Enabled = false
                            if hud.Card then
                                hud.Card.Visible = false
                            end
                            if hud.Xh then
                                hud.Xh.Visible = false
                            end
                        end
                        return
                    end

                    local now = os.clock()
                    if now - (hud.LastUiAt or 0) < 0.03 then
                        return
                    end
                    hud.LastUiAt = now

                    hud.Ensure()
                    hud.Gui.Enabled = true
                    local dt = type(deltaTime) == 'number' and deltaTime or (1 / 60)
                    local player, targetName, source = resolveHudTarget()
                    local rageOn = hudToggle('P8S4T1', false)

                    if targetName and targetName ~= hud.LastTargetName then
                        if hud.LastTargetName then
                            hud.SwapFrom = hud.LastTargetName
                            hud.SwapUntil = now + 0.7
                        end
                        hud.LastTargetName = targetName
                        hud.LostHp = 0
                        hud.GainedHp = 0
                        hud.LastHp = nil
                    end

                    local swapping = now < hud.SwapUntil
                    local accent = hudColor('P1S50C1', Color3.fromRGB(56, 130, 255))
                    hud.Stroke.Color = swapping and Color3.fromRGB(255, 196, 72) or accent

                    if showHud and player and player.Character then
                        hud.Card.Visible = true
                        placeCard(hud.Card)
                        local display = player and (player.DisplayName or player.Name) or targetName
                        if hud.NameLabel.Text ~= display then
                            hud.NameLabel.Text = display
                        end
                        local thumb = avatarImage(player)
                        if hud.Avatar and thumb ~= '' and hud.Avatar.Image ~= thumb then
                            hud.Avatar.Image = thumb
                        end
                        if hud.AvatarStroke then
                            hud.AvatarStroke.Color = accent
                        end
                        local level = player and tonumber(player:GetAttribute('Level')) or nil
                        local streak = player and tonumber(player:GetAttribute('StatisticDuelsWinStreak')) or 0
                        local rank = 'Unranked'
                        if player then
                            local status = GetCachedPlayerStatusInfo(player)
                            rank = status and status.Rank or rank
                        end
                        local device = player and deviceLabel(player) or 'unknown'
                        local accentHex = string.format('#%02x%02x%02x', math.floor(accent.R * 255), math.floor(accent.G * 255), math.floor(accent.B * 255))
                        local meta = string.format(
                            'level %s  rank <font color="%s">%s</font>  device <font color="%s">%s</font>  streak <font color="%s">%d</font>',
                            level and tostring(math.floor(level)) or '--',
                            accentHex,
                            string.lower(tostring(rank)),
                            accentHex,
                            device,
                            accentHex,
                            math.max(0, math.floor(streak))
                        )
                        if hud.MetaLabel.Text ~= meta then
                            hud.MetaLabel.Text = meta
                        end

                        local hum = player and player.Character and player.Character:FindFirstChildOfClass('Humanoid')
                        local hp = hum and hum.Health or 0
                        local maxHp = (hum and hum.MaxHealth and hum.MaxHealth > 0) and hum.MaxHealth or 100
                        local ratio = math.clamp(hp / maxHp, 0, 1)
                        if hud.LastPlayer ~= player then
                            hud.GhostHp = ratio
                            hud.DisplayHp = ratio
                            hud.LastPlayer = player
                            hud.LastHp = hp
                            hud.LostHp = 0
                            hud.GainedHp = 0
                        elseif hud.LastHp ~= nil then
                            local delta = hp - hud.LastHp
                            if delta < -0.5 then
                                hud.LostHp = hud.LostHp - delta
                                if hudToggle('P1S50T2', true) then
                                    hud.GhostDelayUntil = now + 0.12
                                else
                                    hud.GhostHp = ratio
                                end
                            elseif delta > 0.5 then
                                hud.GainedHp = hud.GainedHp + delta
                                hud.GhostHp = ratio
                            end
                            hud.LastHp = hp
                        end
                        hud.DisplayHp = hud.DisplayHp + (ratio - hud.DisplayHp) * math.clamp(dt * 14, 0, 1)
                        if now >= hud.GhostDelayUntil then
                            if hud.GhostHp > hud.DisplayHp then
                                hud.GhostHp = hud.GhostHp + (hud.DisplayHp - hud.GhostHp) * math.clamp(dt * 5, 0, 1)
                            else
                                hud.GhostHp = hud.DisplayHp
                            end
                        end
                        hud.HealthFill.Size = UDim2.fromScale(math.clamp(hud.DisplayHp, 0, 1), 1)
                        hud.HealthFill.BackgroundColor3 = healthColor(hud.DisplayHp)
                        hud.HealthGhost.Size = UDim2.fromScale(math.clamp(hud.GhostHp, 0, 1), 1)
                        hud.HealthValue.Text = string.format('%d / %d', math.floor(hp + 0.5), math.floor(maxHp + 0.5))
                        hud.RatioUp.Text = string.format('%d', math.floor(hud.GainedHp + 0.5))
                        hud.RatioDown.Text = string.format('%d', math.floor(hud.LostHp + 0.5))

                        if hud.RageBar then
                            hud.RageBar.Visible = showRage
                        end
                        if showRage then
                            local statusText
                            if not rageOn then
                                statusText = 'Ragebot: off'
                            elseif swapping then
                                statusText = 'Ragebot: swapping'
                            elseif targetName then
                                statusText = 'Ragebot: ' .. tostring(targetName)
                            else
                                statusText = 'Ragebot: none'
                            end
                            if hud.RageStatus.Text ~= statusText then
                                hud.RageStatus.Text = statusText
                            end
                            hud.RageTarget.Text = ''
                            local mag, left = readLocalAmmo()
                            if mag then
                                hud.RageAmmo.Text = left and (mag .. '  +' .. left) or mag
                            else
                                hud.RageAmmo.Text = ''
                            end
                            if swapping and hud.SwapFrom then
                                hud.RageSub.Text = tostring(hud.SwapFrom) .. ' → ' .. tostring(targetName or '?')
                            else
                                hud.RageSub.Text = ''
                            end
                            local wave = (now * 0.55) % 2 - 1
                            if hud.RageStatusGrad then
                                hud.RageStatusGrad.Offset = Vector2.new(wave, 0)
                                local targetSeq = (mode == 'OFF' and _hudSeqOff) or (mode == 'SWAP' and _hudSeqSwap) or _hudSeqOn
                                if hud.RageStatusGrad.Color ~= targetSeq then
                                    hud.RageStatusGrad.Color = targetSeq
                                end
                            end
                        end

                        if hudToggle('P1S50T3', true) and player then
                            local weapons, equipped = collectWeapons(player)
                            for index = 1, 6 do
                                local slot = hud.Slots[index]
                                local name = weapons[index]
                                if name then
                                    slot.Frame.Visible = true
                                    local image = weaponIcon(name)
                                    if image ~= '' and slot.Frame.Image ~= image then
                                        slot.Frame.Image = image
                                    end
                                    if slot.Cap then
                                        slot.Cap.Text = (image == '' and slot.Frame.Image == '') and name or ''
                                    end
                                    local selected = equipped == name
                                    slot.Stroke.Transparency = selected and 0.15 or 1
                                    slot.Stroke.Thickness = selected and 1.6 or 0
                                    slot.Stroke.Color = accent
                                else
                                    slot.Frame.Visible = false
                                end
                            end
                        else
                            for index = 1, 6 do
                                hud.Slots[index].Frame.Visible = false
                            end
                        end
                    else
                        hud.Card.Visible = false
                    end

                    if showXh and showRage and rageOn then
                        local status
                        if swapping then
                            status = 'Ragebot: swapping'
                        elseif targetName then
                            status = 'Ragebot: ' .. tostring(targetName)
                        else
                            status = 'Ragebot: none'
                        end
                        if hud.XhText and hud.XhText.Text ~= status then
                            hud.XhText.Text = status
                        end
                        if hud.XhGrad then
                            hud.XhGrad.Offset = Vector2.new(math.sin(now * 2.2) * 0.65, 0)
                            local targetSeq = (swapping and _hudSeqSwap) or (targetName and _hudSeqOn) or _hudSeqNone
                            if hud.XhGrad.Color ~= targetSeq then
                                hud.XhGrad.Color = targetSeq
                            end
                        end
                        if hud.XhStroke then
                            hud.XhStroke.Transparency = 1
                        end
                        if hud.Xh then
                            hud.Xh.BackgroundTransparency = 1
                        end
                        local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                        local pos = visuals and visuals.FollowPosition
                        local cam = Workspace.CurrentCamera
                        local center = cam and cam.ViewportSize and Vector2.new(cam.ViewportSize.X * 0.5, cam.ViewportSize.Y * 0.5) or Vector2.new(960, 540)
                        if typeof(pos) ~= 'Vector2' then
                            pos = center
                        end
                        local targetPos = visuals and visuals.GetUnderCrosshairPosition and visuals.GetUnderCrosshairPosition(pos)
                        if targetPos then
                            hud.Xh.Position = UDim2.fromOffset(math.round(targetPos.X), math.round(targetPos.Y))
                        else
                            hud.Xh.Position = UDim2.fromOffset(math.round(pos.X), math.round(pos.Y + 22))
                        end
                        hud.Xh.Visible = true
                    elseif hud.Xh then
                        hud.Xh.Visible = false
                    end
                end
            end)()

            RivalsRuntimeBridge.NativeRemovals = {
                Modules = {},
                Vignette = nil,
                Tracers = nil,
                Muzzle = nil,
                Hitsound = nil,
                Scope = {
                    OverlayHidden = false,
                    ReticleHidden = false,
                    OverlayDirty = false,
                    ReticleDirty = false,
                    Restore = nil,
                },
                Crosshair = {
                    CrosshairVisible = nil,
                    HitmarkerVisible = nil,
                    Restore = nil,
                },
                Animation = { Restore = nil },
            }

            RivalsRuntimeBridge.NativeRemovals.TracerSentinel = '_Tracers\0NoGunTracers'
            RivalsRuntimeBridge.NativeRemovals.MuzzleStub = { PlayParticles = function() end }

            RivalsRuntimeBridge.NativeRemovals.ModulePaths = {
                Other = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ItemInterface', 'Other' },
                Scope = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ItemInterface', 'Mouse', 'Scope' },
                Gun = { 'Modules', 'ItemTypes', 'Gun' },
                ClientViewModel = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ClientViewModel' },
                Crosshair = { 'Modules', 'Crosshair' },
                ViewModelAnimator = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ClientViewModel', 'ViewModelAnimator' },
            }

            RivalsRuntimeBridge.NativeRemovals.AnimationStub = {
                Play = function() end,
                Stop = function() end,
            }

            function RivalsRuntimeBridge.NativeRemovals.RequireModule(key)
                local native = RivalsRuntimeBridge.NativeRemovals
                local cached = native.Modules[key]
                if cached then
                    return cached
                end
                local path = native.ModulePaths[key]
                local cursor = LP:FindFirstChild('PlayerScripts')
                for _, segment in ipairs(path or {}) do
                    cursor = cursor and cursor:FindFirstChild(segment)
                end
                if not cursor then
                    return nil
                end
                local ok, value = pcall(require, cursor)
                if not ok or type(value) ~= 'table' then
                    return nil
                end
                native.Modules[key] = value
                return value
            end

            function RivalsRuntimeBridge.NativeRemovals.ReadConstant(method, index)
                for constantIndex, constantValue in debug.getconstants(method) do
                    if constantIndex == index then
                        return constantValue
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.NativeRemovals.SetVignetteHidden(hidden)
                local native = RivalsRuntimeBridge.NativeRemovals
                if hidden then
                    if native.Vignette then
                        return
                    end
                    local other = native.RequireModule('Other')
                    local update = other and rawget(other, 'Update') or nil
                    if type(update) ~= 'function' then
                        return
                    end
                    local original = native.ReadConstant(update, 2)
                    if type(original) ~= 'number' then
                        return
                    end
                    debug.setconstant(update, 2, 999)
                    native.Vignette = { method = update, index = 2, value = original }
                else
                    local record = native.Vignette
                    if not record then
                        return
                    end
                    native.Vignette = nil
                    debug.setconstant(record.method, record.index, record.value)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.SetGunTracersHidden(hidden)
                local native = RivalsRuntimeBridge.NativeRemovals
                if hidden then
                    if native.Tracers then
                        return
                    end
                    local gun = native.RequireModule('Gun')
                    local localTracers = gun and rawget(gun, '_LocalTracers') or nil
                    if type(localTracers) ~= 'function' then
                        return
                    end
                    for index, value in debug.getconstants(localTracers) do
                        if value == '_Tracers' then
                            rawset(gun, native.TracerSentinel, function() end)
                            debug.setconstant(localTracers, index, native.TracerSentinel)
                            native.Tracers = { class = gun, method = localTracers, index = index, value = value }
                            return
                        end
                    end
                else
                    local record = native.Tracers
                    if not record then
                        return
                    end
                    native.Tracers = nil
                    debug.setconstant(record.method, record.index, record.value)
                    rawset(record.class, native.TracerSentinel, nil)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.SetMuzzleFlashHidden(hidden)
                local native = RivalsRuntimeBridge.NativeRemovals
                if hidden then
                    if native.Muzzle then
                        return
                    end
                    local viewModel = native.RequireModule('ClientViewModel')
                    local muzzleFlash = viewModel and rawget(viewModel, 'MuzzleFlash') or nil
                    if type(muzzleFlash) ~= 'function' then
                        return
                    end
                    local original = debug.getupvalue(muzzleFlash, 2)
                    if type(original) ~= 'table' then
                        return
                    end
                    debug.setupvalue(muzzleFlash, 2, native.MuzzleStub)
                    native.Muzzle = { method = muzzleFlash, value = original }
                else
                    local record = native.Muzzle
                    if not record then
                        return
                    end
                    native.Muzzle = nil
                    debug.setupvalue(record.method, 2, record.value)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.SetGameHitsoundDisabled(disabled)
                local native = RivalsRuntimeBridge.NativeRemovals
                if disabled then
                    if native.Hitsound then
                        return
                    end
                    local viewModel = native.RequireModule('ClientViewModel')
                    local method = viewModel and rawget(viewModel, 'PlayHitmarkerSound') or nil
                    if type(method) ~= 'function' then
                        return
                    end
                    rawset(viewModel, 'PlayHitmarkerSound', function() end)
                    native.Hitsound = { class = viewModel, method = method }
                else
                    local record = native.Hitsound
                    if not record then
                        return
                    end
                    native.Hitsound = nil
                    rawset(record.class, 'PlayHitmarkerSound', record.method)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.EnsureScopeHook()
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                if scope.Restore ~= nil or not (scope.OverlayHidden or scope.ReticleHidden) then
                    return
                end
                local scopeClass = RivalsRuntimeBridge.NativeRemovals.RequireModule('Scope')
                local setActive = scopeClass and rawget(scopeClass, 'SetActive') or nil
                if type(setActive) ~= 'function' then
                    return
                end
                local wrapped = function(scopeObject, active)
                    setActive(scopeObject, active)
                    if not rawget(scopeObject, '_is_scope_active') then
                        return
                    end
                    if scope.OverlayDirty then
                        local visible = not scope.OverlayHidden
                        local circleFrame = rawget(scopeObject, 'CircleFrame')
                        local blurFrame = rawget(scopeObject, 'BlurFrame')
                        if circleFrame then
                            circleFrame.Visible = visible
                        end
                        if blurFrame then
                            blurFrame.Visible = visible
                        end
                    end
                    if scope.ReticleDirty then
                        local reticleContainer = rawget(scopeObject, 'ReticleContainer')
                        if reticleContainer then
                            reticleContainer.Visible = not scope.ReticleHidden
                        end
                    end
                end
                rawset(scopeClass, 'SetActive', wrapped)
                scope.Restore = { class = scopeClass, original = setActive }
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertScopeHook()
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                local restore = scope.Restore
                if not restore then
                    return
                end
                scope.Restore = nil
                rawset(restore.class, 'SetActive', restore.original)
            end

            function RivalsRuntimeBridge.NativeRemovals.SetScopeOverlayHidden(hidden)
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                scope.OverlayHidden = hidden
                scope.OverlayDirty = true
                RivalsRuntimeBridge.NativeRemovals.EnsureScopeHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.SetScopeReticleHidden(hidden)
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                scope.ReticleHidden = hidden
                scope.ReticleDirty = true
                RivalsRuntimeBridge.NativeRemovals.EnsureScopeHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.EnsureCrosshairHook()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                if crosshair.Restore ~= nil then
                    return
                end
                if crosshair.CrosshairVisible == nil and crosshair.HitmarkerVisible == nil then
                    return
                end
                local class = RivalsRuntimeBridge.NativeRemovals.RequireModule('Crosshair')
                local update = class and rawget(class, '_Update') or nil
                if type(update) ~= 'function' then
                    return
                end
                local wrapped = function(instance, ...)
                    update(instance, ...)
                    if rawget(instance, '_destroyed') then
                        return
                    end
                    local frame = rawget(instance, 'Frame')
                    if typeof(frame) ~= 'Instance' then
                        return
                    end
                    local visible = crosshair.CrosshairVisible
                    if visible ~= nil then
                        local foreground = frame:FindFirstChild('Foreground')
                        local background = frame:FindFirstChild('Background')
                        if foreground then
                            foreground.Visible = visible
                        end
                        if background then
                            background.Visible = visible
                        end
                    end
                    local hitmarker = crosshair.HitmarkerVisible
                    if hitmarker ~= nil then
                        local marker = frame:FindFirstChild('Hitmarker')
                        if marker then
                            marker.Visible = hitmarker
                        end
                    end
                end
                rawset(class, '_Update', wrapped)
                crosshair.Restore = { class = class, original = update }
            end

            function RivalsRuntimeBridge.NativeRemovals.EachItemCrosshair(callback)
                local fighter = ResolveLocalFighter()
                for _, item in pairs(type(fighter) == 'table' and rawget(fighter, 'Items') or {}) do
                    local interface = type(item) == 'table' and rawget(item, 'ItemInterface') or nil
                    local mouse = type(interface) == 'table' and rawget(interface, 'Mouse') or nil
                    local mouseCrosshair = type(mouse) == 'table' and rawget(mouse, 'MouseCrosshair') or nil
                    local object = type(mouseCrosshair) == 'table' and rawget(mouseCrosshair, 'Crosshair') or nil
                    if type(object) == 'table' and not rawget(object, '_destroyed') then
                        callback(object)
                    end
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.IsNativeCrosshairActive()
                local fighter = ResolveLocalFighter()
                if type(fighter) ~= 'table' then
                    return false
                end
                local equipped = rawget(fighter, 'EquippedItem')
                if type(equipped) ~= 'table' then
                    return false
                end
                local interface = rawget(equipped, 'ItemInterface')
                local mouse = type(interface) == 'table' and rawget(interface, 'Mouse') or nil
                local mouseCrosshair = type(mouse) == 'table' and rawget(mouse, 'MouseCrosshair') or nil
                local object = type(mouseCrosshair) == 'table' and rawget(mouseCrosshair, 'Crosshair') or nil
                return type(object) == 'table' and rawget(object, '_destroyed') ~= true
            end

            function RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                RivalsRuntimeBridge.NativeRemovals.EachItemCrosshair(function(object)
                    local frame = rawget(object, 'Frame')
                    if typeof(frame) ~= 'Instance' then
                        return
                    end
                    if crosshair.CrosshairVisible ~= nil then
                        local foreground = frame:FindFirstChild('Foreground')
                        local background = frame:FindFirstChild('Background')
                        if foreground then
                            foreground.Visible = crosshair.CrosshairVisible
                        end
                        if background then
                            background.Visible = crosshair.CrosshairVisible
                        end
                    end
                    if crosshair.HitmarkerVisible ~= nil then
                        local marker = frame:FindFirstChild('Hitmarker')
                        if marker then
                            marker.Visible = crosshair.HitmarkerVisible
                        end
                    end
                end)
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertCrosshairFrames()
                local restore = RivalsRuntimeBridge.NativeRemovals.Crosshair.Restore
                local original = restore and restore.original or nil
                if type(original) ~= 'function' then
                    return
                end
                RivalsRuntimeBridge.NativeRemovals.EachItemCrosshair(function(object)
                    task.spawn(function()
                        local previousIdentity = type(getthreadidentity) == 'function' and getthreadidentity() or nil
                        original(object)
                    end)
                end)
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertCrosshairHook()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                local restore = crosshair.Restore
                if not restore then
                    return
                end
                crosshair.Restore = nil
                rawset(restore.class, '_Update', restore.original)
            end

            function RivalsRuntimeBridge.NativeRemovals.SyncCrosshairHook()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                if crosshair.CrosshairVisible == nil and crosshair.HitmarkerVisible == nil then
                    RivalsRuntimeBridge.NativeRemovals.RevertCrosshairHook()
                    return
                end
                RivalsRuntimeBridge.NativeRemovals.EnsureCrosshairHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.SetNativeCrosshairHidden(hidden)
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                local target = nil
                if hidden then
                    target = false
                end
                if crosshair.CrosshairVisible == target then
                    return
                end
                crosshair.CrosshairVisible = target
                if target == nil then
                    RivalsRuntimeBridge.NativeRemovals.RevertCrosshairFrames()
                    if crosshair.HitmarkerVisible ~= nil then
                        RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                    end
                else
                    RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                end
                RivalsRuntimeBridge.NativeRemovals.SyncCrosshairHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.SetHitmarkerHidden(hidden)
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                local target = nil
                if hidden then
                    target = false
                end
                if crosshair.HitmarkerVisible == target then
                    return
                end
                crosshair.HitmarkerVisible = target
                if target == nil then
                    RivalsRuntimeBridge.NativeRemovals.RevertCrosshairFrames()
                    if crosshair.CrosshairVisible ~= nil then
                        RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                    end
                else
                    RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                end
                RivalsRuntimeBridge.NativeRemovals.SyncCrosshairHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.IsLocalAnimator(animator)
                local viewModel = type(animator) == 'table' and rawget(animator, 'ClientViewModel') or nil
                local item = type(viewModel) == 'table' and rawget(viewModel, 'ClientItem') or nil
                local fighter = type(item) == 'table' and rawget(item, 'ClientFighter') or nil
                return type(fighter) == 'table' and rawget(fighter, 'IsLocalPlayer') == true
            end

            function RivalsRuntimeBridge.NativeRemovals.EnsureAnimationHook()
                local native = RivalsRuntimeBridge.NativeRemovals
                local animation = native.Animation
                if animation.Restore ~= nil then
                    return
                end
                local class = native.RequireModule('ViewModelAnimator')
                if type(class) ~= 'table' then
                    return
                end
                local originalPlay = rawget(class, 'PlayAnimation')
                local originalSprint = rawget(class, 'PlaySprintAnimation')
                if type(originalPlay) == 'function' then
                    rawset(class, 'PlayAnimation', function(animator, animationKey, ...)
                        if native.IsLocalAnimator(animator)
                            and RivalsModsState.ShouldSuppressViewmodelAnimation(animator, animationKey) then
                            if RivalsModsState.IsSprintAnimationKey(animator, animationKey) then
                                RivalsModsState.StopSprintOnAnimator(animator)
                            elseif type(animator.StopAnimation) == 'function' then
                                pcall(animator.StopAnimation, animator, animationKey, 0)
                            end
                            return
                        end
                        return originalPlay(animator, animationKey, ...)
                    end)
                end
                if type(originalSprint) == 'function' then
                    rawset(class, 'PlaySprintAnimation', function(animator, ...)
                        if native.IsLocalAnimator(animator)
                            and not IsRivalsModToggleEnabled('P4S2T8')
                            and (IsRivalsModToggleEnabled('P1S31T3') or IsRivalsModToggleEnabled('P1S31T1')) then
                            RivalsModsState.StopSprintOnAnimator(animator)
                            return
                        end
                        return originalSprint(animator, ...)
                    end)
                end
                animation.Restore = {
                    class = class,
                    original = originalPlay,
                    originalSprint = originalSprint,
                }
                local viewModelClass = native.RequireModule('ClientViewModel')
                if type(viewModelClass) == 'table' then
                    local originalCvmPlay = rawget(viewModelClass, 'PlayAnimation')
                    local originalCvmSprint = rawget(viewModelClass, 'ChangeSprintAnimation')
                    if type(originalCvmPlay) == 'function' then
                        rawset(viewModelClass, 'PlayAnimation', function(viewModel, animationKey, ...)
                            local animator = RivalsModsState.ResolveViewModelAnimator(viewModel)
                            if animator and RivalsModsState.ShouldSuppressViewmodelAnimation(animator, animationKey) then
                                if RivalsModsState.IsSprintAnimationKey(animator, animationKey) then
                                    RivalsModsState.StopSprintOnAnimator(animator)
                                end
                                return
                            end
                            return originalCvmPlay(viewModel, animationKey, ...)
                        end)
                    end
                    animation.Restore.viewModelClass = viewModelClass
                    animation.Restore.originalCvmPlay = originalCvmPlay
                    animation.Restore.originalCvmSprint = originalCvmSprint
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertAnimationHook()
                local animation = RivalsRuntimeBridge.NativeRemovals.Animation
                local restore = animation.Restore
                if not restore then
                    return
                end
                animation.Restore = nil
                if restore.class then
                    if type(restore.original) == 'function' then
                        rawset(restore.class, 'PlayAnimation', restore.original)
                    end
                    if type(restore.originalSprint) == 'function' then
                        rawset(restore.class, 'PlaySprintAnimation', restore.originalSprint)
                    end
                end
                if restore.viewModelClass and type(restore.originalCvmPlay) == 'function' then
                    rawset(restore.viewModelClass, 'PlayAnimation', restore.originalCvmPlay)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.SyncAnimationHook()
                local native = RivalsRuntimeBridge.NativeRemovals
                if IsRivalsModToggleEnabled('P1S31T1') or IsRivalsModToggleEnabled('P1S31T2')
                    or IsRivalsModToggleEnabled('P1S31T3') or IsRivalsModToggleEnabled('P1S31T4')
                    or IsRivalsModToggleEnabled('P1S31T5') then
                    native.EnsureAnimationHook()
                else
                    native.RevertAnimationHook()
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.NativeRemovals.RefreshAll()
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local native = RivalsRuntimeBridge.NativeRemovals
                local caps = __akira_genv.AkiraCaps
                native.SetVignetteHidden(native.ReadToggle('P1S27T3')
                    and caps.gate('No ADS Vignette', 'debug.getconstants', 'debug.setconstant'))
                native.SetScopeOverlayHidden(native.ReadToggle('P1S27T4'))
                native.SetScopeReticleHidden(native.ReadToggle('P1S27T5'))
                native.SetGunTracersHidden(native.ReadToggle('P1S27T6')
                    and caps.gate('No Gun Tracers', 'debug.getconstants', 'debug.setconstant'))
                native.SetMuzzleFlashHidden(native.ReadToggle('P1S27T7')
                    and caps.gate('No Muzzle Flash', 'debug.getupvalue', 'debug.setupvalue'))
                native.SetHitmarkerHidden(native.ReadToggle('P1S27T8'))
                native.SetGameHitsoundDisabled(native.ReadToggle('P1S15T3'))
                RivalsRuntimeBridge.ReplicationRemovals.RefreshAll()
            end

            function RivalsRuntimeBridge.NativeRemovals.Destroy()
                local native = RivalsRuntimeBridge.NativeRemovals
                native.SetVignetteHidden(false)
                native.SetGunTracersHidden(false)
                native.SetMuzzleFlashHidden(false)
                native.SetGameHitsoundDisabled(false)
                native.RevertScopeHook()
                native.RevertCrosshairFrames()
                native.RevertCrosshairHook()
                native.RevertAnimationHook()
                RivalsRuntimeBridge.ReplicationRemovals.Destroy()
                RivalsRuntimeBridge.ReplicateHook.Destroy()
                local scope = native.Scope
                scope.OverlayHidden = false
                scope.ReticleHidden = false
                scope.OverlayDirty = false
                scope.ReticleDirty = false
                local crosshair = native.Crosshair
                crosshair.CrosshairVisible = nil
                crosshair.HitmarkerVisible = nil
                native.Modules = {}
            end

            RivalsRuntimeBridge.ReplicateHook = {
                BindingsByEnum = {},
                Restore = nil,
            }

            function RivalsRuntimeBridge.ReplicateHook.ResolveController()
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local module = modules and modules:FindFirstChild('ReplicatedController')
                if not module then
                    return nil
                end
                local ok, controller = pcall(require, module)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                return controller
            end

            function RivalsRuntimeBridge.ReplicateHook.Reserve(enumNames)
                local hook = RivalsRuntimeBridge.ReplicateHook
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.ToEnum) ~= 'function' then
                    return nil
                end
                local tokens = {}
                for _, enumName in ipairs(enumNames) do
                    local ok, token = pcall(enumLibrary.ToEnum, enumLibrary, enumName)
                    if not ok or type(token) ~= 'string' then
                        return nil
                    end
                    tokens[#tokens + 1] = token
                end

                local binding = { enabled = false, handler = nil, tokens = tokens }

                function binding:SetHandler(handler)
                    self.handler = handler
                end

                function binding:SetEnabled(enabled)
                    self.enabled = enabled and true or false
                    if self.enabled then
                        RivalsRuntimeBridge.ReplicateHook.Load()
                    end
                end

                function binding:Destroy()
                    self.handler = nil
                    self.enabled = false
                    for _, token in ipairs(self.tokens) do
                        local list = hook.BindingsByEnum[token]
                        if list then
                            for index = #list, 1, -1 do
                                if list[index] == self then
                                    table.remove(list, index)
                                end
                            end
                            if #list == 0 then
                                hook.BindingsByEnum[token] = nil
                            end
                        end
                    end
                end

                for _, token in ipairs(tokens) do
                    local list = hook.BindingsByEnum[token]
                    if not list then
                        list = {}
                        hook.BindingsByEnum[token] = list
                    end
                    table.insert(list, binding)
                end
                return binding
            end

            function RivalsRuntimeBridge.ReplicateHook.Load()
                local hook = RivalsRuntimeBridge.ReplicateHook
                if hook.Restore ~= nil then
                    return true
                end
                local controller = hook.ResolveController()
                local original = controller and rawget(controller, '_ObjectChanged') or nil
                if type(original) ~= 'function' then
                    return false
                end
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.FromEnum) ~= 'function' then
                    return false
                end
                local bindingsByEnum = hook.BindingsByEnum

                local wrapped = function(...)
                    local packed = table.pack(...)
                    local offset = (type(packed[1]) == 'table') and 1 or 0
                    local objectId = packed[offset + 1]
                    local token = packed[offset + 2]
                    local bindings = type(token) == 'string' and bindingsByEnum[token] or nil
                    if bindings == nil or type(objectId) ~= 'string' then
                        return original(...)
                    end

                    local args = { n = math.max(packed.n - offset - 2, 0) }
                    for index = 1, args.n do
                        args[index] = packed[offset + 2 + index]
                    end
                    local decoded
                    local decodeOk, decodeValue = pcall(enumLibrary.FromEnum, enumLibrary, token)
                    if decodeOk then
                        decoded = decodeValue
                    end
                    local packet = {
                        block = false,
                        objectId = objectId,
                        enumName = decoded,
                        args = args,
                    }

                    local identity
                    if type(getthreadidentity) == 'function' then
                        identity = getthreadidentity()
                    end
                    if type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, 8)
                    end
                    for _, binding in ipairs(bindings) do
                        if binding.enabled and binding.handler then
                            pcall(binding.handler, packet)
                            if packet.block then
                                break
                            end
                        end
                    end
                    if identity ~= nil and type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, identity)
                    end

                    if packet.block then
                        return
                    end
                    return original(...)
                end

                rawset(controller, '_ObjectChanged', wrapped)
                hook.Restore = { controller = controller, original = original }
                return true
            end

            function RivalsRuntimeBridge.ReplicateHook.Revert()
                local hook = RivalsRuntimeBridge.ReplicateHook
                local restore = hook.Restore
                if not restore then
                    return
                end
                hook.Restore = nil
                rawset(restore.controller, '_ObjectChanged', restore.original)
            end

            function RivalsRuntimeBridge.ReplicateHook.RevertIfIdle()
                local hook = RivalsRuntimeBridge.ReplicateHook
                if hook.Restore == nil then
                    return
                end
                for _, list in pairs(hook.BindingsByEnum) do
                    for _, binding in ipairs(list) do
                        if binding.enabled then
                            return
                        end
                    end
                end
                hook.Revert()
            end

            function RivalsRuntimeBridge.ReplicateHook.Destroy()
                local hook = RivalsRuntimeBridge.ReplicateHook
                hook.Revert()
                hook.BindingsByEnum = {}
            end

            function RivalsRuntimeBridge.ReplicateHook.DecodeArg(value)
                if type(value) ~= 'string' then
                    return nil
                end
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.FromEnum) ~= 'function' then
                    return nil
                end
                local ok, name = pcall(enumLibrary.FromEnum, enumLibrary, value)
                if not ok or type(name) ~= 'string' then
                    return nil
                end
                return name
            end

            RivalsRuntimeBridge.ReplicationRemovals = {
                Flashbang = nil,
                Burn = nil,
            }

            function RivalsRuntimeBridge.ReplicationRemovals.EnsureBindings()
                local removals = RivalsRuntimeBridge.ReplicationRemovals
                local hook = RivalsRuntimeBridge.ReplicateHook
                if not removals.Flashbang then
                    local binding = hook.Reserve({ 'ItemChanged' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if hook.DecodeArg(packet.args[2]) == 'BlindEffect' then
                                packet.block = true
                            end
                        end)
                        removals.Flashbang = binding
                    end
                end
                if not removals.Burn then
                    local binding = hook.Reserve({ 'EntityChanged' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if hook.DecodeArg(packet.args[1]) ~= 'BurnEffect' then
                                return
                            end
                            local fighter = ResolveLocalFighter()
                            if not fighter then
                                return
                            end
                            local entity = rawget(fighter, 'Entity')
                            local objectId = type(entity) == 'table' and rawget(entity, 'ObjectID') or nil
                            objectId = objectId
                                or RivalsRuntimeBridge.CombatFeedback.ResolveFighterObjectId(fighter)
                            if objectId == nil or objectId ~= packet.objectId then
                                return
                            end
                            packet.block = true
                        end)
                        removals.Burn = binding
                    end
                end
            end

            function RivalsRuntimeBridge.ReplicationRemovals.RefreshAll()
                local removals = RivalsRuntimeBridge.ReplicationRemovals
                local native = RivalsRuntimeBridge.NativeRemovals
                local wantFlash = native.ReadToggle('P1S27T1')
                local wantBurn = native.ReadToggle('P1S27T2')
                if wantFlash or wantBurn then
                    removals.EnsureBindings()
                end
                if removals.Flashbang then
                    removals.Flashbang:SetEnabled(wantFlash)
                end
                if removals.Burn then
                    removals.Burn:SetEnabled(wantBurn)
                end
                RivalsRuntimeBridge.ReplicateHook.RevertIfIdle()
            end

            function RivalsRuntimeBridge.ReplicationRemovals.Destroy()
                local removals = RivalsRuntimeBridge.ReplicationRemovals
                if removals.Flashbang then
                    removals.Flashbang:Destroy()
                    removals.Flashbang = nil
                end
                if removals.Burn then
                    removals.Burn:Destroy()
                    removals.Burn = nil
                end
            end

            RivalsRuntimeBridge.Movement = {
                Character = nil,
                Humanoid = nil,
                RootPart = nil,
                CollidableParts = {},
                NoclipCharacter = nil,
                NoclipConnections = nil,
                NoclipEnabled = false,
                Flight = nil,
                MechanicsController = nil,
                PlayerModule = nil,
                Controls = nil,
                WalkSpeedHookLoaded = false,
                WalkSpeedHookGetter = nil,
                WalkSpeedHookUpvalueIndex = nil,
                WalkSpeedHookOldUpvalue = nil,
                WalkMultiplierEnabled = false,
                WalkMultiplier = 1,
                SlidingMultiplierEnabled = false,
                SlidingMultiplier = 1,
                JumpPowerHookLoaded = false,
                JumpPowerHookDestroyed = false,
                JumpPowerEnabled = false,
                JumpPowerMultiplier = 1,
                LongJumpPressed = false,
            }

            function RivalsRuntimeBridge.Movement.ReadToggle(optionId)
                LPH_ATTRIBUTES(VM(NONE))
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.Movement.ReadNumber(optionId, fallback)
                LPH_ATTRIBUTES(VM(NONE))
                local option = Options and Options[optionId]
                return option and type(option.Value) == 'number' and option.Value or fallback
            end

            function RivalsRuntimeBridge.Movement.IsKeyActive(optionId)
                LPH_ATTRIBUTES(VM(NONE))
                local option = Options and Options[optionId]
                if option and type(option.GetState) == 'function' then
                    return option:GetState()
                end
                return true
            end

            function RivalsRuntimeBridge.Movement.ReplaceJumpPowerConstants(target)
                local movement = RivalsRuntimeBridge.Movement
                for index, value in pairs(debug.getupvalues(target)) do
                    if type(value) == 'table' then
                        local metatable = getmetatable(value)
                        local metaIndex = type(metatable) == 'table'
                            and rawget(metatable, '__index') or nil
                        local original = nil
                        if type(metaIndex) == 'function' then
                            local ok, wrapped = pcall(function()
                                return value['meow\0d67']
                            end)
                            original = ok and wrapped or nil
                        elseif rawget(value, 'BASE_JUMPPOWER') ~= nil then
                            original = value
                        end
                        if original ~= nil then
                            local upvalueIndex = index
                            debug.setupvalue(target, upvalueIndex, setmetatable({}, {
                                __index = function(_, key)
                                    LPH_ATTRIBUTES(VM(NONE))
                                    if key == 'meow\0d67' then
                                        return original
                                    end
                                    if movement.JumpPowerHookDestroyed then
                                        debug.setupvalue(target, upvalueIndex, original)
                                        return rawget(original, key)
                                    end
                                    if key ~= 'BASE_JUMPPOWER' then
                                        return rawget(original, key)
                                    end
                                    return rawget(original, 'BASE_JUMPPOWER')
                                        * (movement.JumpPowerEnabled and movement.JumpPowerMultiplier or 1)
                                end,
                            }))
                            break
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.Movement.AttemptLoadJumpPowerHook()
                local movement = RivalsRuntimeBridge.Movement
                if movement.JumpPowerHookLoaded then
                    return true
                end
                -- Backoff: probing debug.getupvalues/controllers is expensive; do not
                -- retry every physics frame while the hook target is unavailable.
                local now = os.clock()
                if (movement._JumpPowerHookNextTry or 0) > now then
                    return false
                end
                movement._JumpPowerHookNextTry = now + 1
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function'
                    or type(debug.getconstants) ~= 'function' or type(debug.getprotos) ~= 'function'
                    or type(debug.getproto) ~= 'function' then
                    return false
                end
                local mechanics = movement.ResolveMechanicsController()
                if type(mechanics) ~= 'table' then
                    return false
                end
                local metatable = getmetatable(mechanics)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local hookFighter = type(classIndex) == 'table' and rawget(classIndex, '_HookFighter') or nil
                if type(hookFighter) ~= 'function' then
                    return false
                end
                local localFighter = rawget(mechanics, 'LocalFighter')
                if localFighter == nil then
                    return false
                end
                movement.ReplaceJumpPowerConstants(hookFighter)
                local entityAdded = rawget(localFighter, 'EntityAdded')
                local handler = type(entityAdded) == 'table' and rawget(entityAdded, '_handlerListHead') or nil
                local entityCallback = nil
                while type(handler) == 'table' and entityCallback == nil do
                    local fn = rawget(handler, '_fn')
                    if type(fn) == 'function' then
                        for _, constant in pairs(debug.getconstants(fn)) do
                            if constant == 'CustomGravity' then
                                entityCallback = fn
                                break
                            end
                        end
                    end
                    handler = rawget(handler, '_next')
                end
                if entityCallback == nil then
                    -- Never kick the player for our own hook failure; just skip.
                    ReportRivalsRuntimeIssue('jump_power_hook', 'entity callback not found')
                    return false
                end
                movement.ReplaceJumpPowerConstants(entityCallback)
                for protoIndex in pairs(debug.getprotos(entityCallback)) do
                    local activated = debug.getproto(entityCallback, protoIndex, true)
                    local instance = type(activated) == 'table' and activated[1] or nil
                    if instance ~= nil then
                        movement.ReplaceJumpPowerConstants(instance)
                    end
                end
                movement.JumpPowerHookDestroyed = false
                movement.JumpPowerHookLoaded = true
                return true
            end

            function RivalsRuntimeBridge.Movement.ClearNoclipCharacter()
                local movement = RivalsRuntimeBridge.Movement
                if movement.NoclipConnections then
                    for _, connection in ipairs(movement.NoclipConnections) do
                        connection:Disconnect()
                    end
                end
                movement.NoclipConnections = nil
                movement.NoclipCharacter = nil
                table.clear(movement.CollidableParts)
            end

            function RivalsRuntimeBridge.Movement.BindNoclipCharacter(character)
                local movement = RivalsRuntimeBridge.Movement
                movement.ClearNoclipCharacter()
                movement.NoclipCharacter = character
                for _, descendant in ipairs(character:GetDescendants()) do
                    if descendant:IsA('BasePart') and descendant.CanCollide then
                        movement.CollidableParts[descendant] = true
                    end
                end
                movement.NoclipConnections = {
                    character.DescendantAdded:Connect(function(descendant)
                        if descendant:IsA('BasePart') and descendant.CanCollide then
                            movement.CollidableParts[descendant] = true
                        end
                    end),
                    character.DescendantRemoving:Connect(function(descendant)
                        if descendant:IsA('BasePart') then
                            movement.CollidableParts[descendant] = nil
                        end
                    end),
                }
            end

            function RivalsRuntimeBridge.Movement.SetNoclipEnabled(enabled)
                local movement = RivalsRuntimeBridge.Movement
                if movement.NoclipEnabled and not enabled then
                    for part in pairs(movement.CollidableParts) do
                        part.CanCollide = true
                    end
                end
                movement.NoclipEnabled = enabled == true
            end

            function RivalsRuntimeBridge.Movement.DestroyFlight()
                local movement = RivalsRuntimeBridge.Movement
                local flight = movement.Flight
                movement.Flight = nil
                if flight then
                    pcall(function() flight.Velocity:Destroy() end)
                    pcall(function() flight.Attachment:Destroy() end)
                end
            end

            function RivalsRuntimeBridge.Movement.ResolveCharacter()
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                local rootPart = character and character:FindFirstChild('HumanoidRootPart') or nil
                if character ~= movement.Character or humanoid ~= movement.Humanoid or rootPart ~= movement.RootPart then
                    movement.ClearNoclipCharacter()
                    movement.DestroyFlight()
                    movement.Character = character
                    movement.Humanoid = humanoid
                    movement.RootPart = rootPart
                    movement.LongJumpPressed = false
                end
                return character, humanoid, rootPart
            end

            function RivalsRuntimeBridge.Movement.ResolveControlsMoveVector()
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                if movement.PlayerModule == nil then
                    local playerScripts = LP:FindFirstChild('PlayerScripts')
                    local moduleScript = playerScripts and playerScripts:FindFirstChild('PlayerModule')
                    if moduleScript then
                        local ok, playerModule = pcall(require, moduleScript)
                        if ok and type(playerModule) == 'table'
                            and type(playerModule.GetControls) == 'function' then
                            movement.PlayerModule = playerModule
                        end
                    end
                end
                local playerModule = movement.PlayerModule
                if playerModule then
                    local controls = movement.Controls
                    if type(controls) ~= 'table' or type(controls.GetMoveVector) ~= 'function' then
                        local ok, resolved = pcall(playerModule.GetControls, playerModule)
                        if ok and type(resolved) == 'table' and type(resolved.GetMoveVector) == 'function' then
                            controls = resolved
                            movement.Controls = resolved
                        else
                            controls = nil
                        end
                    end
                    if controls then
                        local ok, moveVector = pcall(controls.GetMoveVector, controls)
                        if ok and typeof(moveVector) == 'Vector3' then
                            return moveVector
                        end
                        movement.Controls = nil
                    end
                end
                return Vector3.zero
            end

            function RivalsRuntimeBridge.Movement.FlightMoveDirection()
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                if UserInputService:GetFocusedTextBox() then
                    return Vector3.zero
                end
                local direction = Vector3.zero
                local cframe = Workspace.CurrentCamera.CFrame
                if UserInputService.KeyboardEnabled then
                    local look = cframe.LookVector
                    local flatLook = Vector3.new(look.X, 0, look.Z)
                    if flatLook.Magnitude > 0 then
                        flatLook = flatLook.Unit
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        direction = direction + flatLook
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        direction = direction - cframe.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        direction = direction - flatLook
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        direction = direction + cframe.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                        direction = direction + Vector3.new(0, 1, 0)
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
                        or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                        direction = direction - Vector3.new(0, 1, 0)
                    end
                else
                    local moveVector = movement.ResolveControlsMoveVector()
                    if moveVector.Magnitude > 0 then
                        direction = direction + cframe.LookVector * -moveVector.Z
                        direction = direction + cframe.RightVector * moveVector.X
                    end
                end
                return direction
            end

            function RivalsRuntimeBridge.Movement.FlattenDirection(vector)
                LPH_ATTRIBUTES(VM(NONE))
                local flat = Vector3.new(vector.X, 0, vector.Z)
                return flat.Magnitude > 0 and flat.Unit or Vector3.zero
            end

            function RivalsRuntimeBridge.Movement.StrafeMoveDirection()
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                if UserInputService:GetFocusedTextBox() then
                    return Vector3.zero
                end
                local direction = Vector3.zero
                local cframe = Workspace.CurrentCamera.CFrame
                local look = movement.FlattenDirection(cframe.LookVector)
                local right = movement.FlattenDirection(cframe.RightVector)
                if UserInputService.KeyboardEnabled then
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        direction = direction + look
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        direction = direction - look
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        direction = direction + right
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        direction = direction - right
                    end
                else
                    local moveVector = movement.ResolveControlsMoveVector()
                    if moveVector.Magnitude > 0 then
                        direction = direction + look * -moveVector.Z
                        direction = direction + right * moveVector.X
                    end
                end
                if direction.Magnitude > 0 then
                    direction = direction.Unit
                end
                return direction
            end

            function RivalsRuntimeBridge.Movement.UpdateFlight(active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                local rootPart = movement.RootPart
                if not active or not rootPart or rootPart.Parent == nil
                    or not movement.Humanoid or movement.Humanoid.Health <= 0 then
                    movement.DestroyFlight()
                    return
                end
                local direction = movement.FlightMoveDirection()
                if direction.Magnitude > 0 then
                    direction = direction.Unit
                end
                local velocityVector = direction * movement.ReadNumber('P10S3S4', 100)
                local flight = movement.Flight
                if flight and flight.RootPart ~= rootPart then
                    movement.DestroyFlight()
                    flight = nil
                end
                if flight then
                    flight.Velocity.VectorVelocity = velocityVector
                    return
                end
                local attachment = Instance.new('Attachment')
                attachment.Parent = rootPart
                local velocity = Instance.new('LinearVelocity')
                velocity.RelativeTo = Enum.ActuatorRelativeTo.World
                velocity.MaxForce = math.huge
                velocity.VectorVelocity = velocityVector
                velocity.Attachment0 = attachment
                velocity.Parent = rootPart
                movement.Flight = { RootPart = rootPart, Attachment = attachment, Velocity = velocity }
            end

            function RivalsRuntimeBridge.Movement.BlankFlightVelocity()
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                if movement.Flight and movement.RootPart and movement.RootPart.Parent then
                    movement.RootPart.AssemblyLinearVelocity = Vector3.zero
                end
            end

            function RivalsRuntimeBridge.Movement.UpdateNoclip(active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                local character = movement.Character
                local alive = character ~= nil and movement.Humanoid ~= nil and movement.Humanoid.Health > 0
                if not alive then
                    movement.ClearNoclipCharacter()
                elseif movement.NoclipCharacter ~= character then
                    movement.BindNoclipCharacter(character)
                end
                movement.SetNoclipEnabled(active == true and alive)
                if not movement.NoclipEnabled then
                    return
                end
                for part in pairs(movement.CollidableParts) do
                    part.CanCollide = false
                end
            end

            function RivalsRuntimeBridge.Movement.UpdateAutoStrafe(deltaTime, active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                local rootPart = movement.RootPart
                if not active or not rootPart or not movement.Humanoid or movement.Humanoid.Health <= 0
                    or not UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                    return
                end
                local speed = movement.ReadNumber('P10S3S5', 50)
                rootPart.CFrame = rootPart.CFrame + movement.StrafeMoveDirection() * (speed / 100) * deltaTime * 60
                rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(0, 1, 0)
            end

            function RivalsRuntimeBridge.Movement.ResolveMechanicsController()
                local movement = RivalsRuntimeBridge.Movement
                if movement.MechanicsController then
                    return movement.MechanicsController
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local mechanicsModule = controllers and controllers:FindFirstChild('MechanicsController')
                if mechanicsModule then
                    local ok, controller = pcall(require, mechanicsModule)
                    movement.MechanicsController = ok and type(controller) == 'table' and controller or nil
                end
                return movement.MechanicsController
            end

            function RivalsRuntimeBridge.Movement.AttemptLoadWalkSpeedHook()
                local movement = RivalsRuntimeBridge.Movement
                if movement.WalkSpeedHookLoaded then
                    return true
                end
                -- Backoff: see AttemptLoadJumpPowerHook.
                local now = os.clock()
                if (movement._WalkSpeedHookNextTry or 0) > now then
                    return false
                end
                movement._WalkSpeedHookNextTry = now + 1
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local mechanics = movement.ResolveMechanicsController()
                if type(mechanics) ~= 'table' then
                    return false
                end
                local metatable = getmetatable(mechanics)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local getWalkSpeed = type(classIndex) == 'table' and rawget(classIndex, '_GetWalkSpeed') or nil
                if type(getWalkSpeed) ~= 'function' then
                    return false
                end
                local upvalueIndex, oldUpvalue
                for index, value in pairs(debug.getupvalues(getWalkSpeed)) do
                    if type(value) == 'table' and rawget(value, 'BASE_WALKSPEED') ~= nil then
                        upvalueIndex = index
                        oldUpvalue = value
                        break
                    end
                end
                if upvalueIndex == nil then
                    return false
                end
                movement.WalkSpeedHookGetter = getWalkSpeed
                movement.WalkSpeedHookUpvalueIndex = upvalueIndex
                movement.WalkSpeedHookOldUpvalue = oldUpvalue
                debug.setupvalue(getWalkSpeed, upvalueIndex, setmetatable({}, {
                    __index = function(_, key)
                        LPH_ATTRIBUTES(VM(NONE))
                        if key ~= 'BASE_WALKSPEED' then
                            -- Game update changed access pattern: pass through to the
                            -- original table instead of kicking the player.
                            local fallback = rawget(oldUpvalue, key)
                            if fallback ~= nil then
                                return fallback
                            end
                            ReportRivalsRuntimeIssue('walkspeed_proxy', 'unexpected key: ' .. tostring(key))
                            return nil
                        end
                        local baseWalkSpeed = rawget(oldUpvalue, 'BASE_WALKSPEED')
                        local isSlide = false
                        pcall(function()
                            isSlide = (debug.info(3, 'n') == 'Slide')
                        end)
                        if movement.SlidingMultiplierEnabled and isSlide then
                            return baseWalkSpeed * movement.SlidingMultiplier
                        end
                        if movement.WalkMultiplierEnabled then
                            return baseWalkSpeed * movement.WalkMultiplier
                        end
                        return baseWalkSpeed
                    end,
                }))
                movement.WalkSpeedHookLoaded = true
                return true
            end

            function RivalsRuntimeBridge.Movement.UpdateWalkSpeed(active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                movement.WalkMultiplier = movement.ReadNumber('P10S3S1', 2)
                movement.WalkMultiplierEnabled = active == true
                movement.AttemptLoadWalkSpeedHook()
            end

            function RivalsRuntimeBridge.Movement.UpdateSliding(active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                movement.SlidingMultiplier = movement.ReadNumber('P10S3S2', 10)
                movement.SlidingMultiplierEnabled = active == true
                movement.AttemptLoadWalkSpeedHook()
            end

            function RivalsRuntimeBridge.Movement.UpdateJumpPower(active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                movement.JumpPowerMultiplier = movement.ReadNumber('P10S3S3', 2)
                movement.JumpPowerEnabled = active == true
                movement.AttemptLoadJumpPowerHook()
            end

            function RivalsRuntimeBridge.Movement.LaunchLongJump()
                local movement = RivalsRuntimeBridge.Movement
                local fighter = ResolveLocalFighter()
                local entity = type(fighter) == 'table' and rawget(fighter, 'Entity') or nil
                if not entity and fighter and type(fighter.GetEntity) == 'function' then
                    local ok, value = pcall(fighter.GetEntity, fighter)
                    entity = ok and value or nil
                end
                local rootPart = movement.RootPart
                local camera = Workspace.CurrentCamera
                if type(entity) ~= 'table' or not rootPart or not camera or not movement.Humanoid
                    or movement.Humanoid.Health <= 0 then
                    return false
                end
                local lookVector = camera.CFrame.LookVector
                local direction = Vector3.new(lookVector.X, 0, lookVector.Z)
                if direction.Magnitude < 0.001 then
                    local rootLook = rootPart.CFrame.LookVector
                    direction = Vector3.new(rootLook.X, 0, rootLook.Z)
                end
                direction = direction.Unit
                if Options.P10S3D1 and Options.P10S3D1.Value == 'Under Feet' then
                    direction = (direction * movement.ReadNumber('P10S3S8', 8) + Vector3.new(0, 4, 0)).Unit
                end
                local velocity = direction * movement.ReadNumber('P10S3S6', 60)
                    + Vector3.new(0, movement.ReadNumber('P10S3S7', 20), 0)
                if type(entity.AirborneCancel) ~= 'function' or type(entity.AirborneTrigger) ~= 'function' then
                    return false
                end
                pcall(entity.AirborneCancel, entity)
                local ok = pcall(entity.AirborneTrigger, entity, velocity, 4)
                return ok
            end

            function RivalsRuntimeBridge.Movement.UpdateLongJump(active)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                if active and not movement.LongJumpPressed then
                    movement.LaunchLongJump()
                end
                movement.LongJumpPressed = active
            end

            __akira_boot_yield()

            function RivalsRuntimeBridge.Movement.Update(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local movement = RivalsRuntimeBridge.Movement
                local wsActive = movement.ReadToggle('P10S3T1') and movement.IsKeyActive('P10S3T1K')
                local slideActive = movement.ReadToggle('P10S3T2') and movement.IsKeyActive('P10S3T2K')
                local jpActive = movement.ReadToggle('P10S3T3')
                local flightActive = movement.ReadToggle('P10S3T4') and movement.IsKeyActive('P10S3T4K')
                local noclipActive = movement.ReadToggle('P10S3T5') and movement.IsKeyActive('P10S3T5K')
                local strafeActive = movement.ReadToggle('P10S3T6') and movement.IsKeyActive('P10S3T6K')
                local ljActive = movement.ReadToggle('P10S3T7') and movement.IsKeyActive('P10S3T7K')
                if not (wsActive or slideActive or jpActive or flightActive or noclipActive or strafeActive or ljActive) then
                    if movement.NoclipEnabled then
                        movement.SetNoclipEnabled(false)
                    end
                    return
                end
                movement.ResolveCharacter()
                movement.UpdateWalkSpeed(wsActive)
                movement.UpdateSliding(slideActive)
                movement.UpdateJumpPower(jpActive)
                movement.UpdateAutoStrafe(deltaTime, strafeActive)
                movement.UpdateFlight(flightActive)
                movement.UpdateNoclip(noclipActive)
                movement.UpdateLongJump(ljActive)
            end

            function RivalsRuntimeBridge.Movement.RefreshAll()
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local movement = RivalsRuntimeBridge.Movement
                local caps = __akira_genv.AkiraCaps
                if movement.ReadToggle('P10S3T1') or movement.ReadToggle('P10S3T2') then
                    caps.gate('WalkSpeed / Sliding Speed', 'debug.getupvalues', 'debug.setupvalue')
                end
                if movement.ReadToggle('P10S3T3') then
                    caps.gate('Jump Power', 'debug.getupvalues', 'debug.setupvalue', 'debug.getconstants', 'debug.getprotos', 'debug.getproto')
                end
                RivalsRuntimeBridge.Movement.Update(0)
            end

            function RivalsRuntimeBridge.Movement.Destroy()
                local movement = RivalsRuntimeBridge.Movement
                movement.SetNoclipEnabled(false)
                movement.ClearNoclipCharacter()
                movement.DestroyFlight()
                if movement.WalkSpeedHookLoaded and movement.WalkSpeedHookGetter
                    and movement.WalkSpeedHookUpvalueIndex ~= nil and movement.WalkSpeedHookOldUpvalue ~= nil then
                    pcall(debug.setupvalue, movement.WalkSpeedHookGetter,
                        movement.WalkSpeedHookUpvalueIndex, movement.WalkSpeedHookOldUpvalue)
                end
                movement.WalkSpeedHookLoaded = false
                movement.WalkSpeedHookGetter = nil
                movement.WalkSpeedHookUpvalueIndex = nil
                movement.WalkSpeedHookOldUpvalue = nil
                movement.WalkMultiplierEnabled = false
                movement.SlidingMultiplierEnabled = false
                movement.JumpPowerHookDestroyed = true
                movement.JumpPowerHookLoaded = false
                movement.JumpPowerEnabled = false
                movement.MechanicsController = nil
                movement.PlayerModule = nil
                movement.Character = nil
                movement.Humanoid = nil
                movement.RootPart = nil
                movement.LongJumpPressed = false
            end

            RivalsRuntimeBridge.DeviceSpoof = {
                Hook = nil,
                Controller = nil,
                SpamToken = 0,
                SpamDevice = nil,
                SpamList = { 'Desktop', 'Mobile', 'Console', 'VR' },
                ControlsMap = {
                    Desktop = 'MouseKeyboard',
                    Mobile = 'Touch',
                    Console = 'Gamepad',
                    VR = 'VR',
                },
            }

            function RivalsRuntimeBridge.DeviceSpoof.ResolveControlsController()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if spoof.Controller then
                    return spoof.Controller
                end
                if not ReplicatedStateReady then
                    BeginReplicatedStateBoot()
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local module = controllers and controllers:FindFirstChild('ControlsController')
                if not module then
                    return nil
                end
                local ok, controller = pcall(require, module)
                if ok and type(controller) == 'table' then
                    spoof.Controller = controller
                end
                return spoof.Controller
            end

            function RivalsRuntimeBridge.DeviceSpoof.ReadEnabled()
                return Toggles and Toggles.P10S7T1 and Toggles.P10S7T1.Value == true
            end

            function RivalsRuntimeBridge.DeviceSpoof.ReadSpamEnabled()
                return Toggles and Toggles.P10S7T2 and Toggles.P10S7T2.Value == true
            end

            function RivalsRuntimeBridge.DeviceSpoof.ReadSpamRate()
                local option = Options and Options.P10S7S1
                local value = option and tonumber(option.Value)
                if value == nil then
                    return 1
                end
                return math.max(0.1, value)
            end

            function RivalsRuntimeBridge.DeviceSpoof.ReadSpoofType()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if type(spoof.SpamDevice) == 'string' then
                    return spoof.SpamDevice
                end
                local option = Options and Options.P10S7D1
                local value = option and option.Value
                return type(value) == 'string' and value or 'VR'
            end

            function RivalsRuntimeBridge.DeviceSpoof.ResolveReplicateControls()
                local fighterController = ResolveFighterController()
                if type(fighterController) ~= 'table' then
                    return nil, nil
                end
                local metatable = getmetatable(fighterController)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local replicateControls = type(classIndex) == 'table'
                    and rawget(classIndex, '_ReplicateControls') or nil
                if type(replicateControls) ~= 'function' then
                    return nil, fighterController
                end
                return replicateControls, fighterController
            end

            function RivalsRuntimeBridge.DeviceSpoof.ForceReplicate()
                local replicateControls, fighterController =
                    RivalsRuntimeBridge.DeviceSpoof.ResolveReplicateControls()
                if replicateControls and fighterController then
                    pcall(replicateControls, fighterController)
                end
            end

            function RivalsRuntimeBridge.DeviceSpoof.AttemptLoadHook()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if spoof.Hook then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local controlsController = spoof.ResolveControlsController()
                if type(controlsController) ~= 'table' then
                    return false
                end
                local replicateControls = spoof.ResolveReplicateControls()
                if type(replicateControls) ~= 'function' then
                    return false
                end
                local upvalueIndex
                for index, value in pairs(debug.getupvalues(replicateControls)) do
                    if value == controlsController then
                        upvalueIndex = index
                        break
                    end
                end
                if upvalueIndex == nil then
                    return false
                end
                local originalValue = debug.getupvalue(replicateControls, upvalueIndex)
                debug.setupvalue(replicateControls, upvalueIndex, setmetatable({}, {
                    __index = function(_, key)
                        LPH_ATTRIBUTES(VM(NONE))
                        if key ~= 'CurrentControls' then
                            -- Pass through to the real controller instead of kicking.
                            local fallback = type(originalValue) == 'table' and rawget(originalValue, key) or nil
                            if fallback ~= nil then
                                return fallback
                            end
                            ReportRivalsRuntimeIssue('device_spoof_proxy', 'unexpected key: ' .. tostring(key))
                            return nil
                        end
                        local value = spoof.ControlsMap[spoof.ReadSpoofType()]
                        if value == nil then
                            ReportRivalsRuntimeIssue('device_spoof_proxy', 'no controls map for spoof type')
                            if type(originalValue) == 'table' then
                                return rawget(originalValue, key)
                            end
                            return nil
                        end
                        return value
                    end,
                }))
                spoof.Hook = {
                    Getter = replicateControls,
                    UpvalueIndex = upvalueIndex,
                    OriginalValue = originalValue,
                }
                return true
            end

            function RivalsRuntimeBridge.DeviceSpoof.AttemptUnloadHook()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                local hook = spoof.Hook
                if not hook then
                    return
                end
                spoof.Hook = nil
                pcall(debug.setupvalue, hook.Getter, hook.UpvalueIndex, hook.OriginalValue)
            end

            function RivalsRuntimeBridge.DeviceSpoof.StopSpam()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                spoof.SpamToken = (spoof.SpamToken or 0) + 1
                spoof.SpamDevice = nil
            end

            function RivalsRuntimeBridge.DeviceSpoof.StartSpam()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                spoof.SpamToken = (spoof.SpamToken or 0) + 1
                local token = spoof.SpamToken
                task.spawn(function()
                    while spoof.SpamToken == token and spoof.ReadSpamEnabled() do
                        spoof.SpamDevice = spoof.SpamList[math.random(1, #spoof.SpamList)]
                        if spoof.AttemptLoadHook() then
                            spoof.ForceReplicate()
                        end
                        task.wait(spoof.ReadSpamRate())
                    end
                end)
            end

            function RivalsRuntimeBridge.DeviceSpoof.RefreshAll()
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                local spamEnabled = spoof.ReadSpamEnabled()
                if spoof.ReadEnabled() or spamEnabled then
                    __akira_genv.AkiraCaps.gate('Device Spoof', 'debug.getupvalues', 'debug.setupvalue')
                    if spoof.AttemptLoadHook() then
                        spoof.ForceReplicate()
                    end
                    if spamEnabled then
                        spoof.StartSpam()
                    else
                        spoof.StopSpam()
                    end
                else
                    spoof.StopSpam()
                    if spoof.Hook then
                        spoof.AttemptUnloadHook()
                        spoof.ForceReplicate()
                    end
                end
            end

            function RivalsRuntimeBridge.DeviceSpoof.Destroy()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                spoof.StopSpam()
                if spoof.Hook then
                    spoof.AttemptUnloadHook()
                    spoof.ForceReplicate()
                end
            end

            RivalsRuntimeBridge.PlayerSpoofer = {
                Binders = setmetatable({}, { __mode = 'k' }),
                OriginalNames = setmetatable({}, { __mode = 'k' }),
                NameSpoofers = setmetatable({}, { __mode = 'k' }),
                NameConnections = setmetatable({}, { __mode = 'k' }),
                RankSpoofers = setmetatable({}, { __mode = 'k' }),
                OriginalRankIcons = setmetatable({}, { __mode = 'k' }),
                PlayerListConnections = {},
                LifecycleConnections = {},
                Started = false,
                Scopes = { 'You', 'Oth' },
                AttributeFields = {
                    { key = 'Name', isName = true, control = 'text',
                        youDefault = 'Akira', othDefault = 'Player' },
                    { key = 'Winstreak', attribute = 'StatisticDuelsWinStreak', control = 'number',
                        youDefault = '999', othDefault = '0' },
                    { key = 'Level', attribute = 'Level', control = 'number',
                        youDefault = '999', othDefault = '0' },
                    { key = 'RankedElo', attribute = 'DisplayELO', control = 'number',
                        youDefault = '3600', othDefault = '0' },
                    { key = 'NametagStatus', attribute = 'PlayerStatus', control = 'text',
                        youDefault = 'Prime', othDefault = 'Prime' },
                    { key = 'Influencer', attribute = 'IsInfluencer', control = 'const', constValue = true },
                    { key = 'RobloxEmployee', attribute = 'IsRobloxEmployee', control = 'const', constValue = true },
                    { key = 'Premium', attribute = 'IsPremium', control = 'const', constValue = true },
                    { key = 'Verified', attribute = 'HasVerifiedBadge', control = 'const', constValue = true },
                    { key = 'NosniyTeam', attribute = 'GroupRank', control = 'const', constValue = 255 },
                },
            }

            function RivalsRuntimeBridge.PlayerSpoofer.ExtractRankAssetId(val)
                if type(val) == 'number' and val > 0 then
                    return 'rbxassetid://' .. tostring(math.floor(val))
                elseif type(val) == 'string' and val ~= '' then
                    local clean = val:match('^%s*(.-)%s*$')
                    if clean and clean:match('^%d+$') then
                        return 'rbxassetid://' .. clean
                    elseif clean and (clean:match('^rbxasset') or clean:match('^http')) then
                        return clean
                    end
                elseif type(val) == 'table' then
                    return RivalsRuntimeBridge.PlayerSpoofer.ExtractRankAssetId(val.Image or val.Texture or val.Icon or val.AssetId or val.Id or val.SmallIcon or val.LargeIcon)
                end
                return nil
            end

            function RivalsRuntimeBridge.PlayerSpoofer.FindRankAssetInGame(targetRankName)
                local lowerRank = tostring(targetRankName or ''):lower()
                if lowerRank == '' or lowerRank == 'unranked' then
                    return nil
                end
                local lp = Players.LocalPlayer
                local pg = lp and lp:FindFirstChild('PlayerGui')
                if pg then
                    for _, d in ipairs(pg:GetDescendants()) do
                        if (d:IsA('ImageLabel') or d:IsA('ImageButton')) and type(d.Image) == 'string' and d.Image ~= '' then
                            local dName = d.Name:lower()
                            local pName = d.Parent and d.Parent.Name:lower() or ''
                            if (dName:find(lowerRank, 1, true) or pName:find(lowerRank, 1, true))
                                and not dName:find('weapon', 1, true) and not dName:find('skin', 1, true) then
                                return d.Image, d.ImageRectOffset, d.ImageRectSize, d.ImageColor3
                            end
                        end
                    end
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local assets = ReplicatedStorage:FindFirstChild('Assets') or (modules and modules:FindFirstChild('Assets'))
                if assets then
                    for _, d in ipairs(assets:GetDescendants()) do
                        if (d:IsA('Decal') or d:IsA('Texture') or d:IsA('ImageLabel')) then
                            local dName = d.Name:lower()
                            if dName:find(lowerRank, 1, true) then
                                local img = (d:IsA('Decal') or d:IsA('Texture')) and d.Texture or d.Image
                                if type(img) == 'string' and img ~= '' then
                                    return img, Vector2.zero, Vector2.zero, Color3.new(1, 1, 1)
                                end
                            end
                        end
                    end
                end
                return nil
            end


            function RivalsRuntimeBridge.PlayerSpoofer.GetOriginal(player)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local orig = spoofer.OriginalNames[player]
                if not orig then
                    orig = {
                        Name = player.Name,
                        DisplayName = player.DisplayName,
                    }
                    spoofer.OriginalNames[player] = orig
                end
                return orig
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ResolveRankData(elo)
                local numElo = tonumber(elo) or 0
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local ExtractRankAssetId = spoofer.ExtractRankAssetId
                local FindRankAssetInGame = spoofer.FindRankAssetInGame
                local rankName = 'Unranked'
                local rankProfile = ResolveEspRankProfile and ResolveEspRankProfile()
                local rankData = nil

                if rankProfile and type(rankProfile.RanksOrder) == 'table' and type(rankProfile.Ranks) == 'table' then
                    local ranksOrder = rankProfile.RanksOrder
                    local ranks = rankProfile.Ranks
                    local rankCount = #ranksOrder
                    for rankIndex, rName in ipairs(ranksOrder) do
                        local rData = ranks[rName]
                        if type(rData) == 'table'
                            and type(rData.RequiredELO) == 'number'
                            and numElo < rData.RequiredELO
                            and rData.RequiredELOLeaderboardRanking == nil then
                            rankName = ranksOrder[math.clamp(rankIndex - 1, 1, rankCount)] or 'Unranked'
                            break
                        end
                    end
                    if rankName == 'Unranked' and numElo > 0 then
                        for rankIndex = rankCount, 1, -1 do
                            local rName = ranksOrder[rankIndex]
                            local rData = ranks[rName]
                            if type(rData) == 'table' and rData.RequiredELOLeaderboardRanking == nil then
                                rankName = rName
                                break
                            end
                        end
                    end
                    rankData = ranks[rankName]
                else
                    if numElo >= 3600 then
                        rankName = 'Nemesis'
                    elseif numElo >= 3000 then
                        rankName = 'Onyx'
                    elseif numElo >= 2400 then
                        rankName = 'Diamond'
                    elseif numElo >= 1800 then
                        rankName = 'Platinum'
                    elseif numElo >= 1200 then
                        rankName = 'Gold'
                    elseif numElo >= 600 then
                        rankName = 'Silver'
                    elseif numElo >= 1 then
                        rankName = 'Bronze'
                    else
                        rankName = 'Unranked'
                    end
                end

                local rankIcon = nil
                local rectOffset = Vector2.zero
                local rectSize = Vector2.zero
                local iconColor = Color3.new(1, 1, 1)

                if type(rankData) == 'table' then
                    rankIcon = ExtractRankAssetId(rankData.Icon)
                        or ExtractRankAssetId(rankData.Image)
                        or ExtractRankAssetId(rankData.Texture)
                        or ExtractRankAssetId(rankData.IconAssetId)
                        or ExtractRankAssetId(rankData.AssetId)
                        or ExtractRankAssetId(rankData.Badge)
                        or ExtractRankAssetId(rankData.BadgeIcon)
                        or ExtractRankAssetId(rankData.RankIcon)
                        or ExtractRankAssetId(rankData.SmallIcon)
                        or ExtractRankAssetId(rankData.LargeIcon)
                        or ExtractRankAssetId(rankData.DisplayIcon)
                    if typeof(rankData.ImageRectOffset) == 'Vector2' then
                        rectOffset = rankData.ImageRectOffset
                    end
                    if typeof(rankData.ImageRectSize) == 'Vector2' then
                        rectSize = rankData.ImageRectSize
                    end
                end

                if not rankIcon and rankProfile then
                    if type(rankProfile.GetRankIcon) == 'function' then
                        local ok, icon = pcall(rankProfile.GetRankIcon, rankProfile, rankName)
                        rankIcon = ok and ExtractRankAssetId(icon) or nil
                    end
                    if not rankIcon and type(rankProfile.RankIcons) == 'table' then
                        rankIcon = ExtractRankAssetId(rankProfile.RankIcons[rankName])
                    end
                    if not rankIcon and type(rankProfile.Icons) == 'table' then
                        rankIcon = ExtractRankAssetId(rankProfile.Icons[rankName])
                    end
                end

                if not rankIcon then
                    local foundImg, foundOffset, foundSize, foundColor = FindRankAssetInGame(rankName)
                    if foundImg then
                        rankIcon = foundImg
                        rectOffset = foundOffset or Vector2.zero
                        rectSize = foundSize or Vector2.zero
                        iconColor = foundColor or Color3.new(1, 1, 1)
                    end
                end

                if not rankIcon then
                    local lower = rankName:lower()
                    if lower == 'nemesis' then
                        rankIcon = 'rbxassetid://18928068710'
                    elseif lower == 'onyx' then
                        rankIcon = 'rbxassetid://18928068800'
                    elseif lower == 'diamond' then
                        rankIcon = 'rbxassetid://18928068900'
                    elseif lower == 'platinum' then
                        rankIcon = 'rbxassetid://18928069000'
                    elseif lower == 'gold' then
                        rankIcon = 'rbxassetid://18928069100'
                    elseif lower == 'silver' then
                        rankIcon = 'rbxassetid://18928069200'
                    elseif lower == 'bronze' then
                        rankIcon = 'rbxassetid://18928069300'
                    end
                end

                return {
                    RankName = rankName,
                    ELO = numElo,
                    Icon = rankIcon,
                    RectOffset = rectOffset,
                    RectSize = rectSize,
                    Color = iconColor,
                }
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ResolvePlayerListRoots()
                local roots = {}
                local seen = {}
                local function addRoot(r)
                    if r and not seen[r] and r:IsA('Instance') then
                        seen[r] = true
                        roots[#roots + 1] = r
                    end
                end

                local lp = Players.LocalPlayer
                local pg = lp and lp:FindFirstChild('PlayerGui')
                if pg then
                    local mainGui = pg:FindFirstChild('MainGui')
                    if mainGui then
                        addRoot(mainGui:FindFirstChild('PlayerList'))
                        addRoot(mainGui:FindFirstChild('Scoreboard'))
                    end
                    addRoot(pg:FindFirstChild('PlayerList'))
                    addRoot(pg:FindFirstChild('Leaderboard'))
                    for _, child in ipairs(pg:GetChildren()) do
                        if child:IsA('ScreenGui') and child ~= mainGui then
                            local nestedPl = child:FindFirstChild('PlayerList', true)
                            if nestedPl then addRoot(nestedPl) end
                        end
                    end
                end
                return roots
            end

            function RivalsRuntimeBridge.PlayerSpoofer.FindPlayerRowContainers(player, playerListRoot)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local orig = spoofer.GetOriginal(player)
                local spoofName = spoofer.NameSpoofers[player]
                local pName = player.Name
                local dName = player.DisplayName

                local targetTexts = {
                    [pName] = true,
                    [dName] = true,
                    [orig.Name] = true,
                    [orig.DisplayName] = true,
                }
                if spoofName and spoofName ~= '' then
                    targetTexts[spoofName] = true
                end

                local rows = {}
                local seen = {}

                for _, desc in ipairs(playerListRoot:GetDescendants()) do
                    if desc:IsA('TextLabel') and targetTexts[desc.Text] then
                        local current = desc
                        local row = desc.Parent
                        while current and current.Parent and current.Parent ~= playerListRoot do
                            local p = current.Parent
                            if p:IsA('ScrollingFrame')
                                or p:FindFirstChildOfClass('UIListLayout')
                                or p:FindFirstChildOfClass('UIGridLayout') then
                                row = current
                                break
                            end
                            current = p
                        end
                        if row and not seen[row] then
                            seen[row] = true
                            rows[#rows + 1] = {
                                Row = row,
                                NameLabel = desc,
                            }
                        end
                    end
                end

                return rows
            end

            function RivalsRuntimeBridge.PlayerSpoofer.UpdateRowVisuals(player, rowInfo)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local orig = spoofer.GetOriginal(player)
                local row = rowInfo.Row
                local nameLabel = rowInfo.NameLabel

                local spoofName = spoofer.NameSpoofers[player]
                if spoofName and spoofName ~= '' then
                    nameLabel.Text = spoofName
                    for _, child in ipairs(nameLabel:GetDescendants()) do
                        if child:IsA('TextLabel') then
                            child.Text = spoofName
                        end
                    end
                end

                local rankSpoof = spoofer.RankSpoofers[player]
                if rankSpoof and rankSpoof.Enabled and rankSpoof.Data then
                    local rankData = rankSpoof.Data
                    for _, desc in ipairs(row:GetDescendants()) do
                        if (desc:IsA('ImageLabel') or desc:IsA('ImageButton')) and desc ~= nameLabel then
                            local dName = desc.Name:lower()
                            local dImg = type(desc.Image) == 'string' and desc.Image:lower() or ''

                            local isDevice = dName:find('device', 1, true) or dName:find('platform', 1, true)
                                or dName:find('control', 1, true) or dName:find('input', 1, true)
                                or dImg:find('mouse', 1, true) or dImg:find('keyboard', 1, true)
                                or dImg:find('touch', 1, true) or dImg:find('gamepad', 1, true)
                                or dImg:find('controller', 1, true) or dImg:find('console', 1, true)
                                or dImg:find('vr', 1, true) or dImg:find('desktop', 1, true)
                                or dImg:find('phone', 1, true) or dImg:find('mobile', 1, true)
                            local isAvatar = dImg:find('avatar', 1, true) or dImg:find('headshot', 1, true) or dImg:find('rbxthumb', 1, true)
                            local isAudio = dName:find('voice', 1, true) or dName:find('mute', 1, true) or dName:find('speaker', 1, true) or dName:find('mic', 1, true)

                            if not isDevice and not isAvatar and not isAudio then
                                local isRankNamed = dName:find('rank', 1, true) or dName:find('elo', 1, true)
                                    or dName:find('badge', 1, true) or dName:find('tier', 1, true)
                                    or dName:find('icon', 1, true) or dName:find('status', 1, true)
                                    or dName:find('division', 1, true)

                                local isRightAligned = false
                                if desc.Position.X.Scale >= 0.45 or (desc.AnchorPoint and desc.AnchorPoint.X >= 0.5) then
                                    isRightAligned = true
                                elseif desc.AbsolutePosition.X > nameLabel.AbsolutePosition.X + 20 then
                                    isRightAligned = true
                                end

                                if (isRankNamed or isRightAligned) and rankData.Icon then
                                    if not spoofer.OriginalRankIcons[desc] then
                                        spoofer.OriginalRankIcons[desc] = {
                                            Image = desc.Image,
                                            ImageRectOffset = desc.ImageRectOffset,
                                            ImageRectSize = desc.ImageRectSize,
                                            ImageColor3 = desc.ImageColor3,
                                            Visible = desc.Visible,
                                        }
                                    end
                                    desc.Image = rankData.Icon
                                    if rankData.RectSize and rankData.RectSize ~= Vector2.zero then
                                        desc.ImageRectOffset = rankData.RectOffset or Vector2.zero
                                        desc.ImageRectSize = rankData.RectSize
                                    else
                                        desc.ImageRectOffset = Vector2.zero
                                        desc.ImageRectSize = Vector2.zero
                                    end
                                    if desc.ImageTransparency > 0.5 then
                                        desc.ImageTransparency = 0
                                    end
                                    desc.Visible = true
                                end
                            end
                        elseif desc:IsA('TextLabel') and desc ~= nameLabel then
                            local t = desc.Text
                            if t == 'Unranked' or tonumber(t) ~= nil
                                or t:lower():find('bronze', 1, true) or t:lower():find('silver', 1, true)
                                or t:lower():find('gold', 1, true) or t:lower():find('platinum', 1, true)
                                or t:lower():find('diamond', 1, true) or t:lower():find('onyx', 1, true)
                                or t:lower():find('nemesis', 1, true) then
                                desc.Text = rankData.RankName
                            end
                        end
                    end
                elseif rankSpoof and not rankSpoof.Enabled then
                    for _, desc in ipairs(row:GetDescendants()) do
                        local origIcon = spoofer.OriginalRankIcons[desc]
                        if origIcon then
                            desc.Image = origIcon.Image
                            desc.ImageRectOffset = origIcon.ImageRectOffset
                            desc.ImageRectSize = origIcon.ImageRectSize
                            desc.ImageColor3 = origIcon.ImageColor3
                            desc.Visible = origIcon.Visible
                            spoofer.OriginalRankIcons[desc] = nil
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.BindPlayerListRoot(root)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if spoofer.PlayerListConnections[root] then
                    return
                end
                local scheduled = false
                local conn = root.DescendantAdded:Connect(function(desc)
                    if (desc:IsA('TextLabel') or desc:IsA('ImageLabel')) and not scheduled then
                        scheduled = true
                        task.delay(0.25, function()
                            scheduled = false
                            if not spoofer.Started then return end
                            for _, p in ipairs(Players:GetPlayers()) do
                                if spoofer.NameSpoofers[p] or (spoofer.RankSpoofers[p] and spoofer.RankSpoofers[p].Enabled) then
                                    local rows = spoofer.FindPlayerRowContainers(p, root)
                                    for _, rowInfo in ipairs(rows) do
                                        spoofer.UpdateRowVisuals(p, rowInfo)
                                    end
                                end
                            end
                        end)
                    end
                end)
                spoofer.PlayerListConnections[root] = conn
            end

            function RivalsRuntimeBridge.PlayerSpoofer.UpdatePlayerGui(player, targetName, origName)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local roots = spoofer.ResolvePlayerListRoots()
                for _, root in ipairs(roots) do
                    spoofer.BindPlayerListRoot(root)
                    local rows = spoofer.FindPlayerRowContainers(player, root)
                    for _, rowInfo in ipairs(rows) do
                        spoofer.UpdateRowVisuals(player, rowInfo)
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.UpdateNametag(player, displayName, username)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local char = player.Character
                if not char then
                    return
                end
                local hrp = char:FindFirstChild('HumanoidRootPart') or char.PrimaryPart
                local nametag = (hrp and hrp:FindFirstChild('NametagGui')) or char:FindFirstChild('NametagGui', true)
                if not nametag then
                    return
                end
                local elements = nametag:FindFirstChild('Elements')
                local nameDisplay = elements and elements:FindFirstChild('NameDisplay') or nametag:FindFirstChild('NameDisplay', true)
                if nameDisplay then
                    local dispLabel = nameDisplay:FindFirstChild('DisplayName')
                    if dispLabel and dispLabel:IsA('TextLabel') then
                        dispLabel.Text = displayName
                        for _, child in ipairs(dispLabel:GetDescendants()) do
                            if child:IsA('TextLabel') then
                                child.Text = displayName
                            end
                        end
                    end
                    local userLabel = nameDisplay:FindFirstChild('Username')
                    if userLabel and userLabel:IsA('TextLabel') then
                        if userLabel.Text ~= '' or username then
                            userLabel.Text = username and ('@' .. username) or ('@' .. displayName)
                        end
                    end
                else
                    for _, desc in ipairs(nametag:GetDescendants()) do
                        if desc:IsA('TextLabel') then
                            desc.Text = displayName
                        end
                    end
                end

                local rankSpoof = spoofer.RankSpoofers[player]
                if rankSpoof and rankSpoof.Enabled and rankSpoof.Data then
                    local rankData = rankSpoof.Data
                    for _, desc in ipairs(nametag:GetDescendants()) do
                        if (desc:IsA('ImageLabel') or desc:IsA('ImageButton')) then
                            local dName = desc.Name:lower()
                            if dName:find('rank', 1, true) or dName:find('badge', 1, true) or dName:find('tier', 1, true) then
                                desc.Image = rankData.Icon
                                if rankData.RectSize and rankData.RectSize ~= Vector2.zero then
                                    desc.ImageRectOffset = rankData.RectOffset or Vector2.zero
                                    desc.ImageRectSize = rankData.RectSize
                                end
                                desc.Visible = true
                            end
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.SetNameSpoof(player, enabled, spoofedValue)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if not player or player.Parent == nil then
                    return
                end
                local orig = spoofer.GetOriginal(player)

                if enabled and spoofedValue and spoofedValue ~= '' then
                    spoofer.NameSpoofers[player] = spoofedValue

                    -- Safe local DisplayName write with guard, never remote player and never player.Name
                    if player == LP and player.DisplayName ~= spoofedValue then
                        spoofer._WritingDisplayName = true
                        pcall(function() player.DisplayName = spoofedValue end)
                        spoofer._WritingDisplayName = false
                    end

                    spoofer.UpdateNametag(player, spoofedValue, orig.Name)
                    spoofer.UpdatePlayerGui(player)

                    if not spoofer.NameConnections[player] then
                        local conns = {}
                        local function onChar(char)
                            if not char then
                                return
                            end
                            task.defer(function()
                                local currentSpoof = spoofer.NameSpoofers[player]
                                if currentSpoof then
                                    spoofer.UpdateNametag(player, currentSpoof, orig.Name)
                                end
                            end)
                            conns.charDescendant = char.DescendantAdded:Connect(function(desc)
                                if desc.Name == 'NametagGui' or desc.Name == 'DisplayName' or desc.Name == 'NameDisplay' then
                                    task.defer(function()
                                        local currentSpoof = spoofer.NameSpoofers[player]
                                        if currentSpoof then
                                            spoofer.UpdateNametag(player, currentSpoof, orig.Name)
                                        end
                                    end)
                                end
                            end)
                        end

                        conns.charAdded = player.CharacterAdded:Connect(onChar)
                        if player.Character then
                            onChar(player.Character)
                        end

                        if player == LP then
                            conns.nameChanged = player:GetPropertyChangedSignal('DisplayName'):Connect(function()
                                if spoofer._WritingDisplayName then
                                    return
                                end
                                local currentSpoof = spoofer.NameSpoofers[player]
                                if currentSpoof and player.DisplayName ~= currentSpoof then
                                    spoofer._WritingDisplayName = true
                                    pcall(function() player.DisplayName = currentSpoof end)
                                    spoofer._WritingDisplayName = false
                                end
                            end)
                        end

                        spoofer.NameConnections[player] = conns
                    end
                else
                    if spoofer.NameSpoofers[player] ~= nil then
                        local prevSpoof = spoofer.NameSpoofers[player]
                        spoofer.NameSpoofers[player] = nil

                        local conns = spoofer.NameConnections[player]
                        if conns then
                            if conns.charAdded then pcall(function() conns.charAdded:Disconnect() end) end
                            if conns.charDescendant then pcall(function() conns.charDescendant:Disconnect() end) end
                            if conns.nameChanged then pcall(function() conns.nameChanged:Disconnect() end) end
                            spoofer.NameConnections[player] = nil
                        end

                        if player == LP and player.DisplayName ~= orig.DisplayName then
                            spoofer._WritingDisplayName = true
                            pcall(function() player.DisplayName = orig.DisplayName end)
                            spoofer._WritingDisplayName = false
                        end

                        spoofer.UpdateNametag(player, orig.DisplayName, orig.Name)
                        if prevSpoof then
                            spoofer.UpdatePlayerGui(player)
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.SetRankSpoof(player, enabled, eloValue)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local elo = tonumber(eloValue) or 3600
                local rankData = spoofer.ResolveRankData(elo)

                if enabled then
                    spoofer.RankSpoofers[player] = {
                        Enabled = true,
                        Data = rankData,
                    }
                    spoofer.SetAttributeSpoof(player, 'DisplayELO', true, elo)
                    spoofer.SetAttributeSpoof(player, 'Rank', true, rankData.RankName)
                    spoofer.SetAttributeSpoof(player, 'RankName', true, rankData.RankName)
                    spoofer.SetAttributeSpoof(player, 'RankTier', true, rankData.RankName)
                    spoofer.SetAttributeSpoof(player, 'RankedTier', true, rankData.RankName)
                    spoofer.SetAttributeSpoof(player, 'DisplayRank', true, rankData.RankName)
                    spoofer.SetAttributeSpoof(player, 'Elo', true, elo)
                    spoofer.SetAttributeSpoof(player, 'RankedElo', true, elo)
                    spoofer.SetAttributeSpoof(player, 'CompetitiveRank', true, rankData.RankName)
                    if rankData.RankName:lower() == 'nemesis' then
                        spoofer.SetAttributeSpoof(player, 'SeasonLeaderboardRank', true, 1)
                        spoofer.SetAttributeSpoof(player, 'LeaderboardRank', true, 1)
                    end

                    if player == LP then
                        pcall(function()
                            local playerScripts = LP:FindFirstChild('PlayerScripts')
                            local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                            local pdcModule = controllers and controllers:FindFirstChild('PlayerDataController')
                            local ok, pdc = pcall(require, pdcModule)
                            if ok and type(pdc) == 'table' and type(pdc.CurrentData) == 'table' then
                                local cData = pdc.CurrentData
                                local rawData = type(cData.Data) == 'table' and cData.Data or nil
                                if rawData then
                                    rawset(rawData, 'DisplayELO', elo)
                                    rawset(rawData, 'Rank', rankData.RankName)
                                    if type(rawData.Seasons) == 'table' then
                                        for _, sData in pairs(rawData.Seasons) do
                                            if type(sData) == 'table' then
                                                sData.SeasonELO = elo
                                                sData.Rank = rankData.RankName
                                            end
                                        end
                                    end
                                end
                            end
                        end)
                    end

                    local orig = spoofer.GetOriginal(player)
                    spoofer.UpdatePlayerGui(player, spoofer.NameSpoofers[player] or player.DisplayName, orig.Name)
                    spoofer.UpdateNametag(player, spoofer.NameSpoofers[player] or player.DisplayName, spoofer.NameSpoofers[player] or player.Name)
                else
                    if spoofer.RankSpoofers[player] then
                        spoofer.RankSpoofers[player] = { Enabled = false }
                        spoofer.SetAttributeSpoof(player, 'DisplayELO', false, nil)
                        spoofer.SetAttributeSpoof(player, 'Rank', false, nil)
                        spoofer.SetAttributeSpoof(player, 'RankName', false, nil)
                        spoofer.SetAttributeSpoof(player, 'RankTier', false, nil)
                        spoofer.SetAttributeSpoof(player, 'RankedTier', false, nil)
                        spoofer.SetAttributeSpoof(player, 'DisplayRank', false, nil)
                        spoofer.SetAttributeSpoof(player, 'Elo', false, nil)
                        spoofer.SetAttributeSpoof(player, 'RankedElo', false, nil)
                        spoofer.SetAttributeSpoof(player, 'CompetitiveRank', false, nil)
                        spoofer.SetAttributeSpoof(player, 'SeasonLeaderboardRank', false, nil)
                        spoofer.SetAttributeSpoof(player, 'LeaderboardRank', false, nil)

                        local orig = spoofer.GetOriginal(player)
                        spoofer.UpdatePlayerGui(player, orig.DisplayName, orig.Name)
                        spoofer.UpdateNametag(player, orig.DisplayName, orig.Name)
                        spoofer.RankSpoofers[player] = nil
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.CreateBinder(instance, attribute)
                local binder = {
                    Instance = instance,
                    Attribute = attribute,
                    Original = instance:GetAttribute(attribute),
                    IsWriting = false,
                    Spoofed = nil,
                    Connection = nil,
                }
                binder.Connection = instance:GetAttributeChangedSignal(attribute):Connect(function()
                    if binder.IsWriting then
                        return
                    end
                    binder.Original = instance:GetAttribute(attribute)
                    binder.IsWriting = true
                    if binder.Spoofed ~= nil then
                        instance:SetAttribute(attribute, binder.Spoofed.value)
                    end
                    binder.IsWriting = false
                end)
                return binder
            end

            function RivalsRuntimeBridge.PlayerSpoofer.BinderSet(binder, spoofed)
                binder.Spoofed = spoofed
                binder.IsWriting = true
                if spoofed == nil then
                    binder.Instance:SetAttribute(binder.Attribute, binder.Original)
                else
                    binder.Instance:SetAttribute(binder.Attribute, spoofed.value)
                end
                binder.IsWriting = false
            end

            function RivalsRuntimeBridge.PlayerSpoofer.BinderDestroy(binder)
                if binder.Connection then
                    binder.Connection:Disconnect()
                end
                pcall(function()
                    binder.Instance:SetAttribute(binder.Attribute, binder.Original)
                end)
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Bind(player, attribute)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    entries = {}
                    spoofer.Binders[player] = entries
                end
                local binder = entries[attribute]
                if binder == nil then
                    binder = spoofer.CreateBinder(player, attribute)
                    entries[attribute] = binder
                end
                return binder
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Unbind(player, attribute)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    return
                end
                local binder = entries[attribute]
                if binder ~= nil then
                    spoofer.BinderDestroy(binder)
                    entries[attribute] = nil
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.SetAttributeSpoof(player, attribute, enabled, value)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if enabled then
                    spoofer.BinderSet(spoofer.Bind(player, attribute), { value = value })
                else
                    spoofer.Unbind(player, attribute)
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ScopeSuffix(player)
                return player == LP and 'You' or 'Oth'
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ReadOption(optionId)
                local option = Options and Options[optionId]
                return option and option.Value
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Apply(player)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if not player or player.Parent == nil then
                    return
                end
                local suffix = spoofer.ScopeSuffix(player)
                for _, field in ipairs(spoofer.AttributeFields) do
                    local enabled = spoofer.ReadToggle('PSpoof' .. suffix .. field.key .. 'T')
                    if field.isName then
                        local raw = spoofer.ReadOption('PSpoof' .. suffix .. field.key .. 'V')
                        local value = (type(raw) == 'string' and raw ~= '') and raw or (suffix == 'You' and field.youDefault or field.othDefault)
                        spoofer.SetNameSpoof(player, enabled, value)
                    elseif field.key == 'RankedElo' then
                        local raw = spoofer.ReadOption('PSpoof' .. suffix .. field.key .. 'V')
                        local value = tonumber(raw) or (suffix == 'You' and 3600 or 0)
                        spoofer.SetRankSpoof(player, enabled, value)
                    elseif field.control == 'const' then
                        spoofer.SetAttributeSpoof(player, field.attribute, enabled, field.constValue)
                    else
                        local raw = spoofer.ReadOption('PSpoof' .. suffix .. field.key .. 'V')
                        local value = raw
                        if field.control == 'number' then
                            value = tonumber(raw)
                        elseif type(raw) == 'string' and raw == '' then
                            value = nil
                        end
                        spoofer.SetAttributeSpoof(player, field.attribute, enabled and value ~= nil, value)
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Cleanup(player)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                spoofer.SetNameSpoof(player, false, nil)
                spoofer.SetRankSpoof(player, false, nil)
                spoofer.OriginalNames[player] = nil
                local entries = spoofer.Binders[player]
                if entries == nil then
                    return
                end
                for _, binder in pairs(entries) do
                    spoofer.BinderDestroy(binder)
                end
                spoofer.Binders[player] = nil
            end

            function RivalsRuntimeBridge.PlayerSpoofer.RefreshAll()
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                spoofer.Start()
                for _, player in ipairs(Players:GetPlayers()) do
                    spoofer.Apply(player)
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Start()
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if spoofer.Started then
                    return
                end
                spoofer.Started = true
                for _, player in ipairs(Players:GetPlayers()) do
                    spoofer.GetOriginal(player)
                end
                local roots = spoofer.ResolvePlayerListRoots()
                for _, root in ipairs(roots) do
                    spoofer.BindPlayerListRoot(root)
                end
                spoofer.LifecycleConnections[#spoofer.LifecycleConnections + 1] =
                    Players.PlayerAdded:Connect(GuardRivalsCallback('PlayerSpoofer_PlayerAdded', function(player)
                        spoofer.GetOriginal(player)
                        spoofer.Apply(player)
                    end))
                spoofer.LifecycleConnections[#spoofer.LifecycleConnections + 1] =
                    Players.PlayerRemoving:Connect(GuardRivalsCallback('PlayerSpoofer_PlayerRemoving', function(player)
                        spoofer.Cleanup(player)
                    end))
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Destroy()
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                for _, connection in ipairs(spoofer.LifecycleConnections) do
                    pcall(function() connection:Disconnect() end)
                end
                spoofer.LifecycleConnections = {}
                for root, conn in pairs(spoofer.PlayerListConnections) do
                    pcall(function() conn:Disconnect() end)
                end
                spoofer.PlayerListConnections = {}
                spoofer.Started = false
                for player in pairs(spoofer.NameSpoofers) do
                    spoofer.SetNameSpoof(player, false, nil)
                end
                for player in pairs(spoofer.RankSpoofers) do
                    spoofer.SetRankSpoof(player, false, nil)
                end
                for player in pairs(spoofer.Binders) do
                    spoofer.Cleanup(player)
                end
                for desc, orig in pairs(spoofer.OriginalRankIcons) do
                    pcall(function()
                        desc.Image = orig.Image
                        desc.ImageRectOffset = orig.ImageRectOffset
                        desc.ImageRectSize = orig.ImageRectSize
                        desc.ImageColor3 = orig.ImageColor3
                        desc.Visible = orig.Visible
                    end)
                end
                spoofer.OriginalRankIcons = setmetatable({}, { __mode = 'k' })
            end

            RivalsRuntimeBridge.ExtraSpoof = {
                Destroyed = false,
                Modules = {},
                Connections = {},
                ImageConnections = setmetatable({}, { __mode = 'k' }),
                AnonConnections = {},
                FakeNames = setmetatable({}, { __mode = 'k' }),
                LeaderboardOldAttrs = {},
                DuelHistoryCopy = nil,
                LoggedEloCopy = nil,
                GiftClaimedCopy = nil,
                CharmHooked = false,
                DataHooked = false,
                BadgeHooked = false,
                HasGamepassHooked = false,
                IdentityStarted = false,
                CharmEloMap = {
                    Unranked = -1,
                    ['Bronze 1'] = 0, ['Bronze 2'] = 200, ['Bronze 3'] = 400,
                    ['Silver 1'] = 600, ['Silver 2'] = 800, ['Silver 3'] = 1000,
                    ['Gold 1'] = 1200, ['Gold 2'] = 1400, ['Gold 3'] = 1600,
                    ['Platinum 1'] = 1800, ['Platinum 2'] = 2000, ['Platinum 3'] = 2200,
                    ['Diamond 1'] = 2400, ['Diamond 2'] = 2600, ['Diamond 3'] = 2800,
                    ['Onyx 1'] = 3000, ['Onyx 2'] = 3200, ['Onyx 3'] = 3400,
                    Nemesis = 3600, Archnemesis = 3600,
                },
                SeasonNameMap = {
                    [0] = 'Zero', [1] = 'Warp', [2] = 'Polar', [3] = 'Fame',
                    Zero = 0, Warp = 1, Polar = 2, Fame = 3,
                },
                SeasonToggleMap = {
                    [0] = 'PSpoofCharmS0T',
                    [1] = 'PSpoofCharmS1T',
                    [2] = 'PSpoofCharmS2T',
                    [3] = 'PSpoofCharmS3T',
                },
                WordList = {
                    'late', 'couple', 'economic', 'obscure', 'landscape', 'spot', 'college', 'rainbow',
                    'leg', 'mixture', 'frank', 'commitment', 'draft', 'motivation', 'fuss', 'settle',
                    'jelly', 'confine', 'pin', 'modernize', 'velvet', 'quarter', 'physical', 'differ',
                    'dish', 'aisle', 'happen', 'council', 'appeal', 'depart', 'urgency', 'vessel',
                },
                CurrencyFields = {
                    { toggle = 'PSpoofCurKeysT', value = 'PSpoofCurKeysV', key = 'WeaponKeys' },
                    { toggle = 'PSpoofCurTokensT', value = 'PSpoofCurTokensV', key = 'UnlockTokens' },
                    { toggle = 'PSpoofCurEventT', value = 'PSpoofCurEventV', key = 'EventCurrency' },
                    { toggle = 'PSpoofCurGloryT', value = 'PSpoofCurGloryV', key = 'Glory' },
                    { toggle = 'PSpoofCurTicketsT', value = 'PSpoofCurTicketsV', key = 'SkinTickets' },
                },
                LeaderboardFields = {
                    { toggle = 'PSpoofLbEloT', value = 'PSpoofLbEloV', name = 'Highest ELO' },
                    { toggle = 'PSpoofLbStreakT', value = 'PSpoofLbStreakV', name = 'Current Highest Win Streak',
                        attr = 'StatisticDuelsWinStreak' },
                    { toggle = 'PSpoofLbKillsT', value = 'PSpoofLbKillsV', name = 'Most Eliminations' },
                    { toggle = 'PSpoofLbWinsT', value = 'PSpoofLbWinsV', name = 'Most Wins' },
                    { toggle = 'PSpoofLbLevelT', value = 'PSpoofLbLevelV', name = 'Highest Level', attr = 'Level' },
                },
            }

            function RivalsRuntimeBridge.ExtraSpoof.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.ExtraSpoof.ReadOption(optionId)
                local option = Options and Options[optionId]
                return option and option.Value
            end

            function RivalsRuntimeBridge.ExtraSpoof.ReadNumber(optionId, fallback)
                local value = tonumber(RivalsRuntimeBridge.ExtraSpoof.ReadOption(optionId))
                if value == nil then
                    return fallback
                end
                return value
            end

            function RivalsRuntimeBridge.ExtraSpoof.ReadText(optionId, fallback)
                local value = RivalsRuntimeBridge.ExtraSpoof.ReadOption(optionId)
                if type(value) == 'string' then
                    return value
                end
                return fallback
            end

            function RivalsRuntimeBridge.ExtraSpoof.RequireController(name)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.Modules[name] then
                    return extra.Modules[name]
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local module = controllers and controllers:FindFirstChild(name)
                if not module then
                    return nil
                end
                local ok, value = pcall(require, module)
                if ok and type(value) == 'table' then
                    extra.Modules[name] = value
                    return value
                end
                return nil
            end

            function RivalsRuntimeBridge.ExtraSpoof.RequireRSModule(name)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.Modules[name] then
                    return extra.Modules[name]
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local module = modules and modules:FindFirstChild(name)
                if not module then
                    return nil
                end
                local ok, value = pcall(require, module)
                if ok and type(value) == 'table' then
                    extra.Modules[name] = value
                    return value
                end
                return nil
            end

            function RivalsRuntimeBridge.ExtraSpoof.Replicate(key)
                local pdc = RivalsRuntimeBridge.ExtraSpoof.RequireController('PlayerDataController')
                local currentData = pdc and rawget(pdc, 'CurrentData')
                if type(currentData) == 'table' and type(currentData.Replicate) == 'function' then
                    pcall(currentData.Replicate, currentData, key)
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.TrackConnection(connection)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.Connections[#extra.Connections + 1] = connection
                return connection
            end

            function RivalsRuntimeBridge.ExtraSpoof.ResolveCharmElo()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local rank = extra.ReadText('PSpoofCharmRank', 'Use Spoofed ELO')
                local mapped = extra.CharmEloMap[rank]
                if mapped ~= nil then
                    return mapped
                end
                if extra.ReadToggle('PSpoofLbEloT') then
                    return extra.ReadNumber('PSpoofLbEloV', 0)
                end
                if extra.ReadToggle('PSpoofYouRankedEloT') then
                    return tonumber(extra.ReadOption('PSpoofYouRankedEloV')) or 3600
                end
                return tonumber(LP:GetAttribute('DisplayELO')) or 0
            end

            function RivalsRuntimeBridge.ExtraSpoof.IsSeasonCharmEnabled(seasonName)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local seasonNum = extra.SeasonNameMap[seasonName]
                local toggleId = seasonNum ~= nil and extra.SeasonToggleMap[seasonNum] or nil
                return toggleId ~= nil and extra.ReadToggle(toggleId)
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureCharmHook()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.CharmHooked then
                    return true
                end
                local seasonLibrary = extra.RequireRSModule('SeasonLibrary')
                if type(seasonLibrary) ~= 'table' or type(seasonLibrary.FormatSeasonRankCharm) ~= 'function' then
                    return false
                end
                extra.OriginalFormatCharm = seasonLibrary.FormatSeasonRankCharm
                seasonLibrary.FormatSeasonRankCharm = function(self, model, seasonName, elo, archRank)
                    if extra.Destroyed == false and extra.IsSeasonCharmEnabled(seasonName) then
                        elo = extra.ResolveCharmElo()
                        archRank = extra.ReadNumber('PSpoofCharmArch', 1)
                    end
                    return extra.OriginalFormatCharm(self, model, seasonName, elo, archRank)
                end
                extra.CharmHooked = true
                extra.CharmLibrary = seasonLibrary
                return true
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateCharmModels(target)
                if shutting_down or not __akira_boot_alive() then
                    return
                end
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local anyCharm = false
                for _, toggleId in pairs(extra.SeasonToggleMap) do
                    if type(toggleId) == 'string' and extra.ReadToggle(toggleId) then
                        anyCharm = true
                        break
                    end
                end
                if not anyCharm then
                    return
                end
                extra.EnsureCharmHook()
                local seasonLibrary = extra.CharmLibrary or extra.RequireRSModule('SeasonLibrary')
                if type(seasonLibrary) ~= 'table' or type(seasonLibrary.FormatSeasonRankCharm) ~= 'function' then
                    return
                end
                local elo = extra.ResolveCharmElo()
                local archRank = extra.ReadNumber('PSpoofCharmArch', 1)

                local function apply(descendant)
                    if not descendant or not descendant:IsA('Model') then
                        return
                    end
                    local name = descendant.Name
                    if string.sub(name, 1, 7) ~= 'Season ' then
                        return
                    end
                    if not descendant:FindFirstChild('Extra') then
                        return
                    end
                    local seasonNum = tonumber(string.sub(name, 8))
                    local toggleId = seasonNum and extra.SeasonToggleMap[seasonNum] or nil
                    local seasonName = seasonNum and extra.SeasonNameMap[seasonNum] or nil
                    if toggleId and seasonName and extra.ReadToggle(toggleId) then
                        pcall(seasonLibrary.FormatSeasonRankCharm, seasonLibrary, descendant, seasonName, elo, archRank)
                    end
                end

                if typeof(target) == 'Instance' then
                    apply(target)
                    return
                end

                local slice = os.clock()
                local function consider(inst)
                    apply(inst)
                    if os.clock() - slice >= 0.004 then
                        task.wait()
                        slice = os.clock()
                        if shutting_down or not __akira_boot_alive() then
                            return false
                        end
                    end
                    return true
                end
                for _, child in ipairs(Workspace:GetChildren()) do
                    if not consider(child) then
                        return
                    end
                    if child:IsA('Model') or child:IsA('Folder') then
                        for _, nested in ipairs(child:GetChildren()) do
                            if not consider(nested) then
                                return
                            end
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.FilterGet(key, data)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.Destroyed then
                    return data
                end
                for _, field in ipairs(extra.CurrencyFields) do
                    if key == field.key and extra.ReadToggle(field.toggle) then
                        return extra.ReadNumber(field.value, data)
                    end
                end
                if key == 'DuelHistory' and extra.ReadToggle('PSpoofHistoryT') then
                    extra.DuelHistoryCopy = extra.DuelHistoryCopy or data
                    extra.MutateDuelHistory(extra.DuelHistoryCopy)
                    return extra.DuelHistoryCopy
                end
                if key == 'LoggedELOEvents' and extra.ReadToggle('PSpoofHistoryT') then
                    extra.LoggedEloCopy = extra.LoggedEloCopy or data
                    extra.MutateLoggedElo(extra.LoggedEloCopy)
                    return extra.LoggedEloCopy
                end
                if extra.ReadToggle('PSpoofFakeGiftT') then
                    if key == 'GiftRobuxSpentProgress' then
                        return extra.ReadNumber('PSpoofGiftSpent', type(data) == 'number' and data or 0)
                    end
                    if key == 'GiftRobuxSpentRewardsClaimed' then
                        return extra.ReadNumber('PSpoofGiftClaimed', type(data) == 'number' and data or 0)
                    end
                end
                if extra.ReadToggle('PSpoofAllPassesT') and key == 'GamepassBundlesClaimed' then
                    local claimed = type(data) == 'table' and AkiraClone(data) or {}
                    return setmetatable(claimed, {
                        __index = function()
                            return true
                        end,
                    })
                end
                return data
            end

            __akira_boot_yield()

            function RivalsRuntimeBridge.ResolveRawDataControllerGet(pdc)
                if RivalsRuntimeBridge.RawDataControllerGet then
                    return RivalsRuntimeBridge.RawDataControllerGet
                end
                local orig = rawget(pdc, 'Get')
                if type(orig) ~= 'function' then
                    local mt = getmetatable(pdc)
                    orig = (type(mt) == 'table' and type(mt.__index) == 'table') and rawget(mt.__index, 'Get') or nil
                end
                if type(orig) == 'function' and orig ~= RivalsRuntimeBridge.MasterDataControllerGet then
                    RivalsRuntimeBridge.RawDataControllerGet = orig
                end
                return orig
            end

            function RivalsRuntimeBridge.MasterDataControllerGet(self, key, ...)
                local orig = RivalsRuntimeBridge.RawDataControllerGet
                local data = nil
                if type(orig) == 'function' and orig ~= RivalsRuntimeBridge.MasterDataControllerGet then
                    data = orig(self, key, ...)
                end

                if RivalsCosmetics and type(RivalsCosmetics.IsEnabled) == 'function' and type(RivalsCosmeticsState) == 'table' and RivalsCosmetics.IsEnabled() then
                    if key == 'CosmeticInventory' then
                        local cachedProxy = RivalsCosmeticsState.CachedCosmeticInventoryProxy
                        if cachedProxy then
                            return cachedProxy
                        end
                        local unlocked = RivalsCosmetics.BuildNativeUnlockedInventory()
                        local proxy = {}
                        if type(data) == 'table' then
                            for k, v in pairs(data) do
                                proxy[k] = v
                            end
                        end
                        if type(unlocked) == 'table' then
                            for k, v in pairs(unlocked) do
                                if proxy[k] == nil then
                                    proxy[k] = v
                                end
                            end
                        end
                        cachedProxy = setmetatable(proxy, {
                            __index = function()
                                return true
                            end,
                        })
                        RivalsCosmeticsState.CachedCosmeticInventoryProxy = cachedProxy
                        return cachedProxy
                    elseif key == 'FavoritedCosmetics' then
                        local favorites = RivalsCosmeticsState.FavoritedCosmetics
                        if type(favorites) == 'table' and next(favorites) then
                            local result = type(data) == 'table' and AkiraClone(data) or {}
                            for weapon, favs in pairs(favorites) do
                                if type(favs) == 'table' then
                                    result[weapon] = result[weapon] or {}
                                    for name, isFav in pairs(favs) do
                                        result[weapon][name] = isFav
                                    end
                                end
                            end
                            return result
                        end
                    end
                end

                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra and type(extra.FilterGet) == 'function' then
                    data = extra.FilterGet(key, data)
                end

                return data
            end

            function RivalsRuntimeBridge.MasterCurrentDataGet(self, key, ...)
                local orig = RivalsRuntimeBridge.RawCurrentDataGet
                local data = nil
                if type(orig) == 'function' and orig ~= RivalsRuntimeBridge.MasterCurrentDataGet then
                    data = orig(self, key, ...)
                end
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra and type(extra.FilterGet) == 'function' then
                    data = extra.FilterGet(key, data)
                end
                return data
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureDataHook()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local pdc = extra.RequireController('PlayerDataController')
                if type(pdc) ~= 'table' or type(pdc.Get) ~= 'function' then
                    return pdc
                end
                RivalsRuntimeBridge.ResolveRawDataControllerGet(pdc)
                extra.OriginalGet = RivalsRuntimeBridge.RawDataControllerGet
                if pdc.Get ~= RivalsRuntimeBridge.MasterDataControllerGet then
                    pdc.Get = RivalsRuntimeBridge.MasterDataControllerGet
                end
                extra.DataHooked = true

                local currentData = rawget(pdc, 'CurrentData')
                if type(currentData) == 'table' and type(currentData.Get) == 'function' then
                    if not RivalsRuntimeBridge.RawCurrentDataGet then
                        RivalsRuntimeBridge.RawCurrentDataGet = currentData.Get
                    end
                    extra.OriginalCurrentGet = RivalsRuntimeBridge.RawCurrentDataGet
                    if currentData.Get ~= RivalsRuntimeBridge.MasterCurrentDataGet then
                        currentData.Get = RivalsRuntimeBridge.MasterCurrentDataGet
                    end
                end
                return pdc
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureHasGamepassHook()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local pdc = extra.RequireController('PlayerDataController')
                if extra.HasGamepassHooked or type(pdc) ~= 'table' or type(pdc.HasGamepass) ~= 'function' then
                    return
                end
                extra.OriginalHasGamepass = pdc.HasGamepass
                pdc.HasGamepass = function(self, name, ...)
                    local owned = extra.OriginalHasGamepass(self, name, ...)
                    if extra.Destroyed == false and extra.ReadToggle('PSpoofAllPassesT')
                        and type(name) == 'string' then
                        return true
                    end
                    return owned
                end
                extra.HasGamepassHooked = true
            end

            function RivalsRuntimeBridge.ExtraSpoof.InsertPlayerByValue(list, userId, value)
                if type(list) ~= 'table' then
                    return
                end
                for index = #list, 1, -1 do
                    local entry = list[index]
                    if entry and tonumber(entry.key) == userId then
                        table.remove(list, index)
                        break
                    end
                end
                local rank = 1
                for index, entry in ipairs(list) do
                    if tonumber(entry.value) >= value then
                        rank = index + 1
                    else
                        break
                    end
                end
                table.insert(list, rank, { key = tostring(userId), value = value })
            end

            function RivalsRuntimeBridge.ExtraSpoof.GetLeaderboardSerial(name)
                local controller = RivalsRuntimeBridge.ExtraSpoof.RequireController('LeaderboardController')
                local serials = controller and controller.LeaderboardSerials
                return type(serials) == 'table' and serials[name] or nil
            end

            function RivalsRuntimeBridge.ExtraSpoof.FireLeaderboardRefresh(name)
                local controller = RivalsRuntimeBridge.ExtraSpoof.RequireController('LeaderboardController')
                local refreshed = controller and controller.Refreshed
                if refreshed and type(refreshed.Fire) == 'function' then
                    pcall(refreshed.Fire, refreshed, name)
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.RemoveLocalFromLeaderboard(name)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local serial = extra.GetLeaderboardSerial(name)
                if not (serial and type(serial.Players) == 'table') then
                    return
                end
                local userId = LP.UserId
                for index = #serial.Players, 1, -1 do
                    local player = serial.Players[index]
                    if player and (player.UserId == userId or player.UserID == userId
                        or player.PlayerId == userId or tonumber(player.key) == userId) then
                        table.remove(serial.Players, index)
                    end
                end
                extra.FireLeaderboardRefresh(name)
            end

            function RivalsRuntimeBridge.ExtraSpoof.ApplyLeaderboardValue(name, value)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                task.spawn(function()
                    local deadline = os.clock() + 12
                    while extra.Destroyed == false and os.clock() < deadline do
                        local serial = extra.GetLeaderboardSerial(name)
                        if serial and type(serial.Players) == 'table' and #serial.Players > 0 then
                            extra.InsertPlayerByValue(serial.Players, LP.UserId, value)
                            extra.FireLeaderboardRefresh(name)
                            return
                        end
                        task.wait(0.5)
                    end
                end)
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureLeaderboardBind()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.LeaderboardBound then
                    return
                end
                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                local misc = remotes and remotes:FindFirstChild('Misc')
                local update = misc and misc:FindFirstChild('UpdateLeaderboard')
                if not (update and update:IsA('RemoteEvent')) then
                    return
                end
                extra.LeaderboardBound = true
                extra.TrackConnection(update.OnClientEvent:Connect(function(data)
                    if extra.Destroyed or type(data) ~= 'table' then
                        return
                    end
                    local boardName = data.Name
                    for _, field in ipairs(extra.LeaderboardFields) do
                        if extra.ReadToggle(field.toggle) and field.name == boardName then
                            task.defer(function()
                                extra.ApplyLeaderboardValue(field.name, extra.ReadNumber(field.value, 0))
                            end)
                        end
                    end
                end))
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateLeaderboards()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.EnsureLeaderboardBind()
                for _, field in ipairs(extra.LeaderboardFields) do
                    if extra.ReadToggle(field.toggle) then
                        local value = extra.ReadNumber(field.value, 0)
                        extra.ApplyLeaderboardValue(field.name, value)
                        if field.attr then
                            if extra.LeaderboardOldAttrs[field.attr] == nil then
                                extra.LeaderboardOldAttrs[field.attr] = LP:GetAttribute(field.attr)
                            end
                            pcall(function()
                                LP:SetAttribute(field.attr, value)
                            end)
                        end
                    else
                        extra.RemoveLocalFromLeaderboard(field.name)
                        if field.attr and extra.LeaderboardOldAttrs[field.attr] ~= nil then
                            pcall(function()
                                LP:SetAttribute(field.attr, extra.LeaderboardOldAttrs[field.attr])
                            end)
                            extra.LeaderboardOldAttrs[field.attr] = nil
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateCurrency()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.EnsureDataHook()
                for _, field in ipairs(extra.CurrencyFields) do
                    extra.Replicate(field.key)
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.MutateDuelHistory(list)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if type(list) ~= 'table' then
                    return
                end
                local matchIndex = math.max(1, math.floor(extra.ReadNumber('PSpoofHistMatch', 1)))
                local match = list[matchIndex]
                if type(match) ~= 'table' then
                    return
                end
                local mode = extra.ReadText('PSpoofHistMode', 'Ranked')
                match.QueueName = mode == 'Ranked' and 'Ranked' or 'Casual'
                match.Map = extra.ReadText('PSpoofHistMap', 'Factory')
                match.Scores = {
                    extra.ReadNumber('PSpoofHistT1', 5),
                    extra.ReadNumber('PSpoofHistT2', 0),
                }
                match.WinningTeamIndex = extra.ReadText('PSpoofHistResult', 'Victory') == 'Victory' and 1 or 2
                local duelerIndex = math.max(1, math.floor(extra.ReadNumber('PSpoofHistDueler', 1)))
                local me = type(match.Duelers) == 'table' and match.Duelers[duelerIndex] or nil
                if type(me) == 'table' then
                    local displayName = extra.ReadText('PSpoofHistDisplay', '')
                    local username = extra.ReadText('PSpoofHistUser', '')
                    if displayName ~= '' then
                        me.DisplayName = displayName
                    end
                    if username ~= '' then
                        me.Username = username
                    end
                    me.Eliminations = extra.ReadNumber('PSpoofHistKills', 15)
                    me.Deaths = extra.ReadNumber('PSpoofHistDeaths', 2)
                    me.Assists = extra.ReadNumber('PSpoofHistAssists', 6)
                    me.Damage = extra.ReadNumber('PSpoofHistDamage', 5000)
                    if mode == 'Ranked' then
                        me.DisplayELO = extra.ReadNumber('PSpoofHistElo', 2000)
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.MutateLoggedElo(list)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if type(list) ~= 'table' then
                    return
                end
                local matchIndex = math.max(1, math.floor(extra.ReadNumber('PSpoofHistMatch', 1)))
                local event = list[matchIndex]
                if type(event) == 'table' then
                    event.CurrentELO = extra.ReadNumber('PSpoofHistElo', 2000)
                    event.ELOIncrement = extra.ReadNumber('PSpoofHistEloChange', 35)
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateDuelHistory()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.EnsureDataHook()
                if extra.ReadToggle('PSpoofHistoryT') then
                    extra.MutateDuelHistory(extra.DuelHistoryCopy)
                    extra.MutateLoggedElo(extra.LoggedEloCopy)
                    extra.Replicate('DuelHistory')
                    extra.Replicate('LoggedELOEvents')
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureBadgeHook()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local wantPremium = extra.ReadToggle('PSpoofYouPremiumT') == true
                local wantVerified = extra.ReadToggle('PSpoofYouVerifiedT') == true
                extra.SpoofPremium = wantPremium
                extra.SpoofVerified = wantVerified
                if not wantPremium and not wantVerified then
                    if extra.BadgeHooked and extra.BadgeIndexOriginal then
                        pcall(function()
                            hookmetamethod(game, '__index', extra.BadgeIndexOriginal)
                        end)
                        extra.BadgeHooked = false
                    end
                    return
                end
                if extra.BadgeHooked then
                    return
                end
                local hookmm = hookmetamethod
                if type(hookmm) ~= 'function' or not __akira_genv.AkiraCaps.gate('Badge Spoof', 'hookmetamethod') then
                    return
                end
                extra.BadgeHooked = true
                local original
                local lpRef = LP
                local hookFn = function(self, key)
                    LPH_ATTRIBUTES(VM(NONE))
                    if self == lpRef then
                        if extra.SpoofPremium and key == 'MembershipType' then
                            return Enum.MembershipType.Premium
                        end
                        if extra.SpoofVerified and key == 'HasVerifiedBadge' then
                            return true
                        end
                    end
                    return original(self, key)
                end
                if type(newcclosure) == 'function' then
                    local okWrap, wrapped = pcall(newcclosure, hookFn)
                    if okWrap and type(wrapped) == 'function' then
                        hookFn = wrapped
                    end
                end
                local ok = pcall(function()
                    original = hookmm(game, '__index', hookFn)
                end)
                extra.BadgeIndexOriginal = ok and original or nil
                if not ok then
                    extra.BadgeHooked = false
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateEloBar()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.ReadToggle('PSpoofYouRankedEloT') == false then
                    return
                end
                local elo = tonumber(extra.ReadOption('PSpoofYouRankedEloV')) or 3600
                local rankData = RivalsRuntimeBridge.PlayerSpoofer.ResolveRankData(elo)
                local rankName = rankData and rankData.RankName or 'Unranked'
                local pg = LP:FindFirstChild('PlayerGui')
                if not pg then
                    return
                end
                for _, descendant in ipairs(pg:GetDescendants()) do
                    if descendant:IsA('TextLabel') and descendant:FindFirstAncestor('ELOBar') then
                        if descendant.Name == 'CurrentELO' then
                            descendant.Text = tostring(elo)
                        elseif descendant.Name == 'LeftRank' or descendant.Name == 'RightRank' then
                            descendant.Text = rankName
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.GetFakeName(player)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local existing = extra.FakeNames[player]
                if existing then
                    return existing
                end
                local words = extra.WordList
                local count = math.random(2, 4)
                local parts = {}
                for index = 1, count do
                    parts[index] = words[math.random(1, #words)]
                end
                local name = table.concat(parts, '') .. tostring(math.random(12, 36))
                extra.FakeNames[player] = name
                return name
            end

            function RivalsRuntimeBridge.ExtraSpoof.ApplyThumbnail(obj)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.Destroyed or not obj or not obj:IsA('ImageLabel') then
                    return
                end
                local image = obj.Image
                if type(image) ~= 'string' then
                    return
                end
                if extra.ReadToggle('PSpoofAnonT') then
                    for _, player in ipairs(Players:GetPlayers()) do
                        image = image:gsub(tostring(player.UserId), '6942067')
                    end
                elseif extra.ReadToggle('PSpoofAvatarT') then
                    local names = { AvatarThumbnail = true, ImageLabel = true, Headshot = true }
                    if names[obj.Name] or (obj.Parent and obj.Parent.Name == 'Thumbnail') then
                        local userId = extra.ReadNumber('PSpoofAvatarUserId', LP.UserId)
                        image = image:gsub(tostring(LP.UserId), tostring(math.floor(userId)))
                    end
                end
                if obj.Image ~= image then
                    obj.Image = image
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.ApplyAnonymousText(obj)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.Destroyed or extra.ReadToggle('PSpoofAnonT') == false then
                    return
                end
                if not (obj and (obj:IsA('TextLabel') or obj:IsA('TextButton') or obj:IsA('TextBox'))) then
                    return
                end
                local text = obj.Text
                if type(text) ~= 'string' or text == '' then
                    return
                end
                for _, player in ipairs(Players:GetPlayers()) do
                    local fakeName = extra.GetFakeName(player)
                    text = text:gsub(player.Name, fakeName)
                    text = text:gsub(player.DisplayName, fakeName)
                end
                if obj.Text ~= text then
                    obj.Text = text
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.BindIdentityObject(obj)
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.ImageConnections[obj] then
                    return
                end
                extra.ApplyThumbnail(obj)
                extra.ApplyAnonymousText(obj)
                local connections = {}
                if obj:IsA('ImageLabel') then
                    connections[#connections + 1] = obj:GetPropertyChangedSignal('Image'):Connect(function()
                        extra.ApplyThumbnail(obj)
                    end)
                end
                if obj:IsA('TextLabel') or obj:IsA('TextButton') or obj:IsA('TextBox') then
                    connections[#connections + 1] = obj:GetPropertyChangedSignal('Text'):Connect(function()
                        extra.ApplyAnonymousText(obj)
                    end)
                end
                extra.ImageConnections[obj] = connections
            end

            function RivalsRuntimeBridge.ExtraSpoof.FindFirstMatchingAttachment(model, name)
                for _, child in ipairs(model:GetChildren()) do
                    if child:IsA('Attachment') and child.Name == name then
                        return child
                    end
                    if not child:IsA('Accoutrement') and not child:IsA('Tool') then
                        local found = RivalsRuntimeBridge.ExtraSpoof.FindFirstMatchingAttachment(child, name)
                        if found then
                            return found
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.AddAccoutrement(character, acc)
                acc.Parent = character
                local handle = acc:FindFirstChild('Handle')
                if not handle then
                    return
                end
                local att = handle:FindFirstChildOfClass('Attachment')
                if att then
                    local match = RivalsRuntimeBridge.ExtraSpoof.FindFirstMatchingAttachment(character, att.Name)
                    if match then
                        local weld = Instance.new('Weld')
                        weld.Part0 = match.Parent
                        weld.Part1 = att.Parent
                        weld.C0 = match.CFrame
                        weld.C1 = att.CFrame
                        weld.Parent = match.Parent
                    end
                else
                    local head = character:FindFirstChild('Head')
                    if head then
                        local weld = Instance.new('Weld')
                        weld.Name = 'HeadWeld'
                        weld.Part0 = head
                        weld.Part1 = handle
                        weld.C0 = CFrame.new(0, 0.5, 0)
                        weld.C1 = acc.AttachmentPoint
                        weld.Parent = head
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.ApplyAvatarToCharacter(character, userId)
                if not character or not character.Parent or not userId then
                    return
                end
                local ok, rig = pcall(function()
                    return Players:CreateHumanoidModelFromUserId(userId)
                end)
                if not ok or not rig then
                    return
                end
                for _, descendant in ipairs(character:GetDescendants()) do
                    if descendant:IsA('Accessory') or descendant:IsA('Shirt') or descendant:IsA('Pants')
                        or descendant:IsA('ShirtGraphic') or descendant:IsA('BodyColors')
                        or descendant:IsA('CharacterMesh') or descendant:IsA('LayeredClothing')
                        or (descendant:IsA('Decal') and descendant.Name == 'face') then
                        pcall(function() descendant:Destroy() end)
                    end
                end
                for _, item in ipairs(rig:GetChildren()) do
                    if item:IsA('Accessory') then
                        pcall(function()
                            RivalsRuntimeBridge.ExtraSpoof.AddAccoutrement(character, item:Clone())
                        end)
                    elseif item:IsA('Shirt') or item:IsA('Pants') or item:IsA('ShirtGraphic')
                        or item:IsA('BodyColors') or item:IsA('LayeredClothing') or item:IsA('CharacterMesh') then
                        pcall(function() item:Clone().Parent = character end)
                    end
                end
                pcall(function() rig:Destroy() end)
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateLiveAvatar()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.ReadToggle('PSpoofAnonT') or extra.ReadToggle('PSpoofAvatarT') == false then
                    return
                end
                local userId = extra.ReadNumber('PSpoofAvatarUserId', LP.UserId)
                extra.ApplyAvatarToCharacter(LP.Character, math.floor(userId))
            end

            function RivalsRuntimeBridge.ExtraSpoof.ScanIdentityRoots()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.ReadToggle('PSpoofAnonT') ~= true and extra.ReadToggle('PSpoofAvatarT') ~= true then
                    return
                end
                local pg = LP:FindFirstChild('PlayerGui')
                if pg then
                    for _, descendant in ipairs(pg:GetDescendants()) do
                        extra.BindIdentityObject(descendant)
                    end
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureIdentityListeners()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                local wantIdentity = extra.ReadToggle('PSpoofAnonT') or extra.ReadToggle('PSpoofAvatarT')
                if extra.ReadToggle('PSpoofFakeRobuxT') then
                    extra.EnsureRobuxListeners()
                end
                if extra.IdentityStarted then
                    if wantIdentity and not extra.IdentityGuiBound then
                        extra.IdentityGuiBound = true
                        local pg = LP:FindFirstChild('PlayerGui')
                        if pg then
                            extra.TrackConnection(pg.DescendantAdded:Connect(function(obj)
                                extra.BindIdentityObject(obj)
                            end))
                            extra.ScanIdentityRoots()
                        end
                    end
                    return
                end
                extra.IdentityStarted = true
                extra.TrackConnection(LP.CharacterAdded:Connect(function(character)
                    task.defer(function()
                        extra.UpdateLiveAvatar()
                    end)
                end))
                local anyCharm = false
                for _, toggleId in pairs(extra.SeasonToggleMap) do
                    if type(toggleId) == 'string' and extra.ReadToggle(toggleId) then
                        anyCharm = true
                        break
                    end
                end
                if anyCharm and extra.CharmWorkspaceBound ~= true then
                    extra.CharmWorkspaceBound = true
                    extra.TrackConnection(Workspace.DescendantAdded:Connect(function(obj)
                        if extra.Destroyed then
                            return
                        end
                        local name = obj.Name
                        if string.sub(name, 1, 7) ~= 'Season ' or not obj:IsA('Model') then
                            return
                        end
                        task.defer(function()
                            extra.UpdateCharmModels(obj)
                        end)
                    end))
                end
                if wantIdentity then
                    extra.IdentityGuiBound = true
                    local pg = LP:FindFirstChild('PlayerGui')
                    if pg then
                        extra.TrackConnection(pg.DescendantAdded:Connect(function(obj)
                            extra.BindIdentityObject(obj)
                        end))
                    end
                    extra.ScanIdentityRoots()
                end
            end

            function RivalsRuntimeBridge.ExtraSpoof.EnsureRobuxListeners()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                if extra.RobuxListenerStarted then
                    return
                end
                extra.RobuxListenerStarted = true
                pcall(function()
                    extra.TrackConnection(game:GetService('CoreGui').DescendantAdded:Connect(function(obj)
                        if extra.Destroyed or extra.SpoofFakeRobux ~= true then
                            return
                        end
                        if obj:IsA('TextLabel') and (obj.Name == 'RobuxPrice' or obj.Name == 'RobuxBalance' or obj.Name == 'RobuxAmount') then
                            obj.Text = extra.FormatRobux(extra.ReadNumber('PSpoofRobuxAmount', 0))
                        end
                    end))
                end)
            end

            function RivalsRuntimeBridge.ExtraSpoof.FormatRobux(amount)
                local text = tostring(math.floor(tonumber(amount) or 0))
                local formatted = text:reverse():gsub('(%d%d%d)', '%1,'):reverse():gsub('^,', '')
                return formatted
            end

            function RivalsRuntimeBridge.ExtraSpoof.UpdateMarketplace()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.EnsureDataHook()
                extra.EnsureHasGamepassHook()
                extra.SpoofFakeRobux = extra.ReadToggle('PSpoofFakeRobuxT') == true
                if extra.ReadToggle('PSpoofFakeGiftT') then
                    extra.Replicate('GiftRobuxSpentProgress')
                    extra.Replicate('GiftRobuxSpentRewardsClaimed')
                end
                if extra.ReadToggle('PSpoofAllPassesT') then
                    extra.Replicate('GamepassBundlesClaimed')
                end
                if extra.SpoofFakeRobux ~= true then
                    return
                end
                extra.EnsureRobuxListeners()
                local amount = extra.FormatRobux(extra.ReadNumber('PSpoofRobuxAmount', 0))
                local function patchRobuxLabels(root)
                    if not root then
                        return
                    end
                    for _, descendant in ipairs(root:GetDescendants()) do
                        if descendant:IsA('TextLabel') and (descendant.Name == 'RobuxPrice' or descendant.Name == 'RobuxBalance' or descendant.Name == 'RobuxAmount') then
                            descendant.Text = amount
                        end
                    end
                end
                local pg = LP:FindFirstChild('PlayerGui')
                patchRobuxLabels(pg)
                local coreGui = game:GetService('CoreGui')
                patchRobuxLabels(coreGui:FindFirstChild('PurchasePromptGui'))
                patchRobuxLabels(coreGui:FindFirstChild('RobloxPromptGui'))
            end

            function RivalsRuntimeBridge.ExtraSpoof.RefreshAll()
                if shutting_down or not __akira_boot_alive() then
                    return
                end
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.Destroyed = false
                extra.EnsureCharmHook()
                extra.EnsureDataHook()
                extra.EnsureHasGamepassHook()
                extra.EnsureBadgeHook()
                extra.EnsureLeaderboardBind()
                extra.EnsureIdentityListeners()
                extra.UpdateLeaderboards()
                extra.UpdateCurrency()
                extra.UpdateDuelHistory()
                extra.UpdateLiveAvatar()
                extra.ScanIdentityRoots()
                extra.UpdateMarketplace()
                extra.UpdateEloBar()
                task.defer(function()
                    if shutting_down or not __akira_boot_alive() then
                        return
                    end
                    extra.UpdateCharmModels()
                end)
            end

            function RivalsRuntimeBridge.ExtraSpoof.Destroy()
                local extra = RivalsRuntimeBridge.ExtraSpoof
                extra.Destroyed = true
                extra.SpoofPremium = false
                extra.SpoofVerified = false
                extra.SpoofFakeRobux = false
                if extra.BadgeHooked and extra.BadgeIndexOriginal then
                    pcall(function()
                        hookmetamethod(game, '__index', extra.BadgeIndexOriginal)
                    end)
                    extra.BadgeHooked = false
                end
                for _, connection in ipairs(extra.Connections) do
                    pcall(function() connection:Disconnect() end)
                end
                extra.Connections = {}
                extra.IdentityStarted = false
                extra.CharmWorkspaceBound = false
                extra.LeaderboardBound = false
                extra.FakeNames = setmetatable({}, { __mode = 'k' })
                extra.ImageConnections = setmetatable({}, { __mode = 'k' })
                local pdc = extra.Modules.PlayerDataController
                if type(pdc) == 'table' then
                    if RivalsRuntimeBridge.RawDataControllerGet and (type(RivalsCosmeticsState) ~= 'table' or not RivalsCosmeticsState.DataControllerGetHooked) then
                        pdc.Get = RivalsRuntimeBridge.RawDataControllerGet
                    end
                    if extra.OriginalHasGamepass and extra.HasGamepassHooked then
                        pdc.HasGamepass = extra.OriginalHasGamepass
                    end
                    local currentData = rawget(pdc, 'CurrentData')
                    if type(currentData) == 'table' and RivalsRuntimeBridge.RawCurrentDataGet then
                        currentData.Get = RivalsRuntimeBridge.RawCurrentDataGet
                    end
                end
                if extra.CharmLibrary and extra.OriginalFormatCharm and extra.CharmHooked then
                    extra.CharmLibrary.FormatSeasonRankCharm = extra.OriginalFormatCharm
                end
                extra.CharmHooked = false
                extra.DataHooked = false
                extra.HasGamepassHooked = false
                extra.BadgeHooked = false
                extra.WrappedGet = nil
                extra.WrappedCurrentGet = nil
                extra.DuelHistoryCopy = nil
                extra.LoggedEloCopy = nil
            end

            RivalsRuntimeBridge.AnimationPlayer = {
                Character = nil,
                Humanoid = nil,
                Track = nil,
                AnimatorWait = nil,
                AwaitingOwnership = false,
                LastLoadFailure = nil,
            }

            function RivalsRuntimeBridge.AnimationPlayer.ReadEnabled()
                return Toggles and Toggles.P10S6T1 and Toggles.P10S6T1.Value == true
            end

            function RivalsRuntimeBridge.AnimationPlayer.ReadSpeed()
                local option = Options and Options.P10S6S1
                return option and type(option.Value) == 'number' and option.Value or 1
            end

            function RivalsRuntimeBridge.AnimationPlayer.ResolveAnimationId()
                local option = Options and Options.P10S6I1
                local value = option and option.Value
                if type(value) ~= 'string' then
                    return nil
                end
                return value:match('%d+')
            end

            function RivalsRuntimeBridge.AnimationPlayer.Stop()
                local player = RivalsRuntimeBridge.AnimationPlayer
                if player.AnimatorWait then
                    player.AnimatorWait:Disconnect()
                    player.AnimatorWait = nil
                end
                local track = player.Track
                player.Track = nil
                if track then
                    pcall(track.Stop, track)
                    pcall(track.Destroy, track)
                end
            end

            function RivalsRuntimeBridge.AnimationPlayer.Apply(awaitOwnership)
                local player = RivalsRuntimeBridge.AnimationPlayer
                player.Stop()
                player.AwaitingOwnership = false
                if not player.ReadEnabled() then
                    return
                end
                local humanoid = player.Humanoid
                if not humanoid or humanoid.Parent == nil then
                    return
                end
                local animator = humanoid:FindFirstChildOfClass('Animator')
                if not animator then
                    player.AnimatorWait = humanoid.ChildAdded:Connect(function(child)
                        if child:IsA('Animator') and player.Humanoid == humanoid then
                            player.Apply(true)
                        end
                    end)
                    return
                end
                local animationId = player.ResolveAnimationId()
                if not animationId then
                    return
                end
                local animation = Instance.new('Animation')
                animation.AnimationId = 'rbxassetid://' .. animationId
                local ok, track = pcall(animator.LoadAnimation, animator, animation)
                animation:Destroy()
                if not ok or not track then
                    if player.LastLoadFailure ~= animationId then
                        player.LastLoadFailure = animationId
                        if Library and type(Library.Notify) == 'function' then
                            Library:Notify({
                                Title = 'Animation Player',
                                Description = 'Animation ' .. animationId .. ' could not be loaded.',
                                Time = 3,
                            })
                        end
                    end
                    return
                end
                player.LastLoadFailure = nil
                track.Priority = Enum.AnimationPriority.Action4
                track.Looped = true
                player.Track = track
                track:Play()
                track:AdjustSpeed(player.ReadSpeed())
                player.AwaitingOwnership = awaitOwnership == true
            end

            function RivalsRuntimeBridge.AnimationPlayer.AdjustSpeed()
                local player = RivalsRuntimeBridge.AnimationPlayer
                if player.Track then
                    pcall(player.Track.AdjustSpeed, player.Track, player.ReadSpeed())
                end
            end

            function RivalsRuntimeBridge.AnimationPlayer.EnforceWindow(track)
                local length = track.Length
                if type(length) ~= 'number' or length <= 0 then
                    return
                end
                local startOption = Options and Options.P10S6S2
                local endOption = Options and Options.P10S6S3
                local startPercent = startOption and tonumber(startOption.Value) or 0
                local endPercent = endOption and tonumber(endOption.Value) or 100
                local windowStart = math.clamp(startPercent, 0, 100) / 100 * length
                local windowEnd = math.clamp(endPercent, 0, 100) / 100 * length
                if windowEnd <= windowStart then
                    return
                end
                if track.TimePosition >= windowEnd or track.TimePosition < windowStart then
                    track.TimePosition = windowStart
                end
            end

            function RivalsRuntimeBridge.AnimationPlayer.Update()
                LPH_ATTRIBUTES(VM(NONE))
                local player = RivalsRuntimeBridge.AnimationPlayer
                if not player.ReadEnabled() and not player.Track then
                    return
                end
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                if character ~= player.Character or humanoid ~= player.Humanoid then
                    player.Stop()
                    player.Character = character
                    player.Humanoid = humanoid
                    player.Apply(true)
                    return
                end
                local track = player.Track
                if not track then
                    return
                end
                if not track.IsPlaying then
                    player.Track = nil
                    pcall(track.Destroy, track)
                    player.Apply(false)
                    return
                end
                if player.AwaitingOwnership and humanoid and humanoid.RootPart then
                    player.AwaitingOwnership = false
                    player.Apply(false)
                    return
                end
                player.EnforceWindow(track)
            end

            function RivalsRuntimeBridge.AnimationPlayer.RefreshAll()
                if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                    return
                end
                RivalsRuntimeBridge.AnimationPlayer.Apply(false)
            end

            function RivalsRuntimeBridge.AnimationPlayer.Destroy()
                local player = RivalsRuntimeBridge.AnimationPlayer
                player.Stop()
                player.Character = nil
                player.Humanoid = nil
                player.AwaitingOwnership = false
                player.LastLoadFailure = nil
            end

            RivalsRuntimeBridge.MovementRecorder = {
                SavePath = 'akira/RIVALS Movement Recordings.json',
                Version = 1,
                Mode = 'Idle',
                PendingKind = nil,
                Recording = nil,
                Replay = nil,
                LastRecording = nil,
                RecordsByName = {},
                RecordsByMap = {},
                PersistenceLoaded = false,
                RefreshingOptions = false,
                InputConnections = {},
                PlayerControls = nil,
                InputLibrary = nil,
                MechanicsController = nil,
                RoundActive = nil,
                RoundToken = nil,
                RoundBindingPending = false,
                RoundBindingGeneration = 0,
                WaypointDirty = true,
                WaypointMapName = nil,
                WaypointMapModel = nil,
                WaypointAnchor = nil,
                Markers = {},
                Routes = {},
                SelectedRecording = nil,
                ActivatedRecording = nil,
            }

            function RivalsRuntimeBridge.MovementRecorder.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.MovementRecorder.ReadNumber(optionId, fallback)
                local option = Options and Options[optionId]
                return option and type(option.Value) == 'number' and option.Value or fallback
            end

            function RivalsRuntimeBridge.MovementRecorder.Notify(message)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if recorder.ReadToggle('P10S4T3') then
                    return
                end
                if Library and type(Library.Notify) == 'function' then
                    Library:Notify({Title = 'Movement Recorder', Description = message, Time = 3})
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.SetToggle(optionId, value)
                local toggle = Toggles and Toggles[optionId]
                if not toggle or toggle.Value == value or type(toggle.SetValue) ~= 'function' then
                    return
                end
                task.defer(function()
                    if Toggles and Toggles[optionId] == toggle and toggle.Value ~= value then
                        toggle:SetValue(value)
                    end
                end)
            end

            function RivalsRuntimeBridge.MovementRecorder.EncodeVector3(value)
                return {value.X, value.Y, value.Z}
            end

            function RivalsRuntimeBridge.MovementRecorder.DecodeVector3(value)
                if type(value) ~= 'table' then
                    return nil
                end
                local x, y, z = tonumber(value[1]), tonumber(value[2]), tonumber(value[3])
                if not x or not y or not z then
                    return nil
                end
                return Vector3.new(x, y, z)
            end

            function RivalsRuntimeBridge.MovementRecorder.EncodeCFrame(value)
                return {value:GetComponents()}
            end

            function RivalsRuntimeBridge.MovementRecorder.DecodeCFrame(value)
                if type(value) ~= 'table' or #value ~= 12 then
                    return nil
                end
                local components = table.create(12)
                for index = 1, 12 do
                    components[index] = tonumber(value[index])
                    if components[index] == nil then
                        return nil
                    end
                end
                return CFrame.new(table.unpack(components))
            end

            function RivalsRuntimeBridge.MovementRecorder.EncodeAction(action)
                local encoded = {kind = action.kind}
                if action.kind == 'Move' then
                    encoded.direction = RivalsRuntimeBridge.MovementRecorder.EncodeVector3(action.direction)
                elseif action.kind == 'Look' then
                    encoded.cframe = RivalsRuntimeBridge.MovementRecorder.EncodeCFrame(action.cframe)
                elseif action.kind == 'Equip' then
                    encoded.index = action.index
                elseif action.kind == 'ItemInput' then
                    encoded.inputType = action.inputType
                elseif action.kind == 'QuickAttack' then
                    encoded.attackType = action.attackType
                elseif action.kind == 'Crouch' then
                    encoded.crouching = action.crouching == true
                end
                return encoded
            end

            function RivalsRuntimeBridge.MovementRecorder.DecodeAction(action)
                if type(action) ~= 'table' or type(action.kind) ~= 'string' then
                    return nil
                end
                local decoded = {kind = action.kind}
                if action.kind == 'Move' then
                    decoded.direction = RivalsRuntimeBridge.MovementRecorder.DecodeVector3(action.direction)
                    return decoded.direction and decoded or nil
                elseif action.kind == 'Look' then
                    decoded.cframe = RivalsRuntimeBridge.MovementRecorder.DecodeCFrame(action.cframe)
                    return decoded.cframe and decoded or nil
                elseif action.kind == 'Equip' then
                    decoded.index = tonumber(action.index)
                    return decoded.index and decoded or nil
                elseif action.kind == 'ItemInput' then
                    decoded.inputType = type(action.inputType) == 'string' and action.inputType or nil
                    return decoded.inputType and decoded or nil
                elseif action.kind == 'QuickAttack' then
                    decoded.attackType = type(action.attackType) == 'string' and action.attackType or nil
                    return decoded.attackType and decoded or nil
                elseif action.kind == 'Crouch' then
                    decoded.crouching = action.crouching == true
                elseif action.kind ~= 'Jump' and action.kind ~= 'Slide' then
                    return nil
                end
                return decoded
            end

            function RivalsRuntimeBridge.MovementRecorder.EncodeRecording(recording)
                local encoded = {
                    mapName = recording.mapName,
                    startCFrame = RivalsRuntimeBridge.MovementRecorder.EncodeCFrame(recording.startCFrame),
                    displayPosition = RivalsRuntimeBridge.MovementRecorder.EncodeVector3(recording.displayPosition),
                    startEquippedIndex = recording.startEquippedIndex,
                    startEquipCooldown = recording.startEquipCooldown,
                    loadoutRequirements = {},
                    keypoints = {},
                    positions = {},
                }
                for itemName in pairs(recording.loadoutRequirements or {}) do
                    encoded.loadoutRequirements[#encoded.loadoutRequirements + 1] = itemName
                end
                table.sort(encoded.loadoutRequirements)
                for _, keypoint in ipairs(recording.keypoints or {}) do
                    encoded.keypoints[#encoded.keypoints + 1] = {
                        offset = keypoint.offset,
                        action = RivalsRuntimeBridge.MovementRecorder.EncodeAction(keypoint.action),
                    }
                end
                for _, position in ipairs(recording.positions or {}) do
                    encoded.positions[#encoded.positions + 1] = {
                        offset = position.offset,
                        position = RivalsRuntimeBridge.MovementRecorder.EncodeVector3(position.position),
                    }
                end
                return encoded
            end

            function RivalsRuntimeBridge.MovementRecorder.DecodeRecording(encoded)
                if type(encoded) ~= 'table' or type(encoded.mapName) ~= 'string' then
                    return nil
                end
                local recording = {
                    mapName = encoded.mapName,
                    startCFrame = RivalsRuntimeBridge.MovementRecorder.DecodeCFrame(encoded.startCFrame),
                    displayPosition = RivalsRuntimeBridge.MovementRecorder.DecodeVector3(encoded.displayPosition),
                    startEquippedIndex = tonumber(encoded.startEquippedIndex),
                    startEquipCooldown = tonumber(encoded.startEquipCooldown),
                    loadoutRequirements = {},
                    keypoints = {},
                    positions = {},
                }
                if not recording.startCFrame or not recording.displayPosition then
                    return nil
                end
                for _, itemName in ipairs(type(encoded.loadoutRequirements) == 'table'
                    and encoded.loadoutRequirements or {}) do
                    if type(itemName) == 'string' and itemName ~= '' then
                        recording.loadoutRequirements[itemName] = true
                    end
                end
                for _, keypoint in ipairs(type(encoded.keypoints) == 'table' and encoded.keypoints or {}) do
                    local action = RivalsRuntimeBridge.MovementRecorder.DecodeAction(keypoint.action)
                    local offset = tonumber(keypoint.offset)
                    if action and offset then
                        recording.keypoints[#recording.keypoints + 1] = {offset = offset, action = action}
                    end
                end
                for _, position in ipairs(type(encoded.positions) == 'table' and encoded.positions or {}) do
                    local value = RivalsRuntimeBridge.MovementRecorder.DecodeVector3(position.position)
                    local offset = tonumber(position.offset)
                    if value and offset then
                        recording.positions[#recording.positions + 1] = {offset = offset, position = value}
                    end
                end
                if #recording.keypoints == 0 then
                    return nil
                end
                table.sort(recording.keypoints, function(left, right) return left.offset < right.offset end)
                table.sort(recording.positions, function(left, right) return left.offset < right.offset end)
                return recording
            end

            function RivalsRuntimeBridge.MovementRecorder.ReindexRecordings()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.RecordsByMap = {}
                for name, recording in pairs(recorder.RecordsByName) do
                    recording.name = name
                    local names = recorder.RecordsByMap[recording.mapName]
                    if not names then
                        names = {}
                        recorder.RecordsByMap[recording.mapName] = names
                    end
                    names[#names + 1] = name
                end
                for _, names in pairs(recorder.RecordsByMap) do
                    table.sort(names)
                end
                recorder.WaypointDirty = true
            end

            function RivalsRuntimeBridge.MovementRecorder.LoadPersistence()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if recorder.PersistenceLoaded then
                    return
                end
                recorder.PersistenceLoaded = true
                recorder.RecordsByName = {}
                local targetSavePath = recorder.SavePath
                if type(isfile) == 'function' and not isfile(targetSavePath) and isfile('Akira/RIVALS Movement Recordings.json') then
                    targetSavePath = 'Akira/RIVALS Movement Recordings.json'
                end
                if type(isfile) == 'function' and isfile(targetSavePath) then
                    local ok, decoded = pcall(function()
                        return game:GetService('HttpService'):JSONDecode(readfile(targetSavePath))
                    end)
                    if ok and type(decoded) == 'table' and decoded.version == recorder.Version
                        and type(decoded.recordings) == 'table' then
                        for name, encoded in pairs(decoded.recordings) do
                            local recording = type(name) == 'string' and recorder.DecodeRecording(encoded) or nil
                            if recording then
                                recorder.RecordsByName[name] = recording
                            end
                        end
                    end
                end
                recorder.ReindexRecordings()
            end

            function RivalsRuntimeBridge.MovementRecorder.WritePersistence()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if type(writefile) ~= 'function' then
                    return false
                end
                local encoded = {}
                for name, recording in pairs(recorder.RecordsByName) do
                    encoded[name] = recorder.EncodeRecording(recording)
                end
                local ok = pcall(function()
                    if type(makefolder) == 'function' and type(isfolder) == 'function'
                        and not isfolder('akira') then
                        makefolder('akira')
                    end
                    writefile(recorder.SavePath, game:GetService('HttpService'):JSONEncode({
                        version = recorder.Version,
                        recordings = encoded,
                    }))
                end)
                return ok
            end

            function RivalsRuntimeBridge.MovementRecorder.GetMapNames()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.LoadPersistence()
                local maps = {}
                for mapName in pairs(recorder.RecordsByMap) do
                    maps[#maps + 1] = mapName
                end
                table.sort(maps)
                return maps
            end

            function RivalsRuntimeBridge.MovementRecorder.GetRecordingNames(mapName)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.LoadPersistence()
                    return AkiraClone(recorder.RecordsByMap[mapName] or {})
            end

            function RivalsRuntimeBridge.MovementRecorder.RefreshRecordingOptions()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if recorder.RefreshingOptions then
                    return
                end
                local mapOption = Options and Options.P10S4D1
                local recordingOption = Options and Options.P10S4D2
                if not mapOption or not recordingOption then
                    return
                end
                recorder.RefreshingOptions = true
                local maps = recorder.GetMapNames()
                local currentMap = mapOption.Value
                if type(mapOption.SetValues) == 'function' then
                    mapOption:SetValues(maps)
                end
                if type(currentMap) ~= 'string' or table.find(maps, currentMap) == nil then
                    currentMap = maps[1]
                    if type(mapOption.SetValue) == 'function' then
                        mapOption:SetValue(currentMap)
                    end
                end
                local names = recorder.GetRecordingNames(currentMap)
                local selectedName = recordingOption.Value
                if type(recordingOption.SetValues) == 'function' then
                    recordingOption:SetValues(names)
                end
                if type(selectedName) ~= 'string' or table.find(names, selectedName) == nil then
                    if type(recordingOption.SetValue) == 'function' then
                        recordingOption:SetValue(names[1])
                    end
                end
                recorder.RefreshingOptions = false
            end

            function RivalsRuntimeBridge.MovementRecorder.SaveLastRecording(name)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.LoadPersistence()
                name = type(name) == 'string' and name:match('^%s*(.-)%s*$') or ''
                if name == '' then
                    recorder.Notify('Enter a recording name first')
                    return false
                end
                if not recorder.LastRecording then
                    recorder.Notify('No recording to save')
                    return false
                end
                local previous = recorder.RecordsByName[name]
                recorder.RecordsByName[name] = recorder.LastRecording
                recorder.ReindexRecordings()
                if not recorder.WritePersistence() then
                    recorder.RecordsByName[name] = previous
                    recorder.ReindexRecordings()
                    recorder.Notify('Failed to save recording')
                    return false
                end
                recorder.LastRecording = nil
                recorder.RefreshRecordingOptions()
                recorder.Notify('Recording saved')
                return true
            end

            function RivalsRuntimeBridge.MovementRecorder.DeleteRecording(name)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.LoadPersistence()
                if type(name) ~= 'string' or name == '' or not recorder.RecordsByName[name] then
                    recorder.Notify('Select a recording to delete')
                    return false
                end
                local previous = recorder.RecordsByName[name]
                recorder.RecordsByName[name] = nil
                recorder.ReindexRecordings()
                if not recorder.WritePersistence() then
                    recorder.RecordsByName[name] = previous
                    recorder.ReindexRecordings()
                    recorder.Notify('Failed to delete recording')
                    return false
                end
                recorder.RefreshRecordingOptions()
                recorder.Notify('Recording deleted')
                return true
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveMapContext()
                local mapParser = RivalsRuntimeBridge.MapParser
                if mapParser and type(mapParser.ResolveMapContext) == 'function' then
                    return mapParser.ResolveMapContext()
                end
                return nil
            end

            function RivalsRuntimeBridge.MovementRecorder.IsRoundActive()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local fighter = ResolveLocalFighter()
                local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                if type(data) == 'table' and rawget(data, 'IsInShootingRange') == true then
                    return true
                end
                if recorder.RoundActive ~= nil then
                    return recorder.RoundActive == true
                end
                return FighterDataCache.LocalDuel.IsInDuel == true
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveDependencies()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if not recorder.PlayerControls then
                    local playerModule = LP:FindFirstChild('PlayerScripts')
                        and LP.PlayerScripts:FindFirstChild('PlayerModule')
                    if playerModule then
                        local ok, module = pcall(require, playerModule)
                        if ok and type(module) == 'table' and type(module.GetControls) == 'function' then
                            local controlsOk, controls = pcall(module.GetControls, module)
                            recorder.PlayerControls = controlsOk and controls or nil
                        end
                    end
                end
                if not recorder.InputLibrary then
                    local modules = ReplicatedStorage:FindFirstChild('Modules')
                    local inputModule = modules and modules:FindFirstChild('InputLibrary')
                    if inputModule then
                        local ok, library = pcall(require, inputModule)
                        recorder.InputLibrary = ok and type(library) == 'table' and library or nil
                    end
                end
                if not recorder.MechanicsController and IsReplicatedStateReady() then
                    local playerScripts = LP:FindFirstChild('PlayerScripts')
                    local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                    local mechanicsModule = controllers and controllers:FindFirstChild('MechanicsController')
                    if mechanicsModule then
                        local ok, controller = pcall(require, mechanicsModule)
                        recorder.MechanicsController = ok and type(controller) == 'table' and controller or nil
                    end
                end
                return recorder.PlayerControls ~= nil and recorder.InputLibrary ~= nil
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveEquippedItem(fighter)
                if type(fighter) ~= 'table' then
                    return nil
                end
                return rawget(fighter, 'EquippedItem')
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveItemIndex(item, fighter)
                local data = type(item) == 'table' and rawget(item, 'Data') or nil
                local index = type(data) == 'table' and tonumber(rawget(data, 'ItemIndex')) or nil
                if index then
                    return index
                end
                for slotIndex, candidate in ipairs(type(fighter) == 'table' and rawget(fighter, 'Items') or {}) do
                    if candidate == item then
                        return slotIndex
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveItemName(item)
                if type(item) ~= 'table' then
                    return nil
                end
                local name = rawget(item, 'Name')
                if type(name) == 'string' and name ~= '' then
                    return name
                end
                local data = rawget(item, 'Data')
                name = type(data) == 'table' and rawget(data, 'Name') or nil
                return type(name) == 'string' and name ~= '' and name or nil
            end

            function RivalsRuntimeBridge.MovementRecorder.GetOffset()
                local active = RivalsRuntimeBridge.MovementRecorder.Recording
                return active and math.max(0, os.clock() - active.StartTime) or 0
            end

            function RivalsRuntimeBridge.MovementRecorder.RecordAction(action)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local active = recorder.Recording
                if not active then
                    return
                end
                active.Data.keypoints[#active.Data.keypoints + 1] = {
                    offset = recorder.GetOffset(),
                    action = action,
                }
            end

            function RivalsRuntimeBridge.MovementRecorder.DiscardUnusedStartItem()
                local active = RivalsRuntimeBridge.MovementRecorder.Recording
                if not active or active.StartItemUsed or active.Data.startEquippedIndex == nil then
                    return
                end
                active.Data.startEquippedIndex = nil
                active.Data.startEquipCooldown = nil
            end

            function RivalsRuntimeBridge.MovementRecorder.RecordItemInput(inputType)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local active = recorder.Recording
                if not active then
                    return
                end
                local fighter = ResolveLocalFighter()
                local item = recorder.ResolveEquippedItem(fighter)
                local itemName = recorder.ResolveItemName(item)
                if itemName then
                    active.Data.loadoutRequirements[itemName] = true
                end
                if recorder.ResolveItemIndex(item, fighter) == active.StartItemIndex then
                    active.StartItemUsed = true
                end
                recorder.RecordAction({kind = 'ItemInput', inputType = inputType})
            end

            function RivalsRuntimeBridge.MovementRecorder.InputMatches(input, inputName)
                local library = RivalsRuntimeBridge.MovementRecorder.InputLibrary
                if not library or type(library.InputIs) ~= 'function' then
                    return false
                end
                local ok, matches = pcall(library.InputIs, library, input, inputName)
                return ok and matches == true
            end

            function RivalsRuntimeBridge.MovementRecorder.HandleInput(input, gameProcessed, began)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if recorder.Mode ~= 'Recording' or gameProcessed then
                    return
                end
                if began and recorder.InputMatches(input, 'Jump') then
                    recorder.RecordAction({kind = 'Jump'})
                    return
                end
                if began and recorder.InputMatches(input, 'QuickMelee') then
                    recorder.RecordAction({kind = 'QuickAttack', attackType = 'Melee'})
                    return
                end
                if began and recorder.InputMatches(input, 'QuickUtility') then
                    recorder.RecordAction({kind = 'QuickAttack', attackType = 'Utility'})
                    return
                end
                local library = recorder.InputLibrary
                for _, inputName in ipairs(type(library) == 'table' and library.ItemInputs or {}) do
                    local definition = type(library.Inputs) == 'table' and library.Inputs[inputName] or nil
                    if definition and recorder.InputMatches(input, inputName) then
                        local inputType = began and definition.StartName or definition.FinishName
                        if type(inputType) == 'string' then
                            recorder.RecordItemInput(inputType)
                        end
                        return
                    end
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.DisconnectRecordingInputs()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                for _, connection in ipairs(recorder.InputConnections) do
                    connection:Disconnect()
                end
                recorder.InputConnections = {}
            end

            function RivalsRuntimeBridge.MovementRecorder.ConnectRecordingInputs()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.DisconnectRecordingInputs()
                recorder.InputConnections = {
                    UserInputService.InputBegan:Connect(GuardRivalsCallback(
                        'MovementRecorder_InputBegan', function(input, gameProcessed)
                            recorder.HandleInput(input, gameProcessed, true)
                        end)),
                    UserInputService.InputEnded:Connect(GuardRivalsCallback(
                        'MovementRecorder_InputEnded', function(input, gameProcessed)
                            recorder.HandleInput(input, gameProcessed, false)
                        end)),
                }
            end

            function RivalsRuntimeBridge.MovementRecorder.SampleRecording()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local active = recorder.Recording
                if not active then
                    return
                end
                local controls = recorder.PlayerControls
                local moveVector = Vector3.zero
                if controls and type(controls.GetMoveVector) == 'function' then
                    local ok, value = pcall(controls.GetMoveVector, controls)
                    if ok and typeof(value) == 'Vector3' then
                        moveVector = value
                    end
                end
                if moveVector ~= active.LastMoveVector then
                    active.LastMoveVector = moveVector
                    recorder.RecordAction({kind = 'Move', direction = moveVector})
                end

                local camera = Workspace.CurrentCamera
                if camera then
                    local pitch, yaw = camera.CFrame:ToOrientation()
                    local cameraRotation = Vector2.new(pitch, yaw)
                    if (cameraRotation - active.LastCameraRotation).Magnitude > 0.0001 then
                        active.LastCameraRotation = cameraRotation
                        recorder.RecordAction({
                            kind = 'Look',
                            cframe = active.AnchorInverse * CFrame.fromOrientation(pitch, yaw, 0),
                        })
                    end
                end

                local fighter = ResolveLocalFighter()
                local item = recorder.ResolveEquippedItem(fighter)
                local equippedIndex = recorder.ResolveItemIndex(item, fighter)
                if equippedIndex ~= active.LastEquippedIndex then
                    active.LastEquippedIndex = equippedIndex
                    recorder.DiscardUnusedStartItem()
                    if equippedIndex ~= nil then
                        recorder.RecordAction({kind = 'Equip', index = equippedIndex})
                    end
                end

                local mechanics = recorder.MechanicsController
                local crouching = mechanics and rawget(mechanics, 'IsCrouching') == true or false
                if crouching ~= active.LastCrouching then
                    active.LastCrouching = crouching
                    recorder.RecordAction({kind = 'Crouch', crouching = crouching})
                end
                local sliding = mechanics and rawget(mechanics, 'IsSliding') == true or false
                if sliding ~= active.LastSliding then
                    active.LastSliding = sliding
                    if sliding then
                        recorder.RecordAction({kind = 'Slide'})
                    end
                end

                local now = os.clock()
                if now - active.LastPositionSampleTime >= 0.1 then
                    active.LastPositionSampleTime = now
                    active.Data.positions[#active.Data.positions + 1] = {
                        offset = recorder.GetOffset(),
                        position = active.AnchorInverse * active.RootPart.Position,
                    }
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.StartRecording()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local context = recorder.ResolveMapContext()
                if not context or not recorder.ResolveDependencies() then
                    recorder.Notify('You need to be alive and in a match')
                    return false
                end
                if recorder.Mode ~= 'Idle' then
                    recorder.Notify(recorder.Mode == 'Recording' and 'Already recording' or "Can't record while replaying")
                    return false
                end
                local fighter = ResolveLocalFighter()
                local item = recorder.ResolveEquippedItem(fighter)
                local equippedIndex = recorder.ResolveItemIndex(item, fighter)
                local equipCooldown = type(item) == 'table' and tonumber(rawget(item, '_equip_cooldown')) or nil
                if equipCooldown then
                    equipCooldown = math.max(0, equipCooldown - tick())
                end
                local camera = Workspace.CurrentCamera
                local pitch, yaw = camera and camera.CFrame:ToOrientation() or 0, 0
                if camera then
                    pitch, yaw = camera.CFrame:ToOrientation()
                end
                local anchorInverse = context.MapAnchor:Inverse()
                local displayPosition = context.RootPart.Position
                if camera then
                    local center = camera.ViewportSize / 2
                    local ray = camera:ViewportPointToRay(center.X, center.Y)
                    displayPosition = ray.Origin + ray.Direction * 100
                end
                recorder.Recording = {
                    Data = {
                        mapName = context.MapName,
                        displayPosition = anchorInverse * displayPosition,
                        startCFrame = anchorInverse * context.RootPart.CFrame,
                        startEquippedIndex = equippedIndex,
                        startEquipCooldown = equipCooldown,
                        keypoints = {{
                            offset = 0,
                            action = {
                                kind = 'Look',
                                cframe = anchorInverse * CFrame.fromOrientation(pitch, yaw, 0),
                            },
                        }},
                        loadoutRequirements = {},
                        positions = {},
                    },
                    AnchorInverse = anchorInverse,
                    RootPart = context.RootPart,
                    Character = context.Character,
                    StartTime = os.clock(),
                    StartItemIndex = equippedIndex,
                    StartItemUsed = false,
                    LastMoveVector = Vector3.zero,
                    LastCameraRotation = Vector2.new(pitch, yaw),
                    LastEquippedIndex = equippedIndex,
                    LastCrouching = false,
                    LastSliding = false,
                    LastPositionSampleTime = 0,
                }
                recorder.Mode = 'Recording'
                recorder.ConnectRecordingInputs()
                recorder.SampleRecording()
                recorder.Notify('Now recording')
                return true
            end

            function RivalsRuntimeBridge.MovementRecorder.StopRecording(saveLast, notify)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if recorder.Mode ~= 'Recording' or not recorder.Recording then
                    return
                end
                recorder.SampleRecording()
                recorder.DiscardUnusedStartItem()
                if saveLast then
                    recorder.LastRecording = recorder.Recording.Data
                end
                recorder.DisconnectRecordingInputs()
                recorder.Recording = nil
                recorder.Mode = 'Idle'
                if notify then
                    recorder.Notify('Recording stopped')
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveStartLook(mapAnchor, keypoints)
                for _, keypoint in ipairs(keypoints or {}) do
                    local action = keypoint.action
                    if action and action.kind == 'Look' then
                        local pitch, yaw = (mapAnchor * action.cframe):ToOrientation()
                        return Vector2.new(pitch, yaw)
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.MovementRecorder.LoadoutFulfilled(recording)
                local owned = {}
                local fighter = ResolveLocalFighter()
                for _, item in ipairs(type(fighter) == 'table' and rawget(fighter, 'Items') or {}) do
                    local itemName = RivalsRuntimeBridge.MovementRecorder.ResolveItemName(item)
                    if itemName then
                        owned[itemName] = true
                    end
                end
                for itemName in pairs(recording.loadoutRequirements or {}) do
                    if not owned[itemName] then
                        return false
                    end
                end
                return true
            end

            function RivalsRuntimeBridge.MovementRecorder.StartReplay(recording)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local context = recorder.ResolveMapContext()
                if not context or not recorder.ResolveDependencies() then
                    recorder.Notify('You need to be alive and in a match')
                    return false
                end
                if recorder.Mode ~= 'Idle' then
                    recorder.Notify(recorder.Mode == 'Recording' and "Can't replay while recording" or 'Already replaying')
                    return false
                end
                if not recording or recording.mapName ~= context.MapName then
                    recorder.Notify('Stand near a recording marker first')
                    return false
                end
                if not recorder.LoadoutFulfilled(recording) then
                    recorder.Notify('Your loadout does not meet this recording')
                    return false
                end
                local fighter = ResolveLocalFighter()
                if recording.startEquippedIndex ~= nil and fighter and type(fighter.EquipItem) == 'function' then
                    task.spawn(function()
                        pcall(fighter.EquipItem, fighter, recording.startEquippedIndex)
                    end)
                end
                local controls = recorder.PlayerControls
                local activeController = type(controls) == 'table'
                    and rawget(controls, 'activeController') or nil
                local controlsWereEnabled = type(activeController) ~= 'table' or rawget(activeController, 'enabled') ~= false
                if controls and type(controls.Disable) == 'function' then
                    pcall(controls.Disable, controls)
                end
                recorder.Replay = {
                    Data = recording,
                    Character = context.Character,
                    Humanoid = context.Humanoid,
                    RootPart = context.RootPart,
                    Fighter = fighter,
                    MapAnchor = context.MapAnchor,
                    State = 'Aligning',
                    AlignElapsed = 0,
                    StuckTime = 0,
                    BestDistance = math.huge,
                    LookAligned = false,
                    StartLook = recorder.ResolveStartLook(context.MapAnchor, recording.keypoints),
                    TargetLook = nil,
                    MoveVector = Vector3.zero,
                    Offset = 0,
                    KeypointIndex = 1,
                    PositionIndex = 1,
                    Controls = controls,
                    ControlsWereEnabled = controlsWereEnabled,
                }
                recorder.Mode = 'Aligning'
                recorder.ActivatedRecording = recording
                recorder.SelectedRecording = recording
                RivalsRuntimeBridge.ResetFlickbot()
                recorder.Notify('Now replaying')
                return true
            end

            function RivalsRuntimeBridge.MovementRecorder.StopReplay(reason, notify)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                if replay.Humanoid and replay.Humanoid.Parent then
                    pcall(replay.Humanoid.Move, replay.Humanoid, Vector3.zero, false)
                end
                if replay.ControlsWereEnabled and replay.Controls and type(replay.Controls.Enable) == 'function' then
                    pcall(replay.Controls.Enable, replay.Controls)
                end
                local mechanics = recorder.MechanicsController
                if mechanics and type(mechanics.SetCrouching) == 'function' then
                    pcall(mechanics.SetCrouching, mechanics, false)
                end
                recorder.Replay = nil
                recorder.Mode = 'Idle'
                recorder.ActivatedRecording = nil
                if notify then
                    if reason == 'Diverged' then
                        recorder.Notify('Replay stopped (off course)')
                    elseif reason == 'Completed' then
                        recorder.Notify('Finished replaying')
                    else
                        recorder.Notify('Stopped replaying')
                    end
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.IsStartItemReady()
                local replay = RivalsRuntimeBridge.MovementRecorder.Replay
                if not replay or replay.Data.startEquippedIndex == nil then
                    return true
                end
                local fighter = replay.Fighter
                local item = RivalsRuntimeBridge.MovementRecorder.ResolveEquippedItem(fighter)
                if RivalsRuntimeBridge.MovementRecorder.ResolveItemIndex(item, fighter)
                    ~= replay.Data.startEquippedIndex then
                    return false
                end
                local cooldown = type(item) == 'table' and rawget(item, '_equip_cooldown') or nil
                return type(cooldown) ~= 'number' or cooldown <= tick()
            end

            function RivalsRuntimeBridge.MovementRecorder.StepAlign(deltaTime)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                if not recorder.IsRoundActive() then
                    replay.Humanoid:Move(Vector3.zero, false)
                    return
                end
                replay.AlignElapsed = replay.AlignElapsed + deltaTime
                local targetPosition = (replay.MapAnchor * replay.Data.startCFrame).Position
                local difference = targetPosition - replay.RootPart.Position
                local planar = Vector3.new(difference.X, 0, difference.Z)
                local distance = planar.Magnitude
                local snapped = distance <= recorder.ReadNumber('P10S4S5', 0.2)
                if snapped then
                    replay.Humanoid:Move(Vector3.zero, false)
                else
                    replay.Humanoid:Move(planar.Unit, false)
                end
                if distance < replay.BestDistance - 0.1 then
                    replay.BestDistance = distance
                    replay.StuckTime = 0
                else
                    replay.StuckTime = replay.StuckTime + deltaTime
                end
                local aligned = (snapped and (replay.StartLook == nil or replay.LookAligned))
                    or replay.StuckTime >= 1
                if not aligned then
                    return
                end
                replay.Humanoid:Move(Vector3.zero, false)
                if not recorder.IsStartItemReady() and replay.AlignElapsed < 3 then
                    return
                end
                replay.State = 'Playing'
                recorder.Mode = 'Playing'
            end

            function RivalsRuntimeBridge.MovementRecorder.HasDiverged(offset)
                local replay = RivalsRuntimeBridge.MovementRecorder.Replay
                local positions = replay and replay.Data.positions or nil
                if not positions or #positions == 0 then
                    return false
                end
                while replay.PositionIndex < #positions
                    and positions[replay.PositionIndex + 1].offset <= offset do
                    replay.PositionIndex = replay.PositionIndex + 1
                end
                local first = positions[replay.PositionIndex]
                local second = positions[replay.PositionIndex + 1]
                local expected = first.position
                if second then
                    local span = second.offset - first.offset
                    local alpha = span > 0 and math.clamp((offset - first.offset) / span, 0, 1) or 0
                    expected = first.position:Lerp(second.position, alpha)
                end
                return (replay.MapAnchor:PointToWorldSpace(expected) - replay.RootPart.Position).Magnitude > 15
            end

            function RivalsRuntimeBridge.MovementRecorder.ApplyReplayAction(action)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                if action.kind == 'Move' then
                    replay.MoveVector = action.direction
                elseif action.kind == 'Look' then
                    local pitch, yaw = (replay.MapAnchor * action.cframe):ToOrientation()
                    replay.TargetLook = Vector2.new(pitch, yaw)
                elseif action.kind == 'Equip' and replay.Fighter and type(replay.Fighter.EquipItem) == 'function' then
                    task.spawn(function() pcall(replay.Fighter.EquipItem, replay.Fighter, action.index) end)
                elseif action.kind == 'ItemInput' and replay.Fighter and type(replay.Fighter.Input) == 'function' then
                    task.spawn(function() pcall(replay.Fighter.Input, replay.Fighter, action.inputType) end)
                elseif action.kind == 'QuickAttack' and replay.Fighter
                    and type(replay.Fighter.QuickAttackDown) == 'function' then
                    task.spawn(function()
                        pcall(replay.Fighter.QuickAttackDown, replay.Fighter, action.attackType)
                        task.wait(0.05)
                        if replay.Fighter and type(replay.Fighter.QuickAttackUp) == 'function' then
                            pcall(replay.Fighter.QuickAttackUp, replay.Fighter, action.attackType)
                        end
                    end)
                elseif action.kind == 'Jump' then
                    local mechanics = recorder.MechanicsController
                    if mechanics then
                        if rawget(mechanics, 'IsSliding') == true and type(mechanics.HighJump) == 'function' then
                            pcall(mechanics.HighJump, mechanics)
                        else
                            if type(mechanics.DoubleJumpRequest) == 'function' then
                                pcall(mechanics.DoubleJumpRequest, mechanics)
                            end
                            if type(mechanics.JumpRequest) == 'function' then
                                pcall(mechanics.JumpRequest, mechanics)
                            end
                        end
                    end
                elseif action.kind == 'Crouch' then
                    local mechanics = recorder.MechanicsController
                    if mechanics and type(mechanics.SetCrouching) == 'function' then
                        pcall(mechanics.SetCrouching, mechanics, action.crouching)
                    end
                elseif action.kind == 'Slide' then
                    local mechanics = recorder.MechanicsController
                    if mechanics and type(mechanics.Slide) == 'function' then
                        task.spawn(function() pcall(mechanics.Slide, mechanics) end)
                    end
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.StepPlaying(deltaTime)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local replay = recorder.Replay
                if not replay then
                    return
                end
                replay.Offset = replay.Offset + deltaTime
                if recorder.HasDiverged(replay.Offset) then
                    recorder.StopReplay('Diverged', true)
                    recorder.SetToggle('P10S4T5', false)
                    return
                end
                local keypoints = replay.Data.keypoints
                while replay.KeypointIndex <= #keypoints do
                    local keypoint = keypoints[replay.KeypointIndex]
                    if replay.Offset < keypoint.offset then
                        break
                    end
                    recorder.ApplyReplayAction(keypoint.action)
                    replay.KeypointIndex = replay.KeypointIndex + 1
                end
                replay.Humanoid:Move(replay.MoveVector, true)
                if replay.KeypointIndex > #keypoints then
                    recorder.StopReplay('Completed', true)
                    recorder.SetToggle('P10S4T5', false)
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.WrapAngle(value)
                return (value + math.pi) % (2 * math.pi) - math.pi
            end

            function RivalsRuntimeBridge.MovementRecorder.SmoothingAlpha(deltaTime)
                local tau = RivalsRuntimeBridge.MovementRecorder.ReadNumber('P10S4S4', 35) / 100 * 0.3
                return tau <= 0 and 1 or 1 - math.exp(-deltaTime / tau)
            end

            function RivalsRuntimeBridge.MovementRecorder.ReadCameraRotation()
                local camera = Workspace.CurrentCamera
                if not camera then
                    return nil
                end
                local pitch, yaw = camera.CFrame:ToOrientation()
                return Vector2.new(pitch, yaw)
            end

            function RivalsRuntimeBridge.MovementRecorder.WriteCameraRotation(rotation)
                local camera = Workspace.CurrentCamera
                if camera and rotation then
                    camera.CFrame = CFrame.new(camera.CFrame.Position)
                        * CFrame.fromOrientation(rotation.X, rotation.Y, 0)
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.UpdateReplayCamera(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local recorder = RivalsRuntimeBridge.MovementRecorder
                local replay = recorder.Replay
                local current = replay and recorder.ReadCameraRotation() or nil
                if not replay or not current then
                    return
                end
                if replay.State == 'Aligning' and replay.StartLook then
                    local difference = Vector2.new(
                        replay.StartLook.X - current.X,
                        recorder.WrapAngle(replay.StartLook.Y - current.Y)
                    )
                    local magnitude = difference.Magnitude
                    if magnitude <= math.rad(0.1) then
                        current = replay.StartLook
                        replay.LookAligned = true
                    else
                        local step = math.min(
                            magnitude * recorder.SmoothingAlpha(deltaTime),
                            math.rad(recorder.ReadNumber('P10S4S3', 180)) * deltaTime
                        )
                        current = current + difference.Unit * step
                        replay.LookAligned = false
                    end
                    recorder.WriteCameraRotation(current)
                elseif replay.State == 'Playing' and replay.TargetLook then
                    local alpha = recorder.SmoothingAlpha(deltaTime)
                    recorder.WriteCameraRotation(Vector2.new(
                        current.X + (replay.TargetLook.X - current.X) * alpha,
                        current.Y + recorder.WrapAngle(replay.TargetLook.Y - current.Y) * alpha
                    ))
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.DestroyWaypoints()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                for _, marker in ipairs(recorder.Markers) do
                    pcall(function() marker.Gui:Destroy() end)
                    pcall(function() marker.Attachment:Destroy() end)
                end
                for _, route in ipairs(recorder.Routes) do
                    pcall(function() route.Gui:Destroy() end)
                    pcall(function() route.Attachment:Destroy() end)
                end
                recorder.Markers = {}
                recorder.Routes = {}
                recorder.SelectedRecording = nil
                recorder.WaypointMapName = nil
                recorder.WaypointMapModel = nil
                recorder.WaypointAnchor = nil
            end

            function RivalsRuntimeBridge.MovementRecorder.ResolveGuiParent()
                if type(gethui) == 'function' then
                    local ok, parent = pcall(gethui)
                    if ok and typeof(parent) == 'Instance' then
                        return parent
                    end
                end
                return game:GetService('CoreGui')
            end

            function RivalsRuntimeBridge.MovementRecorder.CreateWaypointGui(name, position, isRoute)
                local attachment = Instance.new('Attachment')
                attachment.Name = isRoute and 'AkiraMovementRoute' or 'AkiraMovementMarker'
                attachment.WorldPosition = position
                attachment.Parent = Workspace.Terrain
                local gui = Instance.new('BillboardGui')
                gui.Name = attachment.Name
                gui.Adornee = attachment
                gui.AlwaysOnTop = true
                gui.LightInfluence = 0
                gui.MaxDistance = math.huge
                gui.Size = UDim2.fromOffset(isRoute and math.max(90, #name * 8 + 24) or 110, 26)
                gui.Enabled = false
                local label = Instance.new('TextLabel')
                label.Name = 'Label'
                label.BackgroundColor3 = Color3.fromRGB(18, 20, 26)
                label.BackgroundTransparency = 0.2
                label.BorderSizePixel = 0
                label.Size = UDim2.fromScale(1, 1)
                label.Font = Enum.Font.GothamSemibold
                label.TextSize = 14
                label.TextColor3 = Color3.new(1, 1, 1)
                label.Text = name
                label.Parent = gui
                local corner = Instance.new('UICorner')
                corner.CornerRadius = UDim.new(0, 6)
                corner.Parent = label
                gui.Parent = RivalsRuntimeBridge.MovementRecorder.ResolveGuiParent()
                return {Attachment = attachment, Gui = gui, Label = label, Position = position}
            end

            function RivalsRuntimeBridge.MovementRecorder.RebuildWaypoints(context)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.DestroyWaypoints()
                recorder.WaypointDirty = false
                recorder.WaypointMapName = context.MapName
                recorder.WaypointMapModel = context.MapModel
                recorder.WaypointAnchor = context.MapAnchor
                local grouped = {}
                for _, name in ipairs(recorder.RecordsByMap[context.MapName] or {}) do
                    local recording = recorder.RecordsByName[name]
                    if recording then
                        local position = recording.startCFrame.Position
                        local key = math.floor(position.X / 8) .. ','
                            .. math.floor(position.Y / 8) .. ',' .. math.floor(position.Z / 8)
                        local group = grouped[key]
                        if not group then
                            group = {Recordings = {}, Position = Vector3.zero}
                            grouped[key] = group
                        end
                        group.Recordings[#group.Recordings + 1] = recording
                        group.Position = group.Position + position
                    end
                end
                for _, group in pairs(grouped) do
                    local worldPosition = context.MapAnchor:PointToWorldSpace(
                        group.Position / #group.Recordings)
                    local text = #group.Recordings == 1 and '1 recording'
                        or tostring(#group.Recordings) .. ' recordings'
                    local marker = recorder.CreateWaypointGui(text, worldPosition, false)
                    marker.Recordings = group.Recordings
                    recorder.Markers[#recorder.Markers + 1] = marker
                    for _, recording in ipairs(group.Recordings) do
                        local route = recorder.CreateWaypointGui(
                            recording.name,
                            context.MapAnchor:PointToWorldSpace(recording.displayPosition),
                            true
                        )
                        route.Recording = recording
                        route.Marker = marker
                        recorder.Routes[#recorder.Routes + 1] = route
                    end
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.UpdateWaypoints()
                LPH_ATTRIBUTES(VM(NONE))
                local recorder = RivalsRuntimeBridge.MovementRecorder
                for _, marker in ipairs(recorder.Markers) do marker.Gui.Enabled = false end
                for _, route in ipairs(recorder.Routes) do route.Gui.Enabled = false end
                if not recorder.ReadToggle('P10S4T1') then
                    recorder.SelectedRecording = nil
                    return
                end
                local context = recorder.ResolveMapContext()
                if not context then
                    recorder.SelectedRecording = nil
                    return
                end
                if recorder.WaypointDirty or recorder.WaypointMapName ~= context.MapName
                    or recorder.WaypointMapModel ~= context.MapModel
                    or recorder.WaypointAnchor ~= context.MapAnchor then
                    recorder.RebuildWaypoints(context)
                end
                local hideUi = recorder.ReadToggle('P10S4T2')
                if recorder.ActivatedRecording then
                    recorder.SelectedRecording = recorder.ActivatedRecording
                    if not hideUi then
                        for _, route in ipairs(recorder.Routes) do
                            if route.Recording == recorder.ActivatedRecording then
                                route.Label.TextColor3 = Color3.new(0, 1, 0)
                                route.Gui.Enabled = true
                                break
                            end
                        end
                    end
                    return
                end
                local nearest, nearestDistance = nil, math.huge
                for _, marker in ipairs(recorder.Markers) do
                    local distance = (marker.Position - context.RootPart.Position).Magnitude
                    if distance < recorder.ReadNumber('P10S4S1', 3) and distance < nearestDistance then
                        nearest, nearestDistance = marker, distance
                    end
                end
                if nearest then
                    local camera = Workspace.CurrentCamera
                    local bestDistance = math.huge
                    recorder.SelectedRecording = nil
                    for _, route in ipairs(recorder.Routes) do
                        if route.Marker == nearest then
                            route.Fulfillable = recorder.LoadoutFulfilled(route.Recording)
                            local point, visible = camera and camera:WorldToViewportPoint(route.Position) or nil, false
                            if point then visible = point.Z >= 0 end
                            if route.Fulfillable and visible then
                                local screenDistance = (Vector2.new(point.X, point.Y) - camera.ViewportSize / 2).Magnitude
                                if screenDistance < bestDistance then
                                    bestDistance = screenDistance
                                    recorder.SelectedRecording = route.Recording
                                end
                            end
                        end
                    end
                    for _, route in ipairs(recorder.Routes) do
                        if route.Marker == nearest then
                            route.Label.TextColor3 = not route.Fulfillable and Color3.new(1, 0, 0)
                                or route.Recording == recorder.SelectedRecording and Color3.new(1, 1, 0)
                                or Color3.new(1, 1, 1)
                            route.Gui.Enabled = not hideUi
                        end
                    end
                    return
                end
                recorder.SelectedRecording = nil
                if not hideUi then
                    local renderDistance = recorder.ReadNumber('P10S4S2', 50)
                    for _, marker in ipairs(recorder.Markers) do
                        local distance = (marker.Position - context.RootPart.Position).Magnitude
                        if distance < renderDistance then
                            marker.Label.Text = string.format('%s  %.0fm',
                                #marker.Recordings == 1 and '1 recording'
                                    or tostring(#marker.Recordings) .. ' recordings',
                                distance)
                            marker.Gui.Enabled = true
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.Begin(kind)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if not recorder.ReadToggle('P10S4T1') then
                    recorder.SetToggle(kind == 'Record' and 'P10S4T4' or 'P10S4T5', false)
                    return false
                end
                if recorder.IsRoundActive() then
                    return kind == 'Record' and recorder.StartRecording()
                        or recorder.StartReplay(recorder.SelectedRecording)
                end
                if not recorder.ResolveMapContext() then
                    recorder.Notify('You need to be in a match')
                    recorder.SetToggle(kind == 'Record' and 'P10S4T4' or 'P10S4T5', false)
                    return false
                end
                recorder.PendingKind = kind
                recorder.Notify(kind .. ' will start when the round begins')
                return true
            end

            function RivalsRuntimeBridge.MovementRecorder.OnRecordToggled(value)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if value then
                    if recorder.Mode ~= 'Idle' or recorder.PendingKind then
                        recorder.Notify((recorder.Mode == 'Playing' or recorder.Mode == 'Aligning')
                            and "Can't record while replaying" or 'Already recording')
                        recorder.SetToggle('P10S4T4', false)
                        return
                    end
                    if not recorder.Begin('Record') then
                        recorder.SetToggle('P10S4T4', false)
                    end
                else
                    if recorder.PendingKind == 'Record' then recorder.PendingKind = nil end
                    recorder.StopRecording(true, true)
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.OnReplayToggled(value)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if value then
                    if recorder.Mode ~= 'Idle' or recorder.PendingKind then
                        recorder.Notify(recorder.Mode == 'Recording'
                            and "Can't replay while recording" or 'Already replaying')
                        recorder.SetToggle('P10S4T5', false)
                        return
                    end
                    if not recorder.SelectedRecording then
                        recorder.Notify('Stand near a recording marker first')
                        recorder.SetToggle('P10S4T5', false)
                        return
                    end
                    if not recorder.Begin('Replay') then
                        recorder.SetToggle('P10S4T5', false)
                    end
                else
                    if recorder.PendingKind == 'Replay' then recorder.PendingKind = nil end
                    recorder.StopReplay('Stopped', true)
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.OnEnabledToggled(value)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.LoadPersistence()
                recorder.WaypointDirty = true
                if value then
                    return
                end
                recorder.PendingKind = nil
                recorder.StopRecording(false, false)
                recorder.StopReplay('Stopped', false)
                recorder.SetToggle('P10S4T4', false)
                recorder.SetToggle('P10S4T5', false)
                recorder.DestroyWaypoints()
            end

            function RivalsRuntimeBridge.MovementRecorder.HandleReplicate(_, objectId, enumToken, ...)
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if enumToken ~= recorder.RoundToken then
                    return
                end
                local fighter = ResolveLocalFighter()
                local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                if type(data) == 'table' and rawget(data, 'ObjectID') ~= objectId then
                    return
                end
                local status = ...
                recorder.RoundActive = status == 'RoundStarted'
            end

            function RivalsRuntimeBridge.MovementRecorder.BindRoundSignal()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if recorder.RoundBindingPending or not Connections then
                    return
                end
                recorder.RoundBindingPending = true
                recorder.RoundBindingGeneration = recorder.RoundBindingGeneration + 1
                local generation = recorder.RoundBindingGeneration
                BeginReplicatedStateBoot()
                task.spawn(GuardRivalsCallback('MovementRecorder_BindRound', function()
                    local deadline = tick() + 30
                    while generation == recorder.RoundBindingGeneration and not ReplicatedStateReady
                        and tick() < deadline do
                        task.wait(0.1)
                    end
                    local enumLibrary = ResolveEnumLibrary()
                    local tokenOk, token = false, nil
                    if enumLibrary and enumLibrary._enum_builder_complete == true
                        and type(enumLibrary.ToEnum) == 'function' then
                        tokenOk, token = pcall(enumLibrary.ToEnum, enumLibrary, 'Status')
                    end
                    local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                    local replication = remotes and remotes:FindFirstChild('Replication')
                    local fighter = replication and replication:FindFirstChild('Fighter')
                    local replicate = fighter and fighter:FindFirstChild('Replicate')
                    if generation == recorder.RoundBindingGeneration and tokenOk and type(token) == 'string'
                        and replicate and replicate:IsA('RemoteEvent') then
                        recorder.RoundToken = token
                        Connections:disconnect({'MovementRecorder_RoundReplicate'})
                        Connections:register('MovementRecorder_RoundReplicate', replicate.OnClientEvent:Connect(
                            GuardRivalsCallback('MovementRecorder_RoundReplicate', recorder.HandleReplicate)))
                    end
                    recorder.RoundBindingPending = false
                end))
            end

            function RivalsRuntimeBridge.MovementRecorder.Update(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if not recorder.ReadToggle('P10S4T1') then
                    return
                end
                recorder.LoadPersistence()
                local context = recorder.ResolveMapContext()
                local activeCharacter = recorder.Recording and recorder.Recording.Character
                    or recorder.Replay and recorder.Replay.Character or nil
                if activeCharacter and (not context or context.Character ~= activeCharacter) then
                    recorder.StopRecording(false, false)
                    recorder.StopReplay('Stopped', false)
                    recorder.SetToggle('P10S4T4', false)
                    recorder.SetToggle('P10S4T5', false)
                    return
                end
                if recorder.PendingKind and recorder.IsRoundActive() then
                    local kind = recorder.PendingKind
                    recorder.PendingKind = nil
                    local started = kind == 'Record' and recorder.StartRecording()
                        or recorder.StartReplay(recorder.SelectedRecording)
                    if not started then
                        recorder.SetToggle(kind == 'Record' and 'P10S4T4' or 'P10S4T5', false)
                    end
                end
                if recorder.Mode == 'Recording' then
                    recorder.SampleRecording()
                elseif recorder.Mode == 'Aligning' then
                    recorder.StepAlign(math.clamp(tonumber(deltaTime) or 0, 0, 0.1))
                elseif recorder.Mode == 'Playing' then
                    recorder.StepPlaying(math.clamp(tonumber(deltaTime) or 0, 0, 0.1))
                end
            end

            function RivalsRuntimeBridge.MovementRecorder.UpdateRender(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local recorder = RivalsRuntimeBridge.MovementRecorder
                if not recorder.ReadToggle('P10S4T1') then
                    return
                end
                recorder.UpdateReplayCamera(math.clamp(tonumber(deltaTime) or 0, 0, 0.1))
                recorder.UpdateWaypoints()
            end

            function RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                return recorder.Replay ~= nil
                    and (recorder.Mode == 'Aligning' or recorder.Mode == 'Playing')
            end

            function RivalsRuntimeBridge.MovementRecorder.Destroy()
                local recorder = RivalsRuntimeBridge.MovementRecorder
                recorder.RoundBindingGeneration = recorder.RoundBindingGeneration + 1
                recorder.RoundBindingPending = false
                if Connections then
                    Connections:disconnect({'MovementRecorder_RoundReplicate'})
                end
                recorder.PendingKind = nil
                recorder.StopRecording(false, false)
                recorder.StopReplay('Stopped', false)
                recorder.DisconnectRecordingInputs()
                recorder.DestroyWaypoints()
                recorder.RoundActive = nil
                recorder.RoundToken = nil
                recorder.PlayerControls = nil
                recorder.InputLibrary = nil
                recorder.MechanicsController = nil
                recorder.Mode = 'Idle'
            end

