                local isMelee = MeleeFastFire.Enabled and IsMeleeFastFireItem(item)
                local floor = isMelee and MeleeFastFire.IntervalSec or 0.05
                local lastAt = isMelee and MeleeFastFire.LastShotAt or AimbotTriggerbotLastShotAt
                if (now - lastAt) < floor then
                    return false
