            function RivalsRuntimeBridge.FlickbotNormal(rng, mean, standardDeviation)
                local first = math.max(rng:NextNumber(), 1e-15)
                local second = rng:NextNumber()
                return mean + standardDeviation
                    * (math.sqrt(-2 * math.log(first)) * math.cos(2 * math.pi * second))
            end

            function RivalsRuntimeBridge.FlickbotGamma(rng, shape, scale)
                local factor = 1
                if shape < 1 then
                    factor = rng:NextNumber() ^ (1 / shape)
                    shape = shape + 1
                end
                local adjustedShape = shape - (1 / 3)
                local root = math.sqrt(9 * adjustedShape)
                while true do
                    local sample = RivalsRuntimeBridge.FlickbotNormal(rng, 0, 1)
                    local candidate = (1 + (sample / root)) ^ 3
                    if candidate > 0 then
                        local uniform = math.max(rng:NextNumber(), 1e-15)
                        if uniform < 1 - (0.0331 * sample ^ 4)
                            or math.log(uniform) < (0.5 * sample * sample)
                                + adjustedShape * (1 - candidate + math.log(candidate)) then
                            return adjustedShape * candidate * scale * factor
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.FlickbotErf(value)
                local sign = value < 0 and -1 or 1
                local magnitude = math.abs(value)
                local factor = 1 / (1 + 0.3275911 * magnitude)
                local polynomial = 0.254829592 * factor
                    - 0.284496736 * factor ^ 2
                    + 1.421413741 * factor ^ 3
                    - 1.453152027 * factor ^ 4
                    + 1.061405429 * factor ^ 5
                return sign * (1 - polynomial * math.exp(-magnitude * magnitude))
            end

            function RivalsRuntimeBridge.FlickbotLognormalCdf(timeMs, startMs, mean, sigma)
                if timeMs <= startMs then
                    return 0
                end
                return 0.5 * (1 + RivalsRuntimeBridge.FlickbotErf(
                    (math.log(timeMs - startMs) - mean) / (sigma * math.sqrt(2))
                ))
            end

            function RivalsRuntimeBridge.FlickbotLognormalPdf(timeMs, startMs, mean, sigma)
                if timeMs <= startMs then
                    return 0
                end
                local elapsed = timeMs - startMs
                local standardized = (math.log(elapsed) - mean) / sigma
                return math.exp(-0.5 * standardized * standardized)
                    / (sigma * math.sqrt(2 * math.pi) * elapsed)
            end

            function RivalsRuntimeBridge.FlickbotBump(value)
                if value <= 0 or value >= 1 then
                    return 0
                end
                return value * value * (1 - value) ^ 3 / 0.03456
            end

            function RivalsRuntimeBridge.ApplyFlickbotProfile()
                local flickbot = RivalsRuntimeBridge.Flickbot
                local durationMs = math.max(Options.P2S1S10 and Options.P2S1S10.Value or 110, 20)
                flickbot.FittsA = durationMs / 4
                flickbot.FittsB = durationMs / 4
                flickbot.TargetWidth = 80
                flickbot.PeakTimeRatio = 0.32
                flickbot.PrimarySigmaMin = 0.2
                flickbot.PrimarySigmaMax = 0.26
                flickbot.UndershootMin = 0.97
                flickbot.UndershootMax = 1
                flickbot.OvershootProbability = 0.08
                flickbot.OvershootMin = 1.01
                flickbot.OvershootMax = 1.04
                flickbot.SecondCorrectionProbability = 0
                flickbot.CorrectionSigmaMin = 0.1
                flickbot.CorrectionSigmaMax = 0.14
                flickbot.CurvatureScale = math.clamp(
                    Options.P2S1S11 and Options.P2S1S11.Value or 12,
                    0,
                    50
                ) / 1000
                local humanness = math.clamp(
                    Options.P2S1S12 and Options.P2S1S12.Value or 30,
                    0,
                    100
                ) / 30
                flickbot.OuSigma = 0.5 * humanness
                flickbot.TremorAmplitudeMin = 0.05 * humanness
                flickbot.TremorAmplitudeMax = 0.18 * humanness
                flickbot.SignalDependentNoise = 0.02
            end

            function RivalsRuntimeBridge.GenerateFlickbotTrajectory(startX, startY, targetX, targetY)
                RivalsRuntimeBridge.ApplyFlickbotProfile()
                local flickbot = RivalsRuntimeBridge.Flickbot
                local rng = flickbot.Rng
                local function randomBetween(minimum, maximum)
                    return minimum + rng:NextNumber() * (maximum - minimum)
                end
                local function normal(mean, standardDeviation)
                    return RivalsRuntimeBridge.FlickbotNormal(rng, mean, standardDeviation)
                end

                local deltaX = targetX - startX
                local deltaY = targetY - startY
                local distance = math.sqrt(deltaX * deltaX + deltaY * deltaY)
                if distance < 1 then
                    return {}
                end
                local directionX = deltaX / distance
                local directionY = deltaY / distance
                local directionAngle = math.atan2(deltaY, deltaX)
                local indexOfDifficulty = math.log(distance / flickbot.TargetWidth + 1) / math.log(2)
                local duration = math.max(
                    (flickbot.FittsA + flickbot.FittsB * indexOfDifficulty)
                        * math.exp(normal(0, 0.08)),
                    80
                )
                local distanceFactor
                if randomBetween(0, 1) < flickbot.OvershootProbability then
                    distanceFactor = randomBetween(flickbot.OvershootMin, flickbot.OvershootMax)
                else
                    distanceFactor = randomBetween(flickbot.UndershootMin, flickbot.UndershootMax)
                end
                local primaryDistance = distance * distanceFactor
                local primarySigma = randomBetween(flickbot.PrimarySigmaMin, flickbot.PrimarySigmaMax)
                local peakRatio = randomBetween(flickbot.PeakTimeRatio - 0.03, flickbot.PeakTimeRatio + 0.03)
                local primaryMean = math.log(duration * peakRatio) + primarySigma * primarySigma
                local corrections = {}
                local remaining = distance - primaryDistance
                if math.abs(remaining) > 0.5 then
                    local sign = remaining > 0 and 1 or -1
                    local correctionDistance = math.abs(remaining) * randomBetween(0.88, 1.02)
                    local correctionSigma = randomBetween(flickbot.CorrectionSigmaMin, flickbot.CorrectionSigmaMax)
                    local correctionPeak = randomBetween(0.12, 0.18)
                    corrections[#corrections + 1] = {
                        distance = correctionDistance,
                        startMs = duration * randomBetween(0.55, 0.68),
                        mean = math.log(duration * correctionPeak) + correctionSigma * correctionSigma,
                        sigma = correctionSigma,
                        directionX = directionX * sign,
                        directionY = directionY * sign,
                    }
                    local secondRemaining = remaining - correctionDistance * sign
                    if math.abs(secondRemaining) > 0.3
                        and randomBetween(0, 1) < flickbot.SecondCorrectionProbability then
                        local secondSign = secondRemaining > 0 and 1 or -1
                        local secondSigma = randomBetween(0.1, 0.16)
                        local secondPeak = randomBetween(0.08, 0.12)
                        corrections[#corrections + 1] = {
                            distance = math.abs(secondRemaining) * randomBetween(0.85, 1.05),
                            startMs = duration * randomBetween(0.78, 0.88),
                            mean = math.log(duration * secondPeak) + secondSigma * secondSigma,
                            sigma = secondSigma,
                            directionX = directionX * secondSign,
                            directionY = directionY * secondSign,
                        }
                    end
                end

                local angleScale = 0.5 + 0.8 * math.abs(math.sin(directionAngle))
                    - 0.15 * math.abs(math.cos(directionAngle))
                local curvature = distance * flickbot.CurvatureScale * angleScale * normal(0, 1)
                local tremorFrequency = randomBetween(flickbot.TremorFrequencyMin, flickbot.TremorFrequencyMax)
                local tremorAmplitude = randomBetween(flickbot.TremorAmplitudeMin, flickbot.TremorAmplitudeMax)
                local tremorPhaseX = randomBetween(0, 2 * math.pi)
                local tremorPhaseY = randomBetween(0, 2 * math.pi)
                local noiseX = 0
                local noiseY = 0
                local endTime = duration * 1.15
                local sampleTimes = {}
                local sampleTime = 0
                while sampleTime < endTime do
                    sampleTime = sampleTime + math.clamp(
                        RivalsRuntimeBridge.FlickbotGamma(
                            rng,
                            flickbot.GammaShape,
                            flickbot.SampleDeltaMean / flickbot.GammaShape
                        ),
                        2,
                        25
                    )
                    if sampleTime <= endTime + 15 then
                        sampleTimes[#sampleTimes + 1] = sampleTime
                    end
                end

                local trajectory = {}
                for index, timeMs in ipairs(sampleTimes) do
                    local deltaMs = index > 1 and (timeMs - sampleTimes[index - 1]) or flickbot.SampleDeltaMean
                    local deltaSeconds = deltaMs / 1000
                    local primaryProgress = RivalsRuntimeBridge.FlickbotLognormalCdf(
                        timeMs,
                        0,
                        primaryMean,
                        primarySigma
                    )
                    local x = startX + directionX * primaryDistance * primaryProgress
                        - directionY * curvature * RivalsRuntimeBridge.FlickbotBump(primaryProgress)
                    local y = startY + directionY * primaryDistance * primaryProgress
                        + directionX * curvature * RivalsRuntimeBridge.FlickbotBump(primaryProgress)
                    for _, correction in ipairs(corrections) do
                        local correctionProgress = RivalsRuntimeBridge.FlickbotLognormalCdf(
                            timeMs,
                            correction.startMs,
                            correction.mean,
                            correction.sigma
                        )
                        x = x + correction.directionX * correction.distance * correctionProgress
                        y = y + correction.directionY * correction.distance * correctionProgress
                    end

                    local velocity = primaryDistance * RivalsRuntimeBridge.FlickbotLognormalPdf(
                        timeMs,
                        0,
                        primaryMean,
                        primarySigma
                    )
                    for _, correction in ipairs(corrections) do
                        velocity = velocity + correction.distance * RivalsRuntimeBridge.FlickbotLognormalPdf(
                            timeMs,
                            correction.startMs,
                            correction.mean,
                            correction.sigma
                        )
                    end
                    noiseX = noiseX + (-flickbot.OuTheta * noiseX * deltaSeconds
                        + flickbot.OuSigma * math.sqrt(deltaSeconds) * normal(0, 1))
                    noiseY = noiseY + (-flickbot.OuTheta * noiseY * deltaSeconds
                        + flickbot.OuSigma * math.sqrt(deltaSeconds) * normal(0, 1))
                    local timeSeconds = timeMs / 1000
                    local tremorScale = 1 / (1 + velocity * 0.3)
                    local tremorX = math.sin(2 * math.pi * tremorFrequency * timeSeconds + tremorPhaseX)
                    local tremorY = math.sin(2 * math.pi * tremorFrequency * timeSeconds + tremorPhaseY)
                    trajectory[#trajectory + 1] = {
                        x = x + noiseX + tremorAmplitude * tremorScale * tremorX
                            + flickbot.SignalDependentNoise * velocity * normal(0, 1),
                        y = y + noiseY + tremorAmplitude * tremorScale * tremorY
                            + flickbot.SignalDependentNoise * velocity * normal(0, 1),
                        t = timeMs,
                    }
                end
                return trajectory
            end

            function RivalsRuntimeBridge.StartFlickbot()
                local flickbot = RivalsRuntimeBridge.Flickbot
                local camera = Workspace.CurrentCamera
                if RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed()
                    or not camera or not RivalsRuntimeBridge.IsReadyToFight() then
                    return false
                end
                local targeting = AimbotBridge.ResolveTargeting('P2S2_Targeting')
                local configuredAimPart = Options.P2S2_AimPart and Options.P2S2_AimPart.Value or 'Auto'
                local aimFovRadius = Options.P2S2_FOVRadius and Options.P2S2_FOVRadius.Value or 250
                local targetInfo = GetBestAimbotTarget(
                    targeting.requireVisible,
                    targeting.ignoreFov,
                    configuredAimPart,
                    aimFovRadius,
                    targeting.teamCheck
                )
                local targetPart = targetInfo and targetInfo.part or nil
                if not targetPart or not targetPart.Parent then
                    return false
                end
                local targetPoint = camera:WorldToViewportPoint(targetPart.Position)
                if targetPoint.Z <= 0 then
                    return false
                end
                local viewport = camera.ViewportSize
                local generated = RivalsRuntimeBridge.GenerateFlickbotTrajectory(
                    viewport.X * 0.5,
                    viewport.Y * 0.5,
                    targetPoint.X,
                    targetPoint.Y
                )
                if #generated < 2 then
                    return false
                end
                local trajectory = table.create(#generated)
                for index, point in ipairs(generated) do
                    trajectory[index] = {
                        direction = camera:ViewportPointToRay(point.x, point.y).Direction,
                        t = point.t,
                    }
                end
                flickbot.Trajectory = trajectory
                flickbot.TrajectoryIndex = 1
                flickbot.ElapsedMs = 0
                flickbot.TotalMs = trajectory[#trajectory].t
                flickbot.BakedEndDirection = trajectory[#trajectory].direction
                flickbot.Selected = targetInfo
                flickbot.State = 'Flicking'
                return true
            end

            function RivalsRuntimeBridge.SampleFlickbotTrajectory(deltaTime)
                local flickbot = RivalsRuntimeBridge.Flickbot
                local trajectory = flickbot.Trajectory
                flickbot.ElapsedMs = flickbot.ElapsedMs + deltaTime * 1000
                local index = flickbot.TrajectoryIndex
                while index < #trajectory and trajectory[index + 1].t <= flickbot.ElapsedMs do
                    index = index + 1
                end
                flickbot.TrajectoryIndex = index
                local current = trajectory[index]
                local following = trajectory[index + 1]
                if not following then
                    return trajectory[#trajectory].direction, true
                end
                local interval = following.t - current.t
                local alpha = interval > 0
                    and math.clamp((flickbot.ElapsedMs - current.t) / interval, 0, 1)
                    or 1
                return current.direction:Lerp(following.direction, alpha), false
            end

            function RivalsRuntimeBridge.FinishFlickbotToCooldown()
                local flickbot = RivalsRuntimeBridge.Flickbot
                flickbot.Selected = nil
                flickbot.Trajectory = nil
                local cooldownMs = math.clamp(Options.P2S1S9 and Options.P2S1S9.Value or 250, 0, 2000)
                if cooldownMs > 0 then
                    flickbot.State = 'Cooldown'
                    flickbot.Timer = cooldownMs / 1000
                else
                    flickbot.State = 'Idle'
                    flickbot.Timer = 0
                end
            end

            function RivalsRuntimeBridge.IsFlickbotCameraClaimed()
                local state = RivalsRuntimeBridge.Flickbot.State
                return state == 'Flicking' or state == 'PostShot'
            end

            function RivalsRuntimeBridge.UpdateFlickbot(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local flickbot = RivalsRuntimeBridge.Flickbot
                if RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed() then
                    if flickbot.State ~= 'Idle' or flickbot.WasHeld then
                        RivalsRuntimeBridge.ResetFlickbot()
                    end
                    return
                end
                local enabled = Toggles.P2S1T12 and Toggles.P2S1T12.Value == true
                local keypicker = Options.P2S1T12K
                local held = enabled and keypicker and type(keypicker.GetState) == 'function'
                    and keypicker:GetState() == true
                if not enabled then
                    if flickbot.State ~= 'Idle' or flickbot.WasHeld then
                        RivalsRuntimeBridge.ResetFlickbot()
                    end
                    return
                end
                if held and not flickbot.WasHeld and flickbot.State == 'Idle'
                    and not AimbotInputState.SyntheticInputBlocked() then
                    RivalsRuntimeBridge.StartFlickbot()
                end
                flickbot.WasHeld = held

                local frameDelta = math.clamp(type(deltaTime) == 'number' and deltaTime or (1 / 60), 0, 0.1)
                if flickbot.State == 'Flicking' then
                    local selected = flickbot.Selected
                    local targetPart = selected and selected.part or nil
                    local camera = Workspace.CurrentCamera
                    if not targetPart or not targetPart.Parent or not camera or not flickbot.Trajectory then
                        RivalsRuntimeBridge.FinishFlickbotToCooldown()
                        return
                    end
                    local direction, finished = RivalsRuntimeBridge.SampleFlickbotTrajectory(frameDelta)
                    if flickbot.TotalMs > 0 then
                        local targetOffset = targetPart.Position - camera.CFrame.Position
                        if targetOffset.Magnitude > 0.001 then
                            local progress = math.clamp(flickbot.ElapsedMs / flickbot.TotalMs, 0, 1)
                            local corrected = direction
                                + (targetOffset.Unit - flickbot.BakedEndDirection) * progress
                            if corrected.Magnitude > 0.001 then
                                direction = corrected.Unit
                            end
                        end
                    end
                    local cameraController = RivalsModsState.ResolveCameraController()
                    if cameraController and type(cameraController.SetRotation) == 'function' then
                        local pitch, yaw = CFrame.lookAt(camera.CFrame.Position, camera.CFrame.Position + direction):ToOrientation()
                        cameraController:SetRotation(Vector2.new(pitch, yaw))
                    end
                    if finished then
                        if Toggles.P2S1T13 and Toggles.P2S1T13.Value == true then
                            flickbot.State = 'PostShot'
                            flickbot.Timer = math.clamp(
                                Options.P2S1S8 and Options.P2S1S8.Value or 0,
                                0,
                                250
                            ) / 1000
                        else
                            RivalsRuntimeBridge.FinishFlickbotToCooldown()
                        end
                    end
                elseif flickbot.State == 'PostShot' then
                    flickbot.Timer = flickbot.Timer - frameDelta
                    if flickbot.Timer <= 0 then
                        FireTriggerbotShot()
                        RivalsRuntimeBridge.FinishFlickbotToCooldown()
                    end
                elseif flickbot.State == 'Cooldown' then
                    flickbot.Timer = flickbot.Timer - frameDelta
                    if flickbot.Timer <= 0 then
                        flickbot.State = 'Idle'
                        flickbot.Timer = 0
                    end
                end
            end

            RivalsRuntimeBridge.UpdateCameraAim = function(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                if RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed()
                    or RivalsRuntimeBridge.IsFlickbotCameraClaimed()
                    or not AimbotBridge.IsDirectAimbotEnabled()
                    or not IsAimbotGameReady()
                    or not IsAimbotCameraReady()
                    or not RivalsRuntimeBridge.IsReadyToFight() then
                    if RivalsRuntimeBridge.CurrentCameraAimTarget ~= nil then
                        AimbotBridge.ResetCameraAimRandomState()
                    end
                    return
                end

                local camera = Workspace.CurrentCamera
                if not camera then return end

                local targeting = AimbotBridge.ResolveTargeting('P2S2_Targeting')
                local configuredAimPart = Options.P2S2_AimPart and Options.P2S2_AimPart.Value or 'Auto'
                local aimFovRadius = Options.P2S2_FOVRadius and Options.P2S2_FOVRadius.Value or 250
                local targetInfo = GetBestAimbotTarget(
                    targeting.requireVisible,
                    targeting.ignoreFov,
                    configuredAimPart,
                    aimFovRadius,
                    targeting.teamCheck
                )

                if configuredAimPart == 'Random' and targetInfo then
                    local targetIdentity = targetInfo.player or targetInfo.instance
                    local stablePart = AimbotSilentConnections.CameraAimRandomPart
                    if AimbotSilentConnections.CameraAimRandomTarget == targetIdentity
                        and stablePart and stablePart.Parent then
                        local stableAimPart = IsHeadAimbotTargetPart(stablePart) and 'Head' or 'HumanoidRootPart'
                        local stableTargetInfo = RivalsRuntimeBridge.RefreshAimbotTargetInfo(
                            targetInfo,
                            stableAimPart,
                            AimbotBridge.GetAimbotPointerPosition(),
                            DEFAULT_ESP_MAX_DISTANCE,
                            AIMBOT_VISIBILITY_CACHE_PROFILE,
                            aimFovRadius,
                            targeting.ignoreFov
                        )
                        if stableTargetInfo then
                            targetInfo = stableTargetInfo
                        end
                    end
                    AimbotSilentConnections.CameraAimRandomTarget = targetIdentity
                    AimbotSilentConnections.CameraAimRandomPart = targetInfo.part
                else
                    AimbotBridge.ResetCameraAimRandomState()
                end

                if not targetInfo then
                    RivalsRuntimeBridge.CurrentCameraAimTarget = nil
                    return
                end

                if not targeting.ignoreFov then
                    local aimPoint = targetInfo.worldPosition
                    local screenPos, onScreen = AimbotBridge.WorldToAimbotScreen(aimPoint, camera)
                    local pointerPos = AimbotBridge.GetAimbotPointerPosition()
                    if not onScreen or not screenPos or typeof(pointerPos) ~= 'Vector2' or (screenPos - pointerPos).Magnitude > aimFovRadius then
                        RivalsRuntimeBridge.CurrentCameraAimTarget = nil
                        return
                    end
                end

                -- Katana Deflect Check
                if targetInfo.player and Toggles.P2S2_CheckKatana and Toggles.P2S2_CheckKatana.Value then
                    if AimbotBridge.ShouldIgnoreAimbotKatanaDeflectTarget(targetInfo.player, AimbotBridge.ResolveAimbotEquippedItem()) then
                        RivalsRuntimeBridge.CurrentCameraAimTarget = nil
                        return
                    end
                end

                -- Riot Shield Check
                if targetInfo.player and Toggles.P2S2_CheckShield and Toggles.P2S2_CheckShield.Value then
                    local subject = targetInfo.instance or targetInfo.player.Character
                    if ShouldIgnoreRivalsRiotShieldTarget(targetInfo.player, subject, AimbotBridge.ResolveAimbotEquippedItem()) then
                        RivalsRuntimeBridge.CurrentCameraAimTarget = nil
                        return
                    end
                end

                local targetPart = targetInfo.part
                local worldPosition = targetInfo.worldPosition
                if not targetPart or not targetPart.Parent or not worldPosition then
                    RivalsRuntimeBridge.CurrentCameraAimTarget = nil
                    return
                end
                if targetInfo.player and IsRivalsSpawnShieldActive(targetInfo.player.Character) then
                    RivalsRuntimeBridge.CurrentCameraAimTarget = nil
                    return
                end

                RivalsRuntimeBridge.CurrentCameraAimTarget = targetInfo

                -- Movement Prediction for Cam Aim and Mouse Aim
                local predictionEnabled = Toggles.P2S2_Prediction and Toggles.P2S2_Prediction.Value == true
                if predictionEnabled then
                    local targetVelocity = (targetPart and (targetPart.AssemblyLinearVelocity or targetPart.Velocity)) or Vector3.zero
                    if targetInfo.player and targetInfo.player.Character then
                        local hrp = targetInfo.player.Character:FindFirstChild('HumanoidRootPart')
                        if hrp then
                            local hrpVel = hrp.AssemblyLinearVelocity or hrp.Velocity
                            if hrpVel and hrpVel.Magnitude > targetVelocity.Magnitude then
                                targetVelocity = hrpVel
                            end
                        end
                    end

                    if targetVelocity.Magnitude > 0.05 then
                        local predAmount = Options.P2S2_PredictionAmount and Options.P2S2_PredictionAmount.Value or 0.05
                        local usePing = not (Toggles.P2S2_PredPing and Toggles.P2S2_PredPing.Value == false)
                        local pingTime = 0
                        if usePing and LP and type(LP.GetNetworkPing) == 'function' then
                            pingTime = math.clamp(LP:GetNetworkPing(), 0, 0.5)
                        end
                        worldPosition = worldPosition + (targetVelocity * (predAmount + pingTime))
                    end
                end

                local frameDelta = math.clamp(type(deltaTime) == 'number' and deltaTime or (1 / 60), 0, 0.1)

                -- Smoothness: 0 = instant snap, higher = slower/smoother lock.
                -- Frame-rate independent exponential approach.
                local smoothness = math.clamp(Options.P2S2S1 and tonumber(Options.P2S2S1.Value) or 25, 0, 100)
                local blendAlpha
                if smoothness <= 0 then
                    blendAlpha = 1
                else
                    local rate = 120 * math.pow(1.5 / 120, smoothness / 100)
                    blendAlpha = math.clamp(1 - math.exp(-frameDelta * rate), 0.01, 1)
                end

                -- True camera aim for BOTH modes: drive the game's camera controller
                -- rotation state (and the camera itself) instead of synthetic mouse
                -- movement. Keeping the controller's Rotation in sync is what stops
                -- the camera from snapping back to the pre-lock orientation when you
                -- release the aim key.
                local cameraController = RivalsModsState.ResolveCameraController()
                local lookAt = CFrame.lookAt(camera.CFrame.Position, worldPosition)
                local pitch, yaw = lookAt:ToOrientation()

                local currentPitch, currentYaw
                local controllerRotation = nil
                if cameraController then
                    local okRot, liveRotation = pcall(function()
                        return cameraController.Rotation
                    end)
                    if okRot and typeof(liveRotation) == 'Vector2' then
                        controllerRotation = liveRotation
                    end
                end
                if controllerRotation then
                    currentPitch, currentYaw = controllerRotation.X, controllerRotation.Y
                else
                    currentPitch, currentYaw = camera.CFrame:ToOrientation()
                end

                local yawDiff = (yaw - currentYaw + math.pi) % (2 * math.pi) - math.pi
                local newPitch = currentPitch + (pitch - currentPitch) * blendAlpha
                local newYaw = currentYaw + yawDiff * blendAlpha

                local appliedViaController = false
                if cameraController and type(cameraController.SetRotation) == 'function' then
                    local okSet = pcall(cameraController.SetRotation, cameraController, Vector2.new(newPitch, newYaw))
                    appliedViaController = okSet
                end
                if not appliedViaController then
                    camera.CFrame = CFrame.new(camera.CFrame.Position) * CFrame.fromOrientation(newPitch, newYaw, 0)
                end
            end

            local GetBestTriggerbotTarget = function()
                local targeting = AimbotBridge.ResolveTargeting('P2S1_Targeting')
                local allowTeammates = not targeting.teamCheck
                EnsureAimbotTargetTracking()

                local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                local fovRadius = Options.P2S1S2 and Options.P2S1S2.Value or 170
                local maxDistance = DEFAULT_ESP_MAX_DISTANCE
                local ignoreFov = targeting.ignoreFov
                local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                local camera = Workspace.CurrentCamera
                if not camera then
                    return nil
                end

                local bestTarget = nil

                for _, fighter in ipairs(LocalFighterController and LocalFighterController.Objects or {}) do
                    local player = fighter and fighter.Player
                    if player and player ~= LP and IsUnder(player, Players) then
                        local entity = fighter.Entity
                        local subject = entity and entity.Model
                        if not ShouldShow(player, allowTeammates) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('team_or_self', subject, player, 'Players')
                        elseif FighterDataCache.ReadEntity(entity) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('invincible', subject, player, 'Players')
                        elseif ShouldIgnoreRivalsRiotShieldTarget(player, subject or player.Character, AimbotBridge.ResolveAimbotEquippedItem()) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('riot_shield', subject, player, 'Players')
                        else
                            bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, subject, 'Players', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, player, camera, TRIGGERBOT_VISIBILITY_CACHE_PROFILE, targeting.requireVisible)
                        end
                    end
                end

                for model in pairs(TrackedRangeTargets) do
                    if not model.Parent then
                        TrackedRangeTargets[model] = nil
                    else
                        bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, model, 'Range Targets', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, nil, camera, TRIGGERBOT_VISIBILITY_CACHE_PROFILE, targeting.requireVisible)
                    end
                end

                for model in pairs(TrackedPracticeDummies) do
                    if not model.Parent then
                        TrackedPracticeDummies[model] = nil
                    else
                        bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, model, 'Practice Dummies', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, nil, camera, TRIGGERBOT_VISIBILITY_CACHE_PROFILE, targeting.requireVisible)
                    end
                end

                RivalsRuntimeBridge.LastAimbotSweepTarget = bestTarget
                RivalsRuntimeBridge.LastAimbotSweepAt = os.clock()
                return bestTarget
            end

            SharedTryTriggerbotShot = TryTriggerbotShot
            SharedGetBestTriggerbotTarget = GetBestTriggerbotTarget
            end

            local function ResolveTriggerbotTarget(aimbotEnabled, currentTargetInfo)
                local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                local maxDistance = DEFAULT_ESP_MAX_DISTANCE
                local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                local targeting = AimbotBridge.ResolveTargeting('P2S1_Targeting')
                local fovRadius = Options.P2S1S2 and Options.P2S1S2.Value or 170
                local refreshedTarget = currentTargetInfo and RivalsRuntimeBridge.RefreshAimbotTargetInfo(
                    currentTargetInfo,
                    aimPart,
                    mousePosition,
                    maxDistance,
                    TRIGGERBOT_VISIBILITY_CACHE_PROFILE,
                    fovRadius,
                    targeting.ignoreFov
                )
                if refreshedTarget then
                    return refreshedTarget
                end

                local cursorTargetInfo = ResolveCursorTriggerbotTarget()
                if cursorTargetInfo then
                    return cursorTargetInfo
                end

                return GetBestTriggerbotTarget()
            end

            local TryTriggerbotShot = SharedTryTriggerbotShot
            GetBestTriggerbotTarget = SharedGetBestTriggerbotTarget

            RivalsRuntimeBridge.BeginAimbotSilentShot = function(item)
                if (AimbotSilentState.ShotPrimeDepth or 0) > 0 then
                    return false, nil, nil, nil, nil
                end

                if not AimbotBridge.IsSilentAimFullyActive() then
                    AimbotSilentState.RaycastDestination = nil
                    AimbotSilentState.HookTarget = nil
                    return false, nil, nil, nil, nil
                end

                local readyToFight = RivalsRuntimeBridge.IsReadyToFight()
                RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint('Silent Aim', readyToFight, true)
                if not readyToFight then
                    return false, nil, nil, nil, nil
                end

                local targetInfo = RivalsRuntimeBridge.ResolveAimbotSilentHookTarget(item)
                if not targetInfo then
                    return false, nil, nil, nil, nil
                end

                local hitchance = 100
                if Options.P2S1_HitChance and type(Options.P2S1_HitChance.Value) == 'number' then
                    hitchance = math.clamp(Options.P2S1_HitChance.Value, 0, 100)
                end
                if hitchance < 99.5 then
                    if hitchance <= 0 then
                        return false, nil, nil, nil, nil
                    end
                    local lastShot = AimbotBridge.ReadAimbotLastShot and AimbotBridge.ReadAimbotLastShot(item)
                    local now = tick()
                    local windowKey = lastShot
                    if type(windowKey) ~= 'number' then
                        local prevAt = AimbotSilentState.HitChanceAt
                        if type(prevAt) == 'number' and (now - prevAt) < 0.08 then
                            windowKey = AimbotSilentState.HitChanceKey
                        else
                            windowKey = now
                        end
                    end
                    if AimbotSilentState.HitChanceKey ~= windowKey then
                        AimbotSilentState.HitChanceKey = windowKey
                        AimbotSilentState.HitChanceAt = now
                        AimbotSilentState.HitChancePass = (math.random() * 100) <= hitchance
                    end
                    if not AimbotSilentState.HitChancePass then
                        return false, nil, nil, nil, nil
                    end
                end

                if targetInfo.player and IsRivalsSpawnShieldActive(targetInfo.player.Character) then
                    return false, nil, nil, nil, nil
                end

                pcall(RivalsModsState.EnsureSilentV2RaycastHook)
                AimbotSilentState.RaycastDestination = targetInfo.worldPosition
                AimbotSilentState.HookTarget = targetInfo

                local camera = Workspace.CurrentCamera
                local originalCFrame = camera and camera.CFrame or nil

                local camController = RivalsModsState.ResolveCameraController and RivalsModsState.ResolveCameraController()
                local originalCamRotation = nil
                if camController and typeof(camController.Rotation) == 'Vector2' and camera and targetInfo.worldPosition then
                    originalCamRotation = camController.Rotation
                    local originPos = camera.CFrame.Position
                    local lookVec = (targetInfo.worldPosition - originPos).Unit
                    local pitch = math.asin(math.clamp(lookVec.Y, -1, 1))
                    local yaw = math.atan2(-lookVec.X, -lookVec.Z)
                    camController.Rotation = Vector2.new(pitch, yaw)
                end

                if not RivalsModsState.IsSilentV2Mode() and camera and originalCFrame and targetInfo.worldPosition then
                    camera.CFrame = CFrame.lookAt(camera.CFrame.Position, targetInfo.worldPosition)
                end

                AimbotSilentState.ShotPrimeDepth = (AimbotSilentState.ShotPrimeDepth or 0) + 1
                if AimbotBridge.ResolveAimbotSilentDebugEnabled() then
                    RivalsRuntimeBridge.NotifyAimbotStatus('silent_prime', string.format('Silent shot: %s', targetInfo.displayName), true)
                end

                return true, camera, originalCFrame, camController, originalCamRotation
            end

            RivalsRuntimeBridge.FinishAimbotSilentShot = function(didPrime, camera, originalCFrame, camController, originalCamRotation)
                if not didPrime then
                    return
                end

                AimbotSilentState.ShotPrimeDepth = math.max((AimbotSilentState.ShotPrimeDepth or 1) - 1, 0)
                if camController and originalCamRotation then
                    camController.Rotation = originalCamRotation
                end
                if camera and originalCFrame and Workspace.CurrentCamera == camera and RivalsRuntimeBridge.IsReadyToFight() then
                    camera.CFrame = originalCFrame
                end
            end

            RivalsModsState.BeginAimbotSilentShot = RivalsRuntimeBridge.BeginAimbotSilentShot
            RivalsModsState.FinishAimbotSilentShot = RivalsRuntimeBridge.FinishAimbotSilentShot

            local function EnsureAimbotSilentStartShootingHook(item)
                if AimbotSilentConnections.HookedItem == item then
                    return
                end

                if not AimbotBridge.IsAimbotSilentShotHookItem(item) then
                    return
                end

                local originalStartShooting = item.StartShooting
                local wrappedStartShooting
                wrappedStartShooting = function(self, ...)
                    local didPrime, camera, originalCFrame, camController, originalCamRot = RivalsRuntimeBridge.BeginAimbotSilentShot(self)
                    local baseStartShooting = RivalsModsState.ResolveGunStartShootingBase(originalStartShooting)
                    local results = RunWithGameIdentity(baseStartShooting, self, ...)
                    RivalsRuntimeBridge.FinishAimbotSilentShot(didPrime, camera, originalCFrame, camController, originalCamRot)
                    if not results[1] then
                        ReportRivalsRuntimeIssue('silent_start_shooting', results[2])
                        return nil
                    end
                    return table.unpack(results, 2, results.n)
                end

                AimbotSilentConnections.HookedItem = item
                AimbotSilentConnections.OriginalStartShooting = originalStartShooting
                AimbotSilentConnections.WrappedStartShooting = wrappedStartShooting
                item.StartShooting = wrappedStartShooting
            end

            local function UpdateAimbot()
                LPH_ATTRIBUTES(VM(NONE))
                if not (Toggles.P2S1T6 and Toggles.P2S1T6.Value) then
                    RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                end

                local silentActive = AimbotBridge.IsSilentAimFullyActive()
                local triggerbotEnabled = AimbotBridge.IsTriggerbotEnabled()
                local cameraAimActive = AimbotBridge.IsDirectAimbotEnabled()
                if silentActive and not RivalsModsState.SilentV2RaycastHooked then
                    RivalsModsState.EnsureSilentV2RaycastHook()
                end
                if not silentActive then
                    AimbotSilentState.RaycastDestination = nil
                    AimbotSilentState.HookTarget = nil
                    AimbotSilentState.HookTargetCapturedAt = 0
                    AimbotBridge.DisconnectAimbotSilentConnections()
                end
                local readyToFight = RivalsRuntimeBridge.IsReadyToFight()
                RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint('Silent Aim', readyToFight, silentActive == true)
                local aimbotGameReady = silentActive and readyToFight
                local triggerbotGameReady = triggerbotEnabled and readyToFight
                local cameraAimGameReady = cameraAimActive and readyToFight
                local gameReady = aimbotGameReady or triggerbotGameReady or cameraAimGameReady

                local showAimFov = Toggles.P2S2_ShowFOV and Toggles.P2S2_ShowFOV.Value == true
                local showSilentFov = Toggles.P2S1T5 and Toggles.P2S1T5.Value == true
                if showAimFov or showSilentFov then
                    AimbotBridge.UpdateAimbotFovCircle(silentActive, cameraAimActive)
                end

                if not silentActive and not triggerbotEnabled and not cameraAimActive then
                    return
                end

                if not gameReady then
                    RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('game_not_ready')
                    if silentActive then
                        AimbotBridge.ResetAimbotRuntimeState()
                    end
                    AimbotBridge.ResetTriggerbotReactionState()
                    RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                    return
                end

                local item = AimbotBridge.ResolveAimbotEquippedItem()
                if item and silentActive then
                    EnsureAimbotSilentStartShootingHook(item)
                end

                local cameraReady = IsAimbotCameraReady()
                if not cameraReady then
                    RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('camera_not_ready')
                    AimbotBridge.ResetAimbotRuntimeState()
                    AimbotBridge.ResetTriggerbotReactionState()
                    RivalsRuntimeBridge.NotifyAimbotStatus('camera_wait', 'Waiting for camera.')
                    return
                end

                local targetInfo = nil

                if not silentActive then
                    AimbotSilentState.RaycastDestination = nil
                else
                    local shootInputHeld = AimbotBridge.IsAimbotShootInputHeld()
                    local evaluation = RivalsRuntimeBridge.EvaluateAimbotSilentRuntime(item, shootInputHeld)
                    local statusForce = AimbotBridge.ResolveAimbotSilentDebugEnabled()
                    local shouldContinuousAim = evaluation.shouldAim
                    if evaluation.blockedReason then
                        AimbotSilentState.RaycastDestination = nil
                        RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('silent_blocked:' .. tostring(evaluation.blockedReason))
                        RivalsRuntimeBridge.NotifyAimbotStatus('silent_blocked', RivalsRuntimeBridge.BuildAimbotSilentStatus(nil, evaluation), statusForce)
                    else
                        if shouldContinuousAim then
                            targetInfo = RivalsRuntimeBridge.GetBestAimbotTarget()
                            if not targetInfo then
                                AimbotSilentState.RaycastDestination = nil
                                RivalsRuntimeBridge.NotifyAimbotStatus('no_target', 'No target visible.')
                            else
                                RivalsRuntimeBridge.PrimeAimbotAim(targetInfo, item)
                            end
                        end

                        RivalsRuntimeBridge.NotifyAimbotStatus('tracking', RivalsRuntimeBridge.BuildAimbotSilentStatus(targetInfo, evaluation), statusForce)
                    end
                end

                if not triggerbotEnabled then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    return
                end

                local triggerTargetInfo = ResolveTriggerbotTarget(silentActive, targetInfo)
                if not triggerTargetInfo then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    if not silentActive then
                        RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                    end
                    return
                end

                if TryTriggerbotShot(triggerTargetInfo, item, silentActive) and not silentActive then
                    RivalsRuntimeBridge.NotifyAimbotStatus('tracking', string.format('Triggerbot: %s', triggerTargetInfo.displayName))
                end
            end

            RivalsRuntimeBridge.UpdateAimbot = UpdateAimbot
            end)()

            ;(function()
            LPH_ATTRIBUTES(VM(NONE))

            local math_atan2 = math.atan2
            local math_sin = math.sin
            local math_cos = math.cos
            local math_min = math.min
            local math_max = math.max
            local math_clamp = math.clamp
            local math_floor = math.floor
            local math_sqrt = math.sqrt

            local espRayParams = RaycastParams.new()
            espRayParams.FilterType = Enum.RaycastFilterType.Exclude

            local espUpdateAccumulator = 0
            local nextEspReconcile = 0
            local _espRenderFrame = 0

            local function UpdateESP(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local espEnabled = (Toggles and Toggles.P1S1T1 and Toggles.P1S1T1.Value == true)
                    or (EspRenderSettings and EspRenderSettings.Enabled == true)

                if not espEnabled then
                    if not ESPObjects._allHidden then
                        for _, entry in pairs(ESPObjects) do
                            HidePlayerEsp(entry)
                        end
                        ESPObjects._allHidden = true
                    end
                    return
                end
                ESPObjects._allHidden = nil

                espUpdateAccumulator = espUpdateAccumulator + (type(deltaTime) == 'number' and deltaTime or (1 / 60))
                if espUpdateAccumulator < (1 / 60) then
                    return
                end
                espUpdateAccumulator = 0
                _espRenderFrame = (_espRenderFrame + 1) % 1000000000

                local now = os.clock()
                if now >= nextEspReconcile then
                    nextEspReconcile = now + 0.05
                    local created = 0
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LP and IsUnder(p, Players) and not ESPObjects[p] then
                            CreatePlayerEspEntry(p)
                            created = created + 1
                            if created >= 6 then
                                nextEspReconcile = now
                                break
                            end
                        end
                    end
                end

                local cam = Workspace.CurrentCamera
                if not cam then return end
                local camPos = cam.CFrame.Position
                local vpSize = cam.ViewportSize
                local centerX, centerY = vpSize.X / 2, vpSize.Y / 2

                local showHighlight = Toggles.P1S1T2 and Toggles.P1S1T2.Value == true
                local showBox = Toggles.P1S2T1 and Toggles.P1S2T1.Value == true
                local boxStyle = (Options.P1S40D1 and Options.P1S40D1.Value) or 'Corner'
                local showNames = Toggles.P1S1T3 and Toggles.P1S1T3.Value == true
                local showHealth = Toggles.P1S1T4 and Toggles.P1S1T4.Value == true
                local verticalHealth = Toggles.P1S1T7 and Toggles.P1S1T7.Value == true
                local showWeapon = Toggles.P1S1T9 and Toggles.P1S1T9.Value == true
                local showAmmo = Toggles.P1S2T2 and Toggles.P1S2T2.Value == true
                local showDistance = Toggles.P1S1T6 and Toggles.P1S1T6.Value == true
                local showLookDir = Toggles.P1S1T8 and Toggles.P1S1T8.Value == true
                local showArrows = Toggles.P1S1T5 and Toggles.P1S1T5.Value == true
                local showTeammates = Toggles.P1S1T10 and Toggles.P1S1T10.Value == true
                local showSkeleton = Toggles.P1S41T1 and Toggles.P1S41T1.Value == true
                local showSnapline = Toggles.P1S41T2 and Toggles.P1S41T2.Value == true
                local showHeadDot = Toggles.P1S41T3 and Toggles.P1S41T3.Value == true

                local visibleColor = (Options.P1S1C1 and Options.P1S1C1.Value) or Color3.fromRGB(0, 255, 100)
                local hiddenColor = (Options.P1S1C2 and Options.P1S1C2.Value) or Color3.fromRGB(255, 40, 40)
                local lookDirColor = (Options.P1S1C4 and Options.P1S1C4.Value) or Color3.fromRGB(255, 255, 0)
                local skeletonColor = (Options.P1S41C1 and Options.P1S41C1.Value) or Color3.fromRGB(255, 255, 255)
                local snaplineColor = (Options.P1S41C2 and Options.P1S41C2.Value) or Color3.fromRGB(255, 255, 255)
                local headDotColor = (Options.P1S41C3 and Options.P1S41C3.Value) or Color3.fromRGB(255, 255, 255)
                local fillAlpha = (Options.P1S1S3 and Options.P1S1S3.Value) or 0.5
                local outlineAlpha = (Options.P1S1S4 and Options.P1S1S4.Value) or 0
                local maxDistance = 1500

                for targetPlayer, entry in pairs(ESPObjects) do
                    local character = targetPlayer.Character
                    local hrp = character and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
                    local humanoid = character and (character:FindFirstChildOfClass("Humanoid") or character:FindFirstChild("Humanoid"))

                    if not character or not hrp or not humanoid or humanoid.Health <= 0 then
                        HidePlayerEsp(entry)
                        continue
                    end

                    local isTeammate = IsTeammate(targetPlayer)
                    if isTeammate and not showTeammates then
                        HidePlayerEsp(entry)
                        continue
                    end

                    local rootPos = hrp.Position
                    local dist = (rootPos - camPos).Magnitude
                    if dist > maxDistance then
                        HidePlayerEsp(entry)
                        continue
                    end

                    if not entry.LastRaycast or (now - entry.LastRaycast) > 0.08 then
                        entry.LastRaycast = now
                        local filterList = {cam, character}
                        if LP.Character then table.insert(filterList, LP.Character) end
                        espRayParams.FilterDescendantsInstances = filterList
                        local rayResult = Workspace:Raycast(camPos, rootPos - camPos, espRayParams)
                        entry.IsVisible = (rayResult == nil)
                    end
                    local isVisible = (entry.IsVisible == true)

                    local currentColor = isTeammate and visibleColor or (isVisible and visibleColor or hiddenColor)

                    local screenPos, onScreen = cam:WorldToViewportPoint(rootPos)

                    if not onScreen or screenPos.Z <= 0 then
                        if not entry._bodyHidden then
                            entry._bodyHidden = true
                            if entry.Highlight and entry.Highlight.Enabled then entry.Highlight.Enabled = false end
                            if entry.BoxOutline and entry.BoxOutline.Visible then entry.BoxOutline.Visible = false end
                            if entry.BoxMain and entry.BoxMain.Visible then entry.BoxMain.Visible = false end
                            if entry.CornerLines then for _, l in ipairs(entry.CornerLines) do if l.Visible then l.Visible = false end end end
                            if entry.SkeletonLines then for _, l in ipairs(entry.SkeletonLines) do if l.Visible then l.Visible = false end end end
                            if entry.NameText and entry.NameText.Visible then entry.NameText.Visible = false end
                            if entry.HealthBarBg and entry.HealthBarBg.Visible then entry.HealthBarBg.Visible = false end
                            if entry.HealthBarFill and entry.HealthBarFill.Visible then entry.HealthBarFill.Visible = false end
                            if entry.HealthText and entry.HealthText.Visible then entry.HealthText.Visible = false end
                            if entry.WeaponText and entry.WeaponText.Visible then entry.WeaponText.Visible = false end
                            if entry.AmmoText and entry.AmmoText.Visible then entry.AmmoText.Visible = false end
                            if entry.DistanceText and entry.DistanceText.Visible then entry.DistanceText.Visible = false end
                            if entry.LookLine and entry.LookLine.Visible then entry.LookLine.Visible = false end
                            if entry.Snapline and entry.Snapline.Visible then entry.Snapline.Visible = false end
                            if entry.HeadDot and entry.HeadDot.Visible then entry.HeadDot.Visible = false end
                        end

                        if showArrows and entry.Arrow1 and entry.Arrow2 and entry.Arrow3 then
                            local dir = cam.CFrame:VectorToObjectSpace(rootPos - camPos)
                            local angle = math.atan2(dir.X, -dir.Z)
                            local edgeDist = math.min(vpSize.X, vpSize.Y) * 0.42
                            local arrowCenter = Vector2.new(centerX + math.sin(angle) * edgeDist, centerY - math.cos(angle) * edgeDist)
                            local forward = Vector2.new(math.sin(angle), -math.cos(angle))
                            local right = Vector2.new(-forward.Y, forward.X)
                            local tip = arrowCenter + (forward * 14)
                            local baseCenter = arrowCenter - (forward * 14)
                            local leftP = baseCenter - (right * 9)
                            local rightP = baseCenter + (right * 9)

                            entry.Arrow1.From = leftP
                            entry.Arrow1.To = tip
                            entry.Arrow1.Color = currentColor
                            entry.Arrow1.Visible = true

                            entry.Arrow2.From = tip
                            entry.Arrow2.To = rightP
                            entry.Arrow2.Color = currentColor
                            entry.Arrow2.Visible = true

                            entry.Arrow3.From = rightP
                            entry.Arrow3.To = leftP
                            entry.Arrow3.Color = currentColor
                            entry.Arrow3.Visible = true
                        else
                            if entry.Arrow1 then entry.Arrow1.Visible = false end
                            if entry.Arrow2 then entry.Arrow2.Visible = false end
                            if entry.Arrow3 then entry.Arrow3.Visible = false end
                        end
                        continue
                    end

                    entry._allHidden = nil
                    entry._bodyHidden = nil
                    if entry.Arrow1 and entry.Arrow1.Visible then entry.Arrow1.Visible = false end
                    if entry.Arrow2 and entry.Arrow2.Visible then entry.Arrow2.Visible = false end
                    if entry.Arrow3 and entry.Arrow3.Visible then entry.Arrow3.Visible = false end

                    if entry.Highlight then
                        if showHighlight then
                            if entry.Highlight.Parent ~= HighlightContainer then
                                pcall(function()
                                    entry.Highlight.Parent = HighlightContainer
                                end)
                            end
                            entry.Highlight.Adornee = character
                            entry.Highlight.FillColor = currentColor
                            entry.Highlight.OutlineColor = Color3.new(0, 0, 0)
                            entry.Highlight.FillTransparency = fillAlpha
                            entry.Highlight.OutlineTransparency = outlineAlpha
                            entry.Highlight.Enabled = true
                        else
                            entry.Highlight.Enabled = false
                        end
                    end

                    local head = character:FindFirstChild("Head") or character:FindFirstChild("HitboxHead")
                    local headPos = head and head.Position or (rootPos + Vector3.new(0, 2, 0))
                    local feetPos = rootPos - Vector3.new(0, 3, 0)

                    local boxX, boxY, boxWidth, boxHeight, top2d, bottom2d
                    if entry.BBoxFrame == _espRenderFrame and entry.BBox then
                        local bb = entry.BBox
                        boxX, boxY, boxWidth, boxHeight, top2d, bottom2d = bb[1], bb[2], bb[3], bb[4], bb[5], bb[6]
                    else
                        top2d = cam:WorldToViewportPoint(headPos + Vector3.new(0, 0.6, 0))
                        bottom2d = cam:WorldToViewportPoint(feetPos)
                        boxHeight = math.abs(bottom2d.Y - top2d.Y)
                        boxWidth = boxHeight * 0.55
                        boxX = top2d.X - (boxWidth / 2)
                        boxY = top2d.Y
                        entry.BBoxFrame = _espRenderFrame
                        entry.BBox = { boxX, boxY, boxWidth, boxHeight, top2d, bottom2d }
                    end

                    if showBox then
                        if boxStyle == 'Corner' then
                            if entry.BoxMain then entry.BoxMain.Visible = false end
                            if entry.BoxOutline then entry.BoxOutline.Visible = false end
                            if entry.CornerLines and #entry.CornerLines == 8 then
                                local cornerLen = math.clamp(boxWidth * 0.25, 4, 16)
                                local x1, y1 = boxX, boxY
                                local x2, y2 = boxX + boxWidth, boxY + boxHeight

                                entry.CornerLines[1].From = Vector2.new(x1, y1)
                                entry.CornerLines[1].To = Vector2.new(x1 + cornerLen, y1)
                                entry.CornerLines[2].From = Vector2.new(x1, y1)
                                entry.CornerLines[2].To = Vector2.new(x1, y1 + cornerLen)

                                entry.CornerLines[3].From = Vector2.new(x2, y1)
                                entry.CornerLines[3].To = Vector2.new(x2 - cornerLen, y1)
                                entry.CornerLines[4].From = Vector2.new(x2, y1)
                                entry.CornerLines[4].To = Vector2.new(x2, y1 + cornerLen)

                                entry.CornerLines[5].From = Vector2.new(x1, y2)
                                entry.CornerLines[5].To = Vector2.new(x1 + cornerLen, y2)
                                entry.CornerLines[6].From = Vector2.new(x1, y2)
                                entry.CornerLines[6].To = Vector2.new(x1, y2 - cornerLen)

                                entry.CornerLines[7].From = Vector2.new(x2, y2)
                                entry.CornerLines[7].To = Vector2.new(x2 - cornerLen, y2)
                                entry.CornerLines[8].From = Vector2.new(x2, y2)
                                entry.CornerLines[8].To = Vector2.new(x2, y2 - cornerLen)

                                for _, l in ipairs(entry.CornerLines) do
                                    l.Color = currentColor
                                    l.Visible = true
                                end
                            end
                        else
                            if entry.CornerLines then
                                for _, l in ipairs(entry.CornerLines) do l.Visible = false end
                            end
                            if entry.BoxOutline then
                                entry.BoxOutline.Position = Vector2.new(boxX - 1, boxY - 1)
                                entry.BoxOutline.Size = Vector2.new(boxWidth + 2, boxHeight + 2)
                                entry.BoxOutline.Visible = true
                            end
                            if entry.BoxMain then
                                entry.BoxMain.Position = Vector2.new(boxX, boxY)
                                entry.BoxMain.Size = Vector2.new(boxWidth, boxHeight)
                                entry.BoxMain.Color = currentColor
                                entry.BoxMain.Visible = true
                            end
                        end
                    else
                        if entry.BoxMain then entry.BoxMain.Visible = false end
                        if entry.BoxOutline then entry.BoxOutline.Visible = false end
                        if entry.CornerLines then for _, l in ipairs(entry.CornerLines) do l.Visible = false end end
                    end

                    if showSkeleton then
                        if not entry.SkeletonLines or #entry.SkeletonLines == 0 then
                            entry.SkeletonLines = {}
                            for i = 1, #SKELETON_CONNECTIONS do
                                local l = SafeDrawing('Line')
                                if l then
                                    l.Thickness = 1
                                    l.Color = Color3.fromRGB(255, 255, 255)
                                    l.Visible = false
                                    table.insert(entry.SkeletonLines, l)
                                end
                            end
                        end
                    end
                    if showSkeleton and entry.SkeletonLines then
                        for idx, conn in ipairs(SKELETON_CONNECTIONS) do
                            local line = entry.SkeletonLines[idx]
                            if line then
                                local p1 = character:FindFirstChild(conn[1])
                                local p2 = character:FindFirstChild(conn[2])
                                if p1 and p2 then
                                    local s1, v1 = cam:WorldToViewportPoint(p1.Position)
                                    local s2, v2 = cam:WorldToViewportPoint(p2.Position)
                                    if v1 and v2 and s1.Z > 0 and s2.Z > 0 then
                                        line.From = Vector2.new(s1.X, s1.Y)
                                        line.To = Vector2.new(s2.X, s2.Y)
                                        line.Color = skeletonColor
                                        line.Visible = true
                                    else
                                        line.Visible = false
                                    end
                                else
                                    line.Visible = false
                                end
                            end
                        end
                    else
                        if entry.SkeletonLines then
                            for _, l in ipairs(entry.SkeletonLines) do l.Visible = false end
                        end
                    end

                    if showNames and entry.NameText then
                        entry.NameText.Position = Vector2.new(boxX + (boxWidth / 2), boxY - 16)
                        entry.NameText.Text = targetPlayer.DisplayName or targetPlayer.Name
                        entry.NameText.Visible = true
                    else
                        if entry.NameText then entry.NameText.Visible = false end
                    end

                    if showHealth and entry.HealthBarBg and entry.HealthBarFill then
                        local maxHp = (humanoid.MaxHealth and humanoid.MaxHealth > 0) and humanoid.MaxHealth or 100
                        local hp = math.clamp(humanoid.Health, 0, maxHp)
                        local hpPct = hp / maxHp
                        entry.SmoothHp = entry.SmoothHp + ((hpPct - entry.SmoothHp) * 0.15)
                        local smoothRatio = math.clamp(entry.SmoothHp, 0, 1)
                        local hpColor = Color3.fromHSV(smoothRatio * 0.33, 0.9, 0.9)

                        if verticalHealth then
                            local barWidth = 3
                            local barX = boxX - barWidth - 4
                            entry.HealthBarBg.Position = Vector2.new(barX, boxY)
                            entry.HealthBarBg.Size = Vector2.new(barWidth, boxHeight)
                            entry.HealthBarBg.Visible = true

                            local fillHeight = boxHeight * smoothRatio
                            entry.HealthBarFill.Position = Vector2.new(barX, boxY + (boxHeight - fillHeight))
                            entry.HealthBarFill.Size = Vector2.new(barWidth, fillHeight)
                            entry.HealthBarFill.Color = hpColor
                            entry.HealthBarFill.Visible = true

                            if entry.HealthText then
                                entry.HealthText.Position = Vector2.new(barX - 22, boxY + (boxHeight - fillHeight) - 4)
                                entry.HealthText.Text = tostring(math.floor(hp))
                                entry.HealthText.Color = hpColor
                                entry.HealthText.Visible = (smoothRatio < 0.98)
                            end
                        else
                            local barHeight = 3
                            local barY = boxY + boxHeight + 4
                            entry.HealthBarBg.Position = Vector2.new(boxX, barY)
                            entry.HealthBarBg.Size = Vector2.new(boxWidth, barHeight)
                            entry.HealthBarBg.Visible = true

                            local fillWidth = boxWidth * smoothRatio
                            entry.HealthBarFill.Position = Vector2.new(boxX, barY)
                            entry.HealthBarFill.Size = Vector2.new(fillWidth, barHeight)
                            entry.HealthBarFill.Color = hpColor
                            entry.HealthBarFill.Visible = true

                            if entry.HealthText then
                                entry.HealthText.Position = Vector2.new(boxX + fillWidth + 4, barY - 4)
                                entry.HealthText.Text = tostring(math.floor(hp))
                                entry.HealthText.Color = hpColor
                                entry.HealthText.Visible = (smoothRatio < 0.98)
                            end
                        end
                    else
                        if entry.HealthBarBg then entry.HealthBarBg.Visible = false end
                        if entry.HealthBarFill then entry.HealthBarFill.Visible = false end
                        if entry.HealthText then entry.HealthText.Visible = false end
                    end

                    local bottomOffset = (showHealth and not verticalHealth) and 10 or 2
                    if showWeapon and entry.WeaponText then
                        local wep = GetPlayerEquippedWeapon(character)
                        if wep ~= "" then
                            entry.WeaponText.Position = Vector2.new(boxX + (boxWidth / 2), boxY + boxHeight + bottomOffset)
                            entry.WeaponText.Text = wep
                            entry.WeaponText.Visible = true
                            bottomOffset = bottomOffset + 14
                        else
                            entry.WeaponText.Visible = false
                        end
                    else
                        if entry.WeaponText then entry.WeaponText.Visible = false end
                    end

                    if showAmmo and entry.AmmoText then
                        entry.AmmoText.Position = Vector2.new(boxX + (boxWidth / 2), boxY + boxHeight + bottomOffset)
                        entry.AmmoText.Visible = false
                    else
                        if entry.AmmoText then entry.AmmoText.Visible = false end
                    end

                    if showDistance and entry.DistanceText then
                        entry.DistanceText.Position = Vector2.new(boxX + (boxWidth / 2), boxY + boxHeight + bottomOffset)
                        entry.DistanceText.Text = string.format("[%dm]", math.floor(dist))
                        entry.DistanceText.Visible = true
                        bottomOffset = bottomOffset + 14
                    else
                        if entry.DistanceText then entry.DistanceText.Visible = false end
                    end

                    if showLookDir and head and entry.LookLine then
                        local lookVector = head.CFrame.LookVector
                        local endPoint3d = head.Position + (lookVector * 5.5)
                        local endScreen, endOnScreen = cam:WorldToViewportPoint(endPoint3d)
                        local headScreen = cam:WorldToViewportPoint(head.Position)
                        if endOnScreen and endScreen.Z > 0 and headScreen.Z > 0 then
                            entry.LookLine.From = Vector2.new(headScreen.X, headScreen.Y)
                            entry.LookLine.To = Vector2.new(endScreen.X, endScreen.Y)
                            entry.LookLine.Color = lookDirColor
                            entry.LookLine.Visible = true
                        else
                            entry.LookLine.Visible = false
                        end
                    else
                        if entry.LookLine then entry.LookLine.Visible = false end
                    end

                    if showSnapline and entry.Snapline then
                        local snapOrigin = (Options.P1S41D2 and Options.P1S41D2.Value) or 'Bottom'
                        local originPos = snapOrigin == 'Top' and Vector2.new(centerX, 0)
                            or (snapOrigin == 'Center' and Vector2.new(centerX, centerY)
                            or Vector2.new(centerX, vpSize.Y))
                        entry.Snapline.From = originPos
                        entry.Snapline.To = Vector2.new(boxX + (boxWidth / 2), boxY + boxHeight)
                        entry.Snapline.Color = snaplineColor
                        entry.Snapline.Visible = true
                    else
                        if entry.Snapline then entry.Snapline.Visible = false end
                    end

                    if showHeadDot and entry.HeadDot then
                        entry.HeadDot.Position = Vector2.new(top2d.X, top2d.Y + 2)
                        entry.HeadDot.Color = headDotColor
                        entry.HeadDot.Visible = true
                    else
                        if entry.HeadDot then entry.HeadDot.Visible = false end
                    end
                end
            end
            RivalsRuntimeBridge.UpdateESP = UpdateESP
            RivalsRuntimeBridge.AimbotBridge = AimbotBridge
            RivalsRuntimeBridge.ESPClassic.RegisterHitFlash = function(character)
                local player = Players:GetPlayerFromCharacter(character)
                local entry = player and ESPObjects[player]
                if entry then
                    entry.hitFlashAt = tick()
                end
            end

            RivalsRuntimeBridge.CharacterLoadingState = {}
            RivalsRuntimeBridge.DiagnosticLogState = {LastByMessage = {}, ThrottleSeconds = 2}
            RivalsRuntimeBridge.InitialSpawnCooldownComplete = false
            RivalsRuntimeBridge.MatchBoundaryDetectionInstalled = false

            RivalsRuntimeBridge.LocalReadyState = {
                ShieldSeen = false,
                LastSeenFighter = nil,
                ReadyNotified = false,
                InitialLifeAdoptionOpen = true,
            }

            RivalsRuntimeBridge.ResetLocalShieldLatch = function()
                local state = RivalsRuntimeBridge.LocalReadyState
                state.ShieldSeen = false
                state.LastSeenFighter = nil
                state.ReadyNotified = false
                state.InitialLifeAdoptionOpen = true
            end

            RivalsRuntimeBridge.NotifyLocalReadyOnce = function(source)
                local state = RivalsRuntimeBridge.LocalReadyState
                if state.ReadyNotified then
                    return
                end
                state.ReadyNotified = true
                RivalsRuntimeBridge.LogDiagnosticEvent('Ready', 'Loaded -- ready to fight (' .. tostring(source) .. ')')
            end

            RivalsRuntimeBridge.IsLocalReadyToFight = function()
                if not IsAimbotGameReady() then
                    return false
                end

                local duel = FighterDataCache.LocalDuel
                if duel and duel.Seeded and duel.IsInShootingRange == true then
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('shooting range')
                    return true
                end

                local state = RivalsRuntimeBridge.LocalReadyState
                if state.ShieldSeen then
                    return true
                end

                local fighter = ResolveLocalFighter()
                if not fighter then
                    if LP.Character and LP.Character.Parent then
                        local hum = LP.Character:FindFirstChildOfClass('Humanoid')
                        if not hum or hum.Health > 0 then
                            return true
                        end
                    end
                    return false
                end

                if type(fighter.Data) == 'table' and fighter.Data.IsInShootingRange == true then
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('shooting range (sync)')
                    return true
                end

                if state.LastSeenFighter ~= fighter then
                    state.LastSeenFighter = fighter
                end

                local entity = fighter.Entity
                if entity and type(entity.Data) == 'table' and entity.Data.IsInvincible == true then
                    state.ShieldSeen = true
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('spawn shield')
                    return true
                end

                if FighterDataCache.Cache[fighter] == true then
                    state.ShieldSeen = true
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('spawn shield (cache)')
                    return true
                end

                if state.InitialLifeAdoptionOpen then
                    if type(entity) == 'table' and rawget(entity, '_is_in_world') == true
                        and rawget(fighter, 'EquippedItem') ~= nil then
                        state.InitialLifeAdoptionOpen = false
                        state.ShieldSeen = true
                        RivalsRuntimeBridge.NotifyLocalReadyOnce('mid-life adopt (equipped item)')
                        return true
                    end
                end

                local model = entity and entity.Model
                local inWorld = type(entity) == 'table' and rawget(entity, '_is_in_world') == true
                if not inWorld and model and model == LP.Character and model.Parent then
                    inWorld = true
                end
                if inWorld then
                    local equipped = rawget(fighter, 'EquippedItem') ~= nil
                    local alive = Humanoid and Humanoid.Health > 0
                    if equipped or alive then
                        state.ShieldSeen = true
                        RivalsRuntimeBridge.NotifyLocalReadyOnce('in-world fighter')
                        return true
                    end
                end

                return false
            end

            RivalsRuntimeBridge.WaitForLocalReady = function(timeoutSec)
                local deadline = timeoutSec and (tick() + math.min(timeoutSec, 2)) or (tick() + 1)
                while not shutting_down and __akira_boot_alive() do
                    local okReady, isReady = pcall(RivalsRuntimeBridge.IsLocalReadyToFight)
                    if okReady and isReady then
                        return true
                    end
                    if tick() > deadline then
                        return false
                    end
                    task.wait(0.1)
                end
                return false
            end

            RivalsRuntimeBridge.EnsureMatchBoundaryDetection = function()
                if RivalsRuntimeBridge.MatchBoundaryDetectionInstalled then
                    return
                end

                local controller = ResolveFighterController()
                if not controller then
                    return
                end

                local addedSignal = controller.ObjectAdded
                if type(addedSignal) ~= 'table' or type(addedSignal.Connect) ~= 'function' then
                    return
                end

                local ok, conn = pcall(function()
                    return addedSignal:Connect(function(newFighter)
                        if type(newFighter) ~= 'table' then
                            return
                        end
                        local isLocal = newFighter.IsLocalPlayer == true
                            or rawget(newFighter, 'Player') == LP
                        if not isLocal then
                            return
                        end
                        RivalsRuntimeBridge.InitialSpawnCooldownComplete = false
                        RivalsRuntimeBridge.ResetLocalShieldLatch()
                        __akira_boot_log('Match: new local fighter (spawn/map transition)')
                        RivalsRuntimeBridge.LogDiagnosticEvent(
                            'MatchBoundary',
                            'New local fighter detected; readiness latch reset'
                        )
                        if RivalsRuntimeBridge.RunPickupSpawnSetup then
                            RivalsRuntimeBridge.RunPickupSpawnSetup()
                        end
                    end)
                end)

                if ok and conn then
                    if Library and type(Library.GiveSignal) == 'function' then
                        pcall(function() Library:GiveSignal(conn) end)
                    end
                    RivalsRuntimeBridge.MatchBoundaryDetectionInstalled = true
                    if controller.LocalFighter and RivalsRuntimeBridge.RunPickupSpawnSetup then
                        RivalsRuntimeBridge.RunPickupSpawnSetup()
                    end
                end
            end

            RivalsRuntimeBridge.LogDiagnosticEvent = function(scope, message)
                if not (Toggles.P9S3T1 and Toggles.P9S3T1.Value == true) then
                    return
                end

                local now = tick()
                local key = tostring(scope) .. '|' .. tostring(message)
                local state = RivalsRuntimeBridge.DiagnosticLogState
                local last = state.LastByMessage[key]
                if last and (now - last) < state.ThrottleSeconds then
                    return
                end
                state.LastByMessage[key] = now

                if Library and type(Library.Notify) == 'function' then
                    pcall(function()
                        Library:Notify({
                            Title = 'Character Loading Check',
                            Description = string.format('[%s] %s', tostring(scope), tostring(message)),
                            Time = 3,
                        })
                    end)
                end
            end

            RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint = function(featureName, isReady, isEnabled)
                local state = RivalsRuntimeBridge.CharacterLoadingState
                local wasReady = state[featureName] == true
                state[featureName] = isReady

                if not isReady or not isEnabled or wasReady then
                    return
                end

                if not (Toggles.P9S3T1 and Toggles.P9S3T1.Value == true) then
                    return
                end

                if Library and type(Library.Notify) == 'function' then
                    pcall(function()
                        Library:Notify({
                            Title = 'Character Loading Check',
                            Description = featureName .. ' ready',
                            Time = 3,
                        })
                    end)
                end
            end

            RivalsRuntimeBridge.IsReadyToFight = function()
                local camera = Workspace.CurrentCamera
                if not camera then
                    return false
                end
                local char = LP and LP.Character
                if not char or not char.Parent then
                    return false
                end
                local hum = char:FindFirstChildOfClass('Humanoid') or char:FindFirstChild('Humanoid')
                if hum and hum.Health <= 0 then
                    return false
                end
                return true
            end

            RivalsRuntimeBridge.AcquireActiveCharacter = function()
                if not RivalsRuntimeBridge.IsReadyToFight() then
                    return nil
                end
                if LP.Character ~= Char then
                    return nil
                end
                if not HumanoidRootPart or HumanoidRootPart.Parent ~= Char then
                    return nil
                end
                return Char, HumanoidRootPart, Humanoid
            end
            end)()

