            }

            local SAFE_FLOOR = 2
            local SAFE_MAX_RISE = 800

            local function tog(id)
                local t = Toggles[id]
                return t ~= nil and t.Value == true
            end

            local function opt(id, fallback)
                local o = Options[id]
                if o ~= nil and o.Value ~= nil then
                    return o.Value
                end
                return fallback
            end

            local function setOpt(id, value)
                local o = Options[id]
                if o and type(o.SetValue) == 'function' then
                    pcall(function()
                        o:SetValue(value)
                    end)
                end
            end

            local function setTog(id, value)
                local t = Toggles[id]
                if t and type(t.SetValue) == 'function' then
