            local function getHrp()
                local char = LP and LP.Character
                if not char then
                    return nil, nil, nil
                end
                return char:FindFirstChild('HumanoidRootPart'), char, char:FindFirstChildOfClass('Humanoid')
            end

            local function getSpoof()
                return RivalsRuntimeBridge and RivalsRuntimeBridge.CameraSpoof
            end

            local function clientCFrame(hrp)
                local spoof = getSpoof()
                local cf = spoof and spoof.GetClientCFrame and spoof.GetClientCFrame()
                if typeof(cf) == 'CFrame' then
                    return cf
                end
                return hrp and hrp.CFrame
            end

            local function liveServerCFrame(hrp)
                local spoof = getSpoof()
                local cf = spoof and spoof.GetServerCFrame and spoof.GetServerCFrame()
                if typeof(cf) == 'CFrame' then
                    return cf
                end
                return clientCFrame(hrp)
            end

            local function spoofCFrame(hrp, cf)
                if not hrp or typeof(cf) ~= 'CFrame' then
                    return
                end
                local spoof = getSpoof()
                if spoof and spoof.SetServerCFrame then
                    if spoof.Ensure then
                        spoof.Ensure(hrp)
                    end
                    spoof.SetServerCFrame(cf, hrp)
                    return
                end
                hrp.CFrame = cf
            end

            local function spoofClear(hrp)
                local spoof = getSpoof()
                if spoof and spoof.SetServerCFrame then
                    if hrp and spoof.Ensure then
                        spoof.Ensure(hrp)
                    end
                    spoof.SetServerCFrame(nil, hrp)
                end
            end

            local function spoofPosition(hrp, pos)
                if not hrp or typeof(pos) ~= 'Vector3' then
                    return
                end
                local live = liveServerCFrame(hrp)
                local rot = live - live.Position
                spoofCFrame(hrp, CFrame.new(pos) * rot)
            end

            local function clearRootMotion(hrp)
                if not hrp then
                    return
                end
                pcall(function()
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end)
            end

            function Hvh.ResetVoidPattern()
                Hvh.VoidX = (math.random() * 2 - 1) * 1e8
                Hvh.VoidZ = (math.random() * 2 - 1) * 1e8
                Hvh.VoidYOffset = 0
                Hvh.VoidYDir = 1
                Hvh.VoidDirX = math.random() * 2 - 1
                Hvh.VoidDirZ = math.random() * 2 - 1
                Hvh.VoidElapsed = 0
                Hvh.VoidYBase = 1e10 + (math.random() * 2 - 1) * 5e9
                Hvh.LuaBasePos = Vector3.new(0, Hvh.VoidYBase, 0)
                Hvh.LuaVoidPos = Vector3.new(Hvh.VoidX, Hvh.VoidYBase, Hvh.VoidZ)
                local drift = Vector3.new(Hvh.VoidDirX, 0.15, Hvh.VoidDirZ)
                if drift.Magnitude < 0.001 then
                    Hvh.LuaDriftDir = Vector3.new(1, 0, 0)
                else
                    Hvh.LuaDriftDir = drift.Unit
                end
                Hvh.VoidEvadeCD = 0
            end

            Hvh.ResetVoidPattern()

            local function rawVoidTeleport(hrp, pos)
                if not hrp then
                    return
                end
                local now = tick()
                if now - Hvh.LastVelocityClear > 0.2 then
                    Hvh.LastVelocityClear = now
                    clearRootMotion(hrp)
                end
                spoofPosition(hrp, pos)
            end

            local function safeTeleport(hrp, char, pos)
                if not hrp then
                    return
                end
                local client = clientCFrame(hrp)
                local x = pos.X
                local y = math.clamp(pos.Y, SAFE_FLOOR, (client and client.Position.Y or hrp.Position.Y) + SAFE_MAX_RISE)
                local z = pos.Z
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = char and { char } or {}
                local hit = workspace:Raycast(Vector3.new(x, y + 500, z), Vector3.new(0, -1000, 0), params)
                if hit then
                    y = math.max(hit.Position.Y + 3, SAFE_FLOOR)
                end
                clearRootMotion(hrp)
                spoofPosition(hrp, Vector3.new(x, y, z))
            end

            local function getVoidHidePosition(hrp)
                local origin = clientCFrame(hrp)
                local pos = origin and origin.Position or hrp.Position
                return Vector3.new(pos.X + 2e15, 999999, pos.Z + 2e15)
            end

            local function getDirectionalLimitOffset(distance)
                local plusX = opt('P8S11S1', 200000)
                local minusX = opt('P8S11S2', 200000)
                local plusY = opt('P8S11S3', 200000)
                local minusY = opt('P8S11S4', 200000)
                local plusZ = opt('P8S11S5', 200000)
                local minusZ = opt('P8S11S6', 200000)
                local raw = Vector3.new(
                    -minusX + math.random() * (minusX + plusX),
                    -minusY + math.random() * (minusY + plusY),
                    -minusZ + math.random() * (minusZ + plusZ)
                )
                if raw.Magnitude <= 0 then
                    return Vector3.zero
                end
                return raw.Unit * math.min(raw.Magnitude, distance)
            end

            local function computeVoidDriftDir(t)
                local nx, nz, amplitude, frequency = 0, 0, 1, 0.0001
                for _ = 1, 4 do
                    nx = nx + math.noise(t * frequency, 0) * amplitude
                    nz = nz + math.noise(0, t * frequency) * amplitude
                    frequency = frequency * 2.37
                    amplitude = amplitude * 0.5
                end
                nx = nx + math.sin(t * 0.00213) * math.cos(t * 0.00344) * 0.2
                nz = nz + math.cos(t * 0.00131) * math.sin(t * 0.00579) * 0.2
                local len = math.sqrt(nx * nx + nz * nz)
                if len < 0.001 then
                    return math.cos(t * 0.1), math.sin(t * 0.1)
                end
                return nx / len, nz / len
            end

            local function computeVoidDriftDir3D(t)
                local nx, ny, nz, amplitude, frequency = 0, 0, 0, 1, 0.0001
                for _ = 1, 4 do
                    nx = nx + math.noise(t * frequency, 0, 0) * amplitude
                    ny = ny + math.noise(0, t * frequency, 0) * amplitude
                    nz = nz + math.noise(0, 0, t * frequency) * amplitude
                    frequency = frequency * 2.37
                    amplitude = amplitude * 0.5
                end
                local sp, cp = t * 0.00073, t * 0.00213
                nx = nx + math.noise(sp + 13.7, 7.3, 0) * 0.3 + math.sin(cp) * math.cos(cp * 1.618) * 0.2
                ny = ny + math.noise(0, sp + 31.1, 17.9) * 0.3 + math.cos(cp * 0.618) * math.sin(cp * 2.718) * 0.2
                nz = nz + math.noise(7.3, 0, sp + 11.5) * 0.3 + math.sin(cp * 1.3) * math.cos(cp * 0.7) * 0.2
                local len = math.sqrt(nx * nx + ny * ny + nz * nz)
                if len < 0.001 then
                    return Vector3.new(1, 0, 0)
                end
                return Vector3.new(nx / len, ny / len, nz / len)
            end

            local function clampLuaVoid(pos, radius)
                local delta = pos - Hvh.LuaBasePos
                if delta.Magnitude > radius then
                    return Hvh.LuaBasePos + delta.Unit * radius
                end
                return pos
            end

            local function getFarVoidPosition(dt, distance, pattern)
                Hvh.VoidElapsed = Hvh.VoidElapsed + dt
                local elapsed = Hvh.VoidElapsed
                local voidX, voidZ, voidYBase = Hvh.VoidX, Hvh.VoidZ, Hvh.VoidYBase

                if pattern == 'Still Point' then
                    return Vector3.new(voidX, voidYBase + Hvh.VoidYOffset, voidZ)
                elseif pattern == 'Slow Drift' then
                    local dx, dz = computeVoidDriftDir(elapsed)
                    Hvh.VoidDirX = Hvh.VoidDirX + (dx - Hvh.VoidDirX) * Hvh.VoidChaos * dt * 10
                    Hvh.VoidDirZ = Hvh.VoidDirZ + (dz - Hvh.VoidDirZ) * Hvh.VoidChaos * dt * 10
                    Hvh.VoidX = Hvh.VoidX + Hvh.VoidDirX * Hvh.VoidDriftSpeed * dt
                    Hvh.VoidZ = Hvh.VoidZ + Hvh.VoidDirZ * Hvh.VoidDriftSpeed * dt
                    Hvh.VoidYOffset = Hvh.VoidYOffset + Hvh.VoidYDir * Hvh.VoidYDriftSpeed * dt
                    if math.abs(Hvh.VoidYOffset) >= Hvh.VoidYDriftRange then
                        Hvh.VoidYDir = -Hvh.VoidYDir
                    end
                    return Vector3.new(Hvh.VoidX, voidYBase + Hvh.VoidYOffset, Hvh.VoidZ)
                elseif pattern == 'Circle' then
                    local r = math.max(distance * 1000, 1e9) * (1 + math.sin(elapsed))
                    return Vector3.new(voidX + math.cos(elapsed * 3) * r, voidYBase + Hvh.VoidYOffset, voidZ + math.sin(elapsed * 3) * r)
                elseif pattern == 'Figure Eight' then
                    local r = math.max(distance * 2000, 2e9)
                    return Vector3.new(voidX + math.sin(elapsed * 2) * r, voidYBase + math.sin(elapsed * 4) * r * 0.1, voidZ + math.sin(elapsed * 3) * r)
                elseif pattern == 'Wide Sweep' then
                    local t = elapsed * 15
                    local r = math.max(distance * 10000, 1e10)
                    return Vector3.new(voidX + math.sin(t) * r, voidYBase + math.cos(t * 1.5) * r * 0.1, voidZ + math.cos(t) * r)
                elseif pattern == 'Fast Bounce' then
                    local t = elapsed * 50
                    local r = math.max(distance * 10000, 1e10) * math.sin(t)
                    return Vector3.new(voidX + r, voidYBase + math.cos(t) * 1e10, voidZ + r)
                elseif pattern == 'Blink' then
                    if tick() % 0.1 < 0.05 then
                        return Vector3.new(voidX * 2, voidYBase + 1e11, voidZ * 2)
                    end
                    return Vector3.new(voidX, voidYBase, voidZ)
                elseif pattern == 'Grid Hop' then
                    local cell = math.max(distance * 5000, 5e8)
                    local step = math.floor(elapsed * 8)
                    local gx = (step % 5) - 2
                    local gz = (math.floor(step / 5) % 5) - 2
                    local gy = (step % 2 == 0) and 0 or cell * 0.18
                    return Vector3.new(voidX + gx * cell, voidYBase + gy, voidZ + gz * cell)
                elseif pattern == 'Height Wave' then
                    local t = elapsed * 6
                    local r = math.max(distance * 3000, 2e9)
                    return Vector3.new(voidX + math.cos(t * 0.4) * r, voidYBase + math.sin(t) * r * 0.35, voidZ + math.sin(t * 0.4) * r)
                elseif pattern == 'Square Loop' then
                    local r = math.max(distance * 4000, 3e9)
                    local t = (elapsed * 1.8) % 4
                    local side = math.floor(t)
                    local a = t - side
                    local x, z
                    if side == 0 then
                        x, z = -r + a * 2 * r, -r
                    elseif side == 1 then
                        x, z = r, -r + a * 2 * r
                    elseif side == 2 then
                        x, z = r - a * 2 * r, r
                    else
                        x, z = -r, r - a * 2 * r
                    end
                    return Vector3.new(voidX + x, voidYBase + math.sin(elapsed * 8) * r * 0.05, voidZ + z)
                elseif pattern == 'Cross Sweep' then
                    local r = math.max(distance * 6000, 4e9)
                    local t = elapsed * 4
                    local axis = math.floor(t) % 4
                    local a = math.sin(t * math.pi) * r
                    if axis == 0 then
                        return Vector3.new(voidX + a, voidYBase, voidZ)
                    elseif axis == 1 then
                        return Vector3.new(voidX, voidYBase + math.sin(t) * r * 0.08, voidZ + a)
                    elseif axis == 2 then
                        return Vector3.new(voidX - a, voidYBase, voidZ)
                    end
                    return Vector3.new(voidX, voidYBase - math.sin(t) * r * 0.08, voidZ - a)
                elseif pattern == 'Stacked Steps' then
                    local cell = math.max(distance * 3500, 2e9)
                    local step = math.floor(elapsed * 7)
                    local x = ((step % 7) - 3) * cell
                    local z = ((math.floor(step / 7) % 7) - 3) * cell
                    local y = (step % 5) * cell * 0.12
                    return Vector3.new(voidX + x, voidYBase + y, voidZ + z)
                elseif pattern == 'Noise Cloud' then
                    local r = math.max(distance * 5000, 4e9)
                    local t = elapsed * 1.5
                    return Vector3.new(voidX + math.noise(t, 0, 0) * r, voidYBase + math.noise(0, t, 0) * r * 0.25, voidZ + math.noise(0, 0, t) * r)
                elseif pattern == 'Drift 3D' or pattern == 'Chaos' or pattern == 'Loop' or pattern == 'Spiral' or pattern == 'Quantum' then
                    local radius = math.max(distance * 4000, 2e9)
                    local speed = math.max(Hvh.VoidDriftSpeed, 1e9)
                    if not Hvh.LuaBasePos or Hvh.LuaBasePos.Y == 0 then
                        Hvh.LuaBasePos = Vector3.new(0, voidYBase, 0)
                        Hvh.LuaVoidPos = Vector3.new(voidX, voidYBase, voidZ)
                    end
                    if pattern == 'Drift 3D' then
                        local dir = computeVoidDriftDir3D(elapsed)
                        Hvh.LuaDriftDir = Hvh.LuaDriftDir:Lerp(dir, Hvh.VoidChaos * dt * 10)
                        if Hvh.LuaDriftDir.Magnitude < 0.001 then
                            Hvh.LuaDriftDir = Vector3.new(1, 0, 0)
                        else
                            Hvh.LuaDriftDir = Hvh.LuaDriftDir.Unit
                        end
                        Hvh.LuaVoidPos = clampLuaVoid(Hvh.LuaVoidPos + Hvh.LuaDriftDir * speed * dt, radius)
                        if (Hvh.LuaVoidPos - Hvh.LuaBasePos).Magnitude >= radius * 0.98 then
                            Hvh.LuaDriftDir = -Hvh.LuaDriftDir
                        end
                        return Hvh.LuaVoidPos
                    elseif pattern == 'Chaos' then
                        Hvh.LuaVoidPos = clampLuaVoid(Hvh.LuaVoidPos + Vector3.new(
                            (math.random() - 0.5) * speed * dt * 5,
                            (math.random() - 0.5) * speed * dt * 5,
                            (math.random() - 0.5) * speed * dt * 5
                        ), radius)
                        return Hvh.LuaVoidPos
                    elseif pattern == 'Loop' then
                        local r = math.min(radius * 0.8, 1e9 + (elapsed % 100) * 1e7)
                        return Hvh.LuaBasePos + Vector3.new(math.cos(elapsed * 2) * r, math.sin(elapsed * 1.3) * r * 0.2, math.sin(elapsed * 2) * r)
                    elseif pattern == 'Spiral' then
                        local r = math.min(radius * 0.9, (elapsed % 50) * 2e9)
                        return Hvh.LuaBasePos + Vector3.new(math.cos(elapsed * 3) * r, math.sin(elapsed * 0.5) * r * 0.3, math.sin(elapsed * 3) * r)
                    end
                    local r = radius * (math.random() > 0.5 and 1 or -1)
                    return Hvh.LuaBasePos + Vector3.new(r, (math.random() - 0.5) * radius * 0.2, r) + Vector3.new((math.random() - 0.5) * radius, 0, (math.random() - 0.5) * radius)
                end

                local r = math.max(distance * 10000, 1e11)
                local sign = math.random() > 0.5 and 1 or -1
                local jitter = Vector3.new((math.random() * 2 - 1) * 1e9, (math.random() * 2 - 1) * 1e8, (math.random() * 2 - 1) * 1e9)
                return Vector3.new(voidX + r * sign, voidYBase + jitter.Y, voidZ + r * sign) + jitter
            end

            local function performVoidStep(hrp, char, dt)
                local mode = VOID_MODE_MAP[tostring(opt('P8S10D1', 'Void Spam'))] or 'VOID_SPAM'
                local distance = opt('P8S10S1', 500)
                local pattern = tostring(opt('P8S10D2', 'Random Far'))
                local jitterStrength = opt('P8S10S3', 14)
                local phase = Hvh.VoidElapsed + dt * 28

                if mode == 'VOID_HIDE' then
                    if not Hvh.VoidHideLastCFrame then
                        Hvh.VoidHideLastCFrame = clientCFrame(hrp)
                    end
                    rawVoidTeleport(hrp, getVoidHidePosition(hrp))
                    return
                end

                if mode == 'VOID_SPAM' then
                    rawVoidTeleport(hrp, getFarVoidPosition(dt, distance, pattern))
                    return
                end

                local client = clientCFrame(hrp)
                local offset
                if mode == 'FORWARD' then
                    offset = client.LookVector * distance
                elseif mode == 'CAMERA' and workspace.CurrentCamera then
                    offset = workspace.CurrentCamera.CFrame.LookVector * distance
                elseif mode == 'DIRECTIONAL' then
                    offset = getDirectionalLimitOffset(distance)
                else
                    local r1 = distance * (0.60 + 0.40 * math.sin(phase * 2.3))
                    local r2 = distance * (0.25 + 0.15 * math.sin(phase * 5.7))
                    local r3 = distance * (0.10 + 0.10 * math.sin(phase * 11.3))
                    local oX = math.cos(phase * 7.1) * r1 + math.cos(phase * 13.4) * r2 + math.cos(phase * 21.9) * r3
                    local oZ = math.sin(phase * 7.1) * r1 + math.sin(phase * 13.4) * r2 + math.sin(phase * 21.9) * r3
                    local oY = math.sin(phase * 9) * r1 * 0.4 + math.sin(phase * 17) * r2 * 0.3
                    local jX = math.noise(phase * 6, 0, 0) * jitterStrength * 3 + (math.random() - 0.5) * jitterStrength * 2.5
                    local jY = math.noise(0, phase * 6, 0) * jitterStrength * 1.5 + (math.random() - 0.5) * jitterStrength * 1.2
                    local jZ = math.noise(0, 0, phase * 6) * jitterStrength * 3 + (math.random() - 0.5) * jitterStrength * 2.5
                    offset = Vector3.new(oX + jX, oY + jY, oZ + jZ)
                end
                safeTeleport(hrp, char, client.Position + offset)
            end

            local function applyVoidEvade(hrp, dt)
                if not tog('P8S10T2') or not hrp then
                    return
                end
                if Hvh.VoidEvadeCD > 0 then
                    Hvh.VoidEvadeCD = Hvh.VoidEvadeCD - dt
                    return
                end
                local intended = liveServerCFrame(hrp).Position
                local radius = opt('P8S10S4', 8) * 1e9
                local trigger = opt('P8S10S7', 100) * 0.01
                local threshold = radius * trigger
                local minDist, threatVec = math.huge, nil
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LP and player.Character then
                        local other = player.Character:FindFirstChild('HumanoidRootPart')
                        local otherHum = player.Character:FindFirstChildOfClass('Humanoid')
                        if other and otherHum and otherHum.Health > 0 then
                            local predicted = other.Position + other.AssemblyLinearVelocity * 0.5
                            local d = (predicted - intended).Magnitude
                            if d < minDist then
                                minDist = d
                                local away = intended - predicted
                                if away.Magnitude > 0.001 then
                                    threatVec = away.Unit
                                end
                            end
                        end
                    end
                end
                if threatVec and minDist < threshold then
                    local strength = opt('P8S10S8', 100) * 0.01
                    local speed = opt('P8S10S5', 6) * 1e9
                    local push = threatVec * speed * (1 + (1 - minDist / threshold) * 2) * strength * 0.5
                    local nextPos = intended + push
                    Hvh.LuaVoidPos = nextPos
                    rawVoidTeleport(hrp, nextPos)
                    Hvh.VoidEvadeCD = opt('P8S10S6', 0.05)
                end
            end

            local function stopVoid(hrp)
                if not hrp then
                    Hvh.VoidOriginalCFrame = nil
                    Hvh.VoidHideLastCFrame = nil
                    spoofClear(nil)
                    return
                end
                clearRootMotion(hrp)
                spoofClear(hrp)
                Hvh.VoidOriginalCFrame = nil
                Hvh.VoidHideLastCFrame = nil
            end

            local function getOrbitTargetName()
                local value = opt('P8S16D1', nil)
                if typeof(value) == 'Instance' and value:IsA('Player') then
                    return value.Name
                end
                if type(value) == 'string' and value ~= '' then
                    return value
                end
                return nil
            end

            local function getOrbitSubject(hrp)
                local targetName = getOrbitTargetName()
                if targetName then
                    local selected = Players:FindFirstChild(targetName)
                    if selected and selected ~= LP then
                        return selected
                    end
                end
                if not hrp then
                    return nil
                end
                local closest, bestDist = nil, math.huge
                for _, subject in ipairs(Players:GetPlayers()) do
                    if subject ~= LP and subject.Character then
                        local otherHrp = subject.Character:FindFirstChild('HumanoidRootPart')
                        local otherHum = subject.Character:FindFirstChildOfClass('Humanoid')
                        if otherHrp and otherHum and otherHum.Health > 0 then
                            local myPos = clientCFrame(hrp).Position
                            local d = (myPos - otherHrp.Position).Magnitude
                            if d < bestDist then
                                bestDist = d
                                closest = subject
                            end
                        end
                    end
                end
                return closest
            end

            local function getOrbitOffset(angle, radius, height, mode, dt)
                dt = dt or 0
                if mode == 'Figure Eight' then
                    return Vector3.new(math.sin(angle) * radius, height, math.sin(angle * 2) * radius * 0.5)
                elseif mode == 'Vertical Wave' then
                    return Vector3.new(math.cos(angle) * radius, height + math.sin(angle * 2) * radius * 0.5, math.sin(angle) * radius)
                elseif mode == 'Spiral In' then
                    Hvh.OrbitCurrentRadius = math.max(1, (Hvh.OrbitCurrentRadius or radius) - dt * 2)
                    return Vector3.new(math.cos(angle) * Hvh.OrbitCurrentRadius, height, math.sin(angle) * Hvh.OrbitCurrentRadius)
                elseif mode == 'Spiral Out' then
                    Hvh.OrbitCurrentRadius = math.min(radius * 2, (Hvh.OrbitCurrentRadius or radius) + dt * 2)
                    return Vector3.new(math.cos(angle) * Hvh.OrbitCurrentRadius, height, math.sin(angle) * Hvh.OrbitCurrentRadius)
                elseif mode == 'Bounce' then
                    return Vector3.new(math.cos(angle) * radius, height + math.sin((Hvh.OrbitLocalElapsed or 0) * 3) * 5, math.sin(angle) * radius)
                elseif mode == 'Square' then
                    local t = (angle / math.pi) % 4
                    local side = math.floor(t)
                    local a = t - side
                    if side == 0 then
                        return Vector3.new(-radius + a * 2 * radius, height, -radius)
                    elseif side == 1 then
                        return Vector3.new(radius, height, -radius + a * 2 * radius)
                    elseif side == 2 then
                        return Vector3.new(radius - a * 2 * radius, height, radius)
                    end
                    return Vector3.new(-radius, height, radius - a * 2 * radius)
                end
                return Vector3.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
            end

            function Hvh.SaveHome(silent)
                local hrp = getHrp()
                if hrp then
                    local home = clientCFrame(hrp)
                    Hvh.HomeCFrame = home
                    Hvh.HomePosition = home.Position
                    if not silent then
                        hvhNotify(string.format('Home saved: %.0f, %.0f, %.0f', home.Position.X, home.Position.Y, home.Position.Z))
                    end
                    return true
                end
                if not silent then
                    hvhNotify('No character root found.')
                end
                return false
            end

            function Hvh.TeleportHome()
                local hrp = getHrp()
                if hrp and Hvh.HomeCFrame then
                    clearRootMotion(hrp)
                    spoofCFrame(hrp, Hvh.HomeCFrame)
                    return true
                end
                return false
            end

            function Hvh.SnapOrbit()
                local hrp = getHrp()
                local target = getOrbitSubject(hrp)
                local targetRoot = target and target.Character and target.Character:FindFirstChild('HumanoidRootPart')
                if not (hrp and targetRoot) then
                    hvhNotify('No orbit subject found.')
                    return
                end
                local offset = getOrbitOffset(Hvh.OrbitAngle, opt('P8S16S1', 8), opt('P8S16S2', 4), tostring(opt('P8S16D2', 'Circle')))
                local position = targetRoot.Position + offset
                if tog('P8S16T2') then
                    spoofCFrame(hrp, CFrame.new(position, targetRoot.Position))
                else
                    local live = liveServerCFrame(hrp)
                    spoofCFrame(hrp, CFrame.new(position) * (live - live.Position))
                end
            end

            function Hvh.ApplyVoidProfile(value)
                local profile = tostring(value)
                local mode, pattern, distance, interval, jitter
                local drift, yDrift, yRange, chaos
                if profile == 'Steady Scan' then
                    mode, pattern, distance, interval, jitter = 'Void Spam', 'Slow Drift', 2500000, 0.08, 4
                    drift, yDrift, yRange, chaos = 3500000, 1600000, 900000000, 0.55
                elseif profile == 'Fast Sweep' then
                    mode, pattern, distance, interval, jitter = 'Void Spam', 'Cross Sweep', 12000000, 0.025, 18
                    drift, yDrift, yRange, chaos = 12000000, 6000000, 3500000000, 0.9
                elseif profile == 'Deep Void' then
                    mode, pattern, distance, interval, jitter = 'Void Spam', 'Noise Cloud', 50000000, 0.04, 8
                    drift, yDrift, yRange, chaos = 18000000, 9000000, 7000000000, 0.75
                elseif profile == 'Stress Test' then
                    mode, pattern, distance, interval, jitter = 'Void Spam', 'Fast Bounce', 50000000, 0.01, 45
                    drift, yDrift, yRange, chaos = 30000000, 16000000, 12000000000, 0.98
                else
                    return
                end
                Hvh.VoidDriftSpeed = drift
                Hvh.VoidYDriftSpeed = yDrift
                Hvh.VoidYDriftRange = yRange
                Hvh.VoidChaos = chaos
                Hvh.ResetVoidPattern()
                setOpt('P8S10D1', mode)
                setOpt('P8S10D2', pattern)
                setOpt('P8S10S1', distance)
                setOpt('P8S10S2', interval)
                setOpt('P8S10S3', jitter)
            end

            function Hvh.ApplyMotionPreset(value)
                local preset = tostring(value)
                local speed, xJitter, yJitter, distance
                if preset == 'Smooth' then
                    speed, xJitter, yJitter, distance = 360, 10, 4, 120
                elseif preset == 'Wide' then
                    speed, xJitter, yJitter, distance = 900, 35, 10, 900
                elseif preset == 'Heavy' then
                    speed, xJitter, yJitter, distance = 2400, 75, 22, 2500
                elseif preset == 'Max' then
                    speed, xJitter, yJitter, distance = 12000, 120, 60, 5000
                else
                    return
                end
                setOpt('P8S12S1', speed)
                setOpt('P8S12S2', xJitter)
                setOpt('P8S12S3', yJitter)
                setOpt('P8S12S4', distance)
            end

            function Hvh.ApplyDesyncPreset(value)
                local preset = tostring(value)
                local offset, burst, pulse, stutter
                if preset == 'Balanced' then
                    offset, burst, pulse, stutter = 30, 900, 0.05, 0.12
                elseif preset == 'Strong' then
                    offset, burst, pulse, stutter = 40, 1500, 0.03, 0.08
                elseif preset == 'Heavy' then
                    offset, burst, pulse, stutter = 120, 5000, 0.015, 0.04
                elseif preset == 'Max' then
                    offset, burst, pulse, stutter = 260, 12000, 0.005, 0.02
                else
                    return
                end
                setOpt('P8S13S1', offset)
                setOpt('P8S13S2', burst)
                setOpt('P8S13S3', pulse)
                setOpt('P8S13S4', stutter)
            end

            function Hvh.ApplyGravityPreset(value)
                local preset = tostring(value)
                local gravity
                if preset == 'Default' then
                    setOpt('P8S17S2', Hvh.OriginalGravity)
                    return
                elseif preset == 'Zero' then
                    gravity = 0
                elseif preset == 'Low' then
                    gravity = 35
                elseif preset == 'Moon' then
                    gravity = 32
                elseif preset == 'Heavy' then
                    gravity = 400
                elseif preset == 'Void' then
                    gravity = 100000
                else
                    return
                end
                setOpt('P8S17S2', gravity)
                setTog('P8S17T3', true)
            end

            function Hvh.EnableDesyncPreset()
                Hvh.ApplyDesyncPreset(opt('P8S13D1', 'Strong'))
                setTog('P8S13T1', true)
                setTog('P8S13T2', true)
                setTog('P8S13T3', true)
                hvhNotify('Desync preset enabled.')
            end

            function Hvh.StopDesync()
                setTog('P8S13T1', false)
                setTog('P8S13T2', false)
                setTog('P8S13T3', false)
                hvhNotify('Desync stopped.')
            end

            function Hvh.MirrorLimits()
                local x = math.max(opt('P8S11S1', 200000), opt('P8S11S2', 200000))
                local y = math.max(opt('P8S11S3', 200000), opt('P8S11S4', 200000))
                local z = math.max(opt('P8S11S5', 200000), opt('P8S11S6', 200000))
                setOpt('P8S11S1', x)
                setOpt('P8S11S2', x)
                setOpt('P8S11S3', y)
                setOpt('P8S11S4', y)
                setOpt('P8S11S5', z)
                setOpt('P8S11S6', z)
                hvhNotify('Directional limits mirrored.')
            end

            function Hvh.ResetLimits()
                setOpt('P8S11S1', 200000)
                setOpt('P8S11S2', 200000)
                setOpt('P8S11S3', 200000)
                setOpt('P8S11S4', 200000)
                setOpt('P8S11S5', 200000)
                setOpt('P8S11S6', 200000)
                hvhNotify('Directional limits reset.')
            end

            function Hvh.ResetPlayer()
                setTog('P8S17T1', false)
                setTog('P8S17T2', false)
                setTog('P8S17T3', false)
                setOpt('P8S17S1', Hvh.OriginalJumpPower or 50)
                setOpt('P8S17S2', Hvh.OriginalGravity)
                setOpt('P8S17D1', 'Default')
                hvhNotify('Player reset.')
            end

            local function restoreDesyncStutter(hrp)
                if hrp and Hvh.DesyncOriginalAnchored ~= nil then
                    hrp.Anchored = Hvh.DesyncOriginalAnchored
                end
                Hvh.DesyncOriginalAnchored = nil
                Hvh.DesyncStutterAnchored = false
                Hvh.DesyncStutterClock = 0
            end

            local function restoreJump(hum)
                if not hum then
                    return
                end
                if Hvh.OriginalJumpPower then
                    pcall(function()
                        hum.JumpPower = Hvh.OriginalJumpPower
                    end)
                end
                if Hvh.OriginalJumpHeight then
                    pcall(function()
                        hum.JumpHeight = Hvh.OriginalJumpHeight
                    end)
                end
            end

            function Hvh.Update(deltaTime)
                if Hvh.Destroyed then
                    return
                end
                local dt = deltaTime or 0
                local hrp, char, hum = getHrp()

                local voidOn = tog('P8S10T1')
                if voidOn and hrp then
                    if not Hvh.WasVoid then
                        Hvh.VoidOriginalCFrame = clientCFrame(hrp)
                        Hvh.VoidHideLastCFrame = nil
                    end
                    if tick() - Hvh.LastTeleport >= opt('P8S10S2', 0.035) then
                        Hvh.LastTeleport = tick()
                        performVoidStep(hrp, char, dt)
                    end
                    applyVoidEvade(hrp, dt)
                elseif Hvh.WasVoid then
                    stopVoid(hrp)
                end
                Hvh.WasVoid = voidOn

                local pulseOn = tog('P8S12T2')
                if pulseOn and hrp then
                    Hvh.PulseClock = Hvh.PulseClock + dt * 2
                    local power = math.clamp(opt('P8S13S2', 1500) * 0.08, 20, 220)
                    hrp.AssemblyLinearVelocity = Vector3.new(math.cos(Hvh.PulseClock) * power, 24, math.sin(Hvh.PulseClock) * power)
                elseif Hvh.WasPulse and hrp then
                    clearRootMotion(hrp)
                end
                Hvh.WasPulse = pulseOn

                local offsetDesync = tog('P8S13T1')
                local burstDesync = tog('P8S13T2')
                local stutterDesync = tog('P8S13T3')
                local velScramble = tog('P8S13_VelScramble')
                local anyDesync = offsetDesync or burstDesync or stutterDesync or velScramble
                if anyDesync and hrp then
                    if velScramble then
                        local pwr = opt('P8S13S2', 1500)
                        local ang = (tick() * 14) % (math.pi * 2)
                        hrp.AssemblyLinearVelocity = Vector3.new(math.cos(ang) * pwr, (math.random() - 0.5) * pwr * 0.15, math.sin(ang) * pwr)
                    end
                    if offsetDesync then
                        Hvh.DesyncPulseClock = Hvh.DesyncPulseClock + dt
                        if Hvh.DesyncPulseClock >= opt('P8S13S3', 0.03) then
                            Hvh.DesyncPulseClock = 0
                            local angle = tick() * 3
                            local amount = opt('P8S13S1', 40)
                            local offset = Vector3.new(math.sin(angle) * amount, math.sin(angle * 1.7) * amount * 0.35, math.cos(angle) * amount) * 40
                            local velocity = hrp.AssemblyLinearVelocity
                            hrp.AssemblyLinearVelocity = Vector3.new(offset.X, velocity.Y + offset.Y, offset.Z)
                            task.delay(0.05, function()
                                if Hvh.Destroyed or not tog('P8S13T1') then
                                    return
                                end
                                local live = getHrp()
                                if live then
                                    live.AssemblyLinearVelocity = Vector3.zero
                                end
                            end)
                        end
                    end
                    if burstDesync then
                        Hvh.DesyncBurstClock = Hvh.DesyncBurstClock + dt
                        if Hvh.DesyncBurstClock >= 0.025 then
                            Hvh.DesyncBurstClock = 0
                            local direction = Vector3.new(math.random() - 0.5, 0, math.random() - 0.5)
                            if direction.Magnitude < 0.01 then
                                direction = Vector3.new(1, 0, 0)
                            else
                                direction = direction.Unit
                            end
                            local power = opt('P8S13S2', 1500)
                            local velocity = hrp.AssemblyLinearVelocity
                            hrp.AssemblyLinearVelocity = Vector3.new(direction.X * power, velocity.Y + (math.random() - 0.5) * power * 0.2, direction.Z * power)
                            task.delay(0.05, function()
                                if Hvh.Destroyed or not tog('P8S13T2') then
                                    return
                                end
                                local live = getHrp()
                                if live then
                                    live.AssemblyLinearVelocity = Vector3.zero
                                end
                            end)
                        end
                    end
                    if stutterDesync and not tog('P8S17T2') then
                        if Hvh.DesyncOriginalAnchored == nil then
                            Hvh.DesyncOriginalAnchored = hrp.Anchored
                        end
                        Hvh.DesyncStutterClock = Hvh.DesyncStutterClock + dt
                        if Hvh.DesyncStutterClock >= opt('P8S13S4', 0.08) then
                            Hvh.DesyncStutterClock = 0
                            Hvh.DesyncStutterAnchored = not Hvh.DesyncStutterAnchored
                            hrp.Anchored = Hvh.DesyncStutterAnchored
                        end
                    elseif Hvh.DesyncOriginalAnchored ~= nil then
                        restoreDesyncStutter(hrp)
                    end
                elseif Hvh.WasDesync then
                    if hrp then
                        hrp.AssemblyLinearVelocity = Vector3.zero
                    end
                    restoreDesyncStutter(hrp)
                    Hvh.DesyncPulseClock = 0
                    Hvh.DesyncBurstClock = 0
                end
                Hvh.WasDesync = anyDesync

                local freezeOn = tog('P8S17T2')
                if hrp then
                    if freezeOn then
                        if Hvh.PreviousRootAnchored == nil then
                            Hvh.PreviousRootAnchored = hrp.Anchored
                        end
                        clearRootMotion(hrp)
                        hrp.Anchored = true
                    elseif Hvh.WasFrozen then
                        hrp.Anchored = Hvh.PreviousRootAnchored == true
                        Hvh.PreviousRootAnchored = nil
                    end
                end
                Hvh.WasFrozen = freezeOn

                local jumpOn = tog('P8S17T1')
                if hum then
                    if Hvh.OriginalJumpPower == nil then
                        Hvh.OriginalJumpPower = hum.JumpPower
                    end
                    if Hvh.OriginalJumpHeight == nil then
                        Hvh.OriginalJumpHeight = hum.JumpHeight
                    end
                    if jumpOn then
                        pcall(function()
                            hum.UseJumpPower = true
                            hum.JumpPower = opt('P8S17S1', 50)
                        end)
                    elseif Hvh.WasJump then
                        restoreJump(hum)
                    end
                end
                Hvh.WasJump = jumpOn

                local gravityOn = tog('P8S17T3')
                if gravityOn then
                    workspace.Gravity = opt('P8S17S2', Hvh.OriginalGravity)
                elseif Hvh.WasGravity then
                    workspace.Gravity = Hvh.OriginalGravity
                end
                Hvh.WasGravity = gravityOn

                if tog('P8S15T2') and hrp and Hvh.HomePosition and Hvh.HomeCFrame then
                    local now = tick()
                    if now - Hvh.LastHomeCheck >= 0.1 then
                        Hvh.LastHomeCheck = now
                        local visualPos = clientCFrame(hrp).Position
                        if (visualPos - Hvh.HomePosition).Magnitude > opt('P8S15S2', 10)
                            and now - Hvh.LastHomeReturn >= opt('P8S15S1', 3) then
                            Hvh.LastHomeReturn = now
                            clearRootMotion(hrp)
                            spoofCFrame(hrp, Hvh.HomeCFrame)
                        end
                    end
                end

                if tog('P8S15_SafeZone') and hrp and hum and hum.Health > 0 then
                    local threshold = opt('P8S15_SafeDepth', -10)
                    local currentPos = liveServerCFrame(hrp).Position
                    if currentPos.Y < threshold then
                        clearRootMotion(hrp)
                        spoofCFrame(hrp, CFrame.new(currentPos.X, math.abs(threshold) + 50, currentPos.Z))
                    end
                end

                local orientOn = tog('P8S14T1')
                local dodgeVelOn = tog('P8S22T1')
                local aimThreatOn = tog('P8S22_AimThreat')
                if (dodgeVelOn or aimThreatOn) and hrp and hum and hum.Health > 0 then
                    local nowDodge = tick()
                    if nowDodge - Hvh.LastDodgeAt >= opt('P8S22S3', 0.3) then
                        local myPos = liveServerCFrame(hrp).Position
                        local radius = opt('P8S22S1', 20)
                        local threshold = opt('P8S22S4', 800)
                        local mult = opt('P8S22S5', 1)
                        for _, player in ipairs(Players:GetPlayers()) do
                            if player ~= LP and player.Character then
                                local other = player.Character:FindFirstChild('HumanoidRootPart')
                                local otherHead = player.Character:FindFirstChild('Head') or other
                                local vel = other and other.AssemblyLinearVelocity
                                local triggered = false
                                local perp = nil

                                if dodgeVelOn and other and vel and vel.Magnitude > threshold then
                                    local predicted = other.Position + vel * (dt * 3 * mult)
                                    if (predicted - myPos).Magnitude < radius then
                                        triggered = true
                                        perp = Vector3.new(-vel.Z, 0, vel.X)
                                    end
                                end

                                if not triggered and aimThreatOn and otherHead then
                                    local toMe = (myPos - otherHead.Position)
                                    if toMe.Magnitude <= 160 and toMe.Magnitude >= 5 then
                                        local look = otherHead.CFrame.LookVector
                                        local dot = look:Dot(toMe.Unit)
                                        if dot > 0.82 then
                                            triggered = true
                                            perp = Vector3.new(-look.Z, 0, look.X)
                                        end
                                    end
                                end

                                if triggered and perp then
                                    Hvh.LastDodgeAt = nowDodge
                                    if perp.Magnitude < 0.001 then
                                        perp = Vector3.new(1, 0, 0)
                                    else
                                        perp = perp.Unit
                                    end
                                    if math.random() < 0.5 then
                                        perp = -perp
                                    end
                                    spoofPosition(hrp, myPos + perp * opt('P8S22S2', 30))
                                    hvhNotify('Dodged ' .. player.Name)
                                    break
                                end
                            end
                        end
                    end
                end

                if tog('P8S24T1') and hrp then
                    if not Hvh.BlinkAnchor then
                        Hvh.BlinkAnchor = clientCFrame(hrp).Position
                    end
                    Hvh.BlinkClock = (Hvh.BlinkClock or 0) + dt
                    local rate = math.max(opt('P8S24S2', 60), 1)
                    if Hvh.BlinkClock >= (1 / rate) then
                        Hvh.BlinkClock = 0
                        local radius = opt('P8S24S1', 80)
                        local a = math.random() * math.pi * 2
                        local d = math.random() * radius
                        safeTeleport(hrp, char, Hvh.BlinkAnchor + Vector3.new(
                            math.cos(a) * d,
                            (math.random() - 0.5) * radius * 0.3,
                            math.sin(a) * d
                        ))
                    end
                else
                    Hvh.BlinkAnchor = nil
                    Hvh.BlinkClock = 0
                end

                if tog('P8S25T1') and hrp then
                    local target = getOrbitSubject(hrp)
                    local targetRoot = target and target.Character and target.Character:FindFirstChild('HumanoidRootPart')
                    if targetRoot then
                        local keep = opt('P8S25S1', 150)
                        local live = liveServerCFrame(hrp)
                        local delta = live.Position - targetRoot.Position
                        local mag = delta.Magnitude
                        if mag < keep then
                            local dir = mag < 0.001 and Vector3.new(1, 0, 0) or delta.Unit
                            spoofCFrame(hrp, CFrame.new(targetRoot.Position + dir * keep) * (live - live.Position))
                        end
                    end
                end

                if tog('P8S16T1') and hrp then
                    local orbitMode = tostring(opt('P8S16D2', 'Circle'))
                    if Hvh.LastOrbitMode ~= orbitMode then
                        Hvh.LastOrbitMode = orbitMode
                        Hvh.OrbitCurrentRadius = opt('P8S16S1', 8)
                    end
                    local target = getOrbitSubject(hrp)
                    local targetRoot = target and target.Character and target.Character:FindFirstChild('HumanoidRootPart')
                    if targetRoot then
                        local maxLock = opt('P8S16S6', 50)
                        local named = getOrbitTargetName()
                        local live = liveServerCFrame(hrp)
                        if named or not tog('P8S16T4') or (live.Position - targetRoot.Position).Magnitude <= maxLock then
                            local targetPos = targetRoot.Position
                            if tog('P8S16T3') then
                                targetPos = targetPos + targetRoot.AssemblyLinearVelocity * (opt('P8S16S5', 20) * 0.01)
                            end
                            local orbitSpeed = opt('P8S16S3', 1.8)
                            if tostring(opt('P8S16D3', 'Clockwise')) == 'Counter-Clockwise' then
                                orbitSpeed = -orbitSpeed
                            end
                            Hvh.OrbitAngle = Hvh.OrbitAngle + dt * orbitSpeed
                            Hvh.OrbitLocalElapsed = (Hvh.OrbitLocalElapsed or 0) + dt
                            local offset = getOrbitOffset(Hvh.OrbitAngle, opt('P8S16S1', 8), opt('P8S16S2', 4), orbitMode, dt)
                            local dst = targetPos + offset
                            local lerp = math.clamp(opt('P8S16S4', 100) * 0.01, 0.01, 1)
                            local smooth = live.Position:Lerp(dst, lerp)
                            if tog('P8S16T2') then
                                spoofCFrame(hrp, CFrame.new(smooth, Vector3.new(targetPos.X, smooth.Y, targetPos.Z)))
                            else
                                spoofCFrame(hrp, CFrame.new(smooth) * (live - live.Position))
                            end
                        end
                    end
                end

                if tog('P8S23T1') and hrp then
                    local speed = opt('P8S23S1', 5000)
                    if tog('P8S23T2') then
                        Hvh.AaRandomTimer = Hvh.AaRandomTimer + dt
                        if Hvh.AaRandomTimer > 0.1 then
                            Hvh.AaRandomTimer = 0
                            Hvh.AaRandomMultiplier = 0.2 + math.random() * 0.8
                        end
                        speed = speed * Hvh.AaRandomMultiplier
                    end
                    local mode = tostring(opt('P8S23D1', 'Spin'))
                    local angle = opt('P8S23S2', 90)
                    local live = liveServerCFrame(hrp)
                    if mode == 'Spin' then
                        Hvh.AaAngleAccum = Hvh.AaAngleAccum + speed * dt
                        spoofCFrame(hrp, live * CFrame.Angles(0, math.rad(Hvh.AaAngleAccum), 0))
                    elseif mode == 'Jitter' then
                        local signed = Hvh.AaJitterState == 0 and angle or -angle
                        local pitch = tog('P8S23T3') and signed or 0
                        spoofCFrame(hrp, live * CFrame.Angles(math.rad(pitch), math.rad(signed), 0))
                        Hvh.AaJitterState = (Hvh.AaJitterState + 1) % 2
                    elseif mode == 'Invert' then
                        spoofCFrame(hrp, live * CFrame.Angles(0, math.rad(180), 0))
                    elseif mode == 'Roll' then
                        spoofCFrame(hrp, live * CFrame.Angles(0, 0, math.rad(90)))
                    elseif mode == 'Chaos' then
                        spoofCFrame(hrp, live * CFrame.Angles(math.rad(math.random(-180, 180)), math.rad(math.random(-180, 180)), math.rad(math.random(-180, 180))))
                    elseif mode == 'Flat' then
                        local _, curY, _ = live:ToEulerAnglesYXZ()
                        spoofCFrame(hrp, CFrame.new(live.Position) * CFrame.Angles(0, curY, 0))
                    else
                        spoofCFrame(hrp, live * CFrame.Angles(0, math.rad(angle), 0))
                    end
                end

                if orientOn and hrp then
                    local live = liveServerCFrame(hrp)
                    if not Hvh.OrientationBaseLook then
                        local look = Vector3.new(live.LookVector.X, 0, live.LookVector.Z)
                        if look.Magnitude < 0.01 then
                            look = Vector3.new(0, 0, -1)
                        else
                            look = look.Unit
                        end
                        Hvh.OrientationBaseLook = look
                    end
                    local look = Hvh.OrientationBaseLook or Vector3.new(0, 0, -1)
                    local base = CFrame.lookAt(live.Position, live.Position + look)
                    spoofCFrame(hrp, base * CFrame.Angles(
                        math.rad(opt('P8S14S1', 0)),
                        math.rad(opt('P8S14S2', 0)),
                        math.rad(opt('P8S14S3', 0))
                    ))
                else
                    Hvh.OrientationBaseLook = nil
                end
                Hvh.WasOrient = orientOn
            end

            function Hvh.Destroy()
                if Hvh.Destroyed then
                    return
                end
                Hvh.Destroyed = true
                if Hvh.CharAddedConn then
                    Hvh.CharAddedConn:Disconnect()
                    Hvh.CharAddedConn = nil
                end
                local hrp, _, hum = getHrp()
                if Hvh.WasVoid then
                    stopVoid(hrp)
                end
                if hrp then
                    if Hvh.WasPulse or Hvh.WasDesync then
                        clearRootMotion(hrp)
                    end
                    restoreDesyncStutter(hrp)
                    if Hvh.WasFrozen then
                        hrp.Anchored = Hvh.PreviousRootAnchored == true
                    end
                end
                if Hvh.WasJump then
                    restoreJump(hum)
                end
                if Hvh.WasGravity then
                    workspace.Gravity = Hvh.OriginalGravity
                end
                Hvh.WasVoid = false
                Hvh.WasRiot = false
                Hvh.WasPulse = false
                Hvh.WasDesync = false
                Hvh.WasOrient = false
                Hvh.WasFrozen = false
                Hvh.WasGravity = false
                Hvh.WasJump = false
            end

            if LP then
                Hvh.CharAddedConn = LP.CharacterAdded:Connect(function()
                    Hvh.OriginalJumpPower = nil
                    Hvh.OriginalJumpHeight = nil
                    Hvh.PreviousRootAnchored = nil
                    Hvh.DesyncOriginalAnchored = nil
                    Hvh.DesyncStutterAnchored = false
                    Hvh.OrientationBaseLook = nil
                    task.delay(0.75, function()
                        if Hvh.Destroyed then
                            return
                        end
                        if tog('P8S15T1') then
                            Hvh.SaveHome(true)
                        end
                    end)
                end)
            end

            RivalsRuntimeBridge.HvhSystems = Hvh
            end)()

            local _hbOriginal = {}
            local function UpdateHitboxExpansion()
                local enabled = (Toggles.P8S4_HitboxExpander and Toggles.P8S4_HitboxExpander.Value == true)
                if not enabled and not next(_hbOriginal) then
                    return
                end
                local size = (Options.P8S4_HitboxSize and Options.P8S4_HitboxSize.Value) or 14
                local trans = (Options.P8S4_HitboxTrans and Options.P8S4_HitboxTrans.Value) or 0.5
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP and p.Character then
                        local hrpPart = p.Character:FindFirstChild('HumanoidRootPart')
                        if hrpPart and hrpPart:IsA('BasePart') then
                            if enabled then
                                if not _hbOriginal[hrpPart] then
                                    _hbOriginal[hrpPart] = { size = hrpPart.Size, trans = hrpPart.Transparency, canCollide = hrpPart.CanCollide }
                                end
                                pcall(function()
                                    hrpPart.Size = Vector3.new(size, size, size)
                                    hrpPart.Transparency = trans
                                    hrpPart.CanCollide = false
                                end)
                            elseif _hbOriginal[hrpPart] then
                                local orig = _hbOriginal[hrpPart]
                                pcall(function()
                                    hrpPart.Size = orig.size
                                    hrpPart.Transparency = orig.trans
                                    hrpPart.CanCollide = orig.canCollide
                                end)
                                _hbOriginal[hrpPart] = nil
                            end
                        end
                    end
                end
            end

            function RivalsRagebot.Update(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local now = tick()
                pcall(UpdateHitboxExpansion)
                -- Always sample hostile teleports (throttled internally) so
                -- Prioritize Hackers has data even when bait mode is off.
                RivalsRagebot.UpdateHostileTeleportTracker(now)
                if RivalsRagebot.IsBaitModeEnabled() then
                    if RivalsRagebot.IsHostileCheating() then
                        if RivalsRuntimeBridge.ResetAkiraRagebot then
                            RivalsRuntimeBridge.ResetAkiraRagebot()
                        end
                        local item = AimbotBridge.ResolveAimbotEquippedItem()
                        local shotReady = AimbotBridge.IsShotImmediatelyReady(item)

                        if shotReady then
                            RivalsRagebotState.PhaseClockSec = RivalsRagebotState.PhaseClockSec + (deltaTime or 0)
                            local rawPhase = math.random() * (math.pi * 2)
                            local targetInfo, hoverCFrame = RivalsRagebot.ResolveTarget(rawPhase)
                            if hoverCFrame then
                                RivalsRagebotState.HoldCFrame = hoverCFrame
                                RivalsRagebotState.LastHoldUpdateAt = now
                            end
                            local stale = (now - (RivalsRagebotState.LastHoldUpdateAt or 0)) > RivalsRagebot.HoldCFrameStaleTtlSec
                            local holdCFrame = hoverCFrame or (not stale and RivalsRagebotState.HoldCFrame) or nil
                            if stale then
                                RivalsRagebotState.HoldCFrame = nil
                            end
                            if holdCFrame and not RivalsRagebot.IsCandidatePositionInBounds(holdCFrame.Position, nil) then
                                RivalsRagebotState.HoldCFrame = nil
                                holdCFrame = nil
                            end
                            RivalsRagebotState.Target = targetInfo or nil
                            if holdCFrame then
                                local activeChar = RivalsRuntimeBridge.AcquireActiveCharacter()
                                if activeChar then
                                    local cur = activeChar:GetPivot()
                                    RivalsRagebot.SpoofPivotTo(CFrame.new(holdCFrame.Position) * (cur - cur.Position))
                                end
                                return
                            end
                        end

                        RivalsRagebotState.Target = nil
                        RivalsRagebotState.HoldCFrame = nil
                        RivalsRagebotState.LastHoldUpdateAt = 0
                        RivalsRagebot.PivotToBaitTrapOrSnug()
                        return
                    end
                end

                local enabled = RivalsRagebot.IsEnabled()
                if not enabled then
                    if RivalsRagebotState.Target ~= nil then
                        RivalsRagebotState.Target = nil
                        RivalsRagebotState.HoldCFrame = nil
                        RivalsRagebotState.LastHoldUpdateAt = 0
                        RivalsRagebotState.PhaseClockSec = 0
                    end
                    if RivalsRuntimeBridge.UpdateAkiraRagebot then
                        RivalsRuntimeBridge.UpdateAkiraRagebot(deltaTime)
                    end
                    if Toggles.P8S7T1 and Toggles.P8S7T1.Value then
                        RivalsRagebot.UpdateFly(deltaTime)
                    end
                    if Toggles.P8S18T1 and Toggles.P8S18T1.Value then
                        RivalsRagebot.UpdateCounterMethod(deltaTime)
                    end
                    if Toggles.P8S20T1 and Toggles.P8S20T1.Value then
                        RivalsRagebot.UpdateBaitingV1(now)
                    end
                    if Toggles.P8S9T1 and Toggles.P8S9T1.Value then
                        RivalsRagebot.UpdateBaitingV2(now, deltaTime)
                    end
                    return
                end

                local readyToFight = RivalsRuntimeBridge.IsReadyToFight()
                RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint('Ragebot', readyToFight, true)

                if RivalsRuntimeBridge.UpdateAkiraRagebot then
                    RivalsRuntimeBridge.UpdateAkiraRagebot(deltaTime)
                end
                RivalsRagebot.UpdateFly(deltaTime)
                RivalsRagebot.UpdateCounterMethod(deltaTime)
                RivalsRagebot.UpdateBaitingV1(now)
                RivalsRagebot.UpdateBaitingV2(now, deltaTime)
                if RivalsRuntimeBridge.HvhSystems and RivalsRuntimeBridge.HvhSystems.Update then
                    RivalsRuntimeBridge.HvhSystems.Update(deltaTime)
                end
            end


            function RivalsRagebot.ResetCounterMethodsState()
                -- Restore humanoid states if Fly was active before TP
                local char = LP and LP.Character
                local hum  = char and char:FindFirstChildOfClass('Humanoid')
                if hum then
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.Landed,   true)
                    end)
                end
                CounterMethodsState.KiciaPhase    = math.random() * math.pi * 2
                CounterMethodsState.LastNotifyAt   = 0
                CounterMethodsState.BaitWalkPhase  = 0
                CounterMethodsState.ForceWallbang  = false
                if RivalsRuntimeBridge.HvhSystems and RivalsRuntimeBridge.HvhSystems.Destroy then
                    RivalsRuntimeBridge.HvhSystems.Destroy()
                end
            end

            -- ── Fly ──────────────────────────────────────────────────────────
            function RivalsRagebot.IsFlyEnabled()
                return Toggles.P8S7T1 and Toggles.P8S7T1.Value == true
            end

            function RivalsRagebot.UpdateFly(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                local isSleepyCounter = RivalsRagebot.IsCounterMethodEnabled()
                    and Options.P8S18D1 and Options.P8S18D1.Value == 'Sleepy Counter'
                local flyActive = RivalsRagebot.IsFlyEnabled() or isSleepyCounter
                local char = LP and LP.Character
                local hrp  = char and char:FindFirstChild('HumanoidRootPart')
                local hum  = char and char:FindFirstChildOfClass('Humanoid')
                if not hrp or not hum then return end
                if flyActive then
                    local flySpeed = Options.P8S7S1 and Options.P8S7S1.Value or 30
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall,  false)
                        hum:SetStateEnabled(Enum.HumanoidStateType.Landed,    false)
                        hum:ChangeState(Enum.HumanoidStateType.PlatformStand)
                    end)
                    local uis = game:GetService('UserInputService')
                    local upHeld   = uis:IsKeyDown(Enum.KeyCode.Space)       or uis:IsKeyDown(Enum.KeyCode.ButtonA)
                    local downHeld = uis:IsKeyDown(Enum.KeyCode.LeftControl) or uis:IsKeyDown(Enum.KeyCode.ButtonB)
                    local vy = upHeld and flySpeed or (downHeld and -flySpeed or 0)
                    local vx = hrp.AssemblyLinearVelocity.X * 0.85
                    local vz = hrp.AssemblyLinearVelocity.Z * 0.85
                    CounterMethodsState._FlyWasActive = true
                    hrp.AssemblyLinearVelocity = Vector3.new(vx, vy, vz)
                elseif CounterMethodsState._FlyWasActive then
                    CounterMethodsState._FlyWasActive = false
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.Landed,   true)
                    end)
                end
            end

            -- ── Counter Methods ───────────────────────────────────────────────
            function RivalsRagebot.IsCounterMethodEnabled()
                return Toggles.P8S18T1 and Toggles.P8S18T1.Value == true
            end

            function RivalsRagebot.UpdateCounterMethod(deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                if not RivalsRagebot.IsCounterMethodEnabled() then return end
                local method = Options.P8S18D1 and Options.P8S18D1.Value or 'None'
                local char   = LP and LP.Character
                local hrp    = char and char:FindFirstChild('HumanoidRootPart')
                if not hrp then return end
                local depthY  = Options.P8S18S1 and Options.P8S18S1.Value or -15
                local offsetX = Options.P8S18S2 and Options.P8S18S2.Value or 0
                local offsetZ = Options.P8S18S3 and Options.P8S18S3.Value or 0
                if method == 'UE Counter' then
                    local ti = RivalsRagebotState.Target
                    local tp = ti and ti.part
                    if tp and tp.Parent then
                        local tpos = tp.Position
                        local newPos = Vector3.new(tpos.X + offsetX, tpos.Y + depthY, tpos.Z + offsetZ)
                        local ac = RivalsRuntimeBridge.AcquireActiveCharacter()
                        if ac then
                            local cur = ac:GetPivot()
                            RivalsRagebot.SpoofPivotTo(CFrame.new(newPos) * (cur - cur.Position))
                        end
                    end
                elseif method == 'Kicia Counter' then
                    local driftSpeed  = Options.P8S18S4 and Options.P8S18S4.Value or 5
                    local driftRadius = Options.P8S18S5 and Options.P8S18S5.Value or 6
                    CounterMethodsState.KiciaPhase = CounterMethodsState.KiciaPhase + (driftSpeed * (deltaTime or 0))
                    local ph = CounterMethodsState.KiciaPhase
                    local ti = RivalsRagebotState.Target
                    local tp = ti and ti.part
                    if tp and tp.Parent then
                        local tpos = tp.Position
                        local newPos = Vector3.new(
                            tpos.X + math.sin(ph) * driftRadius + offsetX,
                            tpos.Y + depthY,
                            tpos.Z + math.cos(ph) * driftRadius + offsetZ
                        )
                        local ac = RivalsRuntimeBridge.AcquireActiveCharacter()
                        if ac then
                            local cur = ac:GetPivot()
                            RivalsRagebot.SpoofPivotTo(CFrame.new(newPos) * (cur - cur.Position))
                        end
                    end
                elseif method == 'Sleepy Counter' then
                    CounterMethodsState.ForceWallbang = true
                else
                    CounterMethodsState.ForceWallbang = false
                end
            end

            -- ── Baiting V1 ────────────────────────────────────────────────────
            function RivalsRagebot.UpdateBaitingV1(now)
                LPH_ATTRIBUTES(VM(NONE))
                if not (Toggles.P8S20T1 and Toggles.P8S20T1.Value == true) then return end
                RivalsRagebot.UpdateHostileTeleportTracker(now)
                if not RivalsRagebot.IsHostileCheating() then return end
                local notifyInterval = 5
                if (now - CounterMethodsState.LastNotifyAt) > notifyInterval then
                    CounterMethodsState.LastNotifyAt = now
                    if Toggles.P8S20T5 and Toggles.P8S20T5.Value == true then
                        pcall(function()
                            game:GetService('StarterGui'):SetCore('SendNotification', {
                                Title    = 'AKIRA \xE2\x80\x94 Bait Detected',
                                Text     = 'Enemy is TP-raging! Countering now.',
                                Duration = 4,
                            })
                        end)
                    end
                    if Toggles.P8S20T6 and Toggles.P8S20T6.Value == true then
                        if Toggles.P8S9T1 then
                            Toggles.P8S9T1:SetValue(true)
                        end
                    end
                end
                if Toggles.P8S20T2 and Toggles.P8S20T2.Value == true then
                    -- Void Hide: move into OOB/kill-seat
                    RivalsRagebot.PivotToBaitTrapOrSnug()
                end
                if Toggles.P8S20T3 and Toggles.P8S20T3.Value == true then
                    -- Void Trap: position so enemy predicted TP lands inside void
                    local cheater   = RivalsRagebot.GetMostActiveCheater()
                    local predicted = cheater and RivalsRagebot.GetCheaterOffsetPrediction(cheater) or nil
                    local trapPos   = predicted and RivalsRagebot.FindBaitTrapPosition(predicted) or nil
                    if trapPos then
                        local ac = RivalsRuntimeBridge.AcquireActiveCharacter()
                        if ac then
                            local cur = ac:GetPivot()
                            RivalsRagebot.SpoofPivotTo(CFrame.new(trapPos) * (cur - cur.Position))
                        end
                    end
                end
                if Toggles.P8S20T4 and Toggles.P8S20T4.Value == true then
                    -- Void Hit: snap to nearest kill seat for melee range
                    local seatPos = RivalsRagebot.PickKillSeatNearestTarget(
                        HumanoidRootPart and HumanoidRootPart.Position
                    )
                    if seatPos then
                        local ac = RivalsRuntimeBridge.AcquireActiveCharacter()
                        if ac then
                            local cur = ac:GetPivot()
                            RivalsRagebot.SpoofPivotTo(CFrame.new(seatPos) * (cur - cur.Position))
                        end
                    end
                end
            end

            -- ── Baiting V2 ────────────────────────────────────────────────────
            __akira_boot_yield()
            function RivalsRagebot.UpdateBaitingV2(now, deltaTime)
                LPH_ATTRIBUTES(VM(NONE))
                if not (Toggles.P8S9T1 and Toggles.P8S9T1.Value == true) then
                    CounterMethodsState.ForceWallbang = CounterMethodsState.ForceWallbang or false
                    return
                end
                if Toggles.P8S9T2 and Toggles.P8S9T2.Value == true then
                    CounterMethodsState.ForceWallbang = true
                end
                local char = LP and LP.Character
                local hrp  = char and char:FindFirstChild('HumanoidRootPart')
                if not hrp then return end
                local baitMode  = Options.P8S9D1 and Options.P8S9D1.Value or 'Standing'
                local depthY    = Options.P8S9S1 and Options.P8S9S1.Value or -15
                local manualX   = Options.P8S9S2 and Options.P8S9S2.Value or 0
                local manualZ   = Options.P8S9S3 and Options.P8S9S3.Value or 0
                local walkSpeed = Options.P8S9S4 and Options.P8S9S4.Value or 3
                local spoof = RivalsRuntimeBridge.CameraSpoof
                local client = spoof and spoof.GetClientCFrame and spoof.GetClientCFrame()
                local origin = (typeof(client) == 'CFrame' and client.Position) or hrp.Position
                local anchorX = origin.X
                local anchorZ = origin.Z
                if baitMode == 'Manual XYZ' then
                    anchorX = anchorX + manualX
                    anchorZ = anchorZ + manualZ
                elseif baitMode == 'Walking' then
                    CounterMethodsState.BaitWalkPhase = CounterMethodsState.BaitWalkPhase + (walkSpeed * (deltaTime or 0))
                    local ph = CounterMethodsState.BaitWalkPhase
                    anchorX = anchorX + math.sin(ph) * 5
                    anchorZ = anchorZ + math.cos(ph) * 3
                end
                local ugPos = Vector3.new(anchorX, origin.Y + depthY, anchorZ)
                local ac = RivalsRuntimeBridge.AcquireActiveCharacter()
                if ac then
                    local cur = ac:GetPivot()
                    RivalsRagebot.SpoofPivotTo(CFrame.new(ugPos) * (cur - cur.Position))
                end
            end

            RivalsRuntimeBridge.UpdateRagebot = RivalsRagebot.Update
            RivalsRuntimeBridge.RegisterAutoRespawnSignals = RivalsRagebot.RegisterRespawnSignals
            RivalsRuntimeBridge.ResetCounterMethodsState = RivalsRagebot.ResetCounterMethodsState
            end
            RequireSharedModule('rivals_ragebot_kernel').init({
                RivalsRuntimeBridge = RivalsRuntimeBridge,
                Options = Options,
                Toggles = Toggles,
                FighterDataCache = FighterDataCache,
                GetChar = function() return Char end,
                GetRoot = function() return HumanoidRootPart end,
                Genv = __akira_genv,
            })

            do
            local RivalsAutoLoadout = {
                PageNames = {'PickWeapons', 'PickWeaponsList'},
                SlotOrder = {
                    { Name = 'Primary', OptionId = 'P8S5D1', SlotIndex = 1 },
                    { Name = 'Secondary', OptionId = 'P8S5D2', SlotIndex = 2 },
                    { Name = 'Melee', OptionId = 'P8S5D3', SlotIndex = 3 },
                    { Name = 'Utility', OptionId = 'P8S5D4', SlotIndex = 4 },
                },
                OpenRetryDelay = 0.05,
                OpenRetryLimit = 5,
                Unselected = 'Unselected',
                Priorities = {'1', '2', '3'},
                ConfigMetadataId = 'Akira_RivalsAutoLoadoutProfiles',
                Catalog = {},
                LiveValuesBySlot = {},
                ExcludedWeaponNames = {
                    ['MISSING_WEAPON'] = true,
                },
                ExcludedWeaponsBySlot = {
                    Melee = {
                        ['Glast Shard'] = true,
                    },
                    Utility = {
                        ['Elixir'] = true,
                        ['RNG Dice'] = true,
                    },
                },
            }

            function RivalsAutoLoadout.IsEnabled()
                return Toggles.P8S5T1 and Toggles.P8S5T1.Value == true
            end

            function RivalsAutoLoadout.ResolveItemLibrary()
                local cachedItemLibrary = RivalsAutoLoadout.Catalog.ItemLibrary
                if cachedItemLibrary then
                    return cachedItemLibrary
                end

                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local itemLibraryModule = modules and modules:FindFirstChild('ItemLibrary')
                if not itemLibraryModule then
                    return nil
                end

                local ok, itemLibrary = pcall(require, itemLibraryModule)
                if not ok or type(itemLibrary) ~= 'table' then
                    return nil
                end

                RivalsAutoLoadout.Catalog.ItemLibrary = itemLibrary
                return itemLibrary
            end

            function RivalsAutoLoadout.IsAllowedWeaponName(slotName, weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                if RivalsAutoLoadout.ExcludedWeaponNames[weaponName] == true then
                    return false
                end

                local slotExclusions = RivalsAutoLoadout.ExcludedWeaponsBySlot[slotName]
                return not slotExclusions or slotExclusions[weaponName] ~= true
            end

            function RivalsAutoLoadout.ResolveSeedWeaponValues(slotName)
                local cacheKey = string.format('SeedWeaponValues_%s', slotName)
                local cachedValues = RivalsAutoLoadout.Catalog[cacheKey]
                if cachedValues then
                    return cachedValues
                end

                local values = {}
                local slotIndex = nil
                for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                    if slotConfig.Name == slotName then
                        slotIndex = slotConfig.SlotIndex
                        break
                    end
                end

                local itemLibrary = RivalsAutoLoadout.ResolveItemLibrary()
                local slotToClass = itemLibrary and itemLibrary.SlotToClass or nil
                local itemsAlphabetized = itemLibrary and itemLibrary.ItemsAlphabetized or nil
                local items = itemLibrary and itemLibrary.Items or nil
                local classData = type(slotToClass) == 'table' and slotIndex and slotToClass[slotIndex] or nil
                local className = classData and classData.Name or slotName

                if type(itemsAlphabetized) == 'table' and type(items) == 'table' then
                    for _, weaponName in ipairs(itemsAlphabetized) do
                        local weaponData = items[weaponName]
                        if weaponData and weaponData.Class == className and RivalsAutoLoadout.IsAllowedWeaponName(slotName, weaponName) then
                            values[#values + 1] = weaponName
                        end
                    end
                    -- Only cache when the item library was actually available.
                    RivalsAutoLoadout.Catalog[cacheKey] = values
                end
                return values
            end

            function RivalsAutoLoadout.ResolveWeaponValues(slotName)
                return RivalsAutoLoadout.ResolveSeedWeaponValues(slotName)
            end

            function RivalsAutoLoadout.ResolveMapValues()
                local mapParser = RivalsRuntimeBridge.MapParser
                if mapParser and type(mapParser.ResolveMapValues) == 'function' then
                    return mapParser.ResolveMapValues()
                end
                return {'Arena', 'Crossroads', 'Dust', 'Depot', 'Facility', 'Rooftop', 'Cargo', 'Subzero', 'Colosseum', 'Underground', 'Backrooms', 'Shooting Range'}
            end

            function RivalsAutoLoadout.ResolveDefaultWeapons()
                local cachedDefaults = RivalsAutoLoadout.Catalog.DefaultWeapons
                if cachedDefaults then
                    return cachedDefaults
                end

                local defaults = {}
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local constantsModule = modules and modules:FindFirstChild('Constants')
                if constantsModule then
                    local ok, constants = pcall(require, constantsModule)
                    local configuredDefaults = ok and type(constants) == 'table' and constants.DEFAULT_WEAPONS or nil
                    if type(configuredDefaults) == 'table' then
                        for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                            local weaponName = configuredDefaults[slotConfig.SlotIndex]
                                or configuredDefaults[slotConfig.Name]
                            if RivalsAutoLoadout.IsAllowedWeaponName(slotConfig.Name, weaponName) then
                                defaults[slotConfig.Name] = weaponName
                            end
                        end
                    end
                end

                for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                    if not defaults[slotConfig.Name] then
                        defaults[slotConfig.Name] = RivalsAutoLoadout.ResolveWeaponValues(slotConfig.Name)[1]
                            or RivalsAutoLoadout.Unselected
                    end
                end

                RivalsAutoLoadout.Catalog.DefaultWeapons = defaults
                return defaults
            end

            function RivalsAutoLoadout.ResolveActiveProfileKeys()
                local mapKey = 'Default'
                if Toggles.P8S5T3 and Toggles.P8S5T3.Value == true then
                    local mapOption = Options.P8S5D7
                    if mapOption and type(mapOption.Value) == 'string' and mapOption.Value ~= '' then
                        mapKey = mapOption.Value
                    end
                end

                local priority = '1'
                if Toggles.P8S5T4 and Toggles.P8S5T4.Value == true then
                    local priorityOption = Options.P8S5D8
                    if priorityOption and table.find(RivalsAutoLoadout.Priorities, priorityOption.Value) then
                        priority = priorityOption.Value
                    end
                end

                return mapKey, priority
            end

            function RivalsAutoLoadout.ResolveProfile(mapKey, priority, create)
                mapKey = type(mapKey) == 'string' and mapKey ~= '' and mapKey or 'Default'
                priority = table.find(RivalsAutoLoadout.Priorities, priority) and priority or '1'

                local mapProfiles = RivalsAutoLoadoutState.Profiles[mapKey]
                if not mapProfiles and create then
                    mapProfiles = {}
                    RivalsAutoLoadoutState.Profiles[mapKey] = mapProfiles
                end

                local profile = mapProfiles and mapProfiles[priority] or nil
                if not profile and create then
                    profile = {}
                    local defaultWeapons = RivalsAutoLoadout.ResolveDefaultWeapons()
                    for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                        profile[slotConfig.Name] = mapKey == 'Default' and priority == '1'
                            and defaultWeapons[slotConfig.Name]
                            or RivalsAutoLoadout.Unselected
                    end
                    mapProfiles[priority] = profile
                end

                return profile
            end

            function RivalsAutoLoadout.ResolveActiveProfile(create)
                local mapKey, priority = RivalsAutoLoadout.ResolveActiveProfileKeys()
                return RivalsAutoLoadout.ResolveProfile(mapKey, priority, create), mapKey, priority
            end

            function RivalsAutoLoadout.NormalizeSelection(slotConfig, selection, allowUnselected)
                local values = RivalsAutoLoadout.ResolveWeaponValues(slotConfig.Name)
                if type(selection) == 'string' then
                    if allowUnselected and selection == RivalsAutoLoadout.Unselected then
                        return selection
                    end
                    if table.find(values, selection) then
                        return selection
                    end
                elseif type(selection) == 'table' then
                    for _, weaponName in ipairs(values) do
                        if selection[weaponName] == true or table.find(selection, weaponName) then
                            return weaponName
                        end
                    end
                end

                if allowUnselected then
                    return RivalsAutoLoadout.Unselected
                end
                return RivalsAutoLoadout.ResolveDefaultWeapons()[slotConfig.Name]
                    or values[1]
                    or RivalsAutoLoadout.Unselected
            end

            function RivalsAutoLoadout.ResetState()
                RivalsAutoLoadoutState.HasRunThisOpen = false
                RivalsAutoLoadoutState.OpenNonce = RivalsAutoLoadoutState.OpenNonce + 1
            end

            function RivalsAutoLoadout.ResolvePagesFrame()
                local playerGui = LP:FindFirstChild('PlayerGui')
                local mainGui = playerGui and playerGui:FindFirstChild('MainGui')
                local mainFrame = mainGui and mainGui:FindFirstChild('MainFrame')
                return mainFrame and mainFrame:FindFirstChild('Pages') or nil
            end

            function RivalsAutoLoadout.ResolvePageFrame(pageName)
                if type(pageName) ~= 'string' or pageName == '' then
                    return nil
                end

                local pagesFrame = RivalsAutoLoadout.ResolvePagesFrame()
                local pageFrame = pagesFrame and pagesFrame:FindFirstChild(pageName)
                if pageFrame and pageFrame:IsA('GuiObject') then
                    return pageFrame
                end

                return nil
            end

            function RivalsAutoLoadout.IsPageFrameVisible(pageFrame)
                return pageFrame and pageFrame.Visible == true and pageFrame.AbsoluteSize.X > 0 and pageFrame.AbsoluteSize.Y > 0
            end

            function RivalsAutoLoadout.ResolveSavedSelection(slotConfig)
                if not slotConfig then
                    return nil
                end

                local profile, mapKey, priority = RivalsAutoLoadout.ResolveActiveProfile(true)
                local allowUnselected = mapKey ~= 'Default' or priority ~= '1'
                local savedSelection = RivalsAutoLoadout.NormalizeSelection(
                    slotConfig,
                    profile[slotConfig.Name],
                    allowUnselected
                )
                profile[slotConfig.Name] = savedSelection
                return savedSelection
            end

            function RivalsAutoLoadout.SyncSavedSelection(slotConfig)
                if not slotConfig then
                    return
                end

                local option = Options[slotConfig.OptionId]
                if not option then
                    return
                end

                local profile, mapKey, priority = RivalsAutoLoadout.ResolveActiveProfile(true)
                local allowUnselected = mapKey ~= 'Default' or priority ~= '1'
                profile[slotConfig.Name] = RivalsAutoLoadout.NormalizeSelection(
                    slotConfig,
                    option.Value,
                    allowUnselected
                )
            end

            function RivalsAutoLoadout.ResolveVisibleSelectionValues(slotConfig, values)
                local savedSelection = RivalsAutoLoadout.ResolveSavedSelection(slotConfig)
                if table.find(values or {}, savedSelection) then
                    return savedSelection
                end
                return (values or {})[1]
            end

            function RivalsAutoLoadout.ResolvePageController(pageName)
                if type(pageName) ~= 'string' or pageName == '' then
                    return nil
                end

                local cachedPageController = RivalsAutoLoadout.Catalog[pageName]
                if cachedPageController then
                    return cachedPageController
                end

                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local pages = modules and modules:FindFirstChild('Pages')
                local pageModule = pages and pages:FindFirstChild(pageName)
                if not pageModule then
                    return nil
                end

                local ok, pageController = pcall(require, pageModule)
                if not ok or type(pageController) ~= 'table' then
                    return nil
                end

                RivalsAutoLoadout.Catalog[pageName] = pageController
                return pageController
            end

            function RivalsAutoLoadout.ResolveOpenPageController()
                for _, pageName in ipairs(RivalsAutoLoadout.PageNames) do
                    local pageFrame = RivalsAutoLoadout.ResolvePageFrame(pageName)
                    if RivalsAutoLoadout.IsPageFrameVisible(pageFrame) then
                        local pageController = RivalsAutoLoadout.ResolvePageController(pageName)
                        if pageController then
                            return pageName, pageController
                        end
                    end
                end

                return nil, nil
            end

            function RivalsAutoLoadout.ReadVisibleWeaponValues(pageController)
                if not pageController then
                    return nil, nil
                end

                local slotConfig = RivalsAutoLoadout.SlotOrder[pageController._current_slot]
                if not slotConfig then
                    return nil, nil
                end

                local listFrame = pageController.List
                local container = listFrame and listFrame:FindFirstChild('Container')
                if not container then
                    return slotConfig, nil
                end

                local orderedValues = {}
                for _, child in ipairs(container:GetChildren()) do
                    if child.Name == 'WeaponSlot' and child.Visible ~= false then
                        local button = child:FindFirstChild('Button')
                        local title = button and button:FindFirstChild('Title')
                        local locked = button and button:FindFirstChild('Locked')
                        local banned = button and button:FindFirstChild('Banned')
                        local weaponName = title and title.Text or nil
                        if type(weaponName) == 'string' then
                            weaponName = weaponName:match('^%s*(.-)%s*$')
                        end

                        if RivalsAutoLoadout.IsAllowedWeaponName(slotConfig.Name, weaponName) and (not locked or locked.Visible ~= true) and (not banned or banned.Visible ~= true) then
                            orderedValues[#orderedValues + 1] = {
                                Name = weaponName,
                                Order = child.LayoutOrder,
                            }
                        end
                    end
                end

                table.sort(orderedValues, function(left, right)
                    if left.Order == right.Order then
                        return left.Name < right.Name
                    end

                    return left.Order < right.Order
                end)

                local seen = {}
                local values = {}
                for _, entry in ipairs(orderedValues) do
                    if seen[entry.Name] ~= true then
                        seen[entry.Name] = true
                        values[#values + 1] = entry.Name
                    end
                end

                return slotConfig, values
            end

            function RivalsAutoLoadout.RefreshDropdownOption(slotConfig)
                if not slotConfig then
                    return
                end

                local option = Options[slotConfig.OptionId]
                if not option or type(option.SetValues) ~= 'function' then
                    return
                end

                local sourceValues = RivalsAutoLoadout.ResolveWeaponValues(slotConfig.Name)
                local _, mapKey, priority = RivalsAutoLoadout.ResolveActiveProfile(true)
                local values = {}
                if mapKey ~= 'Default' or priority ~= '1' then
                    values[#values + 1] = RivalsAutoLoadout.Unselected
                end
                for _, weaponName in ipairs(sourceValues) do
                    values[#values + 1] = weaponName
                end
                local visibleSelectionValue = RivalsAutoLoadout.ResolveVisibleSelectionValues(slotConfig, values)

                RivalsAutoLoadoutState.RefreshingDropdownValues = RivalsAutoLoadoutState.RefreshingDropdownValues + 1
                pcall(function()
                    option:SetValues(values)
                end)
                if type(option.SetValue) == 'function' then
                    pcall(function()
                        option:SetValue(visibleSelectionValue)
                    end)
                end
                RivalsAutoLoadoutState.RefreshingDropdownValues = RivalsAutoLoadoutState.RefreshingDropdownValues - 1
            end

            function RivalsAutoLoadout.RefreshDropdownOptions()
                for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                    RivalsAutoLoadout.RefreshDropdownOption(slotConfig)
                end
            end

            function RivalsAutoLoadout.CapturePageWeaponValues(pageController)
                local slotConfig, values = RivalsAutoLoadout.ReadVisibleWeaponValues(pageController)
                if not slotConfig or type(values) ~= 'table' or #values <= 0 then
                    return false
                end

                local previousValues = RivalsAutoLoadout.LiveValuesBySlot[slotConfig.Name]
                local hasChanged = type(previousValues) ~= 'table' or #previousValues ~= #values
                if not hasChanged and previousValues then
                    for index, weaponName in ipairs(values) do
                        if previousValues[index] ~= weaponName then
                            hasChanged = true
                            break
                        end
                    end
                end

                if not hasChanged then
                    return false
                end

                RivalsAutoLoadout.LiveValuesBySlot[slotConfig.Name] = values
                RivalsAutoLoadout.RefreshDropdownOption(slotConfig)
                return true
            end

            function RivalsAutoLoadout.BindChosenSlotInputs(pageName, pageController)
                local chosenWeaponSlots = pageController and pageController._chosen_weapon_slots
                if type(chosenWeaponSlots) ~= 'table' then
                    return
                end

                for slotIndex, chosenSlot in ipairs(chosenWeaponSlots) do
                    local button = chosenSlot and chosenSlot:FindFirstChild('Button')
                    if button and button:IsA('GuiButton') then
                        Connections:register(string.format('AutoLoadout_%s_ChosenSlot_%d', pageName, slotIndex), button.Activated:Connect(GuardRivalsCallback(string.format('AutoLoadout_%s_ChosenSlot_%d', pageName, slotIndex), function()
                            task.defer(function()
                                RivalsAutoLoadout.CapturePageWeaponValues(pageController)
                            end)
                        end)))
                    end
                end
            end

            function RivalsAutoLoadout.ResolveSlotSelection(slotConfig)
                if not slotConfig then
                    return nil
                end
                local selectedWeaponName = RivalsAutoLoadout.ResolveSavedSelection(slotConfig)
                return selectedWeaponName ~= RivalsAutoLoadout.Unselected and selectedWeaponName or nil
            end

            function RivalsAutoLoadout.IsWeaponSelected(slotConfig, weaponName)
                if not slotConfig or type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end

                local savedSelection = RivalsAutoLoadout.ResolveSavedSelection(slotConfig)
                return savedSelection == weaponName
            end

            function RivalsAutoLoadout.ResolveCurrentMapName()
                local mapParser = RivalsRuntimeBridge.MapParser
                if mapParser and type(mapParser.ResolveCurrentMapName) == 'function' then
                    return mapParser.ResolveCurrentMapName()
                end
                return 'Default'
            end

            function RivalsAutoLoadout.ResolveRuntimeMapKey()
                if Toggles.P8S5T3 and Toggles.P8S5T3.Value == true then
                    return RivalsAutoLoadout.ResolveCurrentMapName()
                end
                return 'Default'
            end

            function RivalsAutoLoadout.IsRuntimeSelectionAvailable(slotConfig, weaponName)
                if not slotConfig or type(weaponName) ~= 'string' or weaponName == ''
                    or weaponName == RivalsAutoLoadout.Unselected then
                    return false
                end
                local liveValues = RivalsAutoLoadout.LiveValuesBySlot[slotConfig.Name]
                return type(liveValues) ~= 'table' or #liveValues == 0 or table.find(liveValues, weaponName) ~= nil
            end

            function RivalsAutoLoadout.ResolveSelectedWeaponName(slotConfig, profile)
                if not slotConfig or type(profile) ~= 'table' then
                    return nil
                end
                local selectedWeaponName = RivalsAutoLoadout.NormalizeSelection(slotConfig, profile[slotConfig.Name], true)
                return RivalsAutoLoadout.IsRuntimeSelectionAvailable(slotConfig, selectedWeaponName)
                    and selectedWeaponName
                    or nil
            end

            function RivalsAutoLoadout.BuildChosenWeapons(maxSlots)
                local mapKey = RivalsAutoLoadout.ResolveRuntimeMapKey()
                if not mapKey then
                    return nil
                end

                local chosenWeapons = {}
                if Toggles.P8S5T4 and Toggles.P8S5T4.Value == true then
                    for priorityIndex = #RivalsAutoLoadout.Priorities, 1, -1 do
                        local priority = RivalsAutoLoadout.Priorities[priorityIndex]
                        local profile = RivalsAutoLoadout.ResolveProfile(mapKey, priority, true)
                        for slotIndex = 1, maxSlots do
                            local slotConfig = RivalsAutoLoadout.SlotOrder[slotIndex]
                            local selectedWeaponName = RivalsAutoLoadout.ResolveSelectedWeaponName(slotConfig, profile)
                            if selectedWeaponName then
                                chosenWeapons[slotConfig.SlotIndex] = selectedWeaponName
                            end
                        end
                    end
                else
                    local profile = RivalsAutoLoadout.ResolveProfile(mapKey, '1', true)
                    for slotIndex = 1, maxSlots do
                        local slotConfig = RivalsAutoLoadout.SlotOrder[slotIndex]
                        local selectedWeaponName = RivalsAutoLoadout.ResolveSelectedWeaponName(slotConfig, profile)
                        if not selectedWeaponName then
                            return nil
                        end
                        chosenWeapons[slotConfig.SlotIndex] = selectedWeaponName
                    end
                end

                for slotIndex = 1, maxSlots do
                    local slotConfig = RivalsAutoLoadout.SlotOrder[slotIndex]
                    if not chosenWeapons[slotConfig.SlotIndex] then
                        return nil
                    end
                end
                return chosenWeapons
            end

            function RivalsAutoLoadout.ApplyPageController(pageController)
                if not pageController or pageController._is_open ~= true then
                    return nil
                end

                local pageFrame = pageController.PageFrame
                if not pageFrame or pageFrame.Visible ~= true or pageFrame.AbsoluteSize.X <= 0 or pageFrame.AbsoluteSize.Y <= 0 then
                    return nil
                end

                local chosenWeaponSlots = pageController._chosen_weapon_slots
                if type(chosenWeaponSlots) ~= 'table' then
                    return nil
                end

                local maxSlots = math.min(#pageController._chosen_weapon_slots, #RivalsAutoLoadout.SlotOrder)
                if maxSlots <= 0 then
                    return nil
                end

                RivalsAutoLoadout.CapturePageWeaponValues(pageController)

                local chosenWeapons = RivalsAutoLoadout.BuildChosenWeapons(maxSlots)
                if not chosenWeapons then
                    return false
                end

                pageController._chosen_weapons = chosenWeapons
                __akira_boot_log('AutoLoadout: submitting loadout (Finish)')
                local ok, finishError = pcall(pageController.Finish, pageController)
                if not ok then
                    ReportRivalsRuntimeIssue('auto_loadout_finish', finishError)
                end
                return ok
            end

            function RivalsAutoLoadout.ScheduleSubmit(pageName, pageController, openNonce, attempt)
                if not pageController then
                    return
                end

                if openNonce ~= RivalsAutoLoadoutState.OpenNonce then
                    return
                end

                if not RivalsAutoLoadout.IsEnabled() or RivalsAutoLoadoutState.HasRunThisOpen then
                    return
                end

                local appliedPage = RivalsAutoLoadout.ApplyPageController(pageController)
                if appliedPage == true then
                    RivalsAutoLoadoutState.HasRunThisOpen = true
                    return
                end

                if attempt >= RivalsAutoLoadout.OpenRetryLimit then
                    return
                end

                task.delay(RivalsAutoLoadout.OpenRetryDelay, GuardRivalsCallback(string.format('AutoLoadout_%s_Retry_%d', pageName, attempt), function()
                    RivalsAutoLoadout.ScheduleSubmit(pageName, pageController, openNonce, attempt + 1)
                end))
            end

            function RivalsAutoLoadout.QueuePageControllerSubmit(pageName, pageController)
                if not pageController or not RivalsAutoLoadout.IsEnabled() then
                    return
                end

                local openNonce = RivalsAutoLoadoutState.OpenNonce + 1
                RivalsAutoLoadoutState.OpenNonce = openNonce
                RivalsAutoLoadoutState.HasRunThisOpen = false

                task.defer(GuardRivalsCallback(string.format('AutoLoadout_%s_Open', pageName), function()
                    RivalsAutoLoadout.ScheduleSubmit(pageName, pageController, openNonce, 1)
                end))
            end

            function RivalsAutoLoadout.QueueVisiblePageSubmit()
                if not RivalsAutoLoadout.IsEnabled() then
                    return
                end

                local pageName, pageController = RivalsAutoLoadout.ResolveOpenPageController()
                if not pageController then
                    return
                end

                RivalsAutoLoadout.QueuePageControllerSubmit(pageName, pageController)
            end

            function RivalsAutoLoadout.BindPageController(pageName, pageController)
                local boundPageControllers = RivalsAutoLoadoutState.BoundPageControllers
                if boundPageControllers[pageName] == true then
                    return
                end

                pageController = pageController or RivalsAutoLoadout.ResolvePageController(pageName)
                if not pageController then
                    return
                end

                boundPageControllers[pageName] = true
                RivalsAutoLoadout.BindChosenSlotInputs(pageName, pageController)
            end

            function RivalsAutoLoadout.HandlePageFrameVisibility(pageName)
                local pageFrame = RivalsAutoLoadout.ResolvePageFrame(pageName)
                if not RivalsAutoLoadout.IsPageFrameVisible(pageFrame) then
                    RivalsAutoLoadout.ResetState()
                    return
                end

                local pageController = RivalsAutoLoadout.ResolvePageController(pageName)
                if not pageController then
                    return
                end

                RivalsAutoLoadout.BindPageController(pageName, pageController)
                RivalsAutoLoadout.CapturePageWeaponValues(pageController)
                RivalsAutoLoadout.QueuePageControllerSubmit(pageName, pageController)
            end

            function RivalsAutoLoadout.BindPageFrame(pageName, pageFrame)
                local boundPageFrames = RivalsAutoLoadoutState.BoundPageFrames
                if boundPageFrames[pageName] == true then
                    return
                end

                pageFrame = pageFrame or RivalsAutoLoadout.ResolvePageFrame(pageName)
                if not pageFrame then
                    return
                end

                boundPageFrames[pageName] = true
                Connections:register(string.format('AutoLoadout_%s_Visible', pageName), pageFrame:GetPropertyChangedSignal('Visible'):Connect(GuardRivalsCallback(string.format('AutoLoadout_%s_Visible', pageName), function()
                    RivalsAutoLoadout.HandlePageFrameVisibility(pageName)
                end)))

                if RivalsAutoLoadout.IsPageFrameVisible(pageFrame) then
                    RivalsAutoLoadout.HandlePageFrameVisibility(pageName)
                end
            end

            function RivalsAutoLoadout.BindPageControllers()
                task.spawn(GuardRivalsCallback('AutoLoadout_BindControllers', function()
                    local playerGui = WaitForChildRetry(LP, 'PlayerGui', 0.4)
                    local mainGui = playerGui and WaitForChildRetry(playerGui, 'MainGui', 0.4)
                    local mainFrame = mainGui and WaitForChildRetry(mainGui, 'MainFrame', 0.4)
                    local pagesFrame = mainFrame and WaitForChildRetry(mainFrame, 'Pages', 0.4)
                    if not pagesFrame then
                        return
                    end

                    Connections:register('AutoLoadout_PagesChildAdded', pagesFrame.ChildAdded:Connect(GuardRivalsCallback('AutoLoadout_PagesChildAdded', function(child)
                        if not child or not child:IsA('GuiObject') then
                            return
                        end

                        local pageFrame = child
                        for _, pageName in ipairs(RivalsAutoLoadout.PageNames) do
                            if pageName == pageFrame.Name then
                                RivalsAutoLoadout.BindPageFrame(pageName, pageFrame)
                                break
                            end
                        end
                    end)))

                    for _, pageName in ipairs(RivalsAutoLoadout.PageNames) do
                        RivalsAutoLoadout.BindPageFrame(pageName)
                    end
                end))
            end

            function RivalsAutoLoadout.NormalizeProfiles(profiles)
                local normalized = {}
                if type(profiles) == 'table' then
                    for mapKey, mapProfiles in pairs(profiles) do
                        if type(mapKey) == 'string' and mapKey ~= '' and type(mapProfiles) == 'table' then
                            local normalizedMap = {}
                            for _, priority in ipairs(RivalsAutoLoadout.Priorities) do
                                local profile = mapProfiles[priority]
                                if type(profile) == 'table' then
                                    local normalizedProfile = {}
                                    for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                                        normalizedProfile[slotConfig.Name] = RivalsAutoLoadout.NormalizeSelection(
                                            slotConfig,
                                            profile[slotConfig.Name] or profile[slotConfig.SlotIndex],
                                            mapKey ~= 'Default' or priority ~= '1'
                                        )
                                    end
                                    normalizedMap[priority] = normalizedProfile
                                end
                            end
                            if next(normalizedMap) ~= nil then
                                normalized[mapKey] = normalizedMap
                            end
                        end
                    end
                end

                RivalsAutoLoadoutState.Profiles = normalized
                RivalsAutoLoadout.ResolveProfile('Default', '1', true)
                return normalized
            end

            function RivalsAutoLoadout.SetConfigName(configName)
                if type(configName) == 'string' and configName ~= '' then
                    RivalsAutoLoadoutState.ConfigName = configName
                end
            end

            function RivalsAutoLoadout.LoadProfilesFromConfig()
                local configPath = ScriptPaths.config_path(RivalsAutoLoadoutState.ConfigName or 'RIVALS Default')
                if not isfile(configPath) then
                    RivalsAutoLoadout.NormalizeProfiles({})
                    RivalsAutoLoadout.RefreshDropdownOptions()
                    return false
                end

                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    return false
                end
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                local objects = decodeOk and type(decoded) == 'table' and decoded.objects or nil
                if type(objects) ~= 'table' then
                    return false
                end

                local profiles = nil
                for _, object in ipairs(objects) do
                    if object and object.idx == RivalsAutoLoadout.ConfigMetadataId then
                        profiles = object.value
                        break
                    end
                end
                RivalsAutoLoadout.NormalizeProfiles(profiles or {})
                RivalsAutoLoadout.RefreshDropdownOptions()
                return profiles ~= nil
            end

            function RivalsAutoLoadout.SaveProfilesToConfig()
                local configPath = ScriptPaths.config_path(RivalsAutoLoadoutState.ConfigName or 'RIVALS Default')
                if not isfile(configPath) then
                    return false
                end

                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    return false
                end
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                if not decodeOk or type(decoded) ~= 'table' then
                    return false
                end

                local existingObjects = type(decoded.objects) == 'table' and decoded.objects or {}
                local mergedObjects = {}
                for _, object in ipairs(existingObjects) do
                    if not object or object.idx ~= RivalsAutoLoadout.ConfigMetadataId then
                        mergedObjects[#mergedObjects + 1] = object
                    end
                end
                mergedObjects[#mergedObjects + 1] = {
                    idx = RivalsAutoLoadout.ConfigMetadataId,
                    type = 'AkiraMetadata',
                    value = RivalsAutoLoadout.NormalizeProfiles(RivalsAutoLoadoutState.Profiles),
                }
                decoded.objects = mergedObjects
                return pcall(function()
                    writefile(configPath, HttpService:JSONEncode(decoded))
                end)
            end

            RivalsRuntimeBridge.BindAutoLoadoutControllers = RivalsAutoLoadout.BindPageControllers
            RivalsRuntimeBridge.QueueAutoLoadoutSubmission = RivalsAutoLoadout.QueueVisiblePageSubmit
            RivalsRuntimeBridge.ResolveAutoLoadoutWeaponValues = RivalsAutoLoadout.ResolveWeaponValues
            RivalsRuntimeBridge.ResolveAutoLoadoutDefaultWeapon = function(slotName)
                return RivalsAutoLoadout.ResolveDefaultWeapons()[slotName]
            end
            RivalsRuntimeBridge.ResolveAutoLoadoutMapValues = RivalsAutoLoadout.ResolveMapValues
            RivalsRuntimeBridge.ResolveAutoLoadoutPriorities = function()
                return RivalsAutoLoadout.Priorities
            end
            RivalsRuntimeBridge.RefreshAutoLoadoutDropdownValues = RivalsAutoLoadout.RefreshDropdownOptions
            RivalsRuntimeBridge.SyncAutoLoadoutSelection = function(optionId)
                for _, slotConfig in ipairs(RivalsAutoLoadout.SlotOrder) do
                    if slotConfig.OptionId == optionId then
                        RivalsAutoLoadout.SyncSavedSelection(slotConfig)
                        break
                    end
                end
            end
            RivalsRuntimeBridge.SetAutoLoadoutConfigName = RivalsAutoLoadout.SetConfigName
            RivalsRuntimeBridge.LoadAutoLoadoutProfiles = RivalsAutoLoadout.LoadProfilesFromConfig
            RivalsRuntimeBridge.SaveAutoLoadoutProfiles = RivalsAutoLoadout.SaveProfilesToConfig
            RivalsRuntimeBridge.ResetAutoLoadoutState = RivalsAutoLoadout.ResetState
            end

            do
            local RivalsAutoBan = {
                State = {
                    Controller = nil,
                    BoundDuel = nil,
                    LastVoteType = nil,
                    LastSubmitted = nil,
                },
            }

            function RivalsAutoBan.IsEnabled()
                return Toggles.P8S5T2 and Toggles.P8S5T2.Value == true
            end

            function RivalsAutoBan.IsMapVoteEnabled()
                return Toggles.P8S5T5 and Toggles.P8S5T5.Value == true
            end

            function RivalsAutoBan.IsAnyEnabled()
                return RivalsAutoBan.IsEnabled() or RivalsAutoBan.IsMapVoteEnabled()
            end

            function RivalsAutoBan.Read(object, key)
                if not object then
                    return nil
                end
                if type(object.Get) == 'function' then
                    local ok, value = pcall(object.Get, object, key)
                    if ok then
                        return value
                    end
                end
                return object[key]
            end

            function RivalsAutoBan.ResolveController()
                if RivalsAutoBan.State.Controller then
                    return RivalsAutoBan.State.Controller
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local controllerModule = controllers and controllers:FindFirstChild('DuelController')
                if not controllerModule then
                    return nil
                end
                local ok, controller = pcall(require, controllerModule)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                RivalsAutoBan.State.Controller = controller
                return controller
            end

            function RivalsAutoBan.ResolveWeaponValues()
                local values = {}
                local seen = {}
                for _, slotName in ipairs({'Primary', 'Secondary', 'Melee', 'Utility'}) do
                    for _, weaponName in ipairs(RivalsRuntimeBridge.ResolveAutoLoadoutWeaponValues(slotName)) do
                        if type(weaponName) == 'string' and weaponName ~= '' and not seen[weaponName] then
                            seen[weaponName] = true
                            table.insert(values, weaponName)
                        end
                    end
                end
                table.sort(values)
                return values
            end

            function RivalsAutoBan.IsSelected(optionId, weaponName)
                local option = Options[optionId]
                local selected = option and option.Value
                if type(selected) ~= 'table' then
                    return false
                end
                if selected[weaponName] == true then
                    return true
                end
                for _, selectedName in ipairs(selected) do
                    if selectedName == weaponName then
                        return true
                    end
                end
                return false
            end

            function RivalsAutoBan.ResolveMapValues()
                return RivalsRuntimeBridge.ResolveAutoLoadoutMapValues()
            end

            function RivalsAutoBan.IsMapSelected(mapName)
                return RivalsAutoBan.IsSelected('P8S5D9', mapName)
            end

            function RivalsAutoBan.ResolveLocalDueler(duel)
                if type(duel.GetDueler) ~= 'function' then
                    return nil
                end
                local ok, dueler = pcall(duel.GetDueler, duel, LP)
                if ok and dueler then
                    return dueler
                end
                ok, dueler = pcall(duel.GetDueler, duel, LP.UserId)
                return ok and dueler or nil
            end

            function RivalsAutoBan.IsOptionBanned(voteOptions, optionName)
                if type(voteOptions) ~= 'table' or optionName == nil then
                    return false
                end
                for _, option in pairs(voteOptions) do
                    if RivalsAutoBan.Read(option, 'Name') == optionName then
                        return RivalsAutoBan.Read(option, 'IsBanned') ~= nil
                    end
                end
                return false
            end

            function RivalsAutoBan.BansRemaining(duel, voteType)
                local localDueler = RivalsAutoBan.ResolveLocalDueler(duel)
                local teamId = RivalsAutoBan.Read(localDueler, 'TeamID')
                if teamId == nil then
                    return 0
                end
                local maxKey = voteType == 'Weapons' and 'MaxWeaponBansPerTeam' or 'MaxMapBansPerTeam'
                local maxBans = tonumber(RivalsAutoBan.Read(duel, maxKey)) or 0
                local bansByTeam = RivalsAutoBan.Read(duel, 'VoteBansRemaining')
                local bansUsed = type(bansByTeam) == 'table' and tonumber(bansByTeam[teamId]) or 0
                return maxBans - bansUsed
            end

            function RivalsAutoBan.TryVote()
                if not RivalsAutoBan.IsAnyEnabled() then
                    return false, 'disabled'
                end

                local controller = RivalsAutoBan.ResolveController()
                local duel = RivalsAutoBan.State.BoundDuel or (controller and controller.CurrentObject)
                if not duel then
                    RivalsAutoBan.State.LastVoteType = nil
                    RivalsAutoBan.State.LastSubmitted = nil
                    return false, 'no_duel'
                end

                local voteType = RivalsAutoBan.Read(duel, 'VoteOptionsType')
                if voteType ~= RivalsAutoBan.State.LastVoteType then
                    RivalsAutoBan.State.LastVoteType = voteType
                    RivalsAutoBan.State.LastSubmitted = nil
                end
                if voteType == nil then
                    return false, 'no_vote'
                end

                local voteOptions = RivalsAutoBan.Read(duel, 'VoteOptions')
                if type(voteOptions) ~= 'table' or next(voteOptions) == nil then
                    return false, 'no_vote'
                end

                if RivalsAutoBan.State.LastSubmitted ~= nil
                    and not RivalsAutoBan.IsOptionBanned(voteOptions, RivalsAutoBan.State.LastSubmitted) then
                    return false, 'already_voted'
                end

                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                local duels = remotes and remotes:FindFirstChild('Duels')
                local voteRemote = duels and duels:FindFirstChild('Vote')
                if not voteRemote or not voteRemote:IsA('RemoteEvent') then
                    return false, 'no_vote_remote'
                end

                if voteType == 'Maps' then
                    if not RivalsAutoBan.IsMapVoteEnabled() then
                        return false, 'map_vote_disabled'
                    end
                    if not RivalsAutoBan.ResolveLocalDueler(duel) then
                        return false, 'not_dueler'
                    end
                    if RivalsAutoBan.Read(duel, 'MaxMapBansPerTeam') ~= nil
                        and RivalsAutoBan.BansRemaining(duel, 'Maps') <= 0 then
                        return false, 'bans_complete'
                    end

                    for _, option in pairs(voteOptions) do
                        local mapName = RivalsAutoBan.Read(option, 'Name')
                        if mapName and RivalsAutoBan.Read(option, 'IsBanned') == nil
                            and RivalsAutoBan.IsMapSelected(mapName) then
                            RivalsAutoBan.State.LastSubmitted = mapName
                            local ok, err = pcall(voteRemote.FireServer, voteRemote, mapName)
                            if not ok then
                                RivalsAutoBan.State.LastSubmitted = nil
                                return false, tostring(err)
                            end
                            return true
                        end
                    end
                    return false, 'no_selected_map'
                end

                if voteType ~= 'Weapons' or not RivalsAutoBan.IsEnabled() then
                    return false, 'no_weapon_vote'
                end

                local bansRemaining = RivalsAutoBan.BansRemaining(duel, 'Weapons')
                if bansRemaining <= 0 then
                    return false, 'bans_complete'
                end
                local selectionIds = { 'P8S5D5', 'P8S5D6' }
                local selectionId = selectionIds[#selectionIds - bansRemaining + 1]
                if not selectionId then
                    return false, 'no_ban_list'
                end

                for _, option in pairs(voteOptions) do
                    local weaponName = RivalsAutoBan.Read(option, 'Name')
                    if weaponName and RivalsAutoBan.Read(option, 'IsBanned') == nil
                        and RivalsAutoBan.IsSelected(selectionId, weaponName) then
                        RivalsAutoBan.State.LastSubmitted = weaponName
                        local ok, err = pcall(voteRemote.FireServer, voteRemote, weaponName)
                        if not ok then
                            RivalsAutoBan.State.LastSubmitted = nil
                            return false, tostring(err)
                        end
                        return true
                    end
                end
                return false, 'no_selected_option'
            end

            function RivalsAutoBan.BindDuel(duel)
                if not Connections then
                    return
                end
                Connections:disconnect({
                    'AutoBan_VoteOptionsType',
                    'AutoBan_VoteOptions',
                    'AutoBan_VoteBansRemaining',
                    'AutoBan_MaxWeaponBansPerTeam',
                    'AutoBan_MaxMapBansPerTeam',
                })
                RivalsAutoBan.State.BoundDuel = duel
                RivalsAutoBan.State.LastVoteType = nil
                RivalsAutoBan.State.LastSubmitted = nil
                if not duel or type(duel.GetDataChangedSignal) ~= 'function' then
                    return
                end
                for _, key in ipairs({'VoteOptionsType', 'VoteOptions', 'VoteBansRemaining', 'MaxWeaponBansPerTeam', 'MaxMapBansPerTeam'}) do
                    local ok, signal = pcall(duel.GetDataChangedSignal, duel, key)
                    if ok and signal and type(signal.Connect) == 'function' then
                        Connections:register('AutoBan_' .. key, signal:Connect(GuardRivalsCallback('AutoBan_' .. key, RivalsAutoBan.TryVote)))
                    end
                end
                RivalsAutoBan.TryVote()
            end

            function RivalsAutoBan.RegisterSignals()
                if not Connections then
                    return
                end
                if not RivalsAutoBan.IsAnyEnabled() then
                    RivalsAutoBan.Reset()
                    return
                end
                local controller = RivalsAutoBan.ResolveController()
                if not controller then
                    return
                end
                if controller.LocalPlayerJoinedDuel and type(controller.LocalPlayerJoinedDuel.Connect) == 'function' then
                    Connections:register('AutoBan_JoinedDuel', controller.LocalPlayerJoinedDuel:Connect(GuardRivalsCallback('AutoBan_JoinedDuel', function(duel)
                        RivalsAutoBan.BindDuel(duel or controller.CurrentObject)
                    end)))
                end
                if controller.LocalPlayerLeftDuel and type(controller.LocalPlayerLeftDuel.Connect) == 'function' then
                    Connections:register('AutoBan_LeftDuel', controller.LocalPlayerLeftDuel:Connect(GuardRivalsCallback('AutoBan_LeftDuel', function()
                        RivalsAutoBan.BindDuel(nil)
                    end)))
                end
                RivalsAutoBan.BindDuel(controller.CurrentObject)
            end

            function RivalsAutoBan.Reset()
                RivalsAutoBan.State.BoundDuel = nil
                RivalsAutoBan.State.LastVoteType = nil
                RivalsAutoBan.State.LastSubmitted = nil
                if Connections then
                    Connections:disconnect({
                        'AutoBan_JoinedDuel',
                        'AutoBan_LeftDuel',
                        'AutoBan_VoteOptionsType',
                        'AutoBan_VoteOptions',
                        'AutoBan_VoteBansRemaining',
                        'AutoBan_MaxWeaponBansPerTeam',
                        'AutoBan_MaxMapBansPerTeam',
                    })
                end
            end

            RivalsRuntimeBridge.ResolveAutoBanWeaponValues = RivalsAutoBan.ResolveWeaponValues
            RivalsRuntimeBridge.ResolveAutoVoteMapValues = RivalsAutoBan.ResolveMapValues
            RivalsRuntimeBridge.TryAutoBanVote = RivalsAutoBan.TryVote
            RivalsRuntimeBridge.RegisterAutoBanSignals = RivalsAutoBan.RegisterSignals
            RivalsRuntimeBridge.ResetAutoBanState = RivalsAutoBan.Reset
            end

            do
            local RivalsTripmineAutomation = {
                Entries = setmetatable({}, { __mode = 'k' }),
                DestroyingConnections = setmetatable({}, { __mode = 'k' }),
            }

            function RivalsTripmineAutomation.IsEnabled()
                return Toggles.P8S8T1 and Toggles.P8S8T1.Value == true
            end

            function RivalsTripmineAutomation.Untrack(tripmine)
                local entry = RivalsTripmineAutomation.Entries[tripmine]
                if entry and entry.Hitbox then
                    RivalsTripmineAutomation.Entries[entry.Hitbox] = nil
                end
                RivalsTripmineAutomation.Entries[tripmine] = nil
                local connection = RivalsTripmineAutomation.DestroyingConnections[tripmine]
                if connection then
                    pcall(function() connection:Disconnect() end)
                end
                RivalsTripmineAutomation.DestroyingConnections[tripmine] = nil
            end

            function RivalsTripmineAutomation.Track(tripmine)
                if not tripmine or RivalsTripmineAutomation.Entries[tripmine] then
                    return
                end
                task.spawn(GuardRivalsCallback('TripmineAutomation_Track', function()
                    local hitbox = tripmine:WaitForChild('Hitbox', 3)
                    if not hitbox or not hitbox:IsA('BasePart') or not tripmine.Parent then
                        return
                    end
                    local entry = {
                        Tripmine = tripmine,
                        Hitbox = hitbox,
                        EnvironmentId = tripmine:GetAttribute('EnvironmentID'),
                        PlacedBy = tripmine:GetAttribute('PlacedByUserID'),
                        TeamId = tripmine:GetAttribute('TeamID'),
                    }
                    RivalsTripmineAutomation.Entries[tripmine] = entry
                    RivalsTripmineAutomation.Entries[hitbox] = entry
                    RivalsTripmineAutomation.DestroyingConnections[tripmine] = hitbox.Destroying:Connect(
                        GuardRivalsCallback('TripmineAutomation_Destroying', function()
                            RivalsTripmineAutomation.Untrack(tripmine)
                        end)
                    )
                end))
            end

            function RivalsTripmineAutomation.Bind()
                local collectionService = game:GetService('CollectionService')
                Connections:register('TripmineAutomation_Added', collectionService:GetInstanceAddedSignal('SubspaceTripmine'):Connect(
                    GuardRivalsCallback('TripmineAutomation_Added', RivalsTripmineAutomation.Track)
                ))
                Connections:register('TripmineAutomation_Removed', collectionService:GetInstanceRemovedSignal('SubspaceTripmine'):Connect(
                    GuardRivalsCallback('TripmineAutomation_Removed', RivalsTripmineAutomation.Untrack)
                ))
                for _, tripmine in ipairs(collectionService:GetTagged('SubspaceTripmine')) do
                    RivalsTripmineAutomation.Track(tripmine)
                end
            end

            function RivalsTripmineAutomation.Update()
                LPH_ATTRIBUTES(VM(NONE))
                if not RivalsTripmineAutomation.IsEnabled() then
                    return
                end
                if not __akira_genv.AkiraCaps.gate('Subspace Tripmine Auto Trigger', 'firetouchinterest') then
                    return
                end

                local activeChar = RivalsRuntimeBridge.AcquireActiveCharacter()
                local touchPart = activeChar and (activeChar:FindFirstChild('HitboxBody') or activeChar:FindFirstChild('HumanoidRootPart')) or nil
                if not touchPart or not touchPart:IsA('BasePart') then
                    return
                end

                local fighter = ResolveLocalFighter()
                local localEnvironmentId = ReadFighterValue(fighter, 'EnvironmentID')
                    or activeChar:GetAttribute('EnvironmentID')
                local localTeamId = ReadFighterValue(fighter, 'TeamID')
                    or LP:GetAttribute('TeamID')

                for tripmine, entry in pairs(RivalsTripmineAutomation.Entries) do
                    if tripmine == entry.Tripmine then
                        local hitbox = entry.Hitbox
                        if not hitbox or not hitbox.Parent or not tripmine.Parent then
                            RivalsTripmineAutomation.Untrack(tripmine)
                        else
                            local friendly = entry.PlacedBy == LP.UserId
                            if not friendly and localTeamId ~= nil and entry.TeamId ~= nil then
                                friendly = localTeamId == entry.TeamId
                            end
                            local environmentMatches = localEnvironmentId == entry.EnvironmentId
                            local teamTrigger = Toggles.P8S8T2 and Toggles.P8S8T2.Value == true
                            local expectedTransparency = friendly and 0.5 or 1
                            if environmentMatches
                                and (not friendly or teamTrigger)
                                and hitbox.LocalTransparencyModifier == expectedTransparency then
                                firetouchinterest(hitbox, touchPart, 0)
                                firetouchinterest(hitbox, touchPart, 1)
                                return
                            end
                        end
                    end
                end
            end

            function RivalsTripmineAutomation.Reset()
                for tripmine, entry in pairs(RivalsTripmineAutomation.Entries) do
                    if tripmine == entry.Tripmine then
                        RivalsTripmineAutomation.Untrack(tripmine)
                    end
                end
                if Connections then
                    Connections:disconnect({'TripmineAutomation_Added', 'TripmineAutomation_Removed'})
                end
            end

            RivalsRuntimeBridge.BindTripmineAutomation = RivalsTripmineAutomation.Bind
            RivalsRuntimeBridge.UpdateTripmineAutomation = RivalsTripmineAutomation.Update
            RivalsRuntimeBridge.ResetTripmineAutomation = RivalsTripmineAutomation.Reset
            end

            (function()
            local AUTO_QUEUE_FALLBACK_MODES = {
                '1v1',
                '2v2',
                '3v3',
                '4v4',
                '5v5',
                'ranked_1v1',
                'ranked_2v2',
                'ranked_3v3',
            }
            local AUTO_QUEUE_FIRE_DEBOUNCE = 0.08
            local AUTO_QUEUE_RETRY_DELAY = 0.5

            local RivalsAutoQueue = {
                State = {
                    Believed = 'idle',
                    LastFireAt = 0,
                    LastModeFired = nil,
                    Modes = nil,
                    DisplayToKey = nil,
                    RefreshSuppress = false,
                    PlayAgainRegistrationQueued = false,
                    MatchEndedConfirmed = false,
                    RetryActive = false,
                    RetryAttempts = 0,
                    RetryToken = 0,
                    SkipPressActive = false,
                    SkipPressToken = 0,
                    MatchmakingController = nil,
                    ArcadeController = nil,
                    ArcadeModes = nil,
                    LastArcadeTeleportAt = 0,
                },
            }

            local function CollectActiveQueueKeys()
                local seen = {}
                local order = {}
                local function add(key)
                    if type(key) == 'string' and key ~= '' and not seen[key] then
                        seen[key] = true
                        table.insert(order, key)
                    end
                end

                local CollectionService = game:GetService('CollectionService')
                local okPads, pads = pcall(function() return CollectionService:GetTagged('QueuePad') end)
                if okPads and type(pads) == 'table' then
                    for _, pad in ipairs(pads) do
                        local q = pad:GetAttribute('QueueName')
                        add(q)
                    end
                end

                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local rotLib = modules and modules:FindFirstChild('RotatingQueueLibrary')
                if rotLib then
                    local okReq, lib = pcall(require, rotLib)
                    if okReq and type(lib) == 'table' and type(lib.GetCurrent) == 'function' then
                        local okCur, current = pcall(function() return lib:GetCurrent() end)
                        if okCur and type(current) == 'table' and type(current.QueueNames) == 'table' then
                            for _, qn in ipairs(current.QueueNames) do
                                add(qn)
                            end
                        end
                    end
                end

                return order
            end

            local function BuildModeListFromKeys(keys, queueInfoTable)
                local pairs_list = {}
                for _, key in ipairs(keys) do
                    local info = queueInfoTable and queueInfoTable[key]
                    local display = nil
                    if type(info) == 'table' and type(info.DisplayName) == 'string' and info.DisplayName ~= '' then
                        display = info.DisplayName
                    else
                        display = key
                    end
                    table.insert(pairs_list, { display = display, key = key })
                end
                local displays = {}
                local map = {}
                local seenDisplay = {}
                for _, entry in ipairs(pairs_list) do
                    if not seenDisplay[entry.display] then
                        seenDisplay[entry.display] = true
                        table.insert(displays, entry.display)
                        map[entry.display] = entry.key
                    end
                end
                return displays, map
            end

            function RivalsAutoQueue.ResolveModeValues()
                if RivalsAutoQueue.State.Modes ~= nil then
                    return RivalsAutoQueue.State.Modes
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local duelLib = modules and modules:FindFirstChild('DuelLibrary')
                local queueInfoTable = nil
                local duelLibrary = nil
                if duelLib then
                    local ok, lib = pcall(require, duelLib)
                    if ok and type(lib) == 'table' then
                        duelLibrary = lib
                        if type(lib.MatchmakingQueues) == 'table' then
                            queueInfoTable = lib.MatchmakingQueues
                        end
                    end
                end

                local serverOsTime = os.time()
                local serverOsTimeModule = modules and modules:FindFirstChild('ServerOsTime')
                if serverOsTimeModule then
                    local ok, serverTimeLibrary = pcall(require, serverOsTimeModule)
                    if ok and type(serverTimeLibrary) == 'table' and type(serverTimeLibrary.Get) == 'function' then
                        local timeOk, currentServerTime = pcall(serverTimeLibrary.Get, serverTimeLibrary)
                        if timeOk and type(currentServerTime) == 'number' then
                            serverOsTime = currentServerTime
                        end
                    end
                end

                local keys = {}
                local seen = {}
                local function addKey(queueKey)
                    if type(queueKey) == 'string' and queueKey ~= '' and not seen[queueKey] then
                        seen[queueKey] = true
                        keys[#keys + 1] = queueKey
                    end
                end

                local queueOrder = duelLibrary and duelLibrary.MatchmakingQueueOrder or nil
                if type(queueOrder) == 'table' and type(queueInfoTable) == 'table' then
                    for _, queueKey in ipairs(queueOrder) do
                        local queueInfo = queueInfoTable[queueKey]
                        local releaseTime = type(queueInfo) == 'table' and tonumber(queueInfo.TerminalsReleaseTime) or nil
                        if type(queueInfo) == 'table'
                            and queueInfo.CanBeStartedFromClient ~= false
                            and (not releaseTime or releaseTime <= serverOsTime) then
                            addKey(queueKey)
                        end
                    end
                end

                for _, queueKey in ipairs(CollectActiveQueueKeys()) do
                    addKey(queueKey)
                end

                local arcadeModes = duelLibrary and duelLibrary.ArcadeModes or nil
                RivalsAutoQueue.State.ArcadeModes = type(arcadeModes) == 'table' and arcadeModes or {}
                local arcadeOrder = duelLibrary and duelLibrary.ArcadeModeOrder or nil
                if type(arcadeOrder) == 'table' then
                    for _, arcadeModeKey in ipairs(arcadeOrder) do
                        addKey(arcadeModeKey)
                    end
                end

                local catalogInfoTable = {}
                for queueKey, queueInfo in pairs(queueInfoTable or {}) do
                    catalogInfoTable[queueKey] = queueInfo
                end
                for arcadeModeKey, arcadeInfo in pairs(RivalsAutoQueue.State.ArcadeModes) do
                    catalogInfoTable[arcadeModeKey] = arcadeInfo
                end

                if #keys > 0 then
                    local displays, map = BuildModeListFromKeys(keys, catalogInfoTable)
                    RivalsAutoQueue.State.Modes = displays
                    RivalsAutoQueue.State.DisplayToKey = map
                    return displays
                end

                local fallback = {}
                local fallbackMap = {}
                for _, key in ipairs(AUTO_QUEUE_FALLBACK_MODES) do
                    table.insert(fallback, key)
                    fallbackMap[key] = key
                end
                RivalsAutoQueue.State.Modes = fallback
                RivalsAutoQueue.State.DisplayToKey = fallbackMap
                return fallback
            end

            function RivalsAutoQueue.ResolveQueueKeyForDisplay(displayName)
                if type(displayName) ~= 'string' or displayName == '' then return nil end
                if RivalsAutoQueue.State.DisplayToKey == nil then
                    RivalsAutoQueue.ResolveModeValues()
                end
                local map = RivalsAutoQueue.State.DisplayToKey
                if map and map[displayName] then return map[displayName] end
                return displayName
            end

            function RivalsAutoQueue.RefreshDropdownValues()
                RivalsAutoQueue.State.Modes = nil
                RivalsAutoQueue.State.DisplayToKey = nil
                local values = RivalsAutoQueue.ResolveModeValues()
                if Options and Options.P8S6D1 and type(Options.P8S6D1.SetValues) == 'function' then
                    RivalsAutoQueue.State.RefreshSuppress = true
                    pcall(function()
                        Options.P8S6D1:SetValues(values)
                    end)
                    RivalsAutoQueue.State.RefreshSuppress = false
                end
                return values
            end

            local function ResolveQueueRemote(folderName, remoteName, remoteClass)
                local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                local folder = remotes and remotes:FindFirstChild(folderName)
                local remote = folder and folder:FindFirstChild(remoteName)
                if remote and remote:IsA(remoteClass) then
                    return remote
                end
                return nil
            end

            local function ReadAutoQueueDisplay()
                if Options and Options.P8S6D1 then
                    local v = Options.P8S6D1.Value
                    if type(v) == 'string' and v ~= '' then
                        return v
                    end
                end
                return nil
            end

            local function ReadAutoQueueToggle()
                if Toggles and Toggles.P8S6T1 then
                    return Toggles.P8S6T1.Value == true
                end
                return false
            end

            function RivalsAutoQueue.ResolveMatchmakingController()
                if RivalsAutoQueue.State.MatchmakingController then
                    return RivalsAutoQueue.State.MatchmakingController
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local controllerModule = controllers and controllers:FindFirstChild('MatchmakingController')
                if not controllerModule then
                    return nil
                end
                local ok, controller = pcall(require, controllerModule)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                RivalsAutoQueue.State.MatchmakingController = controller
                return controller
            end

            function RivalsAutoQueue.ResolveArcadeMode(queueKey)
                if RivalsAutoQueue.State.ArcadeModes == nil then
                    RivalsAutoQueue.ResolveModeValues()
                end
                local arcadeModes = RivalsAutoQueue.State.ArcadeModes
                return type(arcadeModes) == 'table' and arcadeModes[queueKey] or nil
            end

            function RivalsAutoQueue.ResolveArcadeController()
                if RivalsAutoQueue.State.ArcadeController then
                    return RivalsAutoQueue.State.ArcadeController
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local controllerModule = controllers and controllers:FindFirstChild('ArcadeController')
                if not controllerModule then
                    return nil
                end
                local ok, controller = pcall(require, controllerModule)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                RivalsAutoQueue.State.ArcadeController = controller
                return controller
            end

            function RivalsAutoQueue.TeleportToArcade(queueKey, arcadeMode)
                local placeId = type(arcadeMode) == 'table' and tonumber(arcadeMode.PlaceID) or nil
                if placeId and game.PlaceId == placeId then
                    return true
                end

                local now = tick()
                if now - RivalsAutoQueue.State.LastArcadeTeleportAt < 5 then
                    return false, 'arcade_debounced'
                end
                RivalsAutoQueue.State.LastArcadeTeleportAt = now

                local result = nil
                local controller = RivalsAutoQueue.ResolveArcadeController()
                if controller and type(controller.ToArcadeServer) == 'function' then
                    local ok
                    ok, result = pcall(controller.ToArcadeServer, controller, queueKey)
                    if ok and not (type(result) == 'string' and result ~= '') then
                        RivalsAutoQueue.State.Believed = 'matched'
                        RivalsAutoQueue.State.LastModeFired = queueKey
                        return true
                    end
                else
                    local remote = ResolveQueueRemote('Arcade', 'TeleportToArcadeServer', 'RemoteFunction')
                    if remote then
                        local ok
                        ok, result = pcall(remote.InvokeServer, remote, queueKey)
                        if ok and not (type(result) == 'string' and result ~= '') then
                            RivalsAutoQueue.State.Believed = 'matched'
                            RivalsAutoQueue.State.LastModeFired = queueKey
                            return true
                        end
                    end
                end

                RivalsAutoQueue.State.LastArcadeTeleportAt = 0
                return false, type(result) == 'string' and result or 'arcade_teleport_failed'
            end

            function RivalsAutoQueue.CanFireQueue()
                local status = workspace:GetAttribute('MatchmadeStatus')
                if status ~= 'Started' then
                    return true
                end
                local gameOver = workspace:GetAttribute('MatchmadeGameOver')
                if gameOver == true then
                    return true
                end
                if RivalsAutoQueue.State.MatchEndedConfirmed == true then
                    return true
                end
                return false
            end

            function RivalsAutoQueue.IsInLobby()
                return RivalsAutoQueue.CanFireQueue()
            end

            function RivalsAutoQueue.StopMatchEndRetry()
                RivalsAutoQueue.State.RetryActive = false
                RivalsAutoQueue.State.RetryAttempts = 0
                RivalsAutoQueue.State.RetryToken = (RivalsAutoQueue.State.RetryToken or 0) + 1
            end

            function RivalsAutoQueue.ScheduleMatchEndRetry()
                if not ReadAutoQueueToggle() then return end
                if not RivalsAutoQueue.CanFireQueue() then return end
                local believed = RivalsAutoQueue.State.Believed
                if believed == 'queued' or believed == 'matched' then return end
                if RivalsAutoQueue.State.RetryAttempts >= 150 then
                    RivalsAutoQueue.StopMatchEndRetry()
                    return
                end
                RivalsAutoQueue.State.RetryActive = true
                RivalsAutoQueue.State.RetryToken = (RivalsAutoQueue.State.RetryToken or 0) + 1
                local token = RivalsAutoQueue.State.RetryToken
                task.delay(0.1, function()
                    if token ~= RivalsAutoQueue.State.RetryToken then return end
                    if not RivalsAutoQueue.State.RetryActive then return end
                    if not ReadAutoQueueToggle() then RivalsAutoQueue.StopMatchEndRetry() return end
                    if not RivalsAutoQueue.CanFireQueue() then RivalsAutoQueue.StopMatchEndRetry() return end
                    local b = RivalsAutoQueue.State.Believed
                    if b == 'queued' or b == 'matched' then RivalsAutoQueue.StopMatchEndRetry() return end
                    RivalsAutoQueue.State.RetryAttempts = RivalsAutoQueue.State.RetryAttempts + 1
                    RivalsAutoQueue.FireJoin()
                end)
            end

            function RivalsAutoQueue.ResolveSkipButton()
                local duelInterfaces = RivalsAutoQueue.ResolveDuelInterfacesFrame()
                if not duelInterfaces then return nil end
                for _, descendant in ipairs(duelInterfaces:GetDescendants()) do
                    if descendant:IsA('GuiButton') then
                        local title = descendant:FindFirstChild('Title')
                        if title and title:IsA('TextLabel') and title.Text == 'Skip' then
                            return descendant
                        end
                        if descendant:IsA('TextButton') and descendant.Text == 'Skip' then
                            return descendant
                        end
                    end
                end
                return nil
            end

            function RivalsAutoQueue.PressSkip()
                local button = RivalsAutoQueue.ResolveSkipButton()
                if not button then return false, 'no_skip_button' end
                if not RivalsAutoQueue.IsGuiObjectVisibleInTree(button) then return false, 'skip_not_visible' end
                local pos = button.AbsolutePosition
                local size = button.AbsoluteSize
                if size.X <= 0 or size.Y <= 0 then return false, 'skip_zero_size' end
                if AimbotInputState.SyntheticInputBlocked() then return false, 'ui_open' end
                local cx = pos.X + size.X * 0.5
                local cy = pos.Y + game:GetService('GuiService'):GetGuiInset().Y + size.Y * 0.5
                local ok = pcall(function()
                    local vim = Instance.new('VirtualInputManager')
                    vim:SendMouseButtonEvent(cx, cy, 0, true, button, 1)
                    vim:SendMouseButtonEvent(cx, cy, 0, false, button, 1)
                end)
                if not ok then return false, 'vim_failed' end
                return true, 'vim'
            end

            function RivalsAutoQueue.StopSkipPress()
                RivalsAutoQueue.State.SkipPressActive = false
                RivalsAutoQueue.State.SkipPressToken = (RivalsAutoQueue.State.SkipPressToken or 0) + 1
            end

            function RivalsAutoQueue.PressSkipWithRetry()
                RivalsAutoQueue.StopSkipPress()
                RivalsAutoQueue.State.SkipPressActive = true
                RivalsAutoQueue.State.SkipPressToken = (RivalsAutoQueue.State.SkipPressToken or 0) + 1
                local token = RivalsAutoQueue.State.SkipPressToken
                local startedAt = tick()
                local function attempt()
                    if token ~= RivalsAutoQueue.State.SkipPressToken then return end
                    if not RivalsAutoQueue.State.SkipPressActive then return end
                    local ok = RivalsAutoQueue.PressSkip()
                    if ok then
                        RivalsAutoQueue.State.SkipPressActive = false
                        return
                    end
                    if tick() - startedAt >= 30.0 then
                        RivalsAutoQueue.State.SkipPressActive = false
                        return
                    end
                    task.delay(0.25, attempt)
                end
                attempt()
            end

            function RivalsAutoQueue.FireJoin()
                if not RivalsAutoQueue.IsInLobby() then return false, 'not_in_lobby' end
                if not IsReplicatedStateReady() then return false, 'replicated_state_not_ready' end
                local believed = RivalsAutoQueue.State.Believed
                if believed == 'queued' or believed == 'matched' then
                    return false, 'already_' .. believed
                end
                local display = ReadAutoQueueDisplay()
                if display == nil then return false, 'no_mode_selected' end
                local queueKey = RivalsAutoQueue.ResolveQueueKeyForDisplay(display)
                if type(queueKey) ~= 'string' or queueKey == '' then return false, 'no_key_for_display' end
                local now = tick()
                if now - RivalsAutoQueue.State.LastFireAt < AUTO_QUEUE_FIRE_DEBOUNCE then
                    return false, 'debounced'
                end
                RivalsAutoQueue.State.LastFireAt = now

                local arcadeMode = RivalsAutoQueue.ResolveArcadeMode(queueKey)
                if arcadeMode then
                    return RivalsAutoQueue.TeleportToArcade(queueKey, arcadeMode)
                end

                local controller = RivalsAutoQueue.ResolveMatchmakingController()
                if controller and type(controller.QueueInto) == 'function' then
                    local ok, result = pcall(function()
                        return controller:QueueInto(queueKey)
                    end)
                    if ok then
                        if type(result) == 'string' and #result > 0 then
                            RivalsAutoQueue.State.Believed = 'idle'
                            RivalsAutoQueue.ScheduleMatchEndRetry()
                            return false, result
                        end
                        RivalsAutoQueue.State.Believed = 'queued'
                        RivalsAutoQueue.State.LastModeFired = queueKey
                        RivalsAutoQueue.StopMatchEndRetry()
                        return true
                    end
                elseif not controller then
                    local primary = ResolveQueueRemote('Matchmaking', 'JoinQueue', 'RemoteFunction')
                    if primary then
                        local ok, result = pcall(function()
                            return safe_invoke_server(primary, queueKey)
                        end)
                        if ok and not (type(result) == 'string' and #result > 0) then
                            RivalsAutoQueue.State.Believed = 'queued'
                            RivalsAutoQueue.State.LastModeFired = queueKey
                            RivalsAutoQueue.StopMatchEndRetry()
                            return true
                        end
                    end
                end

                return false, 'no_remote'
            end

            function RivalsAutoQueue.FireLeave()
                RivalsAutoQueue.StopMatchEndRetry()
                RivalsAutoQueue.StopSkipPress()
                if RivalsAutoQueue.State.Believed == 'idle' then
                    return true
                end
                if not IsReplicatedStateReady() then
                    RivalsAutoQueue.State.Believed = 'idle'
                    return true
                end
                local controller = RivalsAutoQueue.ResolveMatchmakingController()
                if controller and type(controller.TryLeaveQueue) == 'function' then
                    local ok = pcall(function()
                        controller:TryLeaveQueue()
                    end)
                    if ok then
                        RivalsAutoQueue.State.Believed = 'idle'
                        return true
                    end
                elseif not controller then
                    local primary = ResolveQueueRemote('Matchmaking', 'TryLeaveQueue', 'RemoteEvent')
                        or ResolveQueueRemote('Matchmaking', 'LeaveQueue', 'RemoteEvent')
                    if primary then
                        local ok = pcall(function()
                            safe_fire_server(primary)
                        end)
                        if ok then
                            RivalsAutoQueue.State.Believed = 'idle'
                            return true
                        end
                    end
                end
                RivalsAutoQueue.State.Believed = 'idle'
                return false
            end

            function RivalsAutoQueue.OnToggled(value)
                if value then
                    RivalsAutoQueue.FireJoin()
                else
                    RivalsAutoQueue.FireLeave()
                end
            end

            function RivalsAutoQueue.OnModeChanged()
                if RivalsAutoQueue.State.RefreshSuppress then return end
                if not ReadAutoQueueToggle() then return end
                if RivalsAutoQueue.State.Believed == 'queued' then
                    RivalsAutoQueue.FireLeave()
                    task.delay(0.15, function()
                        if ReadAutoQueueToggle() then
                            RivalsAutoQueue.FireJoin()
                        end
                    end)
                    return
                end
                RivalsAutoQueue.FireJoin()
            end

            function RivalsAutoQueue.HandleStatusUpdate(...)
                local args = {...}
                local statusValue = args[1]
                if type(statusValue) == 'table' then
                    statusValue = statusValue.Status or statusValue.State or statusValue[1]
                end
                if type(statusValue) == 'string' then
                    local lowered = statusValue:lower()
                    if lowered == 'queued' or lowered == 'searching' then
                        RivalsAutoQueue.State.Believed = 'queued'
                        RivalsAutoQueue.StopMatchEndRetry()
                        return
                    end
                    if lowered == 'matched' or lowered == 'matchfound' or lowered == 'ready' then
                        RivalsAutoQueue.State.Believed = 'matched'
                        RivalsAutoQueue.StopMatchEndRetry()
                        return
                    end
                    if lowered == 'cancelled' or lowered == 'canceled' or lowered == 'expired' or lowered == 'failed' or lowered == 'timeout' or lowered == 'idle' then
                        RivalsAutoQueue.State.Believed = 'idle'
                        if ReadAutoQueueToggle() then
                            task.delay(AUTO_QUEUE_RETRY_DELAY, function()
                                if ReadAutoQueueToggle() and RivalsAutoQueue.IsInLobby() and RivalsAutoQueue.State.Believed == 'idle' then
                                    RivalsAutoQueue.FireJoin()
                                end
                            end)
                        end
                    end
                end
            end

            function RivalsAutoQueue.OnLobbyReturn()
                if not ReadAutoQueueToggle() then return end
                if not RivalsAutoQueue.CanFireQueue() then return end
                local now = tick()
                if now - RivalsAutoQueue.State.LastFireAt < AUTO_QUEUE_FIRE_DEBOUNCE then return end
                RivalsAutoQueue.State.Believed = 'idle'
                RivalsAutoQueue.FireJoin()
            end

            function RivalsAutoQueue.OnMatchmadeGameOverChanged()
                if not ReadAutoQueueToggle() then return end
                local gameOver = workspace:GetAttribute('MatchmadeGameOver')
                if gameOver ~= true then return end
                local now = tick()
                if now - RivalsAutoQueue.State.LastFireAt < AUTO_QUEUE_FIRE_DEBOUNCE then return end
                RivalsAutoQueue.State.Believed = 'idle'
                RivalsAutoQueue.FireJoin()
            end

            function RivalsAutoQueue.OnIsInDuelChanged(newValue, previousValue)
                local isNowInDuel = newValue == true
                local wasInDuel = previousValue == true
                if isNowInDuel and not wasInDuel then
                    RivalsAutoQueue.State.MatchEndedConfirmed = false
                    RivalsAutoQueue.StopMatchEndRetry()
                    RivalsAutoQueue.StopSkipPress()
                    return
                end
                if not (wasInDuel and not isNowInDuel) then return end
                RivalsAutoQueue.State.MatchEndedConfirmed = true
                if not ReadAutoQueueToggle() then return end
                RivalsAutoQueue.PressSkipWithRetry()
                local now = tick()
                if now - RivalsAutoQueue.State.LastFireAt < AUTO_QUEUE_FIRE_DEBOUNCE then return end
                RivalsAutoQueue.State.Believed = 'idle'
                RivalsAutoQueue.FireJoin()
            end

            function RivalsAutoQueue.ResolveFinalResultsButtonsContainer()
                local playerGui = LP and LP:FindFirstChildOfClass('PlayerGui')
                local mainGui = playerGui and playerGui:FindFirstChild('MainGui')
                local mainFrame = mainGui and mainGui:FindFirstChild('MainFrame')
                local duelInterfaces = mainFrame and mainFrame:FindFirstChild('DuelInterfaces')
                local duelInterface = duelInterfaces and duelInterfaces:FindFirstChild('DuelInterface')
                local finalResults = duelInterface and duelInterface:FindFirstChild('FinalResults')
                local buttons = finalResults and finalResults:FindFirstChild('Buttons')
                local bottomRight = buttons and buttons:FindFirstChild('BottomRight')
                return bottomRight and bottomRight:FindFirstChild('Container') or nil
            end

            function RivalsAutoQueue.ResolveDuelInterfacesFrame()
                local playerGui = LP and LP:FindFirstChildOfClass('PlayerGui')
                local mainGui = playerGui and playerGui:FindFirstChild('MainGui')
                local mainFrame = mainGui and mainGui:FindFirstChild('MainFrame')
                return mainFrame and mainFrame:FindFirstChild('DuelInterfaces') or nil
            end

            function RivalsAutoQueue.ResolvePlayAgainButton()
                local container = RivalsAutoQueue.ResolveFinalResultsButtonsContainer()
                local buttonFrame = container and container:FindFirstChild('PlayAgain')
                local button = buttonFrame and buttonFrame:FindFirstChild('Button')
                if button and button:IsA('GuiButton') then
                    local title = button:FindFirstChild('Title')
                    if title and title:IsA('TextLabel') and title.Text == 'Play Again' then
                        return button
                    end
                end
                return nil
            end

            function RivalsAutoQueue.IsGuiObjectVisibleInTree(guiObject)
                if not guiObject or not guiObject:IsA('GuiObject') then
                    return false
                end
                local playerGui = LP and LP:FindFirstChildOfClass('PlayerGui')
                local current = guiObject
                while current and current ~= playerGui do
                    if current:IsA('GuiObject') and current.Visible ~= true then
                        return false
                    end
                    current = current.Parent
                end
                return current == playerGui
            end

            function RivalsAutoQueue.OnPlayAgainVisible(button)
                if not ReadAutoQueueToggle() then return end
                if not RivalsAutoQueue.IsGuiObjectVisibleInTree(button) then return end
                RivalsAutoQueue.State.Believed = 'idle'
                RivalsAutoQueue.FireJoin()
            end

            function RivalsAutoQueue.QueuePlayAgainCheck(button)
                task.defer(function()
                    RivalsAutoQueue.OnPlayAgainVisible(button)
                end)
            end

            function RivalsAutoQueue.RegisterPlayAgainButton()
                local button = RivalsAutoQueue.ResolvePlayAgainButton()
                if not Connections or not button or not button:IsA('GuiButton') then
                    return
                end

                Connections:register('AutoQueue_PlayAgain_Visible', button:GetPropertyChangedSignal('Visible'):Connect(GuardRivalsCallback('AutoQueue_PlayAgain_Visible', function()
                    if button.Visible == true then
                        RivalsAutoQueue.QueuePlayAgainCheck(button)
                    end
                end)))

                local title = button:FindFirstChild('Title')
                if title and title:IsA('TextLabel') then
                    Connections:register('AutoQueue_PlayAgain_Title', title:GetPropertyChangedSignal('Text'):Connect(GuardRivalsCallback('AutoQueue_PlayAgain_Title', function()
                        RivalsAutoQueue.QueuePlayAgainCheck(button)
                    end)))
                end

                local playerGui = LP and LP:FindFirstChildOfClass('PlayerGui')
                local ancestor = button.Parent
                local ancestorIndex = 0
                while ancestor and ancestor ~= playerGui do
                    if ancestor:IsA('GuiObject') then
                        ancestorIndex = ancestorIndex + 1
                        local connectionName = 'AutoQueue_PlayAgain_AncestorVisible_' .. tostring(ancestorIndex)
                        local watchedAncestor = ancestor
                        Connections:register(connectionName, watchedAncestor:GetPropertyChangedSignal('Visible'):Connect(GuardRivalsCallback(connectionName, function()
                            if watchedAncestor.Visible == true then
                                RivalsAutoQueue.QueuePlayAgainCheck(button)
                            end
                        end)))
                    end
                    ancestor = ancestor.Parent
                end

                if RivalsAutoQueue.IsGuiObjectVisibleInTree(button) then
                    RivalsAutoQueue.QueuePlayAgainCheck(button)
                end
            end

            function RivalsAutoQueue.QueuePlayAgainRegistration()
                if RivalsAutoQueue.State.PlayAgainRegistrationQueued then return end
                RivalsAutoQueue.State.PlayAgainRegistrationQueued = true
                task.defer(function()
                    RivalsAutoQueue.State.PlayAgainRegistrationQueued = false
                    RivalsAutoQueue.RegisterPlayAgainButton()
                    RivalsAutoQueue.RegisterSkipButton()
                end)
            end

            function RivalsAutoQueue.RegisterPlayAgainChildWatcher(parent, childName, connectionName)
                if not Connections or not parent then
                    if Connections then Connections:disconnect({ connectionName }) end
                    return nil
                end

                Connections:register(connectionName, parent.ChildAdded:Connect(GuardRivalsCallback(connectionName, function(child)
                    if child.Name == childName then
                        RivalsAutoQueue.QueuePlayAgainRegistration()
                    end
                end)))

                return parent:FindFirstChild(childName)
            end

            function RivalsAutoQueue.OnSkipVisible(button)
                if not ReadAutoQueueToggle() then return end
                if not RivalsAutoQueue.IsGuiObjectVisibleInTree(button) then return end
                RivalsAutoQueue.PressSkip()
            end

            function RivalsAutoQueue.QueueSkipPress(button)
                task.defer(function()
                    RivalsAutoQueue.OnSkipVisible(button)
                end)
            end

            function RivalsAutoQueue.RegisterSkipButton()
                local button = RivalsAutoQueue.ResolveSkipButton()
                if not Connections or not button or not button:IsA('GuiButton') then return end

                Connections:register('AutoQueue_Skip_Visible', button:GetPropertyChangedSignal('Visible'):Connect(GuardRivalsCallback('AutoQueue_Skip_Visible', function()
                    if button.Visible == true then
                        RivalsAutoQueue.QueueSkipPress(button)
                    end
                end)))

                local title = button:FindFirstChild('Title')
                if title and title:IsA('TextLabel') then
                    Connections:register('AutoQueue_Skip_Title', title:GetPropertyChangedSignal('Text'):Connect(GuardRivalsCallback('AutoQueue_Skip_Title', function()
                        RivalsAutoQueue.QueueSkipPress(button)
                    end)))
                end

                local playerGui = LP and LP:FindFirstChildOfClass('PlayerGui')
                local ancestor = button.Parent
                local ancestorIndex = 0
                while ancestor and ancestor ~= playerGui do
                    if ancestor:IsA('GuiObject') then
                        ancestorIndex = ancestorIndex + 1
                        local connectionName = 'AutoQueue_Skip_AncestorVisible_' .. tostring(ancestorIndex)
                        local watchedAncestor = ancestor
                        Connections:register(connectionName, watchedAncestor:GetPropertyChangedSignal('Visible'):Connect(GuardRivalsCallback(connectionName, function()
                            if watchedAncestor.Visible == true then
                                RivalsAutoQueue.QueueSkipPress(button)
                            end
                        end)))
                    end
                    ancestor = ancestor.Parent
                end

                if RivalsAutoQueue.IsGuiObjectVisibleInTree(button) then
                    RivalsAutoQueue.QueueSkipPress(button)
                end
            end

            function RivalsAutoQueue.RegisterPlayAgainSignals()
                if not Connections then return end

                RivalsAutoQueue.RegisterPlayAgainButton()
                RivalsAutoQueue.RegisterSkipButton()

                local duelInterfaces = RivalsAutoQueue.ResolveDuelInterfacesFrame()
                if not duelInterfaces then
                    Connections:disconnect({
                        'AutoQueue_DuelInterfaceAdded',
                        'AutoQueue_FinalResultsFrameAdded',
                        'AutoQueue_FinalResultsButtonsAdded',
                        'AutoQueue_FinalResultsBottomRightAdded',
                        'AutoQueue_FinalResultsContainerAdded',
                    })
                    return
                end

                local duelInterface = RivalsAutoQueue.RegisterPlayAgainChildWatcher(duelInterfaces, 'DuelInterface', 'AutoQueue_DuelInterfaceAdded')
                local finalResults = RivalsAutoQueue.RegisterPlayAgainChildWatcher(duelInterface, 'FinalResults', 'AutoQueue_FinalResultsFrameAdded')
                local buttons = RivalsAutoQueue.RegisterPlayAgainChildWatcher(finalResults, 'Buttons', 'AutoQueue_FinalResultsButtonsAdded')
                local bottomRight = RivalsAutoQueue.RegisterPlayAgainChildWatcher(buttons, 'BottomRight', 'AutoQueue_FinalResultsBottomRightAdded')
                RivalsAutoQueue.RegisterPlayAgainChildWatcher(bottomRight, 'Container', 'AutoQueue_FinalResultsContainerAdded')
            end

            RivalsRuntimeBridge.ResolveAutoQueueModeValues = RivalsAutoQueue.ResolveModeValues
            RivalsRuntimeBridge.RefreshAutoQueueDropdownValues = RivalsAutoQueue.RefreshDropdownValues
            RivalsRuntimeBridge.OnAutoQueueToggled = RivalsAutoQueue.OnToggled
            RivalsRuntimeBridge.OnAutoQueueModeChanged = RivalsAutoQueue.OnModeChanged
            RivalsRuntimeBridge.HandleAutoQueueStatusUpdate = RivalsAutoQueue.HandleStatusUpdate
            RivalsRuntimeBridge.OnAutoQueueLobbyReturn = RivalsAutoQueue.OnLobbyReturn
            RivalsRuntimeBridge.OnAutoQueueMatchmadeGameOverChanged = RivalsAutoQueue.OnMatchmadeGameOverChanged
            FighterDataCache.OnLocalDuelChanged = RivalsAutoQueue.OnIsInDuelChanged
            RivalsRuntimeBridge.OnAutoQueueIsInDuelChanged = RivalsAutoQueue.OnIsInDuelChanged
            RivalsRuntimeBridge.FireAutoQueueJoin = RivalsAutoQueue.FireJoin
            RivalsRuntimeBridge.IsAutoQueueLobby = RivalsAutoQueue.IsInLobby
            RivalsRuntimeBridge.CanAutoQueueFire = RivalsAutoQueue.CanFireQueue
            RivalsRuntimeBridge.GetAutoQueueBelief = function()
                return RivalsAutoQueue.State.Believed
            end
            RivalsRuntimeBridge.RegisterAutoQueuePlayAgainSignals = RivalsAutoQueue.RegisterPlayAgainSignals
            end)()

            -- ============================================================
            -- SKIN CHANGER RUNTIME (ripped from Skin changer.lua)
            -- ============================================================
            local SC_equipped = {}
            local SC_favorites = {}
            local SC_constructingWeapon = nil
            local SC_viewingProfile = nil
            local SC_lastUsedWeapon = nil

            local SC_HttpService = game:GetService('HttpService')
            local SC_SoundService = game:GetService('SoundService')
            local SC_saveFile = 'unlockall/config.json'
            local SC_saveTimer = nil
            local SC_isSaving = false

            local SC_enumCache = {}
            local function SC_getEnumSafe(name)
                if not name then return nil end
                local ok, v = pcall(function()
                    local el = game:GetService('ReplicatedStorage'):FindFirstChild('Modules')
                    el = el and el:FindFirstChild('EnumLibrary')
                    if el then
                        local lib = require(el)
                        return lib and lib:ToEnum(name)
                    end
                end)
                if ok and v then return v end
                return nil
            end

            -- resolve game modules
            local SC_CosmeticLibrary, SC_ItemLibrary, SC_DataController, SC_FighterController
            pcall(function()
                local RS = game:GetService('ReplicatedStorage')
                local PS2 = LP:FindFirstChild('PlayerScripts') or LP.PlayerScripts
                local RSMods = RS:FindFirstChild('Modules')
                local Controllers2 = PS2 and PS2:FindFirstChild('Controllers')
                local function SR(parent, name)
                    if not parent then return nil end
                    local c = parent:FindFirstChild(name)
                    if c then local ok, m = pcall(require, c) if ok and m then return m end end
                    return nil
                end
                SC_CosmeticLibrary = RSMods and SR(RSMods, 'CosmeticLibrary')
                SC_ItemLibrary = RSMods and SR(RSMods, 'ItemLibrary')
                SC_DataController = Controllers2 and SR(Controllers2, 'PlayerDataController')
                SC_FighterController = Controllers2 and SR(Controllers2, 'FighterController')
            end)

            local function SC_cloneCosmetic(name, cosmeticType, options)
                if not SC_CosmeticLibrary or not SC_CosmeticLibrary.Cosmetics then return nil end
                local base = SC_CosmeticLibrary.Cosmetics[name]
                if not base then return nil end
                local data = {}
                for k, v in pairs(base) do data[k] = v end
                data.Name = name
                data.Type = data.Type or cosmeticType or 'Skin'
                data.Seed = data.Seed or math.random(1, 1000000)
                local enumId = SC_getEnumSafe(name)
                if enumId then data.Enum = enumId data.ObjectID = data.ObjectID or enumId end
                if options then
                    if options.inverted ~= nil then data.Inverted = options.inverted end
                    if options.favoritesOnly ~= nil then data.OnlyUseFavorites = options.favoritesOnly end
                end
                return data
            end

            local function SC_saveConfig()
                if SC_saveTimer then pcall(task.cancel, SC_saveTimer) SC_saveTimer = nil end
                SC_saveTimer = task.delay(0.8, function()
                    SC_saveTimer = nil
                    if SC_isSaving or not writefile then return end
                    SC_isSaving = true
                    task.spawn(function()
                        pcall(function()
                            local config = {equipped = {}, favorites = SC_favorites}
                            for weapon, cosmetics in pairs(SC_equipped) do
                                config.equipped[weapon] = {}
                                for cosType, cosData in pairs(cosmetics) do
                                    if cosData and cosData.Name then
                                        config.equipped[weapon][cosType] = {name = cosData.Name, seed = cosData.Seed, inverted = cosData.Inverted}
                                    end
                                end
                            end
                            if makefolder then pcall(makefolder, 'unlockall') end
                            writefile(SC_saveFile, SC_HttpService:JSONEncode(config))
                        end)
                        SC_isSaving = false
                    end)
                end)
            end

            local SC_isLoadingConfig = false
            local function SC_loadConfig()
                if not readfile or not isfile or not isfile(SC_saveFile) then return end
                if SC_isLoadingConfig then return end
                SC_isLoadingConfig = true
                task.spawn(function()
                    local ok, dataStr = pcall(readfile, SC_saveFile)
                    if not ok or not dataStr or dataStr == '' then
                        SC_isLoadingConfig = false
                        return
                    end
                    local okJ, config = pcall(function() return SC_HttpService:JSONDecode(dataStr) end)
                    if not okJ or type(config) ~= 'table' then
                        SC_isLoadingConfig = false
                        return
                    end
                    SC_favorites = config.favorites or {}
                    if config.equipped and type(config.equipped) == 'table' then
                        local weaponCount = 0
                        for weapon, cosmetics in pairs(config.equipped) do
                            SC_equipped[weapon] = SC_equipped[weapon] or {}
                            if type(cosmetics) == 'table' then
                                for cosType, cosData in pairs(cosmetics) do
                                    if cosData and cosData.name then
                                        local cloned = SC_cloneCosmetic(cosData.name, cosType, {inverted = cosData.inverted})
                                        if cloned then
                                            cloned.Seed = cosData.seed
                                            SC_equipped[weapon][cosType] = cloned
                                        else
                                            local fb = {Name = cosData.name, Seed = cosData.seed or math.random(1, 1000000), Inverted = cosData.inverted, Type = cosType}
                                            local eid = SC_getEnumSafe(cosData.name)
                                            if eid then fb.Enum = eid fb.ObjectID = eid end
                                            SC_equipped[weapon][cosType] = fb
                                        end
                                        if cosType == 'Skin' and SC_SkinChanger and type(SC_SkinChanger.ApplySkinModel) == 'function' then
                                            pcall(SC_SkinChanger.ApplySkinModel, SC_SkinChanger, weapon, cosData.name)
                                        end
                                    end
                                end
                            end
                            weaponCount = weaponCount + 1
                            if weaponCount % 3 == 0 then
                                task.wait()
                            end
                        end
                    end
                    SC_isLoadingConfig = false
                    pcall(function()
                        if RivalsRuntimeBridge and type(RivalsRuntimeBridge.ApplyRivalsCosmetics) == 'function' then
                            RivalsRuntimeBridge.ApplyRivalsCosmetics()
                        elseif SC_DataController and SC_DataController.CurrentData then
                            SC_DataController.CurrentData:Replicate('WeaponInventory')
                        end
                    end)
                end)
            end

            -- Hook CosmeticLibrary ownership
            pcall(function()
                if SC_CosmeticLibrary then
                    SC_CosmeticLibrary.OwnsCosmeticNormally = function() return true end
                    SC_CosmeticLibrary.OwnsCosmeticUniversally = function() return true end
                    SC_CosmeticLibrary.OwnsCosmeticForWeapon = function() return true end
                    local origOwns = SC_CosmeticLibrary.OwnsCosmetic
                    SC_CosmeticLibrary.OwnsCosmetic = function(self, inventory, name, weapon)
                        if name and tostring(name):find('MISSING_') then
                            return origOwns and origOwns(self, inventory, name, weapon) or false
                        end
                        return true
                    end
                end
            end)

            -- Hook DataController
            pcall(function()
                if SC_DataController then
                    local origGet = SC_DataController.Get
                    SC_DataController.Get = function(self, key)
                        local data = origGet(self, key)
                        if key == 'CosmeticInventory' then
                            local proxy = (type(data) == 'table') and table.clone(data) or {}
                            return setmetatable(proxy, {__index = function() return true end})
                        end
                        if key == 'FavoritedCosmetics' then
                            local result = data and table.clone(data) or {}
                            for weapon, favs in pairs(SC_favorites) do
                                result[weapon] = result[weapon] or {}
                                for name, isFav in pairs(favs) do result[weapon][name] = isFav end
                            end
                            return result
                        end
                        return data
                    end
                    local origGetWeapon = SC_DataController.GetWeaponData
                    SC_DataController.GetWeaponData = function(self, weaponName)
                        local data = origGetWeapon(self, weaponName)
                        if not data then return nil end
                        if not SC_equipped[weaponName] then return data end
                        local merged = {}
                        for k, v in pairs(data) do merged[k] = v end
                        merged.Name = weaponName
                        for cosType, cosData in pairs(SC_equipped[weaponName]) do
                            merged[cosType] = cosData
                        end
                        return merged
                    end
                end
            end)

            -- Get remotes
            local SC_remotes = game:GetService('ReplicatedStorage'):FindFirstChild('Remotes')
            local SC_dataRemotes = SC_remotes and SC_remotes:FindFirstChild('Data')
            local SC_equipRemote = SC_dataRemotes and SC_dataRemotes:FindFirstChild('EquipCosmetic')
            local SC_favoriteRemote = SC_dataRemotes and SC_dataRemotes:FindFirstChild('FavoriteCosmetic')
            local SC_replicationRemotes = SC_remotes and SC_remotes:FindFirstChild('Replication')
            local SC_fighterRemotes = SC_replicationRemotes and SC_replicationRemotes:FindFirstChild('Fighter')
            local SC_useItemRemote = SC_fighterRemotes and SC_fighterRemotes:FindFirstChild('UseItem')


            -- ClientItem ViewModel hook
            pcall(function()
                local CI
                pcall(function() CI = require(LP.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem) end)
                if CI and CI._CreateViewModel then
                    local origCVM = CI._CreateViewModel
                    CI._CreateViewModel = function(self, viewmodelRef)
                        local wName = self.Name
                        local wPlayer = self.ClientFighter and self.ClientFighter.Player
                        SC_constructingWeapon = (wPlayer == LP) and wName or nil
                        if wPlayer == LP and SC_equipped[wName] and SC_equipped[wName].Skin and viewmodelRef then
                            local dataKey, skinKey, nameKey = self:ToEnum('Data'), self:ToEnum('Skin'), self:ToEnum('Name')
                            if viewmodelRef[dataKey] then
                                viewmodelRef[dataKey][skinKey] = SC_equipped[wName].Skin
                                viewmodelRef[dataKey][nameKey] = SC_equipped[wName].Skin.Name
                            elseif viewmodelRef.Data then
                                viewmodelRef.Data.Skin = SC_equipped[wName].Skin
                                viewmodelRef.Data.Name = SC_equipped[wName].Skin.Name
                            end
                        end
                        local result = origCVM(self, viewmodelRef)
                        SC_constructingWeapon = nil
                        return result
                    end
                end
            end)

            -- ClientViewModel hook
            task.spawn(function()
                local vmPath = LP.PlayerScripts:WaitForChild('Modules', 10)
                if vmPath then vmPath = vmPath:WaitForChild('ClientReplicatedClasses', 10) end
                if vmPath then vmPath = vmPath:WaitForChild('ClientFighter', 10) end
                if vmPath then vmPath = vmPath:WaitForChild('ClientItem', 10) end
                local vmMod = vmPath and vmPath:WaitForChild('ClientViewModel', 10)
                if vmMod then
                    local cvm
                    pcall(function() cvm = require(vmMod) end)
                    if cvm then
                        if cvm.GetWrap and not cvm._SC_GetWrapHooked then
                            cvm._SC_GetWrapHooked = true
                            local origGW = cvm.GetWrap
                            cvm.GetWrap = function(self)
                                local wName = self.ClientItem and self.ClientItem.Name
                                local wPlayer = self.ClientItem and self.ClientItem.ClientFighter and self.ClientItem.ClientFighter.Player
                                if wName and wPlayer == LP and SC_equipped[wName] and SC_equipped[wName].Wrap then
                                    return SC_equipped[wName].Wrap
                                end
                                return origGW(self)
                            end
                        end
                        if cvm.new and not cvm._SC_NewHooked then
                            cvm._SC_NewHooked = true
                            local origNew = cvm.new
                            cvm.new = function(replicatedData, clientItem)
                                local wPlayer = clientItem.ClientFighter and clientItem.ClientFighter.Player
                                local wName = SC_constructingWeapon or clientItem.Name
                                if wPlayer == LP and SC_equipped[wName] then
                                    local ReplicatedClass = require(game:GetService('ReplicatedStorage').Modules.ReplicatedClass)
                                    local dataKey = ReplicatedClass:ToEnum('Data')
                                    replicatedData[dataKey] = replicatedData[dataKey] or {}
                                    local cosmetics = SC_equipped[wName]
                                    if cosmetics.Skin then replicatedData[dataKey][ReplicatedClass:ToEnum('Skin')] = cosmetics.Skin end
                                    if cosmetics.Wrap then replicatedData[dataKey][ReplicatedClass:ToEnum('Wrap')] = cosmetics.Wrap end
                                    if cosmetics.Charm then replicatedData[dataKey][ReplicatedClass:ToEnum('Charm')] = cosmetics.Charm end
                                end
                                local result = origNew(replicatedData, clientItem)
                                if wPlayer == LP and SC_equipped[wName] and SC_equipped[wName].Wrap and result._UpdateWrap then
                                    result:_UpdateWrap()
                                    task.delay(0.1, function() if not result._destroyed then result:_UpdateWrap() end end)
                                end
                                return result
                            end
                        end
                    end
                end
            end)

            -- ItemLibrary image hook
            pcall(function()
                if SC_ItemLibrary and SC_ItemLibrary.GetViewModelImageFromWeaponData then
                    local origImg = SC_ItemLibrary.GetViewModelImageFromWeaponData
                    SC_ItemLibrary.GetViewModelImageFromWeaponData = function(self, weaponData, highRes)
                        if not weaponData then return origImg(self, weaponData, highRes) end
                        local wName = weaponData.Name
                        local shouldShow = (weaponData.Skin and SC_equipped[wName] and weaponData.Skin == SC_equipped[wName].Skin)
                            or (SC_viewingProfile == LP and SC_equipped[wName] and SC_equipped[wName].Skin)
                        if shouldShow and SC_equipped[wName] and SC_equipped[wName].Skin then
                            local skinInfo = self.ViewModels and self.ViewModels[SC_equipped[wName].Skin.Name]
                            if skinInfo then return skinInfo[highRes and 'ImageHighResolution' or 'Image'] or skinInfo.Image end
                        end
                        return origImg(self, weaponData, highRes)
                    end
                end
            end)

            -- SkinChanger viewmodel swap helper
            local SC_SkinChanger = {
                skinFolders = {}, viewModelsPath = nil, backupFolder = nil, skinModelCache = {}, currentAppliedSkin = {},
                InitializeViewModelsPath = function(self)
                    local ps = LP:FindFirstChild('PlayerScripts') or LP.PlayerScripts
                    if not ps then return false end
                    local ok, result = pcall(function() return ps.Assets.ViewModels.Weapons end)
                    if ok and result then self.viewModelsPath = result return true end
                    ok, result = pcall(function() return ps.Assets.ViewModels end)
                    if ok and result then
                        local f = Instance.new('Folder') f.Name = 'Weapons' f.Parent = result
                        self.viewModelsPath = f return true
                    end
                    return false
                end,
                DiscoverSkinFolders = function(self)
                    local ps = LP:FindFirstChild('PlayerScripts') or LP.PlayerScripts
                    if not ps then return false end
                    local VM = ps:FindFirstChild('Assets') and ps.Assets:FindFirstChild('ViewModels')
                    if not VM then return false end
                    for _, child in ipairs(VM:GetChildren()) do
                        if child:IsA('Folder') and child.Name ~= 'Weapons' and child.Name ~= 'OriginalBackups' then
                            self.skinFolders[child.Name] = child
                        end
                    end
                    return true
                end,
                FindSkinModel = function(self, skinName)
                    if not skinName or skinName == '' then return nil end
                    local cached = self.skinModelCache[skinName]
                    if cached and cached.Parent then return cached end
                    for _, sf in pairs(self.skinFolders) do
                        if sf and sf:IsA('Folder') then
                            local found = sf:FindFirstChild(skinName)
                            if found and found:IsA('Model') then self.skinModelCache[skinName] = found return found end
                        end
                    end
                    return nil
                end,
                GetOrCreateBackupFolder = function(self)
                    if self.backupFolder and self.backupFolder.Parent then return self.backupFolder end
                    if not self.viewModelsPath then if not self:InitializeViewModelsPath() then return nil end end
                    local ok, bf = pcall(function()
                        local ex = self.viewModelsPath:FindFirstChild('OriginalBackups')
                        if ex then return ex end
                        local nf = Instance.new('Folder') nf.Name = 'OriginalBackups' nf.Parent = self.viewModelsPath
                        return nf
                    end)
                    if ok then self.backupFolder = bf return bf end
                    return nil
                end,
                ApplySkinModel = function(self, weaponName, skinName)
                    if not skinName or skinName == '' or skinName == 'None' or skinName == 'No Skins Found' then
                        return false
                    end
                    if self.currentAppliedSkin and self.currentAppliedSkin[weaponName] == skinName then
                        return true
                    end
                    if not self.viewModelsPath then if not self:InitializeViewModelsPath() then return false end end
                    local wm = self.viewModelsPath:FindFirstChild(weaponName)
                    if not wm or not wm:IsA('Model') then return false end
                    local sm = self:FindSkinModel(skinName)
                    if not sm then return false end
                    local bf = self:GetOrCreateBackupFolder()
                    if not bf then return false end
                    local bkName = weaponName .. '_Original'
                    if not bf:FindFirstChild(bkName) then
                        local bk = wm:Clone() bk.Name = bkName bk.Parent = bf
                    end
                    wm:Destroy()
                    local nw = sm:Clone() nw.Name = weaponName nw.Parent = self.viewModelsPath
                    if not self.currentAppliedSkin then self.currentAppliedSkin = {} end
                    self.currentAppliedSkin[weaponName] = skinName
                    return true
                end,
                ResetSkinModel = function(self, weaponName)
                    if self.currentAppliedSkin then
                        self.currentAppliedSkin[weaponName] = nil
                    end
                    if not self.viewModelsPath then if not self:InitializeViewModelsPath() then return false end end
                    local bf = self:GetOrCreateBackupFolder()
                    if not bf then return false end
                    local bk = bf:FindFirstChild(weaponName .. '_Original')
                    if not bk then return false end
                    local cur = self.viewModelsPath:FindFirstChild(weaponName)
                    if cur then cur:Destroy() end
                    local restored = bk:Clone() restored.Name = weaponName restored.Parent = self.viewModelsPath
                    return true
                end,
                ResetAllWeapons = function(self)
                    if self.currentAppliedSkin then
                        table.clear(self.currentAppliedSkin)
                    end
                    if not self.viewModelsPath then if not self:InitializeViewModelsPath() then return 0 end end
                    local bf = self:GetOrCreateBackupFolder()
                    if not bf then return 0 end
                    local count = 0
                    for _, bm in ipairs(bf:GetChildren()) do
                        if bm:IsA('Model') and bm.Name:sub(-9) == '_Original' then
                            local wName = bm.Name:sub(1, -10)
                            local cur = self.viewModelsPath:FindFirstChild(wName)
                            if cur then cur:Destroy() end
                            local r = bm:Clone() r.Name = wName r.Parent = self.viewModelsPath
                            count = count + 1
                            if count % 3 == 0 then
                                task.wait()
                            end
                        end
                    end
                    return count
                end,
            }
            task.spawn(function()
                SC_SkinChanger:InitializeViewModelsPath()
                SC_SkinChanger:DiscoverSkinFolders()
            end)

