            local function SC_cleanList(t)
                local seen, items = {}, {}
                for _, v in ipairs(t) do
                    if v and v ~= '' and v ~= 'None' and not seen[v] then seen[v] = true table.insert(items, v) end
                end
                table.sort(items) table.insert(items, 1, 'None') return items
            end
            SC_WrapsData = SC_cleanList(SC_WrapsData)
            SC_CharmsData = SC_cleanList(SC_CharmsData)
            SC_FinishersData = SC_cleanList(SC_FinishersData)

            local SC_WeaponList = {'All'}
            do
                local sw = {}
                for wt, _ in pairs(SC_WeaponsData) do table.insert(sw, wt) end
                table.sort(sw)
                for _, w in ipairs(sw) do table.insert(SC_WeaponList, w) end
            end

            local SC_AllSkinsList = {'None'}
            local function SC_RebuildAllSkinsList()
                local skinSet = {}
                for _, skins in pairs(SC_WeaponsData) do
                    for _, s in ipairs(skins) do if s and s ~= 'None' then skinSet[s] = true end end
                end
                if SC_CosmeticLibrary and SC_CosmeticLibrary.Cosmetics then
                    for cosName, cosData in pairs(SC_CosmeticLibrary.Cosmetics) do
                        if type(cosName) == 'string' and cosName ~= '' and (cosData.Type == 'Skin' or cosData.Type == 'skin') then
                            skinSet[cosName] = true
                        end
                    end
                end
                local list = {}
                for s, _ in pairs(skinSet) do table.insert(list, s) end
                table.sort(list) table.insert(list, 1, 'None')
                SC_AllSkinsList = list
                return SC_AllSkinsList
            end
            task.spawn(SC_RebuildAllSkinsList)

            local function SC_GetSkinsForWeapon(w)
                if w == 'All' then return {'Randomize All', 'None'} end
                local skins = SC_WeaponsData[w] or {}
                if #skins == 0 then return {'No Skins Found'} end
                return skins
            end

            local SC_batchDepth = 0
            local SC_pendingReplicate = false

            local function SC_BeginBatch()
                SC_batchDepth = SC_batchDepth + 1
            end

            local function SC_EndBatch(forceReplicate)
                SC_batchDepth = math.max(0, SC_batchDepth - 1)
                if SC_batchDepth == 0 then
                    SC_saveConfig()
                    if forceReplicate or SC_pendingReplicate then
                        SC_pendingReplicate = false
                        pcall(function()
                            if SC_DataController and SC_DataController.CurrentData then
                                SC_DataController.CurrentData:Replicate('WeaponInventory')
                            end
                        end)
                    end
                end
            end

            local function SC_EquipCosmetic(wName, cosType, cosName, skipReplicate)
                if not wName or not cosName or cosName == '' or cosName == 'No Skins Found' then return false end
                if cosName == 'None' then
                    if SC_equipped[wName] then
                        SC_equipped[wName][cosType] = nil
                        if not next(SC_equipped[wName]) then SC_equipped[wName] = nil end
                        if SC_batchDepth == 0 then
                            SC_saveConfig()
                            if not skipReplicate then
                                pcall(function()
                                    if SC_DataController and SC_DataController.CurrentData then
                                        SC_DataController.CurrentData:Replicate('WeaponInventory')
                                    end
                                end)
                            end
                        else
                            if not skipReplicate then SC_pendingReplicate = true end
                        end
                    end
                    pcall(function() if SC_equipRemote then SC_equipRemote:FireServer(wName, cosType, nil, {}) end end)
                    if cosType == 'Skin' then pcall(function() SC_SkinChanger:ResetSkinModel(wName) end) end
                    return true
                end
                local cosData = SC_cloneCosmetic(cosName, cosType)
                SC_equipped[wName] = SC_equipped[wName] or {}
                if cosData then
                    SC_equipped[wName][cosType] = cosData
                else
                    local fb = {Name = cosName, Type = cosType, Seed = math.random(1, 1000000)}
                    local eid = SC_getEnumSafe(cosName)
                    if eid then fb.Enum = eid fb.ObjectID = eid end
                    SC_equipped[wName][cosType] = fb
                end
                if SC_batchDepth == 0 then
                    SC_saveConfig()
                    if not skipReplicate then
                        pcall(function()
                            if SC_DataController and SC_DataController.CurrentData then
                                SC_DataController.CurrentData:Replicate('WeaponInventory')
                            end
                        end)
                    end
                else
                    if not skipReplicate then SC_pendingReplicate = true end
                end
                pcall(function() if SC_equipRemote then SC_equipRemote:FireServer(wName, cosType, cosName, {}) end end)
                if cosType == 'Skin' then
                    pcall(function() SC_SkinChanger:ApplySkinModel(wName, cosName) end)
                end
                return true
            end

