            local WorldESPState = {}

            function WorldESPState.InitThrowable()
                LPH_ATTRIBUTES(VM(NONE))
                local WORLD_ITEM_NAMES = {
                    ['Throwable - Grenade'] = {Color = Color3.fromRGB(255, 80, 80), Label = 'GRENADE', Key = 'Grenade'},
                    ['Throwable - Flashbang'] = {Color = Color3.fromRGB(255, 255, 100), Label = 'FLASH', Key = 'Flashbang'},
                    ['Throwable - Molotov'] = {Color = Color3.fromRGB(255, 120, 0), Label = 'MOLOTOV', Key = 'Molotov'},
                    ['Throwable - Smoke'] = {Color = Color3.fromRGB(200, 200, 200), Label = 'SMOKE', Key = 'Smoke'},
                    ['Smoke Grenade'] = {Color = Color3.fromRGB(200, 200, 200), Label = 'SMOKE', Key = 'Smoke'},
                    ['Satchel'] = {Color = Color3.fromRGB(255, 50, 50), Label = 'SATCHEL', Key = 'Satchel'},
                    ['SubspaceTripmineHitbox'] = {Color = Color3.fromRGB(255, 50, 50), Label = 'TRIPMINE', Key = 'Tripmine'},
                    ['Flare Gun'] = {Color = Color3.fromRGB(255, 50, 50), Label = 'FLARE GUN', Key = 'Flare Gun'},
                }

                local ThrowableESP = {}
                local ThrowableImageCache = {}

                local function IsTrackedItem(instance)
                    return instance
                        and (instance:IsA('BasePart') or instance:IsA('Model'))
                        and WORLD_ITEM_NAMES[instance.Name] ~= nil
                end

                local function IsThrowableWhitelisted(info)
                    local whitelist = EspRenderSettings.ThrowableWhitelist
                    if type(whitelist) ~= 'table' then
                        return true
                    end
                    local any = false
                    for _, enabled in pairs(whitelist) do
                        if enabled then
                            any = true
                            break
                        end
                    end
                    if not any then
                        return true
                    end
                    return whitelist[info.Key] == true
                end

                local function ResolveThrowableImage(partName, info)
                    local cacheKey = info.Key or partName
                    if ThrowableImageCache[cacheKey] ~= nil then
                        return ThrowableImageCache[cacheKey]
                    end
                    local image = ''
                    local cosmetics = RivalsRuntimeBridge.Cosmetics
                    if cosmetics and type(cosmetics.ResolveItemLibrary) == 'function' then
                        local library = cosmetics.ResolveItemLibrary()
                        local viewModels = library and library.ViewModels
                        if type(viewModels) == 'table' then
                            local data = viewModels[info.Key]
                                or viewModels[partName]
                                or viewModels['Throwable - ' .. tostring(info.Key)]
                            if type(data) == 'table' then
                                image = data.ImageHighResolution or data.Image or ''
                            end
                        end
                    end
                    ThrowableImageCache[cacheKey] = image
                    return image
                end

                local function HideThrowableEntry(entry)
                    if entry.labelVisible then
                        entry.label.Visible = false
                        entry.labelVisible = false
                    end
                    if entry.distanceVisible then
                        entry.distance.Visible = false
                        entry.distanceVisible = false
                    end
                    if entry.billboard then
                        entry.billboard.Enabled = false
                    end
                end

                local function CreateThrowableESP(part)
                    if ThrowableESP[part] then
                        return
                    end

                    local label = Drawing.new('Text')
                    label.Center = true
                    label.Outline = true
                    label.Font = 2
                    label.Visible = false
                    label.Size = 12
                    label.Transparency = PLAYER_CARD_THEME.ThrowableTextTransparency

                    local distance = Drawing.new('Text')
                    distance.Center = true
                    distance.Outline = true
                    distance.Font = 2
                    distance.Visible = false
                    distance.Size = 12
                    distance.Transparency = PLAYER_CARD_THEME.ThrowableTextTransparency

                    local billboard = Instance.new('BillboardGui')
                    billboard.Name = 'AkiraThrowableEsp'
                    billboard.AlwaysOnTop = true
                    billboard.Size = UDim2.fromOffset(42, 42)
                    billboard.StudsOffset = Vector3.new(0, 1.4, 0)
                    billboard.Enabled = false
                    local adornee = part
                    if part:IsA('Model') then
                        adornee = part.PrimaryPart or part:FindFirstChildWhichIsA('BasePart') or part
                    end
                    pcall(function()
                        billboard.Adornee = adornee
                        billboard.Parent = adornee
                    end)

                    local icon = Instance.new('ImageLabel')
                    icon.BackgroundTransparency = 1
                    icon.Size = UDim2.fromScale(1, 1)
                    icon.ScaleType = Enum.ScaleType.Fit
                    icon.Parent = billboard

                    ThrowableESP[part] = {
                        label = label,
                        distance = distance,
                        billboard = billboard,
                        icon = icon,
                        lastRoundedDistance = nil,
                        lastLabelText = nil,
                        lastLabelSize = nil,
                        lastLabelColor = nil,
                        lastLabelPositionX = nil,
                        lastLabelPositionY = nil,
                        labelVisible = false,
                        distanceVisible = false,
                    }
                end

                local function DestroyThrowableESP(part)
                    local entry = ThrowableESP[part]
                    if not entry then
                        return
                    end

                    pcall(function()
                        entry.label:Remove()
                    end)
                    pcall(function()
                        entry.distance:Remove()
                    end)
                    pcall(function()
                        entry.billboard:Destroy()
                    end)
                    ThrowableESP[part] = nil
                end

                function WorldESPState.DestroyThrowable(part)
                    DestroyThrowableESP(part)
                end

                function WorldESPState.DestroyAllThrowable()
                    for part in pairs(ThrowableESP) do
                        DestroyThrowableESP(part)
                    end
                end

                function WorldESPState.RegisterThrowable(part)
                    if not IsTrackedItem(part) then
                        return
                    end

                    CreateThrowableESP(part)
                end

                function WorldESPState.UpdateThrowable()
                    LPH_ATTRIBUTES(VM(NONE))
                    local enabled = EspRenderSettings.ShowThrowable
                    if not enabled then
                        if next(ThrowableESP) ~= nil then
                            for _, entry in pairs(ThrowableESP) do
                                HideThrowableEntry(entry)
                            end
                        end
                        return
                    end

                    local cam = Workspace.CurrentCamera
                    if not cam then
                        return
                    end

                    local maxDist = tonumber(EspRenderSettings.MaxDistance) or DEFAULT_ESP_MAX_DISTANCE
                    local nameSize = math.max(tonumber(EspRenderSettings.ThrowableNameSize) or 14, 8)
                    local distanceSize = math.max(tonumber(EspRenderSettings.ThrowableDistanceSize) or 12, 8)
                    local showName = EspRenderSettings.ThrowableName ~= false
                    local showDistance = EspRenderSettings.ThrowableDistance ~= false
                    local showImage = EspRenderSettings.ThrowableImage == true
                    local nameColor = EspRenderSettings.ThrowableNameColor
                    local distanceColor = EspRenderSettings.ThrowableDistanceColor
                    local rootPosition = HumanoidRootPart and HumanoidRootPart.Position or nil
                    local maxDistSquared = maxDist * maxDist

                    for part in pairs(ThrowableESP) do
                        if not part.Parent or not part:IsDescendantOf(Workspace) or not IsTrackedItem(part) then
                            DestroyThrowableESP(part)
                        end
                    end

                    for part, entry in pairs(ThrowableESP) do
                        repeat
                        local info = WORLD_ITEM_NAMES[part.Name]
                        if not info or not IsThrowableWhitelisted(info) then
                            HideThrowableEntry(entry)
                            break
                        end

                        local pos = part:IsA('BasePart') and part.Position or part:GetPivot().Position
                        local screenPos, onScreen = cam:WorldToViewportPoint(pos)
                        if not onScreen or screenPos.Z <= 0 then
                            HideThrowableEntry(entry)
                            break
                        end

                        local dist = 0
                        if rootPosition then
                            local rootOffset = pos - rootPosition
                            local worldDistanceSquared = rootOffset:Dot(rootOffset)
                            if worldDistanceSquared > maxDistSquared then
                                HideThrowableEntry(entry)
                                break
                            end
                            dist = math.sqrt(worldDistanceSquared)
                        end

                        local screenX = math.round(screenPos.X)
                        local screenY = math.round(screenPos.Y)
                        local roundedDistance = math.floor(dist)

                        if showName then
                            if not entry.labelVisible then
                                entry.label.Visible = true
                                entry.labelVisible = true
                            end
                            if entry.lastLabelSize ~= nameSize then
                                entry.lastLabelSize = nameSize
                                entry.label.Size = nameSize
                            end
                            if entry.lastLabelText ~= info.Label then
                                entry.lastLabelText = info.Label
                                entry.label.Text = info.Label
                            end
                            local labelColor = nameColor or info.Color
                            if entry.lastLabelColor ~= labelColor then
                                entry.lastLabelColor = labelColor
                                entry.label.Color = labelColor
                            end
                            if entry.lastLabelPositionX ~= screenX or entry.lastLabelPositionY ~= screenY then
                                entry.lastLabelPositionX = screenX
                                entry.lastLabelPositionY = screenY
                                entry.label.Position = Vector2.new(screenX, screenY)
                            end
                        else
                            if entry.labelVisible then
                                entry.label.Visible = false
                                entry.labelVisible = false
                            end
                        end

                        if showDistance then
                            if not entry.distanceVisible then
                                entry.distance.Visible = true
                                entry.distanceVisible = true
                            end
                            entry.distance.Size = distanceSize
                            entry.distance.Color = distanceColor or info.Color
                            if entry.lastRoundedDistance ~= roundedDistance then
                                entry.lastRoundedDistance = roundedDistance
                                entry.distance.Text = string.format('%dm', roundedDistance)
                            end
                            local distanceY = screenY + (showName and (nameSize + 2) or 0)
                            entry.distance.Position = Vector2.new(screenX, distanceY)
                        else
                            if entry.distanceVisible then
                                entry.distance.Visible = false
                                entry.distanceVisible = false
                            end
                        end

                        if showImage then
                            local image = ResolveThrowableImage(part.Name, info)
                            if image ~= '' then
                                if entry.icon.Image ~= image then
                                    entry.icon.Image = image
                                end
                                entry.billboard.Enabled = true
                            else
                                entry.billboard.Enabled = false
                            end
                        else
                            entry.billboard.Enabled = false
                        end
                        until true
                    end
                end
            end
            WorldESPState.InitThrowable()

            function WorldESPState.InitHazard()
                LPH_ATTRIBUTES(VM(NONE))
                local WORLD_HAZARD_NAMES = {
                    ['MolotovHitbox'] = {
                        Color = Color3.fromRGB(255, 120, 0),
                        BoxTransparency = 0.78,
                    },
                }

                local HazardESP = {}

                local function IsTrackedHazard(instance)
                    return instance
                        and instance:IsA('BasePart')
                        and WORLD_HAZARD_NAMES[instance.Name] ~= nil
                end

                local function HideHazardESP(entry)
                    if not entry then
                        return
                    end

                    entry.box.Visible = false
                    entry.outline.Visible = false
                end

                local function DestroyHazardAdornment(entry)
                    if not entry then
                        return
                    end

                    pcall(function()
                        entry.box:Destroy()
                    end)
                    pcall(function()
                        entry.outline:Destroy()
                    end)
                end

                local function CreateHazardESP(part)
                    if HazardESP[part] then
                        return
                    end

                    local box = Instance.new('BoxHandleAdornment')
                    box.AlwaysOnTop = true
                    box.Adornee = part
                    box.Visible = false
                    box.ZIndex = 10
                    box.Parent = HazardAdornmentContainer

                    local outline = Instance.new('SelectionBox')
                    outline.Adornee = part
                    outline.Visible = false
                    outline.LineThickness = 0.04
                    outline.Parent = HazardAdornmentContainer

                    HazardESP[part] = {
                        box = box,
                        outline = outline,
                    }
                end

                local function DestroyHazardESP(part)
                    local entry = HazardESP[part]
                    if not entry then
                        return
                    end

                    DestroyHazardAdornment(entry)
                    HazardESP[part] = nil
                end

                function WorldESPState.DestroyHazard(part)
                    DestroyHazardESP(part)
                end

                function WorldESPState.DestroyAllHazard()
                    for part in pairs(HazardESP) do
                        DestroyHazardESP(part)
                    end
                end

                function WorldESPState.RegisterHazard(part)
                    if not IsTrackedHazard(part) then
                        return
                    end

                    CreateHazardESP(part)
                end

                function WorldESPState.UpdateHazard()
                    LPH_ATTRIBUTES(VM(NONE))
                    local enabled = EspRenderSettings.ShowThrowable
                    if not enabled then
                        if next(HazardESP) ~= nil then
                            for _, entry in pairs(HazardESP) do
                                HideHazardESP(entry)
                            end
                        end
                        return
                    end

                    local maxDist = DEFAULT_ESP_MAX_DISTANCE
                    local rootPosition = HumanoidRootPart and HumanoidRootPart.Position or nil
                    local maxDistSquared = maxDist * maxDist
                    for part, entry in pairs(HazardESP) do
                        repeat
                        local info = WORLD_HAZARD_NAMES[part.Name]
                        if not part.Parent or not part:IsDescendantOf(Workspace) or not info then
                            DestroyHazardESP(part)
                            break
                        end

                        if rootPosition then
                            local rootOffset = part.Position - rootPosition
                            local worldDistanceSquared = rootOffset:Dot(rootOffset)
                            if worldDistanceSquared > maxDistSquared then
                                HideHazardESP(entry)
                                break
                            end
                        end

                        entry.box.Adornee = part
                        entry.box.Size = part.Size
                        entry.box.Color3 = info.Color
                        entry.box.Transparency = info.BoxTransparency
                        entry.box.Visible = true

                        entry.outline.Adornee = part
                        entry.outline.Color3 = BlendColor(info.Color, Color3.fromRGB(255, 255, 255), 0.18)
                        entry.outline.SurfaceTransparency = 1
                        entry.outline.Visible = true
                        until true
                    end
                end
            end
            WorldESPState.InitHazard()

            function WorldESPState.InitSoundVisualizer()
                LPH_ATTRIBUTES(VM(NONE))
                WorldESPState.SoundVisualizer = {
                    Tracked = setmetatable({}, { __mode = 'k' }),
                    ActiveEffects = {},
                    PooledEffects = {},
                    Enabled = false,
                    MaxEffects = 32,
                }

                function WorldESPState.DisconnectSound(sound)
                    local trackedSounds = WorldESPState.SoundVisualizer.Tracked
                    local tracked = trackedSounds[sound]
                    if not tracked then
                        return
                    end
                    for _, connection in pairs(tracked.Connections) do
                        pcall(function()
                            connection:Disconnect()
                        end)
                    end
                    trackedSounds[sound] = nil
                end

                function WorldESPState.ResolveSoundEmitterPart(sound)
                    local parent = sound and sound.Parent or nil
                    if not parent then
                        return nil
                    end
                    if parent:IsA('BasePart') then
                        return parent
                    end
                    if parent:IsA('Attachment') and parent.Parent and parent.Parent:IsA('BasePart') then
                        return parent.Parent
                    end
                    return parent:FindFirstAncestorWhichIsA('BasePart')
                end

                function WorldESPState.ResolveSoundSourcePlayer(emitterPart)
                    local model = emitterPart and emitterPart:FindFirstAncestorOfClass('Model') or nil
                    while model do
                        local player = Players:GetPlayerFromCharacter(model)
                        if player then
                            return player
                        end
                        model = model.Parent and model.Parent:FindFirstAncestorOfClass('Model') or nil
                    end
                    return nil
                end

                function WorldESPState.IsSoundSourceAllowed(sourcePlayer)
                    local sourceMode = Options.P1S3D1 and Options.P1S3D1.Value or 'Enemies'
                    if sourcePlayer and sourcePlayer ~= LP
                        and not IsPlayerInLocalEnvironment(sourcePlayer) then
                        return false
                    end
                    if sourceMode == 'All' then
                        return true
                    elseif sourceMode == 'Self' then
                        return sourcePlayer == LP
                    elseif sourceMode == 'Team' then
                        return sourcePlayer ~= nil and sourcePlayer ~= LP and not ShouldShow(sourcePlayer, false)
                    end
                    return sourcePlayer ~= nil and sourcePlayer ~= LP and ShouldShow(sourcePlayer, false)
                end

                function WorldESPState.IsFootstepSound(sound, emitterPart)
                    local descriptor = string.lower(table.concat({
                        tostring(sound and sound.Name or ''),
                        tostring(emitterPart and emitterPart.Name or ''),
                        tostring(sound and sound.Parent and sound.Parent.Name or ''),
                    }, ' '))
                    return descriptor:find('foot', 1, true) ~= nil
                        or descriptor:find('step', 1, true) ~= nil
                        or descriptor:find('running', 1, true) ~= nil
                        or descriptor:find('landing', 1, true) ~= nil
                        or (emitterPart and emitterPart.Name == 'HumanoidRootPart'
                            and sound.Looped == false
                            and sound.TimeLength > 0
                            and sound.TimeLength <= 1)
                end

                function WorldESPState.CreateSoundEffect()
                    local anchor = Instance.new('Part')
                    anchor.Name = '__AkiraSoundPulse'
                    anchor.Anchored = true
                    anchor.CanCollide = false
                    anchor.CanQuery = false
                    anchor.CanTouch = false
                    anchor.CastShadow = false
                    anchor.Transparency = 1
                    anchor.Size = Vector3.new(0.05, 0.05, 0.05)
                    anchor.Parent = Workspace

                    local pulse = Instance.new('SphereHandleAdornment')
                    pulse.Name = '__AkiraSoundPulseAdornment'
                    pulse.Adornee = anchor
                    pulse.AlwaysOnTop = true
                    pulse.Visible = false
                    pulse.ZIndex = 9
                    pulse.Parent = anchor

                    return {
                        Anchor = anchor,
                        Pulse = pulse,
                        StartedAt = 0,
                        Duration = 0,
                        StartRadius = 0,
                        EndRadius = 0,
                    }
                end

                function WorldESPState.DeactivateSoundEffect(index, destroy)
                    local soundVisualizer = WorldESPState.SoundVisualizer
                    local effect = table.remove(soundVisualizer.ActiveEffects, index)
                    if not effect then
                        return
                    end
                    effect.Pulse.Visible = false
                    if destroy then
                        effect.Anchor:Destroy()
                    else
                        soundVisualizer.PooledEffects[#soundVisualizer.PooledEffects + 1] = effect
                    end
                end

                function WorldESPState.SpawnSoundEffect(sound)
                    local soundVisualizer = WorldESPState.SoundVisualizer
                    if not soundVisualizer.Enabled or not sound or not sound.Parent then
                        return
                    end

                    local minVolume = Options.P1S3S1 and Options.P1S3S1.Value or 0.05
                    if sound.Volume < minVolume then
                        return
                    end

                    local emitterPart = WorldESPState.ResolveSoundEmitterPart(sound)
                    if not emitterPart or not WorldESPState.IsSoundSourceAllowed(WorldESPState.ResolveSoundSourcePlayer(emitterPart)) then
                        return
                    end
                    if HumanoidRootPart and sound.RollOffMaxDistance > 0
                        and (emitterPart.Position - HumanoidRootPart.Position).Magnitude > sound.RollOffMaxDistance then
                        return
                    end

                    local isFootstep = WorldESPState.IsFootstepSound(sound, emitterPart)
                    if isFootstep and not (Toggles.P1S3T2 and Toggles.P1S3T2.Value) then
                        return
                    end
                    if not isFootstep and not (Toggles.P1S3T3 and Toggles.P1S3T3.Value) then
                        return
                    end

                    if #soundVisualizer.ActiveEffects >= soundVisualizer.MaxEffects then
                        WorldESPState.DeactivateSoundEffect(1, false)
                    end
                    local effect = table.remove(soundVisualizer.PooledEffects) or WorldESPState.CreateSoundEffect()
                    local loudnessScale = math.clamp(sound.Volume, 0.25, 2)
                    effect.Anchor.CFrame = CFrame.new(emitterPart.Position)
                    effect.StartedAt = tick()
                    effect.Duration = isFootstep and 0.65 or 0.9
                    effect.StartRadius = isFootstep and 0.45 or 0.8
                    effect.EndRadius = (isFootstep and 5 or 9) * loudnessScale
                    effect.Pulse.Color3 = isFootstep
                        and (Options.P1S3C1 and Options.P1S3C1.Value or Color3.fromRGB(255, 210, 80))
                        or (Options.P1S3C2 and Options.P1S3C2.Value or Color3.fromRGB(255, 90, 90))
                    effect.Pulse.Radius = effect.StartRadius
                    effect.Pulse.Transparency = 0.28
                    effect.Pulse.Visible = true
                    soundVisualizer.ActiveEffects[#soundVisualizer.ActiveEffects + 1] = effect
                end

                function WorldESPState.RegisterSound(instance)
                    local soundVisualizer = WorldESPState.SoundVisualizer
                    if not soundVisualizer.Enabled or not instance or not instance:IsA('Sound') or soundVisualizer.Tracked[instance] then
                        return
                    end

                    local tracked = {
                        LastPlayedAt = 0,
                        Connections = {},
                    }
                    soundVisualizer.Tracked[instance] = tracked
                    tracked.Connections.Played = instance.Played:Connect(GuardRivalsCallback('SoundVisualizer_Played', function()
                        local now = tick()
                        if (now - tracked.LastPlayedAt) < 0.03 then
                            return
                        end
                        tracked.LastPlayedAt = now
                        WorldESPState.SpawnSoundEffect(instance)
                    end))
                    tracked.Connections.Destroying = instance.Destroying:Connect(function()
                        WorldESPState.DisconnectSound(instance)
                    end)
                end

                function WorldESPState.DestroySound(instance)
                    if instance and instance:IsA('Sound') then
                        WorldESPState.DisconnectSound(instance)
                    end
                end

                function WorldESPState.UpdateSoundVisualizer()
                    LPH_ATTRIBUTES(VM(NONE))
                    local soundVisualizer = WorldESPState.SoundVisualizer
                    if not soundVisualizer.Enabled then
                        return
                    end

                    local now = tick()
                    for index = #soundVisualizer.ActiveEffects, 1, -1 do
                        local effect = soundVisualizer.ActiveEffects[index]
                        local alpha = math.clamp((now - effect.StartedAt) / effect.Duration, 0, 1)
                        if alpha >= 1 then
                            WorldESPState.DeactivateSoundEffect(index, false)
                        else
                            local easedAlpha = 1 - ((1 - alpha) * (1 - alpha))
                            effect.Pulse.Radius = effect.StartRadius + ((effect.EndRadius - effect.StartRadius) * easedAlpha)
                            effect.Pulse.Transparency = 0.28 + (alpha * 0.72)
                        end
                    end
                end

                function WorldESPState.SetSoundVisualizerEnabled(enabled)
                    local soundVisualizer = WorldESPState.SoundVisualizer
                    enabled = enabled == true
                    if enabled == soundVisualizer.Enabled then
                        return
                    end

                    if enabled then
                        if not Connections then
                            return
                        end

                        soundVisualizer.Enabled = true
                        Connections:register('SoundVisualizer_Added', Workspace.DescendantAdded:Connect(function(descendant)
                            if descendant:IsA('Sound') then
                                WorldESPState.RegisterSound(descendant)
                            end
                        end))
                        Connections:register('SoundVisualizer_Removed', Workspace.DescendantRemoving:Connect(GuardRivalsCallback('SoundVisualizer_Removed', WorldESPState.DestroySound)))
                        Connections:register('SoundVisualizer_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('SoundVisualizer_Render', WorldESPState.UpdateSoundVisualizer)))
                        task.spawn(GuardRivalsCallback('SoundVisualizer_Scan', function()
                            local function consider(root)
                                if not root then
                                    return
                                end
                                for _, descendant in ipairs(root:GetDescendants()) do
                                    if not WorldESPState.SoundVisualizer.Enabled then
                                        return
                                    end
                                    WorldESPState.RegisterSound(descendant)
                                end
                            end
                            consider(Workspace.CurrentCamera)
                            for _, player in ipairs(Players:GetPlayers()) do
                                consider(player.Character)
                            end
                        end))
                        return
                    end

                    soundVisualizer.Enabled = false
                    if Connections then
                        Connections:disconnect({
                            'SoundVisualizer_Added',
                            'SoundVisualizer_Removed',
                            'SoundVisualizer_Render',
                        })
                    end
                    local sounds = {}
                    for sound in pairs(soundVisualizer.Tracked) do
                        sounds[#sounds + 1] = sound
                    end
                    for _, sound in ipairs(sounds) do
                        WorldESPState.DisconnectSound(sound)
                    end
                    while #soundVisualizer.ActiveEffects > 0 do
                        WorldESPState.DeactivateSoundEffect(#soundVisualizer.ActiveEffects, false)
                    end
                end

                function WorldESPState.DestroyAllSoundVisualizer()
                    local soundVisualizer = WorldESPState.SoundVisualizer
                    soundVisualizer.Enabled = false
                    if Connections then
                        Connections:disconnect({
                            'SoundVisualizer_Added',
                            'SoundVisualizer_Removed',
                            'SoundVisualizer_Render',
                        })
                    end
                    local sounds = {}
                    for sound in pairs(soundVisualizer.Tracked) do
                        sounds[#sounds + 1] = sound
                    end
                    for _, sound in ipairs(sounds) do
                        WorldESPState.DisconnectSound(sound)
                    end
                    while #soundVisualizer.ActiveEffects > 0 do
                        WorldESPState.DeactivateSoundEffect(#soundVisualizer.ActiveEffects, true)
                    end
                    for _, effect in ipairs(soundVisualizer.PooledEffects) do
                        effect.Anchor:Destroy()
                    end
                    table.clear(soundVisualizer.PooledEffects)
                end
            end
            WorldESPState.InitSoundVisualizer()

            __akira_boot_yield()

            function RivalsRuntimeBridge.InitEspPreview()
            local EspClassic = RivalsRuntimeBridge.ESPClassic

            local function CreateEspPreviewPart(model, name, size, position, color)
                local part = Instance.new('Part')
                part.Name = name
                part.Size = size
                part.CFrame = CFrame.new(position)
                part.Anchored = true
                part.CanCollide = false
                part.CanQuery = false
                part.CanTouch = false
                part.CastShadow = false
                part.Material = Enum.Material.SmoothPlastic
                part.Color = color
                part.Parent = model
                return part
            end

            local function BuildEspPreviewModel()
                local model = Instance.new('Model')
                model.Name = 'AkiraEspPreview'
                local bodyColor = Color3.fromRGB(116, 124, 137)
                local limbColor = Color3.fromRGB(82, 90, 104)
                local torso = CreateEspPreviewPart(model, 'Torso', Vector3.new(2, 2.2, 1), Vector3.new(0, 0.65, 0), bodyColor)
                CreateEspPreviewPart(model, 'Head', Vector3.new(1.45, 1.45, 1.45), Vector3.new(0, 2.55, 0), Color3.fromRGB(152, 158, 168))
                CreateEspPreviewPart(model, 'LeftArm', Vector3.new(0.75, 2.1, 0.8), Vector3.new(-1.4, 0.7, 0), limbColor)
                CreateEspPreviewPart(model, 'RightArm', Vector3.new(0.75, 2.1, 0.8), Vector3.new(1.4, 0.7, 0), limbColor)
                CreateEspPreviewPart(model, 'LeftLeg', Vector3.new(0.85, 2.2, 0.9), Vector3.new(-0.52, -1.55, 0), limbColor)
                CreateEspPreviewPart(model, 'RightLeg', Vector3.new(0.85, 2.2, 0.9), Vector3.new(0.52, -1.55, 0), limbColor)
                model.PrimaryPart = torso

                local highlight = Instance.new('Highlight')
                highlight.Name = 'PreviewHighlight'
                highlight.Adornee = model
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.Parent = model
                return model, highlight
            end

            local function CreateEspPreviewPane(parent, anchorPoint, position, size, horizontalAlignment, verticalAlignment)
                local pane = Instance.new('Frame')
                pane.AnchorPoint = anchorPoint
                pane.Position = position
                pane.Size = size
                pane.BackgroundTransparency = 1
                pane.ZIndex = 23
                pane.Parent = parent

                local layout = Instance.new('UIListLayout')
                layout.Padding = UDim.new(0, 2)
                layout.FillDirection = Enum.FillDirection.Vertical
                layout.HorizontalAlignment = horizontalAlignment
                layout.VerticalAlignment = verticalAlignment
                layout.SortOrder = Enum.SortOrder.LayoutOrder
                layout.Parent = pane
                return pane
            end

            local function CreateEspPreviewLabel(parent, layoutOrder, textXAlignment)
                local label = Instance.new('TextLabel')
                label.LayoutOrder = layoutOrder
                label.Size = UDim2.new(1, 0, 0, 14)
                label.BackgroundTransparency = 1
                label.Font = Enum.Font.Code
                label.TextColor3 = PLAYER_CARD_THEME.BarTextColor
                label.TextSize = 13
                label.TextStrokeColor3 = PLAYER_CARD_THEME.Classic.BoxOutlineColor
                label.TextStrokeTransparency = 0
                label.TextXAlignment = textXAlignment or Enum.TextXAlignment.Center
                label.ZIndex = 24
                label.Parent = parent
                return label
            end

            local function CreateEspPreviewSegment(parent)
                local segment = Instance.new('Frame')
                segment.BackgroundColor3 = Color3.new(1, 1, 1)
                segment.BorderColor3 = PLAYER_CARD_THEME.Classic.BoxOutlineColor
                segment.BorderSizePixel = 1
                segment.ZIndex = 22
                segment.Visible = false
                segment.Parent = parent
                return segment
            end

            local function SetEspPreviewSegment(segment, visible, position, size, color)
                segment.Visible = visible
                if not visible then
                    return
                end
                segment.Position = position
                segment.Size = size
                segment.BackgroundColor3 = color
            end

            local function UpdateEspPreviewBox(state, visible, color)
                local segments = state.BoxSegments
                if not visible then
                    for _, segment in ipairs(segments) do
                        segment.Visible = false
                    end
                    return
                end

                SetEspPreviewSegment(segments[1], true, UDim2.fromScale(0, 0), UDim2.new(0.28, 0, 0, 2), color)
                SetEspPreviewSegment(segments[2], true, UDim2.new(0.72, 0, 0, 0), UDim2.new(0.28, 0, 0, 2), color)
                SetEspPreviewSegment(segments[3], true, UDim2.new(0, 0, 1, -2), UDim2.new(0.28, 0, 0, 2), color)
                SetEspPreviewSegment(segments[4], true, UDim2.new(0.72, 0, 1, -2), UDim2.new(0.28, 0, 0, 2), color)
                SetEspPreviewSegment(segments[5], true, UDim2.fromScale(0, 0), UDim2.new(0, 2, 0.28, 0), color)
                SetEspPreviewSegment(segments[6], true, UDim2.new(0, 0, 0.72, 0), UDim2.new(0, 2, 0.28, 0), color)
                SetEspPreviewSegment(segments[7], true, UDim2.new(1, -2, 0, 0), UDim2.new(0, 2, 0.28, 0), color)
                SetEspPreviewSegment(segments[8], true, UDim2.new(1, -2, 0.72, 0), UDim2.new(0, 2, 0.28, 0), color)
            end

            RivalsRuntimeBridge.UpdateEspPreview = function()
                local state = RivalsRuntimeBridge.EspPreviewState
                if not state or not state.Overlay or state.Overlay.Parent == nil then
                    return
                end

                local settings = EspRenderSettings
                local color = settings.VisibleColor
                state.Overlay.Visible = settings.Enabled
                state.Highlight.Enabled = settings.Enabled and settings.ShowHighlight
                state.Highlight.FillColor = color
                state.Highlight.OutlineColor = BlendColor(color, PLAYER_CARD_THEME.FrameColor, 0.24)
                state.Highlight.FillTransparency = settings.FillAlpha
                state.Highlight.OutlineTransparency = settings.OutlineAlpha

                UpdateEspPreviewBox(state, settings.ShowBox, color)

                state.Name.Visible = settings.ShowName
                state.Name.Text = LP and LP.Name or 'Player'
                local useHorizontalHealth = settings.ShowHealth and not settings.UseVerticalHealth
                state.TopPane.Position = UDim2.new(0.5, 0, 0, useHorizontalHealth and -21 or -2)

                state.HealthRail.Visible = settings.ShowHealth
                state.HealthNumber.Visible = settings.ShowHealth
                if settings.UseVerticalHealth then
                    state.HealthRailCorner.CornerRadius = UDim.new(0, 0)
                    state.HealthFillCorner.CornerRadius = UDim.new(0, 0)
                    state.HealthRail.AnchorPoint = Vector2.new(1, 0)
                    state.HealthRail.Position = UDim2.new(0, -6, 0, 0)
                    state.HealthRail.Size = UDim2.new(0, 4, 1, 0)
                    state.HealthFill.AnchorPoint = Vector2.new(0, 1)
                    state.HealthFill.Position = UDim2.fromScale(0, 1)
                    state.HealthFill.Size = UDim2.fromScale(1, 0.75)
                    state.HealthNumber.AnchorPoint = Vector2.new(1, 0.5)
                    state.HealthNumber.Position = UDim2.new(0, -10, 0.25, 0)
                    state.HealthNumber.Size = UDim2.new(0, 30, 0, 14)
                    state.HealthNumber.Text = '75'
                else
                    state.HealthRailCorner.CornerRadius = UDim.new(1, 0)
                    state.HealthFillCorner.CornerRadius = UDim.new(1, 0)
                    state.HealthRail.AnchorPoint = Vector2.new(0.5, 1)
                    state.HealthRail.Position = UDim2.new(0.5, 0, 0, -3)
                    state.HealthRail.Size = UDim2.new(0, 60, 0, 14)
                    state.HealthFill.AnchorPoint = Vector2.new(0, 0)
                    state.HealthFill.Position = UDim2.fromScale(0, 0)
                    state.HealthFill.Size = UDim2.fromScale(0.75, 1)
                    state.HealthNumber.AnchorPoint = Vector2.new(0.5, 0.5)
                    state.HealthNumber.Position = UDim2.new(0.5, 0, 0, -10)
                    state.HealthNumber.Size = UDim2.new(0, 54, 0, 14)
                    state.HealthNumber.Text = '75 HP'
                end
                state.HealthFill.BackgroundColor3 = settings.UseVerticalHealth
                    and EspClassic.GetReactiveBarColor(0.75)
                    or GetHealthBarColor(0.75)

                state.AmmoNumber.Visible = settings.ShowAmmoText
                state.AmmoNumber.Text = '20/30'
                state.BottomPane.Position = UDim2.new(0.5, 0, 1, 3)

                state.LookDirectionLine.Visible = settings.ShowLookDir
                state.LookDirectionLine.BackgroundColor3 = settings.LookDirColor

                state.HeldWeapon.Visible = settings.ShowWeapon
                state.HeldWeapon.Text = 'Assault Rifle'
                state.Distance.Visible = settings.ShowDistance
                state.Distance.Text = '42m'
                state.Deflecting.Visible = settings.ShowDeflecting
                state.Deflecting.Text = 'DEFLECTING'
                state.Rank.Visible = settings.ShowRank
                state.Rank.Text = 'DIAMOND'
                state.WinStreak.Visible = settings.ShowWinStreak
                state.WinStreak.Text = '5 WS'

                local previewFont = Enum.Font.Code
                local mainTextSize = 16
                local flagTextSize = 12
                for _, label in ipairs({state.Name, state.AmmoNumber, state.HeldWeapon, state.Distance}) do
                    label.Font = previewFont
                    label.TextSize = mainTextSize
                end
                state.HealthNumber.Font = previewFont
                state.HealthNumber.TextSize = mainTextSize
                for _, label in ipairs({state.Deflecting, state.Rank, state.WinStreak}) do
                    label.Font = previewFont
                    label.TextSize = flagTextSize
                end
                for _, pane in ipairs({state.TopPane, state.BottomPane, state.RightPane}) do
                    local layout = pane:FindFirstChildOfClass('UIListLayout')
                    if layout then
                        layout.Padding = UDim.new(0, 1)
                    end
                end
            end

            RivalsRuntimeBridge.BuildEspPreview = function(groupbox)
                local function BuildEspPreviewAvatarModel()
                    local descriptionOk, description = pcall(function()
                        return Players:GetHumanoidDescriptionFromUserIdAsync(LP.UserId)
                    end)
                    if not descriptionOk or description == nil then
                        return nil
                    end
                    local modelOk, avatarModel = pcall(function()
                        return Players:CreateHumanoidModelFromDescriptionAsync(description, Enum.HumanoidRigType.R15)
                    end)
                    if not modelOk or avatarModel == nil then
                        return nil
                    end
                    avatarModel:PivotTo(CFrame.identity)
                    local animate = avatarModel:FindFirstChild('Animate')
                    if animate then
                        animate:Destroy()
                    end
                    return avatarModel
                end

                local EspPreviewOrbit = {
                    Rotation = math.rad(225),
                    Elevation = math.rad(20),
                    DistanceMultiplier = 4,
                    ModelCenter = Vector3.zero,
                    ModelSize = Vector3.zero,
                    ModelRadius = 4,
                }

                local function MeasureEspPreviewModel(previewModel)
                    local minCorner, maxCorner
                    for _, descendant in ipairs(previewModel:GetDescendants()) do
                        if descendant:IsA('BasePart') and not descendant:FindFirstAncestorOfClass('Accessory') then
                            local halfSize = descendant.Size * 0.5
                            local lowCorner = descendant.Position - halfSize
                            local highCorner = descendant.Position + halfSize
                            if not minCorner then
                                minCorner, maxCorner = lowCorner, highCorner
                            else
                                minCorner = Vector3.new(math.min(minCorner.X, lowCorner.X), math.min(minCorner.Y, lowCorner.Y), math.min(minCorner.Z, lowCorner.Z))
                                maxCorner = Vector3.new(math.max(maxCorner.X, highCorner.X), math.max(maxCorner.Y, highCorner.Y), math.max(maxCorner.Z, highCorner.Z))
                            end
                        end
                    end
                    if not minCorner then
                        return
                    end
                    local size = maxCorner - minCorner
                    EspPreviewOrbit.ModelCenter = (minCorner + maxCorner) * 0.5
                    EspPreviewOrbit.ModelSize = size
                    EspPreviewOrbit.ModelRadius = math.max(size.X, size.Y, size.Z) * 0.5
                end

                local UpdateEspPreviewOverlayRect = nil

                local function UpdateEspPreviewCamera(camera)
                    local distance = math.max(EspPreviewOrbit.ModelRadius * 2.4 * EspPreviewOrbit.DistanceMultiplier, 4)
                    local elevation = math.clamp(EspPreviewOrbit.Elevation, -math.pi / 2 + 0.1, math.pi / 2 - 0.1)
                    local planar = math.cos(elevation)
                    local offset = Vector3.new(
                        math.cos(EspPreviewOrbit.Rotation) * distance * planar,
                        math.sin(elevation) * distance,
                        math.sin(EspPreviewOrbit.Rotation) * distance * planar
                    )
                    camera.CFrame = CFrame.new(EspPreviewOrbit.ModelCenter + offset, EspPreviewOrbit.ModelCenter)
                    if UpdateEspPreviewOverlayRect then
                        UpdateEspPreviewOverlayRect()
                    end
                end

                local model, highlight = BuildEspPreviewModel()
                local viewport = groupbox:AddViewport('P1S4V1', {
                    Object = model,
                    Clone = false,
                    AutoFocus = false,
                    Interactive = false,
                    Height = 400,
                })
                if not viewport then
                    model:Destroy()
                    return
                end
                viewport.Camera.FieldOfView = 18
                MeasureEspPreviewModel(model)
                UpdateEspPreviewCamera(viewport.Camera)

                local viewportFrame = viewport.Object.Parent
                viewportFrame.LightDirection = Vector3.new(-1, -1, -1).Unit
                viewportFrame.LightColor = Color3.fromRGB(255, 255, 255)
                viewportFrame.Ambient = Color3.fromRGB(140, 140, 150)
                viewportFrame.ClipsDescendants = true

                local previewWorldModel = Instance.new('WorldModel')
                previewWorldModel.Parent = viewportFrame
                model.Parent = previewWorldModel

                local backgroundFrame = Instance.new('Frame')
                backgroundFrame.Name = 'EspPreviewBackground'
                backgroundFrame.Size = UDim2.fromScale(1, 1)
                backgroundFrame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                backgroundFrame.BorderSizePixel = 0
                backgroundFrame.ZIndex = 0
                backgroundFrame.Parent = viewportFrame.Parent

                local backgroundGradient = Instance.new('UIGradient')
                backgroundGradient.Rotation = 90
                backgroundGradient.Color = ColorSequence.new(Library.Scheme.MainColor, Library.Scheme.BackgroundColor)
                backgroundGradient.Parent = backgroundFrame

                local backgroundCorner = Instance.new('UICorner')
                backgroundCorner.CornerRadius = UDim.new(0, 6)
                backgroundCorner.Parent = backgroundFrame

                local viewportCorner = Instance.new('UICorner')
                viewportCorner.CornerRadius = UDim.new(0, 6)
                viewportCorner.Parent = viewportFrame

                local orbitButton = Instance.new('TextButton')
                orbitButton.Name = 'EspPreviewOrbitButton'
                orbitButton.Size = UDim2.fromScale(1, 1)
                orbitButton.BackgroundTransparency = 1
                orbitButton.Text = ''
                orbitButton.AutoButtonColor = false
                orbitButton.ZIndex = 19
                orbitButton.Parent = viewportFrame

                local orbitDragging = false
                local orbitLastPosition = nil
                orbitButton.MouseEnter:Connect(GuardRivalsCallback('EspPreview_HoverScroll', function()
                    for _, side in ipairs(groupbox.Tab.Sides) do
                        side.ScrollingEnabled = false
                    end
                end))
                orbitButton.MouseLeave:Connect(GuardRivalsCallback('EspPreview_HoverScroll', function()
                    for _, side in ipairs(groupbox.Tab.Sides) do
                        side.ScrollingEnabled = true
                    end
                end))
                orbitButton.InputBegan:Connect(GuardRivalsCallback('EspPreview_OrbitDrag', function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        orbitDragging = true
                        orbitLastPosition = nil
                    end
                end))
                orbitButton.InputChanged:Connect(GuardRivalsCallback('EspPreview_OrbitZoom', function(input)
                    if input.UserInputType ~= Enum.UserInputType.MouseWheel then
                        return
                    end
                    local direction = 1
                    if input.Position.Z > 0 then
                        direction = -1
                    end
                    EspPreviewOrbit.DistanceMultiplier = math.clamp(EspPreviewOrbit.DistanceMultiplier * 0.85 ^ (-direction), 0.2, 6)
                    UpdateEspPreviewCamera(viewport.Camera)
                end))
                Library:GiveSignal(UserInputService.InputChanged:Connect(GuardRivalsCallback('EspPreview_OrbitDrag', function(input)
                    if not orbitDragging then
                        return
                    end
                    if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then
                        return
                    end
                    local position = Vector2.new(input.Position.X, input.Position.Y)
                    if orbitLastPosition then
                        local delta = position - orbitLastPosition
                        EspPreviewOrbit.Rotation = EspPreviewOrbit.Rotation - delta.X * 0.012
                        EspPreviewOrbit.Elevation = math.clamp(EspPreviewOrbit.Elevation - delta.Y * 0.012, -math.pi / 2 + 0.1, math.pi / 2 - 0.1)
                        UpdateEspPreviewCamera(viewport.Camera)
                    end
                    orbitLastPosition = position
                end)))
                Library:GiveSignal(UserInputService.InputEnded:Connect(GuardRivalsCallback('EspPreview_OrbitDrag', function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        orbitDragging = false
                        orbitLastPosition = nil
                    end
                end)))
                local overlay = Instance.new('Frame')
                overlay.Name = 'EspPreviewOverlay'
                overlay.Size = UDim2.fromScale(1, 1)
                overlay.BackgroundTransparency = 1
                overlay.ZIndex = 20
                overlay.Parent = viewportFrame

                local target = Instance.new('Frame')
                target.Name = 'TargetRect'
                target.AnchorPoint = Vector2.new(0.5, 0.5)
                target.Position = UDim2.fromScale(0.5, 0.5)
                target.Size = UDim2.fromScale(0.3, 0.6)
                target.BackgroundTransparency = 1
                target.ZIndex = 21
                target.Parent = overlay

                UpdateEspPreviewOverlayRect = function()
                    local viewportSize = viewportFrame.AbsoluteSize
                    if viewportSize.X < 1 or viewportSize.Y < 1 then
                        return
                    end
                    local camera = viewport.Camera
                    local cameraCFrame = camera.CFrame
                    local tanHalfFov = math.tan(math.rad(camera.FieldOfView) * 0.5)
                    local aspect = viewportSize.X / viewportSize.Y
                    local center = EspPreviewOrbit.ModelCenter
                    local halfSize = EspPreviewOrbit.ModelSize * 0.5
                    local minX, minY, maxX, maxY
                    for xSign = -1, 1, 2 do
                        for ySign = -1, 1, 2 do
                            for zSign = -1, 1, 2 do
                                local corner = center + Vector3.new(halfSize.X * xSign, halfSize.Y * ySign, halfSize.Z * zSign)
                                local relative = cameraCFrame:PointToObjectSpace(corner)
                                local depth = math.max(-relative.Z, 0.05)
                                local screenX = (relative.X / (depth * tanHalfFov * aspect) * 0.5 + 0.5) * viewportSize.X
                                local screenY = (0.5 - relative.Y / (depth * tanHalfFov) * 0.5) * viewportSize.Y
                                if not minX or screenX < minX then minX = screenX end
                                if not maxX or screenX > maxX then maxX = screenX end
                                if not minY or screenY < minY then minY = screenY end
                                if not maxY or screenY > maxY then maxY = screenY end
                            end
                        end
                    end
                    target.Position = UDim2.fromOffset(math.round((minX + maxX) * 0.5), math.round((minY + maxY) * 0.5))
                    target.Size = UDim2.fromOffset(math.round(maxX - minX), math.round(maxY - minY))
                end
                UpdateEspPreviewOverlayRect()
                viewportFrame:GetPropertyChangedSignal('AbsoluteSize'):Connect(GuardRivalsCallback('EspPreview_Layout', UpdateEspPreviewOverlayRect))

                local boxSegments = table.create(8)
                for segmentIndex = 1, 8 do
                    boxSegments[segmentIndex] = CreateEspPreviewSegment(target)
                end

                local topPane = CreateEspPreviewPane(
                    target,
                    Vector2.new(0.5, 1),
                    UDim2.new(0.5, 0, 0, -2),
                    UDim2.new(3, 0, 0, 18),
                    Enum.HorizontalAlignment.Center,
                    Enum.VerticalAlignment.Bottom
                )
                local bottomPane = CreateEspPreviewPane(
                    target,
                    Vector2.new(0.5, 0),
                    UDim2.new(0.5, 0, 1, 3),
                    UDim2.new(3, 0, 0, 48),
                    Enum.HorizontalAlignment.Center,
                    Enum.VerticalAlignment.Top
                )
                local rightPane = CreateEspPreviewPane(
                    target,
                    Vector2.new(0, 0),
                    UDim2.new(1, 6, 0, 0),
                    UDim2.new(2, 0, 1, 0),
                    Enum.HorizontalAlignment.Left,
                    Enum.VerticalAlignment.Top
                )

                local healthRail = Instance.new('Frame')
                healthRail.BackgroundColor3 = PLAYER_CARD_THEME.BarBackgroundColor
                healthRail.BorderColor3 = PLAYER_CARD_THEME.Classic.BoxOutlineColor
                healthRail.BorderSizePixel = 1
                healthRail.ZIndex = 23
                healthRail.Parent = target
                local healthFill = Instance.new('Frame')
                healthFill.BackgroundColor3 = EspClassic.GetReactiveBarColor(0.75)
                healthFill.BorderSizePixel = 0
                healthFill.ZIndex = 24
                healthFill.Parent = healthRail
                local healthRailCorner = Instance.new('UICorner')
                healthRailCorner.Parent = healthRail
                local healthFillCorner = Instance.new('UICorner')
                healthFillCorner.Parent = healthFill
                local healthNumber = CreateEspPreviewLabel(target, 0, Enum.TextXAlignment.Center)

                local lookDirectionLine = Instance.new('Frame')
                lookDirectionLine.Name = 'LookDirectionLine'
                lookDirectionLine.AnchorPoint = Vector2.new(0, 0.5)
                lookDirectionLine.Position = UDim2.new(0.5, 0, 0.16, 0)
                lookDirectionLine.Size = UDim2.new(0, 38, 0, 2)
                lookDirectionLine.Rotation = -12
                lookDirectionLine.BackgroundColor3 = Color3.fromRGB(255, 255, 0)
                lookDirectionLine.BorderSizePixel = 0
                lookDirectionLine.ZIndex = 25
                lookDirectionLine.Parent = target

                RivalsRuntimeBridge.EspPreviewState = {
                    Viewport = viewport,
                    Overlay = overlay,
                    Target = target,
                    Highlight = highlight,
                    BoxSegments = boxSegments,
                    TopPane = topPane,
                    BottomPane = bottomPane,
                    RightPane = rightPane,
                    Name = CreateEspPreviewLabel(topPane, 1),
                    AmmoNumber = CreateEspPreviewLabel(bottomPane, 1),
                    HeldWeapon = CreateEspPreviewLabel(bottomPane, 2),
                    Distance = CreateEspPreviewLabel(bottomPane, 3),
                    Deflecting = CreateEspPreviewLabel(rightPane, 1, Enum.TextXAlignment.Left),
                    Rank = CreateEspPreviewLabel(rightPane, 2, Enum.TextXAlignment.Left),
                    WinStreak = CreateEspPreviewLabel(rightPane, 3, Enum.TextXAlignment.Left),
                    HealthRail = healthRail,
                    HealthFill = healthFill,
                    HealthRailCorner = healthRailCorner,
                    HealthFillCorner = healthFillCorner,
                    HealthNumber = healthNumber,
                    LookDirectionLine = lookDirectionLine,
                }
                RivalsRuntimeBridge.UpdateEspPreview()

                task.spawn(GuardRivalsCallback('EspPreview_Avatar', function()
                    local waited = 0
                    while RivalsRuntimeBridge.RuntimeRefreshSuspended and waited < 3 do
                        task.wait(0.15)
                        waited = waited + 0.15
                    end
                    task.wait(0.35)
                    local avatarModel = BuildEspPreviewAvatarModel()
                    if avatarModel == nil then
                        return
                    end
                    if Library.Unloaded or viewport.Destroyed then
                        avatarModel:Destroy()
                        return
                    end
                    viewport:SetObject(avatarModel)
                    avatarModel.Parent = previewWorldModel
                    avatarModel:PivotTo(CFrame.identity)
                    local avatarHighlight = Instance.new('Highlight')
                    avatarHighlight.Name = 'PreviewHighlight'
                    avatarHighlight.Adornee = avatarModel
                    avatarHighlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                    avatarHighlight.Parent = avatarModel
                    local state = RivalsRuntimeBridge.EspPreviewState
                    if state then
                        state.Highlight = avatarHighlight
                    end
                    task.wait(0.2)
                    MeasureEspPreviewModel(avatarModel)
                    EspPreviewOrbit.Rotation = math.rad(225)
                    UpdateEspPreviewCamera(viewport.Camera)
                    RivalsRuntimeBridge.UpdateEspPreview()
                end))
            end
            end
            task.defer(function()
                local waited = 0
                while RivalsRuntimeBridge.RuntimeRefreshSuspended and waited < 4 do
                    task.wait(0.15)
                    waited = waited + 0.15
                end
                task.wait(0.1)
                pcall(RivalsRuntimeBridge.InitEspPreview)
            end)

            __akira_boot_status('Creating menu...')
            local Window = GameBootstrap.create_window({
                library = Library,
                script_paths = ScriptPaths,
                auto_show_config = AutoShowConfig,
                position = UDim2.new(0, 230, 0, 200),
                title = TitleTemplate,
                center = true,
            })
            pcall(function()
                local env = (type(getgenv) == 'function' and getgenv()) or _G
                if type(env) == 'table' and env.__AkiraOpenMenu == true then
                    if type(Library.SetVisible) == 'function' then
                        Library:SetVisible(true)
                    elseif Library.Toggled ~= true and type(Library.Toggle) == 'function' then
                        Library:Toggle()
                    end
                end
            end)
            __akira_boot_yield(true)

