                })
                local EffectsTabbox, ViewCamTabbox, CrosshairTabbox, WorldEnvTabbox, PostFxTabbox
                local function akiraUiRun(name, fn)
                    if type(__akira_boot_status) == 'function' then
                        __akira_boot_status('Building ' .. tostring(name) .. '...')
                    end
                    local ok, err = pcall(fn)
                    if not ok then
                        ReportRivalsRuntimeIssue('ui_' .. tostring(name), err)
                    end
                end
                local function BindViewmodelVisualOption(control)
                    if control and type(control.OnChanged) == 'function' then
                        control:OnChanged(GuardRivalsCallback('ViewmodelVisuals_OptionChanged', function(...)
                            if (Library and (Library.ConfigLoading or Library.LayoutSuspended)) or (RivalsRuntimeBridge and RivalsRuntimeBridge.RuntimeRefreshSuspended) then
                                return
                            end
                            RivalsRuntimeBridge.ViewmodelVisuals.RefreshAll(...)
                        end))
                    end
                    return control
                end
                local function BindVisualRemovalOption(control)
                    if control and type(control.OnChanged) == 'function' then
                        control:OnChanged(GuardRivalsCallback('NativeRemovals_OptionChanged', function(...)
                            if (Library and (Library.ConfigLoading or Library.LayoutSuspended)) or (RivalsRuntimeBridge and RivalsRuntimeBridge.RuntimeRefreshSuspended) then
                                return
                            end
                            RivalsRuntimeBridge.NativeRemovals.RefreshAll(...)
                        end))
                    end
                    return control
                end
                local function BindWorldVisualOption(control)
                    if control and type(control.OnChanged) == 'function' then
                        -- Resolve the option/toggle id once at bind time so each change
                        -- can refresh only the subsystem it affects.
                        local boundOptionId = nil
                        for id, opt in pairs(Options or {}) do
                            if opt == control then boundOptionId = id break end
                        end
                        if not boundOptionId then
                            for id, tgl in pairs(Toggles or {}) do
                                if tgl == control then boundOptionId = id break end
                            end
                        end
                        control:OnChanged(GuardRivalsCallback('WorldVisuals_OptionChanged', function()
                            if (Library and Library.ConfigLoading) or RivalsRuntimeBridge.RuntimeRefreshSuspended then
                                return
                            end
                            RivalsRuntimeBridge.WorldVisuals.RefreshForOption(boundOptionId)
                        end))
                    end
                    return control
                end
