                RagebotGroup:AddToggle('P8S4T7', { Text = 'Use Melee', Default = false, Tooltip = 'When melee is equipped (or guns are turned off), ragebot teleports into the target and spam-hits. Hits every nearby enemy hitbox.' })
                RagebotGroup:AddDropdown('P8S4D1', {
