                local function CallHvh(method, ...)
                    local hvh = RivalsRuntimeBridge.HvhSystems
                    if hvh and type(hvh[method]) == 'function' then
                        return hvh[method](...)
                    end
                end

                -- ==============================================================
                -- VOID MOVEMENT
                -- ==============================================================
                local HvhMoveTabbox = HvhTab:AddLeftTabbox('Movement')
                local VoidGroup = HvhMoveTabbox:AddTab('Void')
