            RivalsUIBuilders.BuildRivalsPickupUi = function(Window)
                local P3 = Window:AddTab('Auto', 'activity')
                local AutoTabbox = P3:AddLeftTabbox('Automation')
            local P3S1 = AutoTabbox:AddTab('Pickups')
                P3S1:AddToggle('P8S1T1', {
                    Text = 'Auto Heal',
                    Default = false,
                    Tooltip = 'Automatically grabs health packs when you are low.',
                })
                P3S1:AddToggle('P8S1T2', {
                    Text = 'Auto Ammo Pickup',
                    Default = false,
                    Tooltip = 'Automatically grabs ammo packs when your magazine is empty.',
                })
                P3S1:AddToggle('P8S4T2', {
                    Text = 'Auto Respawn',
                    Default = false,
                    Tooltip = 'Respawns you automatically when the death prompt appears.',
                })

                Toggles.P8S1T1:OnChanged(GuardRivalsCallback('AutoHeal_ToggleChanged', function(value)
                    if value and UpdateRivalsPickupFeatures then
                        UpdateRivalsPickupFeatures()
                    end
                end))
                Toggles.P8S1T2:OnChanged(GuardRivalsCallback('AutoAmmo_ToggleChanged', function(value)
                    if value and UpdateRivalsPickupFeatures then
                        UpdateRivalsPickupFeatures()
                    end
                end))

                local P3S8 = AutoTabbox:AddTab('Tripmines')
                P3S8:AddToggle('P8S8T1', {
                    Text = 'Auto Trigger',
                    Default = false,
                    Tooltip = 'Automatically sets off enemy tripmines.',
                })
                P3S8:AddToggle('P8S8T2', {
                    Text = 'Team Trigger',
                    Default = false,
                    Tooltip = 'Also triggers your own and allied tripmines.',
                })

                local AutoRightTabbox = P3:AddRightTabbox('Queue & Loadout')
            local P3S5 = AutoRightTabbox:AddTab('Loadout & Ban')
                P3S5:AddToggle('P8S5T1', {
                    Text = 'Auto Loadout',
                    Default = false,
                    Tooltip = 'Fills your pick screen once per open using the selected slot fallbacks.',
                })
                P3S5:AddToggle('P8S5T3', {
                    Text = 'Per Map',
                    Default = false,
                    Tooltip = 'Keeps a separate set of loadouts for each selected map.',
                })
                local DepAutoLoadoutMap = P3S5:AddDependencyBox()
                DepAutoLoadoutMap:AddDropdown('P8S5D7', {
                    Values = RivalsRuntimeBridge.ResolveAutoLoadoutMapValues(),
                    Default = 1,
                    Multi = false,
                    Text = 'Map',
                    Searchable = true,
                    MaxVisibleDropdownItems = 12,
                })
                DepAutoLoadoutMap:SetupDependencies({{ Toggles.P8S5T3, true }})

                P3S5:AddToggle('P8S5T4', {
                    Text = 'Multiple Loadouts',
                    Default = false,
                    Tooltip = 'Uses priorities 1 through 3 as item-by-item fallbacks when a weapon is unavailable.',
                })
                local DepAutoLoadoutPriority = P3S5:AddDependencyBox()
                DepAutoLoadoutPriority:AddDropdown('P8S5D8', {
                    Values = RivalsRuntimeBridge.ResolveAutoLoadoutPriorities(),
                    Default = '1',
                    Multi = false,
                    Text = 'Priority',
                })
                DepAutoLoadoutPriority:SetupDependencies({{ Toggles.P8S5T4, true }})

                local DepAutoLoadout = P3S5:AddDependencyBox()
                DepAutoLoadout:AddDropdown('P8S5D1', {
                    Values = RivalsRuntimeBridge.ResolveAutoLoadoutWeaponValues('Primary'),
                    Default = RivalsRuntimeBridge.ResolveAutoLoadoutDefaultWeapon('Primary'),
                    Multi = false,
                    Text = 'Primary',
                    Tooltip = 'Primary weapon for the selected map and loadout priority.',
                })
                DepAutoLoadout:AddDropdown('P8S5D2', {
                    Values = RivalsRuntimeBridge.ResolveAutoLoadoutWeaponValues('Secondary'),
                    Default = RivalsRuntimeBridge.ResolveAutoLoadoutDefaultWeapon('Secondary'),
                    Multi = false,
                    Text = 'Secondary',
                    Tooltip = 'Secondary weapon for the selected map and loadout priority.',
                })
                DepAutoLoadout:AddDropdown('P8S5D3', {
                    Values = RivalsRuntimeBridge.ResolveAutoLoadoutWeaponValues('Melee'),
                    Default = RivalsRuntimeBridge.ResolveAutoLoadoutDefaultWeapon('Melee'),
                    Multi = false,
                    Text = 'Melee',
                    Tooltip = 'Melee weapon for the selected map and loadout priority.',
                })
                DepAutoLoadout:AddDropdown('P8S5D4', {
                    Values = RivalsRuntimeBridge.ResolveAutoLoadoutWeaponValues('Utility'),
                    Default = RivalsRuntimeBridge.ResolveAutoLoadoutDefaultWeapon('Utility'),
                    Multi = false,
                    Text = 'Utility',
                    Tooltip = 'Utility weapon for the selected map and loadout priority.',
                })
                DepAutoLoadout:SetupDependencies({{ Toggles.P8S5T1, true }})
                RivalsRuntimeBridge.RefreshAutoLoadoutDropdownValues()

                Toggles.P8S5T1:OnChanged(GuardRivalsCallback('AutoLoadout_ToggleChanged', function(value)
                    if value then
                        RivalsRuntimeBridge.QueueAutoLoadoutSubmission()
                    else
                        RivalsRuntimeBridge.ResetAutoLoadoutState()
                    end
                end))

                for _, optionId in ipairs({'P8S5D1', 'P8S5D2', 'P8S5D3', 'P8S5D4'}) do
                    local option = Options[optionId]
                    if option and type(option.OnChanged) == 'function' then
                        option:OnChanged(GuardRivalsCallback(string.format('AutoLoadout_%s_Changed', optionId), function()
                            if RivalsAutoLoadoutState.RefreshingDropdownValues > 0 then
                                return
                            end

                            RivalsRuntimeBridge.SyncAutoLoadoutSelection(optionId)
                            RivalsRuntimeBridge.QueueAutoLoadoutSubmission()
                        end))
                    end
                end

                local function RefreshAutoLoadoutProfile()
                    if RivalsAutoLoadoutState.RefreshingDropdownValues > 0 then
                        return
                    end
                    RivalsRuntimeBridge.RefreshAutoLoadoutDropdownValues()
                    RivalsRuntimeBridge.QueueAutoLoadoutSubmission()
                end
                Toggles.P8S5T3:OnChanged(GuardRivalsCallback('AutoLoadout_PerMapChanged', RefreshAutoLoadoutProfile))
                Toggles.P8S5T4:OnChanged(GuardRivalsCallback('AutoLoadout_MultipleChanged', RefreshAutoLoadoutProfile))
                Options.P8S5D7:OnChanged(GuardRivalsCallback('AutoLoadout_MapChanged', RefreshAutoLoadoutProfile))
                Options.P8S5D8:OnChanged(GuardRivalsCallback('AutoLoadout_PriorityChanged', RefreshAutoLoadoutProfile))

                P3S5:AddToggle('P8S5T2', {
                    Text = 'Auto Ban Weapons',
                    Default = false,
                    Tooltip = 'In ranked weapon-ban votes, submits the first available selected weapon for each ban round.',
                })
                local DepAutoBan = P3S5:AddDependencyBox()
                DepAutoBan:AddDropdown('P8S5D5', {
                    Values = RivalsRuntimeBridge.ResolveAutoBanWeaponValues(),
                    Default = {},
                    Multi = true,
                    Text = 'First Ban',
                    Searchable = true,
                    MaxVisibleDropdownItems = 12,
                })
                DepAutoBan:AddDropdown('P8S5D6', {
                    Values = RivalsRuntimeBridge.ResolveAutoBanWeaponValues(),
                    Default = {},
                    Multi = true,
                    Text = 'Second Ban',
                    Searchable = true,
                    MaxVisibleDropdownItems = 12,
                })
                DepAutoBan:SetupDependencies({{ Toggles.P8S5T2, true }})

                Toggles.P8S5T2:OnChanged(GuardRivalsCallback('AutoBan_ToggleChanged', function(value)
                    RivalsRuntimeBridge.RegisterAutoBanSignals()
                    if value then
                        RivalsRuntimeBridge.TryAutoBanVote()
                    end
                end))
                for _, optionId in ipairs({'P8S5D5', 'P8S5D6'}) do
                    Options[optionId]:OnChanged(GuardRivalsCallback(string.format('AutoBan_%s_Changed', optionId), function()
                        RivalsRuntimeBridge.TryAutoBanVote()
                    end))
                end

                local P3S7 = AutoRightTabbox:AddTab('Auto Vote')
                P3S7:AddToggle('P8S5T5', {
                    Text = 'Auto Vote Maps',
                    Default = false,
                    Tooltip = 'Votes for the first selected map offered by the live duel vote.',
                })
                local DepAutoVote = P3S7:AddDependencyBox()
                DepAutoVote:AddDropdown('P8S5D9', {
                    Values = RivalsRuntimeBridge.ResolveAutoVoteMapValues(),
                    Default = {},
                    Multi = true,
                    Text = 'Maps',
                    Searchable = true,
                    MaxVisibleDropdownItems = 12,
                })
                DepAutoVote:SetupDependencies({{ Toggles.P8S5T5, true }})
                Toggles.P8S5T5:OnChanged(GuardRivalsCallback('AutoVote_ToggleChanged', function()
                    RivalsRuntimeBridge.RegisterAutoBanSignals()
                    RivalsRuntimeBridge.TryAutoBanVote()
                end))
                Options.P8S5D9:OnChanged(GuardRivalsCallback('AutoVote_MapsChanged', function()
                    RivalsRuntimeBridge.TryAutoBanVote()
                end))

                local P3S6 = AutoRightTabbox:AddTab('Auto Queue')

                P3S6:AddDropdown('P8S6D1', {
                    Values = RivalsRuntimeBridge.ResolveAutoQueueModeValues(),
                    Default = '1v1',
                    Multi = false,
                    Text = 'Mode',
                    Tooltip = 'Game mode to auto-queue into, including released matchmaking, rotating, and arcade modes.',
                })

                P3S6:AddToggle('P8S6T1', {
                    Text = 'Auto Queue',
                    Default = false,
                    Tooltip = 'Joins the selected mode and re-queues automatically after each match.',
                })

                Toggles.P8S6T1:OnChanged(GuardRivalsCallback('AutoQueue_ToggleChanged', function(value)
                    RivalsRuntimeBridge.OnAutoQueueToggled(value)
                end))

                Options.P8S6D1:OnChanged(GuardRivalsCallback('AutoQueue_ModeChanged', function()
                    RivalsRuntimeBridge.OnAutoQueueModeChanged()
                end))

                return P3
            end

