                        DepthOfField = { Enabled = true, FocusDistance = 35, InFocusRadius = 20, NearIntensity = 0.12, FarIntensity = 0.45 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 0.6, EnvironmentSpecularScale = 1.3, ShadowSoftness = 0.1, GlobalShadows = true },
                    },
                    ['RTX Realistic'] = {
                        Bloom = { Intensity = 0.65, Size = 28, Threshold = 0.88 },
                        ColorCorrection = { Brightness = 0.02, Contrast = 0.28, Saturation = 0.2, TintColor = Color3.fromRGB(255, 252, 248) },
                        SunRays = { Intensity = 0.35, Spread = 0.85 },
                        DepthOfField = { Enabled = true, FocusDistance = 45, InFocusRadius = 25, NearIntensity = 0.08, FarIntensity = 0.3 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 1, EnvironmentSpecularScale = 1, ShadowSoftness = 0.2, GlobalShadows = true },
                    },
                    ['Cinematic Film'] = {
                        Bloom = { Intensity = 0.45, Size = 32, Threshold = 0.9 },
                        ColorCorrection = { Brightness = -0.02, Contrast = 0.38, Saturation = -0.05, TintColor = Color3.fromRGB(255, 245, 235) },
                        SunRays = { Intensity = 0.4, Spread = 0.9 },
                        DepthOfField = { Enabled = true, FocusDistance = 35, InFocusRadius = 20, NearIntensity = 0.15, FarIntensity = 0.45 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 0.8, EnvironmentSpecularScale = 0.9, ShadowSoftness = 0.3, GlobalShadows = true },
                    },
                    ['Vibrant / Neon'] = {
                        Bloom = { Intensity = 1.25, Size = 42, Threshold = 0.8 },
                        ColorCorrection = { Brightness = 0.04, Contrast = 0.32, Saturation = 0.7, TintColor = Color3.fromRGB(255, 255, 255) },
                        SunRays = { Intensity = 0.5, Spread = 0.95 },
                        DepthOfField = { Enabled = false, FocusDistance = 50, InFocusRadius = 30, NearIntensity = 0, FarIntensity = 0 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 1, EnvironmentSpecularScale = 1, ShadowSoftness = 0.1, GlobalShadows = true },
                    },
                    ['Cyberpunk Night'] = {
                        Bloom = { Intensity = 1.45, Size = 38, Threshold = 0.75 },
                        ColorCorrection = { Brightness = -0.05, Contrast = 0.45, Saturation = 0.42, TintColor = Color3.fromRGB(225, 230, 255) },
                        SunRays = { Intensity = 0.25, Spread = 0.7 },
                        DepthOfField = { Enabled = true, FocusDistance = 40, InFocusRadius = 20, NearIntensity = 0.12, FarIntensity = 0.38 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 0.6, EnvironmentSpecularScale = 1.2, ShadowSoftness = 0.1, GlobalShadows = true },
                    },
                    ['Summer Sunshine'] = {
                        Bloom = { Intensity = 0.85, Size = 30, Threshold = 0.85 },
                        ColorCorrection = { Brightness = 0.06, Contrast = 0.22, Saturation = 0.35, TintColor = Color3.fromRGB(255, 250, 235) },
                        SunRays = { Intensity = 0.65, Spread = 1 },
                        DepthOfField = { Enabled = false, FocusDistance = 50, InFocusRadius = 30, NearIntensity = 0, FarIntensity = 0 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 1, EnvironmentSpecularScale = 1, ShadowSoftness = 0.25, GlobalShadows = true },
                    },
                    ['Soft Pastel'] = {
                        Bloom = { Intensity = 0.95, Size = 48, Threshold = 0.82 },
                        ColorCorrection = { Brightness = 0.08, Contrast = 0.08, Saturation = 0.22, TintColor = Color3.fromRGB(255, 240, 250) },
                        SunRays = { Intensity = 0.45, Spread = 0.9 },
                        DepthOfField = { Enabled = true, FocusDistance = 30, InFocusRadius = 15, NearIntensity = 0.2, FarIntensity = 0.35 },
                        Blur = { Enabled = false, Size = 0 },
                        Lighting = { EnvironmentDiffuseScale = 1, EnvironmentSpecularScale = 0.8, ShadowSoftness = 0.5, GlobalShadows = true },
                    },
                },
                GetOrCreateEffect = function(self, className)
                    local effect = self.OwnedEffects[className]
                    if not effect or effect.Parent == nil then
                        effect = Instance.new(className)
                        effect.Name = 'AkiraShader_' .. className
                        pcall(function()
                            effect.Parent = game:GetService('Lighting')
                        end)
                        self.OwnedEffects[className] = effect
                    end
                    return effect
                end,
                DestroyEffect = function(self, className)
                    local effect = self.OwnedEffects[className]
                    self.OwnedEffects[className] = nil
                    if effect then
                        pcall(function() effect:Destroy() end)
                    end
                end,
                -- Coalesced entry point: bursts (slider drags, preset applies) collapse
                -- into a single deferred apply per frame instead of N heavy applies.
                Apply = function(self)
                    if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                        return
                    end
                    if self._ApplyScheduled then
                        self._ApplyDirty = true
                        return
                    end
                    self._ApplyScheduled = true
                    self._ApplyDirty = false
                    task.defer(function()
                        self._ApplyScheduled = false
                        self._ApplyDirty = false
                        pcall(self.ApplyNow, self)
                    end)
                end,
                ApplyNow = function(self)
                    if RivalsRuntimeBridge.RuntimeRefreshSuspended then
                        return
                    end
                    local lighting = game:GetService('Lighting')
                    local enabled = Toggles.Misc_ShadersEnabled and Toggles.Misc_ShadersEnabled.Value == true
                    if not enabled then
                        self:Restore()
                        return
                    end

                    if not self.OriginalLighting then
                        self.OriginalLighting = {
                            EnvironmentDiffuseScale = lighting.EnvironmentDiffuseScale,
                            EnvironmentSpecularScale = lighting.EnvironmentSpecularScale,
                            ShadowSoftness = lighting.ShadowSoftness,
                            GlobalShadows = lighting.GlobalShadows,
                        }
                    end

                    local worldVisuals = RivalsRuntimeBridge.WorldVisuals
                    local lightingGuard = worldVisuals and worldVisuals.LightingGuard
                    local lightingOwned = lightingGuard and lightingGuard.Overrides or nil

                    local presetName = Options.Misc_ShaderPreset and Options.Misc_ShaderPreset.Value or 'RTX Realistic'
                    local preset = (presetName ~= 'Custom') and self.Presets[presetName] or nil

                    local bloomInt = preset and preset.Bloom.Intensity or (Options.Misc_Shader_Bloom and Options.Misc_Shader_Bloom.Value or 0.65)
                    local bloomSz = preset and preset.Bloom.Size or 28
                    local bloomThresh = preset and preset.Bloom.Threshold or 0.88

                    local contrast = preset and preset.ColorCorrection.Contrast or (Options.Misc_Shader_Contrast and Options.Misc_Shader_Contrast.Value or 0.25)
                    local saturation = preset and preset.ColorCorrection.Saturation or (Options.Misc_Shader_Saturation and Options.Misc_Shader_Saturation.Value or 0.2)
                    local brightness = preset and preset.ColorCorrection.Brightness or (Options.Misc_Shader_Brightness and Options.Misc_Shader_Brightness.Value or 0.02)
                    local tint = preset and preset.ColorCorrection.TintColor or (Options.Misc_Shader_Tint and Options.Misc_Shader_Tint.Value or Color3.fromRGB(255, 255, 255))

                    local raysInt = preset and preset.SunRays.Intensity or (Options.Misc_Shader_SunRays and Options.Misc_Shader_SunRays.Value or 0.35)
                    local raysSpread = preset and preset.SunRays.Spread or 0.85

                    local dofOn = preset and preset.DepthOfField.Enabled or (Toggles.Misc_Shader_DoF and Toggles.Misc_Shader_DoF.Value == true)
                    local dofDist = preset and preset.DepthOfField.FocusDistance or (Options.Misc_Shader_DofDist and Options.Misc_Shader_DofDist.Value or 40)
                    local dofRadius = preset and preset.DepthOfField.InFocusRadius or (Options.Misc_Shader_DofRadius and Options.Misc_Shader_DofRadius.Value or 25)
                    local dofNear = preset and preset.DepthOfField.NearIntensity or 0.08
                    local dofFar = preset and preset.DepthOfField.FarIntensity or 0.32

                    local blurOn = preset and preset.Blur.Enabled or (Toggles.Misc_Shader_MotionBlur and Toggles.Misc_Shader_MotionBlur.Value == true)
                    local blurSize = preset and preset.Blur.Size or (Options.Misc_Shader_BlurSize and Options.Misc_Shader_BlurSize.Value or 3)

                    local realLight = preset and preset.Lighting or (Toggles.Misc_Shader_RealLighting and Toggles.Misc_Shader_RealLighting.Value == true and {
                        EnvironmentDiffuseScale = 1,
                        EnvironmentSpecularScale = 1,
                        ShadowSoftness = 0.2,
                        GlobalShadows = true,
                    } or nil)

                    -- Bloom
                    local bloom = self:GetOrCreateEffect('BloomEffect')
                    bloom.Enabled = true
                    bloom.Intensity = bloomInt
                    bloom.Size = bloomSz
                    bloom.Threshold = bloomThresh

                    -- ColorCorrection
                    local cc = self:GetOrCreateEffect('ColorCorrectionEffect')
                    cc.Enabled = true
                    cc.Brightness = brightness
                    cc.Contrast = contrast
                    cc.Saturation = saturation
                    cc.TintColor = tint

                    -- SunRays
                    local rays = self:GetOrCreateEffect('SunRaysEffect')
                    rays.Enabled = true
                    rays.Intensity = raysInt
                    rays.Spread = raysSpread

                    -- DepthOfField
                    if dofOn then
                        local dof = self:GetOrCreateEffect('DepthOfFieldEffect')
                        dof.Enabled = true
                        dof.FocusDistance = dofDist
                        dof.InFocusRadius = dofRadius
                        dof.NearIntensity = dofNear
                        dof.FarIntensity = dofFar
                    else
                        self:DestroyEffect('DepthOfFieldEffect')
                    end

                    -- Blur
                    if blurOn and blurSize > 0 then
                        local blur = self:GetOrCreateEffect('BlurEffect')
                        blur.Enabled = true
                        blur.Size = blurSize
                    else
                        self:DestroyEffect('BlurEffect')
                    end

                    -- Lighting / PBR
                    if realLight then
                        pcall(function()
                            if not (lightingOwned and lightingOwned.EnvironmentDiffuseScale ~= nil) then
                                lighting.EnvironmentDiffuseScale = realLight.EnvironmentDiffuseScale or 1
                            end
                            if not (lightingOwned and lightingOwned.EnvironmentSpecularScale ~= nil) then
                                lighting.EnvironmentSpecularScale = realLight.EnvironmentSpecularScale or 1
                            end
                            if not (lightingOwned and lightingOwned.ShadowSoftness ~= nil) then
                                lighting.ShadowSoftness = realLight.ShadowSoftness or 0.2
                            end
                            if not (lightingOwned and lightingOwned.GlobalShadows ~= nil) then
                                lighting.GlobalShadows = realLight.GlobalShadows ~= false
                            end
                        end)
                    end
                end,
                Restore = function(self)
                    for className in pairs(self.OwnedEffects) do
                        self:DestroyEffect(className)
                    end
                    local lighting = game:GetService('Lighting')
                    if self.OriginalLighting then
                        pcall(function()
                            lighting.EnvironmentDiffuseScale = self.OriginalLighting.EnvironmentDiffuseScale or 0
                            lighting.EnvironmentSpecularScale = self.OriginalLighting.EnvironmentSpecularScale or 0
                            lighting.ShadowSoftness = self.OriginalLighting.ShadowSoftness or 0.5
                            lighting.GlobalShadows = self.OriginalLighting.GlobalShadows ~= false
                        end)
                        self.OriginalLighting = nil
                    end
                end,
            }

            RivalsUIBuilders.BuildRivalsMiscUi = function(Window)
            task.wait()
                local MovementTab = Window:AddTab('Movement', 'move')
                local P10 = Window:AddTab('Misc', 'package')
                task.wait()
                local RIVALS_REWARD_CLAIM_DELAY = 0.2
                local RIVALS_REWARD_SETTLE_DELAY = 0.6
                local RIVALS_REWARD_EMPTY_CONFIRMATIONS = 3

                local function ClaimAllRivalsBundle()
                    local pdc = ResolvePlayerDataController()
                    if not pdc or not IsPlayerDataControllerReady() then
                        Library:Notify({ Title = 'RIVALS', Description = 'Player data not ready yet, try again in a moment.', Time = 3 })
                        return
                    end

                    local DAILY_REWARDS = {
                        { remote = 'ClaimLikeReward',          flag = 'ClaimedLikeReward' },
                        { remote = 'ClaimFavoriteReward',      flag = 'ClaimedFavoriteReward' },
                        { remote = 'ClaimNotificationsReward', flag = 'ClaimedNotificationsReward' },
                    }
                    local dailyClaimed, dailySkippedAlready = 0, 0
                    for _, info in ipairs(DAILY_REWARDS) do
                        if pdc:Get(info.flag) then
                            dailySkippedAlready = dailySkippedAlready + 1
                        else
                            local r = ResolveRivalsDataRemote(info.remote, 'RemoteEvent')
                            if r then
                                local ok = pcall(r.FireServer, r)
                                if ok then
                                    dailyClaimed = dailyClaimed + 1
                                    task.wait(RIVALS_REWARD_CLAIM_DELAY)
                                end
                            end
                        end
                    end

                    local passClaimed = 0
                    local passNotActive, passNoProgress = false, false
                    do
                        local passRemote = ResolveRivalsDataRemote('ClaimBattlePassReward', 'RemoteEvent')
                        if passRemote then
                            local modulesFolder = ReplicatedStorage:FindFirstChild('Modules')
                            local seasonLibraryModule = modulesFolder and modulesFolder:FindFirstChild('SeasonLibrary')
                            if seasonLibraryModule then
                                local okSeason, seasonLibrary = pcall(require, seasonLibraryModule)
                                if okSeason and type(seasonLibrary) == 'table' and type(seasonLibrary.CurrentSeason) == 'table' then
                                    local currentSeason = seasonLibrary.CurrentSeason
                                    if not currentSeason.BattlePassActive then
                                        passNotActive = true
                                    else
                                        local seasons = pdc:Get('Seasons')
                                        local seasonData = type(seasons) == 'table' and currentSeason.Name and seasons[currentSeason.Name] or nil
                                        local battlePass = type(seasonData) == 'table' and seasonData.BattlePass or nil
                                        if type(battlePass) ~= 'table' then
                                            passNoProgress = true
                                        else
                                            local passLevel = tonumber(battlePass.PassLevel) or 0
                                            local maxTrack = tonumber(battlePass.MaxPassTrackNum) or 0
                                            local rewardsClaimed = type(battlePass.RewardsClaimed) == 'table' and battlePass.RewardsClaimed or {}
                                            local rewardsCatalog = type(currentSeason.BattlePassRewards) == 'table' and currentSeason.BattlePassRewards or {}
                                            for tier = 1, passLevel do
                                                local tierCatalog = rewardsCatalog[tier]
                                                if type(tierCatalog) == 'table' then
                                                    local claimedTier = rewardsClaimed[tostring(tier)]
                                                    for track = 1, maxTrack do
                                                        if tierCatalog[track] ~= nil then
                                                            local already = type(claimedTier) == 'table' and claimedTier[tostring(track)]
                                                            if not already then
                                                                local ok = pcall(passRemote.FireServer, passRemote, tier, track)
                                                                if ok then
                                                                    passClaimed = passClaimed + 1
                                                                    task.wait(RIVALS_REWARD_CLAIM_DELAY)
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end

                    local capsuleClaimed = 0
                    local capsuleSkippedDuel = false
                    local duelState = FighterDataCache.LocalDuel
                    if duelState and (duelState.IsInDuel or duelState.IsInShootingRange) then
                        capsuleSkippedDuel = true
                    else
                        local capsuleRemote = ResolveRivalsDataRemote('UseUnclaimedReward', 'RemoteFunction')
                        if capsuleRemote then
                            local maxQty = 99
                            local modulesFolder = ReplicatedStorage:FindFirstChild('Modules')
                            local constantsModule = modulesFolder and modulesFolder:FindFirstChild('CONSTANTS')
                            if constantsModule then
                                local okC, constants = pcall(require, constantsModule)
                                if okC and type(constants) == 'table' and type(constants.MAX_BACKPACK_USE_QUANTITY) == 'number' then
                                    maxQty = constants.MAX_BACKPACK_USE_QUANTITY
                                end
                            end

                            local emptyStreak = 0
                            local failureStreak = 0
                            for _ = 1, 400 do
                                local rewards = pdc:Get('UnclaimedRewards')
                                if type(rewards) ~= 'table' or rewards[1] == nil then
                                    emptyStreak = emptyStreak + 1
                                    if emptyStreak >= RIVALS_REWARD_EMPTY_CONFIRMATIONS then break end
                                    task.wait(RIVALS_REWARD_SETTLE_DELAY)
                                else
                                    emptyStreak = 0
                                    local entry = rewards[1]
                                    local startQty = type(entry) == 'table' and tonumber(entry.Quantity) or 1
                                    if not startQty or startQty < 1 then startQty = 1 end
                                    local useQty = math.min(startQty, maxQty)

                                    local ok, result = pcall(capsuleRemote.InvokeServer, capsuleRemote, 1, useQty)
                                    if ok and result == 'Success' then
                                        capsuleClaimed = capsuleClaimed + 1
                                        failureStreak = 0
                                    else
                                        failureStreak = failureStreak + 1
                                        if failureStreak >= 5 then break end
                                    end

                                    task.wait(RIVALS_REWARD_CLAIM_DELAY)
                                end
                            end
                        end
                    end

                    local parts = {}
                    if dailyClaimed > 0 then table.insert(parts, string.format('%d daily', dailyClaimed)) end
                    if capsuleClaimed > 0 then table.insert(parts, string.format('%d capsule%s', capsuleClaimed, capsuleClaimed == 1 and '' or 's')) end
                    if passClaimed > 0 then table.insert(parts, string.format('%d pass tier%s', passClaimed, passClaimed == 1 and '' or 's')) end

                    local desc
                    if #parts > 0 then
                        desc = 'Claimed ' .. table.concat(parts, ', ') .. '.'
                        if capsuleSkippedDuel then desc = desc .. ' Capsules skipped (in duel/range).' end
                    elseif capsuleSkippedDuel then
                        desc = 'Capsules skipped (in duel/range). Nothing else to claim.'
                    elseif dailySkippedAlready == 3 and not passNotActive and not passNoProgress then
                        desc = 'Already up to date - nothing to claim.'
                    elseif dailySkippedAlready == 3 then
                        desc = 'Daily rewards already claimed - nothing else to claim right now.'
                    else
                        desc = 'Nothing to claim.'
                    end

                    Library:Notify({ Title = 'RIVALS', Description = desc, Time = 4 })
                end

                local playerSpooferLabels = {
                    Name = 'Name Spoofer',
                    Winstreak = 'Win Streak',
                    Level = 'Level',
                    RankedElo = 'Ranked ELO',
                    NametagStatus = 'Nametag Status',
                    Influencer = 'Influencer',
                    RobloxEmployee = 'Roblox Employee',
                    Premium = 'Premium',
                    Verified = 'Verified Badge',
                    NosniyTeam = "Nosniy's Team",
                }
                local playerSpooferScopes = {
                    { suffix = 'You', title = 'Player Spoofer (You)', side = 'Left' },
                    { suffix = 'Oth', title = 'Player Spoofer (Others)', side = 'Right' },
                }
                for _, scope in ipairs(playerSpooferScopes) do
                    local spooferGroup = scope.side == 'Left'
                        and P10:AddLeftGroupbox(scope.title)
                        or P10:AddRightGroupbox(scope.title)
                    for _, field in ipairs(RivalsRuntimeBridge.PlayerSpoofer.AttributeFields) do
                        local toggleId = 'PSpoof' .. scope.suffix .. field.key .. 'T'
                        local toggle = spooferGroup:AddToggle(toggleId, {
                            Text = playerSpooferLabels[field.key],
                            Default = false,
                        })
                        toggle:OnChanged(GuardRivalsCallback(
                            'PlayerSpoofer_Toggle', RivalsRuntimeBridge.PlayerSpoofer.RefreshAll))
                        if field.control ~= 'const' then
                            local valueId = 'PSpoof' .. scope.suffix .. field.key .. 'V'
                            local default = scope.suffix == 'You' and field.youDefault or field.othDefault
                            local valueBox = spooferGroup:AddDependencyBox()
                            valueBox:AddInput(valueId, {
                                Text = 'Value',
                                Default = default,
                                AllowEmpty = true,
                                EmptyReset = '',
                            })
                            Options[valueId]:OnChanged(GuardRivalsCallback(
                                'PlayerSpoofer_Value', RivalsRuntimeBridge.PlayerSpoofer.RefreshAll))
                            valueBox:SetupDependencies({{ Toggles[toggleId], true }})
                        end
                    end
                end

                                local ShadersGroup = P10:AddRightGroupbox('Shaders')
                local shaderToggle = ShadersGroup:AddToggle('Misc_ShadersEnabled', {
                    Text = 'Enable Shaders',
                    Default = false,
                    Tooltip = 'Enables high-fidelity post-processing shaders, bloom, depth of field, and lighting enhancements.',
                })
                shaderToggle:OnChanged(function()
                    RivalsRuntimeBridge.MiscShaders:Apply()
                end)

                local ShaderDepBox = ShadersGroup:AddDependencyBox()
                local isUpdatingPreset = false
                local presetDropdown = ShaderDepBox:AddDropdown('Misc_ShaderPreset', {
                    Values = { 'Silent Hill / Dark Torrent', 'RTX Realistic', 'Cinematic Film', 'Vibrant / Neon', 'Cyberpunk Night', 'Summer Sunshine', 'Soft Pastel', 'Custom' },
                    Default = 'RTX Realistic',
                    Multi = false,
                    Text = 'Shader Preset',
                    Tooltip = 'Choose a premade shader look or select Custom to tweak below.',
                })
                presetDropdown:OnChanged(function(val)
                    local p = RivalsRuntimeBridge.MiscShaders.Presets[val]
                    if p then
                        isUpdatingPreset = true
                        if Options.Misc_Shader_Bloom then Options.Misc_Shader_Bloom:SetValue(p.Bloom.Intensity) end
                        if Options.Misc_Shader_Contrast then Options.Misc_Shader_Contrast:SetValue(p.ColorCorrection.Contrast) end
                        if Options.Misc_Shader_Saturation then Options.Misc_Shader_Saturation:SetValue(p.ColorCorrection.Saturation) end
                        if Options.Misc_Shader_Brightness then Options.Misc_Shader_Brightness:SetValue(p.ColorCorrection.Brightness) end
                        if Options.Misc_Shader_Tint and p.ColorCorrection.TintColor then Options.Misc_Shader_Tint:SetValueRGB(p.ColorCorrection.TintColor) end
                        if Options.Misc_Shader_SunRays then Options.Misc_Shader_SunRays:SetValue(p.SunRays.Intensity) end
                        if Toggles.Misc_Shader_DoF then Toggles.Misc_Shader_DoF:SetValue(p.DepthOfField.Enabled) end
                        if Options.Misc_Shader_DofDist and p.DepthOfField.FocusDistance then Options.Misc_Shader_DofDist:SetValue(p.DepthOfField.FocusDistance) end
                        if Options.Misc_Shader_DofRadius and p.DepthOfField.InFocusRadius then Options.Misc_Shader_DofRadius:SetValue(p.DepthOfField.InFocusRadius) end
                        if Toggles.Misc_Shader_MotionBlur then Toggles.Misc_Shader_MotionBlur:SetValue(p.Blur.Enabled) end
                        if Options.Misc_Shader_BlurSize and p.Blur.Size then Options.Misc_Shader_BlurSize:SetValue(p.Blur.Size) end
                        if Toggles.Misc_Shader_RealLighting then Toggles.Misc_Shader_RealLighting:SetValue(p.Lighting ~= nil) end
                        isUpdatingPreset = false
                    end
                    RivalsRuntimeBridge.MiscShaders:Apply()
                end)

                local function BindShaderControl(ctrl)
                    if ctrl and type(ctrl.OnChanged) == 'function' then
                        ctrl:OnChanged(function()
                            if not isUpdatingPreset and Options.Misc_ShaderPreset and Options.Misc_ShaderPreset.Value ~= 'Custom' then
                                Options.Misc_ShaderPreset:SetValue('Custom')
                            end
                            RivalsRuntimeBridge.MiscShaders:Apply()
                        end)
                    end
                    return ctrl
                end

                BindShaderControl(ShaderDepBox:AddSlider('Misc_Shader_Bloom', {
                    Text = 'Bloom Intensity', Default = 0.65, Min = 0, Max = 3, Rounding = 2,
                }))
                BindShaderControl(ShaderDepBox:AddSlider('Misc_Shader_Contrast', {
                    Text = 'Contrast', Default = 0.28, Min = -0.5, Max = 1.5, Rounding = 2,
                }))
                BindShaderControl(ShaderDepBox:AddSlider('Misc_Shader_Saturation', {
                    Text = 'Saturation', Default = 0.2, Min = -1, Max = 2, Rounding = 2,
                }))
                BindShaderControl(ShaderDepBox:AddSlider('Misc_Shader_Brightness', {
                    Text = 'Brightness', Default = 0.02, Min = -0.5, Max = 0.5, Rounding = 2,
                }))
                BindShaderControl(ShaderDepBox:AddLabel('Color Tint'):AddColorPicker('Misc_Shader_Tint', {
                    Default = Color3.fromRGB(255, 252, 248), Title = 'Shader Tint Color',
                }))
                BindShaderControl(ShaderDepBox:AddSlider('Misc_Shader_SunRays', {
                    Text = 'SunRays Intensity', Default = 0.35, Min = 0, Max = 1, Rounding = 2,
                }))

                local dofToggle = BindShaderControl(ShaderDepBox:AddToggle('Misc_Shader_DoF', {
                    Text = 'Depth of Field', Default = false,
                    Tooltip = 'Realistic camera focus blur (Bokeh / Tilt Shift).',
                }))
                local DofBox = ShaderDepBox:AddDependencyBox()
                BindShaderControl(DofBox:AddSlider('Misc_Shader_DofDist', {
                    Text = 'Focus Distance', Default = 45, Min = 5, Max = 250, Rounding = 0,
                }))
                BindShaderControl(DofBox:AddSlider('Misc_Shader_DofRadius', {
                    Text = 'In Focus Radius', Default = 25, Min = 5, Max = 100, Rounding = 0,
                }))
                DofBox:SetupDependencies({{ Toggles.Misc_Shader_DoF, true }})

                local blurToggle = BindShaderControl(ShaderDepBox:AddToggle('Misc_Shader_MotionBlur', {
                    Text = 'Motion / Soft Blur', Default = false,
                    Tooltip = 'Adds soft cinematic screen blur.',
                }))
                local BlurBox = ShaderDepBox:AddDependencyBox()
                BindShaderControl(BlurBox:AddSlider('Misc_Shader_BlurSize', {
                    Text = 'Blur Amount', Default = 3, Min = 1, Max = 20, Rounding = 0,
                }))
                BlurBox:SetupDependencies({{ Toggles.Misc_Shader_MotionBlur, true }})

                BindShaderControl(ShaderDepBox:AddToggle('Misc_Shader_RealLighting', {
                    Text = 'Enhanced Lighting & PBR', Default = false,
                    Tooltip = 'Enables high specular/diffuse reflections and soft dynamic shadows.',
                }))
                ShaderDepBox:SetupDependencies({{ Toggles.Misc_ShadersEnabled, true }})
                task.wait()

                local P10S1 = P10:AddLeftGroupbox('Rewards')
                P10S1:AddButton({
                    Text = 'Claim All',
