            RivalsUIBuilders.BuildRivalsSearchUi = function(Window)
                local skipFlags = {
                    FeatureSearchQuery = true,
                    FeatureSearchCategory = true,
                    FeatureSearchResults = true,
                }
                local allFeatures = {}

                local function refreshCatalog()
                    table.clear(allFeatures)
                    local seen = {}
                    if type(Toggles) == 'table' then
                        for flag, toggle in pairs(Toggles) do
                            local name = toggle.FeatureName or toggle.Text or flag
                            if type(name) == 'string' and #name > 0 and not skipFlags[flag] and not seen[flag] then
                                seen[flag] = true
                                table.insert(allFeatures, {
                                    Name = name,
                                    Tab = toggle.FeatureTab or 'Misc',
                                    Box = toggle.FeatureBox or 'General',
                                })
                            end
                        end
                    end
                    if type(Options) == 'table' then
                        for flag, option in pairs(Options) do
                            local name = option.FeatureName or option.Text or flag
                            if type(name) == 'string' and #name > 0 and not skipFlags[flag] and not seen[flag] then
                                seen[flag] = true
                                table.insert(allFeatures, {
                                    Name = name,
                                    Tab = option.FeatureTab or 'Misc',
                                    Box = option.FeatureBox or 'General',
                                })
                            end
                        end
                    end
                    table.sort(allFeatures, function(a, b)
                        if a.Tab == b.Tab then
                            return string.lower(a.Name) < string.lower(b.Name)
                        end
                        return string.lower(a.Tab) < string.lower(b.Tab)
                    end)
                end

                local function bindSearch(handler)
                    if type(Window.SetSearchHandler) == 'function' then
                        Window.SetSearchHandler(handler)
                    elseif type(Window.Items) == 'table' and Window.Items.SearchBox then
                        Window.SearchHandler = handler
                    end
                end

                bindSearch(function(query)
                    refreshCatalog()
                    query = string.lower(string.gsub(tostring(query or ''), '^%s*(.-)%s*$', '%1'))
                    if query == '' then
                        return {}
                    end
                    local matches = {}
                    for _, feat in ipairs(allFeatures) do
                        local name = string.lower(feat.Name)
                        local box = string.lower(feat.Box or '')
                        local tab = string.lower(feat.Tab or '')
                        if string.find(name, query, 1, true) or string.find(box, query, 1, true) or string.find(tab, query, 1, true) then
                            table.insert(matches, {
                                Name = feat.Name,
                                Detail = string.format('%s  ·  %s', feat.Tab, feat.Box),
                                Tab = feat.Tab,
                                OnSelect = function()
                                    pcall(function()
                                        Window:SelectTab(feat.Tab)
                                    end)
                                end,
                            })
                            if #matches >= 8 then
                                break
                            end
                        end
                    end
                    return matches
                end)
            end

            local function BuildSkinsSection(skinsTab)
                        -- Skin Changer UI (ripped from Skin changer.lua)
                        local SC_selWeapon = 'All'
                        local SC_selSkin = 'Randomize All'
                        local SC_selWrap = 'None'
                        local SC_selCharm = 'None'
                        local SC_selFinisher = 'None'
                        local SC_selCustomWeapon = SC_WeaponList[2] or 'All'
                        local SC_selCustomSkin = 'None'

                        local SkinsLeftBox = skinsTab:AddLeftGroupbox('skins')
                        local SkinsRightBox = skinsTab:AddRightGroupbox('options')

                        SkinsLeftBox:AddDropdown('SC_SelectWeapon', {
                            Values = SC_WeaponList, Default = 1, Multi = false, Text = 'weapon'
                        })
                        SkinsLeftBox:AddDropdown('SC_SelectSkin', {
                            Values = SC_GetSkinsForWeapon(SC_selWeapon), Default = 1, Multi = false, Text = 'skin'
                        })
                        SkinsLeftBox:AddDropdown('SC_SelectWrap', {
                            Values = SC_WrapsData, Default = 1, Multi = false, Text = 'wrap'
                        })
                        SkinsLeftBox:AddDropdown('SC_SelectCharm', {
                            Values = SC_CharmsData, Default = 1, Multi = false, Text = 'charm'
                        })
                        SkinsLeftBox:AddDropdown('SC_SelectFinisher', {
                            Values = SC_FinishersData, Default = 1, Multi = false, Text = 'finisher'
                        })

                        Options.SC_SelectWeapon:OnChanged(function()
                            SC_selWeapon = Options.SC_SelectWeapon.Value
                            local skins = SC_GetSkinsForWeapon(SC_selWeapon)
                            SC_selSkin = skins[1] or 'None'
                            if Options.SC_SelectSkin then
                                Options.SC_SelectSkin:SetValues(skins)
                                Options.SC_SelectSkin:SetValue(SC_selSkin)
                            end
                        end)
                        Options.SC_SelectSkin:OnChanged(function() SC_selSkin = Options.SC_SelectSkin.Value end)
                        Options.SC_SelectWrap:OnChanged(function() SC_selWrap = Options.SC_SelectWrap.Value end)
                        Options.SC_SelectCharm:OnChanged(function() SC_selCharm = Options.SC_SelectCharm.Value end)
                        Options.SC_SelectFinisher:OnChanged(function() SC_selFinisher = Options.SC_SelectFinisher.Value end)

                        SkinsLeftBox:AddButton({
                            Text = 'apply',
                            Func = function()
                                local isAll = (SC_selWeapon == 'All')
                                local targets = {}
                                if isAll then for wName, _ in pairs(SC_WeaponsData) do table.insert(targets, wName) end
                                else table.insert(targets, SC_selWeapon) end
                                task.spawn(function()
                                    SC_BeginBatch()
                                    for _, wName in ipairs(targets) do
                                        if SC_selSkin == 'Randomize All' then
                                            local s = SC_WeaponsData[wName] or {}
                                            if #s > 0 then SC_EquipCosmetic(wName, 'Skin', s[math.random(1,#s)], true) end
                                        elseif SC_selSkin and SC_selSkin ~= 'No Skins Found' and SC_selSkin ~= 'None' then
                                            local s = SC_WeaponsData[wName] or {}
                                            if table.find(s, SC_selSkin) then SC_EquipCosmetic(wName, 'Skin', SC_selSkin, true) end
                                        elseif SC_selSkin == 'None' then
                                            SC_EquipCosmetic(wName, 'Skin', 'None', true)
                                        end
                                        if SC_selWrap and SC_selWrap ~= 'None' then
                                            SC_EquipCosmetic(wName, 'Wrap', SC_selWrap, true)
                                        elseif SC_selWrap == 'None' and not isAll then
                                            SC_EquipCosmetic(wName, 'Wrap', 'None', true)
                                        end
                                        if SC_selCharm and SC_selCharm ~= 'None' then
                                            SC_EquipCosmetic(wName, 'Charm', SC_selCharm, true)
                                        elseif SC_selCharm == 'None' and not isAll then
                                            SC_EquipCosmetic(wName, 'Charm', 'None', true)
                                        end
                                        if SC_selFinisher and SC_selFinisher ~= 'None' then
                                            SC_EquipCosmetic(wName, 'Finisher', SC_selFinisher, true)
                                        elseif SC_selFinisher == 'None' and not isAll then
                                            SC_EquipCosmetic(wName, 'Finisher', 'None', true)
                                        end
                                    end
                                    SC_EndBatch(true)
                                end)
                            end
                        })

                        SkinsLeftBox:AddButton({
                            Text = 'randomize weapon',
                            Func = function()
                                local isAll = (SC_selWeapon == 'All')
                                local targets = {}
