                        })

                        SkinsLeftBox:AddInput('SC_SearchSkins', {
                            Text = 'search', Placeholder = 'search skins, wraps, charms...',
                            Callback = function(txt)
                                local sl = txt:lower()
                                if sl == '' then
                                    if Options.SC_SelectWeapon then Options.SC_SelectWeapon:SetValues(SC_WeaponList) Options.SC_SelectWeapon:SetValue(SC_selWeapon) end
                                    if Options.SC_SelectSkin then Options.SC_SelectSkin:SetValues(SC_GetSkinsForWeapon(SC_selWeapon)) end
                                    if Options.SC_SelectWrap then Options.SC_SelectWrap:SetValues(SC_WrapsData) end
                                    if Options.SC_SelectCharm then Options.SC_SelectCharm:SetValues(SC_CharmsData) end
                                    if Options.SC_SelectFinisher then Options.SC_SelectFinisher:SetValues(SC_FinishersData) end
                                    if Options.SC_CustomSkinSelect then Options.SC_CustomSkinSelect:SetValues(SC_AllSkinsList) end
                                    return
                                end
                                local fw = {}
                                for _, w in ipairs(SC_WeaponList) do
                                    if w:lower():find(sl, 1, true) then table.insert(fw, w) end
                                end
                                for wt, skins in pairs(SC_WeaponsData) do
                                    for _, sk in ipairs(skins) do
                                        if sk:lower():find(sl, 1, true) and not table.find(fw, wt) then table.insert(fw, wt) end
                                    end
                                end
                                if #fw > 0 and Options.SC_SelectWeapon then
                                    Options.SC_SelectWeapon:SetValues(fw)
                                    SC_selWeapon = fw[1] Options.SC_SelectWeapon:SetValue(SC_selWeapon)
                                    if Options.SC_SelectSkin then
                                        local sk2 = SC_GetSkinsForWeapon(SC_selWeapon)
                                        Options.SC_SelectSkin:SetValues(sk2)
                                        SC_selSkin = sk2[1] or 'None' Options.SC_SelectSkin:SetValue(SC_selSkin)
                                    end
                                end
                            end
                        })

                        SkinsRightBox:AddButton({
                            Text = 'reset weapon',
                            Func = function()
                                task.spawn(function()
                                    SC_BeginBatch()
                                    if SC_selWeapon == 'All' then
                                        SC_equipped = {}
                                        if SC_SkinChanger and type(SC_SkinChanger.ResetAllWeapons) == 'function' then
                                            SC_SkinChanger:ResetAllWeapons()
                                        end
                                    else
                                        if SC_equipped[SC_selWeapon] then
                                            SC_equipped[SC_selWeapon] = nil
                                        end
                                        if SC_SkinChanger and type(SC_SkinChanger.ResetSkinModel) == 'function' then
                                            SC_SkinChanger:ResetSkinModel(SC_selWeapon)
                                        end
                                    end
                                    SC_EndBatch(true)
                                    if Options.SC_SelectWrap then Options.SC_SelectWrap:SetValue('None') end
                                    if Options.SC_SelectCharm then Options.SC_SelectCharm:SetValue('None') end
                                    if Options.SC_SelectFinisher then Options.SC_SelectFinisher:SetValue('None') end
                                    if Options.SC_CustomSkinSelect then Options.SC_CustomSkinSelect:SetValue('None') end
                                end)
                            end
                        })

                        SkinsRightBox:AddButton({
                            Text = 'reset all',
                            Func = function()
                                task.spawn(function()
                                    SC_BeginBatch()
                                    SC_equipped = {}
                                    if SC_SkinChanger and type(SC_SkinChanger.ResetAllWeapons) == 'function' then
                                        SC_SkinChanger:ResetAllWeapons()
                                    end
                                    SC_EndBatch(true)
                                    if Options.SC_SelectWrap then Options.SC_SelectWrap:SetValue('None') end
                                    if Options.SC_SelectCharm then Options.SC_SelectCharm:SetValue('None') end
                                    if Options.SC_SelectFinisher then Options.SC_SelectFinisher:SetValue('None') end
                                    if Options.SC_CustomSkinSelect then Options.SC_CustomSkinSelect:SetValue('None') end
                                end)
                            end
                        })

                        SkinsRightBox:AddDivider()

                        SkinsRightBox:AddButton({
                            Text = 'unlock all',
                            Func = function()
                                pcall(function()
                                    if SC_DataController and SC_DataController.CurrentData then
                                        local fighter = SC_FighterController and SC_FighterController:GetFighter(LP)
                                        if not fighter then
                                            SC_DataController.CurrentData:Replicate('WeaponInventory')
                                        end
                                        SC_DataController.CurrentData:Replicate('CosmeticInventory')
                                    end
                                end)
                            end
                        })

                        -- Custom skin browser
                        local CustomSkinBox = skinsTab:AddRightGroupbox('custom weapon skin')

                        CustomSkinBox:AddDropdown('SC_CustomWeaponSelect', {
                            Values = SC_WeaponList, Default = (#SC_WeaponList >= 2 and 2) or 1,
                            Multi = false, Text = 'weapon'
                        })
                        CustomSkinBox:AddDropdown('SC_CustomSkinSelect', {
                            Values = SC_AllSkinsList, Default = 1, Multi = false, Text = 'custom skin'
                        })

                        Options.SC_CustomWeaponSelect:OnChanged(function()
                            SC_selCustomWeapon = Options.SC_CustomWeaponSelect.Value
                        end)
                        Options.SC_CustomSkinSelect:OnChanged(function()
                            SC_selCustomSkin = Options.SC_CustomSkinSelect.Value
                        end)

                        CustomSkinBox:AddInput('SC_SearchCustomSkin', {
                            Text = 'search skin', Placeholder = 'search any skin...',
                            Callback = function(text)
                                local sl = text:lower()
                                if sl == '' then
                                    if Options.SC_CustomSkinSelect then
                                        Options.SC_CustomSkinSelect:SetValues(SC_AllSkinsList)
                                        Options.SC_CustomSkinSelect:SetValue(SC_AllSkinsList[1] or 'None')
                                    end
                                    return
                                end
                                local filtered = {'None'}
                                for _, s in ipairs(SC_AllSkinsList) do
                                    if s ~= 'None' and s:lower():find(sl, 1, true) then
                                        table.insert(filtered, s)
                                        if #filtered >= 200 then break end
                                    end
                                end
                                if Options.SC_CustomSkinSelect then
                                    Options.SC_CustomSkinSelect:SetValues(filtered)
                                    Options.SC_CustomSkinSelect:SetValue(#filtered > 1 and filtered[2] or 'None')
                                end
                            end
                        })

                        CustomSkinBox:AddButton({
                            Text = 'browse all skins',
                            Func = function()
                                SC_RebuildAllSkinsList()
                                if Options.SC_CustomSkinSelect then
                                    Options.SC_CustomSkinSelect:SetValues(SC_AllSkinsList)
                                    Options.SC_CustomSkinSelect:SetValue(SC_AllSkinsList[2] or 'None')
                                end
                            end
                        })

                        CustomSkinBox:AddButton({
                            Text = 'apply custom skin',
                            Func = function()
                                local wName = (Options.SC_CustomWeaponSelect and Options.SC_CustomWeaponSelect.Value) or SC_selCustomWeapon
                                local sName = (Options.SC_CustomSkinSelect and Options.SC_CustomSkinSelect.Value) or SC_selCustomSkin
                                if not wName then return end
                                task.spawn(function()
                                    SC_BeginBatch()
                                    if not sName or sName == 'None' or sName == '' then
                                        if wName == 'All' then
                                            for tw, _ in pairs(SC_WeaponsData) do
                                                SC_EquipCosmetic(tw, 'Skin', 'None', true)
                                            end
                                        else
                                            SC_EquipCosmetic(wName, 'Skin', 'None', true)
                                        end
                                        SC_EndBatch(true)
                                        return
                                    end
                                    local skinValid = SC_cloneCosmetic(sName, 'Skin') ~= nil
                                    if not skinValid then
                                        SC_EndBatch(false)
                                        return
                                    end
                                    if wName == 'All' then
                                        for tw, _ in pairs(SC_WeaponsData) do
                                            SC_EquipCosmetic(tw, 'Skin', sName, true)
                                        end
                                    else
                                        SC_EquipCosmetic(wName, 'Skin', sName, true)
                                    end
                                    SC_EndBatch(true)
                                end)
                            end
                        })

                        CustomSkinBox:AddButton({
                            Text = 'reset custom skin',
                            Func = function()
                                local wName = (Options.SC_CustomWeaponSelect and Options.SC_CustomWeaponSelect.Value) or SC_selCustomWeapon
                                if not wName then return end
                                task.spawn(function()
                                    SC_BeginBatch()
                                    if wName == 'All' then
                                        for tw, _ in pairs(SC_WeaponsData) do
                                            SC_EquipCosmetic(tw, 'Skin', 'None', true)
                                        end
                                    else
                                        SC_EquipCosmetic(wName, 'Skin', 'None', true)
                                    end
                                    SC_EndBatch(true)
                                    if Options.SC_CustomSkinSelect then Options.SC_CustomSkinSelect:SetValue('None') end
                                end)
                            end
                        })

                        -- Populate catalog dynamically after a delay
                        task.spawn(function()
                            task.wait(2)
                            if SC_CosmeticLibrary and SC_CosmeticLibrary.Cosmetics then
                                local wrapSet = {} for _, w in ipairs(SC_WrapsData) do wrapSet[w] = true end
                                local charmSet = {} for _, c in ipairs(SC_CharmsData) do charmSet[c] = true end
                                local finSet = {} for _, f in ipairs(SC_FinishersData) do finSet[f] = true end
                                local wSkinSets = {}
                                for wn, skins in pairs(SC_WeaponsData) do
                                    wSkinSets[wn] = {}
                                    for _, s in ipairs(skins) do wSkinSets[wn][s] = true end
                                end
                                local count = 0
                                for cosName, cosData in pairs(SC_CosmeticLibrary.Cosmetics) do
                                    if type(cosName) == 'string' and cosName ~= '' then
                                        local cType = cosData.Type
                                        if cType == 'Skin' and cosData.ItemName and type(cosData.ItemName) == 'string' then
                                            local iName = cosData.ItemName
                                            if not SC_WeaponsData[iName] then SC_WeaponsData[iName] = {} wSkinSets[iName] = {} end
                                            if not wSkinSets[iName][cosName] then
                                                wSkinSets[iName][cosName] = true table.insert(SC_WeaponsData[iName], cosName)
                                            end
                                        elseif cType == 'Wrap' and not wrapSet[cosName] then
                                            wrapSet[cosName] = true table.insert(SC_WrapsData, cosName)
                                        elseif cType == 'Charm' and not charmSet[cosName] then
                                            charmSet[cosName] = true table.insert(SC_CharmsData, cosName)
                                        elseif cType == 'Finisher' and not finSet[cosName] then
                                            finSet[cosName] = true table.insert(SC_FinishersData, cosName)
                                        end
                                    end
                                    count = count + 1
                                    if count % 60 == 0 then task.wait() end
                                end
                                SC_RebuildAllSkinsList()
                                -- Update dropdowns with richer data
                                local wList2 = {'All'}
                                local sw2 = {}
                                for wt, _ in pairs(SC_WeaponsData) do table.insert(sw2, wt) end
                                table.sort(sw2)
                                for _, w in ipairs(sw2) do table.insert(wList2, w) end
                                if Options.SC_SelectWeapon then Options.SC_SelectWeapon:SetValues(wList2) end
                                if Options.SC_CustomWeaponSelect then Options.SC_CustomWeaponSelect:SetValues(wList2) end
                                if Options.SC_SelectWrap then Options.SC_SelectWrap:SetValues(SC_WrapsData) end
                                if Options.SC_SelectCharm then Options.SC_SelectCharm:SetValues(SC_CharmsData) end
                                if Options.SC_SelectFinisher then Options.SC_SelectFinisher:SetValues(SC_FinishersData) end
                                if Options.SC_CustomSkinSelect then Options.SC_CustomSkinSelect:SetValues(SC_AllSkinsList) end
                            end
                        end)
            end

            RivalsUIBuilders.BuildRivalsUi = function(Window)
                RivalsRuntimeBridge.RuntimeRefreshSuspended = true
                local layoutSuspended = false
                local function suspendLayout()
                    if not layoutSuspended and Library and type(Library.SuspendLayout) == 'function' then
                        pcall(Library.SuspendLayout, Library)
                        layoutSuspended = true
                    end
                end
                local function resumeLayout()
                    if not layoutSuspended or not Library then
                        return
                    end
                    layoutSuspended = false
                    if type(Library.ResumeLayout) == 'function' then
                        pcall(Library.ResumeLayout, Library)
                    end
                end

                task.spawn(function()
                    if not __akira_boot_alive() then
                        return
                    end
                    -- Streamlined top-level tab structure (7 spacious, crisp tabs)
                    local aimbotTab = Window:AddTab('Aimbot', 'crosshair')
                    local rageTab = Window:AddTab('Rage', 'flame')
                    local espTab = Window:AddTab('ESP', 'eye')
                    local visualsTab = Window:AddTab('Visuals', 'camera')
                    local skinsTab = Window:AddTab('Skins', 'shirt')
                    local miscTab = Window:AddTab('Misc', 'package')

                    -- Setup tab aliases so legacy calls and searches route cleanly without extra tabs
                    Window.Tabs['HvH'] = rageTab
                    Window.Tabs['Crosshair'] = visualsTab
                    Window.Tabs['World'] = visualsTab
                    Window.Tabs['Movement'] = miscTab
                    Window.Tabs['Auto'] = miscTab
                    Window.Tabs['Debug'] = miscTab

                    suspendLayout()
                    if type(__akira_boot_status) == 'function' then
                        __akira_boot_status('Building tabs...')
                    end

                    local function runSection(name, fn)
                        if type(__akira_boot_log) == 'function' then
                            __akira_boot_log('Section ' .. name .. ': start')
                        end
                        if __akira_boot_alive() then
                            local ok, err = pcall(fn)
                            if not ok then ReportRivalsRuntimeIssue(name, err) end
                        end
                        if type(__akira_boot_log) == 'function' then
                            __akira_boot_log('Section ' .. name .. ': done')
                        end
                    end

                    -- Serial Loop 1: Aimbot UI
                    runSection('ui_Aimbot', function()
                        RivalsUIBuilders.BuildRivalsAimbotUi(Window)
                    end)

                    -- Serial Loop 2: Rage & Ragebot UI
                    runSection('ui_Rage', function()
                        RivalsUIBuilders.BuildRivalsModsUi(rageTab)
                    end)
                    runSection('ui_Ragebot', function()
                        RivalsUIBuilders.BuildRivalsRagebotUi(rageTab, rageTab)
                    end)

                    -- Serial Loop 3: ESP UI
                    runSection('ui_ESP', function()
                        RivalsUIBuilders.BuildRivalsEspUi(Window)
                    end)

                    -- Serial Loop 4: Visuals UI
                    runSection('ui_Visuals', function()
                        RivalsUIBuilders.BuildRivalsVisualsUi(Window)
                    end)

                    -- Serial Loop 5: Pickup UI
                    runSection('ui_Pickup', function()
                        RivalsUIBuilders.BuildRivalsPickupUi(Window)
                    end)

                    -- Serial Loop 6: Misc UI
                    runSection('ui_Misc', function()
                        RivalsUIBuilders.BuildRivalsMiscUi(Window)
                    end)

                    -- Serial Loop 7: Skins UI
                    runSection('ui_Skins', function()
                        BuildSkinsSection(skinsTab)
                    end)

                    if type(__akira_boot_log) == 'function' then
                        __akira_boot_log('Runtime: debug ui skipped (was 40s boot freeze)')
                    end

                    -- Build Search tab (indexes all newly created options)
                    if __akira_boot_alive() then
                        local okS, errS = pcall(RivalsUIBuilders.BuildRivalsSearchUi, Window)
                        if not okS then ReportRivalsRuntimeIssue('ui_Search', errS) end
                    end

                    if type(__akira_boot_status) == 'function' then
                        __akira_boot_status('Laying out menu...')
                    end
                    if type(__akira_boot_log) == 'function' then
                        __akira_boot_log('Layout: starting resumeLayout...')
                    end
                    resumeLayout()
                    if type(__akira_boot_log) == 'function' then
                        __akira_boot_log('Runtime: menu mount ok')
                    end
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    task.spawn(function()
                        if not __akira_boot_alive() then
                            return
                        end
                        local finish = RivalsUIBuilders.OnRemainingUiBuilt
                        if type(finish) == 'function' then
                            pcall(finish, Window)
                        end
                    end)
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    local combatReady = RivalsUIBuilders.OnCombatUiBuilt
                    if type(combatReady) == 'function' then
                        pcall(combatReady)
                    end
                    local startLoops = RivalsUIBuilders.OnCombatLoopsReady
                    if type(startLoops) == 'function' then
                        pcall(startLoops)
                    end
                    if type(__akira_boot_overlay_destroy) == 'function' then
                        pcall(__akira_boot_overlay_destroy)
                    end
                    pcall(function()
                        if Window.Tabs and Window.Tabs.Aimbot then
                            Window._PendingDefaultTab = Window.Tabs.Aimbot
                            if type(Window.Tabs.Aimbot.ShowTab) == 'function' then
                                Window.Tabs.Aimbot:ShowTab()
                            end
                        elseif Window.Tabs then
                            local firstTab = next(Window.Tabs)
                            if firstTab and type(firstTab.ShowTab) == 'function' then
                                firstTab:ShowTab()
                            end
                        end
                    end)
                end)
            end

            local RivalsRuntime = {}

            function RivalsRuntime.ResetState()
                if DrawingPool then
                    for _, p in pairs(DrawingPool) do
                        for _, obj in ipairs(p) do
                            if type(obj.Remove) == 'function' then
                                pcall(function() obj:Remove() end)
                            end
                        end
                        table.clear(p)
                    end
                end
                RivalsRuntimeBridge.WorldVisuals.Destroy()
                RivalsRuntimeBridge.ViewmodelVisuals.Destroy()
                if RivalsRuntimeBridge.TargetHud and type(RivalsRuntimeBridge.TargetHud.Destroy) == 'function' then
                    RivalsRuntimeBridge.TargetHud.Destroy()
                end
                RivalsRuntimeBridge.NativeRemovals.Destroy()
                RivalsRagebotState.RespawnBinding = nil
                RivalsRuntimeBridge.Movement.Destroy()
                RivalsRuntimeBridge.DeviceSpoof.Destroy()
                RivalsRuntimeBridge.PlayerSpoofer.Destroy()
                RivalsRuntimeBridge.ExtraSpoof.Destroy()
                RivalsRuntimeBridge.AnimationPlayer.Destroy()
                RivalsRuntimeBridge.MovementRecorder.Destroy()
                if RivalsRuntimeBridge.DestroyAkiraRagebot then
                    RivalsRuntimeBridge.DestroyAkiraRagebot()
                end
                RivalsRuntimeBridge.CombatFeedback.Destroy()
                RivalsRuntimeBridge.ResetRivalsCosmetics()
                RivalsModsState.RestoreHooks()
                AimbotBridge.ResetAimbotRuntimeState()
                AimbotBridge.ResetTriggerbotReactionState()
                AimbotBridge.ResetCameraAimRandomState()
                RivalsRuntimeBridge.ResetFlickbot()
                RivalsRagebotState.Target = nil
                RivalsRagebotState.HoldCFrame = nil
                RivalsRagebotState.LastHoldUpdateAt = 0
                RivalsRagebotState.LastRespawnRequestAt = 0
                RivalsRagebotState.PhaseClockSec = 0
                if RivalsRuntimeBridge.ResetCounterMethodsState then
                    RivalsRuntimeBridge.ResetCounterMethodsState()
                end
                RivalsRuntimeBridge.ResetAutoLoadoutState()
                RivalsRuntimeBridge.ResetAutoBanState()
                RivalsRuntimeBridge.ResetTripmineAutomation()
                LocalPickupObserver.ResetDropTracking()
                AimbotTriggerbotLastShotAt = 0
                MeleeFastFire.LastShotAt = 0
                RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                AimbotInputState.LeftMouse = false
                AimbotInputState.RightMouse = false
                AimbotInputState.TouchCount = 0
                if AimbotFovDrawings and type(AimbotFovDrawings.Destroy) == 'function' then
                    AimbotFovDrawings:Destroy()
                elseif AimbotFovCircle then
                    AimbotFovCircle.Visible = false
                    if AimbotFovCircle then pcall(AimbotFovCircle.Remove, AimbotFovCircle) end
                end
                if SilentFovDrawings and type(SilentFovDrawings.Destroy) == 'function' then
                    SilentFovDrawings:Destroy()
                end
                DestroyAllESP()
                WorldESPState.DestroyAllThrowable()
                WorldESPState.DestroyAllHazard()
                WorldESPState.DestroyAllSoundVisualizer()
                DestroyRuntimeIssueNotification()
            end

            function RivalsRuntime.RegisterPlayerLifecycle()
                RivalsRuntimeBridge.NextESPReconcileAt = 0
                Library:GiveSignal(Players.PlayerRemoving:Connect(GuardRivalsCallback('Player_Removing', function(player)
                    DestroyESP(player)
                end)))

                task.defer(function()
                    if EspRenderSettings.Enabled then
                        pcall(ReconcileESPPlayers)
                    end
                    pcall(EnsureWeaponInfoTracking)
                end)
            end

            function RivalsRuntime.RegisterWorldLifecycle()
                __akira_boot_log('Runtime: world lifecycle...')
                Connections:register('Throwable_Added', Workspace.ChildAdded:Connect(function(child)
                    WorldESPState.RegisterThrowable(child)
                end))
                Connections:register('Throwable_Removed', Workspace.ChildRemoved:Connect(function(child)
                    WorldESPState.DestroyThrowable(child)
                end))
                Connections:register('PickupDrop_Added', Workspace.ChildAdded:Connect(function(child)
                    LocalPickupObserver.ObserveDrop(child)
                end))
                Connections:register('PickupDrop_Removed', Workspace.ChildRemoved:Connect(function(child)
                    LocalPickupObserver.UnobserveDrop(child)
                end))
                Connections:register('Hazard_Added', Workspace.ChildAdded:Connect(function(instance)
                    if instance.Name ~= 'MolotovHitbox' then
                        return
                    end
                    WorldESPState.RegisterHazard(instance)
                end))
                Connections:register('Hazard_Removed', Workspace.ChildRemoved:Connect(function(instance)
                    if instance.Name ~= 'MolotovHitbox' then
                        return
                    end
                    WorldESPState.DestroyHazard(instance)
                end))

                task.spawn(GuardRivalsCallback('WorldLifecycle_Scan', function()
                    local children = Workspace:GetChildren()
                    for index, child in ipairs(children) do
                        WorldESPState.RegisterThrowable(child)
                        LocalPickupObserver.ObserveDrop(child)
                        if index % 40 == 0 then
                            task.wait()
                        end
                    end
                    -- Hazards are picked up by DescendantAdded; skip a full Workspace:GetDescendants() scan on load.
                end))
                WorldESPState.SetSoundVisualizerEnabled(Toggles.P1S3T1 and Toggles.P1S3T1.Value == true)
                task.defer(function()
                    pcall(RivalsRuntimeBridge.BindTripmineAutomation)
                end)
            end

            function RivalsRuntime.RegisterInputLifecycle()
                LPH_ATTRIBUTES(VM(NONE))
                Connections:register('Aimbot_InputBegan', UserInputService.InputBegan:Connect(GuardRivalsCallback('Aimbot_InputBegan', function(input, gameProcessed)
                    LPH_ATTRIBUTES(VM(NONE))
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        AimbotInputState.LeftMouse = true
                        return
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                        AimbotInputState.RightMouse = true
                        return
                    end

                    if gameProcessed then
                        return
                    end
                end)))

                Connections:register('Aimbot_InputEnded', UserInputService.InputEnded:Connect(GuardRivalsCallback('Aimbot_InputEnded', function(input)
                    LPH_ATTRIBUTES(VM(NONE))
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        AimbotInputState.LeftMouse = false
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                        AimbotInputState.RightMouse = false
                    end
                end)))

                Connections:register('Aimbot_TouchStarted', UserInputService.TouchStarted:Connect(GuardRivalsCallback('Aimbot_TouchStarted', function(touch, gameProcessed)
                    LPH_ATTRIBUTES(VM(NONE))
                    if gameProcessed then
                        return
                    end

                    AimbotInputState.TouchCount = AimbotInputState.TouchCount + 1
                end)))

                Connections:register('Aimbot_TouchEnded', UserInputService.TouchEnded:Connect(GuardRivalsCallback('Aimbot_TouchEnded', function()
                    LPH_ATTRIBUTES(VM(NONE))
                    AimbotInputState.TouchCount = math.max(AimbotInputState.TouchCount - 1, 0)
                end)))
            end

            function RivalsRuntime.WaitForInitialLoadInSettle()
                RivalsRuntimeBridge.WaitForLocalReady(0.4)
                pcall(InitCharacter)

                if RivalsRuntimeBridge.IsAutoQueueLobby and RivalsRuntimeBridge.IsAutoQueueLobby() then
                    if type(RivalsRuntimeBridge.RefreshAutoQueueDropdownValues) == 'function' then
                        pcall(RivalsRuntimeBridge.RefreshAutoQueueDropdownValues)
                    end
                    if Toggles and Toggles.P8S6T1 and Toggles.P8S6T1.Value == true
                        and type(RivalsRuntimeBridge.FireAutoQueueJoin) == 'function' then
                        local belief = type(RivalsRuntimeBridge.GetAutoQueueBelief) == 'function'
                            and RivalsRuntimeBridge.GetAutoQueueBelief() or 'idle'
                        if belief == 'idle' then
                            pcall(RivalsRuntimeBridge.FireAutoQueueJoin)
                        end
                    end
                end
            end

            function RivalsRuntime.StartLoops()
                LPH_ATTRIBUTES(VM(NONE))
                __akira_boot_log('Runtime: starting loops...')
                local GuiService = game:GetService('GuiService')
                local os_clock = os.clock
                local RunWorkAccum = 0
                local function RunHot(fn, label)
                    LPH_ATTRIBUTES(VM(NONE))
                    label = label or 'unlabeled'
                    return function(...)
                        LPH_ATTRIBUTES(VM(NONE))
                        if shutting_down then
                            return
                        end
                        local t0 = os_clock()
                        pcall(fn, ...)
                        local cost = os_clock() - t0
                        RunWorkAccum = RunWorkAccum + cost
                        if cost > 0.003 then
                            RunPerfTrack(label, cost)
                        end
                    end
                end
                local function RunThrottled(fn, label, interval)
                    LPH_ATTRIBUTES(VM(NONE))
                    local lastRun = 0
                    local targetInterval = interval or 0.05
                    return function(...)
                        LPH_ATTRIBUTES(VM(NONE))
                        if shutting_down then
                            return
                        end
                        local now = os_clock()
                        if now - lastRun < targetInterval then
                            return
                        end
                        lastRun = now
                        local t0 = os_clock()
                        pcall(fn, ...)
                        local cost = os_clock() - t0
                        RunWorkAccum = RunWorkAccum + cost
                        if cost > 0.003 then
                            RunPerfTrack(label, cost)
                        end
                    end
                end
                local RunPerfReports = {}
                local RunPerfLastFlush = os_clock()
                local function RunPerfFlushIfDue()
                    local now = os_clock()
                    if now - RunPerfLastFlush < 3 then
                        return
                    end
                    RunPerfLastFlush = now
                    for perfLabel, info in pairs(RunPerfReports) do
                        if info.max > 0.005 then
                            __akira_boot_log(('FRAMEPROF: %s max=%.0fms avg=%.1fms calls=%d'):format(perfLabel, info.max * 1000, (info.total / info.n) * 1000, info.n))
                        end
                    end
                    RunPerfReports = {}
                end
                local function RunPerfTrack(label, cost)
                    local info = RunPerfReports[label]
                    if not info then
                        info = { max = 0, total = 0, n = 0 }
                        RunPerfReports[label] = info
                    end
                    if cost > info.max then info.max = cost end
                    info.total = info.total + cost
                    info.n = info.n + 1
                    if info.n >= 300 then
                        info.max = 0
                        info.total = 0
                        info.n = 0
                    end
                    RunPerfFlushIfDue()
                end
                local FrameWatchAccum = 0
                local FrameWatchN = 0
                local FrameWatchMax = 0
                local FrameWatchLast = os_clock()
                local FrameWatchGcLast = collectgarbage('count')
                Connections:register('FrameWatch', RunService.Heartbeat:Connect(function(dt)
                    LPH_ATTRIBUTES(VM(NONE))
                    pcall(function()
                    if shutting_down then
                        return
                    end
                    local now = os_clock()
                    if dt > FrameWatchMax then FrameWatchMax = dt end
                    FrameWatchAccum = FrameWatchAccum + dt
                    FrameWatchN = FrameWatchN + 1
                    if now - FrameWatchLast >= 3 then
                        local gcNow = (type(collectgarbage) == 'function' and collectgarbage('count')) or 0
                        local gcDelta = gcNow - FrameWatchGcLast
                        FrameWatchGcLast = gcNow
                        local regCount = (type(Library) == 'table' and type(Library.Registry) == 'table' and #Library.Registry) or -1
                        local hudRegCount = (type(Library) == 'table' and type(Library.HudRegistry) == 'table' and #Library.HudRegistry) or -1
                        local sigCount = (type(Library) == 'table' and type(Library.Signals) == 'table' and #Library.Signals) or -1
                        if FrameWatchN > 0 and type(__akira_boot_log) == 'function' then
                            __akira_boot_log(('FRAMEWATCH: avg=%.0fms max=%.0fms n=%d work=%.0fms gc=%+.0fMB reg=%d hud=%d sig=%d'):format((FrameWatchAccum / FrameWatchN) * 1000, FrameWatchMax * 1000, FrameWatchN, RunWorkAccum * 1000, gcDelta / 1024, regCount, hudRegCount, sigCount))
                        end
                        FrameWatchAccum = 0
                        FrameWatchN = 0
                        FrameWatchMax = 0
                        RunWorkAccum = 0
                        FrameWatchLast = now
                    end
                    end)
                end))
                Connections:register('ESP_Render', RunService.RenderStepped:Connect(RunHot(RivalsRuntimeBridge.UpdateESP, 'ESP')))
                Connections:register('Throwable_Render', RunService.RenderStepped:Connect(RunThrottled(WorldESPState.UpdateThrowable, 'ThrowableESP', 0.2)))
                Connections:register('Hazard_Render', RunService.RenderStepped:Connect(RunThrottled(WorldESPState.UpdateHazard, 'HazardESP', 0.2)))
                Connections:register('CombatFeedback_Render', RunService.RenderStepped:Connect(RunThrottled(RivalsRuntimeBridge.CombatFeedback.Update, 'CombatFeedback', 0.033)))
                pcall(RunService.UnbindFromRenderStep, RunService, 'AkiraViewmodelVisuals')
                RunService:BindToRenderStep(
                    'AkiraViewmodelVisuals',
                    Enum.RenderPriority.Last.Value,
                    RunHot(RivalsRuntimeBridge.ViewmodelVisuals.Update, 'Viewmodel')
                )
                Connections:register('ViewmodelVisuals_Render', {
                    Disconnect = function()
                        pcall(RunService.UnbindFromRenderStep, RunService, 'AkiraViewmodelVisuals')
                    end,
                })
                Connections:register('Movement_PreSimulation', RunService.PreSimulation:Connect(RunHot(RivalsRuntimeBridge.Movement.Update, 'Movement')))
                Connections:register('MovementRecorder_PreSimulation', RunService.PreSimulation:Connect(RunHot(RivalsRuntimeBridge.MovementRecorder.Update, 'MovementRecorder')))
                Connections:register('Movement_BlankFlight', RunService.RenderStepped:Connect(RunHot(RivalsRuntimeBridge.Movement.BlankFlightVelocity, 'BlankFlight')))
                Connections:register('AnimationPlayer_Render', RunService.RenderStepped:Connect(RunHot(RivalsRuntimeBridge.AnimationPlayer.Update, 'Animations')))
                pcall(RunService.UnbindFromRenderStep, RunService, 'AkiraCameraModifiers')
                RunService:BindToRenderStep(
                    'AkiraCameraModifiers',
                    Enum.RenderPriority.Last.Value - 5,
                    RunHot(RivalsModsState.UpdateCameraModifiers, 'CameraModifiers')
                )
                Connections:register('CameraModifiers_Render', {
                    Disconnect = function()
                        pcall(RunService.UnbindFromRenderStep, RunService, 'AkiraCameraModifiers')
                    end,
                })
                Connections:register('MovementRecorder_Render', RunService.RenderStepped:Connect(RunHot(RivalsRuntimeBridge.MovementRecorder.UpdateRender, 'MovementRecorderRender')))
                Connections:register('Flickbot_Render', RunService.RenderStepped:Connect(RunHot(RivalsRuntimeBridge.UpdateFlickbot, 'Flickbot')))
                Connections:register('CameraAim_Render', RunService.RenderStepped:Connect(RunHot(RivalsRuntimeBridge.UpdateCameraAim, 'CameraAim')))
                Connections:register('Aimbot_Render', RunService.Heartbeat:Connect(RunHot(RivalsRuntimeBridge.UpdateAimbot, 'Aimbot')))
                Connections:register('Ragebot_Heartbeat', RunService.Heartbeat:Connect(RunHot(RivalsRuntimeBridge.UpdateRagebot, 'Ragebot')))
                Connections:register('TripmineAutomation_Heartbeat', RunService.Heartbeat:Connect(RunHot(RivalsRuntimeBridge.UpdateTripmineAutomation, 'Tripmine')))

                -- Aimbot target readout: throttled label update showing who we're locked on.
                Connections:register('AimbotTarget_Display', RunService.Heartbeat:Connect(RunHot(function()
                    LPH_ATTRIBUTES(VM(NONE))
                    local label = RivalsRuntimeBridge.AimbotTargetLabel
                    if not label then
                        return
                    end
                    local now = os.clock()
                    if now - (RivalsRuntimeBridge._AimbotTargetLabelAt or 0) < 0.15 then
                        return
                    end
                    RivalsRuntimeBridge._AimbotTargetLabelAt = now
                    local target = RivalsRuntimeBridge.CurrentCameraAimTarget
                    local name = target and (target.displayName or (target.player and target.player.Name) or (target.instance and target.instance.Name)) or nil
                    local text = name and ('Target: ' .. tostring(name)) or 'Target: none'
                    if RivalsRuntimeBridge._AimbotTargetLabelText ~= text then
                        RivalsRuntimeBridge._AimbotTargetLabelText = text
                        pcall(label.SetText, label, text)
                    end
                end, 'TargetDisplay')))

                Connections:register('RagebotTarget_Display', RunService.Heartbeat:Connect(RunHot(function()
                    LPH_ATTRIBUTES(VM(NONE))
                    local label = RivalsRuntimeBridge.RagebotTargetLabel
                    if not label then
                        return
                    end
                    local now = os.clock()
                    if now - (RivalsRuntimeBridge._RagebotTargetLabelAt or 0) < 0.15 then
                        return
                    end
                    RivalsRuntimeBridge._RagebotTargetLabelAt = now
                    local name = nil
                    local getter = RivalsRuntimeBridge.GetAkiraRagebotTargetName
                    if type(getter) == 'function' then
                        local ok, res = pcall(getter)
                        if ok then
                            name = res
                        end
                    end
                    local text = name and ('Target: ' .. tostring(name)) or 'Target: none'
                    if RivalsRuntimeBridge._RagebotTargetLabelText ~= text then
                        RivalsRuntimeBridge._RagebotTargetLabelText = text
                        pcall(label.SetText, label, text)
                    end
                end, 'RagebotTargetDisplay')))

                local AutoQueueRemotes = ReplicatedStorage:FindFirstChild('Remotes')
                local AutoQueueMatchmaking = AutoQueueRemotes and AutoQueueRemotes:FindFirstChild('Matchmaking')
                local AutoQueueStatus = AutoQueueMatchmaking and AutoQueueMatchmaking:FindFirstChild('UpdateQueueStatus')
                if AutoQueueStatus and AutoQueueStatus:IsA('RemoteEvent') then
                    Connections:register('AutoQueue_StatusUpdate',
                        AutoQueueStatus.OnClientEvent:Connect(GuardRivalsCallback(
                            'AutoQueue_StatusUpdate', RivalsRuntimeBridge.HandleAutoQueueStatusUpdate)))
                end
                Connections:register('AutoQueue_MatchmadeGameOver',
                    workspace:GetAttributeChangedSignal('MatchmadeGameOver'):Connect(GuardRivalsCallback(
                        'AutoQueue_MatchmadeGameOver', RivalsRuntimeBridge.OnAutoQueueMatchmadeGameOverChanged)))
                Connections:register('AutoQueue_LobbyReturn_Teleport',
                    game:GetService('TeleportService').LocalPlayerArrivedFromTeleport:Connect(GuardRivalsCallback(
                        'AutoQueue_LobbyReturn_Teleport', RivalsRuntimeBridge.OnAutoQueueLobbyReturn)))
                RivalsRuntimeBridge.CombatFeedback.RefreshBinding()
                RivalsRuntimeBridge.MovementRecorder.BindRoundSignal()
            end

            function RivalsRuntime.RegisterCharacterLifecycle()
                RefreshLocalPickupHealthObserver()
                AttachWeaponInfoObservers(LP)
                RivalsRuntimeBridge.RegisterAutoRespawnSignals()
                RivalsRuntimeBridge.RegisterAutoBanSignals()
                RivalsRuntimeBridge.RegisterAutoQueuePlayAgainSignals()

                RivalsRuntimeBridge.RunPickupSpawnSetup = function()
                    task.defer(function()
                        if not RivalsRuntimeBridge.WaitForLocalReady(2) then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'WaitForLocalReady timed out; per-spawn setup aborted')
                            return
                        end

                        local fighter = ResolveLocalFighter()
                        if not fighter then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'Local fighter unavailable after readiness; per-spawn setup aborted')
                            return
                        end

                        FighterDataCache.AttachLocalDuelWatchers(fighter)
                        RivalsRuntimeBridge.RegisterAutoRespawnSignals()
                        RivalsRuntimeBridge.RegisterAutoBanSignals()
                        RivalsRuntimeBridge.RegisterAutoQueuePlayAgainSignals()
                        if not InitCharacter() then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'InitCharacter failed after fighter ready; per-spawn setup aborted')
                            return
                        end

                        if not Humanoid or Humanoid.Health <= 0 then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'Humanoid missing or dead at per-spawn; setup aborted')
                            return
                        end

                        RefreshLocalPickupHealthObserver()
                        AttachWeaponInfoObservers(LP)
                        pcall(RivalsModsState.EnsureHooks)
                        pcall(UpdateRivalsPickupFeatures)
                        pcall(RivalsRuntimeBridge.ApplyRivalsCosmetics)
                        if Toggles.SkinChanger_VM_AutoReapply and Toggles.SkinChanger_VM_AutoReapply.Value == true then
                            pcall(RivalsCosmetics.ReapplyAllViewModelSkins)
                        end
                    end)
                end

                if LP.Character then
                    task.spawn(function()
                        local waited = 0
                        while RivalsRuntimeBridge.RuntimeRefreshSuspended and not shutting_down and waited < 3 do
                            task.wait(0.1)
                            waited = waited + 0.1
                        end
                        if not shutting_down then
                            RivalsRuntimeBridge.RunPickupSpawnSetup()
                        end
                    end)
                end

                Library:GiveSignal(LP.CharacterAdded:Connect(GuardRivalsCallback('Pickup_CharacterAdded', function(newChar)
                    RivalsRuntimeBridge.LogDiagnosticEvent(
                        'CharAdded',
                        'LP.CharacterAdded fired (new: ' .. tostring(newChar and newChar.Name or '<nil>') .. ')'
                    )
                    RivalsRuntimeBridge.ResetLocalShieldLatch()
                    RivalsRuntimeBridge.RunPickupSpawnSetup()
                end)))
            end

            function RivalsRuntime.StartCombatRuntime()
                if RivalsRuntime.CombatStarted then
                    return
                end
                RivalsRuntime.CombatStarted = true

                if not Connections then
                    Connections = ConnectionRegistry.new()
                    __akira_genv.__AkiraRivalsConnections = Connections
                end

                RivalsRuntime.RegisterPlayerLifecycle()
                RivalsRuntime.RegisterWorldLifecycle()
                RivalsRuntime.RegisterInputLifecycle()
                RivalsRuntime.RegisterCharacterLifecycle()
            end

            function RivalsRuntime.StartCombatLoops()
                if RivalsRuntime.CombatLoopsStarted then
                    return
                end
                if not __akira_boot_alive() then
                    return
                end
                RivalsRuntime.CombatLoopsStarted = true
                RivalsRuntime.StartCombatRuntime()
                RivalsRuntimeBridge.RuntimeRefreshSuspended = false
                task.spawn(function()
                    if not __akira_boot_alive() then
                        return
                    end
                    RivalsRuntime.StartLoops()
                    pcall(RivalsRuntimeBridge.EnsureMatchBoundaryDetection)
                end)
                task.spawn(function()
                    if not __akira_boot_alive() then
                        return
                    end
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    __akira_boot_log('Runtime: mods hooks...')
                    pcall(RivalsModsState.EnsureHooks)
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    pcall(RivalsRuntime.WaitForInitialLoadInSettle)
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    __akira_boot_log('Runtime: skin changer delegated to Skin changer.lua')
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    pcall(RivalsRuntimeBridge.QueueAutoLoadoutSubmission)
                    __akira_boot_log('Runtime: ready')
                    -- Heartbeat markers: if the game hard-crashes after boot, the last
                    -- heartbeat in akira_boot_log.txt brackets exactly when it died.
                    for _, delay in ipairs({ 0.25, 0.5, 1, 2, 3, 5, 8, 13, 21 }) do
                        task.delay(delay, function()
                            if __akira_boot_alive() then
                                __akira_boot_log('Heartbeat: alive (+' .. tostring(delay) .. 's after ready)')
                            end
                        end)
                    end
                end)
            end

