                        { idx = 'P1S27T7', type = 'Toggle', value = true },
                        { idx = 'P1S31T1', type = 'Toggle', value = false },
                        { idx = 'P1S31T3', type = 'Toggle', value = false },
                        { idx = 'P1S31T4', type = 'Toggle', value = false },

                        -- Lighting
                        { idx = 'P1S4T2', type = 'Toggle', value = true },
                        { idx = 'P1S4C1', type = 'ColorPicker', value = '9b8bb8', transparency = 0 },
                        { idx = 'P1S4C2', type = 'ColorPicker', value = '7a6a98', transparency = 0 },
                        { idx = 'P1S4T3', type = 'Toggle', value = true },
                        { idx = 'P1S4S1', type = 'Slider', value = 4 },
                        { idx = 'P1S4T4', type = 'Toggle', value = true },
                        { idx = 'P1S4S2', type = 'Slider', value = 2.2 },
                        { idx = 'P1S4T5', type = 'Toggle', value = false },
                        { idx = 'P1S6T1', type = 'Toggle', value = false },
                        { idx = 'P1S7T1', type = 'Toggle', value = true },
                        { idx = 'P1S7C1', type = 'ColorPicker', value = 'f0e8ff', transparency = 0 },
                        { idx = 'P1S7S1', type = 'Slider', value = 0.12 },
                        { idx = 'P1S7S2', type = 'Slider', value = 0 },
                        { idx = 'P1S7S3', type = 'Slider', value = 0.06 },
                        { idx = 'P1S12T1', type = 'Toggle', value = true },
                        { idx = 'P1S12D1', type = 'Dropdown', value = 'FPSBoost' },
                        { idx = 'P1S13T1', type = 'Toggle', value = true },
                        { idx = 'P1S13S1', type = 'Slider', value = 0 },
                        { idx = 'P1S13S2', type = 'Slider', value = 0 },
                        { idx = 'P1S13S3', type = 'Slider', value = 0 },
                        { idx = 'P1S13S4', type = 'Slider', value = 0.15 },
                        { idx = 'P1S5T3', type = 'Toggle', value = true },
                    },
                }
                end

                local function CloneRivalsConfigProfileValue(value)
                    if type(value) ~= 'table' then
                        return value
                    end

                    local copy = {}
                    for key, child in pairs(value) do
                        copy[key] = CloneRivalsConfigProfileValue(child)
                    end
                    return copy
                end

                local function CloneRivalsConfigProfileObject(object)
                    local copy = {}
                    for key, value in pairs(object) do
                        copy[key] = CloneRivalsConfigProfileValue(value)
                    end
                    return copy
                end

                local function BuildRivalsConfigProfileDefaultObjects(config_name)
                    EnsureRivalsConfigProfiles()
                    local profile_defaults = ConfigProfileDefaults[config_name]
                    if type(profile_defaults) ~= 'table' then
                        return nil
                    end

                    local objects = {}
                    local indexes_by_id = {}
                    local function upsert(object)
                        if type(object) ~= 'table' or type(object.idx) ~= 'string' then
                            return
                        end

                        local cloned = CloneRivalsConfigProfileObject(object)
                        local existing_index = indexes_by_id[cloned.idx]
                        if existing_index then
                            objects[existing_index] = cloned
                        else
                            indexes_by_id[cloned.idx] = #objects + 1
                            objects[#objects + 1] = cloned
                        end
                    end

                    for _, object in ipairs(SharedConfigDefaultObjects) do
                        upsert(object)
                    end
                    for _, object in ipairs(profile_defaults) do
                        upsert(object)
                    end

                    return objects
                end

                local PREMADE_CONFIG_VERSION = 8

                local function PremadeConfigPaths(config_name)
                    local clean = ScriptPaths.sanitize_config_name(config_name)
                    local dir = (Library and Library.Directory) or 'akira'
                    return {
                        dir .. '/Configs/' .. clean .. '.json',
                        dir .. '/settings/' .. clean .. '.json',
                        ScriptPaths.config_path(clean),
                        'akira/Configs/' .. clean .. '.json',
                        'akira/settings/' .. clean .. '.json',
                    }
                end

                local function WriteRivalsConfigProfileDefault(config_name)
                    local objects = BuildRivalsConfigProfileDefaultObjects(config_name)
                    if not objects then
                        return false, 'unknown RIVALS config profile: ' .. tostring(config_name)
                    end

                    local okEncode, encoded = pcall(HttpService.JSONEncode, HttpService, {
                        objects = objects,
                        akiraPremadeVersion = PREMADE_CONFIG_VERSION,
                    })
                    if not okEncode or type(encoded) ~= 'string' then
                        return false, encoded
                    end
                    for _, path in ipairs(PremadeConfigPaths(config_name)) do
                        local folder = path:match('^(.*)[/\\][^/\\]+$')
                        if folder and isfolder and not isfolder(folder) and makefolder then
                            pcall(makefolder, folder)
                        end
                        pcall(writefile, path, encoded)
                    end
                    return true
                end
                RivalsConfigProfiles.WriteDefault = WriteRivalsConfigProfileDefault

                local function PremadeConfigNeedsRewrite(config_name)
                    local sawFile = false
                    for _, path in ipairs(PremadeConfigPaths(config_name)) do
                        if isfile and isfile(path) then
                            sawFile = true
                            local okRead, content = pcall(readfile, path)
                            if not okRead or type(content) ~= 'string' or content == '' then
                                return true
                            end
                            local version = tonumber(string.match(content, '"akiraPremadeVersion"%s*:%s*(%d+)'))
                            if version ~= PREMADE_CONFIG_VERSION then
                                return true
                            end
                        end
                    end
                    return not sawFile
                end

                -- Premade Legit/Rage files are written after the menu is up so load doesn't hitch.

                local function ApplyPremadeConfigProfile(config_name)
                    local clean = ScriptPaths.sanitize_config_name(config_name)
                    local objects = BuildRivalsConfigProfileDefaultObjects(clean)
                    if not objects then
                        return false
                    end
                    local applyOk = pcall(function()
                        Library:ApplyConfig({ objects = objects })
                    end)
                    if not applyOk then
                        return false
                    end
                    if clean == 'Rage' then
                        pcall(function()
                            if Toggles.P8S4T1 then
                                Toggles.P8S4T1:SetValue(true)
                            end
                        end)
                        pcall(function()
                            local kp = Options.P8S4T1K
                            if kp then
                                kp.Mode = 'Always'
                                if type(kp.SetValue) == 'function' then
                                    kp:SetValue({ Mode = 'Always', Key = 'NONE', Active = true })
                                end
                            end
                        end)
                    elseif clean == 'Legit' then
                        pcall(function()
                            if Toggles.P8S4T1 then
                                Toggles.P8S4T1:SetValue(false)
                            end
                        end)
                    end
                    return true
                end
                RivalsConfigProfiles.Apply = ApplyPremadeConfigProfile

                SaveManager:SetIgnoreIndexes({ 'P1S32D1', 'P1S26D6', 'P1S14D1' })

                ReconcileLoadedState = function()
                    RivalsRuntime.ReconcileGen = (RivalsRuntime.ReconcileGen or 0) + 1
                    local token = RivalsRuntime.ReconcileGen
                    task.spawn(function()
                        if not __akira_boot_alive() then
                            return
                        end
                        local waitedLayout = 0
                        while Library and (Library.ConfigLoading or (Library.IsLayoutSuspended and Library:IsLayoutSuspended())) and __akira_boot_alive() and waitedLayout < 2.5 do
                            task.wait(0.05)
                            waitedLayout = waitedLayout + 0.05
                        end
                        task.wait(0.05)
                        if token ~= RivalsRuntime.ReconcileGen or not __akira_boot_alive() then
                            return
                        end
                        __akira_boot_log('Reconcile: starting...')
                        pcall(RefreshEspRenderSettings)
                        pcall(function()
                            if RivalsModsState and type(RivalsModsState.EnsureHooks) == 'function' then
__akira_boot_log('RuntimeA: EnsureHooks first call...')
                                    RivalsModsState.EnsureHooks()
                            end
                        end)
                        __akira_boot_yield()
                        pcall(function()
                            local world = RivalsRuntimeBridge.WorldVisuals
                            if world and type(world.RefreshAll) == 'function' then
                                world.RefreshAll()
                            end
                        end)
                        __akira_boot_yield()
                        pcall(RivalsRuntimeBridge.ViewmodelVisuals.RefreshAll)
                        pcall(RivalsRuntimeBridge.NativeRemovals.RefreshAll)
                        __akira_boot_yield()
                        pcall(RivalsRuntimeBridge.Movement.RefreshAll)
                        pcall(RivalsRuntimeBridge.DeviceSpoof.RefreshAll)
                        __akira_boot_yield()
                        pcall(RivalsRuntimeBridge.PlayerSpoofer.RefreshAll)
                        pcall(RivalsRuntimeBridge.ExtraSpoof.RefreshAll)
                        __akira_boot_yield()
                        pcall(RivalsRuntimeBridge.AnimationPlayer.RefreshAll)
                        pcall(RivalsRuntimeBridge.ApplyRivalsCosmetics)
                        __akira_boot_log('Reconcile: complete')
                        __akira_boot_log(string.format('LOAD OK: total %.2fs', os.clock() - __akira_boot_clock_start))
                    end)
                end

                Library:OnUnload(GuardRivalsCallback('Runtime_Unload', function()
                    RivalsRuntime.ResetState()
                    if Connections then
                        Connections:disconnect_all()
                    end
                end))

                task.spawn(GuardRivalsCallback('Runtime_FinishSetup', function()
                    if not __akira_boot_alive() then
                        return
                    end
                    RivalsRuntimeBridge.BootConfigReady = true
                    if type(__akira_boot_status) == 'function' then
                        __akira_boot_status('Building Settings...')
                    end
                    if not __akira_boot_alive() then
                        return
                    end
                    pcall(function()
                        if type(Library.SuspendLayout) == 'function' then
                            Library:SuspendLayout()
                        end
                    end)
                    pcall(function()
                        if type(ScriptPaths.remove_premade_configs) == 'function' then
                            ScriptPaths.remove_premade_configs()
                        end
                    end)
                local SharedUI
                local sharedOk, sharedErr = pcall(function()
                    SharedUI = GameBootstrap.create_standard_shared_ui({
                    ui_settings = UISettings,
                    window = Window,
                    library = Library,
                    theme_manager = ThemeManager,
                    script_paths = ScriptPaths,
                    save_manager = SaveManager,
                    current_config_name = 'RIVALS',
                    default_config_name = nil,
                    config_names = {},
                    use_global_config_names = true,
                    toggles = Toggles,
                    options = Options,
                    local_player = LP,
                    defaults = {
                        auto_show = false,
                        show_notification = true,
                        show_keybind_states = false,
                        show_mobile_button = true,
                        auto_execute_on_teleport = false,
                        auto_load_config = false,
                        auto_save_config = false,
                        load_config_name = '',
                        menu_keybind = 'RightShift',
                    },
                    persist_menu_keybind = false,
                    queue_on_teleport = queue_on_teleport,
                    before_save = function(shared_ui, config_name)
                        local saveName = config_name or (shared_ui and shared_ui:resolve_save_config_name()) or ''
                        if saveName == '' then
                            return
                        end
                        if type(RivalsRuntimeBridge.SetRivalsCosmeticsConfigName) == 'function' then
                            pcall(RivalsRuntimeBridge.SetRivalsCosmeticsConfigName, saveName)
                        end
                        if type(RivalsRuntimeBridge.SetAutoLoadoutConfigName) == 'function' then
                            pcall(RivalsRuntimeBridge.SetAutoLoadoutConfigName, saveName)
                        end
                        if type(RivalsRuntimeBridge.CaptureSavedRivalsCosmeticsSelections) == 'function' then
                            pcall(RivalsRuntimeBridge.CaptureSavedRivalsCosmeticsSelections)
                        end
                    end,
                    on_save = function(shared_ui, config_name)
                        local saveName = config_name or (shared_ui and shared_ui:resolve_save_config_name()) or ''
                        if saveName == '' then
                            return
                        end
                        if type(RivalsRuntimeBridge.SetRivalsCosmeticsConfigName) == 'function' then
                            pcall(RivalsRuntimeBridge.SetRivalsCosmeticsConfigName, saveName)
                        end
                        if type(RivalsRuntimeBridge.SetAutoLoadoutConfigName) == 'function' then
                            pcall(RivalsRuntimeBridge.SetAutoLoadoutConfigName, saveName)
                        end
                        if type(RivalsRuntimeBridge.SaveRivalsCosmeticsSelections) == 'function' then
                            pcall(RivalsRuntimeBridge.SaveRivalsCosmeticsSelections)
                        end
                        if type(RivalsRuntimeBridge.SaveAutoLoadoutProfiles) == 'function' then
                            pcall(RivalsRuntimeBridge.SaveAutoLoadoutProfiles)
                        end
                    end,
                    on_load_saved = function(shared_ui, config_name)
                        local loadName = config_name or (shared_ui and shared_ui:resolve_load_config_name()) or ''
                        if loadName == '' then
                            return
                        end
                        if type(RivalsRuntimeBridge.SetRivalsCosmeticsConfigName) == 'function' then
                            pcall(RivalsRuntimeBridge.SetRivalsCosmeticsConfigName, loadName)
                        end
                        if type(RivalsRuntimeBridge.SetAutoLoadoutConfigName) == 'function' then
                            pcall(RivalsRuntimeBridge.SetAutoLoadoutConfigName, loadName)
                        end
                        task.defer(GuardRivalsCallback('Cosmetics_LoadSavedSelections', function()
                            if type(RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections) == 'function' then
                                pcall(RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections)
                            end
                            if type(RivalsRuntimeBridge.RefreshRivalsCosmetics) == 'function' then
                                pcall(RivalsRuntimeBridge.RefreshRivalsCosmetics)
                            end
                        end))
                        task.defer(GuardRivalsCallback('AutoLoadout_LoadSavedProfiles', function()
                            if type(RivalsRuntimeBridge.LoadAutoLoadoutProfiles) == 'function' then
                                pcall(RivalsRuntimeBridge.LoadAutoLoadoutProfiles)
                            end
                        end))
                    end,
                    on_load_default = function(shared_ui, config_name)
                        local loadName = config_name or (shared_ui and shared_ui:resolve_save_config_name()) or ''
                        RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(loadName)
                        RivalsRuntimeBridge.SetAutoLoadoutConfigName(loadName)
                    end,
                    reset_config_to_default = function()
                        return true
                    end,
                    reconcile_loaded_state = function()
                        if ReconcileLoadedState then
                            ReconcileLoadedState()
                        end
                    end,
                })
                end)
                if not sharedOk then
                    ReportRivalsRuntimeIssue('shared_ui', sharedErr)
                end
                task.wait()
                local initialRivalsConfigName = (SharedUI and SharedUI.should_auto_load_config and SharedUI:should_auto_load_config() and SharedUI.resolve_load_config_name and SharedUI:resolve_load_config_name()) or ''
                if initialRivalsConfigName ~= '' then
                    RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(initialRivalsConfigName)
                    RivalsRuntimeBridge.SetAutoLoadoutConfigName(initialRivalsConfigName)
                end

                task.wait()
                pcall(function()
                    GameBootstrap.prepare_setup({
                    save_manager = SaveManager,
                    script_paths = ScriptPaths,
                    current_config_name = 'RIVALS',
                    default_config_name = nil,
                    shared_ui = SharedUI,
                    toggles = Toggles,
                    options = Options,
                    defer_load = true,
                    reconcile_loaded_state = ReconcileLoadedState,
                    on_load_saved = function(shared_ui, config_name)
                        local target_name = config_name or (shared_ui and shared_ui.resolve_load_config_name and shared_ui:resolve_load_config_name()) or ''
                        if target_name == '' then
                            return false, 'no config selected'
                        end
                        local loadOk, loadErr = SaveManager:Load(target_name)
                        if loadOk then
                            ReconcileLoadedState()
                            return true
                        end
                        return false, loadErr
                    end,
                    })
                end)
                task.wait()
                if type(__akira_boot_status) == 'function' then
                    __akira_boot_status('Finishing menu...')
                end
                task.defer(function()
                    if not __akira_boot_alive() then
                        return
                    end
                    __akira_boot_log('Config: applying...')
                    pcall(function()
                        GameBootstrap.load_config({
                            save_manager = SaveManager,
                            script_paths = ScriptPaths,
                            current_config_name = 'RIVALS',
                            default_config_name = nil,
                            shared_ui = SharedUI,
                            reconcile_loaded_state = ReconcileLoadedState,
                            on_load_saved = function(shared_ui, config_name)
                                local loadName = config_name or (shared_ui and shared_ui:resolve_load_config_name()) or 'Legit'
                                RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(loadName)
                                RivalsRuntimeBridge.SetAutoLoadoutConfigName(loadName)
                                task.defer(GuardRivalsCallback('Cosmetics_LoadSavedSelections', function()
                                    task.wait(0.1)
                                    RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections()
                                    pcall(RivalsRuntimeBridge.ApplyRivalsCosmetics)
                                end))
                                task.defer(GuardRivalsCallback('AutoLoadout_LoadSavedProfiles', RivalsRuntimeBridge.LoadAutoLoadoutProfiles))
                            end,
                        })
                    end)
                    __akira_boot_log('Config: applied')
                    pcall(function()
                        if Library and type(Library.ResumeLayout) == 'function' then
                            if type(Library.IsLayoutSuspended) ~= 'function' or Library:IsLayoutSuspended() then
                                Library:ResumeLayout()
                            end
                        end
                    end)
                    RivalsRuntimeBridge.BootConfigReady = true
                    pcall(function()
                        local env = (type(getgenv) == 'function' and getgenv()) or _G
                        if type(env) == 'table' and env.__AkiraOpenMenu == true then
                            env.__AkiraOpenMenu = nil
                            local setVisible = AkiraLibFn(Library, 'Set', 'Visible')
                            local toggle = AkiraLibFn(Library, 'Togg', 'le')
                            if type(setVisible) == 'function' then
                                setVisible(Library, true)
                            elseif Library and Library.Toggled ~= true and type(toggle) == 'function' then
                                toggle(Library)
                            end
                        end
                    end)
                end)
                pcall(function()
                    local env = (type(getgenv) == 'function' and getgenv()) or _G
                    if type(env) == 'table' and env.__AkiraOpenMenu == true then
                        local setVisible = AkiraLibFn(Library, 'Set', 'Visible')
                        local toggle = AkiraLibFn(Library, 'Togg', 'le')
                        if type(setVisible) == 'function' then
                            setVisible(Library, true)
                        elseif Library and Library.Toggled ~= true and type(toggle) == 'function' then
                            toggle(Library)
                        end
                    end
                end)
                if not __akira_boot_alive() then
                    return
                end
                do
                    task.spawn(GuardRivalsCallback('Runtime_InitialRefresh', function()
                        if not __akira_boot_alive() then
                            return
                        end
                        __akira_boot_log('InitialRefresh: reconcile...')
                        if ReconcileLoadedState then
                            pcall(ReconcileLoadedState)
                        end
                        __akira_boot_log('InitialRefresh: load cosmetic selections...')
                        pcall(RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections)
                        __akira_boot_log('InitialRefresh: esp tracking...')
                        pcall(EnsureEspRenderSettingsTracking)
                        __akira_boot_log('InitialRefresh: autoloadout profiles...')
                        pcall(RivalsRuntimeBridge.LoadAutoLoadoutProfiles)
                        __akira_boot_log('InitialRefresh: done')
                    end))
                end

                RivalsUIBuilders.InitializeDone = true

                if SharedUI and type(SharedUI.notify_loaded) == 'function' then
                    pcall(function()
                        SharedUI:notify_loaded(5)
                    end)
                end

                task.defer(function()
                    task.wait(0.2)
                    local autoName = nil
                    if AutoloadSupport and type(AutoloadSupport.current) == 'function' then
                        autoName = AutoloadSupport.current()
                    end
                    if not autoName or autoName == '' then
                        local autoFiles = {
                            (Library.Directory or 'akira') .. '/settings/autoload.txt',
                            (Library.Directory or 'akira') .. '/settings/Autoload.txt',
                            (Library.Directory or 'akira') .. '/Autoload.txt',
                            'akira/settings/autoload.txt',
                            'akira/settings/Autoload.txt',
                            'akira/Autoload.txt',
                        }
                        for _, af in ipairs(autoFiles) do
                            if isfile and isfile(af) and readfile then
                                local ok, c = pcall(readfile, af)
                                if ok and type(c) == 'string' then
                                    local trimmed = c:gsub('^%s+', ''):gsub('%s+$', ''):gsub('^["\']', ''):gsub('["\']$', ''):gsub('%.[jJ][sS][oO][nN]$', '')
                                    if trimmed ~= '' then
                                        autoName = trimmed
                                        break
                                    end
                                end
                            end
                        end
                    end
                    if autoName and autoName ~= '' and not (RivalsRuntimeBridge and RivalsRuntimeBridge.AutoloadConfigApplied == autoName) then
                        __akira_boot_log('Autoload: loading config ' .. tostring(autoName))
                        local ok = SaveManager:Load(autoName)
                        __akira_boot_log('Autoload: config loaded result=' .. tostring(ok))
                        if ok then
                            if ReconcileLoadedState then
                                pcall(ReconcileLoadedState)
                            end
                            task.defer(function()
                                Library:Notify('Auto-loaded config: ' .. autoName, 3)
                            end)
                        end
                    end
                end)
                end))

                -- Mobile toggle button is handled dynamically by library CreateWindow draggable toggle and UI Settings toggle
            end

            pcall(BeginReplicatedStateBoot)
            __akira_boot_status('Building menu...')
            RivalsUIBuilders.OnCombatUiBuilt = function()
                pcall(RivalsRuntime.StartCombatRuntime)
            end
            RivalsUIBuilders.OnCombatLoopsReady = function()
                pcall(RivalsRuntime.StartCombatLoops)
            end
            RivalsUIBuilders.OnRemainingUiBuilt = function(window)
                task.spawn(function()
                    task.wait()
                    if not __akira_boot_alive() then
                        return
                    end
                    pcall(RivalsRuntime.Initialize, window)
                end)
            end
            RivalsUIBuilders.BuildRivalsUi(Window)
            end)()

        end
        RunRivals()
    else
        if type(__akira_boot_overlay_destroy) == 'function' then
            pcall(__akira_boot_overlay_destroy)
        end
        if Library and type(Library.Notify) == 'function' then
            Library:Notify({ Title = 'Akira', Description = 'This script only supports RIVALS.', Time = 5 })
        end
    end

    end, function(e)
        local msg = tostring(e)
        if debug and type(debug.traceback) == 'function' then
            local okTb, tb = pcall(debug.traceback, msg, 2)
            if okTb and type(tb) == 'string' and tb ~= '' then
                return tb
            end
        end
        return msg
    end)

    if not __game_ok then
        if type(__akira_boot_log) == 'function' then
            __akira_boot_log('FATAL ' .. tostring(__game_err))
        end
        if type(__akira_boot_overlay_destroy) == 'function' then
            pcall(__akira_boot_overlay_destroy)
        end
        if ErrorReporter and type(ErrorReporter.report) == 'function' then
            ErrorReporter.report(__game_err, nil, 'game_init')
        end
        if Library and type(Library.Notify) == 'function' then
            Library:Notify({ Title = 'Akira', Description = 'Fatal error: ' .. tostring(__game_err), Time = 8 })
        end
    end
end)()
